def check_norm_724b22bdfc2b2877_4a5830f78605(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及速度平方、动能或势能转化不等式
    trigger_keywords = ['v^2', 'v**2', 'velocity squared', 'kinetic energy', 'potential energy', 'conservation of energy']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) or re.search(r'v\^2\s*[<≤=]', combined_text)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到速度平方或能量转化不等式场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否在解不等式时仅保留了正根而忽略了负根
    # 寻找类似 v <= sqrt(...) 而非 |v| <= sqrt(...) 或 -sqrt <= v <= sqrt 的表达
    pred_lower = prediction.lower()

    # 检查是否出现了平方根开方操作
    has_sqrt = 'sqrt' in pred_lower or '√' in pred_lower or '**0.5' in pred_lower or '^{1/2}' in pred_lower
    if not has_sqrt:
        return {'result': 'inconclusive', 'message': '推理过程中未显式进行开方运算', 'evidence': ''}

    # 检查是否考虑了负值或绝对值符号
    has_symmetry = any(kw in pred_lower for kw in ['absolute value', '±', '+/-', 'negative root', 'both directions', '|v|'])

    # 检查是否存在典型的错误形式：直接写 v <= sqrt(...) 且没有方向限定词
    # 匹配类似 v <= sqrt 或 v < sqrt 的模式
    single_root_pattern = re.search(r'v\s*(?:<=|≤|<)\s*(?:sqrt|√|\([^)]+\)\^0\.5)', pred_lower)

    # 如果物理场景没有明确限定方向（如 "positive direction", "upward only"）
    direction_limited = any(kw in combined_text for kw in ['only positive', 'magnitude only', 'speed', 'scalar'])

    if single_root_pattern and not has_symmetry and not direction_limited:
        return {
            'result': 'fail',
            'message': '在处理平方根不等式时疑似忽略了负根（反向运动）的可能性，未体现对称性。',
            'evidence': str(single_root_pattern.group())
        }

    # Step 3: 符号覆盖检查 (H, g, v, z)
    required_symbols = ['H', 'g', 'v', 'z']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)
    if symbol_count >= 2 and has_symmetry:
        return {'result': 'pass', 'message': '正确处理了不等式的对称性或考虑了方向', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '无法确定是否遗漏负根，证据不足', 'evidence': ''}

