def check_norm_baffb9b5544e3e7e_fa594c53f9a2(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两个物体追踪且保持距离不变（恒定距离约束）
    trigger_keywords = ['追踪', '追及', '保持距离', '距离不变', 'constant distance', 'distance L', 'fixed distance']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到恒定距离追踪运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 预测中是否体现了速度在连线方向投影相等的约束
    # 检查关键词：速度分量、投影、cos、dot product、连线方向
    pred_lower = prediction.lower()
    logic_keywords = ['速度', '分量', '投影', 'cos', 'dot', 'projection', 'velocity component']
    if not any(kw in pred_lower for kw in logic_keywords):
        return {'result': 'fail', 'message': '未提及速度在连线方向的投影或分量关系', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 v_A * cos(theta) = v_B * cos(phi) 或向量点积形式
    # 匹配 v_A cos(theta) = v_B cos(phi) 或类似的等式结构
    pattern_trig = r'v_?[Aa].*cos.*=.*v_?[Bb].*cos'
    pattern_dot = r'v_?[Aa].*\\cdot.*r_?AB.*=.*v_?[Bb].*\\cdot.*r_?AB'

    has_trig = re.search(pattern_trig, prediction, re.IGNORECASE)
    has_dot = re.search(pattern_dot, prediction, re.IGNORECASE)

    if has_trig or has_dot:
        return {'result': 'pass', 'message': '正确应用了恒定距离约束下的速度投影相等原理', 'evidence': (has_trig or has_dot).group()}

    # 如果有相关讨论但公式不完整，返回 inconclusive
    if 'cos' in pred_lower or 'v_' in pred_lower:
        return {'result': 'inconclusive', 'message': '检测到相关物理量但未发现明确的等量约束公式', 'evidence': prediction[:200]}

    return {'result': 'fail', 'message': '预测中缺失核心约束等式 v_A·cos(θ) = v_B·cos(φ)', 'evidence': prediction[:200]}

# rule_id=norm_c0a0537e92a5210f | domain=Mechanics | topic=Kinematics in 1D/2D/3D
# rule_id=norm_c0a0537e92a5210f | domain=Mechanics | topic=Kinematics in 1D/2D/3D
def check_norm_c0a0537e92a5210f_159a435e9715(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及运动学中的二次方程求解时间场景
    # 关键词：二次方程、两个根、t1/t2、运动时间
    trigger_keywords = ['二次方程', '两个根', 't=', '时间', 'quadratic', 'roots']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到涉及二次方程求时间的运动学场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别 prediction 中是否出现了两个正根并进行了舍选
    pred = prediction.lower()
    # 匹配类似 t1=... t2=... 或两个数值的情况
    time_roots = re.findall(r't\s*=\s*(\d+\.?\d*)', pred)
    if len(time_roots) < 2:
        # 尝试匹配中文描述中的根
        time_roots = re.findall(r'(\d+\.?\d*)\s*s', pred)

    if len(time_roots) < 2:
        return {'result': 'inconclusive', 'message': '未在预测中识别出两个时间根', 'evidence': pred[:200]}

    # Step 3: 符号/数值校验 — 检查是否满足 T > Δt (总时间大于分段跨度)
    # 提取数值进行比较（保守处理，仅当明确存在比较逻辑时判断）
    try:
        roots = sorted([float(r) for r in time_roots])
        # 假设较大的根为总时间 T，较小的根或题目给定的跨度为 delta_t
        # 规则要求 T > delta_t，如果 prediction 选择了较小的根作为最终答案且不符合物理逻辑，则报错
        if '舍去' in pred or '取' in pred or 'reject' in pred:
            # 如果 prediction 显式讨论了舍选，检查其逻辑是否符合 T > delta_t
            # 这里通过正则查找是否有 T > delta_t 的不等式结构
            if re.search(r'T\s*>\s*\Delta\s*t', prediction) or re.search(r't\s*>\s*\d+', prediction):
                return {'result': 'pass', 'message': '检测到对时间根的物理舍选逻辑', 'evidence': prediction[-200:]}
    except:
        pass

    # 如果 prediction 中没有体现出对 T > Δt 的校验逻辑，且存在两个正根，则视为逻辑缺失
    if 't1' in pred and 't2' in pred and not any(op in pred for op in ['>', '<', '大于', '小于', '舍']):
        return {'result': 'fail', 'message': '未对二次方程的两个时间根进行物理合理性（T > Δt）校验', 'evidence': prediction[-200:]}

    return {'result': 'inconclusive', 'message': '证据不足以判定舍选逻辑是否正确', 'evidence': ''}

# rule_id=norm_dfd1c529d5d116d5 | domain=Mechanics | topic=Kinematics in 1D/2D/3D
# rule_id=norm_dfd1c529d5d116d5 | domain=Mechanics | topic=Kinematics in 1D/2D/3D
def check_norm_dfd1c529d5d116d5_821fa9d630a2(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及“最后一段时间”与“总路程/高度”的比例关系
    # 关键词：最后、末、比例、几分之几、总高度、总位移
    trigger_keywords = ['最后', '末', '比例', '比值', '总高度', '总位移', '总路程']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '题目未涉及分段位移比例场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了 H(T) 与 H(T-Δt) 的关系方程
    # 核心逻辑是 H_total - H_remaining = H_last_segment 或类似的比例表达
    # 匹配类似 H(T) - H(T-t) = kH 或 H(T-t) = (1-k)H 的结构
    pred = prediction.replace(' ', '')

    # 检查是否包含时间差 T-t 或 T-delta_t 的表达
    time_diff_pattern = r'T-[\Delta]?t|t-[\Delta]?t|T-1'
    has_time_diff = re.search(time_diff_pattern, pred, re.IGNORECASE)

    # 检查是否包含位移/高度的比例关系 (如 3/4, 0.75, k)
    ratio_pattern = r'\d+/\d+|0\.\d+|[kK]'
    has_ratio = re.search(ratio_pattern, pred)

    if not (has_time_diff and has_ratio):
        return {
            'result': 'fail',
            'message': '未检测到分段位移比例建模逻辑，需建立总时间T与前段位移的关系',
            'evidence': prediction[:200]
        }

    # Step 3: 符号与公式结构校验
    # 寻找类似 H - H_prev = delta_H 或 H_prev = (1-k)H 的等式特征
    # 自由落体常用 1/2gt^2，检查是否利用了位移公式的差值
    formula_pattern = r'1/2g\(T-.*\)\^2|g\(T-.*\)\*\*2|h=.*H'
    if re.search(formula_pattern, pred, re.IGNORECASE) or 'T-' in pred:
        return {
            'result': 'pass',
            'message': '已建立分段位移比例方程并尝试求解总时间',
            'evidence': re.search(r'.{0,30}(T-[\Delta]?t).{0,30}', pred).group(0) if has_time_diff else ''
        }

    return {'result': 'inconclusive', 'message': '建模过程不完整或表达不规范', 'evidence': prediction[:100]}

