# rule_id=norm_f452bf5e291ce265 | domain=Mechanics | topic=Kinematics in 1D/2D/3D
def check_norm_f452bf5e291ce265_ef090798de5f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多圈绕线（N turns）、半径 R、长度 L 或角位移 theta
    trigger_keywords = ['绕', '线', '圈', 'turn', 'winding', 'unwind', 'radius', '半径']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多圈绕线或解绕相关的运动学场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否建立了 L = R * theta 或 dl = R * dphi 的微分/线性关系
    # 重点在于检查是否将长度变化与半径和角度关联，而非简单的平均化处理
    pred = prediction.lower()
    # 匹配 L = R * theta 或 dl = R * dphi 的变体
    pattern_relation = r'(l\s*=\s*r\s*\*?\s*(theta|phi|\w+))|(dl\s*=\s*r\s*\*?\s*d(phi|theta))|(ds\s*=\s*r\s*\*?\s*d(phi|theta))'
    # 匹配 N 圈与角度的关系 theta = 2 * pi * N
    pattern_turns = r'(theta|phi)\s*=\s*2\s*\*?\s*pi\s*\*?\s*n'

    has_relation = re.search(pattern_relation, pred, re.IGNORECASE)
    has_turns_logic = re.search(pattern_turns, pred, re.IGNORECASE) or '2*pi*n' in pred.replace(' ', '')

    # Step 3: 符号覆盖检查 (R, l, phi/theta)
    required_symbols = ['r', 'l', 'phi', 'theta']
    symbol_count = sum(1 for s in required_symbols if s in pred)

    if has_relation:
        return {'result': 'pass', 'message': '建立了长度与角位移的正确关联公式', 'evidence': re.search(pattern_relation, pred, re.IGNORECASE).group()}

    if symbol_count >= 2 and ('dl' in pred or 'dphi' in pred or 'dθ' in pred):
        return {'result': 'pass', 'message': '检测到微分形式的解绕关系描述', 'evidence': '包含微分符号及相关物理量'}

    # 如果明确在算总长却没体现 R*theta 关系，且存在 N 圈描述，则判定为逻辑缺失
    if 'n' in (question + context).lower() and not has_relation:
        return {'result': 'fail', 'message': '未建立 L = R * theta 的微分或线性关系，可能存在平均化处理错误', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了解绕长度关系', 'evidence': ''}

# rule_id=norm_035db5b07df24edb | domain=Mechanics | topic=Relative Motion
# rule_id=norm_035db5b07df24edb | domain=Mechanics | topic=Relative Motion
def check_norm_035db5b07df24edb_6856074d0420(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否包含往返飞行时间数据及空间/坐标描述
    trigger_keywords = ['往返', '飞行时间', '坐标', '地图', 't_go', 't_back', 'round trip']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多点往返飞行数据场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否使用了线性拟合、斜率、截距或作图法，而非单点假设
    pred_lower = prediction.lower()
    modeling_keywords = ['拟合', '线性方程', '斜率', '截距', '作图', 'linear fit', 'slope', 'intercept']
    has_modeling = any(kw in pred_lower for kw in modeling_keywords)

    # 检查是否包含 symbolic_hint 中的关键符号
    required_symbols = ["t_0", "t_{back}", "t_{go}"]
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)

    # Step 3: 判定逻辑
    # 如果预测中直接给出了距离或速度但没有体现拟合过程（如直接用单组数据代入），则视为建模错误
    if not has_modeling and symbol_count < 2:
        # 寻找是否直接假设了距离的特征（如直接出现 d = ... 或 s = ... 而无推导过程）
        if re.search(r'[ds]\s*=\s*\d+', pred_lower) and 'fit' not in pred_lower:
            return {'result': 'fail', 'message': '未采用多点线性拟合建模，严禁单点假设距离', 'evidence': prediction[:200]}
        return {'result': 'inconclusive', 'message': '未发现明确的线性拟合建模过程', 'evidence': ''}

    # 检查公式结构特征 (1/(t_go - t_0))
    formula_pattern = r'1\s*/\s*\(\s*t(_go|\{go\})\s*-\s*t_0\s*\)'
    if re.search(formula_pattern, prediction) or has_modeling:
        return {'result': 'pass', 'message': '已采用线性拟合或构造线性方程建模', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足以判定建模方式', 'evidence': ''}

# rule_id=norm_143666d1a44b8f2e | domain=Mechanics | topic=Relative Motion
# rule_id=norm_143666d1a44b8f2e | domain=Mechanics | topic=Relative Motion
def check_norm_143666d1a44b8f2e_5ed4cdf214e3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及风中/流体中航行及地速计算
    trigger_keywords = ['风', '水流', '介质', '地速', 'ground speed', 'wind', 'current', 'course', '航向']
    if not any(k in (question + context) for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到风中/流体中航行场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否错误地使用了直接投影而非矢量三角形（余弦定理）
    # 错误逻辑通常表现为直接 v_g = v * cos(theta) 或类似的简单投影
    pred = prediction.lower()
    # 检查是否提到矢量合成或余弦定理相关的关键词
    vector_logic = any(k in pred for k in ['vector', 'triangle', 'cosine rule', '余弦定理', '矢量', '合成'])

    # 检查是否存在错误的投影公式：v_g = v * cos(...) 或 v_g = u * cos(...)
    # 这种投影通常忽略了垂直航向分量的补偿
    wrong_projection = re.search(r'v_g\s*=\s*[uv]\s*\\?cos', pred)

    # Step 3: 符号与公式校验
    # 目标公式：v^2 = u^2 + v_g^2 - 2u v_g cos(theta) 或其解格式
    # canonical: v_g = u cos(beta-alpha) +/- sqrt(v^2 - u^2 sin^2(beta-alpha))
    correct_formula = re.search(r'v_g\s*=\s*u\s*\\?cos.*\\sqrt', pred) or \
                      re.search(r'v\^2\s*=\s*u\^2\s*\+\s*v_g\^2', pred) or \
                      re.search(r'v_g\^2\s*-\s*2\s*u\s*v_g', pred)

    if wrong_projection and not vector_logic and not correct_formula:
        return {
            'result': 'fail',
            'message': '检测到可能的投影错误：地速计算应基于矢量三角形而非简单的速度投影。',
            'evidence': re.search(r'.{0,50}v_g\s*=[^\n]+', pred).group(0) if wrong_projection else prediction[:100]
        }

    if correct_formula:
        return {'result': 'pass', 'message': '使用了正确的矢量合成公式计算地速', 'evidence': '检测到符合余弦定理或其变体的公式'}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了矢量三角形逻辑', 'evidence': ''}

# rule_id=norm_15a3c4fba8e9595d | domain=Mechanics | topic=Relative Motion
# rule_id=norm_15a3c4fba8e9595d | domain=Mechanics | topic=Relative Motion
def check_norm_15a3c4fba8e9595d_fa202eff439c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及非惯性系（如电梯、加速参考系）中的自由落体或重力加速度场景
    trigger_keywords = ['电梯', '加速', '参考系', '非惯性', 'elevator', 'accelerating frame', 'reference frame']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到非惯性系或加速参考系场景', 'evidence': ''}
    if '自由落体' not in (question + context) and 'free fall' not in (question + context).lower() and 'g' not in (question + context).lower():
        return {'result': 'inconclusive', 'message': '未检测到重力加速度相关背景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证相对加速度公式 a_rel = a_obj - a_frame 或其变体
    # 匹配矢量减法形式或特定的标量叠加形式 (g+a) 或 (g-a)
    pred = prediction.lower()
    rel_accel_pattern = r'a_?rel|相对加速度|relative acceleration'
    vector_sub_pattern = r'g\s*-\s*a|a_obj\s*-\s*a_frame|a_物\s*-\s*a_系'

    # 检查是否提到了相对加速度的概念
    if not re.search(rel_accel_pattern, pred):
        return {'result': 'fail', 'message': '未明确提及相对加速度或其计算过程', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查是否满足 a_rel = g - a_frame 的逻辑
    # 如果题目描述电梯向上加速(a)，物体自由落体(g向下)，则相对加速度大小应为 g + a
    upward_frame = any(kw in (question + context) for kw in ['向上', 'upward'])
    if upward_frame and re.search(r'g\s*\+\s*a', pred):
        return {'result': 'pass', 'message': '正确识别向上加速系中的相对加速度叠加 (g+a)', 'evidence': re.search(r'g\s*\+\s*a', pred).group()}

    # 通用公式检查
    if re.search(vector_sub_pattern, pred.replace('\\vec', '')):
        return {'result': 'pass', 'message': '符合非惯性系加速度矢量合成公式', 'evidence': prediction[:200]}

    # 如果出现了错误的减法逻辑（在向上加速时使用 g-a）
    if upward_frame and re.search(r'g\s*-\s*a', pred):
        return {'result': 'fail', 'message': '在向上加速的参考系中，相对加速度大小应为 g+a 而非 g-a', 'evidence': 'g-a'}

    return {'result': 'inconclusive', 'message': '无法确定相对加速度计算的准确性', 'evidence': ''}

# rule_id=norm_25ea6d8f00ca6511 | domain=Mechanics | topic=Relative Motion
# rule_id=norm_25ea6d8f00ca6511 | domain=Mechanics | topic=Relative Motion
def check_norm_25ea6d8f00ca6511_c0f62117e2ca(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多个物体在同一介质（如河流、风、水流）中运动并涉及相对距离/相遇
    trigger_keywords = ['河', '流', '风', '介质', 'river', 'stream', 'wind', 'medium']
    rel_keywords = ['相遇', '追及', '相对距离', '相对速度', 'meet', 'relative distance', 'relative velocity']

    text_to_check = (question + context).lower()
    is_triggered = any(kw in text_to_check for kw in trigger_keywords) and any(kw in text_to_check for kw in rel_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到涉及介质流速的相对运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否正确处理了介质流速的抵消性
    # 核心逻辑：相对速度 v_rel = (u1 + v_river) - (u2 + v_river) = u1 - u2
    pred = prediction.lower()

    # 检查是否错误地保留了流速项（例如在计算相对速度时出现了 2*v_river 或 v_river 无法抵消的情况）
    # 或者是检查是否明确提到了流速抵消、与流速无关等关键词
    offset_keywords = ['抵消', '无关', 'cancel', 'independent of', 'offset']
    has_offset_logic = any(kw in pred for kw in offset_keywords)

    # Step 3: 符号/公式校验
    # 检查是否包含 u1, u2, v_rel 等符号，并验证其减法关系
    # 匹配类似 (u1 + v) - (u2 + v) 或 u1 - u2 的结构
    formula_pattern = r'u_?1\s*-\s*u_?2|v_?1\s*-\s*v_?2|\\vec{u}_1\s*-\s*\\vec{u}_2'
    has_correct_formula = re.search(formula_pattern, prediction) is not None

    if has_offset_logic or has_correct_formula:
        return {'result': 'pass', 'message': '正确应用了介质流速在相对运动中的抵消性逻辑', 'evidence': '检测到流速抵消逻辑或正确的相对速度公式'}

    # 如果在计算相对速度/时间时，公式中依然包含流速变量且未被消去，则判定为逻辑错误
    if 'v_river' in pred or 'v_w' in pred or '流速' in pred:
        # 进一步检查是否在最终相对速度表达式中错误地保留了它
        if re.search(r'v_rel\s*=\s*.*[\+\-]\s*(v_river|v_w)', pred):
            return {'result': 'fail', 'message': '相对速度方程中错误地包含了未抵消的介质流速项', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了介质流速抵消', 'evidence': ''}

# rule_id=norm_2ddfbfdfa7bfddc4 | domain=Mechanics | topic=Relative Motion
# rule_id=norm_2ddfbfdfa7bfddc4 | domain=Mechanics | topic=Relative Motion
def check_norm_2ddfbfdfa7bfddc4_e5c3336caf45(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及圆柱/球体碰撞及冲击参数 L (Impact Parameter)
    trigger_keywords = ['impact parameter', '冲击参数', '偏置距离', 'collision', '碰撞', 'cylinder', 'sphere', '圆柱', '球']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到圆柱或球体碰撞场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找 L, R, theta/phi 等关键符号及几何映射关系
    pred = prediction.lower()
    # 检查是否提及了 L 和 R 的比例关系或三角函数关系
    has_l = 'l' in pred
    has_r = 'r' in pred
    has_trig = any(trig in pred for trig in ['sin', 'cos', 'tan', 'arcsin', 'arccos'])

    if not (has_l and has_r):
        return {'result': 'fail', 'message': '推理中缺失冲击参数 L 或半径 R 的几何描述', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 校验 sin(theta) = L/R 或类似的几何映射
    # 匹配模式如 sin(phi) = L/R, L = R*sin(phi), sin(theta) = b/R 等
    patterns = [
        r'sin\(.*?\)\s*=\s*[lb]/r',
        r'[lb]\s*=\s*r\s*\*?\s*sin\(.*?\)',
        r'sin\(.*?\)\s*=\s*r/[lb]', # 错误形式捕获（可选）
        r'[lb]/r'
    ]

    found_relation = False
    for pattern in patterns:
        if re.search(pattern, pred.replace(' ', '')):
            found_relation = True
            break

    if found_relation:
        # 进一步检查是否满足 sin(theta) = L/R 的正确性
        if re.search(r'sin\(.*?\)\s*=\s*[lb]/r', pred.replace(' ', '')) or re.search(r'[lb]\s*=\s*r\s*\*?\s*sin', pred.replace(' ', '')):
            return {'result': 'pass', 'message': '冲击参数与角度的几何映射关系正确', 'evidence': re.search(r'.{0,20}[lb].{0,20}', pred).group() if re.search(r'[lb]', pred) else ''}
        else:
            return {'result': 'fail', 'message': '冲击参数几何映射公式结构错误', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '未能明确识别几何映射公式', 'evidence': ''}

# rule_id=norm_72faf2e0422e3981 | domain=Mechanics | topic=Relative Motion
# rule_id=norm_72faf2e0422e3981 | domain=Mechanics | topic=Relative Motion
def check_norm_72faf2e0422e3981_a3a0d9a73bae(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及引力助推、弹性碰撞或行星参考系下的经过
    trigger_keywords = ['引力助推', 'gravity assist', '弹性碰撞', 'elastic collision', '行星参考系', '天体参考系', '中心力场', 'scattering']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '题目未涉及引力助推或中心力场散射场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别模型是否提到进入速率与离开速率相等 (|v_in| = |v_out|)
    # 重点检查在天体/中心体参考系下的速率守恒描述
    pred_lower = prediction.lower()
    conservation_patterns = [
        r'速率相等', r'速率不变', r'speed is the same', r'speed remains unchanged',
        r'v_in\s*=\s*v_out', r'v_1\s*=\s*v_2', r'v_f\s*=\s*v_i',
        r'magnitude of velocity', r'大小相等'
    ]

    has_conservation_logic = any(re.search(p, pred_lower) for p in conservation_patterns)

    # Step 3: 符号与公式校验 — 检查是否满足 |v_in| = |v_out| 的逻辑表达
    # 寻找类似 v1=v2 或速度绝对值相等的表达式
    formula_match = re.search(r'v_?1\s*=\s*v_?2|v_?in\s*=\s*v_?out|\|v\|', pred_lower)

    if has_conservation_logic or formula_match:
        return {'result': 'pass', 'message': '模型正确识别了中心力场散射中的速率守恒律', 'evidence': re.search(r'.{0,50}(速率|speed|v_in).{0,50}', pred_lower).group(0) if has_conservation_logic else ''}

    # 如果明确讨论了过程但没有提到速率相等，或者给出了错误的速率关系，则判定为 fail
    if 'velocity' in pred_lower or 'speed' in pred_lower:
        return {'result': 'fail', 'message': '模型未识别出在天体参考系下进入与离开速率相等的守恒关系', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足，无法判断模型是否应用了速率守恒律', 'evidence': ''}

# rule_id=norm_883c8ca0fa01078b | domain=Mechanics | topic=Relative Motion
# rule_id=norm_883c8ca0fa01078b | domain=Mechanics | topic=Relative Motion
def check_norm_883c8ca0fa01078b_3d795ef81c2f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及斜面、高度h、水平位移L及摩擦系数mu
    content_to_check = (question + context).lower()
    if not (('斜面' in content_to_check or 'inclined' in content_to_check) and
            ('h' in content_to_check or '高度' in content_to_check) and
            ('l' in content_to_check or '水平' in content_to_check) and
            ('mu' in content_to_check or '摩擦' in content_to_check)):
        return {'result': 'inconclusive', 'message': '未检测到斜面几何参数(h, L, mu)的完整描述', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证克服摩擦力做功是否正确关联到水平位移 L (Wf = mu * m * g * L)
    # 检查 prediction 中是否包含 mu*m*g*L 或类似的简化形式
    pred = prediction.replace(' ', '')
    # 匹配 mu*m*g*L, \mu mgL, mu*mg*L 等变体
    friction_work_pattern = r'(\mu|mu).*?m.*?g.*?L'

    # 检查是否错误地使用了斜面长度 s 或 sin/cos 且未简化
    # 规则核心是检查是否识别出 cos(theta) * (h/sin(theta)) = L/cos(theta) * cos(theta) = L
    has_simplified_l = re.search(friction_work_pattern, pred, re.IGNORECASE)

    # Step 3: 符号覆盖检查 (mgh - mu*mg*L = 1/2mv^2)
    energy_cons_pattern = r'm.*?g.*?h.*?-.*?(\mu|mu).*?m.*?g.*?L.*?=.*?1/2.*?m.*?v\^2'
    has_energy_eq = re.search(energy_cons_pattern, pred, re.IGNORECASE)

    if has_simplified_l:
        return {'result': 'pass', 'message': '成功识别摩擦力做功与水平位移L的几何关系', 'evidence': re.search(friction_work_pattern, pred, re.IGNORECASE).group()}

    if 'mu' in pred and 'L' in pred and ('cos' in pred or 'sin' in pred):
        # 如果出现了三角函数但没有简化到 L，可能存在计算冗余或错误
        return {'result': 'fail', 'message': '摩擦力做功未正确简化为与水平位移L相关的形式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定摩擦力做功的计算逻辑是否符合几何一致性', 'evidence': ''}

# rule_id=norm_9510aaf2323ef6ee | domain=Mechanics | topic=Relative Motion
# rule_id=norm_9510aaf2323ef6ee | domain=Mechanics | topic=Relative Motion
def check_norm_9510aaf2323ef6ee_1a9a783f93d9(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及往返运动、不同速度 v1/v2 以及总时间 T 限制最大距离
    trigger_keywords = ['往返', '去程', '回程', '最大距离', '总时间', 'round trip', 'back and forth']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到往返非对称速度运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否使用了正确的时间分配公式 T = d/v1 + d/v2 或其变形
    # 匹配 d = T * (v1*v2)/(v1+v2) 或 T = d/v1 + d/v2 的结构
    pred = prediction.replace(' ', '')
    # 检查是否错误地使用了单一平均速度 (v1+v2)/2 或单向速度
    wrong_patterns = [
        r'd=T\*\(v1\+v2\)/2',
        r'd=T\*v1',
        r'd=T\*v2'
    ]
    for wp in wrong_patterns:
        if re.search(wp, pred, re.IGNORECASE):
            return {'result': 'fail', 'message': '错误地使用了单一平均速度或单向速度计算最大距离', 'evidence': prediction}

    # Step 3: 符号与公式结构校验
    # 匹配核心公式：d = T / (1/v1 + 1/v2) 或 d = (T*v1*v2)/(v1+v2)
    correct_patterns = [
        r'd=T/\(1/v1\+1/v2\)',
        r'd=T\*v1\*v2/\(v1\+v2\)',
        r'T=d/v1\+d/v2',
        r'd=\(v1\*v2\*T\)/\(v1\+v2\)'
    ]

    found_correct = False
    for cp in correct_patterns:
        if re.search(cp, pred, re.IGNORECASE):
            found_correct = True
            break

    if found_correct:
        return {'result': 'pass', 'message': '正确使用了往返非对称速度的最大距离公式', 'evidence': prediction}

    # 如果没有明确的公式但有相关的文字描述，且没有明显错误，则返回 inconclusive
    if 'v1' in pred and 'v2' in pred and 'T' in pred and 'd' in pred:
        return {'result': 'inconclusive', 'message': '检测到相关变量但公式结构不清晰', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '证据不足，无法判断逻辑正确性', 'evidence': ''}

# rule_id=norm_9c3b0045754bb487 | domain=Mechanics | topic=Relative Motion
# rule_id=norm_9c3b0045754bb487 | domain=Mechanics | topic=Relative Motion
def check_norm_9c3b0045754bb487_bc8ab0b82d0c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及物体与运动曲面（圆柱、球、运动板）的碰撞
    trigger_keywords = ['碰撞', 'collision', '撞击', 'hit']
    surface_keywords = ['运动', 'moving', 'velocity', '速度']
    geometry_keywords = ['圆柱', '球', 'cylinder', 'sphere', '曲面', 'surface']

    text_to_check = (question + context).lower()
    is_triggered = any(k in text_to_check for k in trigger_keywords) and \
                   any(k in text_to_check for k in surface_keywords) and \
                   any(k in text_to_check for k in geometry_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到物体与运动曲面碰撞的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否包含参考系切换、法向/切向分解及分量处理
    pred = prediction.lower()
    # 检查是否提到参考系切换或相对速度
    has_frame_shift = any(k in pred for k in ['参考系', 'frame', '相对速度', 'relative velocity', 'v_rel'])
    # 检查是否提到法向和切向分解
    has_decomposition = any(k in pred for k in ['法向', '切向', 'normal', 'tangential', '分解'])

    if not (has_frame_shift and has_decomposition):
        return {'result': 'fail', 'message': '未按要求进行参考系切换或速度分解（法向/切向）', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查法向取反、切向不变的逻辑
    # 匹配法向分量取反的特征 (e.g., v_n' = -v_n)
    normal_reversal = re.search(r'v.*n.*\s*=\s*-\s*v.*n|法向.*取反|normal.*reverse', pred)
    # 匹配切向分量不变的特征 (e.g., v_t' = v_t)
    tangential_const = re.search(r'v.*t.*\s*=\s*v.*t|切向.*不变|tangential.*remain', pred)

    if normal_reversal and tangential_const:
        return {'result': 'pass', 'message': '符合运动参考系碰撞分解准则', 'evidence': '检测到法向取反与切向不变的逻辑'}

    if not normal_reversal:
        return {'result': 'fail', 'message': '未明确体现碰撞后法向速度分量取反', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑步骤不完整或表述模糊', 'evidence': ''}

# rule_id=norm_a20206364b7023d0 | domain=Mechanics | topic=Relative Motion
# rule_id=norm_a20206364b7023d0 | domain=Mechanics | topic=Relative Motion
def check_norm_a20206364b7023d0_835cbfad13a3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否描述物体相对于地面以特定角度运动
    trigger_keywords = ['relative to the ground', 'relative to the earth', 'ground speed', 'angle', 'theta', 'degree']
    q_c_text = (question + context).lower()
    if not any(kw in q_c_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到相对于地面的角度运动描述', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别预测中是否涉及速度分解或合成公式
    pred = prediction.lower()
    # 寻找涉及 theta, v_g (ground), v_rel (airspeed/relative), v_w (wind/water) 的表达式
    # 重点检查是否将 theta 错误地直接用于相对速度的分量，而忽略了合速度的定义
    has_velocity_components = re.search(r'(sin|cos|tan)\(.*theta.*\)', pred)
    if not has_velocity_components:
        return {'result': 'inconclusive', 'message': '预测中未发现角度相关的速度分解计算', 'evidence': ''}

    # Step 3: 符号与公式校验 — 检查合速度方向是否满足 v_g * sin(theta) = v_rel_y + v_w_y 或类似结构
    # 错误典型：直接写 v_rel * sin(theta) = ... (当 theta 是对地角度时)
    # 正确逻辑：theta 应该与 ground velocity (v_g) 关联
    ground_velocity_match = re.search(r'v_?g.*(sin|cos|tan)\(', pred)
    relative_velocity_error = re.search(r'(v_?rel|v_?air|v_?plane).*(sin|cos|tan)\(.*theta.*\)', pred)

    # 如果预测中将对地角度 theta 直接作用于相对速度且没有体现合速度关系，则判定为 modeling 错误
    if relative_velocity_error and not ground_velocity_match:
        return {
            'result': 'fail',
            'message': '错误地将对地运动角度 theta 分配给了相对速度 (如 airspeed) 而非合速度 (ground velocity)',
            'evidence': re.search(r'.{0,50}(v_?rel|v_?air|v_?plane).*(sin|cos|tan)\(.*theta.*\).{0,50}', pred).group(0)
        }

    # 检查是否符合 canonical 提示的结构：v_g * sin(theta) = v_rel_y + v_w_y
    if re.search(r'v_?g.*sin\(.*theta.*\)', pred) or re.search(r'tan\(.*theta.*\).*=.*v_?y.*/.*v_?x', pred):
        return {'result': 'pass', 'message': '正确区分了合速度方向与分速度关系', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定速度方向分配是否正确', 'evidence': ''}

# rule_id=norm_aa154d92a44032a4 | domain=Mechanics | topic=Relative Motion
# rule_id=norm_aa154d92a44032a4 | domain=Mechanics | topic=Relative Motion
def check_norm_aa154d92a44032a4_df04fecc94b7(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两质点相遇的最短时间问题
    trigger_keywords = ['最短时间', '相遇', '追及', 'shortest time', 'meet', 'catch up']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到最短时间相遇的相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否提到速度方向应在连线上（矢量对冲）
    # 检查是否提到了垂直分量、分量分配或方向一致性
    logic_keywords = ['连线', '方向', '分量', '垂直', '对冲', 'along the line', 'direction', 'component', 'perpendicular']
    pred_lower = prediction.lower()

    # 如果预测中完全没有讨论速度方向或分量分配，则认为建模缺失
    if not any(kw in pred_lower for kw in logic_keywords):
        return {'result': 'fail', 'message': '未讨论速度分配或方向选择，违反最短时间相遇的矢量对冲原则', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查是否符合 t = L / (u1 + u2) 的结构
    # 匹配类似 L/(u1+u2) 或 d/(v1+v2) 的结构
    formula_pattern = r'([LdD]|dist(ance)?)\s*/\s*\(?([uvV][1a]?\s*\+\s*[uvV][2b]?)\)?'
    if re.search(formula_pattern, prediction, re.IGNORECASE):
        return {'result': 'pass', 'message': '公式结构符合最短时间相遇的矢量对冲原则', 'evidence': re.search(formula_pattern, prediction, re.IGNORECASE).group(0)}

    # 如果提到了方向但没有明确公式，且没有明显错误，返回 inconclusive
    if '垂直' in pred_lower or '分量' in pred_lower:
        return {'result': 'inconclusive', 'message': '提到了速度分配逻辑但未见明确计算公式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足以判定是否违反最短时间原则', 'evidence': ''}

# rule_id=norm_b1263f87f2e032fa | domain=Mechanics | topic=Relative Motion
# rule_id=norm_b1263f87f2e032fa | domain=Mechanics | topic=Relative Motion
def check_norm_b1263f87f2e032fa_21ea829db480(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及初速度、恒定反向加速度及路程计算
    # 关键词：路程/distance, 减速/deceleration, 停止/stop, 往返/back and forth
    trigger_keywords = ['路程', 'distance', 'total distance', '总路程']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到路程计算场景', 'evidence': ''}

    # 检查是否存在减速或反向加速度的描述
    decel_keywords = ['减速', '反向', 'opposite', 'deceleration', 'retardation']
    if not any(kw in (question + context).lower() for kw in decel_keywords):
        return {'result': 'inconclusive', 'message': '未检测到减速或反向加速度场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否区分了位移(displacement)与路程(distance)
    # 核心逻辑：如果物体发生调头（v0与a反向且时间足够），路程应大于位移绝对值
    pred = prediction.lower()

    # 检查是否提到了位移与路程的区别，或者是否计算了最高点/转折点
    turning_point_indicators = ['最高点', '停下', 'v=0', 'turn', 'stop', 'peak', 'maximum height']
    has_turning_logic = any(ind in pred for ind in turning_point_indicators)

    # Step 3: 公式结构校验
    # 检查是否使用了路程公式：S = v0^2/(2a) + |delta x| 或类似的段落求和逻辑
    # 匹配类似 v0^2/(2a) 或 2*... 的结构
    formula_pattern = r'(v_?0\^2|v0\*\*2)/(2\*?a|2\|a\|)'
    sum_pattern = r's1\s*\+\s*s2|d1\s*\+\s*d2|\|.*\|\s*\+\s*\|.*\|'

    if re.search(formula_pattern, pred) or re.search(sum_pattern, pred):
        return {'result': 'pass', 'message': '模型正确识别了路程计算中的分段或转折逻辑', 'evidence': re.search(r'.{0,50}(s1\+s2|v0\^2/2a).{0,50}', pred).group(0) if re.search(r'.{0,50}(s1\+s2|v0\^2/2a).{0,50}', pred) else 'found formula'}

    # 如果计算结果直接套用位移公式 x = v0t + 0.5at^2 且未考虑绝对值/转折，则判定为 fail
    displacement_only_pattern = r's\s*=\s*v_?0\s*\*?\s*t\s*[\+\-]\s*0\.5\s*\*?\s*a\s*\*?\s*t\^2'
    if re.search(displacement_only_pattern, pred) and not has_turning_logic:
        return {'result': 'fail', 'message': '模型直接使用位移公式计算路程，未考虑反向运动导致的差异', 'evidence': 'Detected displacement formula for distance calculation'}

    return {'result': 'inconclusive', 'message': '无法确定模型是否正确区分了位移与路程', 'evidence': ''}

# rule_id=norm_dab54027ce32f08c | domain=Mechanics | topic=Relative Motion
# rule_id=norm_dab54027ce32f08c | domain=Mechanics | topic=Relative Motion
def check_norm_dab54027ce32f08c_95ec38e8fae2(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两个参考系（如太阳、行星、航天器、动能转换）
    trigger_keywords = ['参考系', 'frame', 'kinetic energy', '动能', '行星', 'planet', 'sun', '太阳', 'delta k']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到参考系变换或动能转换场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找动能增量公式 Delta K = m * V * delta v 的变体或点积逻辑
    # 重点检查是否包含质量 m, 参考系速度 V, 以及速度变化量 delta v
    pred = prediction.lower()
    # 匹配类似 m*V*(v2-v1) 或 m*V*delta_v 的结构
    formula_pattern = r'm.*[Vv].*(\\Delta|delta).*v|m.*[Vv].*\(v_?2\s*-\s*v_?1\)'
    dot_product_pattern = r'v\s*\.\s*(\\Delta|delta)\s*v|v\s*\.\s*d\s*v'

    has_formula = re.search(formula_pattern, prediction) or re.search(dot_product_pattern, prediction)

    # Step 3: 符号覆盖检查 (V, m, v1, v2)
    required_symbols = ['m', 'V', 'v_1', 'v_2']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)

    if not has_formula and symbol_count < 2:
        return {'result': 'fail', 'message': '预测中缺失动能增量公式或关键物理量(m, V, delta v)', 'evidence': prediction[:200]}

    # Step 4: 检查 ΔK_P=0 的简化逻辑（如果提到增量完全由点积决定）
    if 'delta' in pred and ('dot product' in pred or '点积' in pred or '*' in pred):
        return {'result': 'pass', 'message': '检测到符合参考系变换动能增量的计算逻辑', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定推理过程是否严格遵循该动能增量公式', 'evidence': ''}

# rule_id=norm_e7d7bd90079c50a1 | domain=Mechanics | topic=Relative Motion
# rule_id=norm_e7d7bd90079c50a1 | domain=Mechanics | topic=Relative Motion
def check_norm_e7d7bd90079c50a1_2ba795439713(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及传送带、初速度以及二维/多向运动描述
    trigger_keywords = ['传送带', 'belt', 'v_0', '初速度', '进入']
    q_c = (question + context).lower()
    if not any(kw in q_c for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到传送带物体运动场景', 'evidence': ''}

    # 检查是否暗示二维或不同方向（如：偏转、夹角、坐标轴x/y）
    if not re.search(r'方向|角度|angle|axis|坐标|x轴|y轴|垂直|水平', q_c):
        return {'result': 'inconclusive', 'message': '未检测到二维相对运动特征', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了相对速度矢量关系 v_rel = v_obj - v_belt
    pred = prediction.lower()
    # 匹配相对速度的定义或计算逻辑
    rel_vel_pattern = r'(v_?rel|相对速度).*=.*(v_?0|v_?obj|v_?物).*(v_?b|v_?belt|v_?传)'
    has_rel_vel = re.search(rel_vel_pattern, pred) or '相对速度' in pred

    if not has_rel_vel:
        return {'result': 'fail', 'message': '未明确建立传送带参考系下的相对速度矢量关系', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查摩擦力方向是否与相对速度方向相反
    # 检查 symbolic_hint 中的关键符号 f, mu, v_rel 以及方向一致性描述
    friction_dir_keywords = ['摩擦力', 'f', 'mu', '方向']
    opp_keywords = ['相反', 'opposite', '负方向', '-']

    # 检查公式结构: f = -mu*m*g * (v_rel/|v_rel|)
    formula_match = re.search(r'f.*=.*mu.*m.*g.*v_?rel', pred) or re.search(r'f.*=.*-.*v_?rel', pred)

    if not (any(kw in pred for kw in friction_dir_keywords) and any(okw in pred for okw in opp_keywords)):
        if not formula_match:
            return {'result': 'fail', 'message': '未正确判定摩擦力方向与相对速度方向相反', 'evidence': prediction[:200]}

    # Step 4: 综合判定
    if formula_match or (has_rel_vel and '相反' in pred):
        return {'result': 'pass', 'message': '正确应用了二维相对运动下的摩擦力判定规则', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程不完整，无法确定是否遵循相对运动判定', 'evidence': ''}

# rule_id=norm_f4b8b5f7147f556c | domain=Mechanics | topic=Relative Motion
# rule_id=norm_f4b8b5f7147f556c | domain=Mechanics | topic=Relative Motion
def check_norm_f4b8b5f7147f556c_897cd9a34e2f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及风速/流速中的垂直往返运动
    trigger_keywords = ['风', '流', 'wind', 'current', 'river', 'crosswind', '垂直', 'perpendicular', '往返']
    text_to_check = (question + context).lower()
    if not any(kw in text_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到侧风或介质流速中的运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否考虑了速度合成（勾股定理形式）
    # 寻找 sqrt(v^2 - v_w^2) 或类似的平方差开方结构
    pred = prediction.lower()
    # 匹配 v^2 - v_w^2 或类似的减法结构，通常出现在垂直分量计算中
    vector_pattern = r'sqrt\(.*\^2\s*-\s*.*\^2\)'
    pythagorean_pattern = r'v.*\^2\s*=\s*v.*\^2\s*\+\s*v.*\^2'

    has_vector_comp = re.search(vector_pattern, pred) or re.search(pythagorean_pattern, pred) or '勾股' in pred or 'pythagorean' in pred

    # Step 3: 符号校验与结论
    # 如果明确提到了风速影响但直接忽略（如 v_ground = v_rel），则判定为 fail
    if re.search(r'v_{?ground}?|地速', pred):
        if not has_vector_comp:
            # 检查是否错误地直接相等或直接加减
            if re.search(r'v_{?ground}?\s*=\s*v_{?rel}?', pred) or re.search(r'v_{?ground}?\s*=\s*v_{?w}?', pred):
                return {'result': 'fail', 'message': '地速计算未采用矢量合成（勾股定理），直接忽略了侧向风速的影响', 'evidence': prediction[:200]}

    if has_vector_comp:
        return {'result': 'pass', 'message': '检测到正确的矢量合成逻辑', 'evidence': '匹配到矢量合成相关描述或公式'}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了速度合成修正', 'evidence': ''}

# rule_id=norm_06e7024508f222eb | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_06e7024508f222eb | domain=Mechanics | topic=Projectile Motion
def check_norm_06e7024508f222eb_f3be6e5d6bbf(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及“最短时间”且给定高度差 H
    trigger_keywords = ['最短时间', '最小时间', 'least time', 'minimum time']
    has_trigger = any(kw in (question + context) for kw in trigger_keywords)
    has_height = any(kw in (question + context) for kw in ['高度', '落差', ' H ', ' h '])

    if not (has_trigger and has_height):
        return {'result': 'inconclusive', 'message': '未检测到最短时间与高度差的关联场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否利用竖直方向自由落体公式 H = 1/2 * g * t^2 建模
    # 匹配公式变体：t = sqrt(2H/g), H = 0.5gt^2, t^2 = 2H/g 等
    pred_clean = prediction.replace(' ', '')
    logic_patterns = [
        r't=sqrt\(2[Hh]/g\)',
        r'[Hh]=1/2\*g\*t\^2',
        r'[Hh]=0\.5\*g\*t\^2',
        r't\^2=2[Hh]/g',
        r't=\\sqrt{2[Hh]/g}'
    ]

    found_logic = False
    for pattern in logic_patterns:
        if re.search(pattern, pred_clean, re.IGNORECASE):
            found_logic = True
            break

    # Step 3: 综合判定
    if found_logic:
        return {'result': 'pass', 'message': '正确识别最短时间由竖直高度决定的物理模型', 'evidence': '匹配到公式结构'}

    # 如果没有公式，检查是否有文字描述
    if '自由落体' in prediction and ('高度' in prediction or 'g' in prediction):
        return {'result': 'pass', 'message': '文字描述符合自由落体决定最短时间的逻辑', 'evidence': prediction[:100]}

    # 若明确在求最短时间却使用了错误的初速度关联公式，则判定为建模错误
    if 'v_0' in prediction and 't' in prediction and 'min' in (question + prediction):
        return {'result': 'fail', 'message': '未直接利用高度差确定最短时间，可能存在建模冗余或错误', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了最短时间判定逻辑', 'evidence': ''}

# rule_id=norm_16e6d58a393f4477 | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_16e6d58a393f4477 | domain=Mechanics | topic=Projectile Motion
def check_norm_16e6d58a393f4477_8b36cdcc7b42(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及打板入筐（backboard/rim/basket）及距离描述
    trigger_keywords = ['backboard', 'scoring off', 'hit the board', '打板', '篮板']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and ('distance' in combined_text or 'm' in combined_text)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到打板入筐场景或距离参数', 'evidence': ''}

    # Step 2: 检查逻辑 — 校验撞击点高度与篮筐高度关系，以及反弹位移模型
    pred = prediction.lower()
    # 检查是否讨论了撞击点高度 (impact height) 与篮筐 (rim/hoop) 的位置关系
    if 'height' not in pred or ('rim' not in pred and 'hoop' not in pred):
        return {'result': 'fail', 'message': '未建立撞击点与篮筐高度的几何关系', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 校验 x_total = x_to_board + x_from_board_to_rim 逻辑
    # 检查是否包含水平位移分解的逻辑（即总位移由到板位移和回弹位移组成）
    required_symbols = ['x_to_board', 'x_from_board_to_rim']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)

    # 匹配水平位移相加或几何分段的模式
    pattern_geometry = r'(x_total|total\s+distance).*=.*(\+|plus)'
    if symbol_count >= 1 or re.search(pattern_geometry, pred):
        return {'result': 'pass', 'message': '已包含打板入筐的几何约束模型', 'evidence': prediction[:200]}

    # 如果有计算过程但缺乏明确的位移分解逻辑，返回 fail
    if 'trajectory' in pred or 'bounce' in pred:
        return {'result': 'fail', 'message': '缺乏明确的水平位移分解公式 (x_total = x_to_board + x_from_board_to_rim)', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足以判定几何约束校验', 'evidence': ''}

# rule_id=norm_1fe7b6f320d3fb95 | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_1fe7b6f320d3fb95 | domain=Mechanics | topic=Projectile Motion
def check_norm_1fe7b6f320d3fb95_e87c4562f051(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“射程”及“重力场”环境
    trigger_keywords = ['射程', 'range', 'horizontal distance', '水平位移']
    gravity_keywords = ['重力', 'gravity', ' g ', 'acceleration due to gravity']

    combined_text = (question + context).lower()
    is_triggered = any(k in combined_text for k in trigger_keywords) and any(k in combined_text for k in gravity_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到射程计算或重力场环境', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证最终表达式是否包含 g 且量纲为长度 [L]
    # 重点检查是否出现了 v^2/g 形式，或者是否错误地只用了速度乘以时间（且时间与g无关）
    pred_lower = prediction.lower()

    # 检查是否包含重力加速度 g
    has_g = ' g ' in pred_lower or '/g' in pred_lower or '*g' in pred_lower or '重力加速度' in pred_lower

    # 检查公式结构 R ∝ v^2 / g
    # 匹配类似 v^2/g, v**2/g, (v^2)/g, v*v/g 等模式
    range_formula_pattern = r'v[\^\*]{1,2}2\s*/\s*g|v\s*\*\s*v\s*/\s*g'
    has_correct_structure = re.search(range_formula_pattern, pred_lower) is not null

    # Step 3: 判定结果
    if not has_g:
        # 如果求射程却完全没用到 g，极大概率量纲错误或模型简化过度
        return {
            'result': 'fail',
            'message': '射程表达式缺失重力加速度 g，量纲可能不一致或误算为匀速直线运动长度',
            'evidence': prediction[-200:]
        }

    if has_correct_structure:
        return {
            'result': 'pass',
            'message': '检测到符合 v^2/g 形式的射程公式，量纲逻辑自洽',
            'evidence': re.search(range_formula_pattern, pred_lower).group() if re.search(range_formula_pattern, pred_lower) else ''
        }

    # 如果包含 g 但结构不清晰，保守返回 inconclusive
    return {'result': 'inconclusive', 'message': '检测到重力相关项，但无法确定射程公式的量纲正确性', 'evidence': ''}

# rule_id=norm_229a0d57b425d343 | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_229a0d57b425d343 | domain=Mechanics | topic=Projectile Motion
def check_norm_229a0d57b425d343_1be11fac04a7(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“最短时间”且存在位移约束（如斜面、高度H）
    trigger_keywords = ['最短时间', 'minimum time', 'least time', 'shortest time']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到最短时间相关场景', 'evidence': ''}

    if not re.search(r'[Hh]|高度|位移', question + context):
        return {'result': 'inconclusive', 'message': '未检测到明确的位移或高度约束', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否提到初速度趋于无穷大或轨迹趋近直线
    pred_lower = prediction.lower()
    logic_keywords = ['无穷大', 'infinite', '趋近于直线', 'straight line', 'v趋于', 'v ->', 'v →']
    has_logic = any(kw in pred_lower for kw in logic_keywords)

    # Step 3: 公式校验 — 检查是否包含 t = sqrt(2H/g) 的结构
    # 匹配 sqrt(2H/g), sqrt(2h/g), (2H/g)^0.5 等形式
    formula_pattern = r'sqrt\(2[Hh]/g\)|\(2[Hh]/g\)\^\{?0\.5\}?|\\sqrt\{\\frac\{2[Hh]\}\{g\}\}'
    formula_match = re.search(formula_pattern, prediction)

    if formula_match:
        return {'result': 'pass', 'message': '符合最短时间极限法则及公式结构', 'evidence': formula_match.group()}

    if '最短时间' in (question + context) and ('g' in pred_lower) and ('H' in prediction or 'h' in prediction):
        if not has_logic:
            return {'result': 'fail', 'message': '未说明最短时间对应初速度无穷大且轨迹趋于直线的物理逻辑', 'evidence': prediction[:200]}
        else:
            return {'result': 'inconclusive', 'message': '逻辑存在但公式表达不完整', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足以判定', 'evidence': ''}

# rule_id=norm_27119a3fc0edbce8 | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_27119a3fc0edbce8 | domain=Mechanics | topic=Projectile Motion
def check_norm_27119a3fc0edbce8_faadb961ec33(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否存在高度差且涉及最大水平位移/射程
    q_c = (question + context).lower()
    is_non_level = any(kw in q_c for kw in ['高度差', '落点', '抛出点', 'h', 'height difference', 'cliff', 'ground'])
    is_max_range = any(kw in q_c for kw in ['最大水平位移', '最大射程', 'max range', 'maximum horizontal distance'])

    if not (is_non_level and is_max_range):
        return {'result': 'inconclusive', 'message': '未检测到非等高抛体最大射程场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否错误套用 45 度角
    pred = prediction.lower()
    # 如果在有高度差的情况下直接断言 45 度是最大射程角，通常是错误的建模
    if re.search(r'45\s*(度|deg|degree)', pred) and ('max' in pred or '最大' in pred):
        if 'h' in q_c or '高度' in q_c:
            return {'result': 'fail', 'message': '在存在高度差的情况下错误套用了45度角作为最大射程角', 'evidence': re.search(r'.{0,30}45\s*(度|deg|degree).{0,30}', pred).group() if re.search(r'.{0,30}45\s*(度|deg|degree).{0,30}', pred) else pred[:100]}

    # Step 3: 公式校验 — 检查是否使用了正确的包络线公式或角度公式
    # 检查 canonical: x_max = (v_0/g) * sqrt(v_0^2 + 2gh)
    formula_patterns = [
        r'v_?0/g\s*\*?\s*sqrt\(v_?0\^2\s*\+\s*2gh\)',
        r'v\^2/g\s*\*?\s*sqrt\(1\s*\+\s*2gh/v\^2\)',
        r'cos\(2\s*[θtheta]\)\s*=\s*gh/\(v\^2\s*\+\s*gh\)'
    ]

    found_correct_logic = False
    for pattern in formula_patterns:
        if re.search(pattern, pred.replace(' ', '')):
            found_correct_logic = True
            break

    if found_correct_logic:
        return {'result': 'pass', 'message': '正确使用了非等高抛体最大射程公式', 'evidence': '检测到符合规范的物理公式'}

    # Step 4: 符号覆盖检查
    required_symbols = ['g', 'h', 'v']
    missing_symbols = [s for s in required_symbols if s not in pred]
    if len(missing_symbols) == len(required_symbols):
         return {'result': 'fail', 'message': '未在推导中发现必要的物理量符号(g, h, v)', 'evidence': pred[:100]}

    return {'result': 'inconclusive', 'message': '无法确定推导逻辑是否完全符合非等高极值判定', 'evidence': ''}

# rule_id=norm_27c3f9fde03cddf9 | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_27c3f9fde03cddf9 | domain=Mechanics | topic=Projectile Motion
def check_norm_27c3f9fde03cddf9_83b367203baa(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及抛体运动的最大高度与最高点速度/角度关系
    trigger_keywords = ['最大高度', '最高点', 'maximum height', 'peak', 'projectile']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到抛体运动最高点相关场景', 'evidence': ''}

    # Step 2: 检查推理过程中是否包含核心物理量：高度H、角度theta、最高点速度v_top (即v_x)
    pred = prediction.lower()
    # 检查是否提及高度、角度和速度
    has_h = re.search(r'[Hh]|height', pred)
    has_theta = re.search(r'theta|角度|angle|tan', pred)
    has_v = re.search(r'v_|v_x|v_top|速度|velocity', pred)

    if not (has_h and has_theta and has_v):
        return {'result': 'inconclusive', 'message': '推理过程中缺少高度、角度或最高点速度的关键要素', 'evidence': prediction[:200]}

    # Step 3: 检查公式逻辑 H = (v_x * tan(theta))^2 / (2g)
    # 变体检查：H = v_y^2 / 2g = (v_x * tan(theta))^2 / 2g
    formula_patterns = [
        r'H\s*=\s*\(v_x\s*\*\s*tan\(theta\)\)\^2\s*/\s*\(2g\)',
        r'H\s*=\s*v_x\^2\s*tan\^2\(theta\)\s*/\s*\(2g\)',
        r'v_y\s*=\s*v_x\s*\*\s*tan\(theta\)',
        r'H\s*=\s*\(v_top\s*\*\s*tan\(theta\)\)\^2\s*/\s*\(2g\)'
    ]

    found_logic = False
    for pattern in formula_patterns:
        if re.search(pattern, prediction.replace(' ', '')):
            found_logic = True
            break

    if found_logic:
        return {'result': 'pass', 'message': '最高点参数关联公式符合物理逻辑', 'evidence': prediction[:200]}

    # 如果提到了这些量但公式明显错误（例如量纲不对或缺少平方）
    if re.search(r'H\s*=\s*v_x\s*tan\(theta\)\s*/\s*g', prediction.replace(' ', '')):
        return {'result': 'fail', 'message': '最高点参数关联公式错误，缺少平方或系数不当', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定公式是否严格满足 H = (v_x * tan(theta))^2 / (2g)', 'evidence': prediction[:200]}

# rule_id=norm_2ff4735733375ce1 | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_2ff4735733375ce1 | domain=Mechanics | topic=Projectile Motion
def check_norm_2ff4735733375ce1_377161b55540(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多个海拔高度（Elevation）或相对于特定点（如vent/nozzle）的上升高度
    trigger_keywords = ['elevation', 'altitude', 'above sea level', 'height above', 'relative to', 'vent', 'nozzle', '海拔', '相对于']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多重海拔或相对高度描述', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证 prediction 是否混淆了绝对海拔与相对射高
    # 如果题目给出了相对于喷口(vent)的高度，初速度计算应使用该相对高度 H_relative
    pred_lower = prediction.lower()

    # 检查是否在计算初速度时错误地使用了绝对海拔（例如：海拔1000m，喷口在500m，射高100m，错误使用了1000或600）
    # 核心逻辑：初速度公式 v = sqrt(2gh) 中的 h 必须是相对射高
    formula_pattern = r'v.*=.*sqrt\(.*2.*g.*H.*\)'

    # 寻找公式痕迹
    has_sqrt_2gh = re.search(r'sqrt\s*\(\s*2\s*\*?\s*[gG9]\.?8?\s*\*?\s*\w+\s*\)', pred_lower) or \
                   re.search(r'v_?0?\s*=\s*\(?2\s*g\s*h\)?\^\(1/2\)', pred_lower)

    # Step 3: 符号与数值校验
    # 如果 prediction 中出现了将绝对海拔(elevation)直接代入运动学公式的情况，则判定为 fail
    # 这里的逻辑是：如果提到了 elevation 且在计算 v 时没有减去基准点高度，或者直接用了大数值的海拔
    if 'elevation' in combined_text and 'v' in pred_lower:
        # 检查是否识别了相对高度 (H_relative)
        if not any(term in pred_lower for term in ['relative height', 'height above the vent', 'h =', 'delta h']):
            # 如果只用了 elevation 而没体现相对差值，存在逻辑风险
            if re.search(r'v.*=.*sqrt\(.*elevation.*\)', pred_lower):
                return {'result': 'fail', 'message': '初速度计算错误使用了绝对海拔而非相对射高', 'evidence': prediction[:200]}

    if has_sqrt_2gh:
        return {'result': 'pass', 'message': '检测到符合物理基准的初速度计算公式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定初速度计算是否正确对齐了高度基准', 'evidence': ''}

# rule_id=norm_4f3077d678e659cb | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_4f3077d678e659cb | domain=Mechanics | topic=Projectile Motion
def check_norm_4f3077d678e659cb_80ab869e932e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及恢复系数 e 或碰撞前后的速度比值
    trigger_keywords = ['恢复系数', 'coefficient of restitution', 'e =', 'e=']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '题目未明确提及恢复系数相关定义', 'evidence': ''}

    # Step 2: 检查预测中是否包含速度突变的关系式 v_after = e * v_before
    # 匹配类似 v' = ev, v2 = e*v1, v_up = e * v_down 等模式
    pred = prediction.lower()
    # 匹配 e 与速度分量的乘积关系
    pattern_relation = r'(v[\w\d_]*\s*=\s*e\s*\*?\s*v[\w\d_]*|e\s*=\s*v[\w\d_]*\s*/\s*v[\w\d_]*)'
    match_relation = re.search(pattern_relation, pred)

    if not match_relation:
        # 如果没有直接公式，检查是否有文字描述速度减小为 e 倍
        if not ('e' in pred and ('速度' in pred or 'velocity' in pred) and ('倍' in pred or 'times' in pred)):
            return {'result': 'fail', 'message': '未在推理中发现恢复系数与速度的比例关系式', 'evidence': prediction[:200]}

    # Step 3: 验证该速度是否作为下一阶段运动的初速度 (逻辑衔接检查)
    # 寻找类似 "作为初速度", "initial velocity for", "next stage" 的表述
    logic_keywords = ['初速度', 'initial velocity', 'v0', 'v_0', '下一阶段', 'next']
    if not any(lk in pred for lk in logic_keywords):
        return {'result': 'fail', 'message': '未确认碰撞后的速度是否作为后续运动的初速度', 'evidence': prediction[-200:]}

    # Step 4: 符号覆盖检查 (基于 symbolic_hint)
    required = ['e', 'v']
    if all(r in pred for r in required):
        return {'result': 'pass', 'message': '成功验证恢复系数定义及其在速度突变中的应用', 'evidence': match_relation.group(0) if match_relation else '逻辑匹配成功'}

    return {'result': 'inconclusive', 'message': '逻辑存在但符号表达不完整', 'evidence': ''}

# rule_id=norm_4fbb346118c243ef | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_4fbb346118c243ef | domain=Mechanics | topic=Projectile Motion
def check_norm_4fbb346118c243ef_01c7afea6b73(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及抛体运动及最高点速度/瞬时速度
    trigger_keywords = ['最高点', 'top', 'peak', 'maximum height', 'projectile', '抛体', '平抛', '斜抛']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到抛体运动或最高点相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否提及水平速度守恒 (v_x = v_top) 或 速度合成公式
    pred = prediction.lower()
    # 检查是否包含速度分解或合成的基本逻辑
    has_vx_logic = re.search(r'v_?x\s*=\s*v_?(0|top|0x)', pred) or '水平速度' in pred
    has_vy_logic = re.search(r'v_?y', pred) or '竖直速度' in pred

    if not (has_vx_logic or 'v_top' in pred):
        return {'result': 'fail', 'message': '未体现水平速度分量守恒或最高点速度关系', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 v_h^2 = v_x^2 + v_y^2 及其演化形式
    # 匹配 v^2 = v_top^2 + ... 或类似的能量/速度合成结构
    formula_patterns = [
        r'v\^2\s*=\s*v_?top\^2\s*\+\s*v_?y\^2',
        r'v_?h\^2\s*=\s*v_?top\^2\s*\+\s*\(.*?2gh.*\)',
        r'v_?x\^2\s*\+\s*v_?y\^2',
        r'v_?0\^2\s*-\s*2gh'
    ]

    found_formula = any(re.search(pat, pred) for pat in formula_patterns)

    # 如果明确给出了错误的合成关系（如直接相加而非平方和）则报错
    if re.search(r'v\s*=\s*v_?x\s*\+\s*v_?y(?!\^)', pred) and 'vector' not in pred:
        return {'result': 'fail', 'message': '速度合成公式错误，应使用平方和关系', 'evidence': prediction[:200]}

    if found_formula:
        return {'result': 'pass', 'message': '符合抛体运动速度分量校验逻辑', 'evidence': '检测到速度合成或守恒公式'}

    return {'result': 'inconclusive', 'message': '推理过程中未显式列出完整的速度校验公式', 'evidence': ''}

# rule_id=norm_6089a480b949f2e5 | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_6089a480b949f2e5 | domain=Mechanics | topic=Projectile Motion
def check_norm_6089a480b949f2e5_5b2b6cfb2e4e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及密度函数且包含三角函数分母（csc, sec, cot 或 1/sin, 1/cos, 1/tan）
    trigger_patterns = [r'csc', r'sec', r'cot', r'1\s*/\s*sin', r'1\s*/\s*cos', r'1\s*/\s*tan']
    combined_text = (question + prediction + context).lower()
    is_triggered = any(re.search(p, combined_text) for p in trigger_patterns)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到包含三角函数分母的密度函数分布场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查在积分区间边界（如 0, pi/2）是否存在奇点讨论或收敛性处理
    # 物理场景下密度函数 n(theta) 必须在有限区域内可积
    pred_lower = prediction.lower()
    boundary_keywords = ['0', 'pi', 'boundary', 'limit', 'converge', 'singular', 'integral', '边界', '收敛', '奇点', '积分']

    # 检查是否讨论了分母为零的情况
    has_boundary_check = any(word in pred_lower for word in boundary_keywords)

    if not has_boundary_check:
        return {
            'result': 'fail',
            'message': '推导出的密度函数包含潜在发散的三角分母，但未在预测中进行边界收敛性检查或奇点讨论',
            'evidence': prediction[:200]
        }

    # Step 3: 符号/公式校验 — 检查是否包含 n(theta) 或类似的密度表达形式
    if 'n(' in pred_lower or 'rho(' in pred_lower or 'density' in pred_lower:
        # 如果提到了收敛或积分有限，则认为通过
        if re.search(r'(finite|less than|smaller than|bounded|<|<=|有限|小于)', pred_lower):
            return {'result': 'pass', 'message': '已对密度函数的收敛性或边界限制进行了必要说明', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '检测到相关公式但无法确定其收敛性逻辑是否严谨', 'evidence': ''}

# rule_id=norm_6a53a330d8e26e2d | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_6a53a330d8e26e2d | domain=Mechanics | topic=Projectile Motion
def check_norm_6a53a330d8e26e2d_d1332efedac2(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及抛体运动且存在显著高度差（Elevation difference）
    trigger_keywords = ['projectile', 'launch', 'height', 'elevation', 'cliff', 'ground', '抛体', '高度', '悬崖', '落地点']
    combined_text = (question + context).lower()
    is_projectile = any(kw in combined_text for kw in ['projectile', 'motion', '抛体', '斜抛'])
    has_height_diff = any(kw in combined_text for kw in ['height', 'h =', 'h=', 'elevation', 'diff', '高度', '落差'])

    if not (is_projectile and has_height_diff):
        return {'result': 'inconclusive', 'message': '未检测到非等高抛体运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 禁止直接套用等高射程公式 R = (v^2 sin 2θ)/g
    # 匹配常见的等高射程公式变体
    forbidden_pattern = r'v\^2.*sin\(2.*theta\)/g|v\^2.*sin\(2.*θ\)/g|sin\(2.*\).*\/.*g'
    if re.search(forbidden_pattern, prediction, re.IGNORECASE):
        # 如果在有高度差的情况下直接使用了等高公式，判定为建模错误
        return {'result': 'fail', 'message': '在非等高抛体运动中错误套用了等高射程公式 R = (v^2 sin 2θ)/g', 'evidence': re.search(forbidden_pattern, prediction, re.IGNORECASE).group()}

    # Step 3: 检查是否建立了正确的运动学方程 (y = v_y*t - 0.5gt^2 = -h 或类似)
    # 检查是否包含时间 t 的二次方程求解逻辑
    pred_lower = prediction.lower()
    has_y_eq = any(x in pred_lower for x in ['1/2', '0.5', 'gt^2', 'g*t^2'])
    has_x_eq = any(x in pred_lower for x in ['v*cos', 'v_x', 'vx'])

    if has_y_eq and has_x_eq:
        # 进一步检查是否包含根号项（通常出现在非等高位移解时间的过程中）
        if 'sqrt' in pred_lower or '√' in pred_lower:
            return {'result': 'pass', 'message': '正确使用了分步运动学方程求解非等高抛体射程', 'evidence': '检测到 y 方向位移方程及时间求解逻辑'}

    # Step 4: 符号覆盖检查 (g, h, v, theta)
    required_symbols = ['g', 'h', 'v']
    missing_symbols = [s for s in required_symbols if s not in pred_lower]
    if len(missing_symbols) > 1:
        return {'result': 'inconclusive', 'message': '推理过程中缺失关键物理量符号', 'evidence': f'缺失: {missing_symbols}'}

    return {'result': 'inconclusive', 'message': '无法确定是否严格遵循了非等高校验逻辑', 'evidence': ''}

# rule_id=norm_769f7326f2e6e42a | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_769f7326f2e6e42a | domain=Mechanics | topic=Projectile Motion
def check_norm_769f7326f2e6e42a_10f6025d5543(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及抛体运动及能量/高度/位移计算
    trigger_keywords = ['projectile', '抛体', '斜抛', '平抛', 'kinetic energy', '动能', 'potential energy', '势能']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到抛体运动或能量转换场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证 prediction 是否包含动能与势能(mgh)的量级比较
    pred = prediction.lower()
    # 检查是否提到了动能(E/K/Ek)和重力势能(mgh/U/Ep)
    has_energy = re.search(r'(1/2|0\.5)\s*\*?\s*m\s*\*?\s*v\^2|mgh|kinetic|potential', pred)
    if not has_energy:
        return {'result': 'inconclusive', 'message': '推理过程中未显式进行能量量级评估', 'evidence': ''}

    # Step 3: 符号与公式校验 — 检查是否满足 E_min > mgh 的基本物理约束
    # 提取可能的数值或符号表达式进行逻辑一致性判断
    # 寻找类似 E < mgh 或 动能小于势能但物体到达了该高度的逻辑矛盾
    if re.search(r'mgh\s*>\s*(E|K|Ek)', pred) or re.search(r'potential\s+energy\s+greater\s+than\s+kinetic', pred):
        # 如果推理中承认势能大于总动能却认为能到达该点，则判定为逻辑错误
        if 'reach' in pred or 'arrive' in pred or '到达' in pred:
            return {'result': 'fail', 'message': '动能不足以克服重力势能，违反能量守恒量级常识', 'evidence': prediction[:200]}

    # 检查 canonical 提示中的复杂不等式结构 (简化匹配)
    if re.search(r'mgh\s*\+\s*.*g.*L\^2', pred):
        return {'result': 'pass', 'message': '已执行复杂的能量与位移一致性校验', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定能量量级校验是否准确执行', 'evidence': ''}

# rule_id=norm_88a46837ce8e6766 | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_88a46837ce8e6766 | domain=Mechanics | topic=Projectile Motion
def check_norm_88a46837ce8e6766_138beb4b2314(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否出现周期性运动描述（如相同位置、反弹高度相等、周期性碰撞）
    trigger_keywords = ['每次落在相同位置', '反弹高度相等', '周期性', '重复运动', 'bounce back', 'same height', 'periodic']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到周期性碰撞或稳态运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否建立了跨周期的位移补偿方程，而非简单的自由落体公式
    # 重点检查是否包含初速度 v_y_after (或 v0) 与 重力加速度 g 结合的位移公式
    pred = prediction.lower()
    # 匹配类似 v*t + 0.5*g*t^2 或 v*t - 1/2*g*t^2 的结构
    displacement_pattern = r'v.*[\*\s]t.*[\+\-]\s*(0\.5|1/2).*g.*t\^2'

    # 检查是否包含必要的物理量符号
    required_symbols = ['v', 't', 'g']
    has_symbols = all(sym in pred for sym in required_symbols)

    # Step 3: 判定结果
    if re.search(displacement_pattern, pred) or (has_symbols and ('=' in pred)):
        # 进一步检查是否考虑了位移补偿（即方程等号另一侧有位移 L 或 h）
        if re.search(r'=\s*[LhH]', pred) or '位移' in pred or 'displacement' in pred:
            return {'result': 'pass', 'message': '已建立跨周期位移补偿方程', 'evidence': re.search(displacement_pattern, pred).group(0) if re.search(displacement_pattern, pred) else 'found symbols and equation'}
        else:
            return {'result': 'inconclusive', 'message': '检测到公式但无法确认是否用于位移补偿', 'evidence': pred[:100]}

    # 如果只用了简单的自由落体 h = 0.5gt^2 而忽略了反弹初速，则视为建模错误
    if re.search(r'0\.5\s*\*\s*g\s*\*\s*t\^2', pred) and not ('v' in pred and 't' in pred):
        return {'result': 'fail', 'message': '模型简化过度，未考虑反弹初速导致的位移补偿', 'evidence': 'prediction uses simple free fall instead of v*t + 0.5gt^2'}

    return {'result': 'inconclusive', 'message': '未发现明确的位移补偿建模过程', 'evidence': ''}

# rule_id=norm_a4600ee28f7f40ee | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_a4600ee28f7f40ee | domain=Mechanics | topic=Projectile Motion
def check_norm_a4600ee28f7f40ee_04a05f25ceb7(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及圆轨道脱离并再次进入的抛体运动场景
    trigger_keywords = ['圆轨道', '脱离', '离开', '抛体', '再进入', '切向', 'circular orbit', 'tangential', 'projectile']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到圆轨道脱离与再进入的物理场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否提及对称性或 A、B 两点的高度/位置关系
    pred = prediction.lower()
    # 检查是否讨论了对称性或高度一致性
    symmetry_keywords = ['对称', '高度相同', '等高', 'symmetry', 'same height', 'vertical axis']
    has_symmetry_logic = any(kw in pred for kw in symmetry_keywords)

    # 检查是否包含抛体运动的基本位移公式要素 (x_B - x_A 或 v*cos*t)
    has_projectile_eq = re.search(r'v.*cos|v.*sin|1/2.*g.*t\^2|g.*t', pred)

    if not has_symmetry_logic and not has_projectile_eq:
        return {'result': 'fail', 'message': '模型未分析脱离点与进入点的对称性或抛体运动位移约束', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查 symbolic_hint 中要求的关键符号
    required_symbols = ['t', 'theta', 'v_A']
    # 允许 theta 以 θ 或角度形式出现
    missing_symbols = []
    for sym in required_symbols:
        if sym == 'theta':
            if 'theta' not in pred and 'θ' not in pred and 'angle' not in pred:
                missing_symbols.append(sym)
        elif sym not in pred:
            missing_symbols.append(sym)

    if len(missing_symbols) > 1:
        return {'result': 'fail', 'message': f'缺少关键物理量符号: {missing_symbols}', 'evidence': prediction[:200]}

    # 检查位移与速度方向的关联性（如 v_A * cos(theta) * t）
    if re.search(r'v.*cos.*t', pred) or re.search(r'v.*sin.*t', pred):
        return {'result': 'pass', 'message': '模型正确应用了对称性及抛体运动位移公式进行校验', 'evidence': '检测到位移与速度分量的关联公式'}

    return {'result': 'inconclusive', 'message': '逻辑存在但公式表达不完整，无法确定准确性', 'evidence': prediction[:200]}

# rule_id=norm_b332eeff107ee8c5 | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_b332eeff107ee8c5 | domain=Mechanics | topic=Projectile Motion
def check_norm_b332eeff107ee8c5_dbafe76f00ab(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及活塞推水、小孔喷流及外部轨迹
    trigger_keywords = ['活塞', '小孔', '喷出', '水流', 'piston', 'orifice', 'jet']
    trajectory_keywords = ['轨迹', '射程', '落地', '位移', 'range', 'trajectory']
    combined_text = (question + context).lower()
    if not any(k in combined_text for k in trigger_keywords) or not any(k in combined_text for k in trajectory_keywords):
        return {'result': 'inconclusive', 'message': '未检测到活塞喷流及轨迹计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否利用连续性方程 A1v1=A2v2 确定出口速度
    pred = prediction.lower()
    # 匹配 A*v = a*v 或 v_exit = (A/a)*v_piston 相关的逻辑
    continuity_pattern = r'(a[12]?v[12]?\s*=\s*a[12]?v[12]?|v\s*=\s*\(?[as]/[as]\)?\s*\*?\s*v|s[12]v[12])'
    has_continuity = re.search(continuity_pattern, pred) or ('面积' in pred and '速度' in pred)

    if not has_continuity:
        return {'result': 'fail', 'message': '未发现利用连续性方程计算出口初速度的逻辑', 'evidence': prediction[:200]}

    # Step 3: 检查逻辑 — 是否切换至质点动力学（抛体公式）并避免时间混淆
    # 检查是否使用了平抛/斜抛的时间公式 t = sqrt(2h/g)
    projectile_pattern = r'(sqrt\(2h/g\)|1/2\s*g\s*t\^2|v_?x\s*\*\s*t)'
    has_projectile = re.search(projectile_pattern, pred) or ('平抛' in pred or '抛体' in pred)

    if not has_projectile:
        return {'result': 'fail', 'message': '未检测到正确的抛体运动学解耦计算', 'evidence': prediction[:200]}

    # 检查是否混淆了活塞运动时间与液滴飞行时间（若提到活塞位移/L与液滴射程/x的关系，需警惕）
    if 'l/v' in pred and 'x/v' in pred and re.search(r't\s*=\s*l/v', pred) and 'sqrt' not in pred:
        return {'result': 'fail', 'message': '疑似混淆了活塞行程时间与液滴飞行时间', 'evidence': prediction[:200]}

    # Step 4: 符号覆盖检查 (A, v)
    if 'a' in pred and 'v' in pred:
        return {'result': 'pass', 'message': '逻辑完整：包含连续性方程推导及运动学解耦', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑要素不全，无法判定', 'evidence': ''}

# rule_id=norm_c4ba4c41375a4bdf | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_c4ba4c41375a4bdf | domain=Mechanics | topic=Projectile Motion
def check_norm_c4ba4c41375a4bdf_a8e26c720e57(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及抛体运动且存在高度差 (h_start != h_end)
    # 关键词：抛体、斜抛、射程、高度差、从...高度、落到...、h1/h2
    trigger_keywords = ['抛', 'projectile', 'range', '射程', '高度差', 'height difference', 'h_start', 'h_end']
    combined_text = (question + context).lower()
    is_projectile = any(kw in combined_text for kw in ['抛', 'projectile', 'trajectory'])
    has_height_diff = any(kw in combined_text for kw in ['高度', 'height', 'h=', 'y0', 'y_0', 'diff'])

    if not (is_projectile and has_height_diff):
        return {'result': 'inconclusive', 'message': '未检测到非等高抛体运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否错误套用了等高射程公式 R = (v^2 sin2θ)/g
    # 如果 prediction 中直接使用了 sin(2*theta) 或 2*sin*cos 且没有考虑高度 h，则判定为 modeling 错误
    pred = prediction.lower()
    wrong_formula_pattern = r'v\^2.*?sin\(2.*?\)/g|v_0\^2.*?sin\(2.*?\)/g'
    if re.search(wrong_formula_pattern, pred) and not re.search(r'[Hh]|sqrt', pred):
        return {'result': 'fail', 'message': '错误套用了等高抛体射程公式，未考虑高度差', 'evidence': re.search(wrong_formula_pattern, pred).group()}

    # Step 3: 符号/公式校验 — 检查是否建立了包含 g, h, v0 的轨迹方程或最大射程公式
    # 目标公式特征：包含 v0, g, h 且通常涉及平方根或二次方程求解
    required_symbols = ['g', 'h', 'v']
    symbol_count = sum(1 for sym in required_symbols if sym in pred)

    # 检查是否包含轨迹方程或包络线/最大射程的复杂结构
    correct_structure = re.search(r'sqrt\(.*v.*\^2.*\+.*2gh.*\)', pred) or re.search(r'x.*?=.*?v.*?/g.*?sqrt', pred)

    if correct_structure:
        return {'result': 'pass', 'message': '正确使用了包含高度差的射程计算逻辑', 'evidence': '检测到符合要求的公式结构'}

    if symbol_count >= 2 and ('sin' in pred or 'cos' in pred):
        # 如果有基本变量但没匹配到完整公式，保守返回 inconclusive
        return {'result': 'inconclusive', 'message': '检测到相关物理量但公式结构不完整', 'evidence': pred[:100]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了非等高射程', 'evidence': ''}

# rule_id=norm_c952b30ecfa394be | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_c952b30ecfa394be | domain=Mechanics | topic=Projectile Motion
def check_norm_c952b30ecfa394be_8c851426d6f2(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“均匀分布”且与喷射角度/喷淋相关
    trigger_keywords = ['uniformly distributed', '均匀分布', '喷射', 'spray', 'angle', '角度']
    q_c_text = (question + context).lower()
    if not (('uniformly' in q_c_text or '均匀' in q_c_text) and any(k in q_c_text for k in ['angle', '角度', 'spray', '喷'])):
        return {'result': 'inconclusive', 'message': '题目未明确涉及均匀喷淋分布场景', 'evidence': ''}

    # Step 2: 检查建模逻辑 — 是否建立了源分布与目标区域的通量守恒关系
    # 核心逻辑：n(theta) dOmega = sigma dA 或类似的微分等量关系
    pred_text = prediction.lower()
    flux_patterns = [
        r'n\(\s*theta\s*\)', r'd\s*theta', r'sin\s*theta',
        r'2\s*pi', r'sigma', r'rho', r'density',
        r'dx', r'da', r'area'
    ]

    # 检查是否包含通量守恒的建模尝试（寻找微分项或密度项）
    match_count = sum(1 for p in flux_patterns if re.search(p, pred_text))

    # Step 3: 符号与公式结构校验
    # 必须包含 n(theta), x(theta) 和 密度符号 sigma/rho 之一
    required_symbols = ['n', 'x', 'theta']
    symbol_check = all(re.search(rf'[{s}]', pred_text) for s in required_symbols)

    # 检查关键的微分等式结构 (n * sin theta d theta = sigma * x dx)
    has_diff_eq = re.search(r'n.*sin.*d.*theta.*=.*x.*d.*x', pred_text.replace(' ', '')) or \
                  re.search(r'd\s*a.*=.*d\s*a', pred_text) or \
                  re.search(r'flux', pred_text)

    if not symbol_check:
        return {'result': 'fail', 'message': '建模缺失必要物理量符号 (n(θ), x(θ) 或密度)', 'evidence': prediction[:200]}

    if not has_diff_eq and match_count < 4:
        return {'result': 'fail', 'message': '未建立源分布密度与目标区域面积的通量守恒关系', 'evidence': prediction[:200]}

    if has_diff_eq or match_count >= 6:
        return {'result': 'pass', 'message': '已建立均匀性建模的通量守恒关系', 'evidence': '检测到微分等量关系或高频物理建模词汇'}

    return {'result': 'inconclusive', 'message': '检测到部分建模尝试，但逻辑完整性不足以判定', 'evidence': ''}

# rule_id=norm_d131000b4a7a888b | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_d131000b4a7a888b | domain=Mechanics | topic=Projectile Motion
def check_norm_d131000b4a7a888b_8e021df6ab4f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否明确提示不能忽略球体尺寸
    trigger_keywords = ['neglecting the size', 'no longer be possible', 'size of the ball', 'radius', 'diameter']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '题目未明确提示需考虑物体尺寸', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否在位移或碰撞点计算中考虑了半径 r
    # 重点检查是否出现了 L-r, L+r, d-r 等修正项，而非直接使用 L 或错误减去直径 2r
    pred = prediction.lower()
    # 匹配常见的修正形式：变量 [+-] 半径
    correction_pattern = r'([a-zA-Z_]\w*\s*[\+\-]\s*[rR])|([rR]\s*[\+\-]\s*[a-zA-Z_]\w*)'
    has_correction = re.search(correction_pattern, pred)

    # 检查是否错误地使用了直径 (2r 或 d)
    has_diameter_error = re.search(r'[\+\-]\s*2\s*[rR]|[\+\-]\s*[dD](?!_)', pred)

    # Step 3: 符号覆盖检查 (d_wall, r_ball)
    required_symbols = ['r', 'd']
    symbol_count = sum(1 for sym in required_symbols if sym in pred)

    if has_correction:
        return {'result': 'pass', 'message': '模型正确执行了半径修正逻辑', 'evidence': re.search(correction_pattern, pred).group()}

    if has_diameter_error:
        return {'result': 'fail', 'message': '模型错误地使用了直径而非半径进行修正', 'evidence': '检测到直径修正项'}

    # 如果明确提到了尺寸但计算公式中完全没有半径参与加减运算
    if 'r' in pred and not has_correction:
        return {'result': 'fail', 'message': '模型虽提及半径但未在位移计算中进行修正', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了尺寸修正', 'evidence': ''}

# rule_id=norm_e41949981804df90 | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_e41949981804df90 | domain=Mechanics | topic=Projectile Motion
def check_norm_e41949981804df90_0058eedef6c3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“最小初速度”及目标点坐标场景
    q_c = (question + context).lower()
    if not (('最小' in q_c or 'minimum' in q_c) and ('初速度' in q_c or 'initial velocity' in q_c)):
        return {'result': 'inconclusive', 'message': '未检测到最小初速度求解场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否使用了轨迹方程或判别式方法
    pred = prediction.lower()
    # 检查是否提到判别式 (discriminant / Delta) 或 轨迹方程 (trajectory equation)
    has_method = any(kw in pred for kw in ['判别式', 'discriminant', 'delta', '轨迹方程', 'trajectory equation', 'tan'])
    if not has_method:
        return {'result': 'fail', 'message': '未体现利用轨迹方程或判别式求解极值的逻辑', 'evidence': prediction[:200]}

    # Step 3: 公式校验 — 检查 canonical 形式的最小速度公式结构
    # v_min = sqrt(g(H + sqrt(L^2 + H^2)))
    # 匹配特征：sqrt, g, H, L 的组合，以及平方根嵌套
    formula_pattern = r'sqrt\(.*g.*[HL].*sqrt\(.*[HL].*2.*[HL].*2.*\)'
    # 简化匹配：检查是否包含关键的根号下 H + sqrt(L^2+H^2) 结构
    if re.search(r'g.*\(.*[Hh].*sqrt\(.*[Ll].*2.*[Hh].*2.*\)', pred) or \
       re.search(r'v_\{?min\}?', pred) or \
       re.search(r'\\Delta\s*[>=]\s*0', pred):
        return {'result': 'pass', 'message': '逻辑符合轨迹方程判别式求极值方法', 'evidence': re.search(r'.{0,50}(Delta|sqrt|v_min).{0,50}', pred).group(0) if re.search(r'(Delta|sqrt|v_min)', pred) else 'Found logic'}

    return {'result': 'inconclusive', 'message': '推理步骤中未发现明确的判别式计算公式', 'evidence': prediction[-150:]}

# rule_id=norm_ec394bbe1f1ce6f5 | domain=Mechanics | topic=Projectile Motion
# rule_id=norm_ec394bbe1f1ce6f5 | domain=Mechanics | topic=Projectile Motion
def check_norm_ec394bbe1f1ce6f5_3d9c6378cd30(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否为从高处抛向低处的斜抛运动并求最大射程
    q_text = (question + context).lower()
    is_projectile = any(kw in q_text for kw in ['projectile', '斜抛', '抛出', '抛体'])
    is_height_diff = any(kw in q_text for kw in ['高处', '落至', '高度差', 'h', 'height', 'delta h'])
    is_max_range = any(kw in q_text for kw in ['最大射程', '最大水平距离', 'maximum range', 'max horizontal distance'])

    if not (is_projectile and is_max_range):
        return {'result': 'inconclusive', 'message': '未检测到非等高斜抛最大射程场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否误用了 45 度角或简单的平抛模型
    pred = prediction.lower()
    # 如果直接断言 45 度是最大射程的条件，在有高度差的情况下通常是错误的
    if re.search(r'45\s*(deg|度|°)', pred) and ('height' in q_text or 'h' in q_text):
        if not re.search(r'tan|cos|sin|sqrt', pred):
            return {'result': 'fail', 'message': '在有高度差的情况下误用45度角作为最大射程条件', 'evidence': prediction[:200]}

    # Step 3: 公式结构校验 — 检查是否包含 v0, g, h 等关键符号及最大射程的正确结构
    # 目标公式: x_max = (v_0/g) * sqrt(v_0^2 + 2gΔh)
    required_symbols = ['v', 'g', 'h']
    missing_symbols = [s for s in required_symbols if s not in pred]

    # 检查公式特征：sqrt(v^2 + 2gh) 或类似的能量/运动学组合
    has_correct_structure = re.search(r'sqrt\(.*v.*2.*2.*g.*h.*\)', pred) or \
                            re.search(r'v.*/.*g.*sqrt\(', pred)

    if has_correct_structure:
        return {'result': 'pass', 'message': '检测到正确的非等高斜抛最大射程公式结构', 'evidence': prediction[:200]}

    if len(missing_symbols) >= 2:
        return {'result': 'fail', 'message': '缺失关键物理量符号(v, g, h)或计算逻辑不完整', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定推导是否完全符合非等高斜抛模型', 'evidence': ''}

# rule_id=norm_11be185ffa25db7c | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_11be185ffa25db7c | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_11be185ffa25db7c_8a6db7b3507c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及绳索张力、重力分量及圆周运动场景
    trigger_keywords = ['绳', '张力', 'tension', 'circular', '圆周', '摆', 'pendulum']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到圆周运动或张力相关场景', 'evidence': ''}
    if 'g' not in combined_text and '重力' not in combined_text:
        return {'result': 'inconclusive', 'message': '未检测到重力参与受力分析', 'evidence': ''}

    # Step 2: 检查推理过程中是否包含向心力方程的核心要素
    # 必须包含 T, m, v, R/L 以及 g 的组合
    pred = prediction.lower()
    required_patterns = [r'[Tt]', r'[Mm]', r'[Vv]', r'[RrLl]', r'[Gg]']
    if not all(re.search(p, pred) for p in required_patterns):
        return {'result': 'fail', 'message': '推理过程中缺失必要的物理量符号(T, m, v, R, g)', 'evidence': prediction[:200]}

    # Step 3: 检查径向受力方程的符号逻辑
    # 核心逻辑：T 与 mg cos(theta) 的加减关系应对应向心力 mv^2/R
    # 匹配 T - mg... = mv^2/R 或 T + mg... = mv^2/R 结构
    # 考虑到 LaTeX 格式，匹配 T, m, g, cos/sin, v^2, R/L
    centripetal_eq_pattern = r'([Tt]\s*[\+\-]\s*[Mm][Gg].*?)\s*=\s*([Mm][Vv]\^2\s*/\s*[RrLl])'
    match = re.search(centripetal_eq_pattern, prediction)

    if not match:
        # 如果没找到标准方程，尝试寻找 T = ... 的变形
        alt_pattern = r'[Tt]\s*=\s*([Mm][Vv]\^2\s*/\s*[RrLl]\s*[\+\-]\s*[Mm][Gg].*?)'
        match = re.search(alt_pattern, prediction)

    if match:
        eq_part = match.group(0)
        # 检查符号逻辑：通常在最低点 T - mg = mv^2/R，最高点 T + mg = mv^2/R
        # 若 prediction 中出现了 mg 但没有正确的加减逻辑，则可能存在逻辑错误
        if 'cos' in eq_part or 'sin' in eq_part or 'mg' in eq_part:
            return {'result': 'pass', 'message': '检测到符合逻辑的径向受力方程', 'evidence': eq_part}
        else:
            return {'result': 'inconclusive', 'message': '方程结构存在但分量表达不清晰', 'evidence': eq_part}

    # 如果明确在做受力分析但没有写出正确的向心力方程结构
    if '向心力' in pred or 'centripetal' in pred:
        return {'result': 'fail', 'message': '未发现正确的径向受力平衡方程 T ± G_radial = mv²/R', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足，无法判定受力方程准确性', 'evidence': ''}

# rule_id=norm_129cad0de7cb742a | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_129cad0de7cb742a | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_129cad0de7cb742a_76c4545643ba(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及几何曲线（如椭圆、圆）约束下的最值问题
    trigger_keywords = ['最值', '最大值', '最小值', 'maximum', 'minimum', '约束', 'constraint']
    geometry_keywords = ['椭圆', 'ellipse', '圆', 'circle', 'x^2', 'y^2', 'a^2', 'b^2']

    full_text = (question + context).lower()
    is_triggered = any(k in full_text for k in trigger_keywords) and any(k in full_text for k in geometry_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到几何约束最值场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 校验 prediction 是否讨论了边界方程 (x^2/a^2 + y^2/b^2 = 1)
    # 匹配常见的椭圆或圆的方程形式
    constraint_pattern = r'(x\^2|x\*\*2).*(y\^2|y\*\*2).*=.*1|x\^2/a\^2.*y\^2/b\^2.*=.*1'
    pred_lower = prediction.lower()

    has_constraint = re.search(constraint_pattern, pred_lower) or ('=' in pred_lower and ('x' in pred_lower and 'y' in pred_lower))

    if not has_constraint:
        return {'result': 'fail', 'message': '未在推理中明确体现约束方程或边界条件', 'evidence': prediction[:200]}

    # Step 3: 符号校验 — 检查是否包含必要的符号 a, b, x, y 且逻辑闭合
    required_symbols = ['x', 'y', 'a', 'b']
    missing_symbols = [s for s in required_symbols if s not in pred_lower]

    # 如果是椭圆约束但完全没提到参数 a 或 b，且没有代入具体数值，则视为建模不严谨
    if len(missing_symbols) >= 2 and not re.search(r'\d+', pred_lower):
        return {'result': 'fail', 'message': '缺少必要的约束参数符号或数值代入', 'evidence': prediction[:150]}

    # 如果提到了约束且有最值讨论，初步判定为 pass
    if 'max' in pred_lower or 'min' in pred_lower or '最' in pred_lower:
        return {'result': 'pass', 'message': '已包含约束方程及最值点讨论', 'evidence': re.search(r'.{0,50}(max|min|最).{0,50}', pred_lower).group(0) if re.search(r'(max|min|最)', pred_lower) else ''}

    return {'result': 'inconclusive', 'message': '无法确定最值点是否严格满足边界约束', 'evidence': ''}

# rule_id=norm_1b4f35371e9eae4f | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_1b4f35371e9eae4f | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_1b4f35371e9eae4f_0b1674877c80(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及投弹后的最远逃逸距离或冲击波规避场景
    trigger_keywords = ['投弹', '逃逸', '冲击波', '爆炸', 'bomb', 'escape', 'shock wave']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到投弹逃逸相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找圆弧转弯（Circular Turn）与直线切线（Tangent）的结合
    pred = prediction.lower()
    # 检查是否提到转弯、圆弧或向心力相关的运动描述
    has_turn = any(kw in pred for kw in ['转弯', '圆弧', '半径', '向心', 'turn', 'arc', 'radius', 'centripetal'])
    # 检查是否提到切线或直线逃离
    has_tangent = any(kw in pred for kw in ['切线', '直线', 'tangent', 'straight line'])

    if not (has_turn and has_tangent):
        return {
            'result': 'fail',
            'message': '推理过程中缺失关键的“圆弧转弯后接直线切线”的逃逸路径优化逻辑',
            'evidence': prediction[:200]
        }

    # Step 3: 检查时空最优解的描述（如轨迹与波前的关系）
    # 寻找是否讨论了速度矢量、时间或距离的最优性
    if re.search(r'(最远|最大|最优|距离|时间|优化)', pred) and re.search(r'(波前|冲击波|爆炸)', pred):
        return {
            'result': 'pass',
            'message': '模型正确识别了通过圆弧转弯接切线寻找逃逸最优解的逻辑',
            'evidence': re.findall(r'.{0,30}(?:切线|圆弧|转弯).{0,30}', pred)[:2]
        }

    return {'result': 'inconclusive', 'message': '逻辑要素不完整，无法判定', 'evidence': ''}

# rule_id=norm_2a54bbbef13400ae | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_2a54bbbef13400ae | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_2a54bbbef13400ae_46ca38b0cc90(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否同时出现“恒定高度”与“过载/升力比”相关描述
    trigger_keywords = ['constant altitude', 'level turn', '恒定高度', '水平转弯']
    load_keywords = ['lift-to-weight', 'load factor', '过载', 'n =', 'n=']

    q_c_text = (question + context).lower()
    has_altitude = any(k in q_c_text for k in trigger_keywords)
    has_load = any(k in q_c_text for k in load_keywords)

    if not (has_altitude and has_load):
        return {'result': 'inconclusive', 'message': '未检测到恒定高度转弯及过载约束场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否考虑了垂直方向平衡 L*cos(phi)=mg 和水平向心力
    pred = prediction.lower()
    # 检查是否提到了升力的垂直分量或余弦关系
    vertical_balance = re.search(r'l.*cos|mg/l|l.*sin.*v\^2', pred)
    # 检查是否提到了向心力与过载的关系
    centripetal_logic = re.search(r'v\^2\s*/\s*r|g.*tan|sqrt\(n\^2\s*-\s*1\)', pred)

    if not (vertical_balance or centripetal_logic):
        return {'result': 'fail', 'message': '未体现恒定高度转弯时的受力平衡逻辑（L*cos(phi)=mg）', 'evidence': prediction[:200]}

    # Step 3: 公式校验 — 检查核心公式 R = v^2 / (g * sqrt(n^2 - 1)) 的结构
    # 匹配 sqrt(n^2 - 1) 或类似的向心加速度表达式
    formula_pattern = r'sqrt\(\s*n\s*\^?\s*2\s*-\s*1\s*\)'
    if re.search(formula_pattern, pred):
        return {'result': 'pass', 'message': '检测到正确的过载与半径/加速度关系公式', 'evidence': re.search(formula_pattern, pred).group()}

    # 如果有计算过程但公式结构明显错误（如直接用 n 而非 sqrt(n^2-1)）
    if re.search(r'r\s*=\s*v\^2\s*/\s*\(\s*g\s*\*\s*n\s*\)', pred):
        return {'result': 'fail', 'message': '半径计算公式错误，未考虑垂直方向重力平衡导致的过载分量', 'evidence': 'r = v^2 / (g * n)'}

    return {'result': 'inconclusive', 'message': '逻辑存在但公式特征不明显', 'evidence': prediction[:150]}

# rule_id=norm_2aec080d60587adf | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_2aec080d60587adf | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_2aec080d60587adf_6d55d6e71931(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否包含“始终保持静止”、“固定在地面”或“不离开”等约束描述
    trigger_keywords = ['始终保持', '静止', '固定', '接触地面', '不离开', '不脱离', 'remain stationary', 'fixed']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到物体需保持静止或固定的约束条件', 'evidence': ''}

    # Step 2: 检查逻辑 — 在约束生效期间，是否错误地对该物体应用了动量守恒（赋予了速度变量）
    # 寻找动量守恒公式特征，如 m1v1 + m2v2 = ... 或 mv = (M+m)V
    momentum_pattern = r'm[12]?v[12]?\s*\+\s*m[12]?v[12]?\s*='
    conservation_keywords = ['动量守恒', 'momentum conservation', 'conservation of momentum']

    pred_lower = prediction.lower()
    has_momentum_logic = any(kw in pred_lower for kw in conservation_keywords) or re.search(momentum_pattern, pred_lower)

    # 如果题目明确要求物体静止（如固定底座），但解题过程中给该物体分配了速度变量并列出动量守恒，则判定为逻辑错误
    if has_momentum_logic:
        # 进一步检查是否给本应静止的物体（通常是较大的 M 或 ground）分配了非零速度
        if re.search(r'[MV]\s*=\s*[^0\s]', pred_lower) and ('固定' in question or 'fixed' in question):
            return {
                'result': 'fail',
                'message': '物体受静止约束（如固定）时，不应应用动量守恒或赋予其速度变量',
                'evidence': re.search(r'.{0,50}(动量守恒|momentum).{0,50}', pred_lower).group(0) if re.search(r'(动量守恒|momentum)', pred_lower) else prediction[:100]
            }

    # Step 3: 验证是否正确识别了静止参考系
    if 'v=0' in pred_lower.replace(' ', '') or '速度为0' in pred_lower:
        return {'result': 'pass', 'message': '正确处理了静止约束条件', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '无法确定是否误用动量守恒', 'evidence': ''}

# rule_id=norm_591a1674149529b7 | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_591a1674149529b7 | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_591a1674149529b7_edf7ad3beda8(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“零原长”弹簧 (zero relaxed/natural length)
    trigger_keywords = ['zero relaxed length', 'zero natural length', '原长为0', '零原长']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到零原长弹簧相关描述', 'evidence': ''}

    # Step 2: 检查逻辑 — 判定弹簧力矢量方向是否指向固定点/原点
    # 零原长弹簧力 F = -k(r - 0) = -kr，方向必须沿径向指向原点
    pred_lower = prediction.lower()

    # 检查是否错误地描述为切向力或局部坐标轴分量（常见错误建模）
    wrong_indicators = ['tangential', 'along the tangent', '切线方向', 'perpendicular to the radius']
    correct_indicators = ['towards the origin', 'towards the fixed point', 'along the radius', '指向原点', '指向固定点', '径向']

    # Step 3: 符号与公式校验 (F = -kr)
    formula_match = re.search(r'F\s*=\s*-?\s*k\s*\*?\s*r', prediction, re.IGNORECASE) or \
                    re.search(r'\\vec{F}\s*=\s*-?\s*k\s*\\vec{r}', prediction)

    # 判定逻辑
    if any(wi in pred_lower for wi in wrong_indicators):
        return {
            'result': 'fail',
            'message': '零原长弹簧力应指向固定点，而非沿切线或错误方向',
            'evidence': next((wi for wi in wrong_indicators if wi in pred_lower), '')
        }

    if formula_match or any(ci in pred_lower for ci in correct_indicators):
        return {
            'result': 'pass',
            'message': '正确识别零原长弹簧受力方向指向固定点',
            'evidence': formula_match.group(0) if formula_match else 'detected correct direction description'
        }

    return {'result': 'inconclusive', 'message': '预测中未明确说明弹簧力方向或公式', 'evidence': ''}

# rule_id=norm_59673b67b49ab0dd | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_59673b67b49ab0dd | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_59673b67b49ab0dd_e2f54b7d8d60(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及圆周运动脱离及落点半径计算
    trigger_keywords = ['圆弧', '脱离', '离开', '落点', '水平距离', '半径', 'circular', 'leave', 'detach']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到圆周脱离及落点计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否建立了 R_total = R*sinθ + Δx 的位移模型
    # 重点检查是否包含脱离点的水平投影 R*sinθ (或 R*cosθ 取决于角度定义) 以及平抛位移 v*t
    pred = prediction.lower()

    # 检查是否考虑了脱离点的初始水平位置 (R sin theta)
    has_initial_proj = re.search(r'r\s*(\*|\s)?\s*(sin|cos)', pred) or 'r_0' in pred
    # 检查是否考虑了后续平抛的水平位移 (v * t)
    has_projectile_dist = re.search(r'v\s*(\*|\s)?\s*(cos|sin)?\s*(\*|\s)?\s*t', pred) or 'v_x' in pred

    if not (has_initial_proj or has_projectile_dist):
        return {'result': 'fail', 'message': '建模缺失：未发现脱离点水平投影或后续平抛位移的计算逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号与公式结构校验
    # 匹配 canonical: R_total = R sinθ + v cosθ * t (或类似结构)
    # 允许 sin/cos 互换（取决于 theta 是与竖直还是水平的夹角）
    formula_pattern = r'r.*(sin|cos).*\+.*v.*(cos|sin).*t'
    if re.search(formula_pattern, pred.replace(' ', '')):
        return {'result': 'pass', 'message': '位移建模符合物理规则', 'evidence': re.search(formula_pattern, pred.replace(' ', '')).group()}

    # 如果有相关描述但公式不完整，返回 inconclusive
    if 'sin' in pred and 'v' in pred and 't' in pred:
        return {'result': 'inconclusive', 'message': '检测到相关物理量但公式结构不明确', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '证据不足以判定建模正确性', 'evidence': ''}

# rule_id=norm_7590981f1f98693a | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_7590981f1f98693a | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_7590981f1f98693a_5522ec8236d5(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及转动平台上的相对静止条件（ω 或 x）
    trigger_keywords = ['转动', '平台', '圆盘', '相对静止', '不滑动', '角速度', '半径']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到转动平台相对静止场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否讨论了静摩擦力的两个边界（正负最大值或区间）
    # 规则要求讨论 ±μN 或两个临界状态，而非单一等式
    pred_lower = prediction.lower()
    has_max_friction = re.search(r'(\+|\-)?μm?g|最大静摩擦力', pred_lower)
    has_range_logic = re.search(r'区间|范围|边界|临界|\w+min|\w+max|≤|≥', pred_lower)

    if not (has_max_friction and has_range_logic):
        return {
            'result': 'fail',
            'message': '未充分讨论静摩擦力的临界区间或正负最大值边界',
            'evidence': prediction[:200]
        }

    # Step 3: 符号覆盖检查 — 检查关键物理量 T, m, x, μ, ω 的关联性
    # 重点检查是否存在类似 |T - mω^2x| ≤ μmg 的不等式结构或分情况讨论
    required_symbols = ['m', 'ω', 'μ']
    symbol_count = sum(1 for sym in required_symbols if sym in pred_lower or sym in prediction)

    # 如果提到了 T (张力) 和 x (半径)，则进一步验证公式结构
    formula_pattern = re.search(r'mω\^2|μmg|f_s', pred_lower)

    if symbol_count >= 2 and formula_pattern:
        # 检查是否只给出了一个等式（错误倾向）
        if '=' in pred_lower and '≤' not in pred_lower and '≥' not in pred_lower and '范围' not in pred_lower:
            return {
                'result': 'fail',
                'message': '仅给出了单一平衡等式，未体现临界区间判定逻辑',
                'evidence': prediction[:200]
            }
        return {'result': 'pass', 'message': '已包含临界区间讨论及相关物理量', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程中物理量或逻辑链条不完整', 'evidence': ''}

# rule_id=norm_9442944f26725056 | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_9442944f26725056 | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_9442944f26725056_bec406ecc848(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及骑手/物体倾斜角度及转动平衡场景
    trigger_keywords = ['倾斜', '角度', 'theta', 'θ', '平衡', '力矩', 'torque', 'lean']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到倾斜平衡相关的物理场景', 'evidence': ''}
    if '圆周' not in combined_text and '转弯' not in combined_text:
        return {'result': 'inconclusive', 'message': '未检测到圆周运动背景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否正确选择了参考点或引入了惯性力（离心力）
    pred = prediction.lower()
    # 检查是否提到质心(center of mass)或接触点(contact point/ground)
    has_reference_point = any(kw in pred for kw in ['质心', 'center of mass', '接触点', '支点', 'ground', 'contact point'])
    # 检查是否提到惯性力/离心力（随动系特征）
    has_inertial_force = any(kw in pred for kw in ['惯性力', '离心力', 'centrifugal', 'inertial force'])

    if not has_reference_point:
        return {'result': 'fail', 'message': '在处理倾斜平衡时，未明确说明力矩参考点的选择', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查核心平衡方程结构 M*g*L1 = (M*v^2/R)*L2
    # 匹配重力项 M*g 和 向心力/离心力项 v^2/R 或 v^2/(g*R)
    gravity_pattern = r'm.*?g'
    centripetal_pattern = r'v\^2.*?r|v\^2.*?R'

    has_gravity = re.search(gravity_pattern, pred, re.IGNORECASE)
    has_centripetal = re.search(centripetal_pattern, pred, re.IGNORECASE)

    if not (has_gravity and has_centripetal):
        return {'result': 'fail', 'message': '预测中缺失重力矩或向心力/离心力矩的关键物理量表达', 'evidence': prediction[:200]}

    # 如果同时具备参考系意识和核心公式结构，则判定为通过
    if (has_inertial_force or '系' in pred) and (has_gravity and has_centripetal):
        return {'result': 'pass', 'message': '正确应用了参考系选择及对应的力矩平衡方程', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑步骤尚不完整，无法确定正误', 'evidence': ''}

# rule_id=norm_98634271274a0e62 | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_98634271274a0e62 | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_98634271274a0e62_54adf4b216f8(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及单摆绕钉子、绳系圆周运动及最高点场景
    trigger_keywords = ['钉子', '绕钉', '绳', '最高点', '竖直平面', '圆周运动', 'circular motion', 'highest point', 'peg']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到竖直平面绳约束圆周运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否讨论了最高点的临界速度 sqrt(gr) 或 sqrt(g(L-d))
    # 重点检查 prediction 是否错误地认为最高点速度可以为 0，或者忽略了 sqrt(gr) 的约束
    pred = prediction.lower()

    # 匹配 sqrt(gr) 或 sqrt(g(L-d)) 相关的表达式
    critical_velocity_pattern = r'sqrt\(g\s*\*?\s*\(?L\s*-\s*d\)?\)|sqrt\(g\s*\*?\s*r\)|\(g\s*\*?\s*r\)\s*\^\s*0\.5'
    has_critical_v = re.search(critical_velocity_pattern, pred)

    # 检查是否错误地假设最高点速度为 0 (对于绳约束这是错误的)
    zero_velocity_at_top = re.search(r'最高点速度(为|是)0|v\s*=\s*0\s*at\s*the\s*top|velocity\s*is\s*zero\s*at\s*the\s*top', pred)

    if zero_velocity_at_top:
        return {
            'result': 'fail',
            'message': '错误地假设绳约束圆周运动最高点速度为零，未考虑临界速度 sqrt(gr)',
            'evidence': re.search(r'.{0,30}(最高点速度(为|是)0|v\s*=\s*0).{0,30}', pred).group(0) if zero_velocity_at_top else ''
        }

    # Step 3: 符号/公式校验 — 检查是否正确应用了 v >= sqrt(g(L-d))
    if has_critical_v:
        # 如果提到了临界速度且没有明显的零速度错误，初步判定为 pass
        return {'result': 'pass', 'message': '正确识别或应用了最高点临界速度公式', 'evidence': has_critical_v.group(0)}

    # 如果既没有说速度为0，也没有写出明确的临界公式，则证据不足
    return {'result': 'inconclusive', 'message': '未明确检测到对最高点临界速度条件的判定逻辑', 'evidence': ''}

# rule_id=norm_99095c09d52ed7a6 | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_99095c09d52ed7a6 | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_99095c09d52ed7a6_183e50e74a50(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及垂直槽、绳索绕轴约束场景
    trigger_keywords = ['槽', '垂直', '绳', '绕过', '轴', '连接']
    combined_text = (question + context).lower()
    if not all(k in combined_text for k in ['槽', '绳']):
        return {'result': 'inconclusive', 'message': '未检测到垂直槽绳索约束场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否错误使用了勾股定理 (x^2 + y^2 = L^2) 而非线性约束 (x + y = L)
    # 绳索贴合轴心时，各段长度之和应为定值，即 x + y = L
    pred = prediction.lower()

    # 检查是否出现了勾股定理形式的位移约束（错误建模）
    pythagorean_pattern = r'x\^2\s*\+\s*y\^2|\bsqrt\(x\^2\s*\+\s*y\^2\)'
    linear_pattern = r'x\s*\+\s*y\s*=\s*[lL]|x_1\s*\+\s*x_2\s*=\s*[lL]'

    # Step 3: 符号与公式校验
    # 如果预测中使用了勾股定理来描述绳长约束，则判定为建模错误
    if re.search(pythagorean_pattern, pred) and '绳' in pred:
        return {
            'result': 'fail',
            'message': '位移约束建模错误：绳索绕轴约束应为线性长度相加(x+y=L)，而非勾股定理(x^2+y^2=L^2)',
            'evidence': re.search(pythagorean_pattern, pred).group()
        }

    # 如果预测中明确出现了线性约束公式，则判定为 pass
    if re.search(linear_pattern, pred):
        return {
            'result': 'pass',
            'message': '位移约束建模正确，使用了线性长度之和',
            'evidence': re.search(linear_pattern, pred).group()
        }

    return {'result': 'inconclusive', 'message': '未能明确识别位移约束公式类型', 'evidence': ''}

# rule_id=norm_b133ca8bfa86595c | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_b133ca8bfa86595c | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_b133ca8bfa86595c_dd74282da7f2(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否为物体在球面/圆弧外侧下滑脱离的场景
    trigger_keywords = ['球面', '圆弧', '下滑', '脱离', '离开', 'sphere', 'slide off', 'leave']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到球面下滑脱离场景', 'evidence': ''}

    # Step 2: 检查逻辑要素 — 能量守恒与向心力方程的联立
    # 能量守恒: mgR(1-cosθ) = 1/2mv²; 向心力方程: mg cosθ = mv²/R
    pred = prediction.lower()
    has_energy = re.search(r'1/2\s*m\s*v\^?2', pred) or '能量守恒' in pred
    has_centripetal = re.search(r'm\s*v\^?2\s*/\s*r', pred) or '向心力' in pred or 'mg\s*cos' in pred

    if not (has_energy and has_centripetal):
        return {
            'result': 'fail',
            'message': '未体现能量守恒与向心力方程的联立过程',
            'evidence': prediction[:200]
        }

    # Step 3: 符号与数值校验 — 检查临界角 cosθ = 2/3
    # 匹配 cosθ = 2/3 或 0.667
    cos_pattern = r'cos[\s\\{]*\\?theta[\s\\}]*=[\s\\{]*2/3|cos[\s\\{]*\\?theta[\s\\}]*\approx\s*0\.66'
    if re.search(cos_pattern, prediction) or '2/3' in prediction:
        return {
            'result': 'pass',
            'message': '成功验证脱离角临界条件 cosθ = 2/3',
            'evidence': re.search(r'.{0,30}2/3.{0,30}', prediction).group(0) if '2/3' in prediction else ''
        }

    return {'result': 'inconclusive', 'message': '逻辑要素存在但未明确得出 cosθ = 2/3 的结论', 'evidence': prediction[-100:]}

# rule_id=norm_bd2921f9f3b858f5 | domain=Mechanics | topic=Circular Motion and Centripetal Force
# rule_id=norm_bd2921f9f3b858f5 | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_bd2921f9f3b858f5_122f953d344c(sample: dict) -> dict:
    question = sample.get('question', '')
