# rule_id=norm_157e7a66199cb6b0 | domain=Mechanics | topic=Work-Energy Theorem and Conservation of Energy
def check_norm_157e7a66199cb6b0_27bd30998383(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及冲击力作用下“不发生平动”或“静止”的临界判定
    trigger_keywords = ['不发生平动', 'not translate', '保持静止', 'remain stationary', 'no translation']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到不发生平动的临界判定场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找 F <= μMg 或类似的静摩擦力平衡不等式
    # 匹配 F <= mu*M*g 或 F <= f_max 等形式
    pred = prediction.lower()
    # 提取符号特征：F, mu (μ), M, g
    has_f = 'f' in pred
    has_mu = 'mu' in pred or 'μ' in pred
    has_mg = 'mg' in pred or ('m' in pred and 'g' in pred)

    # 检查是否包含不等式逻辑
    inequality_pattern = r'f\s*<=\s*(mu|μ)?\s*m\s*g|f\s*\.?\s*\le\s*(mu|μ)?\s*m\s*g'
    match = re.search(inequality_pattern, pred)

    # Step 3: 判定结果
    if match:
        return {'result': 'pass', 'message': '检测到正确的静摩擦临界平动判定公式', 'evidence': match.group()}

    # 如果明确讨论了平动条件但缺失了核心不等式或符号不全
    if not (has_f and (has_mu or 'friction' in pred)):
        return {'result': 'fail', 'message': '未在推理中体现冲击力与最大静摩擦力的比较逻辑', 'evidence': prediction[:200]}

