# rule_id=norm_30bdd7f560c9f065 | domain=Mechanics | topic=Work-Energy Theorem and Conservation of Energy
# rule_id=norm_30bdd7f560c9f065 | domain=Mechanics | topic=Work-Energy Theorem and Conservation of Energy
def check_norm_30bdd7f560c9f065_4b3b3feca45a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及重力势能、动能定理及坐标轴定义
    trigger_keywords = ['重力', '势能', '动能', 'g', 'height', 'velocity', 'y轴']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到重力势能转换场景', 'evidence': ''}

    # 检查是否涉及坐标轴方向（向上/向下）
    is_y_up = '向上' in (question + context) or '正方向向上' in (question + context)
    is_y_down = '向下' in (question + context) or '正方向向下' in (question + context)
    if not (is_y_up or is_y_down):
        return {'result': 'inconclusive', 'message': '未明确坐标轴方向', 'evidence': ''}

    # Step 2: 检查逻辑 — 提取高度差 Δy 或 y_final - y_initial 的符号
    # 寻找下滑/下降过程的描述
    is_falling = any(kw in (question + prediction) for kw in ['下滑', '下降', '下落', 'falling', 'downward'])

    # Step 3: 符号一致性校验
    # 如果 y 轴向上且物体下降，则 Δy 必须为负，或者势能变化量 ΔEp = mgΔy 必须为负
    if is_y_up and is_falling:
        # 检查是否存在错误的正号表达，如 Δy = h (h>0) 而非 -h
        # 匹配类似 y2-y1=h 或 delta y = h 的模式
        wrong_pattern = re.search(r'(y[2f]\s*-\s*y[1i]|Δy|delta\s*y)\s*=\s*[^\-][\d\w]+', prediction)
        if wrong_pattern:
            return {'result': 'fail', 'message': 'y轴向上且物体下降时，高度差符号未体现负值', 'evidence': wrong_pattern.group(0)}

        # 检查动能定理公式是否正确处理了符号：1/2mv^2 = -mgΔy 或 1/2mv^2 + mgy = const
        if '1/2' in prediction and 'v^2' in prediction and 'mgy' in prediction:
            if re.search(r'1/2\s*m\s*v\^2\s*=\s*m\s*g\s*y', prediction) and 'y' in prediction:
                # 简单启发式：如果直接写成 Ek = mgy 而 y 是负值，则逻辑正确；若 y 被当做正值则错
                pass

    # 检查公式结构是否包含必要符号
    required = ["g", "v", "y"]
    missing = [s for s in required if s not in prediction.lower()]
    if missing:
        return {'result': 'inconclusive', 'message': f'缺少必要物理量符号: {missing}', 'evidence': ''}

    # 若没有明确的符号冲突，且包含能量守恒逻辑，则视为 pass
    if re.search(r'1/2.*v.*2|m.*g.*y', prediction):
        return {'result': 'pass', 'message': '符号逻辑与坐标系定义基本一致', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '无法确定符号一致性细节', 'evidence': ''}

# rule_id=norm_3446b5897fa3bd80 | domain=Mechanics | topic=Work-Energy Theorem and Conservation of Energy
# rule_id=norm_3446b5897fa3bd80 | domain=Mechanics | topic=Work-Energy Theorem and Conservation of Energy
def check_norm_3446b5897fa3bd80_5951955d124d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否定义了坐标轴方向（如 y 轴向上）以及重力势能场景
    trigger_keywords = ['y-axis', 'vertically upwards', 'positive direction', 'coordinate system', '坐标轴', '竖直向上']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到坐标轴方向定义的相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证势能公式 Ep=mgh 中 h 与坐标值的增减关系
    # 重点检查：如果 y 轴向上，下落过程中的位移或坐标变化是否被正确处理为负值，或者势能是否减小
    pred_lower = prediction.lower()
    is_upward = re.search(r'(y|axis).*?(upward|positive|向上)', (question + context).lower())

    # 如果明确了 y 轴向上，检查 prediction 中关于下落/势能变化的描述
    if is_upward:
        # 检查是否包含势能公式或动能定理变形 v^2 = 2g(y_start - y_end)
        required_symbols = ["v", "y_{end}", "y_{start}"]
        formula_match = re.search(r'v\^2\s*=\s*2g\(y_{start}\s*-\s*y_{end}\)', prediction)

        # 检查下落过程中坐标变化与势能的关系
        falling_logic = re.search(r'(fall|down|下落).*?(decrease|negative|减小|负)', pred_lower)

        if formula_match:
            return {'result': 'pass', 'message': '势能参考系与坐标轴方向校验一致', 'evidence': formula_match.group()}

        if 'mgh' in pred_lower and ('delta' in pred_lower or 'y' in pred_lower):
            # 如果提到 mgh 但在 y 轴向上时将下落高度 h 直接等同于 y_end - y_start (正值)，则报错
            if re.search(r'h\s*=\s*y_{end}\s*-\s*y_{start}', pred_lower) and ('fall' in pred_lower or 'down' in pred_lower):
                return {'result': 'fail', 'message': '坐标轴向上时，下落过程的位移应为负值，公式符号逻辑错误', 'evidence': 'h = y_{end} - y_{start}'}

    # Step 3: 符号覆盖检查 (基于 symbolic_hint)
    missing_symbols = [s for s in ["v", "y_{end}", "y_{start}"] if s not in prediction]
    if not missing_symbols and '2g' in prediction:
        return {'result': 'pass', 'message': '符号覆盖完整且包含重力加速度逻辑', 'evidence': 'symbols: ' + str(missing_symbols)}

    return {'result': 'inconclusive', 'message': '证据不足，无法确定势能参考系方向是否校验正确', 'evidence': ''}

