# rule_id=norm_3724e73493d474bb | domain=Mechanics | topic=Work-Energy Theorem and Conservation of Energy
def check_norm_3724e73493d474bb_df51ae3a28cf(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及斜面/导轨运动且存在变力（弹簧、电场、磁场等）
    trigger_keywords = ['斜面', '导轨', '轨道', 'slope', 'track', 'inclined']
    variable_force_keywords = ['弹簧', '电场', '磁场', '变力', 'spring', 'electric field', 'magnetic', 'variable force']

    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and any(kw in combined_text for kw in variable_force_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到斜面/导轨上的变力运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查正压力 N 是否考虑了变力的分量，以及摩擦力是否被错误地当作恒力处理
    pred = prediction.lower()
    # 检查是否直接使用了简单的恒力摩擦公式 f = mu * m * g * cos(theta)
    constant_friction_pattern = r'f\s*=\s*\\?mu\s*m\s*g\s*\\?cos'
    # 检查是否包含正压力 N 的受力分析，特别是包含外部变力 F_ext 的分量
    normal_force_analysis = any(sym in prediction for sym in ['N', 'F_N', 'F_{ext}', 'F_e', 'F_s'])

    # 如果预测中直接套用恒力摩擦公式，且没有对 N 进行变力修正的描述，则判定为 fail
    if re.search(constant_friction_pattern, pred) and not re.search(r'N\(x\)|F_N\(x\)|\\int', pred):
        return {
            'result': 'fail',
            'message': '模型错误：在变力场景下直接套用了恒力摩擦公式，未考虑正压力 N 随位移的变化。',
            'evidence': re.search(constant_friction_pattern, pred).group(0) if re.search(constant_friction_pattern, pred) else prediction[:100]
        }

    # Step 3: 符号/公式校验 — 检查是否包含要求的符号 F_{ext}, N, \theta
    required_symbols = ["N", "\\theta"]
    missing_symbols = [sym for sym in required_symbols if sym not in prediction]

    if not missing_symbols and ('cos' in pred or 'sin' in pred):
        # 如果有积分符号或明确提到 N 的变化，则认为通过
        if '\\int' in pred or 'variable' in pred or '变化' in pred:
            return {'result': 'pass', 'message': '正确考虑了变力对正压力及摩擦力的影响', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了变力耦合的正压力修正', 'evidence': ''}

