# rule_id=norm_37bf0030eceafabf | domain=Mechanics | topic=Work-Energy Theorem and Conservation of Energy
def check_norm_37bf0030eceafabf_cc5d31fcc4e4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及弹性绳索保护下的坠落及加速度/能量问题
    trigger_keywords = ['elastic rope', 'fall', '坠落', '弹性绳', '缓冲', 'acceleration']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到弹性绳索坠落缓冲场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须建立能量守恒方程，包含重力势能变化与弹性势能/功的转化
    # 核心要素：mg(h + delta_L) 或 mg(2L + delta_L)
    pred = prediction.lower()
    energy_patterns = [
        r'mg\(.*?\+.*?\)',
        r'mgh',
        r'\int.*?f\(x\)dx',
        r'1/2.*?k.*?x\^2',
        r'potential energy'
    ]

    has_energy_eq = any(re.search(p, pred) for p in energy_patterns)
    if not has_energy_eq:
        return {'result': 'fail', 'message': '未建立能量守恒方程或未考虑重力势能与弹性功的转化', 'evidence': prediction[:200]}

    # Step 3: 符号与公式结构校验 — 检查关键符号 L, g, m, ΔL 以及 2L 的逻辑
    required_symbols = ['m', 'g', 'L']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    # 检查是否考虑了坠落高度（通常为 2L 或 h_fall）
    fall_height_logic = re.search(r'2\s*\*?\s*L|h_fall|坠落高度', pred)

    if not fall_height_logic and 'delta' not in pred and 'Δ' not in pred:
        return {'result': 'fail', 'message': '建模中缺失关键几何参数（如绳长L或伸长量ΔL）', 'evidence': prediction[:200]}

    # 如果公式中出现了 mg(2L + ΔL) 或类似的积分形式，则判定为 pass
    if re.search(r'mg\(2L\s*\+\s*(delta|Δ)L\)', pred.replace(' ', '')) or re.search(r'\int.*?[Ff]', pred):
        return {'result': 'pass', 'message': '能量守恒建模符合物理规则', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到能量讨论但公式完整性待确认', 'evidence': prediction[:200]}

