# rule_id=norm_4f3e5e81d45e9ccf | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_4f3e5e81d45e9ccf_5615fa95b018(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及加速转动容器内的平衡位置判定
    trigger_keywords = ['角加速度', 'angular acceleration', '平衡位置', 'equilibrium position', '容器', 'container', 'rotating']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到加速转动系统平衡判定场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了切向动力学方程并考虑了纯滚动/力矩平衡
    pred = prediction.lower()
    # 检查是否仅使用了径向力平衡（错误倾向）而忽略了切向/力矩分析
    logic_keywords = ['切向', 'tangential', '力矩', 'torque', '纯滚动', 'pure rolling', 'alpha', 'beta']
    has_tangential_logic = any(kw in pred for kw in logic_keywords)

    if not has_tangential_logic:
        return {'result': 'fail', 'message': '未建立切向动力学方程或力矩平衡方程，可能错误地仅使用了径向力平衡', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查关键物理量 R, alpha, theta, g 以及动力学方程结构
    # 目标方程结构类似于 mg sin(theta) = m * a_t + I * alpha / r
    required_symbols = ['R', 'alpha', 'theta', 'g']
    missing_symbols = [s for s in required_symbols if s.lower() not in pred and s not in pred]

    # 检查 canonical 公式特征：mg sin(theta) 与 加速度/力矩项 的关联
    formula_pattern = r'mg.*sin.*theta|m.*a.*t|I.*alpha|I.*beta'
    formula_match = re.search(formula_pattern, pred)

    if len(missing_symbols) >= 2:
        return {'result': 'fail', 'message': f'缺少关键物理符号: {missing_symbols}', 'evidence': prediction[:200]}

    if formula_match:
        return {'result': 'pass', 'message': '已建立切向动力学分析并包含必要物理量', 'evidence': formula_match.group()}

    return {'result': 'inconclusive', 'message': '逻辑分析尚不完整，无法判定准确性', 'evidence': ''}

