# rule_id=norm_4f6a9961886bf991 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_4f6a9961886bf991_3e8333bacdcd(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及绕轴转动、绳子/拉绳以及速度投影场景
    trigger_keywords = ['转动', '旋转', '轴', '绳', '线速度', '投影', '速度', 'u', 'v']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in ['绳', '线', '带']) or not any(kw in combined_text for kw in ['转', '轴', '轮']):
        return {'result': 'inconclusive', 'message': '未检测到绕轴转动与拉绳系统的相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否考虑了速度投影关系 u = v * cos(theta)
    # 重点检查是否错误地将绳速 u 直接等同于切向速度，或者是否提到了投影/余弦关系
    pred_lower = prediction.lower()

    # 检查是否包含速度投影的公式特征 (u = v cos alpha 或类似的变体)
    projection_pattern = r'u\s*=\s*v.*cos|v\s*=\s*u.*cos|u\s*=\s*\w+.*cos|cos\(alpha\)'
    has_projection = re.search(projection_pattern, pred_lower) or '投影' in pred_lower

    # 检查是否存在错误的直接等值假设 (例如直接令 u = v_tangential 而不考虑角度)
    # 如果题目明确给出了角度 alpha 但解题过程中直接忽略角度进行计算，则视为建模错误
    if 'alpha' in combined_text or '角度' in combined_text or 'theta' in combined_text:
        if not has_projection and ('u=v' in pred_lower.replace(' ', '') or 'v=u' in pred_lower.replace(' ', '')):
            return {'result': 'fail', 'message': '未正确应用速度投影法则，直接将绳速等同于接触点速度', 'evidence': prediction[:200]}

    # Step 3: 符号与公式结构校验
    # 匹配 symbolic_hint 中的 canonical 形式: u = |v_contact| * cos(theta)
    if re.search(r'u\s*=\s*v.*cos', pred_lower) or re.search(r'v.*cos.*=\s*u', pred_lower):
        return {'result': 'pass', 'message': '正确识别并应用了约束点速度投影法则', 'evidence': re.search(r'.{0,30}cos.{0,30}', pred_lower).group() if 'cos' in pred_lower else ''}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了速度投影关系', 'evidence': ''}

# rule_id=norm_57cb55928fbc7c47 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_57cb55928fbc7c47 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_57cb55928fbc7c47_73a84baa7c11(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及圆柱/球体在斜面上“不滑动”或“纯滚动”的场景
    trigger_keywords = ['rolling', 'without slipping', 'no sliding', '纯滚动', '不滑动', '滚动不滑动']
    object_keywords = ['cylinder', 'sphere', 'disk', '圆柱', '球', '圆盘']
    combined_text = (question + context).lower()

    is_triggered = any(kw in combined_text for kw in trigger_keywords) and any(obj in combined_text for obj in object_keywords)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到纯滚动或不滑动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否联立了平动方程 (F=ma) 和转动方程 (tau=I alpha)
    pred = prediction.lower()
    has_newton_linear = re.search(r'm.*g.*sin|f.*=.*m.*a', pred)
    has_torque = re.search(r'f.*r.*=.*i.*alpha|tau.*=.*i', pred)
    has_rolling_constraint = re.search(r'a.*=.*r.*alpha|alpha.*=.*a/r', pred)

    if not (has_newton_linear and has_torque):
        return {
            'result': 'fail',
            'message': '未检测到联立牛顿第二定律与转动定律的受力分析过程',
            'evidence': prediction[:200]
        }

    # Step 3: 校验临界条件 — 检查是否涉及静摩擦力 f <= mu * N 或 tan(alpha) <= mu(1 + mR^2/I)
    # 重点检查是否错误地直接使用了滑动摩擦力公式 f = mu * N 而非不等式校验
    has_friction_limit = re.search(r'f.*<=.*mu|mu.*n|tan.*<=.*mu', pred)
    has_wrong_assumption = re.search(r'f.*=.*mu.*n', pred) and not re.search(r'critical|limit|threshold|临界', pred)

    if has_wrong_assumption:
         return {
            'result': 'fail',
            'message': '在非临界状态下错误地直接使用了滑动摩擦力公式 f=μN，未进行静摩擦力不等式校验',
            'evidence': prediction[prediction.find('f'):prediction.find('f')+50]
        }

    if has_friction_limit or re.search(r'mu.*\(.*1.*\+.*m.*r.*2/i\)', pred):
        return {'result': 'pass', 'message': '正确执行了纯滚动受力分析并考虑了摩擦力临界条件', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '分析过程尚可，但未明确体现摩擦力临界条件的校验', 'evidence': ''}

# rule_id=norm_61e37536e2bf2821 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_61e37536e2bf2821 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_61e37536e2bf2821_de9cc9c5fff7(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及球体/圆柱在水平面受摩擦力从平动/转动向滚动演变
    trigger_keywords = ['球', '圆柱', 'sphere', 'cylinder', 'rolling', '滚动', '摩擦', 'friction']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到球体或圆柱滚动的物理场景', 'evidence': ''}

    # 检查是否涉及状态演变（从滑动到纯滚动）
    if not re.search(r'(纯滚动|pure rolling|sliding to rolling|滑动|演变)', combined_text):
        return {'result': 'inconclusive', 'message': '未检测到滑动向滚动演变的过程', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否利用角动量守恒或冲量矩关系（L = mvR - Iw 或类似形式）
    # 规则要求：检查是否建立 v 与 w 的线性约束，而非对变力位移积分
    pred = prediction.lower()

    # 检查是否提到了角动量守恒或冲量矩定理
    conservation_keywords = ['角动量守恒', 'angular momentum', '冲量矩', 'impulse', 'torque', 'moment of momentum']
    has_conservation = any(kw in pred for kw in conservation_keywords)

    # 检查关键符号：I, R, v, w (omega)
    required_symbols = ['i', 'r', 'v', 'w']
    symbol_count = sum(1 for sym in required_symbols if sym in pred or 'ω' in pred)

    # Step 3: 公式结构校验 (m*v_0*R = m*v_f*R + I*w_f 或类似线性组合)
    # 匹配类似 mvR, Iw, v=wr 的表达
    formula_pattern = re.search(r'(mv[0r]|iw|iω|v\s*=\s*[wrω]|l\s*=\s*)', pred)

    if not has_conservation and not formula_pattern:
        return {
            'result': 'fail',
            'message': '未发现利用角动量守恒或冲量矩建立速度与角速度约束的逻辑，可能错误地使用了变力位移积分',
            'evidence': prediction[:200]
        }

    if symbol_count >= 3 and (has_conservation or formula_pattern):
        return {
            'result': 'pass',
            'message': '正确识别了滑动转滚动过程中的角动量/冲量矩约束关系',
            'evidence': re.findall(r'.{0,30}(?:mv|iw|iω|angular momentum|角动量).{0,30}', pred)[:2]
        }

    return {'result': 'inconclusive', 'message': '推理过程中关于守恒律的描述不够明确', 'evidence': prediction[:150]}

# rule_id=norm_62c10d8869e3ba87 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_62c10d8869e3ba87 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_62c10d8869e3ba87_0677272f1ac0(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“纯滚动” (rolling without slipping) 以及曲面/轨道场景
    trigger_keywords = ['纯滚动', 'rolling without slipping', 'no slip', '不打滑']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到纯滚动约束场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否区分了自转角速度与公转角速度，并建立了速度约束关系
    # 重点寻找 r, R, omega, theta, psi 等符号及其比例关系
    pred_lower = prediction.lower()
    # 检查是否提到了角速度或速度约束公式
    has_angular_relation = any(kw in pred_lower for kw in ['omega', '角速度', 'dψ', 'dθ', 'v ='])
    if not has_angular_relation:
        return {'result': 'fail', 'message': '未在推理中发现角速度约束或速度匹配逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 r * omega = (R+r) * omega_orbital 类似的结构
    # 匹配类似 r*dψ = (R+r)*dθ 或 r*w = (R+r)*W 的模式
    # 考虑到符号多样性，匹配核心结构：半径与角速度乘积的等式
    pattern_rolling = r'(r|R_inner).*?[\*\s]?(omega|w|d[\u03c8\u03c8]|psi)|(R\+r|R-r|R_path).*?[\*\s]?(omega|w|d[\u03b8\u03b8]|theta)'
    if re.search(pattern_rolling, prediction, re.IGNORECASE):
        # 进一步检查是否体现了 r*w = (R+r)*W 的等效性
        if '=' in prediction or 'equal' in pred_lower or 'is' in pred_lower:
            return {'result': 'pass', 'message': '检测到符合纯滚动约束的角速度关联公式', 'evidence': re.search(r'.{0,30}=.{0,30}', prediction).group() if '=' in prediction else ''}

    # 如果提到了纯滚动但没有给出明确的 R, r 比例关系，视为逻辑缺失
    if 'r' in pred_lower and 'R' in pred_lower and '=' not in pred_lower:
        return {'result': 'fail', 'message': '虽提及半径但未建立正确的纯滚动等式约束', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定约束公式是否正确应用', 'evidence': ''}

# rule_id=norm_6681f99a77ea57ab | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_6681f99a77ea57ab | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_6681f99a77ea57ab_0b5fc18a1b85(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否询问脱离支撑面、墙壁或轨道的临界角度/位置
    trigger_keywords = ['脱离', '离开', 'leave', 'detach', 'lose contact', '临界角度', 'critical angle']
    target_objects = ['墙', '轨道', '支撑', 'wall', 'track', 'surface', 'support']

    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and any(obj in combined_text for obj in target_objects)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到涉及脱离约束表面的物理场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须令正压力 N=0 (或 Fn=0)
    # 排除错误逻辑：令合力为0或合力矩为0
    pred_lower = prediction.lower()

    # 检查是否包含 N=0 的逻辑表达 (支持 N, Fn, N_wall, N(theta))
    norm_force_zero_pattern = r'(N|F_?n|F_?norm|正压力|弹力)\s*(=|为|趋于|is|equals)\s*0'
    has_norm_zero = re.search(norm_force_zero_pattern, pred_lower) or 'n=0' in pred_lower.replace(' ', '')

    # 检查是否错误地使用了合力为0或力矩为0作为脱离条件
    wrong_logic_pattern = r'(合力|net force|total force|合外力|torque|力矩)\s*(=|为|is)\s*0'
    has_wrong_logic = re.search(wrong_logic_pattern, pred_lower)

    # Step 3: 综合判定
    if has_norm_zero:
        # 如果提到了 N=0，且没有明显的合力为0的误导，判定为 pass
        return {'result': 'pass', 'message': '正确识别脱离临界条件为正压力为零', 'evidence': re.search(norm_force_zero_pattern, pred_lower).group(0) if re.search(norm_force_zero_pattern, pred_lower) else 'N=0'}

    if has_wrong_logic:
        return {'result': 'fail', 'message': '错误地将合力或力矩为零作为脱离约束的临界条件', 'evidence': has_wrong_logic.group(0)}

    # 如果既没写 N=0 也没写合力=0，但给出了结果，检查是否有 N 相关的符号计算
    if 'n' in pred_lower or '\\theta' in pred_lower:
        return {'result': 'inconclusive', 'message': '检测到相关物理量但未明确看到 N=0 的判定步骤', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '推理过程中缺失临界条件判定逻辑', 'evidence': ''}

# rule_id=norm_668b2147a56a2371 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_668b2147a56a2371 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_668b2147a56a2371_dd17a832dc8a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多个物体（块、圆柱、滑轮等）且受外力 F 驱动
    q_c = (question + context).lower()
    is_multi_body = any(kw in q_c for kw in ['block', 'cylinder', 'pulley', 'mass', '物体', '圆柱', '滑轮', '质量'])
    has_force = 'f' in q_c or 'force' in q_c or '外力' in q_c
    if not (is_multi_body and has_force):
        return {'result': 'inconclusive', 'message': '未检测到多物体受力驱动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证加速度 a 的表达式是否包含外力 F
    # 排除纯重力自由落体（g）或纯几何约束的情况
    pred = prediction.lower()
    # 寻找 a = ... 的表达式
    accel_patterns = [r'a\s*=\s*[^\n]+', r'acceleration\s*(is|=)\s*[^\n]+']
    found_accel = False
    for pattern in accel_patterns:
        match = re.search(pattern, pred)
        if match:
            found_accel = True
            expr = match.group(0)
            # 如果加速度表达式中完全没有 F (或 f)，且不是在讨论重力加速度 g，则判定为逻辑断裂
            if 'f' not in expr and 'force' not in expr:
                # 进一步确认是否为常数（如 a = g, a = 9.8）且题目并非自由落体
                if re.search(r'=\s*(\d+(\.\d+)?|g)\b', expr) and 'free fall' not in q_c:
                    return {'result': 'fail', 'message': '加速度表达式丢失外力 F，动力学耦合逻辑断裂', 'evidence': expr}

    # Step 3: 符号覆盖检查 (Required: F, M, a)
    if found_accel:
        has_f = 'f' in pred
        has_m = 'm' in pred
        if not has_f and not ('g' in pred and 'free fall' in q_c):
             return {'result': 'fail', 'message': '预测中未体现外力对系统加速度的影响', 'evidence': prediction[:200]}
        return {'result': 'pass', 'message': '加速度表达式包含动力学驱动项', 'evidence': 'Detected acceleration expression with force coupling'}

    return {'result': 'inconclusive', 'message': '未找到明确的加速度计算表达式', 'evidence': ''}

# rule_id=norm_6d4801e5b20d5fd3 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_6d4801e5b20d5fd3 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_6d4801e5b20d5fd3_25a9f87aea25(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及平面纯滚动及速度约束（如绳子、杆、瞬心）
    trigger_keywords = ['纯滚动', 'rolling without slipping', '瞬心', 'instantaneous center', '速度场']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到纯滚动或瞬心法适用场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了以接触点为瞬心的速度关系 v = ω * L 或 u = v * cos(θ)
    # 重点检查是否提到了角速度 omega (ω) 与距离或投影的关系
    pred_lower = prediction.lower()
    # 匹配 omega, w, 距离 d, L, r 以及余弦投影关系
    has_omega = re.search(r'[ωw]|omega', pred_lower)
    has_geometry = re.search(r'cos|sin|投影|垂直距离|perpendicular', pred_lower)

    if not (has_omega and has_geometry):
        return {'result': 'fail', 'message': '推理过程中未体现瞬心投影法或角速度与线速度的几何投影关系', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查 canonical 公式 u = ω * d_perp 的结构
    # 匹配类似 u = omega * d, v = w * L * cos, u = w * h 等结构
    formula_pattern = r'[uv]\s*=\s*[ωw]\s*[*·]?\s*[a-zA-Z_{}]+\s*[*·]?\s*(cos|sin)?'
    if re.search(formula_pattern, pred_lower):
        return {'result': 'pass', 'message': '检测到符合瞬心投影法的速度约束公式', 'evidence': re.search(formula_pattern, pred_lower).group()}

    # 如果有相关描述但公式不完整，返回 inconclusive
    if 'omega' in pred_lower or 'ω' in pred_lower:
        return {'result': 'inconclusive', 'message': '检测到角速度描述，但未发现明确的投影约束公式', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '证据不足以判定逻辑正确性', 'evidence': ''}

# rule_id=norm_6d86d7b47e4bc255 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_6d86d7b47e4bc255 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_6d86d7b47e4bc255_ed73acfbe374(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及连杆系统（linkage/rod system）及角加速度计算
    trigger_keywords = ['连杆', '杆件', 'linkage', 'rod', 'hinge', '铰链', '连接点']
    target_keywords = ['角加速度', 'angular acceleration', 'alpha', '\\alpha']
    combined_text = (question + context).lower()

    is_triggered = any(k in combined_text for k in trigger_keywords) and any(k in combined_text for k in target_keywords)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到连杆系统角加速度计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否考虑了连接点处的未知约束力（F_x, F_y 或 T_constraint）
    # 规则严禁直接套用单体定轴转动公式 (I*alpha = tau_ext)，必须包含约束力项
    pred = prediction.lower()
    constraint_patterns = [
        r'[Ff](_?[xy]|_?n|_?t)', # Fx, Fy, Fn, Ft
        r'约束力', r'reaction force', r'hinge force',
        r'\\tau_{?constraint}?', r'\\sum\\s*\\tau'
    ]

    has_constraint_analysis = any(re.search(p, prediction) for p in constraint_patterns)

    # Step 3: 符号与公式结构校验
    # 检查是否包含 I, alpha, tau 等核心符号，并检查公式是否仅为简单的 I*alpha=M_ext
    required_symbols = ['I', 'alpha', 'tau']
    symbol_count = sum(1 for s in required_symbols if s in prediction or ('\\' + s) in prediction)

    # 如果预测中直接使用了简单的 I*alpha = M (且 M 只是重力矩等已知力矩)，则判定为建模错误
    simple_formula = re.search(r'I\s*\\?alpha\s*=\s*m_?g', pred)

    if not has_constraint_analysis and simple_formula:
        return {
            'result': 'fail',
            'message': '建模错误：计算连杆角加速度时未考虑连接点处的未知约束力矩，严禁直接套用单体定轴转动公式。',
            'evidence': re.sub(r'\s+', ' ', prediction[:200])
        }

    if has_constraint_analysis and symbol_count >= 2:
        return {
            'result': 'pass',
            'message': '分析过程包含了约束力项或复杂的力矩耦合分析。',
            'evidence': '检测到约束力分析或力矩求和项'
        }

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了内力矩耦合', 'evidence': ''}

# rule_id=norm_6fa5831e7c0ffd7e | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_6fa5831e7c0ffd7e | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_6fa5831e7c0ffd7e_c332354dec8a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及立方体/刚体绕边缘或非质心轴转动
    trigger_keywords = ['moment of inertia', 'rotational inertia', '转动惯量', 'parallel axis theorem', '平行轴定理']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到转动惯量计算场景', 'evidence': ''}

    if 'edge' not in (question + context).lower() and 'pivot' not in (question + context).lower() and '边缘' not in (question + context):
        return {'result': 'inconclusive', 'message': '未明确涉及非质心轴/边缘轴计算', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否应用了平行轴定理 I = I_cm + Md^2
    pred = prediction.lower()
    # 检查是否包含平行轴定理的核心结构
    has_parallel_logic = re.search(r'i_cm\s*\+\s*m', pred) or re.search(r'\+\s*m.*d\^2', pred) or 'parallel axis' in pred

    # Step 3: 符号与数值校验 — 针对立方体绕边缘轴的具体公式校验
    # I_edge = 1/6*ML^2 + M*(L/sqrt(2))^2 = 2/3*ML^2
    # 检查是否出现了 2/3 或 0.667 相关的系数，或者 d = L/sqrt(2) 的推导
    has_correct_coeff = re.search(r'2/3\s*m\s*l\^2', pred) or re.search(r'0\.66[67]', pred)
    has_distance_calc = re.search(r'l/sqrt\(2\)', pred) or re.search(r'l/\(2\^0\.5\)', pred) or 'sqrt(2)' in pred

    if not has_parallel_logic and not has_correct_coeff:
        return {'result': 'fail', 'message': '未正确应用平行轴定理或计算非质心轴转动惯量', 'evidence': prediction[:200]}

    if has_correct_coeff or (has_parallel_logic and has_distance_calc):
        return {'result': 'pass', 'message': '正确应用平行轴定理计算边缘轴转动惯量', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到相关计算但无法确定公式准确性', 'evidence': prediction[:150]}

# rule_id=norm_73f62216d7e04568 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_73f62216d7e04568 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_73f62216d7e04568_e4df3ac23785(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“物体A支撑物体B”且“B在重力下运动”
    # 匹配关键词如：支撑、托住、放在...上，以及重力、下落、运动等
    trigger_keywords = ['支撑', '托', '放在', '置于', 'support', 'placed on']
    gravity_keywords = ['重力', 'gravity', 'mg', '下落', '运动', 'motion']

    q_c_text = (question + context).lower()
    is_triggered = any(k in q_c_text for k in trigger_keywords) and any(k in q_c_text for k in gravity_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到多体支撑与重力运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否对A和B分别进行了受力分析（寻找相互作用力N或压力/支持力的体现）
    pred = prediction.lower()
    # 检查是否提到了相互作用力（N, N\', 压力, 支持力, normal force）
    interaction_terms = ['n\'', '支持力', '压力', 'normal force', 'reaction force', '相互作用']
    has_interaction = any(term in pred for term in interaction_terms)

    # Step 3: 符号与公式校验 — 检查动力学方程中是否包含 N 和 L_arm 等要素
    # 重点检查是否将 N 作为内力引入了方程（如 tau = ... - N * L）
    has_n_symbol = 'n' in pred or 'f_n' in pred
    has_torque_logic = re.search(r'tau|torque|i\\alpha|i\*alpha|力矩', pred)

    # 如果完全没有提到相互作用力或压力，且没有体现受力平衡/动力学方程的耦合，判定为 fail
    if not has_interaction and not (has_n_symbol and has_torque_logic):
        return {
            'result': 'fail',
            'message': '未在动力学分析中体现物体间的相互作用力（支持力/压力），可能存在孤立求解错误',
            'evidence': prediction[:200]
        }

    # 检查 canonical 提示中的公式结构：tau_net = tau_gravity - N * L_arm
    # 匹配类似 I*alpha = ... - N*L 或类似的力矩平衡/动力学表达
    formula_pattern = r'([\tauI].*?=.*?mg.*?[nN].*?[lL])|([nN].*?[lL].*?[\tauI])'
    if re.search(formula_pattern, pred):
        return {'result': 'pass', 'message': '检测到耦合动力学方程及相互作用力分析', 'evidence': '匹配到耦合力矩/动力学表达'}

    return {'result': 'inconclusive', 'message': '检测到相关概念但公式结构不明确', 'evidence': prediction[:150]}

# rule_id=norm_8230770f76f237a3 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_8230770f76f237a3 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_8230770f76f237a3_28a12d9e48c0(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及转动刚体（如杆、盘）的支持力/正压力 N 求解
    trigger_keywords = ['支持力', '正压力', '轴承力', '作用力', 'normal force', 'reaction force']
    rotational_keywords = ['转动', '刚体', '杆', '盘', 'rotation', 'rigid body', 'rod', 'pivot']

    full_text = (question + context).lower()
    is_rotational = any(kw in full_text for kw in rotational_keywords)
    is_force_query = any(kw in full_text for kw in trigger_keywords)

    if not (is_rotational and is_force_query):
        return {'result': 'inconclusive', 'message': '未检测到转动刚体支持力求解场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否包含重力分量、切向加速度贡献以及向心加速度贡献
    pred = prediction.lower()
    # 检查向心项 (通常包含 omega^2 或 v^2/R)
    has_centripetal = re.search(r'\\omega\^2|v\^2/|\\dot{\\theta}\^2|向心', pred)
    # 检查切向/重力项 (通常包含 alpha, g, sin/cos theta)
    has_gravity_comp = re.search(r'mg|g\\sin|g\\cos|重力', pred)
    has_tangential = re.search(r'\\alpha|a_t|\\ddot{\\theta}|切向', pred)

    # 检查是否仅考虑了力矩/切向项而忽略了向心项（这是规则指出的典型错误）
    if not has_centripetal and has_tangential:
        return {
            'result': 'fail',
            'message': '计算支持力时疑似缺失向心加速度（与角速度平方相关）的贡献，仅考虑切向项会导致结果偏差',
            'evidence': prediction[:200]
        }

    # Step 3: 符号覆盖检查 (根据 symbolic_hint)
    required_symbols = ["N", "\\omega", "\\theta"]
    missing_symbols = [s for s in required_symbols if s not in prediction]

    # 如果关键符号缺失且没有中文描述，则认为证据不足或逻辑不全
    if len(missing_symbols) >= 2 and not (has_centripetal or '加速度' in pred):
        return {'result': 'fail', 'message': '计算过程缺失必要的物理量符号（如角速度或角度）', 'evidence': f"缺失符号: {missing_symbols}"}

    # Step 4: 公式结构校验 (Mg - N = M * a_y)
    if re.search(r'N\s*=\s*m.*g.*\-\s*m.*a', pred.replace(' ', '')) or re.search(r'm.*g.*\-\s*N\s*=\s*m.*a', pred.replace(' ', '')):
        return {'result': 'pass', 'message': '支持力计算公式结构基本完整', 'evidence': '检测到牛顿第二定律在质心坐标下的应用'}

    return {'result': 'inconclusive', 'message': '无法确定计算过程是否完整，建议人工核查', 'evidence': ''}

# rule_id=norm_840032ad440779a2 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_840032ad440779a2 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_840032ad440779a2_1cc8d4572ef5(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多个刚体、铰链连接及瞬时加速度计算
    trigger_keywords = ['hinge', '铰链', 'link', '连杆', 'rigid body', '刚体', 'joint', '连接点']
    accel_keywords = ['acceleration', '加速度', 'instantaneous', '瞬时']

    full_text = (question + context).lower()
    is_triggered = any(kw in full_text for kw in trigger_keywords) and any(kw in full_text for kw in accel_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到多连杆系统或加速度计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了公共连接点的加速度约束方程 (a_B = a_A + alpha x r)
    # 匹配加速度合成公式的特征：a_... = a_... + alpha * r 或类似的矢量关系
    pred = prediction.lower()
    # 匹配 a_B = a_A + alpha x r 类型的结构
    accel_constraint_pattern = r'a_[a-zA-Z]\s*=\s*a_[a-zA-Z]\s*\+\s*(\\alpha|alpha).*r'
    # 匹配 a = alpha * r (纯转动) 或 a = a_rel + a_accel (相对运动)
    simplified_pattern = r'a\s*=\s*(\\alpha|alpha).*r'

    has_constraint = re.search(accel_constraint_pattern, pred) or re.search(simplified_pattern, pred)

    # Step 3: 符号覆盖检查 (alpha, a, r)
    required_symbols = ['\\alpha', 'a', 'r']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)

    if not has_constraint and symbol_count < 2:
        return {
            'result': 'fail',
            'message': '未检测到必要的加速度约束方程或矢量合成逻辑，可能漏掉连接点的运动学约束',
            'evidence': prediction[:200]
        }

    if has_constraint:
        return {
            'result': 'pass',
            'message': '已建立加速度约束方程',
            'evidence': re.search(accel_constraint_pattern, pred).group(0) if re.search(accel_constraint_pattern, pred) else 'Found basic accel relation'
        }

    return {'result': 'inconclusive', 'message': '存在相关符号但公式结构不完整，无法确定约束校验是否充分', 'evidence': ''}

# rule_id=norm_8aa25b1b5d7d44a9 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_8aa25b1b5d7d44a9 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_8aa25b1b5d7d44a9_9b620f4b0dc9(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及 rpm (revolutions per minute) 以及加速度/位移计算
    trigger_keywords = ['rpm', 'rev/min', '转/分', '转每分']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '题目未涉及 rpm 单位', 'evidence': ''}

    target_keywords = ['acceleration', 'displacement', 'theta', 'angle', '加速度', '位移', '角位移', '转过']
    if not any(kw in (question + context).lower() for kw in target_keywords):
        return {'result': 'inconclusive', 'message': '题目未要求计算加速度或位移', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否进行了 rpm 到 rad/s 的转换 (2π/60 或 π/30)
    # 匹配转换系数：2*pi/60, pi/30, 6.28/60, 0.1047 等
    conversion_patterns = [
        r'2\s*\*?\s*(pi|π)\s*/\s*60',
        r'(pi|π)\s*/\s*30',
        r'\*\s*0\.1047',
        r'\*\s*6\.28\s*/\s*60'
    ]

    has_conversion = any(re.search(pat, prediction, re.IGNORECASE) for pat in conversion_patterns)

    # 另一种情况：计算圈数时直接使用平均转速 (n1+n2)/2 * t
    has_rev_logic = re.search(r'\(\s*n1\s*\+\s*n2\s*\)\s*/\s*2', prediction) or 'average' in prediction.lower()

    # Step 3: 符号校验 — 检查是否建立了 omega = n * (2pi/60) 的关系
    symbolic_match = re.search(r'omega|ω', prediction, re.IGNORECASE) and re.search(r'n\s*\*|rpm\s*\*', prediction, re.IGNORECASE)

    if has_conversion or (has_rev_logic and 'rev' in prediction.lower()):
        return {'result': 'pass', 'message': '已检测到单位转换逻辑或正确的圈数计算方法', 'evidence': prediction[:200]}

    # 如果直接将 rpm 数值代入含有 rad/s 定义的公式（如 alpha = delta_omega / t）而未见转换系数，则判定为 fail
    if re.search(r'[αa]\s*=\s*\(?n[21]?\s*-\s*n[12]?\)?\s*/', prediction):
        return {'result': 'fail', 'message': '直接将 rpm 数值代入运动学公式，未进行 rad/s 转换', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了转速单位转换', 'evidence': ''}

# rule_id=norm_8cfa1f6fdf5142dd | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_8cfa1f6fdf5142dd | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_8cfa1f6fdf5142dd_3590122275c4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及加速平台上的物体翻转/转动临界状态
    trigger_keywords = ['rotate', 'tip', 'topple', 'flip', 'overturn', '翻转', '转动', '倾覆', '刚要']
    accel_keywords = ['accelerating', 'platform', 'base', 'frame', '加速', '基座', '平台']

    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and any(kw in combined_text for kw in accel_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到加速基座翻转的临界场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 确认是否考虑了支点转移、重力矩、惯性力矩
    pred_lower = prediction.lower()

    # 检查是否提及支点(pivot/edge/corner)或力矩平衡
    has_pivot_logic = any(kw in pred_lower for kw in ['pivot', 'edge', 'corner', '边缘', '支点', '角点'])
    has_torque_logic = any(kw in pred_lower for kw in ['torque', 'moment', '力矩', 'tau'])

    if not (has_pivot_logic or has_torque_logic):
        return {'result': 'fail', 'message': '模型未分析翻转支点或力矩平衡状态', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查惯性力矩(-ma)与重力矩的平衡结构
    # 核心公式应包含惯性项 (ma 或 m*a) 和重力项 (mg)
    has_inertial_term = re.search(r'm\s*\*?\s*a', pred_lower) or '惯性' in pred_lower
    has_gravity_term = re.search(r'm\s*\*?\s*g', pred_lower) or '重力' in pred_lower

    # 检查是否包含角加速度 alpha 或 I_pivot (针对动力学关联)
    has_kinematic_link = any(sym in prediction for sym in ['alpha', 'α', 'I_p', 'I_pivot'])

    if not (has_inertial_term and has_gravity_term):
        return {'result': 'fail', 'message': '力矩平衡方程中缺失惯性力矩或重力矩项', 'evidence': prediction[:300]}

    # 如果包含 alpha 且有惯性项，则认为建模较为完整
    if has_kinematic_link or 'tau' in pred_lower:
        return {'result': 'pass', 'message': '模型正确包含了非惯性系下的力矩平衡及运动学关联分析', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到部分物理要素，但无法确认公式推导的完整性', 'evidence': ''}

# rule_id=norm_98c180ab61f6623a | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_98c180ab61f6623a | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_98c180ab61f6623a_95495a69b787(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及空间相关的摩擦系数 μ(x) 或变系数摩擦，并询问纯滚动/运动状态
    trigger_keywords = ['摩擦系数', 'mu', 'μ', 'friction coefficient']
    is_variable_mu = re.search(r'[μu]\s*\(\s*x\s*\)', question + context) or re.search(r'摩擦系数.*函数', question + context)
    is_rolling = re.search(r'纯滚动|rolling without slipping|运动状态', question + context)

    if not (is_variable_mu and is_rolling):
        return {'result': 'inconclusive', 'message': '未检测到变系数摩擦力下的纯滚动判定场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 判定纯滚动是否达成应看速度 v(t) 与 R*w(t) 的演化交点
    # 错误逻辑通常是直接令 a = R*alpha (加速度方程相等) 来求临界，而忽略了初速度与角速度的积分过程
    pred_lower = prediction.lower()
    has_evolution = re.search(r'速度.*角速度.*(相等|交点|演化|积分)', pred_lower) or re.search(r'v\s*=\s*R\s*\*?\s*w', pred_lower)
    has_acceleration_only = re.search(r'a\s*=\s*R\s*\*?\s*alpha', pred_lower) or re.search(r'加速度.*相等', pred_lower)

    # 如果只提到了加速度相等而没有提到速度/角速度的演化关系，则判定为概念错误
    if has_acceleration_only and not has_evolution:
        return {
            'result': 'fail',
            'message': '判定纯滚动应基于速度与角速度的演化交点(v=Rw)，而非仅令加速度方程相等。',
            'evidence': re.search(r'.{0,50}a\s*=\s*R\s*\*?\s*alpha.{0,50}', prediction).group(0) if has_acceleration_only else prediction[:100]
        }

    # Step 3: 符号覆盖检查 (R, v, w)
    required_symbols = ['R', 'v', 'w']
    missing_symbols = [s for s in required_symbols if s not in prediction]
    if not missing_symbols and has_evolution:
        return {'result': 'pass', 'message': '正确使用了速度与角速度关系判定纯滚动状态', 'evidence': '检测到符号: ' + str(required_symbols)}

    return {'result': 'inconclusive', 'message': '推理过程中关于纯滚动判定的依据不充分', 'evidence': ''}

# rule_id=norm_9c0b9dbfb21b1ed2 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_9c0b9dbfb21b1ed2 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_9c0b9dbfb21b1ed2_bdd056210ea1(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否同时出现“纯滚动”与“摩擦系数”
    trigger_keywords = ['pure rolling', 'rolling without slipping', '纯滚动', '不打滑滚动']
    mu_keywords = ['friction coefficient', 'coefficient of friction', '摩擦系数', 'μ', '\\mu']

    q_c = (question + context).lower()
    has_rolling = any(kw in q_c for kw in trigger_keywords)
    has_mu = any(kw in q_c for kw in mu_keywords)

    if not (has_rolling and has_mu):
        return {'result': 'inconclusive', 'message': '未同时检测到纯滚动场景与摩擦系数设定', 'evidence': ''}

    # Step 2: 检查逻辑 — 判定是否错误地将静摩擦力直接设为 f = μN
    # 纯滚动中 f 是静摩擦力，通常 f < μN，除非是临界状态。若直接代入 f = μN 求解加速度或力矩通常是错误的。
    pred = prediction.lower()
    # 匹配类似 f = mu * N, f = mu*m*g, f = \mu N 等表达式
    error_pattern = r'f\s*=\s*(\\mu|mu)\s*([Nn]|m\s*g)'

    # 检查是否通过动力学方程联立求解 (a = alpha * r, tau = I * alpha)
    correct_logic_patterns = [
        r'a\s*=\s*\\?alpha\s*r',
        r'\\tau\s*=\s*I\s*\\?alpha',
        r'f\s*r\s*=\s*I',
        r'f\s*<=\s*(\\mu|mu)'
    ]
    has_correct_logic = any(re.search(p, pred) for p in correct_logic_patterns)

    if re.search(error_pattern, pred):
        # 如果直接用了 f=muN 且没有提到这是临界状态(limiting/critical)，则判定为概念错误
        if 'critical' not in pred and 'limiting' not in pred and '临界' not in pred and '最大静摩擦' not in pred:
            return {
                'result': 'fail',
                'message': '在纯滚动问题中错误地直接使用了滑动摩擦力公式 f = μN，纯滚动摩擦力应由动力学方程联立求解。',
                'evidence': re.search(error_pattern, pred).group(0)
            }

    # Step 3: 符号覆盖检查
    required_symbols = ['I', 'a', 'f']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)

    if has_correct_logic and symbol_count >= 2:
        return {'result': 'pass', 'message': '正确使用了动力学方程联立求解纯滚动摩擦力', 'evidence': '检测到动力学关联公式'}

    return {'result': 'inconclusive', 'message': '无法确定摩擦力的处理逻辑是否正确', 'evidence': ''}

# rule_id=norm_a1f3006a408a62d0 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_a1f3006a408a62d0 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_a1f3006a408a62d0_12d18accb169(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及加速度随位移/时间变化（变力）且要求解速度
    # 匹配关键词如：加速度随x变化、a=kx、F=kx、变力、非恒力，且问句包含速度/动能
    trigger_keywords = ['加速度', '力', 'a=', 'F=']
    variable_keywords = ['变化', '函数', '线性', '非线性', 'x', 's', '位移']
    target_keywords = ['速度', 'v=', '末速度', '动能']

    q_text = (question + context).lower()
    is_variable_accel = any(k in q_text for k in trigger_keywords) and any(k in q_text for k in variable_keywords)
    is_asking_velocity = any(k in q_text for k in target_keywords)

    if not (is_variable_accel and is_asking_velocity):
        return {'result': 'inconclusive', 'message': '未检测到变力/变加速度求解速度的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 禁止使用匀变速直线运动公式 (v=at, v^2-v0^2=2as)
    pred = prediction.lower()
    # 匹配典型的匀变速公式特征
    invalid_formulas = [r'v\s*=\s*a\s*t', r'v\^2\s*-\s*v0\^2\s*=\s*2\s*a', r'v_t\s*=\s*v_0\s*\+\s*at']
    for pattern in invalid_formulas:
        if re.search(pattern, pred):
            return {'result': 'fail', 'message': '在变力场景下错误使用了匀变速直线运动公式', 'evidence': re.search(pattern, pred).group()}

    # Step 3: 符号/公式校验 — 必须包含功能关系或积分表达
    # 检查能量守恒、动能定理或积分符号
    energy_patterns = [r'1/2\s*m\s*v\^2', r'\Delta\s*E', r'\int', r'W\s*=', r'动能定理', r'能量守恒']
    has_energy_logic = any(re.search(p, pred) or p in pred for p in energy_patterns)

    # 检查 symbolic_hint 中的必要符号
    required_symbols = ["E_k", "E_p"]
    symbol_count = sum(1 for s in required_symbols if s in prediction)

    if has_energy_logic or symbol_count >= 1:
        return {'result': 'pass', 'message': '正确使用了功能关系或积分方法处理变力做功', 'evidence': '检测到能量/积分相关逻辑'}

    return {'result': 'inconclusive', 'message': '无法确定是否使用了正确的物理模型', 'evidence': pred[:100]}

# rule_id=norm_a59ed2849121245e | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_a59ed2849121245e | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_a59ed2849121245e_26053125260f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及光滑水平面上的物体倾倒/滑动且初始静止
    trigger_keywords = ['光滑', '无摩擦', 'smooth', 'frictionless', 'horizontal surface']
    motion_keywords = ['倾倒', '滑下', 'falling', 'tipping', 'sliding']

    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and \
                   any(kw in combined_text for kw in motion_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到光滑水平面倾倒或滑动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否应用了水平动量守恒（质心水平位置不变）
    pred = prediction.lower()
    # 检查是否错误地描述为圆弧轨迹（建模错误）
    arc_error = re.search(r'(圆弧|arc|circular path|trajectory is a circle)', pred)
    # 检查是否提到水平方向动量守恒或质心水平位移为零
    momentum_cons = re.search(r'(水平方向动量守恒|momentum in the x-direction is conserved|v_{x,cm}\s*=\s*0|x_{cm}\s*=\s*const)', pred)
    vertical_fall = re.search(r'(竖直下落|vertical|straight down|only vertical)', pred)

    # Step 3: 判定结果
    if arc_error and not (momentum_cons or vertical_fall):
        return {
            'result': 'fail',
            'message': '建模错误：在无摩擦水平面上，质心应竖直下落（水平动量守恒），而非圆弧轨迹。',
            'evidence': str(arc_error.group(0))
        }

    if momentum_cons or vertical_fall or re.search(r'x_{cm}', pred):
        return {
            'result': 'pass',
            'message': '正确识别质心水平位置不变或水平动量守恒。',
            'evidence': pred[:150]
        }

    return {'result': 'inconclusive', 'message': '未明确提及质心运动轨迹或动量守恒逻辑', 'evidence': ''}

# rule_id=norm_ad7a006418c55987 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
# rule_id=norm_ad7a006418c55987 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_ad7a006418c55987_a1135a00dfb2(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
