    if not any(kw in (question + context) for kw in ['倒车', '反向', '正向', '比较']):
        return {'result': 'inconclusive', 'message': '未检测到正反向能力比较要求', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否识别出倒车上坡等效于驱动轮位置相对于重心的几何关系反转
    pred = prediction.lower()
    logic_keywords = ['等效', '反转', '重心', '位置', '正压力', 'N_drive', '驱动轮']

    # 检查是否讨论了驱动轮正压力 N_drive 的变化
