# rule_id=norm_6ee38e665133a929 | domain=Mechanics | topic=Torque and Static Equilibrium
# rule_id=norm_6ee38e665133a929 | domain=Mechanics | topic=Torque and Static Equilibrium
def check_norm_6ee38e665133a929_11db7e391774(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及卷状材料（厚度s、内外径R、单位长度质量lambda）
    trigger_keywords = ['厚度', '内径', '外径', '单位长度质量', '线密度', '卷', 'thickness']
    combined_text = (question + context).lower()
    if not all(re.search(kw, combined_text) for kw in ['厚', '径']):
        return {'result': 'inconclusive', 'message': '未检测到卷状材料几何转换场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否使用了面积等效原理 L = pi(Ro^2 - Ri^2) / s
    # 核心公式特征：(Ro^2 - Ri^2) 除以 s，并乘以 pi
    pred = prediction.lower()
    # 匹配平方差除以厚度的结构
    area_equiv_pattern = r'pi.*\(.*R.*\^2.*-.*R.*\^2.*\).*/.*s'
    # 匹配质量公式 M = lambda * L
    mass_formula_pattern = r'M.*=.*lambda.*pi.*\(.*R.*\^2.*-.*R.*\^2.*\).*/.*s'

    # 检查是否使用了错误的平均周长近似 (Ro+Ri)*pi * (Ro-Ri)/s (虽然数学等价但逻辑出发点不同，规则强调面积等效)
    # 重点检查是否直接出现了平方差公式
    has_area_logic = re.search(r'R[oa]?\^2\s*-\s*R[ib]?\^2', pred) or re.search(r'\(R[oa]\s*\+\s*R[ib]\)\(R[oa]\s*-\s*R[ib]\)', pred)

    if not has_area_logic:
        return {'result': 'fail', 'message': '未发现基于面积等效原理的计算逻辑，可能误用简单近似', 'evidence': prediction[:200]}

    # Step 3: 符号覆盖检查
    required_symbols = ['R', 's', 'pi']
    missing_symbols = [sym for sym in required_symbols if sym.lower() not in pred]
    if missing_symbols:
        return {'result': 'fail', 'message': f'计算过程中缺失关键物理量符号: {missing_symbols}', 'evidence': prediction[:200]}

    if re.search(area_equiv_pattern, pred.replace(' ', '')) or re.search(r'\pi.*R.*2', pred):
        return {'result': 'pass', 'message': '已验证使用面积等效原理进行质量转换', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑推导不清晰，无法确定是否完全符合面积等效要求', 'evidence': ''}

