    # Step 1: 触发条件 — 检查是否涉及宇宙半径、哈勃常数或宇宙密度
    trigger_keywords = ['宇宙半径', 'cosmic radius', 'Hubble constant', '哈勃常数', '宇宙密度', 'cosmic density', 'average density of the universe']
