    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否出现逃逸速度或束缚状态相关的关键词
    trigger_keywords = ['does not escape', 'maximum speed to remain bound', 'escape velocity', 'remain bound']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到逃逸速度或束缚状态相关的触发词', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否提及总能量 E=0 或 逃逸速度公式 sqrt(2)*v
    pred = prediction.lower()
    # 检查是否建立了能量守恒或临界能量 E=0 的概念
    energy_check = 'total energy' in pred or 'e = 0' in pred or 'e=0' in pred or 'kinetic energy' in pred
    # 检查是否使用了逃逸速度的比例关系 sqrt(2)
    formula_check = re.search(r'sqrt\(2\)', pred) or '1.414' in pred or 'escape speed' in pred

    if not (energy_check or formula_check):
        return {
            'result': 'fail',
            'message': '未能在推理中找到临界状态设定（如总能量E=0或逃逸速度公式）',
            'evidence': prediction[:200]
        }

    # Step 3: 符号与公式结构校验
    # 检查是否包含 v_final <= sqrt(2) * v_0 的逻辑含义
    if re.search(r'v.*<=.*sqrt\(2\).*v', pred) or re.search(r'v.*=.*sqrt\(2\).*v', pred):
        return {'result': 'pass', 'message': '正确应用了逃逸速度临界条件', 'evidence': prediction[:200]}

    if 'sqrt(2)' in pred and ('v' in pred or 'speed' in pred):
         return {'result': 'pass', 'message': '识别到逃逸速度系数 sqrt(2)', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到相关讨论但无法确定公式准确性', 'evidence': prediction[:200]}

