    if not has_equilibrium:
        return {'result': 'fail', 'message': '未体现通过势能一阶导数确定平衡位置的步骤', 'evidence': prediction[:200]}

    if not has_second_derivative:
        return {'result': 'fail', 'message': '未体现通过势能二阶导数（有效劲度系数）计算频率的逻辑', 'evidence': prediction[:200]}

    # Step 3: 公式结构校验 — 检查是否符合 omega = sqrt(k/m) 形式，其中 k 为二阶导
    # 匹配类似 sqrt(U''/M) 的结构
    formula_pattern = r'sqrt\(.*d\^2.*\/.*m.*\)|sqrt\(.*k\/.*m.*\)'
    if re.search(formula_pattern, pred) or 'sqrt' in pred:
        return {'result': 'pass', 'message': '逻辑完整，包含平衡位置确定与二阶展开频率计算', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑步骤基本具备，但公式表达不明确', 'evidence': prediction[:200]}

