# rule_id=norm_e054444e56855deb | domain=Mechanics | topic=Oscillations and Simple Harmonic Motion
def check_norm_e054444e56855deb_a24653b01ec4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及简谐运动(SHM)中叠放物体的最大接触力/压力
    trigger_keywords = ['简谐', 'SHM', 'harmonic', '振动', 'oscillation']
    target_keywords = ['最大接触力', '最大压力', 'maximum force', 'normal force', 'N_max', 'Nmax']

    is_shm = any(k in (question + context).lower() for k in trigger_keywords)
    is_max_force = any(k in (question + context).lower() for k in target_keywords)

    if not (is_shm and is_max_force):
        return {'result': 'inconclusive', 'message': '未检测到SHM系统最大接触力计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否识别出最大压力在最低点且公式包含加速度项
    pred = prediction.lower()
    # 检查是否提到最低点或加速度向上
    has_location = any(k in pred for k in ['最低点', 'lowest', 'bottom', 'acceleration upward', '加速度向上'])
    # 检查核心公式结构 N = m(g + a)
    has_formula_structure = re.search(r'm.*\(.*g.*\+.*a.*\)', pred) or re.search(r'mg.*\+.*ma', pred)

    if not (has_location or has_formula_structure):
        return {'result': 'fail', 'message': '未正确分析最大压力出现的位置或受力平衡结构', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查 a_max = ω²A 以及 N_max = m(g + ω²A)
    # 匹配 ω^2A 或 w^2A 或 omega^2 * A
    accel_pattern = r'(\omega|w|omega).{0,3}2.{0,3}(A|a)'
    final_pattern = r'm.*\(.*g.*\+.*(\omega|w|omega).{0,3}2.{0,3}(A|a).*\)'

    has_accel = re.search(accel_pattern, pred)
    has_final = re.search(final_pattern, pred)

    if has_final:
        return {'result': 'pass', 'message': '成功识别最大压力公式 N = m(g + ω²A)', 'evidence': prediction[:200]}
    elif has_accel:
        return {'result': 'inconclusive', 'message': '识别出最大加速度但未明确最终压力公式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程不完整', 'evidence': ''}

# rule_id=norm_f1b2ce240cc4c221 | domain=Mechanics | topic=Oscillations and Simple Harmonic Motion
# rule_id=norm_f1b2ce240cc4c221 | domain=Mechanics | topic=Oscillations and Simple Harmonic Motion
def check_norm_f1b2ce240cc4c221_ca8d6fdcbdd9(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及“第N次接触”或“碰撞”且处于“极值/平衡”状态
    trigger_keywords = ['第', '次', '接触', '碰撞', '极值', '最高点', '最低点', '平衡位置']
    q_text = question + context
    if not all(k in q_text for k in ['次', '接触']) and '碰撞' not in q_text:
        return {'result': 'inconclusive', 'message': '未检测到多次接触或碰撞的周期性场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 预测中是否建立了运动时间与周期的等式关系 (nT 或 nT/2)
    # 检查是否包含周期符号 T 以及质量 m 或劲度系数 k (SHM特征)
    pred_text = prediction.lower()
    has_period = 't' in pred_text or '2\\pi' in pred_text or 'sqrt' in pred_text
    if not has_period:
        return {'result': 'fail', 'message': '预测未体现简谐运动周期 T 的计算或关联', 'evidence': prediction[:200]}

    # Step 3: 公式结构校验 — 寻找 t = n*T/2 或类似的整数/半整数倍关系
    # 匹配模式如 n*T, nT/2, (2n+1)T/4 等
    time_relation_pattern = r'(t|\Delta t)\s*=\s*.*(n|k|\d+).*T'
    half_period_pattern = r'T\s*/\s*2|0\.5\s*\*?\s*T'

    found_relation = re.search(time_relation_pattern, prediction) or re.search(half_period_pattern, prediction)

    if found_relation:
        # 进一步检查 required_symbols: T, k, m
        if 't' in pred_text and ('k' in pred_text or 'm' in pred_text):
            return {'result': 'pass', 'message': '已建立运动时间与周期的整数或半整数倍关系', 'evidence': found_relation.group()}
        else:
            return {'result': 'inconclusive', 'message': '检测到时间关系但缺少必要的物理参量(k, m)', 'evidence': prediction[:150]}

    # 如果提到了次数但完全没写时间等式，判定为逻辑缺失
    if re.search(r'第[n\d]次', q_text) and 't' not in pred_text:
        return {'result': 'fail', 'message': '未通过周期性条件推导第N次接触的状态', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了周期性触地约束', 'evidence': ''}

# rule_id=norm_f3e5cedda8641202 | domain=Mechanics | topic=Oscillations and Simple Harmonic Motion
# rule_id=norm_f3e5cedda8641202 | domain=Mechanics | topic=Oscillations and Simple Harmonic Motion
def check_norm_f3e5cedda8641202_564f2894806f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')
    full_text = (question + ' ' + context).lower()
    pred_text = prediction.lower()

    # Step 1: 触发条件 — 检查是否涉及橡皮筋（rubber band）且排除弹簧（spring）干扰
    if 'rubber band' not in full_text:
        return {'result': 'inconclusive', 'message': '未检测到橡皮筋相关描述', 'evidence': ''}
    if 'spring' in full_text and 'rubber band' not in question:
        return {'result': 'inconclusive', 'message': '题目可能主要涉及弹簧而非橡皮筋约束', 'evidence': ''}

    # Step 2: 检查逻辑 — 橡皮筋不能产生推力（即长度小于原长时力为0）
    # 查找是否存在将橡皮筋当作弹簧处理（支持压缩力）的错误建模
    compression_keywords = ['compressed', 'compression', 'push', 'pushing force', 'negative extension']
    has_compression_logic = any(kw in pred_text for kw in compression_keywords)

    # Step 3: 符号与公式校验 — 检查 F = k(L - L0) 的分段一致性
    # 如果预测中提到 L < L0 或类似描述，检查其对应的力是否为 0
    if re.search(r'l\s*<\s*l_?0', pred_text) or re.search(r'length\s*<\s*original', pred_text):
        # 如果在 L < L0 情况下计算了非零力或使用了标准胡克定律 F=kx 而未加限制
        if re.search(r'f\s*=\s*k', pred_text) and not ('0' in pred_text and 'if' in pred_text):
            return {
                'result': 'fail',
                'message': '模型错误：橡皮筋在压缩状态（L < L0）下不应产生弹力/推力',
                'evidence': re.findall(r'.{0,50}l\s*<\s*l_?0.{0,50}', pred_text)[0] if 'l < l0' in pred_text else prediction[:100]
            }

    # 如果明确提到了橡皮筋松弛或力为0，则判定为 pass
    if 'slack' in pred_text or 'force is 0' in pred_text or 'tension only' in pred_text:
        return {'result': 'pass', 'message': '正确考虑了橡皮筋的单向受力约束', 'evidence': 'detected slack/tension-only logic'}

    return {'result': 'inconclusive', 'message': '未能明确判定橡皮筋受力建模是否正确', 'evidence': ''}

# rule_id=norm_ff0d9d4f3bb808a2 | domain=Mechanics | topic=Oscillations and Simple Harmonic Motion
# rule_id=norm_ff0d9d4f3bb808a2 | domain=Mechanics | topic=Oscillations and Simple Harmonic Motion
def check_norm_ff0d9d4f3bb808a2_983964d0310e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及复合系统（如小车、摆、滑块）的简谐运动周期计算
    trigger_keywords = ['period', 'oscillation', 'harmonic', '周期', '简谐', '振动', '摆', 'pendulum']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到简谐运动周期相关场景', 'evidence': ''}

    # Step 2: 检查公式结构是否符合 T = 2π√(m/k) 的量纲逻辑
    # 重点检查是否包含 2π 以及根号下的惯性项与恢复力项的比值
    pred = prediction.lower()
    formula_pattern = r'2\s*pi.*sqrt|2\s*π.*sqrt|sqrt\(.*\/.*\)'
    if not re.search(formula_pattern, pred):
        # 如果没有明显的根号公式，检查是否有关于 M 或 g 的定性描述
        if 'm' not in pred and 'g' not in pred and 'l' not in pred:
            return {'result': 'inconclusive', 'message': '未发现周期公式或关键物理量描述', 'evidence': ''}

    # Step 3: 检查物理趋势逻辑 (M增大->T增大; g增大->T减小)
    # 检查是否存在违反物理直觉的描述
    fail_evidence = []
    # 错误逻辑1: M 增大导致 T 减小 (惯性项在分母的错误)
    if re.search(r'(m|mass|质量).*increase.*(period|t).*decrease', pred) or \
       re.search(r'(m|mass|质量).*增大.*(周期|t).*减小', pred):
        fail_evidence.append("错误地认为质量/惯性增大导致周期减小")

    # 错误逻辑2: g 增大导致 T 增大 (恢复力项在分子的错误)
    if re.search(r'(g|gravity).*increase.*(period|t).*increase', pred) or \
       re.search(r'(g|gravity).*增大.*(周期|t).*增大', pred):
        fail_evidence.append("错误地认为重力加速度/恢复力增大导致周期增大")

    if fail_evidence:
        return {'result': 'fail', 'message': '; '.join(fail_evidence), 'evidence': prediction[:200]}

    # Step 4: 符号覆盖检查 (M, g, l)
    required_symbols = ['m', 'g']
    found_symbols = [s for s in required_symbols if s in pred]
    if len(found_symbols) >= 1 and re.search(r'2.*pi|2.*π', pred):
        return {'result': 'pass', 'message': '周期公式结构与物理趋势符合量纲逻辑', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '证据不足以判定公式正确性', 'evidence': ''}

# rule_id=norm_4b6bdf1a3efaf7f9 | domain=Mechanics | topic=Resonance and Damped Oscillations
# rule_id=norm_4b6bdf1a3efaf7f9 | domain=Mechanics | topic=Resonance and Damped Oscillations
def check_norm_4b6bdf1a3efaf7f9_70a6d60866ed(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及受迫振动、共振频率或最大振幅频率
    trigger_keywords = ['受迫振动', '共振频率', '最大振幅', 'resonance', 'forced oscillation']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到受迫振动共振频率相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否混淆了固有频率 omega_0 或阻尼频率 omega_d
    # 阻尼振动频率通常为 sqrt(w0^2 - beta^2)，而共振频率为 sqrt(w0^2 - 2*beta^2)
    pred = prediction.lower()

    # 检查是否错误地使用了固有频率作为共振频率（忽略阻尼影响）
    if 'omega_0' in pred or '固有频率' in pred:
        if '阻尼' in (question + context) and not re.search(r'2\\beta\^2|2b\^2/\(4M\^2\)|b\^2/\(2M\^2\)', pred):
            # 如果题目有阻尼但解题直接用固有频率，可能存在混淆
            pass # 继续后续更精确的公式检查

    # Step 3: 公式结构校验 — 检查是否包含正确的共振频率表达式 omega_r^2 = omega_0^2 - 2*beta^2
    # 对应 canonical: \omega_r = \sqrt{\frac{k}{M} - \frac{b^2}{2M^2}}
    correct_patterns = [
        r'\\omega_r\s*=\s*\\sqrt{[^}]*k/M\s*-\s*b\^2/\(2M\^2\)}',
        r'\\omega_r\^2\s*=\s*\\omega_0\^2\s*-\s*2\\beta\^2',
        r'\\omega_r\s*=\s*\\sqrt{\\omega_0\^2\s*-\s*2\\beta\^2}',
        r'k/M\s*-\s*b\^2/\(2M\^2\)'
    ]

    found_correct = any(re.search(pat, prediction) for pat in correct_patterns)

    # 检查常见的错误：误用阻尼振动频率公式 (w0^2 - beta^2)
    wrong_patterns = [
        r'\\omega_r\^2\s*=\s*\\omega_0\^2\s*-\s*\\beta\^2',
        r'\\sqrt{k/M\s*-\s*b\^2/\(4M\^2\)}'
    ]
    found_wrong = any(re.search(pat, prediction) for pat in wrong_patterns)

    if found_correct:
        return {'result': 'pass', 'message': '正确使用了受迫振动共振频率公式', 'evidence': '匹配到正确公式结构'}

    if found_wrong:
        return {'result': 'fail', 'message': '混淆了共振频率与阻尼振动频率，共振频率应减去 2*beta^2', 'evidence': '检测到错误的频率修正项'}

    # 如果提到共振频率但没有给出明确公式，且数值直接等于 sqrt(k/M)，在有阻尼情况下判定为 fail
    if '阻尼' in (question + context) and re.search(r'\\omega_r\s*=\s*\\omega_0', pred):
         return {'result': 'fail', 'message': '在有阻尼受迫振动中误将固有频率作为共振频率', 'evidence': 'omega_r = omega_0'}

    return {'result': 'inconclusive', 'message': '未能识别明确的共振频率计算逻辑', 'evidence': ''}

# rule_id=norm_664309dfda09855d | domain=Mechanics | topic=Resonance and Damped Oscillations
# rule_id=norm_664309dfda09855d | domain=Mechanics | topic=Resonance and Damped Oscillations
def check_norm_664309dfda09855d_84f2c0979420(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及质量微小变化 Δm、共振频率偏移及相位移动 Δφ
    trigger_keywords = ['质量', '共振', '相位', '偏移', 'delta', 'Δm', 'Δphi', 'Δφ']
    combined_text = (question + context).lower()
    if not (('共振' in combined_text or 'resonance' in combined_text) and
            ('质量' in combined_text or 'mass' in combined_text or 'm' in combined_text)):
        return {'result': 'inconclusive', 'message': '未检测到共振频率微扰场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否建立了 Δφ 与 Δm 的线性近似关系
    pred = prediction.lower()
    # 检查是否包含相位公式或其导数形式的逻辑要素
    logic_keywords = ['tan', 'phi', 'φ', '导数', '近似', 'linear', 'approx']
    has_logic = any(kw in pred for kw in logic_keywords)

    # Step 3: 符号与公式结构校验
    # 匹配 Δφ ≈ (ω₀/b) * Δm 或 Δφ ∝ Δm 等类似结构
    # 重点检查 symbolic_hint 中的关键符号：b/m, Δm, Δφ, ω₀
    required_symbols = [r'\Delta\s*m', r'\Delta\s*phi', r'\Delta\s*φ', r'omega', r'ω']
    symbol_count = sum(1 for sym in required_symbols if re.search(sym, prediction, re.IGNORECASE))

    # 检查线性比例关系：Δφ 与 Δm 的关联
    linear_relation = re.search(r'(\Delta\s*phi|Δφ).*(\Delta\s*m|Δm)', prediction, re.IGNORECASE)

    if not linear_relation and symbol_count < 2:
        return {'result': 'fail', 'message': '未建立相位移动 Δφ 与质量变化 Δm 的线性近似关联', 'evidence': prediction[:200]}

    if linear_relation and ('b' in pred or 'gamma' in pred or '阻尼' in pred):
        return {'result': 'pass', 'message': '成功识别共振点附近的相位-质量微扰关联', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到相关符号但推导逻辑不完整', 'evidence': prediction[:200]}

# rule_id=norm_9003b8c2680fe3e6 | domain=Mechanics | topic=Resonance and Damped Oscillations
# rule_id=norm_9003b8c2680fe3e6 | domain=Mechanics | topic=Resonance and Damped Oscillations
def check_norm_9003b8c2680fe3e6_1d485cfad410(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及参数激励系统（如摆长变化、重心变化、荡秋千、参数周期变化）
    trigger_keywords = ['摆长', '重心', '周期性变化', '荡秋千', '参数激励', 'parametric', 'swing']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到参数激励或系统参数周期性变化的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找驱动频率 ω 与固有频率 ω0 的关系描述
    # 重点检查是否提到驱动频率是固有频率的两倍 (ω = 2ω0)
    pred = prediction.lower()

    # 匹配 ω = 2ω0 或类似的文本描述（如“两倍”、“2倍”、“double”）
    pattern_formula = r'ω\s*=\s*2\s*ω0|f\s*=\s*2\s*f0|omega\s*=\s*2\s*omega0'
    pattern_text = r'(驱动频率|频率).*?(2倍|两倍|double).*?(固有频率|自然频率)'

    has_formula = re.search(pattern_formula, pred)
    has_text = re.search(pattern_text, pred)

    if has_formula or has_text:
        return {'result': 'pass', 'message': '正确识别参数共振的主共振频率匹配准则 (ω = 2ω0)', 'evidence': has_formula.group(0) if has_formula else has_text.group(0)}

    # Step 3: 检查是否存在错误的频率匹配（例如误认为 ω = ω0）
    wrong_pattern = r'ω\s*=\s*ω0|频率.*?等于.*?固有频率'
    if re.search(wrong_pattern, pred):
        return {'result': 'fail', 'message': '参数激励系统的主共振应在驱动频率为固有频率两倍处，而非相等', 'evidence': '检测到错误的频率匹配描述'}

    return {'result': 'inconclusive', 'message': '未在预测中找到明确的频率匹配关系论证', 'evidence': prediction[:200]}

# rule_id=norm_bef5c00dc00ec40a | domain=Mechanics | topic=Resonance and Damped Oscillations
# rule_id=norm_bef5c00dc00ec40a | domain=Mechanics | topic=Resonance and Damped Oscillations
def check_norm_bef5c00dc00ec40a_17df6cc929e2(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及受迫振动且给出固有频率定义
    # 匹配 omega_0 = sqrt(k/M) 或类似的受迫振动背景
    trigger_keywords = ['omega_0', 'ω_0', 'sqrt(k/M)', 'k/m', '受迫振动', 'forced oscillation']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到受迫振动或固有频率定义场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查最终表达式是否消去了质量 M 或弹性系数 k，统一使用 omega_0
    # 如果 prediction 中依然大量出现 k 而非 omega_0，或者没有将 b/M 作为一个整体或阻尼项处理，则可能未标准化
    pred_clean = prediction.replace(' ', '')

    # 检查是否要求求解 A(omega) 或 phi(omega)
    target_keywords = ['A(', 'phi(', 'φ(', '振幅', '相位']
    if not any(tk in (question + context) for tk in target_keywords):
        return {'result': 'inconclusive', 'message': '题目未明确要求求解振幅或相位函数', 'evidence': ''}

    # Step 3: 符号与公式结构校验
    # 检查是否使用了 omega_0^2 代替 k/M
    has_omega_0 = 'omega_0' in prediction or 'ω_0' in prediction
    # 检查是否依然保留了原始的 k/M 形式（如果已经定义了 omega_0 却不用）
    has_raw_k_m = re.search(r'k/M|k/m', pred_clean)

    # 核心检查：如果公式中包含 sqrt((...)^2 + (...)^2) 结构，检查其内部是否标准化
    # 匹配 A = (F_0/M) / sqrt((omega_0^2 - omega^2)^2 + (b*omega/M)^2) 的特征
    standard_pattern = re.search(r'omega_0\^2-omega\^2', pred_clean)
    damping_pattern = re.search(r'b\*?omega/M|2\*?gamma\*?omega', pred_clean)

    if has_omega_0 and standard_pattern:
        return {'result': 'pass', 'message': '表达式已按固有频率 omega_0 进行标准化', 'evidence': prediction[-200:]}

    if has_raw_k_m and not has_omega_0:
        return {'result': 'fail', 'message': '未按要求使用固有频率 omega_0 标准化，仍保留 k/M 形式', 'evidence': prediction[-200:]}

    return {'result': 'inconclusive', 'message': '无法确定表达式是否完全标准化', 'evidence': ''}

# rule_id=norm_0c275c29ea714811 | domain=Mechanics | topic=Normal Modes and Coupled Oscillations
# rule_id=norm_0c275c29ea714811 | domain=Mechanics | topic=Normal Modes and Coupled Oscillations
def check_norm_0c275c29ea714811_4fcbb485b3a5(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否为 N 个质点、N-1 个弹簧的线性链模型
    trigger_keywords = ['质点', '弹簧', '链', 'coupled', 'oscillation', 'chain', 'masses']
    q_c_text = (question + context).lower()
    if not any(kw in q_c_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到链式多体系统场景', 'evidence': ''}

    # 检查是否明确提到 N 个质点 N-1 个弹簧（自由边界条件）
    if not re.search(r'n\s*个质点.*n-1\s*个弹簧', q_c_text) and 'open boundary' not in q_c_text:
        # 如果没有明确说明是自由边界链，保守返回
        return {'result': 'inconclusive', 'message': '无法确认是否为自由边界链式模型', 'evidence': ''}

    # Step 2: 检查逻辑 — 校验边界质点（1和N）的受力表达式
    pred = prediction.lower()

    # 检查是否存在冗余的 k0 或 kN 项（通常表示固定边界或环状，与 N-1 弹簧矛盾）
    redundant_patterns = [r'k_0', r'k_n', r'k0', r'kn', r'x_0', r'x_{n\+1}']
    for pat in redundant_patterns:
        if re.search(pat, pred):
            return {
                'result': 'fail',
                'message': '检测到冗余的边界项（如k0或kN），不符合N-1个弹簧的链式模型定义',
                'evidence': re.search(pat, pred).group()
            }

    # Step 3: 符号/公式校验 — 检查 F1 和 FN 的结构
    # F1 应只包含 (x2 - x1) 项，FN 应只包含 (xN - x_{N-1}) 项
    f1_match = re.search(r'f_1\s*=\s*k_1\s*\(\s*x_2\s*-\s*x_1\s*\)', pred.replace(' ', ''))
    fn_match = re.search(r'f_n\s*=\s*-k_{n-1}\s*\(\s*x_n\s*-\s*x_{n-1}\s*\)', pred.replace(' ', ''))

    if f1_match or fn_match:
        return {
            'result': 'pass',
            'message': '边界受力表达式符合线性链模型要求',
            'evidence': (f1_match.group() if f1_match else '') + (fn_match.group() if fn_match else '')
        }

    return {'result': 'inconclusive', 'message': '未在预测中找到明确的边界受力表达式', 'evidence': ''}

# rule_id=norm_99805e3772a1211f | domain=Mechanics | topic=Normal Modes and Coupled Oscillations
# rule_id=norm_99805e3772a1211f | domain=Mechanics | topic=Normal Modes and Coupled Oscillations
def check_norm_99805e3772a1211f_7e04eaf76a16(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及耦合振子、弹簧连接或运动方程列写
    trigger_keywords = ['耦合', 'coupled', 'oscillation', 'normal mode', '简正', '弹簧', 'spring', '质点', 'mass']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and re.search(r'u_\{?[ij]?\}?|x_\{?[ij]?\}?', combined_text + prediction)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到耦合振子运动方程场景', 'evidence': ''}

    # Step 2: 检查 prediction 中是否包含运动方程的列写逻辑
    # 寻找类似 m*u'' = ... 或 m*a = ... 的结构
    eq_patterns = [r'm_?\d*\s*\\ddot', r'm_?\d*\s*a_?\d*', r'\\frac{d\^2}{dt\^2}']
    if not any(re.search(p, prediction) for p in eq_patterns):
        return {'result': 'inconclusive', 'message': '预测中未显式列写运动方程', 'evidence': ''}

    # Step 3: 检查受力项符号一致性 -k(u_i - u_j) 或 -ku_i + ku_j
    # 核心逻辑：本位移 u_i 的系数应为负，相邻位移 u_j 的系数应为正
    # 匹配模式如：-k(u_1 - u_2) 或 -k1*u1 + k1*u2
    # 错误模式：k(u_i - u_j) [本位移系数为正] 或 -k(u_i + u_j) [相邻位移系数为负]

    # 检查是否存在错误的符号组合，例如 +k(u_i - u_j) 这种导致不稳定的形式
    # 匹配形如 +k(u_i - u_j) 或 k*(u_i - u_j) 且前面没有负号的情况
    wrong_patterns = [
        r'\+\s*k\s*\(\s*u_([ij12])\s*-\s*u_([ij12])\s*\)', # +k(u_i-u_j)
        r'-\s*k\s*\(\s*u_([ij12])\s*\+\s*u_([ij12])\s*\)', # -k(u_i+u_j)
        r'k_?\d*\s*u_([ij12])\s*-\s*k_?\d*\s*u_([ij12])'   # ku_i - ku_j (i项为正)
    ]

    for wp in wrong_patterns:
        match = re.search(wp, prediction)
        if match:
            return {
                'result': 'fail',
                'message': '耦合项符号错误：本位移系数应为负且与相邻位移符号相反，检测到不符合 -k(ui - uj) 的形式',
                'evidence': match.group(0)
            }

    # 检查正确模式的迹象
    correct_patterns = [
        r'-\s*k\s*\(\s*u_([ij12])\s*-\s*u_([ij12])\s*\)',
        r'k\s*\(\s*u_([ij12])\s*-\s*u_([ij12])\s*\)', # 需结合上下文看是否在等号右侧且带负号，此处简化
        r'-\s*k_?\d*\s*u_([ij12])\s*\+\s*k_?\d*\s*u_([ij12])'
    ]

    for cp in correct_patterns:
        if re.search(cp, prediction):
            return {'result': 'pass', 'message': '运动方程受力项符号符合物理规律', 'evidence': re.search(cp, prediction).group(0)}

    return {'result': 'inconclusive', 'message': '无法确定受力项符号是否正确', 'evidence': ''}

# rule_id=norm_a85c2fe52874aa6e | domain=Mechanics | topic=Normal Modes and Coupled Oscillations
# rule_id=norm_a85c2fe52874aa6e | domain=Mechanics | topic=Normal Modes and Coupled Oscillations
def check_norm_a85c2fe52874aa6e_086e8de22cd1(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及质点系受力之和、位移加权和或质心运动推导
    trigger_keywords = ['受力之和', '合外力', '位移加权', '质心', 'center of mass', 'sum of forces', 'internal force']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到内力系统守恒推导的相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否提及牛顿第三定律或内力抵消 (ΣFi=0)
    pred = prediction.lower()
    # 匹配 ΣFi=0 或类似的内力抵消表述
    force_sum_pattern = r'(\\sum|sum).*F_?i.*=.*0|F_?1.*\+.*F_?2.*=.*0|牛顿第三定律|Newton\'s third law'
    if not re.search(force_sum_pattern, pred):
        return {'result': 'fail', 'message': '推导过程中未明确利用牛顿第三定律或说明内力之和为零', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查是否推导出位移加权和为常数 (Σmi xi = const)
    # 匹配 m_i x_i 的求和形式以及常数项
    mass_pos_pattern = r'(\\sum|sum).*m_?i.*x_?i|m_?1.*x_?1.*\+.*m_?2.*x_?2|质心.*恒定|center of mass.*constant'
    if not re.search(mass_pos_pattern, pred):
        return {'result': 'fail', 'message': '未完成从受力平衡到位移加权和（质心状态）的逻辑推导', 'evidence': prediction[-200:]}

    # Step 4: 综合判定
    if 'const' in pred or '恒量' in pred or '常量' in pred or '=' in pred:
        return {'result': 'pass', 'message': '逻辑推导完整，包含内力抵消与质心运动状态描述', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '推导过程不完整或证据不足', 'evidence': ''}

# rule_id=norm_1d7bbb1a9f7e5463 | domain=Mechanics | topic=Elasticity and Hooke's Law
# rule_id=norm_1d7bbb1a9f7e5463 | domain=Mechanics | topic=Elasticity and Hooke's Law
def check_norm_1d7bbb1a9f7e5463_cd646822697a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及均匀弹簧的局部片段、切割或长度变化后的劲度系数计算
    trigger_keywords = ['弹簧', '切成', '截取', '片段', '长度为', '原长', '劲度系数', 'k']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到弹簧片段劲度系数计算场景', 'evidence': ''}

    # 检查是否涉及长度变化 Δl 或 L_0
    if not re.search(r'l|L|长度', combined_text):
        return {'result': 'inconclusive', 'message': '未检测到长度相关的物理量', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否应用了 k 与 L 成反比的性质
    pred = prediction.lower()
    # 匹配 k' = k * (L/l) 及其变体，如 k1*l1 = k2*l2 或 k 乘以长度比值
    scaling_patterns = [
        r'k\s*\*\s*\(\s*[Ll]_?0?\s*/\s*[Δ\d\.]*l\s*\)',
        r'k\s*\*\s*[Ll]_?0?\s*/\s*[Δ\d\.]*l',
        r'k_?总?\s*\*\s*\(L_?总?\s*/\s*L_?段?\)',
        r'k\s*\*\s*n', # n 为倍数关系
        r'劲度系数.*反比',
        r'k\s*l\s*=\s*constant'
    ]

    found_logic = False
    for pattern in scaling_patterns:
        if re.search(pattern, pred) or re.search(pattern, prediction):
            found_logic = True
            break

    # Step 3: 符号与公式结构校验
    # 如果题目明确给出了长度比例或切割份数，检查是否有乘法修正
    if found_logic:
        return {'result': 'pass', 'message': '已正确应用劲度系数与长度成反比的缩放规则', 'evidence': '检测到缩放逻辑或公式'}

    # 如果预测中直接使用了原 k 而未进行长度修正，则判定为建模错误
    if re.search(r'k\s*=\s*k_?0', pred) and ('切' in combined_text or '段' in combined_text):
         return {'result': 'fail', 'message': '未考虑弹簧切割后劲度系数的变化，应满足 k_segment = k_total * (L_total / L_segment)', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了劲度系数缩放', 'evidence': ''}

# rule_id=norm_242c0daca9f11afb | domain=Mechanics | topic=Elasticity and Hooke's Law
# rule_id=norm_242c0daca9f11afb | domain=Mechanics | topic=Elasticity and Hooke's Law
def check_norm_242c0daca9f11afb_689171a993b1(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及刚性板(rigid plates)连接多个弹性元件(rods/beams)
    trigger_keywords = ['rigid plate', 'rigid bar', 'rigid support', '刚性板', '刚性杆', '刚性支座']
    elastic_keywords = ['rod', 'beam', 'elastic', 'thermal', 'expansion', '杆', '梁', '弹性', '热膨胀']

    text_to_check = (question + context).lower()
    is_triggered = any(kw in text_to_check for kw in trigger_keywords) and any(kw in text_to_check for kw in elastic_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到刚性约束与弹性元件组合场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了位移协调方程 (Compatibility Equation)
    # 核心逻辑是各部分位移相等或总位移受限，且包含热应力和弹性应力的综合考虑
    pred = prediction.lower()
    compatibility_patterns = [
        r'delta\s*l',
        r'displacement',
        r'compatibility',
        r'位移协调',
        r'变形协调',
        r'\\delta',
        r'\\Delta'
    ]

    has_compatibility = any(re.search(p, pred) for p in compatibility_patterns)
    if not has_compatibility:
        return {'result': 'fail', 'message': '未建立几何位移协调方程，仅进行受力分析可能导致错误', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查是否包含 E, F, Delta l, alpha 等关键物理量及其组合关系
    # 期望看到类似 Delta l = L(alpha*Delta T - F/EA) 的结构
    required_symbols = ['e', 'f', 'alpha', 'delta']
    missing_symbols = [s for s in required_symbols if s not in pred and f'\\{s}' not in pred]

    # 如果缺失超过2个核心符号，认为建模不完整
    if len(missing_symbols) >= 2:
        return {'result': 'fail', 'message': f'缺少关键物理量建模: {missing_symbols}', 'evidence': prediction[:200]}

    # 检查是否存在等式关系 (如 delta1 = delta2 或 delta_total = ...)
    if '=' not in pred and 'equal' not in pred and '相等' not in pred:
        return {'result': 'fail', 'message': '未体现位移之间的等量约束关系', 'evidence': prediction[:200]}

    return {'result': 'pass', 'message': '已建立位移协调方程并考虑了相关物理量', 'evidence': re.findall(r'.{0,50}[=].{0,50}', prediction)[0] if '=' in prediction else ''}

# rule_id=norm_2dfb594123c0fa2d | domain=Mechanics | topic=Elasticity and Hooke's Law
# rule_id=norm_2dfb594123c0fa2d | domain=Mechanics | topic=Elasticity and Hooke's Law
def check_norm_2dfb594123c0fa2d_162c214c20a4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“最大载荷”及“永久变形”且包含多个部件
    trigger_keywords = ['maximum load', 'permanent deformation', 'elastic limit', 'yield point']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords)
    # 检查是否涉及多个部件（如 rods, wires, components, members 等复数形式或 A and B）
    has_multiple_parts = re.search(r'\\w+s\\b|and|both|system', combined_text)

    if not (is_triggered and has_multiple_parts):
        return {'result': 'inconclusive', 'message': '未检测到临界载荷或多部件系统场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否识别出“最先达到”应变极限的部件并据此计算 F_max
    pred_lower = prediction.lower()
    # 寻找“first to reach”, "limiting", "minimum of", "whichever occurs first" 等逻辑描述
    logic_keywords = ['first', 'reach', 'limit', 'strain', 'yield', 'beta', 'epsilon']
    logic_match = any(kw in pred_lower for kw in logic_keywords)

    if not logic_match:
        return {'result': 'fail', 'message': '推理过程中未体现寻找系统中“最先达到”应变极限部件的逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查是否包含 epsilon <= beta 或类似的应变不等式约束
    # 匹配 \epsilon, \beta 以及相关的比较逻辑
    symbol_pattern = r'(\\epsilon|epsilon).*?(\\leq|<=|max|limit).*?(\\beta|beta)'
    if re.search(symbol_pattern, prediction, re.IGNORECASE):
        return {'result': 'pass', 'message': '已正确应用临界应变约束逻辑计算最大载荷', 'evidence': re.search(symbol_pattern, prediction, re.IGNORECASE).group(0)}

    # 如果有计算过程但符号不完全匹配，保守返回 inconclusive
    if 'load' in pred_lower and ('=' in pred_lower or 'is' in pred_lower):
        return {'result': 'inconclusive', 'message': '检测到载荷计算但未明确识别应变极限符号约束', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '证据不足以判定逻辑正确性', 'evidence': ''}

# rule_id=norm_58348c66cd5655ab | domain=Mechanics | topic=Elasticity and Hooke's Law
# rule_id=norm_58348c66cd5655ab | domain=Mechanics | topic=Elasticity and Hooke's Law
def check_norm_58348c66cd5655ab_6d7fc990b586(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及热膨胀、承载力或热力耦合场景
    trigger_keywords = ['热膨胀', '受热', '温度变化', 'thermal expansion', 'temperature change', '承载力', 'load capacity']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到热力耦合或承载力计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否识别了总应变包含热应变，并考虑了应变极限 beta
    # 重点检查是否提到受热梁先达到极限或总应变公式
    pred_lower = prediction.lower()
    logic_keywords = ['总应变', '热应变', '应变极限', 'total strain', 'thermal strain', 'limit', 'beta', 'β']
    if not any(kw in pred_lower for kw in logic_keywords):
        return {'result': 'fail', 'message': '推理过程中未明确提及总应变构成或应变极限判定逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查是否包含 alpha, delta T, beta 等关键符号及不等式结构
    # 匹配类似 alpha*delta_T + F/EA <= beta 的结构
    required_symbols = [r'\\alpha', r'\\Delta T', r'\\beta']
    missing_symbols = [s for s in required_symbols if not re.search(s, prediction)]

    if missing_symbols:
        return {'result': 'fail', 'message': f'缺少必要的物理符号: {missing_symbols}', 'evidence': prediction[:200]}

    # 检查不等式逻辑：热应变 + 弹性应变 <= 极限
    formula_pattern = r'(\\alpha.*\\Delta T|\\Delta T.*\\alpha).*\+.*(F|P|\\sigma).*(<=|\\le).*\\beta'
    if re.search(formula_pattern, prediction):
        return {'result': 'pass', 'message': '已正确识别热力耦合下的应变极限判定逻辑', 'evidence': re.search(formula_pattern, prediction).group()}

    return {'result': 'inconclusive', 'message': '检测到相关符号但公式结构不完整', 'evidence': prediction[:200]}

# rule_id=norm_5f7e003de29dbb0b | domain=Mechanics | topic=Elasticity and Hooke's Law
# rule_id=norm_5f7e003de29dbb0b | domain=Mechanics | topic=Elasticity and Hooke's Law
def check_norm_5f7e003de29dbb0b_c57ff4ef074d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及刚体板(rigid plates)连接多个弹性元件的超静定问题
    trigger_keywords = ['rigid plate', 'rigid bar', 'rigid beam', '刚性板', '刚性杆', '刚体板']
    elastic_keywords = ['spring', 'beam', 'rod', 'elastic', '弹簧', '梁', '杆', '弹性']

    text_to_check = (question + context).lower()
    is_triggered = any(kw in text_to_check for kw in trigger_keywords) and any(kw in text_to_check for kw in elastic_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到刚体板连接弹性元件的超静定场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了位移协调方程 (Compatibility Equation)
    # 核心逻辑是各部分形变关系（相等或比例关系）与力平衡方程联立
    pred = prediction.lower()
    compatibility_patterns = [
        r'\\delta', r'\\Delta L', r'deformation', r'displacement', r'elongation',
        r'位移协调', r'形变量', r'伸长量', r'变形关系'
    ]

    has_compatibility = any(re.search(p, pred) for p in compatibility_patterns)
    has_equilibrium = any(re.search(p, pred) for p in [r'force balance', r'equilibrium', r'\\sum F', r'力平衡'])

    if not has_compatibility:
        return {
            'result': 'fail',
            'message': '在处理超静定问题时，未发现位移协调方程（如形变量相等或几何约束关系）',
            'evidence': prediction[:200]
        }

    # Step 3: 符号/公式校验 — 检查 canonical 形式的位移等式或相关符号
    # 检查是否包含 \Delta L 或相关机械/热应变符号
    required_symbols = [r'\\Delta L', r'\\epsilon', r'\\delta']
    symbol_found = any(re.search(sym, prediction) for sym in required_symbols)

    # 检查是否存在等式结构，如 Delta L1 = Delta L2
    equality_structure = re.search(r'\\Delta L_?1?\s*=\s*\\Delta L_?2?', prediction)

    if has_compatibility and has_equilibrium:
        if symbol_found or equality_structure:
            return {'result': 'pass', 'message': '已建立位移协调与力平衡的联立关系', 'evidence': prediction[:150]}
        else:
            return {'result': 'inconclusive', 'message': '虽有文字描述但缺乏明确的位移协调公式', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定是否完整执行了位移协调分析', 'evidence': ''}

# rule_id=norm_942cd09c971dbd47 | domain=Mechanics | topic=Elasticity and Hooke's Law
# rule_id=norm_942cd09c971dbd47 | domain=Mechanics | topic=Elasticity and Hooke's Law
def check_norm_942cd09c971dbd47_aa7825b6d184(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及薄壁容器（球形/圆柱形）及爆破/断裂/抗拉强度
    trigger_keywords = ['vessel', 'container', 'cylinder', 'sphere', 'burst', 'rupture', 'tensile strength', 'thickness', '压力容器', '爆破', '抗拉强度', '壁厚']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到薄壁容器爆破或抗拉强度相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找截面受力平衡方程的特征
    # 核心逻辑：压差产生的力 (P * Area_cross_section) = 材料抗拉力 (Sigma * Area_material)
    # 典型形式：P * pi * r^2 = sigma * 2 * pi * r * t (圆柱/球截面)
    pred = prediction.lower()

    # 检查是否提到了压力与截面积的乘积，以及应力与周长/厚度的乘积
    # 匹配模式：包含 p, r, sigma, t 且存在平衡关系
    has_pressure_force = re.search(r'p.*(r|d|radius|diameter).*\^2', pred) or 'pi*r^2' in pred.replace(' ', '')
    has_tensile_force = re.search(r'(sigma|stress|sigma_t).*2.*pi.*r.*t', pred.replace(' ', '')) or '2*pi*r*t' in pred.replace(' ', '')

    # Step 3: 判定结果
    if has_pressure_force and has_tensile_force:
        return {'result': 'pass', 'message': '检测到正确的截面受力平衡建模逻辑', 'evidence': 'Found force balance components involving P*r^2 and sigma*r*t'}

    # 如果使用了表面积 (4*pi*r^2) 而非截面积 (pi*r^2) 来平衡压力，通常是错误的建模
    if '4*pi*r^2' in pred.replace(' ', '') and 'p' in pred:
         return {'result': 'fail', 'message': '建模错误：可能错误地使用了表面积而非截面积进行受力平衡', 'evidence': 'Detected 4*pi*r^2 in pressure force calculation'}

    # 检查是否完全缺失平衡方程
    if 'sigma' not in pred and 'stress' not in pred:
        return {'result': 'fail', 'message': '未发现应力平衡方程或抗拉强度建模', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定建模方程的准确性', 'evidence': ''}

# rule_id=norm_9d159b05cb88f927 | domain=Mechanics | topic=Elasticity and Hooke's Law
# rule_id=norm_9d159b05cb88f927 | domain=Mechanics | topic=Elasticity and Hooke's Law
def check_norm_9d159b05cb88f927_586caf7ca8a8(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及固体压缩、拉伸或胡克定律建模
    trigger_keywords = ['弹性', '形变', '伸长', '压缩', '胡克定律', 'elastic', 'deformation', 'elongation', 'compression', 'Hooke']
    combined_text = (question + context).lower()
    if not any(k in combined_text for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到固体形变或胡克定律相关建模场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找 ΔL (delta L) 和 L0 (original length) 的提取
    # 匹配形如 ΔL = L0 或 ΔL/L0 >= 1 的逻辑错误
    pred = prediction.lower()

    # 检查是否存在 ΔL = L0 的极端错误描述
    if re.search(r'delta\s*l\s*=\s*l_?0', pred) or re.search(r'形变量等于原长', pred):
        return {'result': 'fail', 'message': '模型崩溃：形变量 ΔL 等于原长 L0，违反小形变假设', 'evidence': prediction[:200]}

    # Step 3: 数值校验 — 提取应变 ε = ΔL/L0 并判断是否远小于 1
    # 尝试匹配类似 "strain = 1.0" 或 "ε = 1" 或 "delta L / L = 1"
    strain_match = re.search(r'(strain|应变|\Delta\s*l\s*/\s*l_?0)\s*(?:=|is|为)\s*([0-9.]+)', pred)
    if strain_match:
        try:
            strain_val = float(strain_match.group(2))
            if strain_val >= 0.9:
                return {'result': 'fail', 'message': f'应变 ε={strain_val} 过大，不符合弹性力学基本假设', 'evidence': strain_match.group(0)}
            elif strain_val < 0.2:
                return {'result': 'pass', 'message': '应变处于合理的小形变范围', 'evidence': strain_match.group(0)}
        except ValueError:
            pass

    # Step 4: 符号覆盖检查
    if 'l_0' in pred and 'delta' in pred and '/' in pred:
        return {'result': 'pass', 'message': '包含必要的应变计算符号且未发现明显逻辑错误', 'evidence': 'L_0, delta L'}

    return {'result': 'inconclusive', 'message': '未能提取到明确的应变数值或比例关系', 'evidence': ''}

# rule_id=norm_9ddf43f44812fde9 | domain=Mechanics | topic=Elasticity and Hooke's Law
# rule_id=norm_9ddf43f44812fde9 | domain=Mechanics | topic=Elasticity and Hooke's Law
def check_norm_9ddf43f44812fde9_21760c8fd775(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及分子间势能（如Morse势、Lennard-Jones势）估算强度
    trigger_keywords = ['势能', 'potential', 'Morse', 'Lennard-Jones', '强度', 'strength', 'dV/dx']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到分子势能求强度的相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 强度是否由最大回复力（dV/dx 的极值）决定
    # 检查是否提到了对势能求导得到力，以及寻找力最大值的过程（通常涉及二阶导数为零）
    pred = prediction.lower()
    has_derivative = re.search(r'd[Vv]/d[xr]|\partial [Vv]/\partial [xr]', pred)
    has_max_force = re.search(r'max|最大|极值|peak', pred) and ('力' in pred or 'force' in pred)

    # 检查是否错误地使用了能量相等点（如结合能直接除以距离）而非力最大值点
    if not has_derivative or not has_max_force:
        return {
            'result': 'fail',
            'message': '未体现通过势能一阶导数（力）的最大值来确定强度的逻辑',
            'evidence': prediction[:200]
        }

    # Step 3: 符号与公式校验 — 检查是否涉及二阶导数为零或公式结构
    # 强度公式通常包含 1/A * max|dV/dx|
    has_second_derivative = re.search(r'd\^2[Vv]/d[xr]\^2|二阶导', pred)
    formula_match = re.search(r'\\sigma|strength|强度.*=.*(1/A|max)', pred)

    if has_second_derivative or formula_match:
        return {
            'result': 'pass',
            'message': '逻辑正确：通过寻找势能一阶导数的极值（或二阶导数为零点）来估算强度',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '检测到求导步骤但未明确判定强度计算的完整性', 'evidence': prediction[:100]}

# rule_id=norm_cba70983ea34de0e | domain=Mechanics | topic=Elasticity and Hooke's Law
# rule_id=norm_cba70983ea34de0e | domain=Mechanics | topic=Elasticity and Hooke's Law
def check_norm_cba70983ea34de0e_d6cd1c7d15ba(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及杨氏模量（Young's Modulus）或弹性模量计算
    trigger_keywords = ['杨氏模量', "Young's modulus", '弹性模量', 'elastic modulus', 'modulus of elasticity']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到杨氏模量相关计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别材料类型（橡胶 vs 金属）并提取预测结果中的量级
    pred = prediction.lower()
    is_rubber = any(kw in (question + context + pred) for kw in ['橡胶', 'rubber', 'elastomer'])
    is_metal = any(kw in (question + context + pred) for kw in ['金属', 'metal', 'steel', 'iron', 'copper', 'aluminum', '钢', '铁', '铜', '铝'])

    # 提取科学计数法或 10^n 形式的数值
    # 匹配如 2e11, 10^11, 10**11, 1.1 * 10^11 等
    magnitude_match = re.findall(r'(?:10\s*[\^\*\*]{1,2}\s*|e|E|10\s*的\s*)(\d{1,2})', pred)

    # Step 3: 量级校验逻辑
    if magnitude_match:
        magnitudes = [int(m) for m in magnitude_match]
        # 检查金属量级 (通常 10-11)
        if is_metal and not any(10 <= m <= 12 for m in magnitudes):
            return {'result': 'fail', 'message': '金属杨氏模量量级异常，通常应在 10^10~10^11 Pa 左右', 'evidence': f'检测到量级: 10^{magnitudes}'}
        # 检查橡胶量级 (通常 6-9)
        if is_rubber and not any(5 <= m <= 9 for m in magnitudes):
            return {'result': 'fail', 'message': '橡胶杨氏模量量级异常，通常应在 10^6~10^9 Pa 左右', 'evidence': f'检测到量级: 10^{magnitudes}'}

    # Step 4: 检查是否误用压强 (如 10^5 Pa 大气压)
    if '10^5' in pred or '10**5' in pred or '1.01' in pred:
        if any(kw in pred for kw in ['atm', 'pressure', '压强', '大气压']):
            return {'result': 'fail', 'message': '疑似误将环境压强或接触压强当作弹性模量', 'evidence': '预测中出现 10^5 Pa 附近的数值且提及压强'}

    # 如果没有明确违反且包含相关计算步骤，则返回 pass 或 inconclusive
    if magnitude_match:
        return {'result': 'pass', 'message': '量级在合理物理范围内', 'evidence': f'检测到量级: 10^{magnitude_match}'}

    return {'result': 'inconclusive', 'message': '未能提取到明确的模量量级数值进行校验', 'evidence': ''}

# rule_id=norm_e4408575a75e7182 | domain=Mechanics | topic=Elasticity and Hooke's Law
# rule_id=norm_e4408575a75e7182 | domain=Mechanics | topic=Elasticity and Hooke's Law
def check_norm_e4408575a75e7182_9c0134e9d0e3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及物体在液体中的浮沉状态及密度参数
    trigger_keywords = ['float', 'submerge', 'density', 'liquid', 'buoyancy', '浮', '沉', '密度', '液体']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到浮力平衡或密度相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否利用阿基米德原理建立平衡方程 (F_b = G)
    # 重点检查是否包含排开体积(V_displaced)、壳体质量(m_shell)或内部质量(m_contents)
    pred = prediction.lower()
    logic_patterns = [
        r'f_?b\s*=\s*g',
        r'rho.*v.*g\s*=',
        r'buoyant force.*weight',
        r'阿基米德',
        r'浮力.*重力'
    ]
    if not any(re.search(p, pred) for p in logic_patterns):
        return {'result': 'fail', 'message': '未发现建立浮力与重力平衡方程的逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查 canonical 公式中的关键物理量
    # ρ_liquid * V_displaced * g = (m_shell + m_contents) * g
    required_symbols = ['v', 'm', 'rho']
    missing_symbols = [s for s in required_symbols if s not in pred]

    # 如果预测中完全没有体现质量守恒或体积排开关系，则判定为逻辑缺失
    if len(missing_symbols) >= 2:
        return {'result': 'fail', 'message': '缺少计算壳体参数所需的关键物理量符号', 'evidence': prediction[:200]}

    # 检查是否尝试解出壳体厚度或体积 (thickness, volume, shell)
    if re.search(r'thickness|volume|shell|厚度|体积|壳', pred):
        return {'result': 'pass', 'message': '成功建立浮力平衡方程并尝试推导壳体参数', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑步骤不完整，无法确定是否正确推导', 'evidence': ''}

# rule_id=norm_124a4ac90ac430fe | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
# rule_id=norm_124a4ac90ac430fe | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
def check_norm_124a4ac90ac430fe_805a28fde453(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否出现 N x N lattice 且给出具体 N 值
    # 匹配如 "3x3 lattice", "4 x 4 lattice", "5*5 lattice" 等模式
    lattice_match = re.search(r'(\d+)\s*[xX*]\s*(\1)\s+lattice', question + context, re.IGNORECASE)
    if not lattice_match:
        return {'result': 'inconclusive', 'message': '未检测到具体的 N x N 晶格描述', 'evidence': ''}

    n_value = int(lattice_match.group(1))
    expected_total = n_value ** 2

    # Step 2: 检查 prediction 中是否涉及总数计算，并核对是否等于 N^2
    # 查找 prediction 中提到的总数、求和项数或实体总数
    pred_text = prediction.lower()
    # 匹配如 "total of 9", "sum over 16 items", "N^2 = 25" 等表达
    total_patterns = [
        rf'total (?:number|units|sites|points|atoms) (?:is|of|=)\s*{expected_total}',
        rf'sum (?:over|of)\s*{expected_total}',
        rf'{n_value}\^2\s*=\s*{expected_total}'
    ]

    found_correct_total = any(re.search(p, pred_text) for p in total_patterns)

    # Step 3: 检查是否存在错误的求和项数（例如漏掉项导致总数不符）
    # 如果提到了总数但不是 expected_total，则判定为 fail
    wrong_total_match = re.search(rf'total (?:number|units|sites|points|atoms) (?:is|of|=)\s*(\d+)', pred_text)
    if wrong_total_match:
        actual_total = int(wrong_total_match.group(1))
        if actual_total != expected_total:
            return {
                'result': 'fail',
                'message': f'晶格单元总数计算错误：期望 {expected_total} (即 {n_value}^2)，实际给出 {actual_total}',
                'evidence': wrong_total_match.group(0)
            }

    if found_correct_total:
        return {'result': 'pass', 'message': f'正确识别并使用了晶格规模 {n_value}x{n_value}={expected_total}', 'evidence': lattice_match.group(0)}

    return {'result': 'inconclusive', 'message': '未在推理过程中明确发现总数校验逻辑', 'evidence': ''}

# rule_id=norm_15eb33f5c7c1e7fb | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
# rule_id=norm_15eb33f5c7c1e7fb | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
def check_norm_15eb33f5c7c1e7fb_8f5d86409e4d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及碳纳米管、石墨烯等单层原子结构
    trigger_keywords = ['碳纳米管', '石墨烯', 'CNT', 'graphene', '单层', 'single-layer']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到碳纳米管或石墨烯等微观结构场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否误用实心体积公式 (V = pi * r^2 * L 或 V = A * d)
    # 重点检查 prediction 是否包含面密度或有效层间距的建模逻辑
    pred_lower = prediction.lower()

    # 检查是否提到了面密度 (surface density / areal density) 或 有效层间距 (effective thickness / d_eff)
    modeling_keywords = ['面密度', 'areal density', 'surface density', '有效厚度', 'effective thickness', 'd_eff', '层间距']
    has_modeling = any(kw in pred_lower for kw in modeling_keywords)

    # Step 3: 符号与公式校验 (ρ = (n * M_c) / (N_A * A * d_eff))
    # 检查是否包含关键符号：A (面积), M_c (单胞质量/摩尔质量), d_eff (有效间距)
    required_symbols = ['A', 'M', 'd']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)

    # 如果 prediction 中直接使用了实心圆柱体积公式计算密度且未提及有效层间距，则判定为建模错误
    if re.search(r'V\s*=\s*\\pi\s*r\^2', prediction) or re.search(r'ρ\s*=\s*m\s*/\s*V', prediction):
        if 'd_eff' not in prediction and '有效' not in prediction:
            return {'result': 'fail', 'message': '可能误用了实心几何体体积公式，未考虑单层结构的有效层间距或面密度建模', 'evidence': prediction[:200]}

    # 检查公式结构是否符合提示中的 canonical 形式
    formula_pattern = r'ρ|rho.*=.*M.*/.*\(.*A.*d.*\)'
    if re.search(formula_pattern, prediction):
        return {'result': 'pass', 'message': '检测到符合规范的微观结构宏观化建模公式', 'evidence': re.search(formula_pattern, prediction).group()}

    if has_modeling or symbol_count >= 2:
        return {'result': 'pass', 'message': '推理中包含了面密度或有效间距的考量', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定建模方式是否正确，建议人工核查', 'evidence': ''}

# rule_id=norm_62c87bd5be31a573 | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
# rule_id=norm_62c87bd5be31a573 | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
def check_norm_62c87bd5be31a573_65d0343635a6(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多边形轮（如正方形、棱柱）在特定路面滚动且质心高度不变
    trigger_keywords = ['正方形', '多边形', '棱柱', 'square wheel', 'polygon', 'rolling']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and ('质心' in combined_text or 'center of mass' in combined_text)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到非圆轮滚动或质心高度相关的物理场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了瞬时半径 r(theta) 与路面 y(x) 的几何匹配关系
    pred_lower = prediction.lower()
    # 检查是否提到几何匹配、半径函数或路面形状函数
    geometry_match = re.search(r'(r\(θ\)|r\(theta\)|radius|路面|y\(x\)|shape|curve)', pred_lower)
    if not geometry_match:
        return {'result': 'fail', 'message': '未建立接触点到轴心的瞬时半径与路面函数的几何匹配关系', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查是否利用 N >= 0 或向心力公式确定临界速度
    # 必须包含 N, M, g, v 等符号，并体现正压力大于等于0的物理约束
    required_symbols = ['n', 'm', 'g', 'v']
    symbol_check = all(re.search(rf'\b{s}\b', pred_lower) for s in required_symbols)

    # 检查临界条件 N >= 0 或 N = Mg - F_c 的逻辑结构
    critical_condition = re.search(r'(n\s*(>=|=>|≥|>)\s*0|n\s*=\s*m.*g|向心力|centripetal)', pred_lower)

    if symbol_check and critical_condition:
        return {'result': 'pass', 'message': '已建立几何匹配方程并利用正压力约束分析临界速度', 'evidence': prediction[:200]}
    elif not critical_condition:
        return {'result': 'fail', 'message': '缺失正压力 N >= 0 的动力学约束分析', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑要素不完整，无法判定', 'evidence': ''}

# rule_id=norm_8d0c6e7eff5c5d6a | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
# rule_id=norm_8d0c6e7eff5c5d6a | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
def check_norm_8d0c6e7eff5c5d6a_128f0220e4b5(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两体质心系动量计算
    # 关键词：质心系、动量、两个物体/质量、相对速度
    trigger_keywords = ['质心系', 'center of mass frame', 'CM frame', '动量', 'momentum']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到质心系动量计算场景', 'evidence': ''}

    # 检查是否涉及两个质量 m1, m2
    if not (re.search(r'm[12]', question + context) or ('质量' in question and '两个' in question)):
        return {'result': 'inconclusive', 'message': '未检测到两体系统', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否使用了折合质量 (reduced mass) 乘以相对速度的逻辑
    # 核心公式特征：m1*m2/(m1+m2) 或 μ (mu) 乘以 (v1-v2)
    pred = prediction.lower()
    reduced_mass_pattern = r'(m1\*?m2|m_1\*?m_2)\s*/\s*\(m1\s*\+\s*m2|m_1\s*\+\s*m_2\)'
    relative_vel_pattern = r'(v1\s*-\s*v2|v_1\s*-\s*v_2|u1\s*-\s*u2)'

    has_reduced_mass = re.search(reduced_mass_pattern, pred) or '折合质量' in pred or 'reduced mass' in pred
    has_relative_vel = re.search(relative_vel_pattern, pred) or '相对速度' in pred

    # Step 3: 综合判定
    if has_reduced_mass and has_relative_vel:
        # 进一步检查公式结构是否匹配 p = mu * delta_v
        if re.search(r'p.*=.*' + reduced_mass_pattern + r'.*' + relative_vel_pattern, pred):
            return {'result': 'pass', 'message': '正确使用了折合质量与相对速度计算质心系动量', 'evidence': re.search(r'.{0,30}' + reduced_mass_pattern + r'.{0,30}', pred).group(0)}
        return {'result': 'pass', 'message': '推理中包含了折合质量和相对速度的要素', 'evidence': 'detected reduced mass and relative velocity terms'}

    # 如果明确在求质心系动量但没有使用该快捷公式，且计算过程复杂或缺失，视为潜在错误或未按规则执行
    if '质心系动量' in (question + context) and not (has_reduced_mass or 'mu' in pred):
        return {'result': 'fail', 'message': '未检测到使用折合质量快捷公式计算质心系动量', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定是否应用了快捷公式', 'evidence': ''}

# rule_id=norm_b032183cd96cacf2 | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
# rule_id=norm_b032183cd96cacf2 | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
def check_norm_b032183cd96cacf2_9e321aacea88(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及可滑动底座、摆动、水平无摩擦等场景
    trigger_keywords = ['底座', '滑块', '光滑水平', '摆动', '小球', '摆长', 'frictionless', 'smooth surface', 'swing']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多体系统水平约束场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否应用了水平方向动量守恒或质心位移关联
    # 核心逻辑通常体现为 M*x = m*(L*sin(theta) - x) 或类似的位移/速度守恒关系
    pred = prediction.lower()
    momentum_keywords = ['动量守恒', 'momentum conservation', '质心', 'center of mass', '水平方向', 'horizontal direction']
    has_momentum_logic = any(kw in pred for kw in momentum_keywords)

    # 检查公式特征：M*dx + m*(dx + l*sin) = 0 或类似的比例关系
    formula_pattern = re.search(r'm[\s\*]*x|M[\s\*]*X|m/(M\+m)|M/(M\+m)', prediction)

    if not (has_momentum_logic or formula_pattern):
        return {'result': 'fail', 'message': '未检测到水平方向动量守恒或质心位移关联的建模逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 symbolic_hint 中的周期公式或质量比例关系
    # 提示公式: T = 2*pi*sqrt( (M/(M+m)) * (l/g) )
    canonical_pattern = r'2\s*\*?\s*pi\s*\*?\s*sqrt\s*\(\s*\(?M\s*/\s*\(M\s*\+\s*m\)\)?\s*\*?\s*\(?l\s*/\s*g\)?\s*\)'
    if re.search(canonical_pattern, prediction, re.IGNORECASE):
        return {'result': 'pass', 'message': '检测到正确的等效摆长或周期修正公式', 'evidence': re.search(canonical_pattern, prediction, re.IGNORECASE).group()}

    # 检查是否提到了质量比例关系 M/(M+m)
    if 'm' in pred and 'm' in pred and ('m+m' in pred.replace(' ', '') or 'm/(m+m)' in pred.replace(' ', '')):
        return {'result': 'pass', 'message': '逻辑中包含质量比例修正，符合水平约束校验', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到相关物理量但公式结构不完整', 'evidence': prediction[:150]}

# rule_id=norm_bdd077775730a74c | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
# rule_id=norm_bdd077775730a74c | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
def check_norm_bdd077775730a74c_ca38609846e3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及具有质量分布的几何板（三角形、矩形、板、刚体）在重力场中的运动
    trigger_keywords = ['三角形', '矩形', '板', '刚体', '质量分布', 'triangle', 'rectangle', 'plate', 'rigid body']
    gravity_keywords = ['重力', '势能', 'gravity', 'potential energy', 'E_p', 'U_g']

    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and any(kw in combined_text for kw in gravity_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '题目未涉及刚体或几何板的重力势能场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查势能公式是否基于质心（Center of Mass / CM）坐标
    # 寻找质心相关的关键词或符号表示
    cm_patterns = [r'质心', 'center of mass', 'cm', 'c.m.', r'y_{cm}', r'h_{cm}', r'y_c', r'h_c']
    pred_lower = prediction.lower()

    has_cm_reference = any(re.search(p, pred_lower) for p in cm_patterns)

    # 检查是否错误地使用了顶点（vertex/vertices）坐标计算整体势能
    vertex_error_patterns = [r'顶点', 'vertex', 'vertices', r'y_1', r'y_2', r'y_3']
    mentions_vertex = any(re.search(p, pred_lower) for p in vertex_error_patterns)

    # Step 3: 符号与公式结构校验 (E_p = sum M_i g y_{cm,i})
    # 匹配类似 Mgy_cm 或 mgh_c 的结构
    formula_pattern = r'm.*g.*(y|h|z)(_?c|cm)'
    has_correct_formula = re.search(formula_pattern, pred_lower) is not null

    if has_cm_reference or has_correct_formula:
        return {'result': 'pass', 'message': '势能计算采用了质心坐标原则', 'evidence': prediction[:200]}

    if mentions_vertex and not has_cm_reference:
        return {'result': 'fail', 'message': '势能计算疑似错误使用顶点坐标而非质心坐标', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定势能计算是否基于质心', 'evidence': ''}

# rule_id=norm_c9af79b7f383f140 | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
# rule_id=norm_c9af79b7f383f140 | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
def check_norm_c9af79b7f383f140_80084b680d04(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及固体、纳米材料或密度的计算场景
    trigger_keywords = ['密度', 'density', '纳米材料', 'nanomaterial', '固体', 'solid', 'kg/m', 'g/cm']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到密度计算或固体材料相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 从 prediction 中提取密度数值及其单位
    # 匹配常见的密度数值表达，如 rho = 1.2e3, 5000 kg/m^3, 0.8 g/cm^3 等
    density_pattern = r'(?:\\rho|density|密度)\s*(?:=|is|为)?\s*([0-9\.eE\-\+^]+)\s*(kg/m\^?3|g/cm\^?3)'
    matches = re.findall(density_pattern, prediction, re.IGNORECASE)

    if not matches:
        return {'result': 'inconclusive', 'message': '未在预测中找到明确的密度数值及单位', 'evidence': ''}

    for val_str, unit in matches:
        try:
            # 处理科学计数法中的 ^ 符号
            clean_val_str = val_str.replace('^', '')
            val = float(clean_val_str)

            # 统一换算为 kg/m^3
            if 'g/cm' in unit.lower():
                val_kg_m3 = val * 1000
            else:
                val_kg_m3 = val

            # Step 3: 数值校验 — 检查是否在 10^2 ~ 2.3*10^4 kg/m^3 范围内 (考虑最重金属锇约 22590)
            if val_kg_m3 < 100 or val_kg_m3 > 23000:
                return {
                    'result': 'fail',
                    'message': f'密度计算结果 {val_kg_m3} kg/m^3 偏离固体常识量级 (10^2~10^4)，可能存在建模或单位换算错误',
                    'evidence': f'value: {val_str}, unit: {unit}'
                }
        except ValueError:
            continue

    # 若提取到的数值都在合理范围内，或无法解析具体数值，则返回 pass 或 inconclusive
    if matches:
        return {'result': 'pass', 'message': '密度数值在合理物理量级范围内', 'evidence': str(matches[0])}

    return {'result': 'inconclusive', 'message': '无法确定密度数值的准确性', 'evidence': ''}

# rule_id=norm_d3bf22f9fa593d4a | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
# rule_id=norm_d3bf22f9fa593d4a | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
def check_norm_d3bf22f9fa593d4a_4b030ab2ee5c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及晶格常数、键长或原子排列计算宏观量
    trigger_keywords = ['晶格', 'lattice', '键长', 'bond length', '原子排列', 'unit cell', '单胞', '晶胞']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到晶格或微观结构相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否通过单位晶格(Unit Cell)推导，而非随意假设宏观尺寸(如长度h)
    # 规则严禁在未给出总量时随意假设宏观尺寸（如长度h）
    pred_lower = prediction.lower()
    # 寻找是否使用了单位晶格相关的推导逻辑（如 n/V, n/A, 密度公式等）
    has_unit_cell_logic = any(kw in pred_lower for kw in ['unit cell', '晶胞', '单胞', '每个原子', 'per atom'])

    # 检查是否违规假设了宏观长度 h 或 L 而没有给出总量关系
    # 如果推导中直接出现 "假设长度为h" 或 "let length be h" 且缺乏单位晶格转换，则视为风险
    macro_assumption = re.search(r'(假设|let|assume).*(长度|length|h|L|H)', pred_lower)

    # Step 3: 符号与公式校验 (rho = n*M / (V_cell * Na))
    # 检查是否包含核心符号：M (摩尔质量), V (体积), n (原子数)
    required_symbols = ['M', 'V', 'n']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    # 逻辑判定
    if macro_assumption and not has_unit_cell_logic:
        return {
            'result': 'fail',
            'message': '推导中随意假设了宏观尺寸(如h/L)，未体现基于单位晶格(Unit Cell)的微观推导逻辑',
            'evidence': re.sub(r'\s+', ' ', prediction[:200])
        }

    if 'n' in prediction and ('V' in prediction or 'a^3' in prediction or 'a^2' in prediction):
        # 匹配密度或原子数密度公式的结构
        formula_pattern = re.search(r'n.*/.*(V|a\^3|a\^2|L\^3)', prediction)
        if formula_pattern:
            return {'result': 'pass', 'message': '推导符合微观结构参数一致性，使用了单位晶格比例关系', 'evidence': formula_pattern.group()}

    if len(missing_symbols) > 1:
        return {'result': 'fail', 'message': '缺少必要的微观结构推导符号(M, V_cell, n)', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定推导逻辑是否严格遵循单位晶格一致性', 'evidence': ''}

# rule_id=norm_8414f57364c49049 | domain=Mechanics | topic=Dynamics of Systems of Particles
# rule_id=norm_8414f57364c49049 | domain=Mechanics | topic=Dynamics of Systems of Particles
def check_norm_8414f57364c49049_93584430e8df(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否包含动态过程描述（如 falling from rest, in the process of）
    trigger_keywords = ['falling from rest', 'in the process of', 'accelerating', 'moving', 'dynamic']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到动态过程描述，规则不适用', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否错误使用了静力平衡公式 T = mg 或 T = sum(mg)
    # 动力学场景下，若直接令张力等于重力之和而忽略加速度，则判定为逻辑错误
    pred_lower = prediction.lower()
    # 匹配类似 T = mg, T = m1g + m2g, T = \sum mg 等模式
    static_equilibrium_pattern = r'T\s*=\s*(\sum\s*)?m(_?\w+)?\s*g'

    # 检查是否提到了牛顿第二定律或加速度相关分析
    has_acceleration_analysis = any(kw in pred_lower for kw in ['ma', 'newton', 'acceleration', 'f=ma', 'f = ma'])

    if re.search(static_equilibrium_pattern, pred_lower) and not has_acceleration_analysis:
        return {
            'result': 'fail',
            'message': '在动态过程中错误使用了静力平衡公式 T=Σmg，未考虑系统加速度或牛顿第二定律',
            'evidence': re.search(static_equilibrium_pattern, pred_lower).group(0)
        }

    # Step 3: 符号覆盖检查 — 检查是否包含必要的物理量符号 T 和 g
    if 'T' in prediction and 'g' in prediction:
        if has_acceleration_analysis:
            return {'result': 'pass', 'message': '已包含动力学分析，未发现静力平衡误用', 'evidence': 'Detected acceleration analysis'}

    return {'result': 'inconclusive', 'message': '无法确定是否误用静力平衡公式', 'evidence': ''}

# rule_id=norm_20d11d3ce665c77f | domain=Electromagnetism | topic=Coulomb's Law and Electric Fields
# rule_id=norm_20d11d3ce665c77f | domain=Electromagnetism | topic=Coulomb's Law and Electric Fields
def check_norm_20d11d3ce665c77f_d395a3e50d6e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及线电荷、柱对称场或电势函数 V(r)
    trigger_keywords = ['线电荷', '柱对称', '无限长', '电势', 'V(r)', 'potential', 'cylindrical']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到线电荷或柱对称电势场景', 'evidence': ''}

    # Step 2: 检查 prediction 中是否出现了包含分母常数的对数项，如 ln(r/r0)
    # 匹配形如 ln(r/a), ln(r/R), ln(r/r0) 等结构
    log_pattern = r'ln\s*\(\s*r\s*/\s*[a-zA-Z0-9_]+\s*\)'
    pred_text = prediction.lower()

    # 如果 prediction 中存在 ln(r/r0) 且同时存在常数项 K 或 C
    if re.search(log_pattern, pred_text) and re.search(r'\+\s*[KC]', pred_text):
        # Step 3: 检查是否进行了冗余剥离（即是否将 ln(r/r0) 拆解为 ln(r) - ln(r0) 并合并）
        # 如果公式中依然保留了 ln(r/r0) + K 的形式，则视为未剥离冗余
        # 理想形式应为 ln(r) + K' 或类似结构
        evidence_match = re.search(log_pattern + r'\s*\+\s*[KC]', pred_text)
        if evidence_match:
            return {
                'result': 'fail',
                'message': '检测到对数项中存在可合并至常数项的冗余因子（如 ln(r/r0) + K），应简化为 ln(r) + K\'。',
                'evidence': evidence_match.group(0)
            }

    # Step 4: 验证是否已经化简为 ln(r) + K 形式
    if re.search(r'ln\s*\(\s*r\s*\)\s*\+\s*[KC]', pred_text):
        return {'result': 'pass', 'message': '电势项已完成冗余剥离，保持最简形式', 'evidence': 'ln(r) + K'}

    return {'result': 'inconclusive', 'message': '未能明确识别电势公式的化简状态', 'evidence': ''}

