# rule_id=norm_2a4529a60c2088fe | domain=Electromagnetism | topic=Coulomb's Law and Electric Fields
def check_norm_2a4529a60c2088fe_912c660d2861(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
