    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及离解能 (E_dis) 与晶体总势能 (V_total) 的转换关系
    trigger_keywords = ['离解能', '结合能', 'dissociation energy', 'binding energy', 'lattice energy', 'E_dis', 'V_total', '势能']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到离解能或晶体势能相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查吸引势能项是否为负，以及 E_dis = -V_total 的逻辑关系
    pred = prediction.lower()
    # 检查是否提到吸引势能为负 (V_att < 0)
    att_neg_pattern = r'(吸引势|V_att|V_a).*?(负|negative|-\s*\d|小于\s*0)'
    # 检查离解能与总势能的符号关系 E_dis = -V_total 或 E_dis + V_total = 0
    relation_pattern = r'(E_dis|E_{dis}|离解能).*?(-|负).*?(V_total|V_{total}|总势能|V_0|V\(r_0\))'

    has_att_neg = re.search(att_neg_pattern, pred)
    has_relation = re.search(relation_pattern, pred) or re.search(r'(V_total|V_{total}).*?(-|负).*?(E_dis|E_{dis})', pred)

    # Step 3: 符号覆盖与公式结构检查 (基于 symbolic_hint)
    # 检查是否包含核心符号 E_dis, V_att, V_rep
    required_symbols = ['E', 'V'] # 简化匹配，防止 LaTeX 格式干扰
    symbol_check = all(sym in prediction for sym in required_symbols)

    if has_relation:
        # 如果明确写出了 E_dis = -V_total 且 V_total 为负，则 pass
        if 'positive' in pred or '大于0' in pred or '>' in pred:
             return {'result': 'pass', 'message': '离解能与势能符号逻辑一致', 'evidence': re.search(relation_pattern, pred).group(0) if has_relation else ''}
        return {'result': 'pass', 'message': '检测到正确的能量转换逻辑', 'evidence': 'E_dis = -V_total'}

    if not has_relation and ('E_dis' in pred and 'V' in pred):
        # 如果提到了两者但没有体现负号关系，判定为逻辑风险
        return {'result': 'fail', 'message': '未明确离解能与总势能的相反数关系 (E_dis = -V_total)', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足以判定符号一致性', 'evidence': ''}

