# rule_id=norm_38359db4d279cded | domain=Electromagnetism | topic=Coulomb's Law and Electric Fields
def check_norm_38359db4d279cded_129394e722f9(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及马德隆常数、晶格能或多层邻居求和
    trigger_keywords = ['马德隆', 'Madelung', '晶格能', 'lattice energy', 'lattice potential', 'nearest neighbor', '邻居', '求和']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到晶格能求和或马德隆常数计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证系数（配位数）与距离因子（分母）的匹配性
    # 重点检查是否存在将不同距离项（如 r0 和 sqrt(2)r0）强行合并分母的逻辑错误
    pred = prediction.lower()

    # 提取常见的晶格几何因子：1, sqrt(2), sqrt(3), 2 等
    # 检查是否存在类似 (6+12)/r0 这种将不同距离的配位数直接相加的情况
    # 典型的 NaCl 结构前三项：6/1, 12/sqrt(2), 8/sqrt(3)

    # 检查是否提到了多层邻居但公式中分母单一化
    if re.search(r'\\sum|\\frac', pred):
        # 如果出现了求和符号，但分母中没有体现出根号因子（对于非简立方/体心/面心等常见结构）
        # 这是一个保守的启发式检查：如果提到了多层（如 second, third neighbors）但没有 sqrt(2) 或 sqrt(3)
        if ('second' in pred or '次近邻' in pred) and not (re.search(r'sqrt\(2\)|1\.414', pred)):
            return {'result': 'fail', 'message': '计算次近邻贡献时未发现正确的距离因子（如 sqrt(2)）', 'evidence': prediction[:200]}

        if ('third' in pred or '第三近邻' in pred) and not (re.search(r'sqrt\(3\)|1\.732|2', pred)):
            return {'result': 'fail', 'message': '计算第三近邻贡献时未发现正确的距离因子（如 sqrt(3) 或 2）', 'evidence': prediction[:200]}

    # Step 3: 符号覆盖检查 (r_0, r_i, z_i)
    required_symbols = ['r_0', 'r', 'z']
    # 允许 LaTeX 格式或普通文本格式
    symbol_count = 0
    for sym in required_symbols:
        if sym in pred or sym.upper() in pred:
            symbol_count += 1

    if symbol_count >= 2:
        # 如果公式结构看起来合理（有求和且分母有根号或不同项）
        if re.search(r'\d+/\s*sqrt|\d+/\s*1\.', pred) or re.search(r'\\frac{\s*\d+\s*}{\s*\\sqrt', pred):
            return {'result': 'pass', 'message': '公式中体现了配位数与几何距离因子的对应关系', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定求和项与距离因子是否严格匹配', 'evidence': ''}

