# rule_id=norm_92c00466f468bce4 | domain=Electromagnetism | topic=Coulomb's Law and Electric Fields
# rule_id=norm_92c00466f468bce4 | domain=Electromagnetism | topic=Coulomb's Law and Electric Fields
def check_norm_92c00466f468bce4_79b833f99b0c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')
    full_text = (question + context).lower()
    pred_text = prediction.lower()

    # Step 1: 触发条件 — 检查是否涉及带电体在空气与液体介质中悬挂且偏角不变的场景
    trigger_keywords = ['偏角', '角度', 'angle', 'theta', 'θ']
    medium_keywords = ['液体', '介质', '油', '浸入', 'liquid', 'oil', 'dielectric']
    if not (any(k in full_text for k in trigger_keywords) and any(k in full_text for k in medium_keywords)):
        return {'result': 'inconclusive', 'message': '未检测到电介质中悬挂偏角平衡场景', 'evidence': ''}
    if '不变' not in full_text and '相同' not in full_text and 'same' not in full_text:
        return {'result': 'inconclusive', 'message': '未明确提及偏角保持不变', 'evidence': ''}

    # Step 2: 检查逻辑 — 核心公式 ρ/(ρ - ρ0) = εr 或其等价形式 (mg/Fe = (mg-f)/Fe')
    # 检查关键物理量符号：ε_r (相对介电常数), ρ (物体密度), ρ_0 (液体密度)
    required_patterns = [
        r'ε_?r',
        r'ρ',
        r'ρ_?0|ρ_?l|ρ_?w'  # 液体密度常用下标
    ]

    # 检查公式结构：ρ / (ρ - ρ0) = εr
    formula_pattern = r'ρ\s*/\s*\(\s*ρ\s*-\s*ρ_?0\s*\)\s*=\s*ε_?r'

    # Step 3: 判定结果
    found_symbols = [p for p in required_patterns if re.search(p, pred_text)]

    if re.search(formula_pattern, pred_text.replace(' ', '')):
        return {'result': 'pass', 'message': '检测到正确的密度与介电常数平衡关系式', 'evidence': prediction}

    if len(found_symbols) < 2:
        return {'result': 'fail', 'message': '推理过程中缺失关键物理量（密度或相对介电常数）', 'evidence': prediction[:200]}

    # 检查是否提到了浮力与库仑力减小的抵消关系
    if ('浮力' in pred_text or 'buoyancy' in pred_text) and ('介电常数' in pred_text or 'dielectric' in pred_text):
        if '/' in pred_text or '=' in pred_text:
             return {'result': 'pass', 'message': '包含物理逻辑描述且有定量计算迹象', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定推理是否完全符合偏角不变平衡律', 'evidence': ''}

# rule_id=norm_9c1e77a161edf3da | domain=Electromagnetism | topic=Coulomb's Law and Electric Fields
# rule_id=norm_9c1e77a161edf3da | domain=Electromagnetism | topic=Coulomb's Law and Electric Fields
def check_norm_9c1e77a161edf3da_49fe1b6223f4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及三个或更多电荷/质点在同一直线上
    # 匹配关键词如：三个电荷、三点、同一直线、共线、q1/q2/q3等
    trigger_keywords = ['三个', '3个', '三点', '三个电荷', '同一直线', '共线', 'q1', 'q2', 'q3']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多体共线电荷场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否考虑了任意一对电荷间的相互作用力 (F_net = sum(k*qi*qj/r^2))
    # 检查 prediction 是否只关注了中心点，而忽略了边缘电荷间的力
    pred = prediction.lower()
    # 寻找库仑定律公式特征：k*q*q/r^2 或类似的变体
    coulomb_pattern = r'k.*q[123i].*q[123j]|q[123i]q[123j]/r|r\^2'
    interactions = re.findall(coulomb_pattern, pred)

    # 如果只出现了一组相互作用（例如只算了两两中的一对），或者没有体现求和过程，则可能建模不完整
    # 重点检查是否提到了所有可能的配对，或者使用了合力/叠加原理
    if '合力' not in pred and '平衡' not in pred and '叠加' not in pred and len(interactions) < 2:
        return {'result': 'fail', 'message': '建模不完整：未检查任意一对电荷间的相互作用力，可能仅考虑了部分受力', 'evidence': prediction[:200]}

    # Step 3: 符号覆盖检查 (q_i, q_j, r_ij)
    required_symbols = ['q', 'r', 'k']
    missing_symbols = [s for s in required_symbols if s not in pred]
    if len(missing_symbols) == len(required_symbols):
        return {'result': 'fail', 'message': '缺少必要的物理量符号(q, r, k)进行受力分析', 'evidence': prediction[:150]}

    # 如果 prediction 中包含了求和公式或多个相互作用项，则视为通过
    if re.search(r'\+|sum|Σ|f12|f23|f13', pred):
        return {'result': 'pass', 'message': '已执行多体受力完整性检查', 'evidence': '检测到受力叠加或多组相互作用项'}

    return {'result': 'inconclusive', 'message': '无法确定受力分析是否完整', 'evidence': ''}

# rule_id=norm_cd1212c1c8e27ba4 | domain=Electromagnetism | topic=Coulomb's Law and Electric Fields
# rule_id=norm_cd1212c1c8e27ba4 | domain=Electromagnetism | topic=Coulomb's Law and Electric Fields
def check_norm_cd1212c1c8e27ba4_7b5fc90694ae(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及点电荷系统的势能计算或最短距离（通常涉及能量守恒）
    trigger_keywords = ['势能', 'potential energy', '最短距离', 'closest distance', 'q1', 'q2']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到点电荷势能相关场景', 'evidence': ''}

    # Step 2: 检查公式结构 U = k*q1*q2/r 的符号逻辑
    # 查找是否提到了同号/异号电荷及其对应的势能正负
    pred_lower = prediction.lower()

    # 提取电荷性质：同号(same sign/positive product) vs 异号(opposite sign/negative product)
    is_same_sign = '同号' in pred_lower or 'same sign' in pred_lower or 'positive' in pred_lower
    is_opp_sign = '异号' in pred_lower or 'opposite sign' in pred_lower or 'negative' in pred_lower

    # 检查公式 U = k*q1*q2/r 的符号一致性
    # 如果提到同号电荷，势能应为正；如果提到异号电荷，势能应为负
    if 'q1*q2' in pred_lower or 'k*q1*q2' in pred_lower:
        # 检查是否存在符号矛盾，例如：同号电荷势能为负，或异号电荷势能为正
        if ('同号' in pred_lower or 'same sign' in pred_lower) and ('势能为负' in pred_lower or 'energy is negative' in pred_lower):
            return {'result': 'fail', 'message': '同号电荷势能符号判断错误，应为正值', 'evidence': prediction}
        if ('异号' in pred_lower or 'opposite sign' in pred_lower) and ('势能为正' in pred_lower or 'energy is positive' in pred_lower):
            return {'result': 'fail', 'message': '异号电荷势能符号判断错误，应为负值', 'evidence': prediction}

    # Step 3: 检查公式形式是否符合 U = k*q1*q2/r
    formula_match = re.search(r'U\s*=\s*k\s*\*?\s*q1\s*\*?\s*q2\s*/\s*r', prediction, re.IGNORECASE)
    if formula_match:
        # 如果公式正确且没有明显的逻辑矛盾，则视为通过
        return {'result': 'pass', 'message': '势能公式结构及符号逻辑正确', 'evidence': formula_match.group()}

    # 如果没有明确的公式但逻辑描述正确，也尝试给出 pass
    if (is_same_sign and '正' in pred_lower) or (is_opp_sign and '负' in pred_lower):
         return {'result': 'pass', 'message': '电荷性质与势能正负号逻辑匹配', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '未能明确提取势能符号逻辑', 'evidence': ''}

# rule_id=norm_e7c24452753dcf5e | domain=Electromagnetism | topic=Coulomb's Law and Electric Fields
# rule_id=norm_e7c24452753dcf5e | domain=Electromagnetism | topic=Coulomb's Law and Electric Fields
def check_norm_e7c24452753dcf5e_2c2a30e5b84d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两物体碰撞、最近距离或动能转化场景
    trigger_keywords = ['最近距离', 'closest approach', 'minimum distance', '碰撞', 'collision']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到两物体达到最近距离的物理场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证 prediction 是否提及动能转化或质心动能/相对动能的概念
    pred_lower = prediction.lower()
    logic_keywords = ['动能', 'kinetic energy', '势能', 'potential energy', '质心', 'center of mass']
    if not any(kw in pred_lower for kw in logic_keywords):
        return {'result': 'fail', 'message': '在最近距离判定中缺失动能与势能转化的逻辑分析', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查是否包含相对动能转化为势能的等效表达 (1/2 * mu * v_rel^2 = Delta_U)
    # 匹配动能表达式 (1/2 mv^2) 以及势能变化或能量守恒的结构
    energy_pattern = r'(1/2|0\.5).*m.*v\^2|E_k|\Delta U|U_p'
    mu_v_rel_pattern = r'v_.*rel|v_1.*v_2|m_1.*m_2/(m_1\+m_2)'

    has_energy_expr = re.search(energy_pattern, prediction, re.IGNORECASE)
    has_rel_motion = re.search(mu_v_rel_pattern, prediction, re.IGNORECASE)

    if has_energy_expr and ('相等' in prediction or 'equal' in pred_lower or '=' in prediction):
        return {'result': 'pass', 'message': '逻辑符合最近距离处相对动能完全转化为势能的物理规则', 'evidence': re.search(r'.{0,50}(=|equal|相等).{0,50}', prediction).group(0) if '=' in prediction else prediction[:100]}

    if not has_energy_expr:
        return {'result': 'fail', 'message': '未能识别到正确的能量转化公式或符号表达 (mu, v_rel, U)', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '存在能量讨论但公式完整性不足以判定', 'evidence': prediction[:100]}

# rule_id=norm_2be0396613b09c89 | domain=Electromagnetism | topic=Electric Potential and Potential Energy
# rule_id=norm_2be0396613b09c89 | domain=Electromagnetism | topic=Electric Potential and Potential Energy
def check_norm_2be0396613b09c89_97f10291ba0b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及电势、半径 R 和电荷 Q 的化简场景
    trigger_keywords = ['电势', '电位', 'potential', 'electric potential']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords) or 'r' not in combined_text.lower() or 'q' not in combined_text.lower():
        return {'result': 'inconclusive', 'message': '未检测到电势化简或相关物理量场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别 prediction 中是否存在量纲不一致的加减项（如 Q + QR 或 Q + Q/R）
    # 重点检查加减号两边的项，如果一项含 R 而另一项不含 R，则量纲必不一致
    pred = prediction.replace(' ', '')
    # 匹配类似 Q + Q*R, Q - Q*R, Q + k*Q*R 等模式
    dimension_mismatch_patterns = [
        r'[qQ]\s*[\+\-]\s*[qQ][rR]', # Q +/- QR
        r'[qQ][rR]\s*[\+\-]\s*[qQ]', # QR +/- Q
        r'[qQ]\s*[\+\-]\s*[qQ]/[rR]', # Q +/- Q/R
        r'[qQ]/[rR]\s*[\+\-]\s*[qQ]'  # Q/R +/- Q
    ]

    for pattern in dimension_mismatch_patterns:
        match = re.search(pattern, pred, re.IGNORECASE)
        if match:
            return {
                'result': 'fail',
                'message': '检测到电势表达式中各项量纲不一致（如 Q 与 QR 直接相加减），违反物理常识',
                'evidence': match.group(0)
            }

    # Step 3: 符号覆盖检查 — 检查是否包含必要的物理量符号 Q, R, k
    required = ['q', 'r']
    missing = [s for s in required if s not in pred.lower()]
    if missing:
        return {'result': 'inconclusive', 'message': '预测中缺失必要的物理符号', 'evidence': f'缺失: {missing}'}

    # 如果公式结构符合 [kQ/R] 的基本特征，则视为通过
    if re.search(r'[kK].*[qQ]/[rR]', pred) or re.search(r'[qQ]/.*[rR]', pred):
        return {'result': 'pass', 'message': '电势表达式量纲结构基本合理', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '无法确定量纲一致性', 'evidence': ''}

