    energy_keywords = ['work', 'energy', 'potential', '功', '能', '势能']
    has_energy = any(kw in target_text for kw in energy_keywords)
    # 匹配变量平方的模式，如 d_0^2, x^2, r^2, (d0)**2
    has_square_term = re.search(r'[a-zA-Z]_?\d*\^2|pow\([a-zA-Z]_?\d*,\s*2\)', answer + prediction)

    if not (has_energy and has_square_term):
        return {'result': 'inconclusive', 'message': '未检测到功或能量的二次项表达需求', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找线性回复力 (F=kx) 或线性场强分布 (E=kr) 的建模过程
    pred = prediction.lower()
    # 寻找积分表达式或线性力/场描述
    linear_force_pattern = re.search(r'f\s*=\s*k\s*\*?\s*[a-zA-Z]|field\s+is\s+proportional|线性|正比', pred)
    integral_pattern = re.search(r'\\int|integral|积分', pred)

    # Step 3: 符号校验 — 检查是否包含关键符号 d_0 和 k (或类似系数)
    required_symbols = ['d_0', 'k']
    missing_symbols = [s for s in required_symbols if s not in prediction and s.replace('_', '') not in prediction]

    if not (linear_force_pattern or integral_pattern):
        return {
            'result': 'fail',
            'message': '模型未体现线性力或场强的积分过程，难以支撑二次项能量表达式的来源',
            'evidence': prediction[:200]
        }

    if len(missing_symbols) == len(required_symbols):
        return {
            'result': 'fail',
            'message': f'缺少关键物理量符号: {missing_symbols}',
            'evidence': prediction[:150]
        }

    # Step 4: 验证公式结构是否符合 W = 1/2 k d^2 逻辑
    if re.search(r'1/2|0\.5|\\frac{1}{2}', prediction) and has_square_term:
        return {'result': 'pass', 'message': '模型包含线性积分逻辑且量纲匹配正确', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到相关要素但推导逻辑完整性不确定', 'evidence': ''}

