    periodic_keywords = ['collision', 'loss', 'period', 'cycle', '碰撞', '损耗', '周期', '每次']

    q_c_text = (question + context).lower()
    is_triggered = any(kw in q_c_text for kw in trigger_keywords) and any(kw in q_c_text for kw in periodic_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '题目未明确涉及周期性稳态速度平衡场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了速度映射关系 v_{n+1} = f(v_n) 并令其相等求解
    pred = prediction.lower()
    # 检查是否包含速度相等的稳态思想 (v_n = v_{n+1} 或 v_s)
    steady_state_logic = re.search(r'v_{?n\+1}?|v_{?n}?|v_s|v_{?steady}?', pred)
    mapping_logic = re.search(r'=|equal|same|constant', pred)

    if not (steady_state_logic and mapping_logic):
        return {
            'result': 'fail',
            'message': '未检测到建立速度映射关系或稳态平衡条件 (v_{n+1} = v_n)',
            'evidence': prediction[:200]
        }

    # Step 3: 符号/公式校验 — 检查是否包含损耗系数 eta (\eta) 或类似的比例关系
    # 根据 symbolic_hint，重点检查 v_s 和 \eta 的关联
    has_eta = '\\eta' in prediction or 'eta' in pred
    has_vs = 'v_s' in prediction or 'v_{s}' in prediction or 'v_m' in prediction

    # 检查是否存在类似 v = eta * v + delta_v 的结构特征
    formula_structure = re.search(r'v.*=.*\\eta.*v', prediction) or re.search(r'v_s.*=.*', prediction)

    if has_eta and has_vs and formula_structure:
        return {'result': 'pass', 'message': '成功建立稳态速度平衡方程并包含必要物理参数', 'evidence': prediction[:200]}

    if not formula_structure:
        return {
            'result': 'fail',
            'message': '推理中缺失稳态速度的解析表达式或平衡方程',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '逻辑存在但符号表达不完整', 'evidence': prediction[:200]}

