    # Step 2: 检查逻辑 — 验证是否利用标量叠加原理（部分电荷产生的电势与总电荷成比例）
    pred = prediction.lower()
    # 寻找电荷比例关系 q/Q 或 (n/m)Q 等描述
    ratio_pattern = r'(q/Q|Q/q|比例|占|\d+/\d+|ratio)'
    # 寻找电势叠加或比例计算的描述
    logic_pattern = r'(V|U).*=.*(q/Q|\(q/Q\)|n/m).*V|V_.*=.*V_.*\*|电势.*(等于|为).*总.*(比例|几分之几)'

    has_ratio = re.search(ratio_pattern, pred) or re.search(r'[qQ].*[\/÷].*[Qq]', pred)
    has_logic = re.search(logic_pattern, pred) or '叠加' in pred or 'scalar' in pred

    if not (has_ratio or has_logic):
        return {
            'result': 'fail',
            'message': '预测未体现利用电荷比例进行电势缩放的标量叠加逻辑',
            'evidence': prediction[:200]
        }

    # Step 3: 符号与公式结构校验
    # 检查是否包含 V_{piece} = (q/Q) * V_{full} 的类似结构
    formula_match = re.search(r'[VU].*\*.*[qQ].*/.*[Qq]', prediction) or re.search(r'[qQ].*/.*[Qq].*\*.*[VU]', prediction)

    if formula_match:
        return {
            'result': 'pass',
            'message': '检测到符合缩放律的电势计算逻辑和公式结构',
            'evidence': formula_match.group()
        }

    return {'result': 'inconclusive', 'message': '逻辑描述存在但缺乏明确的比例公式', 'evidence': prediction[:150]}

