    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及直流电路中电容器的稳态电荷量或电压计算
    trigger_keywords = ['steady state', 'steady-state', '稳态', 'long time', '电荷量', 'charge on the capacitor']
    if not any(kw in (question + context).lower() for kw in trigger_keywords) or 'capacitor' not in (question + context).lower():
        return {'result': 'inconclusive', 'message': '未检测到直流电路电容稳态计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 确认是否提到电容器支路电流为0，以及是否应用了 KVL 或并联电压相等原则
    pred_lower = prediction.lower()
    # 检查是否意识到稳态下电容支路无电流 (I=0)
    has_zero_current = any(kw in pred_lower for kw in ['current is zero', 'no current', 'i = 0', 'open circuit', '断路', '电流为0'])
    # 检查是否使用了 KVL 或电压等效关系
    has_voltage_logic = any(kw in pred_lower for kw in ['kvl', 'kirchhoff', 'voltage law', 'potential difference', 'parallel', '并联', '电势差'])

    if not (has_zero_current or has_voltage_logic):
        return {'result': 'fail', 'message': '未体现稳态下电容支路电流为零或电压等效的判定逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查 V_C = |sum E - sum IR| 的结构特征
    # 匹配类似 V = E - IR 或 V = IR 的结构
    formula_pattern = r'(V|U|E|I|R|\\sum)'
    symbols_found = re.findall(formula_pattern, prediction)

    # 检查是否包含必要的物理量符号
    required_symbols = ['E', 'I', 'R']
    symbol_count = sum(1 for s in required_symbols if s in prediction)

    if symbol_count >= 2 or re.search(r'[VEU]\s*=\s*.*[IR]', prediction):
        return {'result': 'pass', 'message': '逻辑符合稳态电容电压判定准则', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程不够详尽，无法确定是否严格遵循 KVL 计算', 'evidence': prediction[:200]}

