# rule_id=norm_415e96cfa1389a60 | domain=Electromagnetism | topic=DC Circuits and Kirchhoff's Laws
def check_norm_415e96cfa1389a60_e97daa62bea7(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题干是否包含“points X and Y are short connected”或类似短路描述
    trigger_keywords = ['short connected', 'short-circuited', 'short circuit', 'points .* and .* are shorted']
    if not any(re.search(kw, (question + context).lower()) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到短路连接的相关描述', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证 prediction 是否将短接点视为等电势点 (phi_H = phi_B)
    # 检查是否包含电势相等的逻辑表述或符号表示
    potential_eq_pattern = r'\\phi_([A-Za-z0-9])\s*=\s*\\phi_([A-Za-z0-9])|potential\s+at\s+.*\s+is\s+the\s+same|equal\s+potential'
    if not re.search(potential_eq_pattern, prediction, re.IGNORECASE):
        return {
            'result': 'fail',
            'message': '未在推理中体现短接点电势相等的逻辑或等效电路简化',
            'evidence': prediction[:200]
        }

    # Step 3: 符号校验 — 检查 symbolic_hint 中要求的 phi 符号及等式结构
    # 重点检查是否出现了 phi_H = phi_B 或类似的电势相等公式
    if '\\phi' in prediction:
        if re.search(r'\\phi_[A-Za-z0-9]\s*=\s*\\phi_[A-Za-z0-9]', prediction):
            return {'result': 'pass', 'message': '成功识别短路点并应用了等电势简化逻辑', 'evidence': re.search(r'\\phi_[A-Za-z0-9]\s*=\s*\\phi_[A-Za-z0-9]', prediction).group()}

    # 如果有文字描述但缺乏公式，且逻辑合理，则返回 inconclusive 以示保守
    if 'same potential' in prediction.lower() or 'equivalent circuit' in prediction.lower():
        return {'result': 'inconclusive', 'message': '有简化趋势但缺乏明确的电势相等公式', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确执行了短路归零化简', 'evidence': ''}

