# rule_id=norm_68c647a14c10ea2c | domain=Electromagnetism | topic=DC Circuits and Kirchhoff's Laws
# rule_id=norm_68c647a14c10ea2c | domain=Electromagnetism | topic=DC Circuits and Kirchhoff's Laws
def check_norm_68c647a14c10ea2c_dbae00c5c3fc(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否为含电容器、电阻器且涉及开关/稳态/电势计算的直流电路题
    trigger_keywords = ['电容', 'capacitor', '稳态', 'steady state', '电势', 'potential', '开关', 'switch']
    combined_text = (question + context).lower()
    if not (any(kw in combined_text for kw in ['电容', 'capacitor']) and any(kw in combined_text for kw in ['电势', 'potential', '电压', 'voltage'])):
        return {'result': 'inconclusive', 'message': '未检测到含容电路电势计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否仅错误地使用了电阻分压，而忽略了电荷守恒
    # 孤立节点（由电容极板连接的节点）在稳态下电流为0，必须用电荷守恒 ΣQ = ΣC(V-Vi) = 0
    pred = prediction.lower()
    # 检查是否提到电荷守恒或电量相关的公式结构
    has_charge_conservation = any(kw in pred for kw in ['电荷守恒', 'charge conservation', 'q=', 'sigma q', 'sum of charge'])
    # 检查公式特征：C * (V - V_i) 或类似的电势差乘电容形式
    has_potential_diff_formula = re.search(r'[Cc]\s*\*?\s*\(\s*[Vv]\s*[-–]\s*[Vv]', pred) or re.search(r'[Cc]\d*\(V', pred)

    # 如果题目包含多个电容且涉及节点电势，但预测中只看到电阻比例(R1/R2)而无电荷方程，则判定为建模错误
    if '电阻' in combined_text and ('分压' in pred or re.search(r'R\d/R\d', pred)):
        if not (has_charge_conservation or has_potential_diff_formula):
            return {'result': 'fail', 'message': '在含容电路稳态分析中未应用电荷守恒定律，可能错误地仅使用了电阻分压', 'evidence': prediction[:200]}

    # Step 3: 符号与公式结构校验
    if has_charge_conservation and has_potential_diff_formula:
        return {'result': 'pass', 'message': '已检测到电荷守恒方程及电势差表达，建模逻辑正确', 'evidence': re.search(r'.{0,50}[Cc].{0,50}', pred).group(0) if re.search(r'[Cc]', pred) else ''}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了电荷守恒方程', 'evidence': ''}

# rule_id=norm_6ef9931ab0c48336 | domain=Electromagnetism | topic=DC Circuits and Kirchhoff's Laws
# rule_id=norm_6ef9931ab0c48336 | domain=Electromagnetism | topic=DC Circuits and Kirchhoff's Laws
def check_norm_6ef9931ab0c48336_7ac5c843aa14(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否为RC电路稳态下的电势计算场景
    trigger_keywords = ['steady state', '稳态', '电势', 'potential', 'voltage at point']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到RC电路稳态电势计算场景', 'evidence': ''}
    if 'capacitor' not in combined_text and '电容' not in combined_text:
        return {'result': 'inconclusive', 'message': '未检测到电容元件', 'evidence': ''}

    # Step 2: 检查逻辑要素 — 稳态下电容支路电流为0及KCL应用
    pred = prediction.lower()
    # 检查是否提到稳态下电容相当于断路或电流为0
    steady_logic = ['current is 0', 'no current', 'open circuit', '电流为0', '断路', '没有电流']
    has_steady_logic = any(logic in pred for logic in steady_logic)

    # 检查是否应用了节点电压法或KCL方程
    kcl_logic = ['kcl', 'kirchhoff', 'node voltage', '节点电压', '流入等于流出', 'sum']
    has_kcl_logic = any(logic in pred for logic in kcl_logic)

    if not has_steady_logic and 'i =' not in pred:
        return {'result': 'fail', 'message': '未明确稳态下电容支路电流为0的物理事实', 'evidence': prediction[:200]}

    # Step 3: 公式结构校验 — 检查是否存在类似 sum((V_i - V_node)/R_i) = 0 的结构
    # 匹配形如 (V-V)/R 或 (U-V)/R 的项
    kcl_pattern = r'([VU]\w*\s*-\s*[VU]\w*)\s*/\s*R\w*'
    if not re.search(kcl_pattern, prediction, re.IGNORECASE) and not has_kcl_logic:
        return {'result': 'fail', 'message': '未发现基于KCL的节点电压方程列式', 'evidence': prediction[:200]}

    # Step 4: 结论判定
    if has_steady_logic and (has_kcl_logic or re.search(kcl_pattern, prediction, re.IGNORECASE)):
        return {'result': 'pass', 'message': '遵循RC稳态判定准则，包含电流判定与KCL列式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程不完整，无法确认是否严格执行准则', 'evidence': ''}

