def check_norm_94338324b04776e8_e1574ee12c16(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 题干明确引用图像但未提供图像描述或拓扑矩阵
    trigger_keywords = ['as shown in the image', 'as shown in the figure', '如图所示', '见图']
    has_image_ref = any(kw in (question + context).lower() for kw in trigger_keywords)
    # 检查 context 或 question 中是否包含拓扑描述（如节点连接、矩阵等）
    has_topology = re.search(r'(node|matrix|connection|topology|节点|矩阵|连接)', (question + context).lower())

    if not has_image_ref or has_topology:
        return {'result': 'inconclusive', 'message': '未检测到缺失图像引用的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 禁止通过 assume 或 common scenario 构造电路拓扑
    pred_lower = prediction.lower()
    forbidden_patterns = [
        r'assume (the|a) (circuit|topology|connection)',
        r'common (scenario|setup|configuration)',
        r'假设(电路|拓扑|连接)',
        r'常见(场景|设置|配置)'
    ]

    for pattern in forbidden_patterns:
        if re.search(pattern, pred_lower):
            return {
                'result': 'fail',
                'message': '在缺失图像信息时，禁止通过假设或常见场景构造电路拓扑',
                'evidence': re.search(pattern, pred_lower).group()
            }

    # Step 3: 检查是否识别为信息缺失或寻找基尔霍夫约束而非直接计算
    valid_logic = [
        r'(missing|insufficient) (information|data|image)',
        r'kirchhoff',
        r'kvl|kcl',
        r'基尔霍夫',
        r'信息不足',
        r'缺失图像'
    ]

    if any(re.search(p, pred_lower) for p in valid_logic):
        return {'result': 'pass', 'message': '正确识别信息缺失或尝试建立基尔霍夫约束', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '推理过程中未明确体现拓扑构建逻辑', 'evidence': ''}

# rule_id=norm_d9360b23e3f45a1b | domain=Electromagnetism | topic=DC Circuits and Kirchhoff's Laws
# rule_id=norm_d9360b23e3f45a1b | domain=Electromagnetism | topic=DC Circuits and Kirchhoff's Laws
def check_norm_d9360b23e3f45a1b_88b0efcadd2d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及超立方体、n维网格或高度对称电阻框架
    trigger_keywords = ['超立方体', 'n维网格', 'n-dimensional', 'hypercube', '对称电阻', '等电势', '等势点', '缩点']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到高维对称网络或等电势缩点场景', 'evidence': ''}

    # Step 2: 检查逻辑要素 — 是否包含分层、拓扑距离或并联化简步骤
    pred = prediction.lower()
    logic_keywords = ['层', '距离', '并联', '等势', '等电势', 'layer', 'distance', 'parallel']
    found_logic = [kw for kw in logic_keywords if kw in pred]

    if len(found_logic) < 2:
        return {
            'result': 'fail',
            'message': '解题过程缺失关键的对称性分层或等电势缩点逻辑',
            'evidence': prediction[:200]
        }

    # Step 3: 符号与公式校验 — 检查是否包含 R_{eq} = \sum (1/N) R 形式的结构
    # 匹配类似 1/n, 1/k, R/n 等分式求和特征
    formula_pattern = r'(\\sum|\\frac{1}{[Nn]|\\d+}|R/[Nn]|R/\\d+)'
    if not re.search(formula_pattern, prediction):
        # 如果没有显式公式，检查是否有分母相关的数值描述
        if not re.search(r'分层|连接数|棱数', pred):
            return {
                'result': 'fail',
                'message': '未发现符合特征的等效电阻化简公式或层间连接分析',
                'evidence': prediction[-200:]
            }

    # Step 4: 验证结果特征 — 检查是否提到总棱数或对称性因子
    if re.search(r'总棱数|总边数|total edges|symmetry', pred + context):
        return {'result': 'pass', 'message': '逻辑完整，包含对称分层与等电势化简步骤', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '逻辑步骤基本存在，但关键特征匹配不充分', 'evidence': ''}

# rule_id=norm_f8956fa5959db950 | domain=Electromagnetism | topic=DC Circuits and Kirchhoff's Laws
# rule_id=norm_f8956fa5959db950 | domain=Electromagnetism | topic=DC Circuits and Kirchhoff's Laws
def check_norm_f8956fa5959db950_126bea1ef0e1(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题干是否仅包含基础电阻电路且未提及运放
    # 排除包含 Op-Amp, Operational Amplifier, 运放, 放大器, 或典型运放符号描述的题目
    op_amp_keywords = ['op-amp', 'operational amplifier', '运放', '放大器', 'triangle', '三角形']
    q_text = (question + context).lower()
    if any(kw in q_text for kw in op_amp_keywords):
        return {'result': 'inconclusive', 'message': '题干已包含运放相关描述，不适用此规则', 'evidence': ''}

    # 确认题干包含电阻或接地等基础直流电路描述
    dc_keywords = ['resistor', 'resistance', 'ground', 'ohm', '电阻', '接地', '欧姆']
    if not any(kw in q_text for kw in dc_keywords):
        return {'result': 'inconclusive', 'message': '未检测到基础直流电路场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查解题步骤是否错误引入了运放模型假设
    pred = prediction.lower()
    # 检查是否包含 "虚地" (Virtual Ground) 或 "理想运放" (Ideal Op-Amp) 的假设
    invalid_assumptions = [
        'virtual ground', 'virtual short', 'ideal op-amp',
        '虚地', '虚短', '理想运放', '运放模型'
    ]

    found_violation = []
    for term in invalid_assumptions:
        if term in pred:
            found_violation.append(term)

    if found_violation:
        # 提取包含违规词汇的片段作为证据
        match = re.search(f".{{0,30}}({'|'.join(found_violation)}).{{0,30}}", pred)
        evidence = match.group(0) if match else prediction[:100]
        return {
            'result': 'fail',
            'message': f'在无运放的电路题中错误引入了运放假设: {found_violation}',
            'evidence': evidence
        }

    # Step 3: 结论归纳
    if 'kirchhoff' in pred or 'ohm' in pred or 'kcl' in pred or 'kvl' in pred:
        return {'result': 'pass', 'message': '解题步骤符合基础电路分析，未引入无关模型', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '未发现明显的建模错误或合规证据', 'evidence': ''}

# rule_id=norm_319934efd8651ef6 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
# rule_id=norm_319934efd8651ef6 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
def check_norm_319934efd8651ef6_2d9e77196011(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及交流电相位控制、晶闸管、导通角或平均功率计算
    trigger_keywords = ['晶闸管', '导通角', '相位控制', 'thyristor', 'firing angle', 'conduction angle', 'dimmer', '调光器', '平均功率', 'average power']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到交流电相位控制或平均功率计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别积分过程或结果中是否包含 sin(2θ) 或 sin(2ωt) 形式的补偿项
    # 交流功率积分 ∫sin²(x)dx = x/2 - sin(2x)/4，若只保留线性项则为错误
    pred = prediction.lower()

    # 匹配 sin(2*theta), sin(2wt), sin(2α) 等形式，允许空格和括号变化
    sin_2theta_pattern = r'sin\s*\(\s*2\s*[\u03b1\u03b2\u03b8\u03c9t\w]+\s*\)'
    has_sin_2theta = re.search(sin_2theta_pattern, pred) is not null

    # 检查是否只进行了线性积分（如只看到 theta/2 或 alpha/2 而没有减项）
    # 如果预测中出现了积分符号或功率公式推导，但缺失了 sin(2x) 项，则判定为 fail
    if '∫' in pred or 'integral' in pred or '/' in pred:
        if not has_sin_2theta:
            # 进一步确认是否在计算平均功率 P
            if 'p =' in pred or 'p=' in pred or '功率' in pred:
                return {
                    'result': 'fail',
                    'message': '在交流功率积分中缺失 sin(2θ) 补偿项，可能仅保留了线性相位项，导致计算不完整',
                    'evidence': prediction[-200:]
                }

    # Step 3: 符号覆盖校验
    if has_sin_2theta and ('/' in pred or '1/2' in pred or '1/4' in pred):
        return {
            'result': 'pass',
            'message': '检测到包含 sin(2θ) 形式的积分补偿项，符合功率计算完整性要求',
            'evidence': re.search(sin_2theta_pattern, pred).group(0)
        }

    return {'result': 'inconclusive', 'message': '无法确定积分项是否完整', 'evidence': ''}

# rule_id=norm_6f7eba3d1f2d5d28 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
# rule_id=norm_6f7eba3d1f2d5d28 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
def check_norm_6f7eba3d1f2d5d28_699440fd6740(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及线圈(Coil)或电动机(Motor)的热功率计算
    trigger_keywords = ['线圈', '电动机', 'coil', 'motor', '内阻', '热功率']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到线圈或电动机热功率相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 判定是否错误地将总功率(UI)或阻抗(Z)直接等同于热功率计算中的电阻项
    pred = prediction.lower()
    # 检查是否提到了 I^2*r 或 P_热 的区分逻辑
    has_thermal_formula = re.search(r'i\^2\s*\*?\s*r', pred) or '热功率' in pred
    # 检查是否提到了功率因数 cos 或 相量关系
    has_phasor_logic = 'cos' in pred or '相位' in pred or 'phi' in pred or '功率因数' in pred

    # 如果预测中直接用 P = U*I 计算热功率且没有提到内阻 r，则判定为逻辑错误
    if re.search(r'p\s*=\s*u\s*\*?\s*i', pred) and not (has_thermal_formula or has_phasor_logic):
        return {'result': 'fail', 'message': '未区分总功率与热功率，或未考虑内阻与阻抗的区别', 'evidence': prediction[:200]}

    # Step 3: 符号覆盖检查 (P, I, V/U, r)
    required_symbols = ['i', 'p', 'r']
    missing_symbols = [s for s in required_symbols if s not in pred]

    if not missing_symbols and (has_thermal_formula or has_phasor_logic):
        return {'result': 'pass', 'message': '正确使用了热功率计算公式并考虑了内阻/相量关系', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程中关于功率分配的描述不明确', 'evidence': ''}

# rule_id=norm_7257de6542bc3bf5 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
# rule_id=norm_7257de6542bc3bf5 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
def check_norm_7257de6542bc3bf5_6de2ea33dbf7(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及微小电容 Cq、寄生电容 C0 以及反射系数差值 ΔΓ 的最大化
    trigger_keywords = ['反射系数', 'ΔΓ', 'delta gamma', 'reflection coefficient', 'C_q', 'C_0', 'C0', 'Cq']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到微小电容反射优化场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否利用 LC 谐振频率作为工作频率
    pred_lower = prediction.lower()
    resonance_pattern = r'(谐振|resonance|LC|1/\(2\*pi\*sqrt\(L\*C\)\))'
    if not re.search(resonance_pattern, pred_lower):
        return {'result': 'fail', 'message': '未明确提及利用LC谐振频率进行优化', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查阻抗匹配是否涉及电容比 (Cq/C0) 的缩放关系
    # 检查 canonical: Z_match ~ (C_q/C_0) Z_0 的结构特征
    scaling_pattern = r'(C_?q\s*/\s*C_?0|C_?0\s*/\s*C_?q|电容比|capacitance ratio)'
    impedance_match = r'(Z_?0|阻抗匹配|impedance match|Z_?match)'

    has_scaling = re.search(scaling_pattern, prediction)
    has_impedance = re.search(impedance_match, prediction)

    if has_scaling and has_impedance:
        return {'result': 'pass', 'message': '模型正确应用了基于电容比缩放的阻抗匹配优化规则', 'evidence': re.search(scaling_pattern, prediction).group(0)}

    if not has_scaling:
        return {'result': 'fail', 'message': '阻抗匹配未体现微小电容与寄生电容的变换比缩放逻辑', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑要素不完整，无法判定', 'evidence': ''}

# rule_id=norm_755ad0868f9a73a5 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
# rule_id=norm_755ad0868f9a73a5 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
def check_norm_755ad0868f9a73a5_f45b78d15b4b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及受控开关（晶闸管、调光器、斩波、截断波形）及平均功率计算
    trigger_keywords = ['晶闸管', 'thyristor', '调光器', 'dimmer', '截断', '斩波', 'chopped', '导通角', 'firing angle']
    if not any(kw in (question + context).lower() for kw in trigger_keywords) or '平均功率' not in (question + context + prediction):
        return {'result': 'inconclusive', 'message': '未检测到受控开关波形功率计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别积分表达式并检查系数是否为周期归一化（1/T 或 1/2pi 或 1/pi）
    # 错误逻辑通常会将系数写成 1/(t_end - t_start) 即仅针对导通区间平均
    pred = prediction.replace(' ', '')
    # 匹配类似 1/T * integral 或 (1/T) * integral 的结构
    # 常见的周期表示：T, 2pi, pi, 2π, π, 0.02(50Hz)
    period_pattern = r'(1/(T|2pi|2π|pi|π|0\.02|2\*pi))'
    integral_pattern = r'integral|∫'

    # 如果 prediction 中出现了积分计算，但没有正确的周期归一化系数
    if re.search(integral_pattern, pred, re.IGNORECASE):
        # 检查是否存在 1/T 类的归一化项
        if not re.search(period_pattern, pred, re.IGNORECASE):
            # 进一步检查是否错误地使用了导通区间长度作为分母，例如 1/(t2-t1)
            if re.search(r'1/\([tαθ].*-[tαθ].*\)', pred):
                return {'result': 'fail', 'message': '平均功率计算错误：积分系数应为完整周期T，而非仅为导通时间区间长度', 'evidence': prediction}
            return {'result': 'inconclusive', 'message': '检测到积分但未发现明确的周期归一化系数', 'evidence': prediction}

    # Step 3: 符号覆盖检查
    required_symbols = ['T', 't_end', 't_start']
    # 考虑到实际题目可能用 alpha, beta 等表示角度，这里做宽松匹配
    if '1/T' in pred or '1/(2*pi)' in pred or '1/pi' in pred:
        return {'result': 'pass', 'message': '已执行正确的周期归一化处理', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '无法确定归一化逻辑是否正确', 'evidence': ''}

# rule_id=norm_8324873514d15a73 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
# rule_id=norm_8324873514d15a73 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
def check_norm_8324873514d15a73_5bb7d6f7ae85(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否为RC或RL并联电路的总电流计算场景
    trigger_keywords = ['并联', 'parallel', 'RC', 'RL', '总电流', 'total current']
    content_to_check = (question + context).lower()
    is_triggered = any(kw in content_to_check for kw in trigger_keywords) and ('电流' in content_to_check or 'current' in content_to_check)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到RC/RL并联电路电流合成场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否存在错误的代数相加 (I = IR + IC)
    # 交流电中，电阻和电容/电感电流相位差90度，直接相加是典型错误
    pred = prediction.replace(' ', '')
    error_patterns = [
        r'I=I_?R\+I_?[CL]',
        r'I_total=I_?R\+I_?[CL]',
        r'I=I_?C\+I_?R'
    ]
    for pattern in error_patterns:
        if re.search(pattern, pred, re.IGNORECASE):
            return {'result': 'fail', 'message': '错误地使用了代数相加而非矢量合成（勾股定理）', 'evidence': re.search(pattern, pred, re.IGNORECASE).group()}

    # Step 3: 公式校验 — 检查是否使用了勾股定理公式 I = sqrt(IR^2 + IC^2)
    # 匹配 sqrt(IR^2 + IC^2) 或 (IR^2 + IC^2)^0.5 等形式
    correct_patterns = [
        r'I(_total)?=sqrt\(I_?R\^2\+I_?[CL]\^2\)',
        r'I(_total)?=\(I_?R\^2\+I_?[CL]\^2\)\^0\.5',
        r'I(_total)?=\(I_?R\^2\+I_?[CL]\^2\)\^\(1/2\)',
        r'I^2=I_?R\^2\+I_?[CL]\^2'
    ]

    found_correct = False
    for pattern in correct_patterns:
        if re.search(pattern, pred, re.IGNORECASE):
            found_correct = True
            evidence_str = re.search(pattern, pred, re.IGNORECASE).group()
            break

    if found_correct:
        return {'result': 'pass', 'message': '正确使用了正交支路电流合成公式', 'evidence': evidence_str}

    # Step 4: 辅助角公式检查 (针对瞬时值)
    if 'sin' in pred or 'cos' in pred:
        if 'phi' in pred or 'atan' in pred or 'arctan' in pred:
            return {'result': 'pass', 'message': '检测到瞬时值合成的辅助角处理', 'evidence': '包含三角函数合成逻辑'}

    return {'result': 'inconclusive', 'message': '未能明确判定电流合成逻辑的正确性', 'evidence': prediction[:100]}

# rule_id=norm_8ef95d8ed4ee4711 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
# rule_id=norm_8ef95d8ed4ee4711 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
def check_norm_8ef95d8ed4ee4711_e5adf3f37f07(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“阻抗相等”且包含不同性质元件（R, L, C）
    trigger_keywords = ['阻抗相等', 'impedance', 'equal', 'same impedance']
    components = ['R', 'L', 'C', '电阻', '电感', '电容']
    q_c = (question + context).lower()

    has_trigger = any(kw in q_c for kw in trigger_keywords)
    has_multiple_components = sum(1 for comp in components if comp.lower() in q_c) >= 2

    if not (has_trigger and has_multiple_components):
        return {'result': 'inconclusive', 'message': '未检测到阻抗相等或多元件场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 区分阻抗模相等与复阻抗相等
    pred = prediction.lower()
    # 检查是否错误地直接令复阻抗相等（如 Z_R = Z_C 而非 |Z_R| = |Z_C|）
    # 典型错误：R = 1/(j*w*C) 或 R = -j/(w*C) 这种直接等式，或者忽略了 j
    direct_complex_eq = re.search(r'z_?[rlc]\s*=\s*z_?[rlc]', pred)
    modulus_mention = any(kw in pred for kw in ['模', 'magnitude', 'absolute', '|', 'sqrt'])

    # 如果预测中直接将不同元件的复阻抗设为相等，且没有体现模的概念，则判定为概念错误
    if direct_complex_eq and not modulus_mention:
        return {
            'result': 'fail',
            'message': '未能区分阻抗模相等与复阻抗相等，不同性质元件复阻抗不能直接等值',
            'evidence': re.search(r'.{0,30}z_?[rlc]\s*=\s*z_?[rlc].{0,30}', prediction).group() if direct_complex_eq else prediction[:100]
        }

    # Step 3: 符号与公式校验 — 检查是否正确使用了模相等公式 R = 1/(wC) 或 R = wL
    # 匹配 R = 1/(w*C) 或 R = w*L 等模相等形式
    correct_mod_eq = re.search(r'r\s*=\s*(1\s*/\s*\(?ω\s*c\)?|ω\s*l)', pred)
    # 检查是否保留了相位差（j 或复数形式）
    has_phase = any(kw in pred for kw in ['j', 'i', 'angle', 'phase', 'exp', 'phi'])

    if correct_mod_eq:
        return {'result': 'pass', 'message': '正确处理了阻抗模相等关系', 'evidence': correct_mod_eq.group()}

    if not has_phase and ('j' in (question + answer)):
        return {'result': 'fail', 'message': '计算中丢失了相位信息或复数算子 j', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确区分了阻抗性质', 'evidence': ''}

# rule_id=norm_997a880e55d908d7 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
# rule_id=norm_997a880e55d908d7 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
def check_norm_997a880e55d908d7_a4b33bdcf9d0(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及无限重复单元、梯形电路或晶格波动问题
    trigger_keywords = ['infinite', 'ladder', 'periodic', 'lattice', 'repeating', '无限', '梯形', '周期', '晶格']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到无限重复单元或周期性结构场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否应用了布洛赫定理（Bloch\'s Theorem）或相位因子 e^{j Phi}
    # 搜索关键词：Bloch, phase factor, phase shift, 相位因子, 布洛赫
    pred_lower = prediction.lower()
    bloch_keywords = ['bloch', 'phase factor', 'phase shift', 'e^{j', 'e^{i', 'exp(j', 'exp(i', '相位因子']
    has_bloch_logic = any(kw in pred_lower for kw in bloch_keywords)

    # Step 3: 符号/公式校验 — 检查 V_{n+1} = V_n * e^{j Phi} 形式的解
    # 匹配类似 V_{n+1}/V_n = exp(...) 或 V_n = V_0 * exp(j*n*phi) 的结构
    formula_patterns = [
        r'[Vv]_\{?n\+1\}?\s*=\s*[Vv]_\{?n\}?\s*\*?\s*e\^\{?[ij]',
        r'[Vv]_\{?n\}?\s*=\s*[Vv]_0\s*\*?\s*e\^\{?[ij].*n',
        r'e\^\{?[ij]\s*[Pp]hi\}?',
        r'exp\([ij]\s*[Pp]hi\)'
    ]
    has_formula = any(re.search(pat, prediction) for pat in formula_patterns)

    if has_bloch_logic or has_formula:
        return {'result': 'pass', 'message': '已应用布洛赫定理或相位因子处理周期性结构', 'evidence': re.search(r'.{0,50}(bloch|e\^\{?[ij]|exp\().{0,50}', prediction, re.I).group(0) if has_bloch_logic else ''}

    # 如果明确在讨论周期性解但缺失相位因子关系，则判定为逻辑缺失
    if 'solution' in pred_lower or 'current' in pred_lower or 'voltage' in pred_lower:
        return {'result': 'fail', 'message': '未检测到布洛赫定理形式的解（相邻单元相位差关系）', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了周期性对称性解', 'evidence': ''}

# rule_id=norm_c8275fb1fcdbad3b | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
# rule_id=norm_c8275fb1fcdbad3b | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
def check_norm_c8275fb1fcdbad3b_5990c7814a41(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及交流电整流（半波/全波）及平均值计算
    trigger_keywords = ['整流', '平均电流', '平均值', 'rectifier', 'average current']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到整流电路平均值计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否为半波整流并核实其平均值公式
    # 半波整流特征：通常涉及单个二极管或明确提到“半波”
    is_half_wave = '半波' in (question + context + prediction) or 'single diode' in (question + context).lower()

    # 提取预测中的公式或数值特征
    pred_clean = prediction.replace(' ', '')

    # Step 3: 符号与数值校验
    # 半波整流平均值应为 I_peak / pi (约 0.318 * I_peak)
    # 错误逻辑通常会误用全波整流公式 2 * I_peak / pi (约 0.637 * I_peak)
    if is_half_wave:
        # 检查是否存在错误的 2/pi 系数
        if re.search(r'2\*?I_?m/\\?pi|2\*?I_?peak/\\?pi|0\.637', pred_clean, re.IGNORECASE):
            return {
                'result': 'fail',
                'message': '半波整流平均电流计算错误，误用了全波整流的系数(2/pi)',
                'evidence': re.search(r'.{0,20}(2\*?I_?m/\\?pi|2\*?I_?peak/\\?pi|0\.637).{0,20}', pred_clean).group()
            }

        # 检查是否正确使用了 1/pi 系数
        if re.search(r'I_?m/\\?pi|I_?peak/\\?pi|0\.318', pred_clean, re.IGNORECASE):
            return {'result': 'pass', 'message': '半波整流平均值计算公式正确', 'evidence': 'I_peak / pi'}

    # 如果没有明确的公式冲突，但提到了积分区间，检查 T/2 与 T 的匹配
    if '1/T' in pred_clean and '0' in pred_clean and 'T/2' in pred_clean:
        if '2*I_m/pi' in pred_clean or '2*I_peak/pi' in pred_clean:
             return {'result': 'fail', 'message': '积分区间为0到T/2时，系数1/T对应的是半波平均值，不应出现2/pi', 'evidence': pred_clean[:100]}

    return {'result': 'inconclusive', 'message': '未能明确判定整流系数是否正确', 'evidence': ''}

# rule_id=norm_c8466abd52501045 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
# rule_id=norm_c8466abd52501045 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
def check_norm_c8466abd52501045_f037ca437a78(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及并联支路电流合成及非纯电阻元件（交流电路）
    trigger_keywords = ['并联', '支路', '总电流', '相量', '交流', 'AC', 'impedance', 'reactance']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到并联交流电路电流合成场景', 'evidence': ''}

    # 检查是否包含电流符号 I1, I2, I
    if not (re.search(r'I_?1', combined_text) and re.search(r'I_?2', combined_text)):
        return {'result': 'inconclusive', 'message': '题目未明确给出支路电流符号', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否使用了相量合成（余弦定理或平方和关系）
    # 错误逻辑通常是直接代数相加 I = I1 + I2
    pred = prediction.lower()

    # 检查是否错误地使用了简单代数相加
    if re.search(r'i\s*=\s*i_?1\s*\+\s*i_?2', pred) and not re.search(r'cos|phi|theta|\^2|sqrt', pred):
        return {'result': 'fail', 'message': '错误地使用了代数相加而非相量合成', 'evidence': re.search(r'i\s*=\s*i_?1\s*\+\s*i_?2', pred).group()}

    # Step 3: 公式结构校验 — 寻找类似 I^2 = I1^2 + I2^2 + 2*I1*I2*cos(phi) 的结构
    # 匹配平方关系或余弦项
    phasor_pattern = r'(i\^2|i_?total\^2).*=.*(i_?1\^2.*i_?2\^2|i_?2\^2.*i_?1\^2)'
    cos_pattern = r'cos\s*\(\s*(phi|theta|\w+)\s*\)'

    if re.search(phasor_pattern, pred) or (re.search(r'i\s*=\s*sqrt', pred) and 'cos' in pred):
        return {'result': 'pass', 'message': '正确使用了相量合成公式或余弦定理', 'evidence': prediction[:200]}

    # 如果提到了相位差但没写出完整公式，保守返回 inconclusive
    if '相位差' in pred or 'phase' in pred:
        return {'result': 'inconclusive', 'message': '提到了相位关系但公式表达不完整', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了相量合成规则', 'evidence': ''}

# rule_id=norm_ffd75d909213cad4 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
# rule_id=norm_ffd75d909213cad4 | domain=Electromagnetism | topic=AC Circuits (Impedance and Reactance)
def check_norm_ffd75d909213cad4_52ef5d622501(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否要求通过 t0 和 f 表达，且涉及三角函数积分场景
    trigger_keywords = ['t0', 'f', 'express', 'integral', 'sin', 'cos']
    q_c_text = (question + context).lower()
    if not all(k in q_c_text for k in ['t0', 'f']) or not any(k in q_c_text for k in ['sin', 'cos', 'integral']):
        return {'result': 'inconclusive', 'message': '未检测到要求的变量表达或三角积分场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 禁止小角近似，必须保留完整的三角函数项
    # 寻找是否存在将 sin(x) 直接替换为 x 的迹象，或者在积分结果中丢失了周期项
    pred = prediction.lower()
    # 检查是否出现了类似 sin(wt) ≈ wt 的近似描述
    if re.search(r'sin\(.*?\)\s*\u2248\s*[^\s]+', pred) or 'approximation' in pred:
        if 'small angle' in pred or 'sin(x) = x' in pred.replace(' ', ''):
            return {'result': 'fail', 'message': '在未授权情况下使用了小角近似', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查积分 sin^2(wt) 的标准形式是否被保留
    # 标准形式应包含 t/2 和 sin(2wt)/4w 相关的结构，而非简单的线性项
    has_integral_result = re.search(r't/2|sin\(2.*?[wt]\)', pred)
    # 如果题目涉及功率或有效值计算（通常涉及 sin^2 积分），但结果只有线性项而无三角项，则可能违规
    if 'sin^2' in q_c_text or 'cos^2' in q_c_text:
        if not has_integral_result and re.search(r'\b[tf]\b', pred):
             return {'result': 'fail', 'message': '积分结果缺失完整的三角函数项，疑似过度简化', 'evidence': prediction[:200]}

    if has_integral_result:
        return {'result': 'pass', 'message': '保留了完整的三角函数积分项', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否使用了非法近似', 'evidence': ''}

# rule_id=norm_008b468e1f400528 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_008b468e1f400528 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_008b468e1f400528_c1c2f4cfb57d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及电流筒、Z-pinch、导线阵列或磁压计算场景
    trigger_keywords = ['电流筒', 'Z-pinch', '导线阵列', '磁压', 'magnetic pressure', 'pinch force']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到电流筒或磁压相关物理场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找磁压公式 P = B^2 / (2μ₀) 或其展开形式 P = (μ₀ I²) / (8 π² r²)
    # 匹配 B^2 / (2*mu) 或类似结构
    b_square_pattern = r'B\^2\s*/\s*\(2\s*μ_?0\)'
    # 匹配展开式 (mu0 * I^2) / (8 * pi^2 * r^2)
    canonical_pattern = r'μ_?0\s*\*?\s*I\^2\s*/\s*\(\s*8\s*\*?\s*π\^2\s*\*?\s*r\^2\s*\)'
    # 匹配安培环路定理场强 B = mu0*I / (2*pi*r)
    field_pattern = r'B\s*=\s*μ_?0\s*\*?\s*I\s*/\s*\(\s*2\s*\*?\s*π\s*\*?\s*r\s*\)'

    pred = prediction.replace(' ', '')

    has_b_sq = re.search(b_square_pattern, prediction, re.IGNORECASE) or 'B^2/2' in pred
    has_canonical = re.search(canonical_pattern, prediction, re.IGNORECASE) or 'I^2' in pred and '8' in pred and 'pi^2' in pred
    has_field = re.search(field_pattern, prediction, re.IGNORECASE)

    # Step 3: 综合判定
    if has_canonical or (has_b_sq and has_field):
        return {'result': 'pass', 'message': '正确使用了电流筒表面磁压模型或场强计算公式', 'evidence': prediction[:200]}

    # 如果提到了磁压但公式结构错误（例如分母不是8pi^2而是2pi或4pi）
    if 'P=' in pred or '压强' in prediction:
        if 'I^2' in pred and not ('8' in pred or '8*pi^2' in pred):
            return {'result': 'fail', 'message': '磁压公式系数或结构错误，未正确应用 P = (μ₀ I²) / (8 π² r²)', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '未能明确识别磁压计算过程', 'evidence': ''}

# rule_id=norm_1679cb4d165e11a6 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_1679cb4d165e11a6 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_1679cb4d165e11a6_34831363434f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及非均匀场（柱/球对称）及积分提示（erf, Gamma, 积分符号）
    trigger_keywords = ['erf', 'gamma', 'integral', '积分', '非均匀', '柱对称', '球对称', 'potential', '电势']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到非均匀场运动或积分提示场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 严禁使用匀加速运动公式 (s = 1/2 at^2 或 v = at)
    # 如果在非均匀场中直接套用匀加速公式，判定为建模错误
    invalid_patterns = [r'1/2\s*\*?\s*a\s*\*?\s*t\^2', r'v\s*=\s*a\s*\*?\s*t', r's\s*=\s*v_0\s*t']
    for pattern in invalid_patterns:
        if re.search(pattern, prediction, re.IGNORECASE):
            return {'result': 'fail', 'message': '在非均匀场中错误使用了匀加速运动公式', 'evidence': re.search(pattern, prediction, re.IGNORECASE).group()}

    # Step 3: 符号与公式校验 — 检查是否通过能量守恒求 v(r) 并进行 dt = dr/v 积分
    # 必须包含能量守恒相关项 (1/2 mv^2) 和 积分结构
    pred_lower = prediction.lower()
    has_energy = '1/2' in pred_lower and ('m' in pred_lower or 'v' in pred_lower)
    has_integral_form = 'dt' in pred_lower and 'dr' in pred_lower and '/' in pred_lower

    # 检查 symbolic_hint 中的关键符号
    required_symbols = ['erf', 'v(r)']
    symbol_check = all(sym.lower() in pred_lower for sym in required_symbols)

    if has_energy and has_integral_form and symbol_check:
        return {'result': 'pass', 'message': '正确使用了能量守恒与积分法计算变力场运动时间', 'evidence': '检测到能量守恒项与积分结构'}

    if not has_energy and not has_integral_form:
         return {'result': 'fail', 'message': '未发现基于能量守恒的积分建模过程', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程不完整，无法确认是否严格执行积分审计', 'evidence': ''}

# rule_id=norm_17b242290833d34e | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_17b242290833d34e | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_17b242290833d34e_86a13ac8b21d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及电磁学计算且题干可能缺失特定几何/环境常数
    # 关注磁场、洛伦兹力、半径、周期等计算场景
    keywords = ['磁场', '磁感应强度', '洛伦兹力', '轨道半径', '周期', 'B', 'Lorentz', 'magnetic']
    if not any(k in (question + context) for k in keywords):
        return {'result': 'inconclusive', 'message': '未检测到电磁学相关计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否存在盲目假设数值（如将未给出的 L, d, R, B 设为 1.0 或 1）
    # 重点检查 prediction 中是否出现了 "假设...为1" 或 "令...=1" 的表述，且该参数在 question 中未定义数值
    assumption_patterns = [
        r'(?:假设|令|设|take|assume).*?([a-zA-Z])\s*=\s*1(?:\.0)?',
        r'=\s*1(?:\.0)?\s*(?:代入|计算)'
    ]

    found_assumption = False
    for pattern in assumption_patterns:
        match = re.search(pattern, prediction)
        if match:
            symbol = match.group(1) if len(match.groups()) > 0 else "未知变量"
            # 检查该符号是否在题干中已有明确数值（若有数值则不算盲目假设）
            # 简单判断：若题干中没有该符号紧跟数字，则视为盲目假设
            if not re.search(rf'{symbol}\s*=\s*\d', question + context):
                found_assumption = True
                evidence_str = match.group(0)
                break

    if found_assumption:
        return {
            'result': 'fail',
            'message': '在计算公式中存在题干未给出的参数时，盲目假设数值（如设为1.0）而非保持符号化表达。',
            'evidence': evidence_str
        }

    # Step 3: 检查是否保持了符号化表达
    # 如果 prediction 中包含大量字母公式且最终结果含字母，则倾向于 pass
    if re.search(r'[a-zA-Z]{2,}\s*=', prediction) and not re.search(r'=\s*\d+\.?\d*$', prediction.strip()):
        return {'result': 'pass', 'message': '推理过程中保持了符号化表达或未发现盲目代值', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '无法确定是否存在违规假设行为', 'evidence': ''}

# rule_id=norm_29f4031d1b30fc56 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_29f4031d1b30fc56 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_29f4031d1b30fc56_ca0be4897f28(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及磁场中的多维运动耦合场景
    # 触发特征：包含磁场B、速度分量(vx/vy/x'/y')以及加速度/力(ax/ay/x''/y'')
    trigger_keywords = ['磁场', 'B', 'Lorentz', '洛伦兹', 'qvB']
    combined_text = (question + context).lower()
    is_triggered = any(kw.lower() in combined_text for kw in trigger_keywords)

    # 检查是否存在跨轴耦合的物理量符号
    coupling_symbols = ["x''", "y'", "ax", "vy", "ay", "vx", "dvx", "dvy"]
    has_coupling_context = any(sym in (question + context) for sym in coupling_symbols)

    if not (is_triggered or has_coupling_context):
        return {'result': 'inconclusive', 'message': '未检测到多维运动耦合场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别方程组是否体现了耦合关系 (如 x'' 与 y' 的关联)
    pred = prediction.lower()
    # 匹配类似 m*x'' = q*y'*B 或 ax = k*vy 的耦合结构
    coupling_patterns = [
        r"x''\s*=.*y'",
        r"y''\s*=.*x'",
        r"ax\s*=.*vy",
        r"ay\s*=.*vx",
        r"dvx/dt\s*=.*vy",
        r"dvy/dt\s*=.*vx"
    ]

    found_coupling_logic = any(re.search(p, pred.replace(' ', '')) for p in coupling_patterns)

    # Step 3: 符号覆盖检查 (required_symbols: B, x'', y')
    required = ['B']
    missing_req = [r for r in required if r not in prediction]

    # 判定逻辑：如果识别到耦合需求但预测中直接对单轴独立积分（忽略了另一轴速度的影响），则判定为 fail
    # 典型的错误特征：在存在B的情况下，直接使用 v = v0 + at 且 a 为常数（未考虑速度偏转）
    if not found_coupling_logic and ('independent' in pred or '独立' in pred):
        return {'result': 'fail', 'message': '错误地将耦合运动视为单轴独立运动处理', 'evidence': prediction[:200]}

    if found_coupling_logic:
        return {'result': 'pass', 'message': '正确识别并建立了耦合微分方程关系', 'evidence': '检测到耦合方程结构'}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了耦合关系', 'evidence': prediction[:150]}

