    # Step 2: 检查逻辑 — 验证 prediction 是否包含差分形式或特定的几何耦合项结构
    # 重点检查分母中是否存在类似 bp - aq 的耦合项结构
    pred_clean = prediction.replace(' ', '')
    # 匹配类似 1/(bp-aq) 或 (bp-aq)^-1 的结构，其中 a,b,p,q 为符号
    coupling_pattern = r'1/\([a-zA-Z][a-zA-Z]-[a-zA-Z][a-zA-Z]\)'

    # 检查是否提及导数收敛或极限过程
    limit_keywords = ['limit', '收敛', 'converge', 'derivative', '导数', 'dt', 'd/dt']
    has_limit_logic = any(kw in prediction.lower() for kw in limit_keywords)

    # Step 3: 符号校验 — 检查 symbolic_hint 要求的 a, b, p, q 是否出现
    required_symbols = ['a', 'b', 'p', 'q']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    if not has_limit_logic:
        return {'result': 'fail', 'message': '推理中缺失离散项向连续导数/积分转化的极限逻辑', 'evidence': prediction[:200]}

    if len(missing_symbols) > 2: # 允许少量符号差异，但核心耦合变量应存在
        return {'result': 'fail', 'message': '缺失关键几何耦合变量 (a,b,p,q)', 'evidence': f'缺失符号: {missing_symbols}'}

    # 检查 canonical 结构：1/(bp - aq)
    if re.search(r'1/\([bp][pq]-[aq][qp]\)', pred_clean) or re.search(r'1/\([a-z]{2}-[a-z]{2}\)', pred_clean):
        return {'result': 'pass', 'message': '检测到符合一致性要求的几何耦合积分核结构', 'evidence': prediction[:200]}

