    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及等离子体、重力场与磁场的共同作用
    trigger_keywords = ['等离子体', 'plasma', '磁场', 'magnetic field', '重力', 'gravity', '漂移', 'drift']
    combined_text = (question + context).lower()
    if not (any(kw in combined_text for kw in ['等离子体', 'plasma']) and
            any(kw in combined_text for kw in ['重力', 'gravity', 'g']) and
            any(kw in combined_text for kw in ['磁场', 'magnetic', 'b'])):
        return {'result': 'inconclusive', 'message': '未检测到等离子体在重力场与磁场共同作用的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否区分了热运动与漂移运动，并检查漂移速度公式
    pred_lower = prediction.lower()
    # 检查是否提到漂移速度 (drift velocity)
    if 'drift' not in pred_lower and '漂移' not in pred_lower:
        return {'result': 'fail', 'message': '未明确提及或区分宏观漂移运动', 'evidence': prediction[:200]}

    # Step 3: 公式校验 — 验证 v_d = mg / (qB) 的结构
    # 匹配包含 m, g, q, B 的除法结构，允许不同的书写顺序
    formula_pattern = r'v_?d?\s*=\s*\(?m\s*\*?\s*g\)?\s*/\s*\(?q\s*\*?\s*B\)?'
    if re.search(formula_pattern, prediction, re.IGNORECASE):
        return {'result': 'pass', 'message': '正确应用了重力漂移速度公式 v_d = mg/(qB)', 'evidence': re.search(formula_pattern, prediction, re.IGNORECASE).group()}

    # 备选检查：如果公式不完整但缺少关键符号
    required_symbols = ['m', 'g', 'q', 'B']
