# rule_id=norm_3f3881b7f19a68b3 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_3f3881b7f19a68b3_f3e31e6ecc67(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及刚性杆(rod)及其两端连接(attached at the ends)且处于磁场或重力场中
    q_c = (question + context).lower()
    is_rod = 'rod' in q_c or '杆' in q_c
    is_attached = 'attached' in q_c or 'fixed' in q_c or '连接' in q_c or '固定' in q_c
    is_field = any(x in q_c for x in ['magnetic', 'gravity', '磁场', '重力', 'field'])

    if not (is_rod and is_attached and is_field):
        return {'result': 'inconclusive', 'message': '未检测到刚性杆约束及场运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否考虑了杆的内力约束（法向加速度/速度关联）或质心与转动的耦合
    pred = prediction.lower()
    # 寻找速度投影相等或法向约束的关键词
    constraint_keywords = ['constraint', 'rigid', 'velocity projection', 'relative', 'center of mass', 'rotation', '约束', '刚性', '速度投影', '质心', '转动']
    has_constraint_logic = any(kw in pred for kw in constraint_keywords)

    # Step 3: 符号/公式校验 — 检查 v1·r12 = v2·r12 类似的投影关系或 R, v 的关联
    # 匹配类似 v*cos 或 v1 = v2 的速度关联表达式
    has_formula = re.search(r'v[\d_]*\s*\.\s*r|v[\d_]*\s*cos|v_1\s*=\s*v_2', pred) or ('v' in pred and 'R' in pred)

    if not has_constraint_logic and not has_formula:
        return {
            'result': 'fail',
            'message': '模型分析缺失刚性约束处理，未体现两端速度关联或质心转动耦合',
            'evidence': prediction[:200]
        }

    if has_constraint_logic and has_formula:
        return {
            'result': 'pass',
            'message': '已考虑刚性杆约束及动力学耦合关系',
            'evidence': re.findall(r'.{0,50}(?:constraint|v|R).{0,50}', pred)[:3]
        }

    return {'result': 'inconclusive', 'message': '检测到部分相关描述，但约束逻辑不够明确', 'evidence': prediction[:100]}

# rule_id=norm_3fd664abd2685498 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_3fd664abd2685498 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_3fd664abd2685498_525c3c9db618(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及地磁场、磁针偏转角 theta 的计算
    trigger_keywords = ['地磁', '磁针', '偏转角', 'theta', 'θ', 'magnetic field', 'deflection']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到地磁偏角计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否包含 tan(theta) = B_induced / B_earth_horizontal 的关系
    # 匹配 tan(theta) 或 theta 约等于 B/B 的结构
    pred = prediction.lower()
    formula_pattern = r'(tan|θ|theta).*=.*(b|f|i).*/.*(b|h)'
    has_formula = re.search(formula_pattern, pred)

    # 检查是否包含地磁水平分量 (B_z 或 B_h)
    has_earth_component = 'b_z' in pred or 'b_h' in pred or '水平分量' in pred or 'horizontal' in pred

    if not (has_formula or has_earth_component):
        return {'result': 'fail', 'message': '未发现地磁偏角正切关系公式或水平分量参数', 'evidence': prediction[:200]}

    # Step 3: 单位校验 — 若结果极小，检查是否进行了弧度到分(')或秒(")的转换
    # 寻找类似 0.001 这种极小数值，并检查是否有单位转换迹象
    small_value_match = re.search(r'0\.00\d+', pred)
    unit_conversion_match = re.search(r"'|\"|分|秒|60", pred)

    if small_value_match and not unit_conversion_match:
        return {'result': 'fail', 'message': '计算结果极小时未发现弧度向分或秒的单位转换', 'evidence': small_value_match.group()}

    if has_formula and (not small_value_match or unit_conversion_match):
        return {'result': 'pass', 'message': '符合地磁偏角计算逻辑及单位转换规范', 'evidence': 'Formula and unit check passed'}

    return {'result': 'inconclusive', 'message': '证据不足以判定单位转换是否正确', 'evidence': ''}

