# rule_id=norm_49d08402d9e338c7 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_49d08402d9e338c7 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_49d08402d9e338c7_96f33c0c5235(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及磁偶极子/单极子靠近良导体薄膜（非超导体）
    q_c_text = (question + context).lower()
    is_magnetic_source = re.search(r'(magnetic\s+dipole|monopole|磁偶极子|磁单极子)', q_c_text)
    is_conducting_film = re.search(r'(conducting\s+thin\s+film|良导体|金属薄膜|finite\s+conductivity)', q_c_text)
    is_superconductor = re.search(r'(superconductor|超导体|Meissner)', q_c_text)

    if not (is_magnetic_source and is_conducting_film) or is_superconductor:
        return {'result': 'inconclusive', 'message': '题目未明确涉及良导体薄膜或可能涉及超导体', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否错误地直接套用等值镜像法（Image Method）
    # 良导体在磁场下应考虑涡流延迟、扩散方程或随时间变化的响应，而非简单的静态等值镜像
    pred = prediction.lower()
    # 寻找是否直接使用了简单的镜像电荷/磁荷公式，如 -m 或等距离镜像，且没有提到扩散/电导率/时间演化
    has_simple_image = re.search(r'(image\s+method|镜像法|method\s+of\s+images)', pred)
    has_diffusion_or_eddy = re.search(r'(diffusion|eddy\s+current|conductivity|diffusion\s+equation|涡流|扩散方程|电导率|有限电导)', pred)

    # 如果使用了镜像法但完全没有提到扩散、涡流或电导率的影响，则判定为建模错误
    if has_simple_image and not has_diffusion_or_eddy:
        return {
            'result': 'fail',
            'message': '良导体薄膜在磁场下不能直接套用超导体的等值镜像法，需考虑有限电导率导致的扩散或涡流效应。',
            'evidence': re.search(r'.{0,50}(image|镜像).{0,50}', prediction, re.IGNORECASE).group(0) if has_simple_image else prediction[:100]
        }

    # Step 3: 验证是否提到了正确的物理机制
    if has_diffusion_or_eddy:
        return {'result': 'pass', 'message': '正确识别了良导体的物理特性，未盲目套用简单镜像法', 'evidence': '检测到关键词: ' + (re.search(r'(diffusion|eddy|conductivity|扩散|涡流)', pred).group(0))}

    return {'result': 'inconclusive', 'message': '无法确定推理是否正确区分了良导体与超导体的镜像处理', 'evidence': ''}

# rule_id=norm_58166bceadb1cf73 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_58166bceadb1cf73 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_58166bceadb1cf73_fadb05b45af0(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及有限长导线且长度与距离处于同一数量级
    # 匹配如 D, 2D, L, 2L 等长度标识，以及“有限长”、“线段”等关键词
    trigger_keywords = ['有限长', '线段', 'finite length', 'segment']
    is_finite = any(kw in (question + context) for kw in trigger_keywords)
    # 检查是否存在长度与距离的比例关系描述，如 D 和 2D
    ratio_pattern = re.search(r'([a-zA-Z])\s*和\s*\d*\1|\d+[a-zA-Z].*\d+[a-zA-Z]', question + context)

    if not (is_finite or ratio_pattern):
        return {'result': 'inconclusive', 'message': '未检测到有限长导线或特定比例场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否错误使用了无限长直导线公式 B = mu_0*I / 2*pi*r
    # 无限长公式特征：分母为 2*pi*r 或 2πr
    infinite_formula = re.search(r'mu_0\s*\*?\s*I\s*/\s*\(\s*2\s*\*?\s*pi\s*\*?\s*r\s*\)', prediction)
    infinite_formula_alt = re.search(r'μ₀I\s*/\s*2πr', prediction)

    # Step 3: 检查是否使用了有限长积分公式或其角度形式
    # 目标公式特征：分母含 4*pi*r 且包含 cos 或 sin 的差值/和
    finite_pattern = re.search(r'mu_0.*4.*pi.*(cos|sin)', prediction, re.IGNORECASE)
    integral_mention = any(kw in prediction for kw in ['积分', 'integral', 'Biot-Savart', '毕奥', '角度'])

    if (infinite_formula or infinite_formula_alt) and not finite_pattern:
        return {
            'result': 'fail',
            'message': '错误套用了无限长直导线公式，有限长导线需使用积分或含角度的公式',
            'evidence': f'检测到无限长公式或缺失积分步骤: {prediction[:150]}'
        }

    if finite_pattern or integral_mention:
        return {
            'result': 'pass',
            'message': '正确使用了有限长导线磁场计算逻辑或公式',
            'evidence': f'匹配到有限长公式特征: {prediction[:150]}'
        }

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了有限长导线积分', 'evidence': ''}

# rule_id=norm_59e60cd61b0932ff | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_59e60cd61b0932ff | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_59e60cd61b0932ff_6c400fa7b4ea(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')
    full_text = (question + context).lower()
    pred_text = prediction.lower()

    # Step 1: 触发条件 — 检查是否涉及电荷/磁极在有限电导率平面（薄膜）附近的运动
    trigger_keywords = ['conductivity', 'finite conductivity', 'thin film', 'moving charge', 'moving monopole', '有限电导率', '薄膜', '运动电荷', '磁单极子']
    if not any(kw in full_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到有限电导率平面或电荷运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否将镜像视为连续分布（拖尾效应/随时间演化），而非单一对称点
    # 寻找描述分布、拖尾、随时间变化或非单一镜像的关键词
    distribution_keywords = ['distribution', 'continuous', 'trailing', 'wake', 'time-dependent', '连续分布', '拖尾', '随时间演化', '分布镜像']
    single_point_keywords = ['single image', 'point charge image', 'symmetric point', '单一镜像', '对称点']

    has_distribution = any(kw in pred_text for kw in distribution_keywords)
    is_oversimplified = any(kw in pred_text for kw in single_point_keywords) and not has_distribution

    if is_oversimplified:
        return {'result': 'fail', 'message': '模型过于简化：将镜像视为单一对称点电荷，忽略了有限电导率导致的连续分布（拖尾效应）。', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查是否包含要求的物理量符号或求和/积分结构
    # 符号要求: \tau (弛豫时间), v (速度), v_0 (特征速度)
    required_symbols = ['\\tau', 'v_0', 'v']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)

    # 检查公式结构: \Phi \propto \sum [1/r_n - 1/r_{n+1}] 或类似的差分/积分形式
    formula_pattern = r'1/r_.*-.*1/r_'
    has_formula = re.search(formula_pattern, prediction) is not null

    if has_distribution or symbol_count >= 2 or has_formula:
        return {'result': 'pass', 'message': '模型正确考虑了镜像电荷的连续分布或相关物理参数。', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了镜像分布逻辑。', 'evidence': ''}

# rule_id=norm_733cca9b150f76b4 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_733cca9b150f76b4 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_733cca9b150f76b4_0dd104fc4b5b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否为圆柱电容器且满足间距 d << 半径 R 的近似场景
    trigger_keywords = ['圆柱', 'cylindrical', '电容', 'capacitor']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到圆柱电容器场景', 'evidence': ''}

    # 检查是否存在近似条件 d << R 或 间距远小于半径
    approx_pattern = r'(d\s*<<\s*R|间距.*小于.*半径|d\s*\ll\s*R)'
    if not re.search(approx_pattern, question + context + prediction):
        return {'result': 'inconclusive', 'message': '未检测到近似平行板的触发条件 d << R', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查面积 A 是否取为侧面积 2πRL 而非截面积
    # 错误建模通常会错误使用 pi*R^2 或忽略 L
    pred = prediction.replace(' ', '')
    area_correct = '2*pi*R*L' in pred or '2πRL' in pred or '2\\piRL' in pred
    area_wrong = 'pi*R^2' in pred or 'πR^2' in pred or 'pi*R**2' in pred

    if area_wrong and not area_correct:
        return {'result': 'fail', 'message': '面积 A 错误地使用了截面积而非侧面积 2πRL', 'evidence': prediction}

    # Step 3: 公式校验 — 检查电容公式 C = ε₀εᵣ(2πRL)/d 的结构
    # 匹配包含 epsilon, 2, pi, R, L, d 的组合
    formula_pattern = r'C\s*=\s*.*(epsilon|ε).*2.*(pi|π).*R.*L.*/.*d'
    if re.search(formula_pattern, pred, re.IGNORECASE):
        return {'result': 'pass', 'message': '正确使用了近似平行板电容公式', 'evidence': prediction}

    # 如果提到了面积但公式不完整，进一步检查符号覆盖
    required_symbols = ['L', 'R', 'd']
    missing_symbols = [s for s in required_symbols if s not in prediction]
    if missing_symbols:
        return {'result': 'fail', 'message': f'建模缺失关键几何参数: {missing_symbols}', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '无法确定建模是否完全符合规则要求', 'evidence': ''}

# rule_id=norm_735d35d6a6069ccb | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_735d35d6a6069ccb | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_735d35d6a6069ccb_84a029954a73(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否出现“返回初始位置”、“闭合轨道”或“经过N次”的描述
    trigger_keywords = ['返回初始位置', '回到起点', '闭合轨道', '经过', '第', '次', 'original position', 'closed orbit']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到周期性回归或闭合轨道相关描述', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否建立了径向运动周期 (Tr) 与角向偏转周期 (Tθ) 的比例关系或共振条件
    pred = prediction.lower()
    # 寻找周期、频率、比例关系或共振相关的关键词
    logic_keywords = ['周期', '比例', 'n*', 'm*', 'ratio', 'period', 'resonance', '2\\pi', '2pi']
    has_logic = any(kw in pred for kw in logic_keywords)

    # 检查 symbolic_hint 中的关键符号：7 times, original position
    symbol_check = '7' in pred or '七' in pred

    if not has_logic:
        return {'result': 'fail', 'message': '未建立径向与角向运动的周期比例关系或共振条件', 'evidence': prediction[:200]}

    # Step 3: 公式结构校验 — 检查是否满足 Δθ = 2πk 或类似的整数倍关系
    # 匹配类似 n*Tr = m*T 或 Δθ = 2π 的模式
    formula_pattern = r'(\\Delta\\s*\\theta|delta\\s*theta).*2\\s*\\pi|n\\s*\\*\\s*T|m\\s*\\*\\s*T|\\d+\\s*\\*\\s*T'
    if re.search(formula_pattern, pred) or symbol_check:
        return {'result': 'pass', 'message': '已建立周期性回归的共振比例关系', 'evidence': re.search(formula_pattern, pred).group(0) if re.search(formula_pattern, pred) else 'detected required symbols'}

    return {'result': 'inconclusive', 'message': '检测到相关描述但无法确认计算逻辑的严密性', 'evidence': prediction[:150]}

# rule_id=norm_748f4f3598f49e87 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_748f4f3598f49e87 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_748f4f3598f49e87_8d6a949c6668(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及场强（磁场、重力等）随距离 r 的幂次比例变化
    trigger_keywords = ['距离', '半径', ' r ', ' R ', '幂次', '反比', '平方比', '立方比']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到场强随距离变化的比例换算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 核实是否使用了基准值（如 A0, Re）进行比例缩放
    # 寻找类似 A * (R/r)^n 的结构，或者 A0 * (1/r)^n 的比例表达
    pred = prediction.lower()
    # 匹配比例缩放模式：(R/r)^n 或 (r/R)^n 或 A0 * ...
    scaling_pattern = re.compile(r'([a-zA-Z0-9_]+)\s*\*\s*\(?\s*([a-zA-Z0-9_]+)\s*/\s*([a-zA-Z0-9_]+)\s*\)?\s*\^\s*\d+')
    ratio_pattern = re.compile(r'\(\s*[Rr]\s*/\s*[Rr]\s*\)')

    has_scaling = scaling_pattern.search(pred) or ratio_pattern.search(pred) or '基准' in pred or '地表' in pred

    # Step 3: 错误识别 — 检查是否直接将常数与带单位距离进行幂次运算（如 B = k / r^3 而非 B = B0 * (R/r)^3）
    # 如果出现了物理常数（如 G, k, mu）直接除以 r 的幂次，且没有基准值抵消单位，则可能存在风险
    direct_calc_pattern = re.compile(r'[Gkμ]\s*/\s*[rR]\s*\^\s*\d+')

    if has_scaling:
        return {'result': 'pass', 'message': '检测到使用了基准值比例缩放逻辑', 'evidence': scaling_pattern.search(pred).group(0) if scaling_pattern.search(pred) else '比例换算描述'}

    if direct_calc_pattern.search(pred):
        return {'result': 'fail', 'message': '错误地将物理常数与带单位距离直接进行幂次运算，未进行基准值比例缩放', 'evidence': direct_calc_pattern.search(pred).group(0)}

    return {'result': 'inconclusive', 'message': '无法确定是否正确使用了比例换算公式', 'evidence': pred[:100]}

# rule_id=norm_757ee7fbc47e0f33 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_757ee7fbc47e0f33 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_757ee7fbc47e0f33_fc64ced0b898(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及等量异种电荷（电偶极子）在匀强磁场中的运动
    trigger_keywords = ['电偶极子', 'dipole', '等量异种', 'opposite charge', '匀强磁场', 'uniform magnetic field']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到电偶极子在匀强磁场中运动的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否考虑了总磁力取决于相对速度以及动量项的抵消逻辑
    pred = prediction.lower()
    # 检查是否提到合力 F = q(v1-v2)xB 或类似表达
    force_pattern = r'q.*(v1\s*-\s*v2|v_rel|dr_rel/dt).*B'
    # 检查是否提到动量修正或导数抵消项
    momentum_pattern = r'(d/dt|derivative).*M.*v_CM'

    has_force_logic = re.search(force_pattern, pred) or '相对速度' in pred
    has_momentum_logic = re.search(momentum_pattern, pred) or '抵消' in pred or 'cancel' in pred

    if not (has_force_logic or has_momentum_logic):
        return {'result': 'fail', 'message': '推理中未体现总磁力与相对速度的关系或动量修正项的抵消逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号校验 — 检查关键物理量 B, q, r_rel, v_CM 是否出现
    required_symbols = ['B', 'q', 'r', 'v']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    if len(missing_symbols) > 2:
        return {'result': 'fail', 'message': f'缺少关键物理符号: {missing_symbols}', 'evidence': prediction[:150]}

    # 验证公式结构的完整性
    if re.search(r'd.*v_CM.*/dt.*=.*q.*v_rel.*B', pred.replace(' ', '')):
        return {'result': 'pass', 'message': '成功验证电偶极子受力抵消与动量修正逻辑', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑要素部分存在但公式匹配不完全', 'evidence': prediction[:150]}

# rule_id=norm_75d06b1775215041 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_75d06b1775215041 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_75d06b1775215041_d9a5f3573ce0(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及三维坐标系下的洛伦兹力或磁场运动
    trigger_keywords = ['洛伦兹力', 'Lorentz force', '磁场', 'magnetic field', 'B_z', 'B_x', 'B_y', 'F_x', 'F_y', 'F_z']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到洛伦兹力分量计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证分量正交性 (例如 F_x 不应直接由 B_x 产生)
    # 重点检查 F_x = q(v_y B_z - v_z B_y) 这种结构，若出现 F_x 包含 B_x 则违反物理逻辑
    pred = prediction.replace(' ', '')

    # 检查是否存在错误的同轴分量耦合 (如 F_x 依赖 B_x)
    invalid_patterns = [
        (r'F_?x.*B_?x', "F_x 分量不应包含 B_x"),
        (r'F_?y.*B_?y', "F_y 分量不应包含 B_y"),
        (r'F_?z.*B_?z', "F_z 分量不应包含 B_z")
    ]
    for pattern, msg in invalid_patterns:
        if re.search(pattern, pred, re.IGNORECASE):
            return {'result': 'fail', 'message': f'违反分量正交性: {msg}', 'evidence': re.search(pattern, prediction, re.IGNORECASE).group()}

    # Step 3: 公式结构校验 — 检查是否符合右手定则的行列式展开项
    # 检查 F_x 是否包含 v_y*B_z 或 v_z*B_y
    required_patterns = [
        r'F_?x.*(v_?y.*B_?z|B_?z.*v_?y)',
        r'F_?y.*(v_?z.*B_?x|B_?x.*v_?z)',
        r'F_?z.*(v_?x.*B_?y|B_?y.*v_?x)'
    ]

    match_count = 0
    for rp in required_patterns:
        if re.search(rp, pred, re.IGNORECASE):
            match_count += 1

    if match_count >= 1:
        # 进一步检查符号，例如 F_x = q(v_y B_z - v_z B_y)
        if 'F_x' in prediction and 'v_y' in prediction and 'B_z' in prediction:
            if re.search(r'F_?x.*=.*(v_?y.*B_?z.*-.*v_?z.*B_?y|B_?z.*v_?y.*-.*B_?y.*v_?z)', pred, re.IGNORECASE):
                return {'result': 'pass', 'message': '洛伦兹力分量正交性及符号校验通过', 'evidence': prediction[:150]}
            elif re.search(r'F_?x.*=.*v_?z.*B_?y.*-.*v_?y.*B_?z', pred, re.IGNORECASE):
                return {'result': 'fail', 'message': '洛伦兹力分量符号错误（违反右手定则）', 'evidence': prediction[:150]}

        return {'result': 'pass', 'message': '检测到正确的分量正交关系', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '未发现明确的分量计算公式', 'evidence': ''}

