# rule_id=norm_9504b14b591da75c | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_9504b14b591da75c_6c1cfb537716(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及地球磁场/偶极子场、俯仰角及粒子逃逸/损失锥场景
    trigger_keywords = ['地球磁场', '偶极子', 'dipole', 'pitch angle', '俯仰角', 'loss cone', '损失锥', '磁镜', 'magnetic mirror']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到偶极子场或俯仰角相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否利用第一绝热不变量（磁矩守恒）建立 B 与 sin^2(theta) 的关系
    # 核心逻辑是 sin^2(theta)/B = const，或者 B_0/B_m = sin^2(theta_0)
    pred = prediction.lower()

    # 检查是否错误使用了匀强磁场公式 (如直接用 R = mv/qB 且假设 B 恒定)
    uniform_field_indicators = ['uniform magnetic field', '匀强磁场', 'constant b']
    if any(ind in pred for ind in uniform_field_indicators) and 'magnetic moment' not in pred:
        return {'result': 'fail', 'message': '错误地使用了匀强磁场假设，未考虑磁矩守恒', 'evidence': prediction[:200]}

    # Step 3: 符号与公式结构校验
    # 匹配 sin^2(theta)/B 或类似的比例关系
    conservation_patterns = [
        r'sin\^2.*\/.*B',
        r'B_0.*sin\^2',
        r'B_m.*sin\^2',
        r'\mu\s*=\s*mv\^2\/2B',
        r'magnetic\s+moment\s+conservation',
        r'adiabatic\s+invariant'
    ]

    found_logic = False
    for pattern in conservation_patterns:
        if re.search(pattern, pred, re.IGNORECASE):
            found_logic = True
            break

    if found_logic:
        return {'result': 'pass', 'message': '正确使用了磁矩守恒或第一绝热不变量建立场强与俯仰角关系', 'evidence': prediction[:200]}

    # 如果提到了俯仰角但没有给出守恒关系的推导过程，判定为建模缺失
    if 'pitch angle' in pred or 'theta' in pred:
        return {'result': 'fail', 'message': '未建立初始位置与磁镜点的磁场强度比值关系(sin^2(theta)/B)', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了磁矩守恒逻辑', 'evidence': ''}

# rule_id=norm_9acc44bb988da688 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
# rule_id=norm_9acc44bb988da688 | domain=Electromagnetism | topic=Magnetic Fields and Lorentz Force
def check_norm_9acc44bb988da688_6f6dfe5aa31c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及悬浮/平衡位置附近的微小振动或频率求解
    trigger_keywords = ['振动', '频率', '周期', '平衡位置', '微小位移', 'harmonic', 'oscillation', 'frequency']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到微小振动或频率求解场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找回复力 F 与位移 z 的关系描述
    # 重点检查是否推导了 F = -k(z-z0) 或类似的导数关系 dF/dz < 0
    pred_lower = prediction.lower()

    # 匹配力与位移成正比的表达 (如 F = kz, F = -kz, dF/dz)
    force_relation_pattern = r'(F|f|力).*?([kz]|位移|z-z0)'
    if not re.search(force_relation_pattern, pred_lower):
        return {'result': 'inconclusive', 'message': '未在推理中发现明确的回复力与位移关系表达', 'evidence': ''}

    # Step 3: 符号校验 — 验证回复力方向是否正确（必须为负反馈，即 F = -k*delta_z）
    # 如果出现 F = k*z (k>0) 且没有负号，或者描述力与位移同向，则判定为逻辑错误
    # 匹配错误的逻辑：力与位移同向 (F = kz)
    wrong_logic_pattern = r'F\s*=\s*k\s*\*?\s*z(?!\s*[-+])|力与位移方向相同|F\s*=\s*k\s*z'
    correct_logic_pattern = r'F\s*=\s*-\s*k|回复力|负反馈|dF/dz\s*<\s*0|F\s*\propto\s*-\s*z'

    if re.search(wrong_logic_pattern, pred_lower) and not re.search(correct_logic_pattern, pred_lower):
        return {
            'result': 'fail',
            'message': '模型计算出的力与位移成正比且同向，违反了简谐运动回复力方向相反的物理逻辑',
            'evidence': re.search(force_relation_pattern, pred_lower).group(0)
        }

    if re.search(correct_logic_pattern, pred_lower):
        return {'result': 'pass', 'message': '回复力逻辑符合 F = -kz 的物理要求', 'evidence': '检测到负反馈或回复力描述'}

    return {'result': 'inconclusive', 'message': '无法确定回复力的符号逻辑是否正确', 'evidence': ''}

