    if not any(kw in full_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到旋转波近似（RWA）相关的物理场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否将振荡场分解为两个旋转分量
    # 检查是否包含分解后的项，如 b[cos(wt)i + sin(wt)j] 或类似的向量表达
    decomposition_pattern = r'b.*cos.*sin|cos.*i.*sin.*j|1/2.*\(e\^|exp\(i.*wt\)'
    has_decomposition = re.search(decomposition_pattern, pred_text)

    # Step 3: 检查逻辑 — 验证是否舍弃了高速运动项（反向旋转项）
    # 关键词：discard, ignore, neglect, counter-rotating, 舍弃, 忽略, 高频项
    discard_keywords = ['discard', 'ignore', 'neglect', 'drop', 'counter-rotating', '舍弃', '忽略', '高频', '反向旋转']
    has_discard = any(kw in pred_text for kw in discard_keywords)

    # Step 4: 符号校验 (symbolic_hint)
    # 检查是否提到 i' (旋转系) 或相关的角频率 w
    has_symbols = 'omega' in pred_text or '\\omega' in pred_text or 'b' in pred_text

    if has_decomposition and has_discard:
        return {'result': 'pass', 'message': '正确应用了旋转波近似逻辑，包含分解与舍弃项步骤', 'evidence': 'Decomposition and discard logic found'}

    if not has_decomposition and not has_discard:
        # 如果明确在讨论 RWA 但没有分解过程，判定为逻辑缺失
        if 'rwa' in pred_text or 'rotating wave' in pred_text:
            return {'result': 'fail', 'message': '在应用旋转波近似时，未体现将振荡场分解并舍弃高频项的逻辑', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程中关于RWA的分解或舍弃步骤不明确', 'evidence': ''}

