# rule_id=norm_e64e8b2d1e41df74 | domain=Electromagnetism | topic=Electromagnetic Induction and Faraday's Law
def check_norm_e64e8b2d1e41df74_a479d0dcb527(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及磁场随时间变化（dB/dt 或 B=kt）且求解静止导体棒的电动势
    trigger_keywords = ['磁场', '随时间', '变化', 'B=', 'dB/dt', '电动势', '导体棒']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到磁场随时间变化的感生电动势场景', 'evidence': ''}

    # 排除动生电动势干扰（如切割磁感线）
    if '切割' in (question + context) and '静止' not in (question + context):
        return {'result': 'inconclusive', 'message': '可能涉及动生电动势，不适用本规则', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否利用涡旋电场积分或构造闭合回路利用法拉第定律
    # 检查公式特征：E = (r/2)(dB/dt) 或 epsilon = dPhi/dt 或积分形式
    pred = prediction.lower()
    has_integral = re.search(r'\\int|积分|dl', pred)
    has_vortex_e = re.search(r'r/2|dB/dt|k/2|涡旋电场', pred)
    has_faraday = re.search(r'd\\phi/dt|\\Delta\\Phi/\\Delta t|磁通量变化率', pred)

    if not (has_integral or has_vortex_e or has_faraday):
        return {
            'result': 'fail',
            'message': '未检测到正确的感生电动势计算路径（涡旋电场积分或闭合回路磁通量法）',
            'evidence': prediction[:200]
        }

    # Step 3: 符号校验 — 检查 symbolic_hint 中的关键符号
    required_symbols = ['B', 'L', 'd', 'k']
    # 只要出现其中两个以上关键符号且有公式结构则认为通过
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)

    if (has_vortex_e or has_integral) and symbol_count >= 1:
        return {'result': 'pass', 'message': '正确使用了感生电动势的计算方法', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '推理过程模糊，无法确定计算路径', 'evidence': ''}

# rule_id=norm_e955ffda51ce5218 | domain=Electromagnetism | topic=Electromagnetic Induction and Faraday's Law
# rule_id=norm_e955ffda51ce5218 | domain=Electromagnetism | topic=Electromagnetic Induction and Faraday's Law
def check_norm_e955ffda51ce5218_949ba1e2bddb(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及非闭合路径（断路、开口、U型导轨不计电阻等）的感应电压计算
    trigger_keywords = ['非闭合', '断路', '开口', 'open circuit', 'not closed', '电势差', '电压', 'voltage difference']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到非闭合路径电压计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否错误使用了法拉第定律标量形式 (dPhi/dt) 而非动生电动势积分
    # 错误模式：直接使用 epsilon = dPhi/dt 或 delta Phi / delta t 处理断路
    pred = prediction.lower()
    faraday_scalar_pattern = r'd\\phi/dt|\\Delta\\Phi/\\Delta t|\\Phi/t'

    # 正确模式：使用动生电动势积分或各边电势差 (v x B)
    motional_emf_pattern = r'\\int.*v.*B.*dl|Blv|BvL|\\vec{v}\\times\\vec{B}'

    # 如果预测中出现了法拉第标量公式，且没有出现动生电动势的积分或Blv形式，则判定为建模错误
    if re.search(faraday_scalar_pattern, pred) and not re.search(motional_emf_pattern, pred):
        return {
            'result': 'fail',
            'message': '在处理非闭合路径时错误使用了法拉第电磁感应定律的标量形式，应使用动生电动势积分或Blv。',
            'evidence': re.search(faraday_scalar_pattern, pred).group(0)
        }

    # Step 3: 符号覆盖检查 — 检查是否包含必要的物理量 B, v, l
    required_symbols = ['B', 'v', 'l']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    if not missing_symbols and re.search(motional_emf_pattern, prediction):
        return {'result': 'pass', 'message': '正确使用了动生电动势方法处理非闭合路径电压', 'evidence': 'found motional emf pattern with B,v,l'}

    return {'result': 'inconclusive', 'message': '无法确定计算逻辑是否合规', 'evidence': ''}

# rule_id=norm_ef722f57487bafc6 | domain=Electromagnetism | topic=Electromagnetic Induction and Faraday's Law
# rule_id=norm_ef722f57487bafc6 | domain=Electromagnetism | topic=Electromagnetic Induction and Faraday's Law
def check_norm_ef722f57487bafc6_ec3337106c98(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及旋转线圈测电阻模型
    trigger_keywords = ['rotating coil', 'absolute standard for the ohm', 'needle set at angle theta', '旋转线圈', '欧姆绝对标准']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到旋转线圈测电阻相关场景', 'evidence': ''}

    # Step 2: 检查建模逻辑 — 必须基于磁场矢量合成 (tan theta = B_i/B_0) 而非机械平衡
    pred = prediction.lower()
    # 检查是否提到了磁场合成或正切关系
    vector_logic = ['tan', 'tangent', 'resultant field', 'magnetic field vector', 'B_i', 'B_0', '合成磁场', '正切']
    has_vector_logic = any(kw in pred for kw in vector_logic)

    # 检查是否错误地使用了机械扭矩平衡 (torque, mechanical balance)
    mechanical_error = 'torque balance' in pred or 'mechanical equilibrium' in pred or '扭矩平衡' in pred

    if mechanical_error and not has_vector_logic:
        return {'result': 'fail', 'message': '模型识别错误：应使用磁场矢量合成建立 tan(theta) 关系，而非机械扭矩平衡', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 (R ∝ ω / tan θ)
    # 检查必要符号 R, omega, theta
    required_symbols = ['R', 'omega', 'theta']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction or (sym == 'omega' and 'ω' in prediction) or (sym == 'theta' and 'θ' in prediction))

    # 检查公式结构特征：R 与 tan(theta) 的反比关系或 R 与 omega 的正比关系
    formula_pattern = re.search(r'R.*=.*omega.*/.*tan', pred.replace('ω', 'omega').replace('θ', 'theta'))

    if formula_pattern or (symbol_count >= 2 and 'tan' in pred):
        return {'result': 'pass', 'message': '模型识别正确，建立了正确的正切矢量关系', 'evidence': prediction[:200]}

    if symbol_count < 2:
        return {'result': 'inconclusive', 'message': '缺乏必要的物理量符号，无法判定模型准确性', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '证据不足，无法明确判定建模逻辑', 'evidence': ''}

