# rule_id=norm_6a0941dfb780540e | domain=Electromagnetism | topic=Self-Inductance and Mutual Inductance
def check_norm_6a0941dfb780540e_848cb5a9b01b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及运动导体（如旋转杆、棒）与自感元件（螺线管、电感）构成的回路
    trigger_keywords = ['旋转', '运动', '棒', '杆', 'rod', 'rotating', 'moving']
    inductance_keywords = ['自感', '螺线管', '电感', 'inductance', 'solenoid', ' L ']

    q_c = (question + context).lower()
    is_triggered = any(k in q_c for k in trigger_keywords) and any(k in q_c for k in inductance_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '题目未涉及运动导体与自感元件的耦合场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须同时包含回路电压方程（含L di/dt和动生电动势）与动力学方程（力矩/力）
    pred = prediction.lower()

    # 检查电压方程要素：自感项 L*di/dt 或 L*I'，以及动生电动势项（通常含 B, r, w 或 v）
    has_voltage_eq = (re.search(r'l.*d[iI]/dt', pred) or 'li\'' in pred or 'l*i\'' in pred) and \
                     (re.search(r'[bB].*[vV]', pred) or re.search(r'[bB].*[\omegaw]', pred) or 'blv' in pred)

    # 检查动力学方程要素：安培力矩/力项（含 B, I, L/r）与加速度/角加速度项（含 m*a 或 J*alpha/dw/dt）
    has_dynamics_eq = (re.search(r'[bB].*[iI]', pred) and (re.search(r'[ma].*[ad]', pred) or re.search(r'[jJ].*d[\omegaw]/dt', pred) or 'dw/dt' in pred))

    # Step 3: 综合判定
    if not has_voltage_eq:
        return {'result': 'fail', 'message': '建模缺失回路电压方程或未考虑自感/动生电动势项', 'evidence': prediction[:200]}

    if not has_dynamics_eq:
        return {'result': 'fail', 'message': '建模缺失动力学方程或未考虑安培力/力矩的反作用', 'evidence': prediction[:200]}

    # 检查符号覆盖 (B, I, L, w)
    required_symbols = ['B', 'I', 'L']
    missing_symbols = [s for s in required_symbols if s not in prediction]
    if not missing_symbols:
        return {'result': 'pass', 'message': '已建立完整的机电耦合方程组', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到方程但符号完整性不足', 'evidence': ''}

# rule_id=norm_ebabbac8de45164b | domain=Electromagnetism | topic=Self-Inductance and Mutual Inductance
# rule_id=norm_ebabbac8de45164b | domain=Electromagnetism | topic=Self-Inductance and Mutual Inductance
def check_norm_ebabbac8de45164b_ac9fb7ef8f03(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两个线圈且未明确同名端/绕向
    # 关键词：两个线圈、互感、耦合、M、di/dt
    trigger_keywords = ['两个线圈', '线圈1', '线圈2', '互感', '耦合', 'mutual inductance']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) or ' M ' in question

    # 检查是否明确了同名端（点号）或绕向，若已明确则不触发此多解性检查
    explicit_direction = any(kw in combined_text for kw in ['同名端', '点号', 'dot', '绕向', '顺时针', '逆时针'])

    if not is_triggered or explicit_direction:
        return {'result': 'inconclusive', 'message': '未检测到互感耦合多解性触发场景或已明确绕向', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否考虑了正负两种耦合方向 (\pm M)
    pred = prediction.lower()
    # 寻找是否包含两种情况的讨论，或者使用了正负号表示
    has_dual_cases = any(kw in pred for kw in ['两种情况', '两种可能', '正负', 'plus or minus', '±', '+/-'])

    # Step 3: 公式结构校验 — 检查是否出现类似 U = iR ± M(di/dt) 的结构
    # 匹配包含 M 和 di/dt 且带有正负号或分类讨论的特征
    formula_pattern = r'([\+\-]\s*M|M\s*di/dt.*[\+\-]\s*M|\pm\s*M)'
    has_formula_flexibility = re.search(formula_pattern, prediction) is not null

    if not (has_dual_cases or has_formula_flexibility):
        return {
            'result': 'fail',
            'message': '在未明确同名端的情况下，未考虑互感电动势的正负两种耦合可能性',
            'evidence': prediction[:200]
        }

    if has_dual_cases and (' M ' in prediction or 'di/dt' in prediction):
        return {
            'result': 'pass',
            'message': '正确识别并讨论了互感耦合的多解性',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '无法确定是否充分考虑了多解性', 'evidence': ''}

# rule_id=norm_10f2eb9cd206bdb3 | domain=Electromagnetism | topic=RL, RC, and RLC Circuits
# rule_id=norm_10f2eb9cd206bdb3 | domain=Electromagnetism | topic=RL, RC, and RLC Circuits
def check_norm_10f2eb9cd206bdb3_3c9fa4bee553(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 题目涉及电路时间/周期计算，且未提供具体数值（如阈值电压、电流曲线数值）
    # 检查是否属于 RL/RC/RLC 电路场景
    circuit_keywords = ['电路', '电容', '电感', 'RC', 'RL', 'RLC', '充电', '放电', '振荡']
    time_keywords = ['时间', '周期', '时长', 't =', 'T =']
    if not any(k in (question + context) for k in circuit_keywords) or not any(k in (question + context) for k in time_keywords):
        return {'result': 'inconclusive', 'message': '未检测到电路时间计算场景', 'evidence': ''}

    # 检查题目是否缺失具体数值（如没有出现具体的电压数值或阈值点）
    # 如果题目中已经给出了具体的电压数值（如 5V, 10V），则不触发此规则
    if re.search(r'\d+\s*[Vv]', question + context):
        return {'result': 'inconclusive', 'message': '题目已提供具体数值，不适用符号推导规则', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否直接假设了数值，还是保留了符号变量
    # 常见的假设数值行为：直接令 U=1, U_th=0.5 等
    assumption_patterns = [
        r'假设\s*[Uu]\w*\s*=\s*\d+',
        r'令\s*[Uu]\w*\s*=\s*\d+',
        r'取\s*[Uu]\w*\s*=\s*\d+'
    ]
    for pattern in assumption_patterns:
        if re.search(pattern, prediction):
            return {'result': 'fail', 'message': '严禁在题目未提供数据时自行假设数值，应保留符号变量推导', 'evidence': re.search(pattern, prediction).group()}

    # Step 3: 检查是否保留了符号变量（如 U_th, U_h, U_0, R, C 等）进行解析式推导
    symbolic_patterns = [r'[Uu]_[th]', r'[Uu]_[h0]', r'\ln', r'\exp', r'RC', r'L/R']
    has_symbolic = any(re.search(p, prediction) for p in symbolic_patterns)

    if has_symbolic:
        return {'result': 'pass', 'message': '正确使用了符号变量进行解析式推导', 'evidence': '检测到符号变量或解析表达式'}

    return {'result': 'inconclusive', 'message': '无法确定是否进行了符号推导', 'evidence': ''}

# rule_id=norm_13eb5182cd39fd4b | domain=Electromagnetism | topic=RL, RC, and RLC Circuits
# rule_id=norm_13eb5182cd39fd4b | domain=Electromagnetism | topic=RL, RC, and RLC Circuits
