# rule_id=norm_692514895c1cdc35 | domain=Electromagnetism | topic=RL, RC, and RLC Circuits
def check_norm_692514895c1cdc35_ef1db5b568fb(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及非线性元件（晶闸管、二极管等）与电容并联的RC电路
    trigger_keywords = ['非线性', '晶闸管', '二极管', 'thyristor', 'diode', 'tunnel diode', '并联']
    combined_text = (question + context).lower()
    is_rc = 'rc' in combined_text or '电容' in combined_text
    has_nonlinear = any(kw in combined_text for kw in trigger_keywords)

    if not (is_rc and has_nonlinear):
        return {'result': 'inconclusive', 'message': '未检测到非线性元件并联RC电路场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否考虑了等效电阻 R_i 与 R 的并联关系来计算时间常数
    pred = prediction.lower()
    # 检查是否提到了并联等效电阻或新的时间常数计算方式
    parallel_pattern = r'r.*\\|\\|.*r|r.*r.*/\(r.*\+.*r\)|并联.*电阻'
    tau_pattern = r'\\tau|时间常数|time constant'

    has_parallel_logic = re.search(parallel_pattern, pred) or '等效电阻' in pred
    has_tau_calc = re.search(tau_pattern, pred)

    if not (has_parallel_logic and has_tau_calc):
        return {
            'result': 'fail',
            'message': '未发现非线性元件分支与外部电阻并联等效计算时间常数的逻辑',
            'evidence': prediction[:200]
        }

    # Step 3: 符号/公式校验 — 检查是否符合 tau = (R*Ri)/(R+Ri) * C 的结构
    # 匹配类似 (R*R_i)/(R+R_i)*C 或 R_eff * C 的形式
    formula_match = re.search(r'\\tau.*=.*R.*C', prediction) or re.search(r'R.*R.*/.*\+.*C', prediction)

    if formula_match:
        return {
            'result': 'pass',
            'message': '已正确执行非线性元件并联等效的时间常数建模',
            'evidence': formula_match.group(0)
        }

    return {'result': 'inconclusive', 'message': '逻辑存在但公式表达不明确', 'evidence': prediction[:150]}

