    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及极化强度 P 与电场 E 的相位差 δ
    trigger_keywords = ['相位差', 'phase difference', 'delta', 'δ', '极化强度', 'polarization']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到极化相位差相关背景', 'evidence': ''}

    # Step 2: 检查逻辑 — 能量衰减/耗散项是否包含 sin δ 或 Im(ε)
    # 物理规则要求耗散正比于相位差的正弦值，若仅有幅值比 β 而无相位函数则报错
    pred_text = prediction.lower()

    # 检查是否提到了能量衰减、耗散或衰减系数 γ
    dissipation_keywords = ['衰减', '耗散', 'attenuation', 'dissipation', 'loss', 'γ', 'gamma']
    if not any(kw in pred_text for kw in dissipation_keywords):
        return {'result': 'inconclusive', 'message': '推理过程未明确讨论能量衰减项', 'evidence': ''}

    # Step 3: 符号与公式校验 — 必须包含 sin(δ) 或相关的虚部表示
    # 匹配 sin(delta), sin δ, Im(epsilon) 等模式
    has_sin_delta = re.search(r'sin\s*[\(\[]?\s*(delta|δ)', pred_text)
    has_im_eps = re.search(r'im\s*[\(\[]?\s*(epsilon|ε)', pred_text)

    # 检查是否只提到了幅值比 β 而忽略了相位
    has_beta = re.search(r'beta|β', pred_text)

    if has_sin_delta or has_im_eps:
        return {'result': 'pass', 'message': '模型包含了正确的相位耗散项 (sin δ)', 'evidence': prediction[:200]}

    if has_beta and not (has_sin_delta or has_im_eps):
        return {
            'result': 'fail',
            'message': '物理建模错误：能量衰减系数应正比于 sin δ，当前结果仅含幅值比或缺失相位函数',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '无法确定衰减项的具体数学形式', 'evidence': ''}

