    # 检查是否提到磁场 B 与波矢 k 的关系（平行或纵向传播）
    if not re.search(r'(parallel|longitudinal|along|alongside|平行|纵向)', combined_text):
        return {'result': 'inconclusive', 'message': '未明确磁场与波矢的平行关系', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否错误地仅使用了简单的等离子体频率 omega_p
    pred_lower = prediction.lower()
    # 如果预测中只提到 omega = omega_p 或 f = f_p 而忽略了磁场修正，则可能存在建模错误
    simple_cutoff_pattern = r'(\omega|f)\s*=\s*(\omega|f)_p'
    correction_keywords = ['cyclotron', 'omega_c', 'lorentz', 'correction', '回旋频率', '修正', 'sqrt']

    has_simple = re.search(simple_cutoff_pattern, pred_lower)
    has_correction = any(kw in pred_lower for kw in correction_keywords)

    if has_simple and not has_correction:
        return {
            'result': 'fail',
            'message': '模型错误：在磁化等离子体中直接使用未修正的等离子体频率作为截止频率，未考虑洛伦兹力修正。',
            'evidence': prediction[:200]
        }

    # Step 3: 符号/公式校验 — 检查是否包含修正后的截止频率公式特征
    # 目标公式特征：omega^2 +/- omega_c*omega - omega_p^2 = 0 或其解的结构
    formula_pattern = r'(\omega(_c)?|B|e|m_e).*(\omega(_p)?|n_e)'
    if re.search(formula_pattern, prediction):
        if 'sqrt' in pred_lower and ('omega_c' in pred_lower or 'B' in pred_lower):
            return {'result': 'pass', 'message': '正确考虑了磁场对截止频率的修正', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了磁化等离子体修正逻辑', 'evidence': ''}

