    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及电场中偶极子的力矩(Torque)或功率(Power)推导
    trigger_keywords = ['dipole', '偶极子', 'torque', '力矩', 'power', '功率', 'p·E', 'p.E']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到偶极子动力学相关场景', 'evidence': ''}

    # Step 2: 检查符号一致性逻辑
    # 检查力矩是否作为恢复力矩（通常涉及负号，如 -pE sin(theta)）
    # 检查功率/能量守恒关系 H = dW/dt = d/dt(p·E)
    pred = prediction.lower()

    # 检查符号一致性：如果提到力矩(tau)和角度(theta)，通常应体现恢复力性质
    has_torque_logic = re.search(r'tau|torque|力矩', pred)
    has_power_logic = re.search(r'power|功率|dW/dt|H\(t\)', pred)

    if not (has_torque_logic or has_power_logic):
        return {'result': 'inconclusive', 'message': '预测中未包含明确的力矩或功率推导逻辑', 'evidence': ''}

    # Step 3: 符号与公式结构校验 (基于 symbolic_hint)
    # 检查是否满足 H = d/dt(p·E) 或类似的能量导数关系
    # 检查 required_symbols: E(t), dot{theta}, p_0, theta(t)
    required_symbols = ['e', 'p_0', 'theta']
    missing_symbols = [s for s in required_symbols if s not in pred]

    # 检查功率公式 H(t) = E(t) * d/dt(p_x(t)) 的变体
    power_pattern = r'd/dt\s*\(\s*p.*E\s*\)|E.*d/dt\s*\(\s*p\s*\)|p.*E.*cos|p.*E.*sin'

    if has_power_logic and not re.search(power_pattern, pred):
        return {'result': 'fail', 'message': '功率表达式未体现能量守恒关系 H = d/dt(p·E)', 'evidence': prediction[:200]}

    if len(missing_symbols) > 1:
         return {'result': 'inconclusive', 'message': '关键物理符号缺失，无法判定一致性', 'evidence': f'缺失符号: {missing_symbols}'}

    # 检查恢复力矩的负号逻辑 (针对简谐或平衡态分析)
    if 'sin' in pred and 'theta' in pred and 'tau' in pred:
        if '-' not in pred and 'negative' not in pred and '恢复' not in pred:
            return {'result': 'fail', 'message': '力矩推导可能缺失恢复力方向的负号', 'evidence': prediction[:200]}

    return {'result': 'pass', 'message': '偶极子动力学符号与能量关系基本一致', 'evidence': prediction[:150]}

