# rule_id=norm_6c76723284e424a5 | domain=Electromagnetism | topic=Magnetic Dipoles and Magnetic Materials
# rule_id=norm_6c76723284e424a5 | domain=Electromagnetism | topic=Magnetic Dipoles and Magnetic Materials
def check_norm_6c76723284e424a5_b69015db3e9e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及磁偶极子在平面上方的悬浮或微振动频率
    trigger_keywords = ['磁偶极子', 'magnetic dipole', '悬浮', 'levitation', 'superconductor', '超导', '频率', 'frequency', 'oscillation']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到磁悬浮或磁偶极子微振动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找势能 U ∝ z^-n 或力 F ∝ z^-(n+1) 的幂律描述
    pred = prediction.lower()
    # 匹配类似 z^-n, h^-n, 1/z^n 等模式
    power_law_pattern = r'([zh])\s*\^?\s*[-\(]?\s*n'
    if not re.search(power_law_pattern, pred) and '1/z' not in pred and '1/h' not in pred:
        return {'result': 'inconclusive', 'message': '未在推理中发现明确的幂律关系描述', 'evidence': ''}

    # Step 3: 核心校验 — 检查频率公式 Omega = sqrt((n+1)g/h) 或劲度系数 k = (n+1)mg/h
    # 允许 n+1 或 n 相关的系数，因为具体 n 的定义可能随势能或力而异
    # 匹配 sqrt((n+1)g/h) 或类似的结构
    omega_pattern = r'sqrt\s*\(\s*\(?n\s*\+\s*1\)?\s*\*?\s*g\s*/\s*[zh]\s*\)'
    k_pattern = r'k\s*=\s*\(?n\s*\+\s*1\)?\s*\*?\s*m\s*\*?\s*g\s*/\s*[zh]'

    has_omega = re.search(omega_pattern, pred)
    has_k = re.search(k_pattern, pred)

    if has_omega or has_k:
        return {'result': 'pass', 'message': '频率或劲度系数的幂律推导符合预期', 'evidence': re.search(omega_pattern if has_omega else k_pattern, pred).group()}

    # 如果提到了频率但公式结构错误（例如漏了 n+1 或 g/h 比例不对）
    if 'omega' in pred or '频率' in pred:
        # 检查是否出现了错误的比例，如 sqrt(g/h) 而没有 n 因子
        if re.search(r'sqrt\s*\(\s*g\s*/\s*[zh]\s*\)', pred) and not ('n' in pred):
            return {'result': 'fail', 'message': '频率公式缺失幂律指数 n 相关的修正项', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定频率推导的准确性', 'evidence': ''}

# rule_id=norm_f2a6027d974a99fc | domain=Electromagnetism | topic=Magnetic Dipoles and Magnetic Materials
# rule_id=norm_f2a6027d974a99fc | domain=Electromagnetism | topic=Magnetic Dipoles and Magnetic Materials
def check_norm_f2a6027d974a99fc_bc16e26d61a1(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否要求以精细结构常数 alpha 和静能 E0 表示能量
    # 匹配 alpha (\alpha) 和 E0 (E_0, mc^2)
    trigger_keywords = ['\\alpha', 'alpha', '精细结构常数']
    energy_keywords = ['E_0', 'E0', 'mc^2', '静能', 'rest energy']

    has_alpha = any(k in (question + context) for k in trigger_keywords)
    has_e0 = any(k in (question + context) for k in energy_keywords)

    if not (has_alpha and has_e0):
        return {'result': 'inconclusive', 'message': '题目未明确要求使用 alpha 和 E0 进行能量估计', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否建立了能量与 alpha^n * E0 的比例关系
    # 重点检查 prediction 中是否出现了 U/E0 或类似的比例表达式
    pred_text = prediction.replace(' ', '')
    # 匹配类似 U/E_0, E/E_0, U \approx \alpha^n E_0 的模式
    pattern_ratio = re.compile(r'([UE]/E_?0|\\alpha|alpha.*E_?0)', re.IGNORECASE)

    if not pattern_ratio.search(pred_text):
        return {'result': 'fail', 'message': '未发现建立静电/磁能与静能 E0 的比例关系', 'evidence': prediction[:200]}

    # Step 3: 符号与幂次校验 — 检查 alpha 的幂次是否在合理范围内 (通常为 alpha^2, alpha^4 等)
    # 寻找 alpha^n 或 alpha**n
    alpha_power_pattern = re.compile(r'(\\alpha|alpha)(\^|\*\*)?(\d+)?')
    alpha_matches = alpha_power_pattern.findall(pred_text)

    if not alpha_matches:
        return {'result': 'fail', 'message': '未在推导中使用精细结构常数 alpha', 'evidence': prediction[:200]}

    # 如果找到了 alpha 且有比例关系，初步判定为 pass
    return {'result': 'pass', 'message': '已建立基于 alpha 和 E0 的能量关联建模', 'evidence': str(alpha_matches)}

