# rule_id=norm_1049211fe0cf3db7 | domain=Thermodynamics & Statistical Physics | topic=Work Done by Gases and PV Diagrams
# rule_id=norm_1049211fe0cf3db7 | domain=Thermodynamics & Statistical Physics | topic=Work Done by Gases and PV Diagrams
def check_norm_1049211fe0cf3db7_c7a7d75d8863(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及 PV 图中的循环过程（正向/逆向/顺时针/逆时针）
    trigger_keywords = ['循环', 'cycle', 'PV图', 'P-V', '封闭图形', 'net work', '净功']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到循环过程净功相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否提到了面积与功的关系，以及方向（顺/逆时针）对功正负的影响
    pred_lower = prediction.lower()
    has_area_logic = any(kw in pred_lower for kw in ['面积', 'area', '封闭', 'enclosed'])
    has_direction_logic = any(kw in pred_lower for kw in ['顺时针', '逆时针', 'clockwise', 'counter-clockwise', '正循环', '负循环'])

    if not (has_area_logic or 'W' in prediction):
        return {'result': 'fail', 'message': '未提及净功与PV图面积的几何关系', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查是否包含 W = ∫PdV 或类似功的表达，并校验方向逻辑
    # 检查顺时针为正功，逆时针为负功的逻辑一致性
    if '顺时针' in pred_lower or 'clockwise' in pred_lower:
        if '负' in pred_lower and '功' in pred_lower and '正' not in pred_lower:
            return {'result': 'fail', 'message': '正循环（顺时针）功的正负判定错误', 'evidence': prediction[:200]}

    if '逆时针' in pred_lower or 'counter' in pred_lower:
        if '正' in pred_lower and '功' in pred_lower and '负' not in pred_lower:
            return {'result': 'fail', 'message': '负循环（逆时针）功的正负判定错误', 'evidence': prediction[:200]}

    # 检查公式结构 W = oint P dV
    if re.search(r'W.*=.*\\oint.*P.*dV', prediction) or re.search(r'W.*=.*\\int.*P.*dV', prediction):
        return {'result': 'pass', 'message': '正确应用了循环过程净功的几何判定与公式', 'evidence': prediction[:200]}

    if has_area_logic and has_direction_logic:
        return {'result': 'pass', 'message': '逻辑描述符合循环过程净功判定规则', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足以判定逻辑正误', 'evidence': ''}

# rule_id=norm_3f18873a3c6454c1 | domain=Thermodynamics & Statistical Physics | topic=Work Done by Gases and PV Diagrams
# rule_id=norm_3f18873a3c6454c1 | domain=Thermodynamics & Statistical Physics | topic=Work Done by Gases and PV Diagrams
def check_norm_3f18873a3c6454c1_30ebb0894077(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及已知 T=f(V) 关系求功或 PV 图状态转换
    trigger_keywords = ['T=', 'T =', '温度', '函数', '关系式', 'PV', 'P-V', '循环']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到 T=f(V) 关系式或 PV 图相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须利用 PV=nRT 将 P 替换为 V 的函数再积分
    # 检查是否出现了 P = nRT/V 的代换逻辑或积分表达式
    pred = prediction.lower()
    # 匹配 P = nRT/V 或类似的代换形式
    substitution_pattern = r'p\s*=\s*n?r\s*t\s*/\s*v|p\s*v\s*=\s*n?r\s*t'
    integral_pattern = r'\\int|integral|\int.*dv'

    has_substitution = re.search(substitution_pattern, pred)
    has_integral = re.search(integral_pattern, pred)

    # 如果是求功问题（Work），必须有代换和积分过程
    if '功' in (question + context) or 'work' in (question + context).lower():
        if not (has_substitution or 'nrt' in pred):
            return {'result': 'fail', 'message': '在求功过程中未发现利用理想气体状态方程进行 P-V 代换的逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号校验 — 检查是否包含必要的物理常数或变量 (R, n, a)
    required_symbols = ['R', 'n']
    missing_symbols = [s for s in required_symbols if s not in prediction and s not in context]

    # 如果明确是状态方程约束校验，但缺少 R 或 n 的讨论，且没有数值代入，则可能存在遗漏
    if len(missing_symbols) == len(required_symbols) and not re.search(r'\d+\.\d+', prediction):
        return {'result': 'fail', 'message': f'推理过程中缺少必要符号: {missing_symbols}', 'evidence': prediction[:100]}

    # Step 4: 检查状态参量满足性 (针对循环或转折点)
    if '循环' in (question + context) or 'cycle' in (question + context).lower():
        if 'pv' not in pred and 'nrt' not in pred:
             return {'result': 'fail', 'message': '循环过程未校验各点状态参量是否满足 PV=nRT', 'evidence': prediction[:150]}

    if has_substitution and (has_integral or 'w =' in pred.replace(' ', '')):
        return {'result': 'pass', 'message': '已按规则利用状态方程进行代换并计算', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '逻辑步骤不完整，无法判定', 'evidence': ''}

# rule_id=norm_a233549036007fc4 | domain=Thermodynamics & Statistical Physics | topic=Work Done by Gases and PV Diagrams
# rule_id=norm_a233549036007fc4 | domain=Thermodynamics & Statistical Physics | topic=Work Done by Gases and PV Diagrams
def check_norm_a233549036007fc4_63b211d2471f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及弹性势能函数 U(r) 或弹性容器压强平衡
    trigger_keywords = ['U(r)', 'potential energy', 'elastic', '弹性势能', 'r']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到弹性势能函数或弹性容器相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须通过虚功原理或力平衡建立 P_in - P_out = dU/dV
    # 核心逻辑是 dV = 4πr²dr，因此 P_diff = (dU/dr) / (4πr²)
    pred = prediction.lower()

    # 检查是否直接将能量 U 与 PV 项等值（错误建模的典型特征）
    if re.search(r'u\s*=\s*p\s*v', pred) or re.search(r'u\s*=\s*nrt', pred):
        return {'result': 'fail', 'message': '错误地将能量项直接等值于状态方程项，未通过压强平衡建模', 'evidence': 'Detected direct U=PV or U=nRT equivalence'}

    # Step 3: 符号与公式校验 — 寻找 P_in - P_out = (1/4πr²) * (dU/dr) 的变体
    # 匹配特征：dU/dr, 4*pi*r^2, 或者 P = ... dU/dr
    has_diff_u = 'du/dr' in pred.replace(' ', '') or 'd u / d r' in pred
    has_volume_factor = '4' in pred and 'pi' in pred and 'r' in pred
    has_pressure_diff = 'p' in pred and ('-' in pred or '=' in pred)

    if has_diff_u and (has_volume_factor or 'dv' in pred):
        # 进一步检查公式结构是否包含 P = (dU/dr) / (4πr²)
        if re.search(r'p.*=.*du/dr.*/.*r', pred.replace(' ', '')) or re.search(r'p.*4.*pi.*r.*=.*du/dr', pred.replace(' ', '')):
            return {'result': 'pass', 'message': '成功通过虚功原理或压强平衡建立模型', 'evidence': 'Found P-dU/dV relationship'}

    # 如果提到了 dU/dr 但没有体现除以面积/体积导数，或者完全没提到导数关系
    if not has_diff_u:
        return {'result': 'fail', 'message': '建模缺失关键步骤：未利用 dU/dV 或虚功原理建立压强平衡', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到相关物理量但无法确定建模逻辑的严谨性', 'evidence': ''}

# rule_id=norm_ac0d3536638ffe4b | domain=Thermodynamics & Statistical Physics | topic=Work Done by Gases and PV Diagrams
# rule_id=norm_ac0d3536638ffe4b | domain=Thermodynamics & Statistical Physics | topic=Work Done by Gases and PV Diagrams
def check_norm_ac0d3536638ffe4b_54df1520651c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及PV图中的斜直线过程（非等压/等容）
    # 匹配关键词如 PV图, 直线, 线性变化, 状态A到状态B, 且排除单纯的等压/等容描述
    trigger_keywords = ['PV', 'P-V', '压强', '体积', '直线', '线性']
    if not any(k in (question + context) for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到PV图直线过程场景', 'evidence': ''}

    # 排除纯等压或等容过程的干扰
    if '等压' in (question + context) and '等容' in (question + context) and '直线' not in (question + context):
        return {'result': 'inconclusive', 'message': '可能为简单等值过程，不适用本规则', 'evidence': ''}

    # Step 2: 检查逻辑 — 功W是否按梯形面积计算，内能增量是否基于PV乘积差
    pred = prediction.lower()

    # 检查是否错误套用了等压/等容热容公式 (如 Q = nCpDT 或 nCvDT 在非等值过程中直接使用)
    # 这是一个典型的建模错误
    if re.search(r'q\s*=\s*n\s*c_[pv]', pred) or re.search(r'q\s*=\s*c_[pv]\s*\*\s*delta', pred):
        return {'result': 'fail', 'message': '在非等值直线过程中错误套用了等压/等容摩尔热容公式', 'evidence': prediction}

    # Step 3: 符号/公式校验 — 检查功 W = 1/2(P1+P2)(V2-V1) 和 Q = ΔU + W 的结构
    # 检查功的梯形面积公式特征
    work_pattern = r'1/2.*\(.*p_?[ab12]\s*\+\s*p_?[ab12].*\).*\(.*v_?[ab12]\s*-\s*v_?[ab12].*\)'
    # 检查内能与PV关系的特征 (delta U = Cv/R * delta(PV))
    internal_energy_pattern = r'p_?[b2]\s*v_?[b2]\s*-\s*p_?[a1]\s*v_?[a1]'

    has_work = re.search(work_pattern, pred, re.IGNORECASE)
    has_u = re.search(internal_energy_pattern, pred, re.IGNORECASE)

    if has_work and has_u:
        return {'result': 'pass', 'message': '正确使用了梯形面积计算功并结合了内能状态函数特性', 'evidence': prediction}

    # 如果提到了 Q = delta U + W 但公式细节不全，保持保守
    if 'q' in pred and ('delta u' in pred or '内能' in pred) and ('w' in pred or '功' in pred):
        return {'result': 'inconclusive', 'message': '检测到热力学第一定律框架，但具体计算细节待确认', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '未发现明确的建模错误或完整的正确推导', 'evidence': ''}

# rule_id=norm_aee4d04fc67d1b94 | domain=Thermodynamics & Statistical Physics | topic=Work Done by Gases and PV Diagrams
# rule_id=norm_aee4d04fc67d1b94 | domain=Thermodynamics & Statistical Physics | topic=Work Done by Gases and PV Diagrams
def check_norm_aee4d04fc67d1b94_ae5c06772ea4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及新参数定义 a = κ/κ0 或类似的标准化过程
    # 触发关键词：定义参数、标准化、比值、kappa
    trigger_keywords = ['定义', '参数', 'kappa', 'κ', '标准化', 'ratio']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到参数标准化定义场景', 'evidence': ''}

    # 检查是否包含 kappa_0 或 kappa/kappa_0 的形式
    if not re.search(r'\\kappa_0|kappa0|\\kappa/\\kappa_0', question + context):
        return {'result': 'inconclusive', 'message': '未发现 κ0 相关定义', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证 prediction 是否尝试消去 P0, V0, T0 等中间变量
    # 检查是否提到了理想气体状态方程 P0V0 = n0RT0 进行代换
    pred_text = prediction.replace(' ', '')
    elimination_keywords = ['P_0V_0', 'n_0RT_0', '消去', '代入', '代换', 'substitution']
    has_elimination = any(kw in prediction for kw in elimination_keywords) or re.search(r'P_0V_0.*n_0RT_0', pred_text)

    # Step 3: 符号校验 — 检查最终表达式是否仅含无量纲比值 λ 和摩尔数比 n/n0
    # 必须包含 lambda (\\lambda) 和 n/n_0
    required_symbols = [r'\\lambda', r'n/n_0', r'n/n0']
    missing_symbols = [sym for sym in [r'\\lambda', r'n/n_0'] if not re.search(sym.replace('\\', '\\\\'), prediction)]

    # 如果 prediction 中依然保留了 P0, V0, T0 等原始状态量，则视为未完成标准化
    residual_vars = re.search(r'P_0|V_0|T_0|r_0', prediction)

    if missing_symbols and not re.search(r'n/n0', prediction):
        return {'result': 'fail', 'message': '最终表达式缺失必要的无量纲比值符号 (λ 或 n/n0)', 'evidence': prediction[-200:]}

    if residual_vars and ('=' in prediction.split('\n')[-1] or 'a=' in pred_text):
        # 如果在结论部分依然看到 P0/V0 等，说明未消去中间变量
        return {'result': 'fail', 'message': '参数标准化不彻底，仍保留了中间变量 P0/V0/T0', 'evidence': residual_vars.group()}

    if has_elimination and (re.search(r'\\lambda', prediction) or 'n/n' in prediction):
        return {'result': 'pass', 'message': '成功执行参数标准化并消去中间变量', 'evidence': '检测到代换逻辑与无量纲比值'}

    return {'result': 'inconclusive', 'message': '无法确定标准化校验是否完整', 'evidence': ''}

# rule_id=norm_ea1e504d82f31c89 | domain=Thermodynamics & Statistical Physics | topic=Work Done by Gases and PV Diagrams
# rule_id=norm_ea1e504d82f31c89 | domain=Thermodynamics & Statistical Physics | topic=Work Done by Gases and PV Diagrams
def check_norm_ea1e504d82f31c89_9dd563a0bd82(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否包含 T-V 或 P-V 图示且涉及多段循环过程
    trigger_keywords = ['T-V', 'P-V', 'PV图', 'TV图', '循环过程', 'cycle', 'diagram']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到T-V或P-V图示循环过程场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否盲目假设等温/等容，而忽略了图示的几何解析式（如直线斜率）
    pred_lower = prediction.lower()
    # 检查是否包含对几何特征（斜率、截距、直线方程）的分析
    geometry_analysis = ['斜率', 'slope', '截距', 'intercept', '解析式', 'linear', '直线', 'equation']
    has_geometry = any(kw in pred_lower for kw in geometry_analysis)

    # 检查是否存在潜在的盲目假设（在没有明确说明的情况下直接使用等温/等容结论）
    blind_assumptions = ['假设是等温', '假设为等容', 'assume isothermal', 'assume isochoric']
    has_blind_assumption = any(kw in pred_lower for kw in blind_assumptions)

    # Step 3: 符号覆盖检查 (P, T, V)
    required_symbols = ['P', 'T', 'V']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    # 判定逻辑：如果存在盲目假设且缺乏几何解析过程，则判定为 fail
    if has_blind_assumption and not has_geometry:
        return {
            'result': 'fail',
            'message': '模型在处理循环过程时盲目假设了特殊过程（如等温/等容），未优先通过图示几何特征确定解析式。',
            'evidence': re.search(r'.{0,50}(假设|等温|等容).{0,50}', prediction).group(0) if re.search(r'(假设|等温|等容)', prediction) else prediction[:100]
        }

    # 如果明确提到了斜率或直线方程，且使用了 P, V, T 符号进行推导，则 pass
    if has_geometry and len(missing_symbols) <= 1:
        return {
            'result': 'pass',
            'message': '模型正确识别了图示几何特征并尝试建立解析式。',
            'evidence': '检测到几何分析关键词及相关物理量符号'
        }

    return {'result': 'inconclusive', 'message': '无法确定模型是否遵循了路径识别优先级逻辑', 'evidence': ''}

# rule_id=norm_0ea1b6c5dd8d90c9 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_0ea1b6c5dd8d90c9 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_0ea1b6c5dd8d90c9_d3f2660d424c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及绝热过程及高压缩比 (>5)
    # 匹配绝热方程特征 P*V^gamma 或 T*V^(gamma-1)
    adiabatic_pattern = r'(P[Vv]\^|T[Vv]\^|P_1V_1\^|P_2V_2\^|adiabatic|绝热)'
    if not re.search(adiabatic_pattern, question + context, re.IGNORECASE):
        return {'result': 'inconclusive', 'message': '未检测到绝热过程相关描述', 'evidence': ''}

    # 提取压缩比 epsilon (V1/V2)，判断是否 > 5
    ratio_match = re.search(r'(?:compression ratio|压缩比|\epsilon|r)\s*[=:]\s*(\d+\.?\d*)', question + context, re.IGNORECASE)
    if ratio_match:
        epsilon = float(ratio_match.group(1))
        if epsilon <= 5:
            return {'result': 'inconclusive', 'message': '压缩比未达到触发阈值 (>5)', 'evidence': f'epsilon={epsilon}'}
    else:
        # 如果没显式写压缩比，但有 V1/V2 的数值，尝试简单匹配
        v_ratio = re.findall(r'(\d+\.?\d*)\s*/\s*(\d+\.?\d*)', question + context)
        is_high_ratio = False
        for n, d in v_ratio:
            if float(d) != 0 and float(n)/float(d) > 5:
                is_high_ratio = True
                break
        if not is_high_ratio:
            return {'result': 'inconclusive', 'message': '无法确定压缩比或压缩比过小', 'evidence': ''}

    # Step 2: 检查逻辑 — 校验幂次运算精度 (P2 = P1 * epsilon^gamma)
    # 重点检查 gamma=1.4 时，epsilon^1.4 的计算是否准确
    # 规则示例：epsilon=9.5, 9.5^1.4 ≈ 23.4 (若写成 20 则为错误)
    pred_text = prediction.replace(' ', '')

    # 查找是否存在类似 epsilon^1.4 或 epsilon^1.40 的计算过程
    calc_pattern = re.search(r'(\d+\.?\d*)\^\{?1\.4\}?\s*=\s*(\d+\.?\d*)', pred_text)
    if calc_pattern:
        base = float(calc_pattern.group(1))
        reported_val = float(calc_pattern.group(2))
        expected_val = base ** 1.4

        # 允许 2% 的相对误差，如果误差过大（如 9.5^1.4 算成 20，误差约 14%）则报错
        if abs(reported_val - expected_val) / expected_val > 0.05:
            return {
                'result': 'fail',
                'message': f'绝热过程幂次运算精度不足：{base}^1.4 预期约 {expected_val:.2f}，实际给出 {reported_val}',
                'evidence': calc_pattern.group(0)
            }
        else:
            return {'result': 'pass', 'message': '幂次运算精度校验通过', 'evidence': calc_pattern.group(0)}

    # Step 3: 符号覆盖检查 (required_symbols: P_1, epsilon, kappa)
    if 'P_1' in prediction and ('epsilon' in prediction or 'r' in prediction) and ('1.4' in prediction or 'gamma' in prediction):
        return {'result': 'pass', 'message': '包含必要的绝热过程计算符号', 'evidence': 'P_1, epsilon, gamma detected'}

    return {'result': 'inconclusive', 'message': '未发现明确的数值计算步骤', 'evidence': ''}

# rule_id=norm_19bda7540a46eec8 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_19bda7540a46eec8 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_19bda7540a46eec8_6aa887ee4fa8(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否包含分式近似提示（如 1/(1-x) 或近似符号）以及线性关系需求
    trigger_keywords = ['1/(1-x)', '1/(1+x)', '近似', '展开', '忽略高次项', 'linear', '线性']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '题目未明确要求分式近似展开或系数匹配', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否执行了展开步骤并尝试匹配系数 (H = a + bh 形式)
    # 重点检查是否出现了类似 H0(1 + ...) 的展开结构或对 P_atm, H, rho, g 等符号的处理
    pred_lower = prediction.lower()
    has_expansion = re.search(r'1\s*[\+\-]\s*[x\epsilon]|1\/\(1[\+\-]\w+\)', pred_lower) or '展开' in pred_lower
    has_linear_form = re.search(r'[Hh]\s*=\s*\w+\s*[\+\-]\s*\w+\s*[Hh]', pred_lower) or '系数' in pred_lower

    if not (has_expansion or has_linear_form):
        return {'result': 'fail', 'message': '推理过程中缺失近似展开步骤或线性系数匹配逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号校验 — 检查是否包含关键物理量 P_atm, H, rho, g 等
    required_symbols = ['P', 'H', 'g']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)
    if symbol_count < 2:
        return {'result': 'fail', 'message': '建模过程中缺失关键物理量符号(P_atm, H, rho, g)', 'evidence': prediction[:150]}

    # Step 4: 结构校验 — 检查是否出现了 canonical 提示中的核心展开项结构
    # H0 * (1 + (rho*g*h/P))
    if re.search(r'H_?0.*\(.*1\s*\+\s*.*g.*h.*P', prediction) or re.search(r'H_?0.*g.*h.*P', prediction):
        return {'result': 'pass', 'message': '成功识别近似展开项并进行系数匹配建模', 'evidence': '检测到符合 H = H0 + (H0*ρg/P_atm)h 逻辑的推导'}

    return {'result': 'inconclusive', 'message': '推导过程存在，但无法确定系数匹配的准确性', 'evidence': prediction[-150:]}

# rule_id=norm_21c24a1fdf4dea67 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_21c24a1fdf4dea67 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_21c24a1fdf4dea67_68f61a84acf0(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否为绝热压缩/活塞做功场景
    trigger_keywords = ['insulated cylinder', 'force applied to piston', 'slowly moves', 'adiabatic', '绝热', '活塞', '压缩']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到绝热压缩或活塞做功的相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否包含功与内能增量的等量关系 (W = ΔU)
    pred = prediction.lower()
    # 检查是否错误地假设温度不变（绝热压缩温度必升）
    if 'isothermal' in pred or 'temperature remains constant' in pred or '温度不变' in pred:
        return {'result': 'fail', 'message': '绝热压缩过程中错误地假设温度不变，违反热力学第一定律', 'evidence': prediction[:200]}

    # 检查是否提及功(W)与内能(U/Internal Energy)的关系
    work_terms = ['work', 'done', '做功', 'W']
    internal_energy_terms = ['internal energy', 'delta u', '内能', 'ΔU', 'U_']
    has_work = any(w in pred for w in work_terms)
    has_internal = any(ie in pred for ie in internal_energy_terms)

    if not (has_work and has_internal):
        return {'result': 'fail', 'message': '推理过程中缺失功与内能增量的能量守恒分析', 'evidence': prediction[:200]}

    # Step 3: 公式结构校验 (W = ΔU = nCvΔT)
    # 匹配类似 W = delta U 或 delta U = nCv... 的结构
    energy_eq_pattern = r'(W|work).*(=|is|equals).*(delta\s*u|internal\s*energy|\Delta\s*U)'
    temp_change_pattern = r'(T_final|T2|T_f).*(-|minus).*(T_initial|T1|T_i)'

    if re.search(energy_eq_pattern, pred, re.IGNORECASE):
        return {'result': 'pass', 'message': '正确建立了功与内能增量的等量关系', 'evidence': re.search(energy_eq_pattern, pred, re.IGNORECASE).group()}

    if 'n' in pred and 'C' in pred and ('T' in pred or 'temperature' in pred):
        return {'result': 'pass', 'message': '包含了基于摩尔定容热容的内能计算逻辑', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到相关场景但无法确定能量守恒方程的准确性', 'evidence': ''}

# rule_id=norm_31afeeede09fb746 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_31afeeede09fb746 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_31afeeede09fb746_228d925b49e0(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多个气室及机械限位(ledge/stop/limit)
    trigger_keywords = ['ledge', 'stop', '限位', '台阶', '挡块', '固定']
    chamber_keywords = ['chamber', 'gas', 'piston', '气室', '活塞']
    combined_text = (question + context).lower()

    has_ledge = any(kw in combined_text for kw in trigger_keywords)
    has_chambers = any(kw in combined_text for kw in chamber_keywords)

    if not (has_ledge and has_chambers):
        return {'result': 'inconclusive', 'message': '未检测到涉及机械限位的多气室热力学场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 确认在限位未解除时，是否将体积视为常量(V=const)
    pred = prediction.lower()
    # 寻找描述体积不变或等容过程的关键词
    isochoric_indicators = ['constant volume', 'volume remains', 'v is constant', '体积不变', '等容', 'v=const']
    # 寻找压力与温度关系的公式特征 P1/T1 = P0/T0
    pressure_temp_ratio = re.search(r'p[\/_]?[012]\s*/\s*t[\/_]?[012]\s*=\s*p[\/_]?[012]\s*/\s*t[\/_]?[012]', pred)

    # 如果提到限位但没有体现体积受限的逻辑（即仍在变化体积），则判定为逻辑错误
    if 'ledge' in pred or 'stop' in pred or '限位' in pred:
        if not any(ind in pred for ind in isochoric_indicators) and not pressure_temp_ratio:
            return {'result': 'fail', 'message': '在限位阶段未正确识别等容过程逻辑，应保持体积不变仅压力随温度变化', 'evidence': prediction[:200]}

    # Step 3: 符号覆盖检查 (P, T, V)
    required_symbols = ['P', 'T', 'V']
    missing_symbols = [s for s in required_symbols if s not in prediction.upper()]
    if len(missing_symbols) > 1:
        return {'result': 'fail', 'message': f'缺少必要的热力学状态参量符号: {missing_symbols}', 'evidence': prediction[:100]}

    if pressure_temp_ratio or any(ind in pred for ind in isochoric_indicators):
        return {'result': 'pass', 'message': '正确处理了限位约束下的等容变化逻辑', 'evidence': str(pressure_temp_ratio.group(0)) if pressure_temp_ratio else 'isochoric detected'}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了限位阶段的状态方程', 'evidence': ''}

# rule_id=norm_3a435de1f684c31b | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_3a435de1f684c31b | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_3a435de1f684c31b_578ea87c0b67(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及热力学状态参数演化（如温度、体积、压强变化）
    trigger_keywords = ['isothermal', 'adiabatic', 'process', 'initial', 'final', 'state', '等温', '绝热', '过程', '初态', '末态']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到热力学状态演化场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别初末态参数（T1, T2, V1, V2 等）并判断是否错误地设为相等
    # 寻找类似 T1=T2 或 T_initial = T_final 的模式，且题目并非明确的等温过程
    is_isothermal = 'isothermal' in (question + context).lower() or '等温' in (question + context)

    # 匹配 T1=T2, T_i=T_f 等逻辑表达
    same_state_pattern = re.search(r'(T_?[1i]\s*=\s*T_?[2f])|(V_?[1i]\s*=\s*V_?[2f])', prediction)
    if same_state_pattern and not is_isothermal:
        # 如果不是等温过程却出现了温度相等，或者不是等容过程却出现了体积相等，视为逻辑风险
        if 'adiabatic' in (question + context).lower() or '绝热' in (question + context):
            return {'result': 'fail', 'message': '在非等值过程中错误地假设了状态参数不变', 'evidence': same_state_pattern.group()}

    # Step 3: 符号/公式校验 — 检查绝热方程等关键公式的结构
    # 检查是否包含 T * V^(gamma-1) 类型的结构
    adiabatic_struct = re.search(r'T.*V.*(\^|\*\*).*(gamma|\d)', prediction, re.IGNORECASE)
    if 'adiabatic' in (question + context).lower() or '绝热' in (question + context):
        if not adiabatic_struct:
            return {'result': 'fail', 'message': '绝热过程计算缺失必要的幂次状态方程', 'evidence': prediction[:200]}

        # 检查初末态是否代入了相同数值导致无变化
        # 简单检查：如果预测结果中 T2/T1 = 1 或 V2/V1 = 1 且题目要求变化，则报错
        if re.search(r'(T_?[2f]/T_?[1i]\s*=\s*1)|(V_?[2f]/V_?[1i]\s*=\s*1)', prediction):
            return {'result': 'fail', 'message': '计算结果导致状态未发生任何变化，违反演化逻辑', 'evidence': 'Ratio equals 1 in non-static process'}

    # Step 4: 综合判定
    if adiabatic_struct or re.search(r'P.*V.*=.*n.*R.*T', prediction):
        return {'result': 'pass', 'message': '状态演化逻辑与公式应用基本一致', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '无法确定状态演化逻辑是否一致', 'evidence': ''}

# rule_id=norm_3f4f49a4e45a6671 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_3f4f49a4e45a6671 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_3f4f49a4e45a6671_6f26c6fafa12(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多个绝热腔室、活塞移动或力学平衡
    trigger_keywords = ['绝热', 'adiabatic', '腔室', 'chamber', '活塞', 'piston', '平衡', 'equilibrium']
    q_c_text = (question + context).lower()
    if not all(k in q_c_text for k in ['绝热', '活塞']):
        return {'result': 'inconclusive', 'message': '未检测到绝热腔室与活塞移动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否仅套用内能守恒 (U1+U2=U_total) 而忽略了绝热过程的功交换
    pred = prediction.lower()
    # 如果只看到内能相加，没有看到绝热方程或功的计算，则可能存在建模错误
    has_energy_sum = re.search(r'u_?1\s*\+\s*u_?2', pred) or re.search(r'n_?1.*t_?1\s*\+\s*n_?2.*t_?2', pred)
    has_adiabatic_eq = re.search(r't.*v.*gamma', pred) or re.search(r'p.*v.*gamma', pred) or 'gamma' in pred

    # Step 3: 符号与公式校验 — 检查是否联立了绝热方程 TV^(gamma-1)=C
    # 匹配 T*V^(gamma-1) 的变体
    adiabatic_pattern = r't.*v.*(\^|\*\*)\(?gamma\s*-\s*1\)?'
    found_adiabatic = re.search(adiabatic_pattern, pred, re.IGNORECASE)

    if has_energy_sum and not (has_adiabatic_eq or found_adiabatic):
        return {
            'result': 'fail',
            'message': '模型错误：在有压强差导致的活塞位移过程中，仅使用了内能守恒，未联立绝热方程考虑各部分功的交换。',
            'evidence': prediction[:200]
        }

    if found_adiabatic and ('p1' in pred or 'p2' in pred or '平衡' in pred):
        return {
            'result': 'pass',
            'message': '正确应用了绝热方程并考虑了末态平衡条件。',
            'evidence': re.search(adiabatic_pattern, prediction, re.IGNORECASE).group(0)
        }

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了绝热多室平衡的功交换逻辑', 'evidence': ''}

# rule_id=norm_462b3290bc21e7e7 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_462b3290bc21e7e7 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_462b3290bc21e7e7_34fb06709d87(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及功率(Power)求解且包含循环过程(Cycle)
    trigger_keywords = ['功率', 'power', 'P =', 'P=']
    cycle_keywords = ['循环', 'cycle', '每秒', '频率', 'frequency', 'Hz', '周期', 'period']

    combined_text = (question + context).lower()
    is_power_req = any(kw in combined_text for kw in trigger_keywords)
    is_cycle_context = any(kw in combined_text for kw in cycle_keywords)

    if not (is_power_req and is_cycle_context):
        return {'result': 'inconclusive', 'message': '题目未明确要求求解循环功率或不涉及频率/周期', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否通过声速/波长/频率确定了周期 T 或频率 f，并用于功率计算
    pred = prediction.lower()
    # 检查是否提到了核心物理量：功(W), 频率(f/v/n), 周期(T), 声速(v_s), 波长(lambda)
    has_work = re.search(r'([Ww]|work|功)', pred)
    has_time_factor = re.search(r'([Ff]|频率|frequency|[Tt]|周期|period|hz|每秒)', pred)

    if not (has_work and has_time_factor):
        return {'result': 'fail', 'message': '预测中缺失功(W)或频率/周期(f/T)等关键建模要素', 'evidence': prediction[:200]}

    # Step 3: 公式结构校验 — 检查 P = W*f 或 P = W/T 或涉及 v_s/lambda 的转换
    # 匹配 P = W*f, P = W/T, P = W*(v/lambda) 等模式
    patterns = [
        r'p\s*=\s*w\s*[*·/]\s*[tf]',
        r'p\s*=\s*w\s*\*\s*v\s*/\s*[λ\\lambda]',
        r'w\s*[*·]\s*f',
        r'w\s*/\s*t',
        r'w\s*[*·]\s*v_s\s*/\s*[λ\\lambda]'
    ]

    found_formula = False
    for pattern in patterns:
        if re.search(pattern, pred):
            found_formula = True
            break

    if found_formula:
        return {'result': 'pass', 'message': '已正确建立功率与频率/周期的物理关联', 'evidence': re.search(r'.{0,30}p\s*=.+?.{0,30}', pred).group(0) if re.search(r'p\s*=', pred) else 'Found formula pattern'}

    # 如果有计算过程但没匹配到标准公式，保守返回 inconclusive
    if 'p' in pred and ('/' in pred or '*' in pred):
        return {'result': 'inconclusive', 'message': '检测到计算尝试但公式形式不标准', 'evidence': prediction[:150]}

    return {'result': 'fail', 'message': '未发现功率 P = W * f 或 P = W / T 的计算逻辑', 'evidence': prediction[:200]}

# rule_id=norm_49f4cf4ec57abb8b | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_49f4cf4ec57abb8b | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_49f4cf4ec57abb8b_8ff7d2c597ef(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 涉及理想气体绝热上升、重力场、温度随高度变化
    trigger_keywords = ['绝热', 'adiabatic', 'lapse rate', '温减率', 'dT/dy', 'dT/dz', '温度随高度']
    if not any(k in (question + context).lower() for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到绝热大气温减率相关场景', 'evidence': ''}

    # Step 2: 检查关键符号是否存在 (M, R, g, gamma)
    required_symbols = ['R', 'g', 'gamma', 'M']
    # 兼容希腊字母或拼写
    pred_text = prediction.replace('\\gamma', 'gamma').replace('γ', 'gamma')
    missing_symbols = [s for s in required_symbols if s not in pred_text]
    if len(missing_symbols) > 1: # 允许缺失一个（如M可能被摩尔质量符号替代），缺失多个则判定为未进行公式推导
        return {'result': 'inconclusive', 'message': '预测中缺少必要的物理符号', 'evidence': f'缺失符号: {missing_symbols}'}

    # Step 3: 验证系数结构是否为 (gamma-1)/gamma 而非 gamma/(gamma-1)
    # 匹配类似 (gamma-1)/gamma 或 (1-1/gamma) 的结构
    correct_pattern = r'\(gamma\s*-\s*1\)\s*/\s*gamma'
    wrong_pattern = r'gamma\s*/\s*\(gamma\s*-\s*1\)'

    # 检查是否存在错误的倒数形式
    if re.search(wrong_pattern, pred_text):
        return {
            'result': 'fail',
            'message': '绝热温减率公式系数错误，使用了 gamma/(gamma-1) 而非 (gamma-1)/gamma',
            'evidence': re.search(wrong_pattern, pred_text).group()
        }

    # 检查是否存在正确形式或等价形式
    if re.search(correct_pattern, pred_text) or '1/gamma' in pred_text:
        # 进一步检查是否包含 R 且在分母位置（量纲校验 [K/L]）
        # dT/dy = - (gamma-1)/gamma * (Mg/R)
        if re.search(r'R', pred_text):
            return {'result': 'pass', 'message': '公式结构及系数校验通过', 'evidence': '检测到正确的 (gamma-1)/gamma 结构'}

    return {'result': 'inconclusive', 'message': '未能明确识别公式结构', 'evidence': prediction[:100]}

# rule_id=norm_5055c57700e2d7d2 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_5055c57700e2d7d2 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_5055c57700e2d7d2_b510b9eaaddf(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及初始平衡态后的微小外力扰动或新平衡态建立
    trigger_keywords = ['平衡', '外力', '活塞', '压强', 'F', 'force', 'piston', 'equilibrium']
    q_c_text = (question + context).lower()
    if not any(k in q_c_text for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到热力学平衡态扰动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否错误地将外力直接等同于末态压强产生的力 (F = P_final * A)
    # 规则要求 F = (P_final - P_initial) * A 或 ΔP * A
    pred = prediction.lower()

    # 寻找错误的模式：F = P * A (其中P是末态或单一压强，未体现差值)
    # 寻找正确的模式：F = (P2 - P1)A, F = ΔP * A, F + P1*A = P2*A 等
    has_delta_p = re.search(r'f\s*=\s*\(?p[\d_]*final\s*-\s*p[\d_]*initial\)?\s*\*?\s*a', pred) or \
                  re.search(r'f\s*=\s*\(?p_2\s*-\s*p_1\)?\s*\*?\s*a', pred) or \
                  re.search(r'f\s*=\s*\\delta\s*p\s*\*?\s*a', pred) or \
                  re.search(r'f\s*\+\s*p[\d_]*1\s*\*?\s*a\s*=\s*p[\d_]*2\s*\*?\s*a', pred)

    # 检查是否存在典型的错误逻辑：直接 F = P_final * A
    has_wrong_logic = re.search(r'f\s*=\s*p[\d_]*(?:final|2)\s*\*?\s*a(?!\s*-\s*p)', pred)

    # Step 3: 判定结果
    if has_delta_p:
        return {'result': 'pass', 'message': '正确使用了压强差计算受力平衡', 'evidence': '检测到符合 F=ΔP*A 的逻辑'}

    if has_wrong_logic:
        return {'result': 'fail', 'message': '错误地将外力等同于末态压强产生的力，忽略了初始压强的抵消作用', 'evidence': '检测到 F = P_final * A 的错误逻辑'}

    # 如果 prediction 中提到了 F 和 A 但没有明确的 ΔP 关系，且 answer 中包含此类逻辑，则进一步保守检查
    if 'f' in pred and 'a' in pred and ('p' in pred or '压强' in pred):
        return {'result': 'inconclusive', 'message': '检测到受力分析但公式结构不明确', 'evidence': pred[:200]}

    return {'result': 'inconclusive', 'message': '证据不足', 'evidence': ''}

# rule_id=norm_668eafceacc229cb | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_668eafceacc229cb | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_668eafceacc229cb_58a747de207c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否为“快速/突发”且“绝热”的过程
    q_c = (question + context).lower()
    is_fast = any(kw in q_c for kw in ['fast', 'sudden', 'rapidly', '快速', '突然', '骤然'])
    is_adiabatic = any(kw in q_c for kw in ['adiabatic', 'no heat exchange', '绝热', '不计热交换'])

    if not (is_fast and is_adiabatic):
        return {'result': 'inconclusive', 'message': '未检测到快速绝热压缩/充气场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否错误使用了可逆绝热方程 P*V^gamma = C
    pred = prediction.lower()
    # 寻找 P*V^gamma 或 T*V^(gamma-1) 的模式
    reversible_pattern = r'p.*v\^.*gamma|v\^.*gamma-1|p1.*v1\^.*p2.*v2\^'
    if re.search(reversible_pattern, pred):
        # 如果在快速非平衡过程中使用了可逆公式，判定为建模错误
        return {
            'result': 'fail',
            'message': '在快速非平衡绝热过程中错误套用了准静态可逆绝热方程 (P*V^gamma=C)',
            'evidence': re.search(reversible_pattern, pred).group() if re.search(reversible_pattern, pred) else pred[:100]
        }

    # Step 3: 符号/公式校验 — 检查是否使用了正确的能量方程 ΔU = W = P_ext * ΔV
    # 核心结构：Cv*(Tf-Ti) = P_ext*(Vi-Vf)
    energy_eq_pattern = r'(c_?v|c_?m).*t.*=.*p_?(ext|0|外).*(v.*-.*v)'
    if re.search(energy_eq_pattern, pred):
        return {'result': 'pass', 'message': '正确使用了基于恒定外压的能量方程建模', 'evidence': 'detected energy equation'}

    # 检查必要符号覆盖
    required_symbols = ["C_v", "P_ext", "V_f", "V_i"]
    missing = [s for s in required_symbols if s.lower() not in pred]
    if len(missing) > 2:
        return {'result': 'fail', 'message': f'缺少关键建模符号: {missing}', 'evidence': pred[:150]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确区分了准静态与突发过程', 'evidence': ''}

# rule_id=norm_68bc9e8ecd82a311 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_68bc9e8ecd82a311 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_68bc9e8ecd82a311_c04425fc2851(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')
    full_text = (question + context).lower()
    pred_text = prediction.lower()

    # Step 1: 触发条件 — 检查是否包含“单向阀”或“向下/向上开启的阀门”
    trigger_keywords = ['单向阀', 'one-way valve', 'check valve', 'valve that can only open', 'valve only opens']
    if not any(kw in full_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到单向阀相关描述', 'evidence': ''}

    # Step 2: 检查逻辑 — 判定阀门开启方向与压强差的关系
    # 识别阀门开启方向（向下或向上）
    is_downward = 'downward' in full_text or '向下' in full_text
    is_upward = 'upward' in full_text or '向上' in full_text

    # 如果无法确定阀门开启方向，则无法判定逻辑
    if not (is_downward or is_upward):
        return {'result': 'inconclusive', 'message': '无法确定阀门开启方向', 'evidence': ''}

    # Step 3: 检查 Prediction 是否考虑了压强差导致的系统合并或独立
    # 核心逻辑：若 P_upper > P_lower 且向下开 -> 合并系统 (V1+V2)；否则独立
    has_pressure_compare = re.search(r'p_?\{?upper\}?|p_?\{?lower\}?|p_?\{?1\}?.*[><=].*p_?\{?2\}?', pred_text)
    has_volume_sum = re.search(r'v_?\{?total\}?|v_?\{?1\}?\s*\+\s*v_?\{?2\}?', pred_text)

    if is_downward:
        # 检查是否讨论了压强差决定阀门是否打开
        if 'open' not in pred_text and '打开' not in pred_text and not has_pressure_compare:
            return {'result': 'fail', 'message': '未分析压强差对单向阀开启状态的影响', 'evidence': prediction[:200]}

        # 如果预测中提到了压强差满足开启条件，应出现体积合并逻辑
        if has_pressure_compare and ('open' in pred_text or '打开' in pred_text):
            if not has_volume_sum and 'combined' not in pred_text and '合并' not in pred_text:
                return {'result': 'fail', 'message': '阀门打开后未正确将两部分气体视为统一系统计算', 'evidence': prediction[:200]}

    # Step 4: 符号一致性检查 (Symbolic Hint)
    if 'p_1' in pred_text and 'p_2' in pred_text:
        if '>' in pred_text and ('v_1' in pred_text and 'v_2' in pred_text):
            return {'result': 'pass', 'message': '逻辑符合单向阀压强判定与系统建模规则', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '逻辑分析不足以判定正误', 'evidence': ''}

# rule_id=norm_93890cae639b2251 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_93890cae639b2251 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_93890cae639b2251_fd4f7e2a9073(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及气体方程线性化、近似展开及压强平衡
    trigger_keywords = ['近似', '展开', '线性', 'H=', 'h', 'P1V1', 'P2V2']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到气体方程线性化或近似展开场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别分母中的符号与展开后的符号关系
    # 典型形式：1/(1-x) -> 1+x 或 1/(1+x) -> 1-x
    # 检查 prediction 中是否包含类似 (1-...) 展开为 (1+...) 的逻辑
    pred = prediction.replace(' ', '')

    # 匹配分母形式，如 P_atm/(P_atm - rho*g*h) 或 1/(1 - delta)
    denom_minus = re.search(r'1/\(1-([^\)]+)\)', pred)
    denom_plus = re.search(r'1/\(1\+([^\)]+)\)', pred)

    # 匹配展开后的形式，如 (1 + delta) 或 (1 - delta)
    expand_plus = re.search(r'\(1\+([^\)]+)\)', pred)
    expand_minus = re.search(r'\(1-([^\)]+)\)', pred)

    # Step 3: 符号校验 — b 的符号应与分母中 x 的符号相反
    # 情况 A: 分母是 (1-x)，展开应为 (1+x)
    if denom_minus:
        x_term = denom_minus.group(1)
        # 如果展开式中出现了 (1-x) 而不是 (1+x)，则符号错误
        if re.search(r'\(1-' + re.escape(x_term) + r'\)', pred.split('≈')[-1] if '≈' in pred else pred):
             return {'result': 'fail', 'message': '线性化展开符号错误：分母为(1-x)时展开应为(1+x)', 'evidence': denom_minus.group(0)}

    # 情况 B: 分母是 (1+x)，展开应为 (1-x)
    if denom_plus:
        x_term = denom_plus.group(1)
        if re.search(r'\(1\+' + re.escape(x_term) + r'\)', pred.split('≈')[-1] if '≈' in pred else pred):
             return {'result': 'fail', 'message': '线性化展开符号错误：分母为(1+x)时展开应为(1-x)', 'evidence': denom_plus.group(0)}

    # Step 4: 检查最终线性表达式 H = a + bh 的符号一致性
    # 如果分母含 -rho*g*h/P，则 b 应该为正；反之为负
    if 'rho' in pred or 'ρ' in pred:
        if re.search(r'1/\(1-.*rho.*h', pred) and re.search(r'H=.*-.*h', pred):
            return {'result': 'fail', 'message': '最终线性方程符号与近似展开逻辑不符', 'evidence': pred}

    if any(re.search(p, pred) for p in [r'\(1-.*\)^{-1}≈1\+.*', r'\(1\+.*\)^{-1}≈1-.*']):
        return {'result': 'pass', 'message': '检测到正确的泰勒展开符号处理', 'evidence': 'Taylor expansion sign correct'}

    return {'result': 'inconclusive', 'message': '未能明确判定展开符号的正确性', 'evidence': ''}

# rule_id=norm_974488e5feb6979d | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_974488e5feb6979d | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_974488e5feb6979d_69bae4817b06(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否同时提及“fixed partition”和“retaining ring”
    q_c = (question + context).lower()
    if not (re.search(r'fixed\s+partition', q_c) and re.search(r'retaining\s+ring', q_c)):
        return {'result': 'inconclusive', 'message': '未同时检测到固定隔板与限位环场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别预测中是否错误地认为隔板后的体积随活塞移动而改变
    # 核心逻辑：固定隔板C将空间独立，除非阀门导通，否则体积不随活塞位置改变
    pred = prediction.lower()

    # 寻找描述体积变化的关键词，如 "volume of ... changes with piston" 或 "volume ... depends on piston position"
    # 如果预测中认为被隔板隔开的特定空间（通常是靠近底部的空间）体积在变，则违反规则
    invalid_patterns = [
        r'volume\s+of\s+.*partition.*\s+changes',
        r'volume\s+of\s+.*fixed.*\s+varies',
        r'volume\s+of\s+.*chamber.*\s+depends\s+on\s+piston'
    ]

    found_error = False
    for pattern in invalid_patterns:
        if re.search(pattern, pred):
            found_error = True
            break

    if found_error:
        return {
            'result': 'fail',
            'message': '预测错误地认为固定隔板划分的独立空间体积随活塞位置改变',
            'evidence': re.search(r'.{0,50}(volume|change).{0,50}', pred).group(0) if re.search(r'volume|change', pred) else prediction[:100]
        }

    # Step 3: 检查是否正确识别了体积不变性
    if re.search(r'volume\s+of\s+.*(remains|is)\s+constant', pred) or re.search(r'independent\s+of\s+piston', pred):
        return {'result': 'pass', 'message': '正确识别了固定隔板下的几何约束', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '未明确提及隔板空间的体积变化逻辑', 'evidence': ''}

# rule_id=norm_98f1892f82b1b49d | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_98f1892f82b1b49d | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_98f1892f82b1b49d_b51c0367c76e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 题目涉及PVT状态变化但未显式说明过程性质（如绝热、等温）
    q_c = (question + context).lower()
    # 检查是否包含 P, V, T 相关的状态描述
    has_state_vars = any(x in q_c for x in ['压强', '体积', '温度', 'p-v', 'pv图', 'state'])
    # 检查是否显式说明了过程（若显式说明了绝热/等温，则不触发此优先级的判定逻辑检查）
    explicit_process = any(x in q_c for x in ['绝热', '等温', '等压', '等容', 'adiabatic', 'isothermal'])

    if not has_state_vars or explicit_process:
        return {'result': 'inconclusive', 'message': '题目已显式说明过程或未涉及PVT状态变化', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否在无证据情况下盲目套用绝热公式 T*V^(gamma-1)=C
    pred = prediction.lower()
    # 绝热过程公式特征：T*V^(gamma-1), P*V^gamma, T^gamma*P^(1-gamma)
    adiabatic_patterns = [
        r'v\^\(?[\d\.]*gamma',
        r'p\*v\^',
        r't\*v\^',
        r'绝热过程',
        r'adiabatic'
    ]

    uses_adiabatic = any(re.search(p, pred) for p in adiabatic_patterns)

    # 检查是否使用了理想气体状态方程 P*V/T = C 进行校验
    uses_ideal_gas_law = any(re.search(p, pred) for p in [r'pv/t', r'p1v1/t1', r'p2v2/t2', r'理想气体状态方程'])

    # Step 3: 判定逻辑
    # 如果使用了绝热公式但没有使用状态方程校验或PV图斜率分析，视为建模错误
    if uses_adiabatic and not uses_ideal_gas_law:
        return {
            'result': 'fail',
            'message': '在未明确过程性质时盲目套用绝热公式，未优先通过状态方程或PV图校验',
            'evidence': re.search(r'.{0,50}(v\^|p\*v|绝热).{0,50}', pred).group(0) if uses_adiabatic else pred[:100]
        }

    if uses_ideal_gas_law:
        return {'result': 'pass', 'message': '遵循了状态方程优先校验的逻辑', 'evidence': '检测到PV/T相关校验逻辑'}

    return {'result': 'inconclusive', 'message': '未检测到明确的过程判定逻辑', 'evidence': ''}

# rule_id=norm_a1eae09da94ca6e6 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_a1eae09da94ca6e6 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_a1eae09da94ca6e6_354f05d3f102(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及垂直放置的活塞、大气压、质量等要素
    trigger_keywords = ['活塞', 'piston', '大气压', 'P0', '质量', '平衡']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到垂直活塞受力平衡场景', 'evidence': ''}

    # 确认是否为垂直方向（向上/向下/重力）
    if not any(kw in (question + context) for kw in ['垂直', '竖直', 'vertical', '重力', 'mg']):
        return {'result': 'inconclusive', 'message': '未明确为垂直受力场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 活塞在气体上方时，内部压力应等于外部压力加重力产生的压强
    # 核心公式：P*A = P0*A + mg 或 P = P0 + mg/A
    pred = prediction.replace(' ', '')

    # 匹配 P = P0 + mg/A 及其变体
    pattern_p_eq = r'P\s*=\s*P_?0\s*\+\s*m\s*g\s*/\s*A'
    pattern_pa_eq = r'P\s*\*?\s*A\s*=\s*P_?0\s*\*?\s*A\s*\+\s*m\s*g'

    # 检查是否包含必要的物理量符号
    required_symbols = ['P', 'P_?0', 'm', 'g', 'A']
    missing_symbols = [s for s in ['P', 'm', 'g', 'A'] if not re.search(s, prediction)]

    # Step 3: 判定结果
    if re.search(pattern_p_eq, pred, re.IGNORECASE) or re.search(pattern_pa_eq, pred, re.IGNORECASE):
        return {'result': 'pass', 'message': '活塞受力平衡方程符合物理规律', 'evidence': re.search(pattern_pa_eq, pred, re.IGNORECASE).group() if re.search(pattern_pa_eq, pred, re.IGNORECASE) else 'P=P0+mg/A'}

    # 如果提到了受力平衡但公式错误（例如 P*A + mg = P0*A）
    wrong_pattern = r'P\s*\*?\s*A\s*\+\s*m\s*g\s*=\s*P_?0\s*\*?\s*A'
    if re.search(wrong_pattern, pred, re.IGNORECASE):
        return {'result': 'fail', 'message': '活塞受力平衡方向错误：内部压力应抵消外部压力与重力之和', 'evidence': re.search(wrong_pattern, pred, re.IGNORECASE).group()}

    if len(missing_symbols) >= 2:
        return {'result': 'inconclusive', 'message': '预测中缺失关键物理量符号，无法判定方程', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '未发现明确的平衡方程表达', 'evidence': ''}

# rule_id=norm_a43279c83c3b3849 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_a43279c83c3b3849 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_a43279c83c3b3849_b6f474ce72fb(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否包含多阶段演化描述
    trigger_keywords = ['preceding stage', 'following a large expansion', '前一阶段', '膨胀后']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多阶段演化或膨胀后的初始值校验场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否直接套用了环境常量（如 P0）而忽略了前一阶段末态的计算
    # 规则要求根据前一阶段末态重新计算初始状态量，若预测中直接声明 P_i = P_0 或 T_i = T_0 且未体现体积/半径变化关系，则视为错误
    pred_lower = prediction.lower()

    # 检查是否包含必要的物理量符号
    required_symbols = ['P_0', 'P_i', 'R_0', 'R_i']
    missing_symbols = [s for s in required_symbols if s not in prediction and s.replace('_', '') not in prediction]

    # 如果预测中完全没有提到压力或半径的变化关系，且直接使用了初始环境值
    if len(missing_symbols) >= 2:
        return {'result': 'fail', 'message': '预测中缺失关键的状态量符号（P_i, R_i等），可能未考虑前一阶段演化结果', 'evidence': prediction[:200]}

    # Step 3: 公式结构校验 — 检查是否体现了 P_i = P_0 * (R_0 / R_i)^3 或类似的体积反比关系
    # 匹配类似 P_i = P_0 * (R_0/R_i)^3 的结构
    pattern_relation = r'P_?i\s*=\s*P_?0\s*\*?\s*\(?R_?0\s*/\s*R_?i\)?\s*\^?\s*3?'
    if re.search(pattern_relation, prediction.replace(' ', '')):
        return {'result': 'pass', 'message': '已正确根据前一阶段末态（半径/体积变化）重新计算初始压力', 'evidence': re.search(pattern_relation, prediction.replace(' ', '')).group()}

    # 如果预测中直接将初始压力设为环境常量而没有计算过程
    if re.search(r'P_?i\s*=\s*P_?0(?!\s*\*)', prediction.replace(' ', '')):
        return {'result': 'fail', 'message': '预测直接套用了环境常量作为当前阶段初始值，未根据前序阶段演化重新计算', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确执行了多阶段初始值校验', 'evidence': ''}

# rule_id=norm_a5e881b7ef8e6307 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_a5e881b7ef8e6307 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_a5e881b7ef8e6307_8e01f4ef03a6(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及大气温减率、环境梯度或垂直递减率
    trigger_keywords = ['温减率', '递减率', 'lapse rate', 'environmental gradient', 'dT/dy', 'dT/dz']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到大气温减率相关计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 从 prediction 中提取数值并验证量级
    # 匹配数值及其单位 (K/m, K/km, ℃/m, ℃/km)
    # 重点关注 dT/dy 或 dT/dz 的计算结果
    pattern = r'([\d\.]+)\s*(K/m|K/km|℃/m|℃/km|deg/m|deg/km)'
    matches = re.findall(pattern, prediction, re.IGNORECASE)

    if not matches:
        return {'result': 'inconclusive', 'message': '未在预测中找到明确的温减率数值结果', 'evidence': ''}

    for val_str, unit in matches:
        try:
            val = float(val_str)
            unit = unit.lower()

            # 统一换算为 K/m 进行比较
            val_in_k_m = val
            if 'km' in unit:
                val_in_k_m = val / 1000.0

            # 熔断检查：若出现 > 1 K/m (即 1000 K/km)，在地球大气物理中必错
            if val_in_k_m > 1.0:
                return {'result': 'fail', 'message': '温减率数值量级严重错误，超过物理常识上限(1 K/m)', 'evidence': f'{val_str} {unit}'}

            # 正常范围检查：0.005-0.01 K/m (5-10 K/km)
            # 考虑到题目可能有特殊假设，仅对极端偏离(如 > 0.02 K/m)进行保守判定
            if val_in_k_m > 0.02:
                return {'result': 'fail', 'message': '计算结果偏离标准大气温减率量级(约0.0065 K/m)过大', 'evidence': f'{val_str} {unit}'}

        except ValueError:
            continue

    # Step 3: 符号覆盖检查 (dT, dy/dz)
    if 'dt' in prediction.lower() and ('dy' in prediction.lower() or 'dz' in prediction.lower()):
        return {'result': 'pass', 'message': '数值量级在合理范围内且包含必要物理符号', 'evidence': str(matches[0])}

    return {'result': 'inconclusive', 'message': '数值存在但缺乏完整推理证据', 'evidence': str(matches[:2])}

# rule_id=norm_aea48de3e5969366 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_aea48de3e5969366 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_aea48de3e5969366_8b83c2646848(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多个腔室、隔板（活塞）及体积变化
    trigger_keywords = ['腔室', '隔板', '活塞', 'chamber', 'piston', 'partition']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and ('体积' in combined_text or 'volume' in combined_text)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到多腔室联动或体积改变场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否错误地对所有腔室直接套用绝热过程方程 pV^γ=const
    # 如果 prediction 中出现了类似 pV^gamma 的形式，但没有讨论受力平衡，则存在误用风险
    pred_lower = prediction.lower()
    has_adiabatic_eq = re.search(r'p.*v.*[\^\*\*].*[\gamma|1\.4|5/3]', pred_lower) or 'pv^' in pred_lower

    # 检查是否包含受力平衡方程 P*A + mg = P*A 的变体
    # 匹配模式：压力*面积 + 重力 = 压力*面积 (或类似 P1*S + mg = P2*S)
    force_balance_pattern = r'p.*[as].*\+.*mg.*=.*p.*[as]|p.*[as].*=.*p.*[as].*\+.*mg'
    has_force_balance = re.search(force_balance_pattern, pred_lower) or ('mg' in pred_lower and 'p' in pred_lower and '=' in pred_lower)

    # Step 3: 综合判定
    # 如果使用了绝热方程但完全没有提到受力平衡（mg, P*S等），判定为逻辑缺失
    if has_adiabatic_eq and not has_force_balance:
        return {
            'result': 'fail',
            'message': '在多腔室联动中直接套用绝热方程，未结合隔板受力平衡方程(P*A + mg = P*A)确定压力关系',
            'evidence': prediction[:200]
        }

    # 如果明确写出了受力平衡关系，则认为通过了该项逻辑检查
    if has_force_balance:
        return {
            'result': 'pass',
            'message': '已考虑隔板受力平衡关系',
            'evidence': re.search(force_balance_pattern, pred_lower).group() if re.search(force_balance_pattern, pred_lower) else 'mg balance found'
        }

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了腔室间的压力联动关系', 'evidence': ''}

# rule_id=norm_bb4b03106fbc5ce0 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_bb4b03106fbc5ce0 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_bb4b03106fbc5ce0_d65cc598b4a3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及绝热过程及 P-R 或 T-R 的幂函数关系
    # 关键词：绝热 (adiabatic), 绝热指数 (gamma), 尺度因子/半径 (R), 温度 (T), 压强 (P)
    trigger_keywords = ['绝热', 'adiabatic', 'gamma', 'γ']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords) or 'r' not in combined_text:
        return {'result': 'inconclusive', 'message': '未检测到绝热过程或尺度因子R的相关描述', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证 P ∝ R^(-3γ) 或 T ∝ R^(-3(γ-1)) 的指数计算
    # 重点检查 prediction 中是否出现了错误的幂次关系，特别是 gamma 的系数
    pred = prediction.lower()

    # 检查 T 与 R 的关系：T ∝ R^(-3(gamma-1))
    t_r_pattern = r't\s*\(?r\)?\s*(?:\propto|\sim|=|\s)\s*r\^?\s*\{?(-?3\s*\(?\s*gamma\s*-\s*1\s*\)?|\s*-3\s*\gamma\s*\+\s*3)\}?'
    # 检查 P 与 R 的关系：P ∝ R^(-3gamma)
    p_r_pattern = r'p\s*\(?r\)?\s*(?:\propto|\sim|=|\s)\s*r\^?\s*\{?(-?3\s*gamma)\}?'

    has_t_relation = re.search(t_r_pattern, pred)
    has_p_relation = re.search(p_r_pattern, pred)

    # 如果 prediction 中提到了 T 和 R 的关系，但指数不符合 -3(gamma-1)
    if 't' in pred and 'r' in pred:
        wrong_t_exp = re.search(r't\s*\propto\s*r\^?\s*\{?(-?\s*\gamma\s*-\s*1)\}?', pred) # 漏了系数3
        if wrong_t_exp:
            return {'result': 'fail', 'message': 'T与R的幂次关系缺失系数3，应为-3(gamma-1)', 'evidence': wrong_t_exp.group(0)}

    # Step 3: 符号一致性校验
    if has_t_relation or has_p_relation:
        return {'result': 'pass', 'message': '绝热过程指数幂次计算符合物理规律', 'evidence': (has_t_relation.group(0) if has_t_relation else has_p_relation.group(0))}

    # 如果有推导过程但没匹配到标准形式，且存在明显的 gamma 运算错误
    if 'gamma' in pred and ('3' not in pred and 'r' in pred):
        return {'result': 'fail', 'message': '在绝热推导中未发现正确的尺度因子幂次项(3gamma)', 'evidence': pred[:200]}

    return {'result': 'inconclusive', 'message': '未能明确识别幂次计算过程', 'evidence': ''}

# rule_id=norm_bef5cf977f8e2f8a | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_bef5cf977f8e2f8a | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_bef5cf977f8e2f8a_48255505d788(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否包含描述剧烈、快速充气或大孔流动的词汇
    trigger_keywords = ['filled fast', 'large hole', 'flow rate is so large', 'rapidly filled', 'suddenly opened', 'fast flow']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到描述剧烈/快速充气过程的关键词', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否错误使用了绝热准静态方程 P*V^gamma = C
    # 剧烈过程不满足准静态条件，不应直接使用泊松公式
    pred_lower = prediction.lower()
    if re.search(r'p.*v\^\\?gamma', pred_lower) or re.search(r't.*v\^\\?\(gamma-1\)', pred_lower):
        return {
            'result': 'fail',
            'message': '在剧烈/快速充气过程中错误套用了绝热准静态方程 (P*V^gamma=C)',
            'evidence': re.findall(r'p.*v\^\\?gamma|t.*v\^\\?\(gamma-1\)', pred_lower)[0]
        }

    # Step 3: 符号/公式校验 — 检查是否使用了能量守恒方程 Delta U = W_ext
    # 预期形式: nCv(T2-T1) = P_ext(V1-V2) 或类似的能量平衡表达
    energy_patterns = [
        r'c_v.*t_2.*t_1',
        r'p_.*v_.*v_',
        r'\\delta u.*w',
        r'u_2.*u_1.*w'
    ]

    found_energy_logic = any(re.search(pat, pred_lower) for pat in energy_patterns)

    if found_energy_logic:
        return {'result': 'pass', 'message': '正确识别非准静态过程并尝试使用能量守恒建模', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '未发现明确的建模逻辑冲突或符合项', 'evidence': ''}

# rule_id=norm_cec0b109cb481e56 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_cec0b109cb481e56 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_cec0b109cb481e56_233e63c72fc2(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及循环回到初始态或阀门打开的情境
    trigger_keywords = ['回到初始', '恢复到', '阀门打开', 'open the valve', 'return to initial', 'back to state 1']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到循环节点或阀门开启场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 区分状态点 4 与回复过程 4->1，检查是否错误地认为状态 4 压力已等于 P1
    # 规则要求：状态 4 是膨胀结束瞬时态，P4 > P1，V4 = V1
    pred = prediction.lower()

    # 寻找关于状态 4 的描述，特别是压力和体积的关系
    has_state_4 = re.search(r'[Pp]_?4|[Ss]tate\s*4|状态\s*4', pred)
    if not has_state_4:
        return {'result': 'inconclusive', 'message': '预测中未明确提及状态点 4', 'evidence': ''}

    # 检查是否错误地将 P4 直接等同于 P1 (大气压/初始压)
    # 错误模式：P4 = P1 或 P4 = P_atm (在膨胀结束瞬间)
    error_pattern = re.search(r'[Pp]_?4\s*=\s*[Pp]_?1|[Pp]_?4\s*=\s*[Pp]_?a', pred)
    if error_pattern:
        return {
            'result': 'fail',
            'message': '错误地将膨胀结束瞬时态(State 4)的压力等同于初始压力，未区分状态点与回复过程',
            'evidence': error_pattern.group(0)
        }

    # Step 3: 符号/公式校验 — 检查是否体现了 P4 > P1 或 V4 = V1 的逻辑
    correct_logic = re.search(r'[Vv]_?4\s*=\s*[Vv]_?1', pred) and ('>' in pred or 'higher' in pred)
    if correct_logic:
        return {
            'result': 'pass',
            'message': '正确区分了状态点4与初始状态，并识别了体积相等或压力差异',
            'evidence': '检测到 V4=V1 或压力比较逻辑'
        }

    return {'result': 'inconclusive', 'message': '无法确定是否正确区分了状态点与回复过程', 'evidence': ''}

# rule_id=norm_d0a2ee778e95335e | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_d0a2ee778e95335e | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_d0a2ee778e95335e_d72a5aca35ac(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否为涉及外力、缓慢移动的绝热过程
    q_c = (question + context).lower()
    trigger_keywords = ['external force', 'very slowly', 'adiabatic', 'change distance', 'piston']
    if not all(re.search(k, q_c) for k in ['adiabatic']):
        return {'result': 'inconclusive', 'message': '未检测到绝热过程关键词', 'evidence': ''}
    if not any(re.search(k, q_c) for k in ['external force', 'very slowly', 'slowly', 'pull', 'push']):
        return {'result': 'inconclusive', 'message': '未检测到主动外力或缓慢移动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否存在非自由绝热过程（有外力做功）
    # 如果存在外力做功，直接使用 PV^gamma = C 往往是错误的（除非外力被包含在等效压力中）
    pred = prediction.lower()
    has_external_work_mention = any(x in pred for x in ['work done by external', 'external work', 'dw_ext', 'f * dx', 'f dx'])
    uses_adiabatic_law = re.search(r'p[vV]\^?(\\gamma|gamma|1\.4)', pred)

    # Step 3: 符号与公式校验 — 检查是否回归热力学第一定律 dU = dW + dQ (dQ=0)
    # 重点检查是否考虑了 dU = dW_gas + dW_external 或类似的能量守恒表达
    has_first_law = any(re.search(p, prediction) for p in [r'dU\s*=\s*dW', r'\Delta U\s*=\s*W', r'Q\s*=\s*0'])

    if uses_adiabatic_law and not has_external_work_mention:
        # 如果只用了绝热方程而忽略了外力功的独立项，可能存在建模错误
        return {'result': 'fail', 'message': '在有主动外力做功的绝热过程中，直接套用PV^gamma公式而未显式分析外力功可能导致错误', 'evidence': prediction[:200]}

    if has_first_law and (has_external_work_mention or 'dU' in prediction):
        return {'result': 'pass', 'message': '正确识别了非自由绝热过程中的能量转化关系', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定推理是否正确处理了外力功', 'evidence': ''}

# rule_id=norm_e31b9e3963a4e653 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_e31b9e3963a4e653 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_e31b9e3963a4e653_c196d039fef2(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题干是否涉及热力学过程且存在隐含参数（如未直接给出初值）
    # 关键词：热力学过程（等温/绝热/循环）、参数缺失（未给出、求、未知）
    thermo_keywords = ['等温', '绝热', '等压', '等容', '循环', 'isothermal', 'adiabatic', 'isobaric', 'isochoric']
    missing_keywords = ['未给出', '未告知', '未知', '假设', '设为', 'let', 'assume']

    is_thermo = any(kw in (question + context) for kw in thermo_keywords)
    has_missing_hint = any(kw in (question + context) for kw in missing_keywords) or re.search(r'[P|V|T|n|R]\d?\s*=\s*\?', question)

    if not (is_thermo and has_missing_hint):
        return {'result': 'inconclusive', 'message': '题干未明确体现参数缺失或非热力学过程场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否存在“自行假设具体数值”的违规行为
    # 排除物理常数（如 R=8.31, g=9.8）后的具体数值假设
    # 匹配模式：假设 P=1, V=1, T=300 等具体数字赋值
    illegal_assumption = re.search(r'(?:假设|令|设|let|assume)\s*[P|V|T|n]\s*=\s*\d+(\.\d+)?(?!\s*[k|K|J|R|g])', prediction)

    # Step 3: 检查逻辑 — 检查是否尝试从前序状态推导（如从状态1推导状态2）
    # 关键词：末态、初态、由过程A、根据前一阶段
    derivation_keywords = ['前一', '末态', '初态', '推导', '关系', 'state', 'previous', 'final', 'initial']
    has_derivation = any(kw in prediction for kw in derivation_keywords) or re.search(r'[P|V|T]1.*[P|V|T]2', prediction)

    if illegal_assumption and not has_derivation:
        return {
            'result': 'fail',
            'message': '检测到在缺失参数时自行假设了具体数值，而非通过前序过程推导。',
            'evidence': illegal_assumption.group(0)
        }

    if has_derivation:
        return {
            'result': 'pass',
            'message': '推理中包含状态推导逻辑，符合处理规范。',
            'evidence': '检测到状态关联推导'
        }

    return {'result': 'inconclusive', 'message': '无法确定参数处理是否合规', 'evidence': ''}

# rule_id=norm_e46b8ee3800fa2e3 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_e46b8ee3800fa2e3 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_e46b8ee3800fa2e3_db1530cd519b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及隔板/活塞支撑在台阶/垫圈上的单向约束场景
    trigger_keywords = ['隔板', '活塞', 'diaphragm', 'piston', 'ledge', 'gasket', '台阶', '垫圈', '卡口']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到单向约束（台阶/隔板）场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否分析了压力差（合力）与约束方向的关系
    pred = prediction.lower()
    # 检查是否提到了压力差、受力分析或合力方向
    force_analysis = ['压力差', '合力', 'net force', 'pressure difference', 'p_lower', 'p_upper', 'mg', '重力']
    if not any(fa in pred for fa in force_analysis):
        return {'result': 'fail', 'message': '未对隔板进行受力分析或压力差判定', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查是否包含位移为0的判定逻辑（当合力指向台阶时）
    # 逻辑：如果 (P_lower - P_upper) * A <= m*g (假设向上为正，台阶在上方限制)，则位移为0
    # 或者简单检查是否提到了“不动”、“位移为0”、“体积不变”等结论与压力条件的关联
    movement_check = ['不动', '不变', 'zero displacement', 'remains', 'fixed', 'delta v = 0', '位移为0']
    if any(mc in pred for mc in movement_check):
        # 如果提到了不动，检查是否伴随压力比较逻辑
        if re.search(r'[Pp].*[<>].*[Pp]', pred) or '压力' in pred:
            return {'result': 'pass', 'message': '正确执行了单向约束下的力学平衡判定', 'evidence': prediction[:200]}

    # 如果预测中直接忽略了台阶的约束力，直接计算平衡，则可能存在建模错误
    if 'p1 = p2' in pred.replace(' ', '') and not any(mc in pred for mc in movement_check):
         return {'result': 'fail', 'message': '可能忽略了台阶约束，直接假设了压力相等', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了单向约束逻辑', 'evidence': ''}

# rule_id=norm_e842b537f6ffa96d | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_e842b537f6ffa96d | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_e842b537f6ffa96d_5a459d2f10e3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及气体弹簧等效系数计算
    trigger_keywords = ['spring constant', 'equivalent spring', '弹簧常数', '等效弹簧', 'stiffness', '刚度']
    gas_keywords = ['gas', 'piston', 'cylinder', '气体', '活塞', '气缸']
    text_to_check = (question + context).lower()
    if not (any(k in text_to_check for k in trigger_keywords) and any(k in text_to_check for k in gas_keywords)):
        return {'result': 'inconclusive', 'message': '未检测到气体弹簧等效系数建模场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别过程类型（等温或绝热）并校验公式结构
    pred = prediction.lower()
    # 检查是否包含核心物理量 A, P, V
    if not all(re.search(rf'\b{s}\b', pred, re.IGNORECASE) for s in ['a', 'p', 'v']):
        return {'result': 'fail', 'message': '预测中缺失关键物理量符号 (A, P, V)', 'evidence': prediction[:200]}

    # 检查等温过程公式: k = (P/V) * A^2
    isothermal_pattern = r'k\s*=\s*\(?p/v\)?\s*\*?\s*a\s*\^?\s*2'
    # 检查绝热过程公式: k = (gamma * P / V) * A^2
    adiabatic_pattern = r'k\s*=\s*\(?gamma\s*\*?\s*p/v\)?\s*\*?\s*a\s*\^?\s*2'

    is_isothermal = 'isothermal' in text_to_check or '等温' in text_to_check
    is_adiabatic = 'adiabatic' in text_to_check or '绝热' in text_to_check or 'gamma' in pred

    if is_isothermal:
        if re.search(isothermal_pattern, pred.replace(' ', '')):
            return {'result': 'pass', 'message': '等温过程气体弹簧系数公式正确', 'evidence': prediction[:200]}
        else:
            return {'result': 'fail', 'message': '等温过程公式应为 k = (P/V)A^2', 'evidence': prediction[:200]}

    if is_adiabatic:
        if re.search(adiabatic_pattern, pred.replace(' ', '')) or 'gamma' in pred:
            if re.search(r'gamma', pred):
                return {'result': 'pass', 'message': '绝热过程气体弹簧系数建模包含比热比', 'evidence': prediction[:200]}
            return {'result': 'fail', 'message': '绝热过程公式缺失 gamma 参数', 'evidence': prediction[:200]}

    # Step 3: 通用导数形式检查 k = |dP/dV| * A^2
    if re.search(r'dp/dv', pred) and 'a' in pred:
        return {'result': 'pass', 'message': '检测到基于导数定义的等效系数建模', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定建模公式是否准确', 'evidence': ''}

# rule_id=norm_ebe0b0cdd0f71639 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_ebe0b0cdd0f71639 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_ebe0b0cdd0f71639_94f0b687c315(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 涉及玻璃管倒置、部分装水/液柱且有封闭气体的平衡问题
    trigger_keywords = ['玻璃管', '倒置', '封闭气体', '水银柱', '液柱', '开口向下']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到玻璃管倒置或封闭气体平衡场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证几何关系 L = H + h (或类似长度守恒/组成关系)
    # 检查 prediction 是否包含长度 L, H, h 的几何关联
    pred_text = prediction.replace(' ', '')
    # 匹配 L = H + h 或 H = L - h 等变体
    length_pattern = r'([LHh])=([LHh])\+([LHh])|([LHh])=([LHh])-([LHh])'
    has_geometry = re.search(length_pattern, pred_text)

    # Step 3: 检查压强平衡方程 P_atm = P_gas + ρgh (或 P_gas = P_0 - h)
    # 针对倒置情况，管内压强平衡通常为 P_gas = P_0 - h (h为液柱高度)
    pressure_pattern = r'P(_?gas)?=P(_?0|atm)-(h|ρgh)'
    has_pressure = re.search(pressure_pattern, pred_text, re.IGNORECASE)

    if not has_geometry and 'L' in (question + context):
        # 如果题目明确给出了总长L等符号，但推理中没有建立几何等式，视为逻辑缺失
        return {'result': 'fail', 'message': '未建立封闭气体与液柱的几何长度约束关系', 'evidence': prediction[:200]}

    if has_geometry and has_pressure:
        return {'result': 'pass', 'message': '已验证几何约束与压强平衡方程', 'evidence': re.search(length_pattern, pred_text).group()}

    return {'result': 'inconclusive', 'message': '推理过程中几何或压强平衡关系不完整', 'evidence': prediction[:100]}

# rule_id=norm_edb808918c63c379 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
# rule_id=norm_edb808918c63c379 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_norm_edb808918c63c379_99ae5d478d6e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及密度、压强、声速求解体积或质量
    trigger_keywords = ['密度', '压强', '声速', '音速', '体积', '质量', 'density', 'pressure', 'sound speed', 'volume', 'mass']
    combined_text = (question + context).lower()
    match_count = sum(1 for word in trigger_keywords if word in combined_text)
    if match_count < 3:
        return {'result': 'inconclusive', 'message': '未检测到足够的热力学状态量关联场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否利用声速公式 v = sqrt(gamma * P / rho)
    # 匹配声速公式的变体，考虑 LaTeX 和纯文本形式
    speed_of_sound_patterns = [
        r'v_s\s*=\s*\\sqrt{\\frac{\\gamma\s*P}{\\rho}}',
        r'v\s*=\s*sqrt\(gamma\s*\*\s*P\s*/\s*rho\)',
        r'v\^2\s*=\s*\\gamma\s*P\s*/\s*\\rho',
        r'\\gamma\s*P\s*/\s*\\rho'
    ]

    pred_text = prediction.replace(' ', '')
    formula_found = False
    for pattern in speed_of_sound_patterns:
        if re.search(pattern.replace(' ', ''), pred_text, re.IGNORECASE):
            formula_found = True
            break

    if not formula_found:
        # 进一步检查是否包含关键符号组合
        required_symbols = ['P', 'gamma', 'rho', 'v']
        symbol_hits = [s for s in required_symbols if s in prediction or s in f'\\{s}']
        if len(symbol_hits) < 3:
            return {'result': 'fail', 'message': '推理过程中缺失声速与状态参量(P, rho, gamma)的关联公式', 'evidence': prediction[:200]}

    # Step 3: 检查是否结合几何尺寸或基准体积 V
    volume_keywords = ['体积', 'V', 'volume', 'L^3', 'area', 'length']
    if not any(word in prediction for word in volume_keywords):
        return {'result': 'fail', 'message': '未发现结合几何尺寸确定基准体积的步骤', 'evidence': prediction[-150:]}

    # Step 4: 综合判定
    if formula_found:
        return {'result': 'pass', 'message': '成功校验声速公式及状态参数关联', 'evidence': '检测到声速公式及体积相关描述'}

    return {'result': 'inconclusive', 'message': '逻辑要素基本具备但公式表达不规范', 'evidence': ''}

# rule_id=norm_0f564f7195dc4f90 | domain=Thermodynamics & Statistical Physics | topic=Second Law and Entropy
# rule_id=norm_0f564f7195dc4f90 | domain=Thermodynamics & Statistical Physics | topic=Second Law and Entropy
def check_norm_0f564f7195dc4f90_7fa1473faccb(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及理想气体熵变计算及准静态/线性过程
    trigger_keywords = ['理想气体', '熵变', 'entropy change', 'delta s', '\\Delta S']
    process_keywords = ['准静态', '线性', 'P-V', '过程', 'process']

    q_c = (question + context).lower()
    if not (any(k in q_c for k in trigger_keywords) and any(k in q_c for k in process_keywords)):
        return {'result': 'inconclusive', 'message': '未检测到理想气体熵变计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否使用了状态函数法（T, V, P 参量）而非路径积分 (dQ/T)
    pred = prediction.lower()
    # 状态函数公式特征：ln(T2/T1), ln(V2/V1), ln(P2/P1)
    state_func_patterns = [
        r'ln\(t_?2/t_?1\)', r'ln\(v_?2/v_?1\)', r'ln\(p_?2/p_?1\)',
        r'\\ln\s*\\?\(.*?/.*?\\?\)', r'nrv?ln'
    ]
    # 路径积分特征：积分符号 + dQ/T 或 dQ/dT
    integral_path_patterns = [
        r'\\int.*?dq/t', r'\\int.*?\\frac{dq}{t}', r'积分.*?dq/t'
    ]

    has_state_func = any(re.search(p, pred) for p in state_func_patterns)
    has_integral_path = any(re.search(p, pred) for p in integral_path_patterns)

    # Step 3: 判定结果
    # 如果使用了状态函数公式，则符合规则
    if has_state_func:
        return {'result': 'pass', 'message': '使用了理想气体状态函数法计算熵变', 'evidence': re.search(r'.{0,50}ln\(.*?\).{0,50}', pred).group(0) if has_state_func else ''}

    # 如果明显在进行复杂的路径积分而没有提到状态函数公式，则视为逻辑风险（不推荐）
    if has_integral_path and not has_state_func:
        return {'result': 'fail', 'message': '优先推荐使用状态函数法而非路径积分计算熵变', 'evidence': '检测到路径积分表达式但缺失状态函数公式'}

    return {'result': 'inconclusive', 'message': '无法确定是否使用了状态函数法', 'evidence': ''}

# rule_id=norm_3c7004a99f51d1e8 | domain=Thermodynamics & Statistical Physics | topic=Second Law and Entropy
# rule_id=norm_3c7004a99f51d1e8 | domain=Thermodynamics & Statistical Physics | topic=Second Law and Entropy
def check_norm_3c7004a99f51d1e8_4f5a3f00f1c7(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及 P-V 图及状态函数（熵、内能）变化量计算
    trigger_keywords = ['P-V', 'PV图', '压强-体积', '熵', '内能', 'entropy', 'internal energy', '变化量', 'delta']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到P-V图或状态函数变化量计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否从图中提取了具体的始末状态坐标（如 P0, V0, P1, V1 等）
    # 规则要求代入端点值而非保留抽象符号
    required_symbols = ['P_0', 'V_0', 'P_1', 'V_1', 'P_2', 'V_2', 'T_1', 'T_2']
    # 检查 prediction 中是否出现了具体的坐标符号或数值代入过程
    found_coords = [sym for sym in required_symbols if sym in prediction or sym.replace('_', '') in prediction]

    # 如果 prediction 中完全没有出现坐标提取或代入的迹象，且最终结果仅为抽象公式，则判定为 fail
    if len(found_coords) < 2:
        # 进一步检查是否直接给出了数值但没写符号，若连数值代入的特征（如数字乘积）也没有则 fail
        if not re.search(r'\d+\s*[\*\/\+]\s*\d+', prediction):
            return {
                'result': 'fail',
                'message': '未在计算过程中提取并代入始末状态的具体坐标值（P, V, T），仅保留了抽象符号。',
                'evidence': prediction[:200]
            }

    # Step 3: 公式结构校验 — 检查是否包含熵变或内能变化的典型对数/线性结构
    # 匹配类似 ln(T2/T1), ln(V2/V1) 或 nCv(T2-T1) 的结构
    formula_patterns = [
        r'ln\(.*[\/\/].*\)',
        r'log\(.*[\/\/].*\)',
        r'C_v.*\(',
        r'C_p.*\(',
        r'\Delta S',
        r'\Delta U'
    ]
    has_formula = any(re.search(p, prediction, re.IGNORECASE) for p in formula_patterns)

    if has_formula and len(found_coords) >= 2:
        return {
            'result': 'pass',
            'message': '已检测到状态函数计算公式及对应的端点坐标代入。',
            'evidence': f'检测到坐标: {found_coords}'
        }

    return {'result': 'inconclusive', 'message': '无法确定是否完整代入了端点值，建议人工核对。', 'evidence': prediction[:150]}

# rule_id=norm_4ea42073c0236d36 | domain=Thermodynamics & Statistical Physics | topic=Second Law and Entropy
# rule_id=norm_4ea42073c0236d36 | domain=Thermodynamics & Statistical Physics | topic=Second Law and Entropy
def check_norm_4ea42073c0236d36_6114e84ba3a3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及非理想气体（如范德华气体）的自由膨胀或等温过程熵变
    trigger_keywords = ['非理想气体', '范德华', 'van der Waals', 'state equation', '状态方程']
    process_keywords = ['自由膨胀', 'free expansion', '等温', 'isothermal', 'entropy change', '熵变']

    combined_text = (question + context).lower()
    is_non_ideal = any(k in combined_text for k in trigger_keywords)
    is_relevant_process = any(k in combined_text for k in process_keywords)

    if not (is_non_ideal and is_relevant_process):
        return {'result': 'inconclusive', 'message': '未检测到非理想气体熵变计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 严禁直接套用理想气体 ΔU=0 或 ΔS=nRln(V2/V1) 的结论
    pred = prediction.lower()
    # 如果直接宣称内能不变且没有基于状态方程推导，或者直接套用理想气体公式，则视为逻辑错误
    if 'delta u = 0' in pred or 'du=0' in pred or 'du = 0' in pred:
        # 检查是否缺乏对 (dU/dV)_T 的考虑
        if 'partial u' not in pred and 'cv' not in pred and 'internal energy' in pred:
            return {'result': 'fail', 'message': '错误地直接套用了理想气体内能不变的结论', 'evidence': prediction[:200]}

    # Step 3: 检查是否使用了正确的积分公式或麦克斯韦关系
    # 匹配 (dP/dT)_V 或相关的热力学基本方程
    maxwell_pattern = r'partial\s*p.*partial\s*t.*v|ds\s*=\s*.*dv|int.*p/t.*dv'
    has_correct_relation = re.search(maxwell_pattern, pred, re.IGNORECASE) is not null

    # 检查 symbolic_hint 中的关键公式结构
    formula_pattern = r'\\Delta\s*S\s*=\s*\\int.*\\frac{.*P}{.*T}.*dV'
    has_formula = re.search(formula_pattern, prediction) is not None

    if has_correct_relation or has_formula:
        return {'result': 'pass', 'message': '使用了正确的热力学关系式进行熵变计算', 'evidence': prediction[:200]}

    # 如果既没有正确公式又表现出逻辑简化倾向
    if 'nr' in pred and 'ln' in pred and 'v_2/v_1' in pred:
         return {'result': 'fail', 'message': '疑似直接套用理想气体熵变公式，未考虑非理想项', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定计算逻辑是否严谨', 'evidence': ''}

# rule_id=norm_a568ae7c434ab5de | domain=Thermodynamics & Statistical Physics | topic=Second Law and Entropy
# rule_id=norm_a568ae7c434ab5de | domain=Thermodynamics & Statistical Physics | topic=Second Law and Entropy
def check_norm_a568ae7c434ab5de_4850629ff565(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否要求一阶近似 (first order) 以及是否存在微扰项 (如 a', epsilon, delta)
    trigger_keywords = ['first order', '一阶', '近似', 'approximation']
    perturbation_terms = ["a'", "\\epsilon", "\\delta", "a/V", "a'/V"]

    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords)
    has_perturbation = any(pt in (question + context) for pt in perturbation_terms)

    if not (is_triggered and has_perturbation):
        return {'result': 'inconclusive', 'message': '未检测到一阶近似或微扰项要求', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别微扰项在求导或积分前后的系数一致性
    # 重点检查如 P = (NkT/V)(1 + a'/V) 求导时，a'/V 的系数是否因为算子操作（如对T求导）被错误改变或丢失
    # 搜索 prediction 中涉及微扰项的表达式变化
    pred_clean = prediction.replace(' ', '')

    # 匹配模式：寻找类似 (1 + a'/V) 或 (1 + epsilon) 的结构
    pattern_term = r'\(1[\+\-]((?:[a-zA-Z\']+/?[a-zA-Z]*)|\\?[a-z]+)\)'
    matches = re.findall(pattern_term, prediction)

    if not matches:
        # 如果没有显式的一阶修正项结构，检查是否在最终结果中丢失了修正项
        if not any(pt in prediction for pt in perturbation_terms):
            return {'result': 'fail', 'message': '推理过程中丢失了一阶修正项或微扰项', 'evidence': prediction[-200:]}
        return {'result': 'inconclusive', 'message': '无法提取明确的一阶项系数结构', 'evidence': ''}

    # Step 3: 符号一致性校验 — 检查求导/代换后系数是否发生非预期的跳变
    # 例如：如果对 T 求导，(1 + a'/V) 应该保持不变（若 a' 与 T 无关）
    # 如果发现 a'/V 变成了 2a'/V 或 a'/V^2 而无物理解释，则判定为计算错误
    if 'partial' in prediction or 'd/' in prediction or '微分' in prediction:
        # 简单检查：如果修正项在等号两边系数不一致且无算子作用理由
        # 此处逻辑较为保守，仅在发现明显系数丢失时报错
        if len(set(matches)) > 1 and not any(op in prediction for op in ['2', '1/2', 'exp']):
             # 允许合理的物理系数变化，但若完全消失则报错
             pass

    # 检查 canonical 形式：P = (NkT/V)(1 + a'/V) -> dP/dT = (Nk/V)(1 + a'/V)
    if "a'" in (question + context) and "a'" in prediction:
        # 检查是否在求导后 a' 依然存在
        if 'derivative' in combined_text or 'partial' in combined_text:
            if "a'" not in prediction.split('=')[-1]:
                return {'result': 'fail', 'message': '一阶近似项在求导或代换后丢失', 'evidence': prediction[-150:]}

    return {'result': 'pass', 'message': '一阶近似项系数处理逻辑基本一致', 'evidence': str(matches)}

# rule_id=norm_708144492b9c33a6 | domain=Thermodynamics & Statistical Physics | topic=Carnot Cycle and Efficiency
# rule_id=norm_708144492b9c33a6 | domain=Thermodynamics & Statistical Physics | topic=Carnot Cycle and Efficiency
def check_norm_708144492b9c33a6_d21f6de254ef(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两个有限热容物体（热源）的卡诺循环/最大功问题
    trigger_keywords = ['热容', 'heat capacity', 'finite', '有限', '最大功', 'maximum work', 'final temperature', '末温']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords) or 'carnot' not in combined_text:
        return {'result': 'inconclusive', 'message': '未检测到涉及有限热容热源的卡诺循环场景', 'evidence': ''}

    # Step 2: 检查逻辑要素 — 是否利用全过程可逆性（熵增为零）确定末温
    pred = prediction.lower()
    entropy_keywords = ['entropy', 'reversible', 'ds = 0', '熵', '可逆', 'ln', 'log']
    if not any(kw in pred for kw in entropy_keywords):
        return {'result': 'fail', 'message': '推理过程中未体现熵增为零或可逆性分析', 'evidence': prediction[:200]}

    # Step 3: 检查逻辑要素 — 是否利用能量守恒（功等于内能改变量）
    energy_keywords = ['energy conservation', 'internal energy', 'w =', 'work =', '能量守恒', '内能']
    if not any(kw in pred for kw in energy_keywords):
        return {'result': 'fail', 'message': '推理过程中未体现能量守恒或功与内能改变量的关系', 'evidence': prediction[:200]}

    # Step 4: 符号/公式校验 — 检查特征末温 sqrt(T1*T2) 或功的表达式
    # 典型末温 Tf = sqrt(T1 * T2)
    tf_pattern = r'sqrt\(\s*T_?1\s*\*?\s*T_?2\s*\)'
    # 典型功 W = C(T1 + T2 - 2*sqrt(T1*T2))
    work_pattern = r'T_?1\s*\+\s*T_?2\s*-\s*2\s*\*?\s*sqrt'

    if re.search(tf_pattern, prediction) or re.search(work_pattern, prediction):
        return {'result': 'pass', 'message': '逻辑完整且包含正确的物理公式结构', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑步骤存在但公式匹配不明确', 'evidence': prediction[:200]}

# rule_id=norm_8d83b09d355edb7d | domain=Thermodynamics & Statistical Physics | topic=Carnot Cycle and Efficiency
# rule_id=norm_8d83b09d355edb7d | domain=Thermodynamics & Statistical Physics | topic=Carnot Cycle and Efficiency
def check_norm_8d83b09d355edb7d_5b2e29aa6a80(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及有限热源间的热机功计算
    trigger_keywords = ['热机', '功', '有限热源', 'heat engine', 'work', 'finite heat source']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到热机功计算相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否应用了能量守恒 (W = ΔU) 且考虑了温度变化
    # 重点检查是否包含类似 W = C(T1+T2-2Tf) 或 W = Q1 - Q2 的逻辑
    pred = prediction.lower()
    # 检查是否提到内能变化或温度差的累加
    energy_conservation_patterns = [
        r'w\s*=\s*.*c.*t',
        r'内能.*减少',
        r'energy.*conservation',
        r't_1\s*\+\s*t_2\s*-\s*2t_f'
    ]

    has_logic = any(re.search(p, pred) for p in energy_conservation_patterns)

    # Step 3: 符号与公式校验 — 检查 symbolic_hint 中的关键符号和结构
    # 检查是否漏掉冷端（即是否只算了吸热而没算放热，或者公式结构是否完整）
    required_symbols = ['C', 'T_f', 'W']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    if not has_logic and len(missing_symbols) > 1:
        return {
            'result': 'fail',
            'message': '预测中未体现功等于系统总内能减少量的逻辑，或缺少关键物理量计算',
            'evidence': prediction[:200]
        }

    # 检查公式 canonical: W = C(T_1 + T_2 - 2T_f) 的变体
    if re.search(r'W\s*=\s*C\s*\(?T_?1\s*\+\s*T_?2\s*-\s*2\s*T_?f\)?', prediction):
        return {'result': 'pass', 'message': '检测到符合能量守恒的热机功计算公式', 'evidence': re.search(r'W\s*=\s*C\s*\(?T_?1\s*\+\s*T_?2\s*-\s*2\s*T_?f\)?', prediction).group()}

    if 'W' in prediction and ('T_1' in prediction or 'T1' in prediction) and 'T_f' in prediction:
        return {'result': 'pass', 'message': '包含必要的物理量和功的计算步骤', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '逻辑步骤不完整，无法确定是否违反能量守恒约束', 'evidence': ''}

# rule_id=norm_a2100811f6f6f4d0 | domain=Thermodynamics & Statistical Physics | topic=Carnot Cycle and Efficiency
# rule_id=norm_a2100811f6f6f4d0 | domain=Thermodynamics & Statistical Physics | topic=Carnot Cycle and Efficiency
def check_norm_a2100811f6f6f4d0_bd418e32c1b8(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两个有限热容量物体通过热机达到平衡的场景
    trigger_keywords = ['有限热容', 'heat capacity', 'finite source', 'heat reservoir', 'thermal equilibrium']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords) or 'carnot' not in combined_text:
        return {'result': 'inconclusive', 'message': '未检测到有限热源卡诺循环场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 校验是否提到熵变为零 (ΔS=0) 或可逆过程
    pred = prediction.lower()
    entropy_keywords = ['entropy', '熵', 'reversible', '可逆', 'delta s', 'ds = 0']
    if not any(kw in pred for kw in entropy_keywords):
        return {'result': 'fail', 'message': '未提及可逆循环的熵变守恒条件', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查终温是否为几何平均值 T_f = sqrt(T1 * T2)
    # 匹配 T_f = sqrt(T1*T2) 或类似的几何平均表达
    geometric_mean_pattern = r'(T_?f|T_?final|终温).*=.*(sqrt|\\sqrt|\^0\.5|\^\{1/2\}).*(T_?1.*T_?2|T_?2.*T_?1)'
    if re.search(geometric_mean_pattern, prediction, re.IGNORECASE) or re.search(r'T_?f\s*=\s*\\sqrt\{T_1\s*T_2\}', prediction):
        return {'result': 'pass', 'message': '正确推导出终温为几何平均值', 'evidence': prediction[-200:]}

    # 如果提到算术平均 (T1+T2)/2 则明确错误
    arithmetic_mean_pattern = r'\(T_?1\s*\+\s*T_?2\)/2'
    if re.search(arithmetic_mean_pattern, prediction):
        return {'result': 'fail', 'message': '错误地使用了算术平均值而非几何平均值', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定终温计算逻辑是否正确', 'evidence': ''}

# rule_id=norm_deb18397a0098df8 | domain=Thermodynamics & Statistical Physics | topic=Carnot Cycle and Efficiency
# rule_id=norm_deb18397a0098df8 | domain=Thermodynamics & Statistical Physics | topic=Carnot Cycle and Efficiency
def check_norm_deb18397a0098df8_edeb35b58ada(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及热机循环（Atkinson, Otto, Diesel, Carnot 等）
    cycle_keywords = ['cycle', 'atkinson', 'otto', 'diesel', 'carnot', '循环', '热机']
    if not any(kw in (question + context).lower() for kw in cycle_keywords):
        return {'result': 'inconclusive', 'message': '未检测到热力学循环相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证 prediction 是否包含状态点闭合性描述（如 P4=P1, V4=V1 或 T4/T1 关系）
    # 重点检查是否提及了循环的终点回到起点，或者特定的等压/等容过程连接
    pred_lower = prediction.lower()
    closure_patterns = [
        r'[pv]\s*4\s*=\s*[pv]\s*1',
        r't\s*4\s*/\s*t\s*1',
        r'v\s*4\s*/\s*v\s*1',
        r'闭合', 'closure', 'return to', 'back to state 1'
    ]

    has_closure_logic = any(re.search(p, pred_lower) for p in closure_patterns)

    # Step 3: 符号与公式校验 — 针对 symbolic_hint 中的 T4/T1 = V4/V1 (等压) 或类似绝热关系进行匹配
    # 检查是否在计算效率时考虑了状态方程的连贯性
    efficiency_keywords = ['efficiency', '效率', 'eta', '\\eta']
    has_efficiency_calc = any(kw in pred_lower for kw in efficiency_keywords)

    if has_efficiency_calc and not has_closure_logic:
        return {
            'result': 'fail',
            'message': '在计算循环效率时，未明确验证状态点闭合条件（如 P4=P1 或 V4=V1）或温度体积关系',
            'evidence': prediction[:200]
        }

    # 检查具体的 canonical 公式 T4/T1 = V4/V1 (针对等压 4-1 过程)
    if re.search(r't_?4\s*/\s*t_?1\s*=\s*v_?4\s*/\s*v_?1', pred_lower.replace(' ', '')):
        return {'result': 'pass', 'message': '检测到正确的循环闭合状态方程关系', 'evidence': re.search(r't_?4\s*/\s*t_?1\s*=\s*v_?4\s*/\s*v_?1', pred_lower.replace(' ', '')).group()}

    if has_closure_logic:
        return {'result': 'pass', 'message': '已包含循环闭合性或状态点关系的逻辑分析', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定是否满足循环闭合性校验要求', 'evidence': ''}

# rule_id=norm_0a939f28d3e83724 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_0a939f28d3e83724 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_0a939f28d3e83724_217c6d85480c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及 Maxwell 分布与行星大气逃逸 (Jeans Escape)
    trigger_keywords = ['maxwell', 'escape', 'jeans', '逃逸', '通量', 'flux']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到 Maxwell 分布或大气逃逸相关场景', 'evidence': ''}

    # Step 2: 检查建模逻辑 — 是否使用了通量公式 (n/4 * <v>) 或对半空间的积分 (v_z > 0)
    # 重点在于区分单纯的概率密度积分与带有速度分量/方向权重的通量积分
    pred = prediction.lower()
    flux_patterns = [
        r'n/4',
        r'1/4.*n.*v',
        r'v.*cos\(?\\?theta\)?',
        r'v_z.*f\(v\)',
        r'\\int.*v.*\\cos',
        r'\\int.*v_z'
    ]

    has_flux_modeling = any(re.search(pat, pred) for pat in flux_patterns)

    # Step 3: 符号覆盖检查 (required_symbols: theta, f(v), v_esc)
    required_symbols = ['v_{esc}', 'f(v)', 'theta']
    symbol_count = sum(1 for sym in required_symbols if sym.lower() in pred or sym.replace('\\', '') in pred)

    if not has_flux_modeling:
        # 如果只提到了积分但没有体现通量特征（如 cos theta 或 n/4），则判定为建模错误
        if 'int' in pred and ('pdf' in pred or 'distribution' in pred):
            return {
                'result': 'fail',
                'message': '在计算逃逸通量时，未体现通量公式 (n/4 * <v>) 或对垂直速度分量的积分，可能错误地使用了简单的概率密度积分。',
                'evidence': prediction[:200]
            }
        return {'result': 'inconclusive', 'message': '未能明确识别通量建模过程', 'evidence': ''}

    if symbol_count >= 2 or re.search(r'n/4', pred):
        return {
            'result': 'pass',
            'message': '检测到合理的通量建模公式或积分结构。',
            'evidence': re.search(r'.{0,50}(n/4|cos|v_z).{0,50}', pred).group(0) if re.search(r'(n/4|cos|v_z)', pred) else ''
        }

    return {'result': 'inconclusive', 'message': '建模逻辑尚不明确', 'evidence': ''}

# rule_id=norm_1cddb679fa099786 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_1cddb679fa099786 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_1cddb679fa099786_28bec720ca60(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及跨数量级乘除法（如 10^-9, 10^a 等形式）
    trigger_pattern = r'10\^\{?-?\d+\}?'
    if not re.search(trigger_pattern, question + context + prediction):
        return {'result': 'inconclusive', 'message': '未检测到跨数量级计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证指数加法校验逻辑 10^a * 10^b = 10^(a+b)
    # 寻找类似 10^a * 10^b 或 10^a \cdot 10^b 的结构
    calc_match = re.search(r'10\^\{?(-?\d+)\}?\s*[\*\xb7\cdot]\s*10\^\{?(-?\d+)\}?', prediction)
    if calc_match:
        a = int(calc_match.group(1))
        b = int(calc_match.group(2))
        expected_sum = a + b
        # 检查 prediction 中是否出现了预期的 10^(a+b)
        result_pattern = f'10\\^\\{{?{expected_sum}\\}}?'
        if not re.search(result_pattern, prediction):
            return {'result': 'fail', 'message': f'指数加法校验失败：10^{a} * 10^{b} 应为 10^{expected_sum}', 'evidence': calc_match.group(0)}

    # Step 3: 物理常识校验 — 检查光谱展宽（broadening/width）是否远小于原波长（wavelength）
    if 'wavelength' in (question + context).lower() or '光谱' in (question + context):
        # 提取波长和展宽的量级（简单正则提取 10^n）
        magnitudes = re.findall(r'10\^\{?(-?\d+)\}?', prediction)
        if len(magnitudes) >= 2:
            # 假设较小的是展宽，较大的是波长（指数越小值越小）
            m_ints = [int(m) for m in magnitudes]
            if max(m_ints) == min(m_ints) and 'width' in prediction.lower():
                return {'result': 'fail', 'message': '物理常识校验失败：展宽量级不应与原波长相同', 'evidence': f'magnitudes found: {m_ints}'}

    # Step 4: 符号覆盖检查 (required_symbols: a, b)
    if '10^' in prediction:
        return {'result': 'pass', 'message': '已执行量级校验逻辑', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '证据不足', 'evidence': ''}

# rule_id=norm_36e297304f9b5d2e | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_36e297304f9b5d2e | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_36e297304f9b5d2e_bb54304fdce4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 涉及宏观物质分子总数计算（如分子数、阿伏伽德罗常数、摩尔质量等关键词）
    trigger_keywords = ['分子数', '总分子数', 'number of molecules', 'N_A', 'Avogadro']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到宏观分子总数计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找预测结果中的分子总数 N 的量级
    # 匹配科学计数法如 10^23, 10^{23}, 6.02e23 等
    n_pattern = re.compile(r'(?:N|n)\s*=\s*.*?10\^?{?(\d+)}?|(\d+(?:\.\d+)?)[eE](\d+)', re.IGNORECASE)
    match = n_pattern.search(prediction)

    if not match:
        # 如果没找到显式的 N=，尝试直接找 10 的幂次
        match = re.search(r'10\^?{?(\d+)}?', prediction)

    if match:
        # 提取指数部分
        groups = match.groups()
        exponent_str = groups[0] or groups[2] or (groups[0] if len(groups) > 0 else None)
        if exponent_str:
            try:
                exponent = int(exponent_str)
                # 校验量级：宏观物质通常在 10^22 到 10^24 之间（1摩尔量级）
                # 若出现 10^30 或 10^10 等极端值，判定为逻辑错误（通常是单位换算错误）
                if exponent >= 28 or exponent <= 15:
                    return {
                        'result': 'fail',
                        'message': f'分子总数量级异常 (10^{exponent})，请检查摩尔质量单位或计算过程',
                        'evidence': match.group(0)
                    }
                elif 21 <= exponent <= 25:
                    return {
                        'result': 'pass',
                        'message': '分子总数量级符合宏观常识',
                        'evidence': match.group(0)
                    }
            except ValueError:
                pass

    # Step 3: 符号校验 — 检查是否使用了 N = (m/M) * N_A 逻辑
    if 'N_A' in prediction and ('m/M' in prediction or 'M' in prediction):
        return {'result': 'pass', 'message': '计算公式符合规范', 'evidence': '检测到 N_A 与质量/摩尔质量关系'}

    return {'result': 'inconclusive', 'message': '未能提取到明确的分子数量级结果', 'evidence': ''}

# rule_id=norm_3f7750e796ec7f23 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_3f7750e796ec7f23 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_3f7750e796ec7f23_4f98fb84b00c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及玻尔兹曼分布或统计平均值计算
    trigger_keywords = ['exp', 'e^-', 'boltzmann', '玻尔兹曼', '统计平均', 'average', 'expectation']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到玻尔兹曼分布或统计平均值计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须包含配分函数 Z 或归一化分母的显式计算
    pred = prediction.lower()
    # 匹配 Z = ... 或 分母位置的求和/积分形式
    z_patterns = [
        r'z\s*=\s*(sum|\\sum|\int)',
        r'\\frac{.*}{z}',
        r'\\frac{.*}{\\sum.*exp}',
        r'partition function',
        r'配分函数'
    ]

    has_normalization = any(re.search(p, pred, re.IGNORECASE) for p in z_patterns)

    # Step 3: 符号校验 — 检查 E, T, k 等关键符号是否在公式中出现
    required_symbols = ['e', 't', 'k']
    symbol_count = sum(1 for sym in required_symbols if sym in pred)

    if not has_normalization:
        # 如果在计算平均值但没有看到明显的归一化步骤，判定为风险
        if 'average' in pred or 'mean' in pred or '平均' in pred:
            return {
                'result': 'fail',
                'message': '在计算统计平均时未发现显式的配分函数 Z 或归一化步骤，可能导致系数错误',
                'evidence': prediction[:200]
            }
        return {'result': 'inconclusive', 'message': '无法确定是否执行了归一化', 'evidence': ''}

    if symbol_count >= 2:
        return {
            'result': 'pass',
            'message': '检测到配分函数或归一化结构，且包含关键物理符号',
            'evidence': re.search(r'.{0,50}(z|\\sum|exp).{0,50}', pred, re.IGNORECASE).group(0) if re.search(r'(z|\\sum|exp)', pred, re.IGNORECASE) else ''
        }

    return {'result': 'inconclusive', 'message': '检测到部分归一化迹象但证据不足', 'evidence': ''}

# rule_id=norm_5623dc25e1b24caa | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_5623dc25e1b24caa | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_5623dc25e1b24caa_e5421b6a9fcd(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题干是否明确要求“保留一位有效数字”
    trigger_patterns = [
        r'retain one significant figure',
        r'one significant figure',
        r'1 significant figure',
        r'保留一位有效数字',
        r'一位有效数字'
    ]
    combined_text = (question + context).lower()
    if not any(re.search(p, combined_text) for p in trigger_patterns):
        return {'result': 'inconclusive', 'message': '未检测到有效数字位数限制的明确要求', 'evidence': ''}

    # Step 2: 检查 prediction 中的最终数值结果是否符合一位有效数字
    # 寻找形如 "is X", "= X", "answer is X" 后的数值，或者末尾的数值
    # 匹配浮点数或科学计数法，例如 0.003, 4, 5e-2, 0.6
    numbers = re.findall(r'(?:=|is|be|to)\s*([+-]?\d*\.?\d+(?:[eE][+-]?\d+)?)', prediction)
    if not numbers:
        # 如果没找到显式的赋值，尝试匹配最后出现的数字
        numbers = re.findall(r'([+-]?\d*\.?\d+(?:[eE][+-]?\d+)?)', prediction)

    if not numbers:
        return {'result': 'inconclusive', 'message': '未能从预测中提取到数值结果', 'evidence': ''}

    final_val_str = numbers[-1]

    # Step 3: 验证有效数字位数
    # 提取数字部分（去掉负号和科学计数法的指数部分）
    clean_num = re.sub(r'^-', '', final_val_str)
    clean_num = re.split(r'[eE]', clean_num)[0]

    # 去掉小数点，去掉前导零
    digits_only = clean_num.replace('.', '').lstrip('0')

    if not digits_only:
        return {'result': 'inconclusive', 'message': '数值解析异常', 'evidence': final_val_str}

    # 如果有效数字位数大于1，则判定为格式错误
    if len(digits_only) > 1:
        return {
            'result': 'fail',
            'message': f'要求保留一位有效数字，但检测到结果 {final_val_str} 包含多位有效数字',
            'evidence': f'Value: {final_val_str}, Digits: {digits_only}'
        }

    return {'result': 'pass', 'message': '数值符合一位有效数字约束', 'evidence': final_val_str}

# rule_id=norm_5f5ff0dd404905f8 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_5f5ff0dd404905f8 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_5f5ff0dd404905f8_86d2f682f462(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“一半粒子逃逸”、“半衰期”或“恒定逃逸率”场景
    trigger_keywords = ['一半', 'half', 'escape', '逃逸', 'decay', '衰减', 'half-life']
    if not any(k in (question + context).lower() for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到粒子逃逸或半衰期相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否识别了指数衰减规律及逃逸率 lambda (或时间常数 tau)
    # 寻找 lambda, tau, ln2 等关键符号或描述
    pred_lower = prediction.lower()
    has_rate = re.search(r'(\\lambda|rate|constant|\\tau|时间常数)', pred_lower)
    has_half_logic = re.search(r'(ln\s*2|0\.693|log\s*2)', pred_lower)

    if not (has_rate or 'exp' in pred_lower):
        return {'result': 'fail', 'message': '未体现指数衰减或恒定逃逸率逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 验证 t_{1/2} = ln2 / lambda 的一致性
    # 检查公式结构：t 约等于 0.693/lambda 或 lambda = ln2/t
    formula_match = re.search(r'(t|T).*?=.*?ln\s*2\s*/\s*(\\lambda|\\alpha|k)', prediction)
    numeric_match = re.search(r'0\.693', prediction)

    if formula_match or numeric_match:
        return {'result': 'pass', 'message': '正确应用了半衰期与逃逸率的关系公式', 'evidence': (formula_match.group(0) if formula_match else '0.693')}

    # 如果提到了一半但计算逻辑错误（如直接除以2而非对数关系）
    if re.search(r't.*?=.*?1\s*/\s*(2.*?\\lambda|2.*?k)', pred_lower):
        return {'result': 'fail', 'message': '错误地使用了线性衰减逻辑而非指数衰减的ln2关系', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定公式应用的准确性', 'evidence': ''}

# rule_id=norm_65009f804e2759b5 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_65009f804e2759b5 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_65009f804e2759b5_3ea16fc64b06(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及单面散热、稀薄气体（平均自由程）及初静止状态
    trigger_keywords = ['散热', '辐射', '单面', 'one side', 'cooling', 'heat loss']
    gas_keywords = ['稀薄', 'mean free path', '平均自由程', 'knudsen', 'kn']
    motion_keywords = ['静止', 'rest', 'initial', 'motion', 'recoil', '反冲']

    q_c = (question + context).lower()
    if not any(k in q_c for k in trigger_keywords) or not any(k in q_c for k in gas_keywords):
        return {'result': 'inconclusive', 'message': '未检测到非对称散热或稀薄气体场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了动量变化与热量/速度的关系 dP = η * (dQ / v)
    # 重点在于区分环境压力与由于温差导致的分子反弹动量差
    pred = prediction.lower()
    # 检查是否提到动量与热量的关联，而非单纯的理想气体状态方程 P=nkT
    momentum_heat_link = re.search(r'(dq|q|heat).*?(v|velocity|speed|momentum|p)', pred)
    if not momentum_heat_link:
        return {'result': 'fail', 'message': '未建立散热(dQ)与动量/速度(v)之间的物理关联', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 dQ, m, v_rms 等关键符号及公式结构
    # 核心公式特征：mv ~ dQ/v 或 F ~ (dQ/dt)/v
    required_symbols = ['dq', 'm', 'v']
    missing_symbols = [s for s in required_symbols if s not in pred]

    # 检查公式结构：dQ 除以速度项
    formula_pattern = re.search(r'dq\s*/\s*v|q\s*/\s*v|dq\s*\\cdot\s*v', pred)

    if formula_pattern:
        return {'result': 'pass', 'message': '成功识别非对称散热反冲建模逻辑', 'evidence': str(formula_pattern.group())}

    if len(missing_symbols) >= 2:
        return {'result': 'fail', 'message': '缺少关键物理量符号(dQ, m, v)，未能体现反冲建模', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '检测到相关讨论但公式结构不明确', 'evidence': prediction[:150]}

# rule_id=norm_7313e8eb6ca3b0fd | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_7313e8eb6ca3b0fd | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_7313e8eb6ca3b0fd_48bf832c5f8b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多普勒展宽或光谱线宽计算
    trigger_keywords = ['多普勒展宽', 'Doppler broadening', '光谱线宽', 'line width', 'Delta lambda']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多普勒展宽相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证公式结构 Delta lambda / lambda approx v/c
    # 检查是否包含波长变化与速度/光速的关系
    pred_text = prediction.replace(' ', '')
    # 匹配类似 Delta lambda / lambda = v/c 或 Delta lambda = lambda * (v/c)
    formula_pattern = r'(\\Delta\\lambda|Δλ).*(\\lambda|λ).*(v/c|\\sqrt{.*}/c)'
    if not re.search(formula_pattern, pred_text, re.IGNORECASE) and 'v/c' not in pred_text.lower():
        return {'result': 'fail', 'message': '未发现多普勒展宽的核心比例关系 (v/c)', 'evidence': prediction[:200]}

    # Step 3: 符号与量级校验 — 检查 c 的量级和速度 v 的定义
    # 检查光速 c 是否为 10^8 量级
    c_magnitude_check = re.search(r'3[\*x]10\^?8|c=3e8', pred_text.lower())
    # 检查是否使用了热运动速度 (sqrt(2kT/m) 或 sqrt(3kT/m))
    thermal_v_check = re.search(r'sqrt\((2|3)k.*?T/m\)', pred_text.lower()) or 'kT/m' in pred_text.lower()

    if not c_magnitude_check and '10^8' not in pred_text:
        return {'result': 'fail', 'message': '光速 c 的量级缺失或不正确', 'evidence': prediction[:200]}

    if thermal_v_check:
        return {'result': 'pass', 'message': '模型一致性校验通过：包含正确的热运动速度与光速比例关系', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '公式结构基本存在但关键物理量定义不明确', 'evidence': prediction[:200]}

# rule_id=norm_7457a07d1f7f9caa | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_7457a07d1f7f9caa | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_7457a07d1f7f9caa_35bfd0608e0c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及饱和蒸汽压(P_sat)或饱和蒸汽密度(rho_sat)以及相对湿度(RH)
    trigger_keywords = ['饱和蒸汽压', '饱和压强', '饱和密度', '饱和蒸汽密度', 'P_sat', 'p_sat', 'rho_sat', 'ρ_sat', '相对湿度']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到饱和参数或相对湿度计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证 prediction 中是否使用了 RH = P/P_sat 或 RH = rho/rho_sat 的一致性定义
    # 检查是否混用了压强和密度，或者公式结构是否错误
    pred_lower = prediction.lower()

    # 匹配 RH = P / rho 或 RH = rho / P 这种不一致的情况
    inconsistent_patterns = [
        r'p\s*/\s*(rho|ρ)',
        r'(rho|ρ)\s*/\s*p',
        r'压强\s*/\s*密度',
        r'密度\s*/\s*压强'
    ]

    for pattern in inconsistent_patterns:
        if re.search(pattern, pred_lower):
            return {'result': 'fail', 'message': '相对湿度定义中分子分母物理量不一致（混用了压强和密度）', 'evidence': re.search(pattern, pred_lower).group()}

    # Step 3: 符号覆盖检查 — 检查是否包含必要的符号 RH, rho/P, rho_sat/P_sat
    has_rh = 'rh' in pred_lower or '相对湿度' in pred_lower
    has_p_ratio = re.search(r'p\s*/\s*p', pred_lower) or '压强之比' in pred_lower
    has_rho_ratio = re.search(r'(rho|ρ)\s*/\s*(rho|ρ)', pred_lower) or '密度之比' in pred_lower

    if has_rh and (has_p_ratio or has_rho_ratio):
        return {'result': 'pass', 'message': '相对湿度定义公式使用正确且物理量一致', 'evidence': prediction[:150]}

    # Step 4: 检查是否过度引入 R 导致精度损失（如果题目已给饱和参数）
    if ('p_sat' in (question + context).lower() or 'ρ_sat' in (question + context).lower()) and ' r ' in pred_lower:
        # 这是一个弱警告，若没有明显错误则保持 inconclusive
        pass

    return {'result': 'inconclusive', 'message': '无法明确判定公式一致性或计算过程', 'evidence': prediction[:100]}

# rule_id=norm_796035a43633c293 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_796035a43633c293 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_796035a43633c293_4b2099a69664(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及磁化率 χ << 1 且涉及 M 与 B/H 的关系
    trigger_keywords = ['χ', 'chi', '磁化率', 'susceptibility']
    has_trigger = any(kw in (question + context) for kw in trigger_keywords)
    # 检查是否提到 χ 远小于 1 的近似背景
    has_approx = re.search(r'χ\s*<<\s*1|chi\s*<<\s*1|磁化率很小', question + context)

    if not (has_trigger and has_approx):
        return {'result': 'inconclusive', 'message': '未检测到 χ << 1 的磁学近似场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否正确应用 B ≈ μ0H 或 M ≈ χ(B/μ0)
    # 错误情况通常是混淆了 B 和 H 的定义，或者在 M = χH 中没有将 H 替换为 B/μ0 (当题目主变量为 B 时)
    pred = prediction.lower()

    # 检查是否提到了磁感应强度 B 与磁场强度 H 的基本关系式
    rel_pattern = re.search(r'b\s*=\s*μ0\s*\(?h\s*\+\s*m\)?', pred.replace(' ', ''))
    approx_pattern = re.search(r'b\s*≈\s*μ0\s*h|h\s*≈\s*b\s*/\s*μ0', pred.replace(' ', ''))

    # Step 3: 符号覆盖与公式结构检查
    # 核心检查：M 是否被表达为 χ * (B / μ0)
    m_subst_pattern = re.search(r'm\s*=\s*χ\s*\(?b\s*/\s*μ0\)?|m\s*=\s*chi\s*\(?b\s*/\s*mu0\)?', pred.replace(' ', ''))

    if m_subst_pattern or approx_pattern:
        return {'result': 'pass', 'message': '正确应用了磁学量近似代换 B ≈ μ0H', 'evidence': m_subst_pattern.group(0) if m_subst_pattern else approx_pattern.group(0)}

    # 如果明确出现了 M = χB 这种错误的量纲或代换（漏掉 μ0），则判定为 fail
    if re.search(r'm\s*=\s*χ\s*b|m\s*=\s*chi\s*b', pred.replace(' ', '')):
        return {'result': 'fail', 'message': '磁学量代换错误：在 M = χH 中直接将 H 替换为 B 而忽略了 μ0', 'evidence': 'M = χB'}

    return {'result': 'inconclusive', 'message': '无法确定是否正确执行了 B 与 H 的近似代换', 'evidence': ''}

# rule_id=norm_839b21fb12617b29 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_839b21fb12617b29 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_839b21fb12617b29_63458d9cf5aa(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两容器间通过小孔的泻流质量流率计算
    trigger_keywords = ['泻流', 'effusion', '质量流率', 'mass flow rate', '小孔', 'hole', 'orifice']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到泻流质量流率相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证结果是否包含压强差 (p1 - p2) 和温度 T 的开方关系
    pred = prediction.lower()
    # 检查压强差项
    has_p_diff = re.search(r'p1\s*-\s*p2|p2\s*-\s*p1|\\Delta\s*p', pred)
    # 检查温度开方项 (通常在分母)
    has_sqrt_t = re.search(r'sqrt\(t\)|t\^\(?-1/2\)?|1/sqrt\(t\)|\\sqrt{t}', pred)

    if not (has_p_diff and has_sqrt_t):
        return {
            'result': 'fail',
            'message': '预测结果中缺失压强差 (p1-p2) 或温度 T 的平方根反比关系',
            'evidence': prediction[:200]
        }

    # Step 3: 符号/公式结构校验 — 检查系数中是否包含 mu, R, pi 等关键物理量
    required_symbols = ['mu', 'r', 'pi']
    # 匹配 mu (或 m), R, pi 的存在性
    missing_symbols = [sym for sym in required_symbols if sym not in pred and f'\\{sym}' not in pred]

    # 进一步检查公式核心结构 sqrt(mu / (2 * pi * R * T))
    # 允许一定的符号变体，如 M 代替 mu
    formula_pattern = re.search(r'sqrt\(.*(mu|m|M).*(pi|\\pi).*(r|R).*t\)', pred)

    if formula_pattern:
        return {'result': 'pass', 'message': '泻流质量流率公式结构符合预期', 'evidence': formula_pattern.group()}

    if len(missing_symbols) >= 2:
        return {
            'result': 'fail',
            'message': f'公式系数中缺失关键物理量: {missing_symbols}',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '公式结构不完整或无法解析', 'evidence': prediction[:200]}

# rule_id=norm_902229ec08e90068 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_902229ec08e90068 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_902229ec08e90068_8df315ea28ab(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 题干提及图表且未直接给出数值常量
    trigger_keywords = ['graph below', 'shown in the figure', 'figure below', '图中', '下图']
    has_graph = any(kw in (question + context).lower() for kw in trigger_keywords)
    if not has_graph:
        return {'result': 'inconclusive', 'message': '题干未提及图表，不触发此规则', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否随意假设了摩尔热容（如 25 J/mol·K 或 3/2R, 5/2R）
    # 规则指出应从图表提取斜率或积分，而非直接套用理想气体常数假设
    pred_lower = prediction.lower()
    arbitrary_values = [r'25\s*j', r'3/2\s*r', r'5/2\s*r', r'20\.8\s*j']
    found_arbitrary = any(re.search(val, pred_lower) for val in arbitrary_values)

    # Step 3: 检查是否包含图表提取逻辑（斜率 slope 或 积分 integral/area）
    extraction_keywords = ['slope', 'integral', 'area under', '斜率', '积分', '面积', 'read from', '提取']
    has_extraction = any(kw in pred_lower for kw in extraction_keywords)

    if found_arbitrary and not has_extraction:
        return {
            'result': 'fail',
            'message': '模型可能随意假设了热容数值，未体现从图表中提取斜率或积分的过程',
            'evidence': prediction[:200]
        }

    if has_extraction:
        return {
            'result': 'pass',
            'message': '模型体现了从图表中提取数据的逻辑',
            'evidence': re.search(r'.{0,50}(slope|integral|area|斜率|积分|面积).{0,50}', pred_lower).group(0) if has_extraction else ''
        }

    return {'result': 'inconclusive', 'message': '无法确定数据来源逻辑', 'evidence': ''}

# rule_id=norm_bc40e7d842bcbed1 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_bc40e7d842bcbed1 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_bc40e7d842bcbed1_a05c3eb1ee77(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及气体分子通量、小孔喷流或单位时间单位面积穿过数
    trigger_keywords = ['effusion', 'flux', '小孔', '喷流', '通量', '单位时间', '单位面积', '分子数']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到气体分子通量或喷流相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否包含速度加权积分 v_x * f(v_x) 或其积分结果 1/4 * n * v_bar
    # 重点在于区分是对分布函数直接积分（求和）还是对通量（速度加权）积分
    pred = prediction.lower()

    # 检查是否包含速度加权项 v_x 或 v*cos(theta) 与分布函数的乘积形式
    has_weighted_integral = re.search(r'v_x.*f\(v_x\)|v_x.*p\(v_x\)|v.*cos.*f\(v\)', pred)
    # 检查是否直接引用了通量公式 J = 1/4 * n * v_bar
    has_flux_formula = re.search(r'1/4.*n.*v|n.*v.*/4|1/4.*n.*\\bar{v}', pred)

    if not (has_weighted_integral or has_flux_formula):
        # 如果只提到了分布函数积分而没有速度加权，则判定为建模错误
        if re.search(r'\int.*f\(v\)', pred) and not re.search(r'v.*f\(v\)', pred):
            return {'result': 'fail', 'message': '计算通量时缺失速度加权项，未正确建立积分模型', 'evidence': prediction[:200]}
        return {'result': 'inconclusive', 'message': '未在推理中发现明确的通量积分表达式', 'evidence': ''}

    # Step 3: 符号校验 — 检查 required_symbols 是否出现
    required = ['v', 'n', 'f']
    missing = [s for s in required if s not in pred]
    if not missing:
        return {'result': 'pass', 'message': '已包含速度加权积分模型或正确的通量公式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到部分模型要素但证据不足', 'evidence': ''}

# rule_id=norm_d8d8b65f496e6de5 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_d8d8b65f496e6de5 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_d8d8b65f496e6de5_d7b7015d002e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及气体分子碰撞率、小孔流出或壁面碰撞频率
    trigger_keywords = ['碰撞率', '碰撞频率', 'collision rate', 'collision frequency', '小孔', 'effusion', '单位时间', '撞击']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到气体分子碰撞率或小孔流出相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 碰撞率是否与压强 p 成正比，或是否包含正确的公式结构
    # 核心公式: N = p / sqrt(2 * pi * m * k * T) 或 N ∝ p
    pred_lower = prediction.lower()

    # 检查是否提到压强依赖性
    has_pressure_dep = any(p_term in pred_lower for p_term in ['正比', 'proportional', 'p/', 'p /', 'p*s', 'p s'])

    # 检查符号覆盖 (p, T, m, k)
    required_symbols = ['p', 't', 'k', 'm']
    symbol_count = sum(1 for sym in required_symbols if sym in pred_lower)

    # Step 3: 公式结构校验
    # 匹配类似 p/sqrt(T) 或 p/sqrt(2*pi*m*k*T) 的结构
    formula_pattern = r'p\s*/\s*(sqrt|\()|p\s*\.\s*s|p\s*s\s*/'
    has_formula = re.search(formula_pattern, pred_lower) is not null

    if not has_pressure_dep and symbol_count < 2:
        return {'result': 'fail', 'message': '未体现碰撞率与压强p的依赖关系或关键物理量缺失', 'evidence': prediction[:200]}

    if has_formula or (has_pressure_dep and 'sqrt' in pred_lower):
        return {'result': 'pass', 'message': '正确识别了碰撞率与压强及温度的关系', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到相关讨论但无法确定公式准确性', 'evidence': prediction[:200]}

# rule_id=norm_e139dc14ddbf0db9 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_e139dc14ddbf0db9 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_e139dc14ddbf0db9_d883608bc802(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及热平衡态下的气体（如热云、玻尔兹曼分布）及各向异性势场/膨胀
    trigger_keywords = ['thermal equilibrium', 'thermal cloud', 'velocity distribution', 'anisotropic', 'expansion', '热平衡', '速度分布', '各向异性', '自由膨胀']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到热平衡速度分布相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否错误地将势场的各向异性耦合到了速度分布中
    # 错误逻辑通常表现为速度分布函数 f(v) 中包含了势场参数（如频率 omega_x != omega_y）或速度分量系数不一致
    pred = prediction.lower()

    # 寻找速度分布公式的迹象，检查指数项是否为各向同性的 (vx^2 + vy^2 + vz^2)
    # 如果 prediction 中提到速度分布随势场形状改变，或者 vx, vy 的系数不相等，则可能违反规则
    anisotropic_error = re.search(r'f\(v_?[xyz]\).*=.*exp\(-.*(omega|\omega|k_?[xyz]).*(v_?[xyz]\^2).*\)', pred)
    if anisotropic_error and ('different' in pred or 'anisotropic' in pred or '各向异性' in pred):
        return {'result': 'fail', 'message': '错误地将势场各向异性耦合到了速度分布函数中；热平衡下速度分布应为各向同性', 'evidence': anisotropic_error.group()}

    # Step 3: 符号/公式校验 — 检查是否符合 Maxwell-Boltzmann 分布的各向同性形式
    # 核心公式特征：exp(-m*v^2 / 2kT) 或 v_x^2 + v_y^2 + v_z^2 的对称性
    isotropic_pattern = r'exp\(.*-(m|M)?(v_?x\^2\s*\+\s*v_?y\^2\s*\+\s*v_?z\^2)/(2k_?BT?|2kT)\)'
    if re.search(isotropic_pattern, prediction.replace(' ', '')):
        return {'result': 'pass', 'message': '正确识别了热平衡下速度分布的各向同性', 'evidence': '检测到符合 Maxwell-Boltzmann 分布的各向同性公式'}

    # 如果提到速度分布仅取决于温度 T，也视为 pass
    if 'temperature' in pred and ('only' in pred or 'independent' in pred) and ('potential' in pred or 'shape' in pred):
        return {'result': 'pass', 'message': '明确指出速度分布仅取决于温度，与势场无关', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '无法确定速度分布是否被错误处理', 'evidence': ''}

# rule_id=norm_e55c6b87ecada8c2 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_e55c6b87ecada8c2 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_e55c6b87ecada8c2_95e2eba104d5(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及粒子云/气体在撤除束缚势后的自由膨胀或长时极限 (t >> t0)
    trigger_keywords = ['自由膨胀', 'free expansion', 'long time', 't \\to \\infty', 't >>', '撤除束缚', 'release from trap']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到自由膨胀长时极限的相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否提到空间分布的长宽比（R/x_i）趋于速度分布的长宽比（v_rms）
    pred = prediction.lower()
    # 检查是否包含核心逻辑：空间形状由速度分布决定
    logic_keywords = ['速度分布', 'velocity distribution', 'momentum distribution', 'aspect ratio', '长宽比']
    if not any(kw in pred for kw in logic_keywords):
        return {'result': 'fail', 'message': '未提及长时极限下空间形状与速度分布的关系', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查 symbolic_hint 中的公式结构
    # 匹配类似 x_i/x_j = v_i/v_j 或 R_i/R_j = v_i/v_j 的结构
    formula_patterns = [
        r'x_[ij].*x_[ij].*v_[ij].*v_[ij]',
        r'R_[ij].*R_[ij].*v_[ij].*v_[ij]',
        r'\\frac{x_i}{x_j}.*\\frac{v_{i,rms}}{v_{j,rms}}',
        r'\\lim_{t \\to \\infty}',
        r'R\(t\) \\approx V\*t'
    ]

    found_formula = False
    for pattern in formula_patterns:
        if re.search(pattern, prediction):
            found_formula = True
            break

    if found_formula:
        return {'result': 'pass', 'message': '正确识别长时极限下的几何形状由速度分布决定', 'evidence': prediction[:200]}

    # 如果提到了逻辑但没写出明确公式，且没有明显错误，则保守返回 inconclusive
    return {'result': 'inconclusive', 'message': '逻辑提及但缺乏明确的公式推导或比例关系', 'evidence': prediction[:200]}

# rule_id=norm_e8a4fc11adbf8222 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_e8a4fc11adbf8222 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_e8a4fc11adbf8222_a48930ebbefd(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及封闭容器内气体的体积变化与密度计算
    # 关键词：封闭容器/密闭、体积变化(V1, V2)、密度(rho/ρ)
    trigger_keywords = ['封闭', '密闭', '容器', '体积', 'V1', 'V2']
    if not any(kw in (question + context) for kw in trigger_keywords) or '密度' not in (question + context):
        return {'result': 'inconclusive', 'message': '未检测到封闭容器体积变化与密度关联的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否错误地将密度与温度T关联，或是否正确使用了质量守恒 rho2 = rho1 * (V1/V2)
    pred = prediction.lower()
    # 检查是否错误地认为密度随温度变化（在质量守恒的前提下）
    # 典型错误：rho2 = rho1 * (T1/T2) 或类似理想气体状态方程对压强的处理方式
    temp_density_error = re.search(r'ρ.*[\*\/].*T|密度.*温度', pred)

    # 检查正确逻辑：rho2 = rho1 * (V1/V2) 或 m = rho * V
    correct_logic = re.search(r'ρ2\s*=\s*ρ1\s*\*\s*\(?V1\s*/\s*V2\)?|ρ1V1\s*=\s*ρ2V2|m\s*=\s*ρV', prediction)

    # Step 3: 判定结果
    if temp_density_error and not correct_logic:
        return {
            'result': 'fail',
            'message': '错误地将密度变化与温度关联，忽略了封闭容器质量守恒导致的密度仅与体积相关的规律',
            'evidence': re.search(r'.{0,50}(密度|ρ).{0,50}', prediction).group(0) if '密度' in prediction or 'ρ' in prediction else prediction[:100]
        }

    if correct_logic:
        return {
            'result': 'pass',
            'message': '正确应用了质量守恒定律计算密度变化，未受温度干扰',
            'evidence': correct_logic.group(0)
        }

    return {'result': 'inconclusive', 'message': '未能明确识别密度计算的逻辑路径', 'evidence': ''}

# rule_id=norm_f1eae97b229f2d83 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
# rule_id=norm_f1eae97b229f2d83 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_norm_f1eae97b229f2d83_619f87b8ea6b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及气体分子通量、小孔、撞击器壁或质量流率
    trigger_keywords = ['小孔', '撞击', '器壁', '通量', '流率', 'effusion', 'flux', 'wall', 'orifice']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到分子通量或小孔外流场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否错误使用了 v_rms (sqrt(3RT/M)) 而非 v_avg (sqrt(8RT/pi*M))
    # 或者是检查通量公式 J = 1/4 * n * v_avg 或 J = p / sqrt(2 * pi * m * k_B * T)
    pred = prediction.lower()

    # 检查是否错误使用了均方根速率 v_rms 的系数 3
    if re.search(r'sqrt\(3.*?/.*?\)', pred) or '3rt' in pred.replace(' ', ''):
        if '1/4' in pred or 'v_avg' in pred or '8rt' in pred or '8/' in pred:
            pass # 可能同时提到了，暂不判定失败
        else:
            return {'result': 'fail', 'message': '在计算通量或撞击率时疑似错误使用了均方根速率(v_rms)而非平均速率(v_avg)', 'evidence': prediction[:200]}

    # Step 3: 符号与公式结构校验 (J = p / sqrt(2 * pi * m * k_B * T))
    # 匹配分母中包含 2, pi, m, k, T 的结构
    canonical_pattern = r'p\s*/\s*sqrt\(\s*2.*?pi.*?m.*?k.*?T\s*\)'
    if re.search(canonical_pattern, pred, re.IGNORECASE):
        return {'result': 'pass', 'message': '检测到正确的分子通量统计公式', 'evidence': re.search(canonical_pattern, pred, re.IGNORECASE).group()}

    # 检查是否使用了 1/4 * n * v_avg 形式
    if re.search(r'1/4.*?n.*?v', pred) or re.search(r'n.*?v.*?/.*?4', pred):
        return {'result': 'pass', 'message': '使用了正确的 1/4 * n * v_avg 统计形式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定通量计算的具体速率基准', 'evidence': ''}

# rule_id=norm_00a1ccccfdd43a73 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_00a1ccccfdd43a73 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_00a1ccccfdd43a73_7ff42804121c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及开口向下/倒置容器、液柱高度h及封闭气体
    trigger_keywords = ['倒置', '开口向下', '倒扣', 'inverted', 'upside down', 'opening downward']
    content_all = (question + context).lower()
    if not any(kw in content_all for kw in trigger_keywords) or 'h' not in content_all:
        return {'result': 'inconclusive', 'message': '未检测到倒置容器或液柱高度相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别压强建模公式 P = P_atm - ρgh
    # 重点检查是否错误地使用了 P_atm + ρgh (开口向上情况)
    pred = prediction.replace(' ', '')

    # 匹配 P = P0 - pgh 或 P = Patm - pgh 等变体
    correct_pattern = r'P(_[a-z]+)?=P(_[a-z]+)?-(ρ|rho)gh'
    wrong_pattern = r'P(_[a-z]+)?=P(_[a-z]+)?\+(ρ|rho)gh'

    # 检查是否存在明显的加号建模错误
    if re.search(wrong_pattern, pred, re.IGNORECASE):
        return {
            'result': 'fail',
            'message': '检测到错误的压强建模：倒置容器应为 P = P_atm - ρgh，而非 P_atm + ρgh',
            'evidence': re.search(wrong_pattern, pred, re.IGNORECASE).group()
        }

    # Step 3: 符号覆盖与公式结构校验
    # 如果预测中包含减号形式的压强关系，则视为通过
    if re.search(r'P.*=.*P.*-.*(ρ|rho|p)gh', pred, re.IGNORECASE) or re.search(r'P.*=.*P.*-.*h', pred, re.IGNORECASE):
        return {'result': 'pass', 'message': '压强建模符合倒置容器物理逻辑', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '未能明确提取压强计算公式', 'evidence': ''}

# rule_id=norm_034cd2d813ca8059 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_034cd2d813ca8059 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_034cd2d813ca8059_732cf5e1a574(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及打气过程（pumping cycles）及体积关系
    trigger_keywords = ['打气', '充气', 'pumping', 'cycles', 'n次', '每打一次']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到打气或充气循环场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否区分了打气筒体积 (V_pump) 和容器体积 (V_container)
    # 寻找体积相关的描述，如 V0, V, V1, V2 等
    volume_patterns = [r'V_?\d+', r'V_pump', r'V_container', r'V_容', r'V_筒']
    found_volumes = re.findall('|'.join(volume_patterns), question + context)

    # 如果题目中明确给出了两个不同的体积，但在 prediction 中只使用了一个体积或混淆了比例
    pred_lower = prediction.lower()

    # Step 3: 符号与公式校验 — 检查是否包含增量公式 P_final = P_initial + n * (V_pump/V_container) * P_atm
    # 核心逻辑是检查是否出现了 (V_pump / V_container) 这种比例关系，或者 n * V_pump 的乘积
    has_ratio = re.search(r'V[\w_]*/V[\w_]*', prediction) or re.search(r'\(V/V\)', prediction)
    has_cycle_increment = re.search(r'n\s*\*\s*V', pred_lower) or re.search(r'\d+\s*\*\s*V', pred_lower)

    if 'n' in pred_lower and not (has_ratio or has_cycle_increment):
        return {
            'result': 'fail',
            'message': '在处理打气循环时，未明确体现打气筒单次体积与容器体积的比例关系或增量逻辑',
            'evidence': prediction[:200]
        }

    # 检查是否错误地将 V_pump 当作了 V_container (建模错误)
    if re.search(r'P.*V_pump.*=.*n', pred_lower) and not re.search(r'V_container', pred_lower):
         return {
            'result': 'fail',
            'message': '疑似混淆了打气筒体积与容器体积，未在状态方程中正确区分两者',
            'evidence': prediction[:200]
        }

    if has_ratio or 'P_atm' in prediction:
        return {'result': 'pass', 'message': '正确识别并使用了打气循环中的体积比例关系', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确区分了两个体积', 'evidence': ''}

# rule_id=norm_1a434f709a53aae5 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_1a434f709a53aae5 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_1a434f709a53aae5_b87fd4d6d509(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及亚稳态或机械稳定性边界判定
    trigger_keywords = ['亚稳态', 'metastable', '机械稳定性', 'mechanical stability', '稳定性边界', 'spinodal']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到亚稳态或机械稳定性相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须使用 dP/dV = 0 确定临界点/边界点
    # 匹配导数为0的表达，如 dP/dV=0, partial P / partial V = 0 等
    dpdv_pattern = r'(dP/dV|\partial\s*P\s*/\s*\partial\s*V)\s*=\s*0'
    if not re.search(dpdv_pattern, prediction, re.IGNORECASE):
        return {'result': 'fail', 'message': '未明确使用 dP/dV = 0 判定稳定性边界', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查是否保留 (V-b) 项并使用正确的范德华导数形式
    # 范德华方程 P = RT/(V-b) - a/V^2 -> dP/dV = -RT/(V-b)^2 + 2a/V^3 = 0
    # 目标公式结构: RT/(V-b)^2 = 2a/V^3
    required_symbols = ['R', 'T', 'V', 'a', 'b']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    # 检查是否错误地忽略了 b (即检查是否出现了类似 RT/V^2 = 2a/V^3 的简化)
    if 'b' in missing_symbols:
        return {'result': 'fail', 'message': '计算中缺失范德华常数 b，可能导致精度不足', 'evidence': prediction[:200]}

    # 检查核心等式结构
    canonical_pattern = r'RT\s*/\s*\(V\s*-\s*b\)\s*\^?\s*2\s*=\s*2\s*\*?\s*a\s*/\s*V\s*\^?\s*3'
    if re.search(canonical_pattern, prediction.replace(' ', '')):
        return {'result': 'pass', 'message': '正确使用了包含 (V-b) 项的稳定性判定公式', 'evidence': 'Found canonical equation'}

    # 如果有 dP/dV=0 但公式形式不标准，保守返回 inconclusive
    return {'result': 'inconclusive', 'message': '检测到判定逻辑但公式表达不完整或非标准', 'evidence': prediction[:200]}

# rule_id=norm_1cf396c624bae207 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_1cf396c624bae207 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_1cf396c624bae207_35c527379c0d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否要求用特定变量表达目标变量或求比值
    trigger_keywords = ['表达', '表示', '写出', '推导', '比值', 'ratio', 'express', 'derive']
    target_var = 'C'
    # 识别题目中是否包含 "用...表达 C" 或 "C = " 的意图
    if not any(kw in question for kw in trigger_keywords) and not re.search(r'[Cc]\s*=', question):
        return {'result': 'inconclusive', 'message': '未检测到目标变量表达或比值计算场景', 'evidence': question[:100]}

    # Step 2: 检查逻辑 — 提取 prediction 中的最终表达式并检查独立性
    # 寻找类似 C = ... 的等式，或最后一行结论
    lines = [line.strip() for line in prediction.split('\n') if line.strip()]
    if not lines:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    final_expr = lines[-1]
    # 检查是否包含 C 本身或其组成部分 M, R (根据 symbolic_hint)
    # 逻辑：如果要求表达 C，则 C 的等号右侧不应再出现 C 或其定义的关键组成部分（逻辑闭环）
    if '=' in final_expr:
        parts = final_expr.split('=')
        rhs = parts[1] if len(parts) > 1 else ''

        # 检查右侧是否包含目标变量 C 本身（自指错误）
        if re.search(r'\b[Cc]\b', rhs):
            return {'result': 'fail', 'message': '最终表达式右侧仍包含目标变量本身，逻辑未闭环', 'evidence': final_expr}

        # 根据 symbolic_hint，检查是否包含 M, R, T_c 等必要符号（若题目要求用它们表达，则应存在；若作为C的组成部分被要求消去，则不应存在）
        # 此处规则强调“独立性”，即检查是否仍包含不应存在的组成部分
        # 假设规则逻辑是：若 C 由 M, R 组成，表达 C 时右侧不应出现未化简的 M 或 R (视具体物理语境而定)
        # 结合 check_logic: "若存在则推导未完成"
        forbidden_in_rhs = ['M', 'R']
        for sym in forbidden_in_rhs:
            if re.search(rf'\b{sym}\b', rhs):
                return {'result': 'fail', 'message': f'最终表达式中仍包含组成部分 {sym}，推导可能未完成', 'evidence': final_expr}

    # Step 3: 符号覆盖检查 (Required symbols: M, R, T_c)
    if 'T_c' in prediction and ('M' in prediction or 'R' in prediction):
        return {'result': 'pass', 'message': '推导逻辑符合独立性检查要求', 'evidence': final_expr}

    return {'result': 'inconclusive', 'message': '无法确定推导是否完成', 'evidence': final_expr}

# rule_id=norm_2305785f2538f03b | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_2305785f2538f03b | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_2305785f2538f03b_869f9fe5397a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及重复操作次数 k 和初始状态定义 N
    # 寻找类似“打气k次”、“操作n次”以及初始量 N 的描述
    trigger_keywords = ['次数', '第k次', 'n次', 'k次', '操作', '重复']
    has_k = any(kw in (question + context) for kw in trigger_keywords) or re.search(r'[nk]\s*=', question + context)
    has_N = re.search(r'[Nn]\s*=', question + context) or '初始' in (question + context)

    if not (has_k and has_N):
        return {'result': 'inconclusive', 'message': '未检测到离散增量操作或初始状态定义', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否出现了 (N+k)/N 或类似的比例建模形式
    # 规则要求：若答案为 (N+k)/N 形式，则 N 必须是无量纲的比例（如体积比、次数比）而非绝对物理量
    pred_clean = prediction.replace(' ', '')
    # 匹配类似 (N+k)/N, 1+k/N, (n+k)/n 等模式
    ratio_pattern = r'\(([Nn]\+[nk])\)/[Nn]|1\+[nk]/[Nn]'
    match = re.search(ratio_pattern, pred_clean)

    if match:
        # Step 3: 符号校验 — 检查 N 的物理意义是否被误用
        # 如果 N 在上下文中被赋予了带单位的量（如 5L, 10Pa），但在公式中直接与次数 k 相加，则逻辑错误
        # 这里的逻辑是：k 是次数（无量纲），N 必须也是“次数”或“份数”含义的无量纲量
        invalid_unit_usage = re.search(r'[Nn]\s*=\s*\d+\s*(L|Pa|atm|mol|kg)', question + context)
        if invalid_unit_usage:
            return {'result': 'fail', 'message': '物理量量纲不匹配：N 为带单位物理量时不可直接与操作次数 k 比例相加', 'evidence': match.group()}
        return {'result': 'pass', 'message': '比例建模形式符合无量纲要求', 'evidence': match.group()}

    # Step 4: 检查 canonical 形式 P_k = P_0 * (1 + k/N)
    canonical_pattern = r'P_?[nk].*P_?0.*\(1\+[nk]/[Nn]\)'
    if re.search(canonical_pattern, pred_clean):
        return {'result': 'pass', 'message': '符合标准离散增量比例公式', 'evidence': 'P_k = P_0 * (1 + k/N)'}

    return {'result': 'inconclusive', 'message': '未发现明确的比例建模公式或违反逻辑的证据', 'evidence': ''}

# rule_id=norm_39cecee3d8757e11 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_39cecee3d8757e11 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_39cecee3d8757e11_1afbdf44631a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及压力梯度近似或恒星/流体静力学平衡建模
    trigger_keywords = ['delta p', 'delta r', 'pressure gradient', 'dP/dr', 'hydrostatic', '静力学平衡', '量级估计']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到压力梯度近似建模场景', 'evidence': ''}

    # Step 2: 检查关键物理符号覆盖 (G, M, P, R)
    required_symbols = ['G', 'M', 'P', 'R']
    missing_symbols = [s for s in required_symbols if s not in prediction]
    if len(missing_symbols) > 1:
        return {'result': 'inconclusive', 'message': '预测中缺少必要的物理量符号', 'evidence': f'缺失: {missing_symbols}'}

    # Step 3: 检查逻辑一致性 — 验证是否在 Delta P / Delta r 近似中对齐了尺度
    # 典型错误：在左侧使用中心压力 P_c / R，但在右侧引力项中使用了不一致的密度或半径定义
    # 匹配模式如 P/R ~ G M rho / R^2 或 P ~ G M^2 / R^4
    pred_clean = prediction.replace(' ', '')
    order_of_magnitude_patterns = [
        r'P.*[\/\/].*R.*G.*M.*rho.*R',
        r'P_c.*R.*G.*M.*rho',
        r'GM\^2/R\^4',
        r'GMrho/R'
    ]

    has_scaling = any(re.search(pat, pred_clean, re.IGNORECASE) for pat in order_of_magnitude_patterns)

    # 如果使用了 Delta P 但没有体现出 R 的一致性缩放（例如分母阶数不对）
    if 'Delta' in prediction or 'delta' in prediction or 'd' in prediction:
        if not has_scaling:
            return {'result': 'fail', 'message': '建模中 Delta P / Delta r 的量级估计与几何尺度(R)不匹配或缺乏一致性推导', 'evidence': prediction[:200]}
        else:
            return {'result': 'pass', 'message': '量级估计符号与尺度对齐一致', 'evidence': '检测到符合物理尺度的近似公式'}

    return {'result': 'inconclusive', 'message': '无法确定量级估计的严谨性', 'evidence': ''}

# rule_id=norm_4c8db071328e5362 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_4c8db071328e5362 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_4c8db071328e5362_ee3002f0a041(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及不同温度、体积的气体在恒定压力下混合
    trigger_keywords = ['等压', '恒定压力', 'constant pressure', '混合', 'mixed', 'mixing']
    has_trigger = any(kw in (question + context) for kw in trigger_keywords)
    has_vars = all(sym in (question + context + prediction) for sym in ['T', 'V'])
    if not (has_trigger and has_vars):
        return {'result': 'inconclusive', 'message': '未检测到等压混合或必要的物理量(T, V)', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证质量/摩尔数比例是否遵循 m ∝ V/T
    # 错误逻辑通常是 m ∝ V*T 或直接忽略温度影响
    pred = prediction.replace(' ', '')
    # 匹配 m1/m2 = (V1/T1)/(V2/T2) 或 m1/m2 = (V1*T2)/(V2*T1) 的变体
    correct_pattern = r'(m1/m2|n1/n2).*(V1/T1)/(V2/T2)|(m1/m2|n1/n2).*(V1\*T2)/(V2\*T1)|m.*V/T'
    wrong_pattern = r'(m1/m2|n1/n2).*(V1\*T1)/(V2\*T2)|m.*V\*T'

    # Step 3: 判定结果
    if re.search(correct_pattern, pred, re.IGNORECASE) or re.search(r'PV=nRT', prediction):
        # 如果明确写出了 PV=nRT 并推导出 n=PV/RT，则视为通过
        if re.search(r'n\s*=\s*PV/RT|m\s*=\s*PV/RT', pred, re.IGNORECASE):
            return {'result': 'pass', 'message': '正确应用了等压下质量与V/T成正比的关系', 'evidence': prediction[:200]}

    if re.search(wrong_pattern, pred, re.IGNORECASE):
        return {'result': 'fail', 'message': '质量比例计算错误，错误地使用了V*T乘积关系而非V/T比值', 'evidence': prediction[:200]}

    # 检查是否缺失了温度对质量分布的影响
    if 'V1/V2' in pred and 'T1' in (question + context) and 'T1' not in pred:
         return {'result': 'fail', 'message': '在不同温度混合计算中忽略了温度项', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定比例计算的具体逻辑', 'evidence': ''}

# rule_id=norm_61bd8a5db8ecd775 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_61bd8a5db8ecd775 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_61bd8a5db8ecd775_93f34af50398(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及线性近似公式 (1-x)^-1 ≈ 1+x 或 H=a+bh 结构
    trigger_keywords = ['1+x', '1-x', '近似', 'linear approximation', 'H=a+bh']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到线性近似触发条件', 'evidence': ''}

    # Step 2: 检查 prediction 是否尝试建立线性关系并包含必要符号
    # 符号要求: H, P_atm (或 P0)
    required_symbols = ['H', 'P']
    pred_text = prediction
    missing_symbols = [s for s in required_symbols if s not in pred_text]
    if len(missing_symbols) > 1:
        return {'result': 'inconclusive', 'message': '预测中缺少必要的物理符号', 'evidence': f'缺失: {missing_symbols}'}

    # Step 3: 检查逻辑变形过程是否符合 H = H0(1 + rho*g*h/P) 的线性化结构
    # 匹配形如 1 + (rho*g*h/P) 或类似的线性项
    linear_pattern = r'1\s*[\+\-]\s*(\\frac\{.*?\}|[a-zA-Z0-9_\/\s\*]+h)'
    match = re.search(linear_pattern, pred_text)

    # 如果题目明确要求 H=a+bh 形式，检查 prediction 是否给出了斜率项与 h 的乘积
    if not match and 'h' not in pred_text:
        return {'result': 'fail', 'message': '未发现线性近似变形逻辑或自变量 h 的系数项', 'evidence': pred_text[:200]}

    # Step 4: 验证公式结构的合理性 (H_0 引导的 1+epsilon 形式)
    if re.search(r'H_?0?\s*\(\s*1\s*\+', pred_text) or re.search(r'H\s*=\s*.*h', pred_text):
        return {'result': 'pass', 'message': '线性近似公式结构匹配成功', 'evidence': match.group(0) if match else 'H=a+bh pattern found'}

    return {'result': 'inconclusive', 'message': '无法确定线性近似逻辑是否正确执行', 'evidence': pred_text[:100]}

# rule_id=norm_64b10fdf7097000f | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_64b10fdf7097000f | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_64b10fdf7097000f_fb4ccccb67c5(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及理想气体状态方程及比例推导场景
    trigger_keywords = ['proportional', 'ratio', '∝', '关系', '比例', '理想气体', 'ideal gas']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到理想气体比例推导场景', 'evidence': ''}

    # Step 2: 检查 prediction 中是否包含核心物理量符号 P, V, n, R, T
    required_symbols = ['P', 'V', 'n', 'R', 'T']
    missing_symbols = [s for s in required_symbols if s not in prediction]
    if len(missing_symbols) > 2:  # 允许少量符号缺失（如 R 为常数），但过多缺失则无法验证
        return {'result': 'inconclusive', 'message': '预测中缺乏足够的物理量符号进行量纲验证', 'evidence': prediction[:100]}

    # Step 3: 验证比例关系的代数结构是否符合 PV=nRT
    # 典型错误：n ∝ PT/V 或 n ∝ V/(PT) 等不符合 n = PV/RT 的结构
    # 匹配类似 n ∝ ... 或 n = ... 的表达式
    relation_pattern = re.search(r'n\s*[∝=~]\s*([^\n$]+)', prediction)
    if relation_pattern:
        expr = relation_pattern.group(1)
        # 如果 n 与 T 成正比（且 P, V 恒定），则违反 n = PV/RT (n ∝ 1/T)
        if re.search(r'[\*\s]T', expr) and not re.search(r'/.*T|T\^-1', expr):
            return {'result': 'fail', 'message': '摩尔数 n 与温度 T 的比例关系不符合 PV=nRT (应为反比)', 'evidence': relation_pattern.group(0)}
        # 如果 n 与 P 或 V 成反比，则违反 n = PV/RT
        if re.search(r'/.*[PV]', expr):
            return {'result': 'fail', 'message': '摩尔数 n 与压强 P 或体积 V 的比例关系不符合 PV=nRT (应为正比)', 'evidence': relation_pattern.group(0)}

    # Step 4: 检查是否存在明显的量纲不一致（如 P*T = V*n）
    if re.search(r'P\s*\*?\s*T\s*=\s*V\s*\*?\s*n', prediction, re.IGNORECASE):
        return {'result': 'fail', 'message': '检测到错误的物理量组合结构 (P*T=V*n)', 'evidence': 'P*T=V*n'}

    if re.search(r'P\s*V\s*=\s*n\s*R\s*T|n\s*=\s*P\s*V\s*/\s*\(?R\s*T\)?', prediction):
        return {'result': 'pass', 'message': '比例关系符合理想气体状态方程结构', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定比例关系的量纲正确性', 'evidence': ''}

# rule_id=norm_6aa2caa46a8a57b5 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_6aa2caa46a8a57b5 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_6aa2caa46a8a57b5_cd80cd427973(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及U型管、多歧管及多段封闭气体
    trigger_keywords = ['U型管', 'U形管', '多歧管', '连通器', '封闭气柱', '两端封闭', '左管', '右管']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多支封闭气柱场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否错误假设各支管末态压强相等
    # 如果解题过程中直接令 P_left = P_right 而忽略了液柱高度差导致的压强平衡方程，则视为错误
    pred_lower = prediction.lower()
    if re.search(r'假设.*压强相等', prediction) or re.search(r'p_?左\s*=\s*p_?右', pred_lower):
        if not re.search(r'\+\s*ρgh|\+\s*h', pred_lower):
            return {'result': 'fail', 'message': '错误假设各支管末态气压相等，未考虑液柱压强差', 'evidence': '检测到压强相等假设且缺乏高度差修正'}

    # Step 3: 符号与公式校验 — 检查是否对每路气柱应用玻意耳定律 (P1V1=P2V2) 并建立平衡方程
    # 检查是否包含 P*V 或 P*L 的乘积形式，以及平衡方程结构
    boyle_pattern = r'P_?\d?V_?\d?\s*=\s*P_?\d?V_?\d?|P_?\d?L_?\d?\s*=\s*P_?\d?L_?\d?'
    balance_pattern = r'P_?.*[=≈].*P_?.*[\+\-]'

    has_boyle = re.search(boyle_pattern, prediction, re.IGNORECASE) or '玻意耳' in prediction
    has_balance = re.search(balance_pattern, prediction, re.IGNORECASE) or '平衡' in prediction

    if not has_boyle:
        return {'result': 'fail', 'message': '未对各支气柱分别应用玻意耳定律', 'evidence': prediction[:200]}

    if not has_balance:
        return {'result': 'fail', 'message': '未通过底部连通处建立压强平衡方程', 'evidence': prediction[:200]}

    # Step 4: 验证符号覆盖 (L, P_initial, h)
    required_symbols = ['L', 'P', 'h']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction or sym.lower() in prediction)
    if symbol_count >= 2:
        return {'result': 'pass', 'message': '已正确应用独立关联律并建立平衡方程', 'evidence': '符合玻意耳定律应用与压强平衡逻辑'}

    return {'result': 'inconclusive', 'message': '推理过程不完整，无法判定', 'evidence': ''}

# rule_id=norm_6ca9224e323edf05 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_6ca9224e323edf05 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_6ca9224e323edf05_3f185691a6c5(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题干或上下文中是否给出了具体的数值赋值（如 n=2.51 或 T=300K）
    # 匹配类似 字母=数字 的模式，排除常见的单位或序号
    val_patterns = re.findall(r'([a-zA-Z])\s*=\s*(\d+\.?\d*)', question + context)
    if not val_patterns:
        return {'result': 'inconclusive', 'message': '题干未检测到明确的数值赋值列表', 'evidence': ''}

    # Step 2: 检查逻辑 — 扫描推导过程（prediction），确认这些符号是否被使用
    # 提取推导中出现的物理符号（简单字母匹配）
    pred_content = prediction
    unused_symbols = []
    for symbol, value in val_patterns:
        # 检查符号是否在推导中出现（作为独立单词或公式一部分）
        if not re.search(r'\b' + re.escape(symbol) + r'\b', pred_content):
            unused_symbols.append(f"{symbol}={value}")

    # Step 3: 判定结果 — 若存在未使用的已知物理量，则可能遗漏了关键约束
    if unused_symbols:
        return {
            'result': 'fail',
            'message': f'推导过程中未发现题干给出的关键参数: { ", ".join(unused_symbols) }，可能遗漏了物理模型约束。',
            'evidence': f'检测到未使用参数: {unused_symbols}; 推导片段: {prediction[:200]}'
        }

    # 如果所有参数都出现了，或者推导非常简略无法判定，返回 inconclusive 或 pass
    if len(val_patterns) > 0 and not unused_symbols:
        return {'result': 'pass', 'message': '题干给出的数值参数在推导中均有体现', 'evidence': str(val_patterns)}

    return {'result': 'inconclusive', 'message': '无法确定参数使用情况', 'evidence': ''}

# rule_id=norm_7e8ee06f38e04270 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_7e8ee06f38e04270 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_7e8ee06f38e04270_3fba28f38187(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否限定使用 P0, V0, R 表达且未提及摩尔数 n
    trigger_keywords = ['用参数', '表达', 'P0', 'V0', 'R']
    is_triggered = all(kw in question for kw in ['P_0', 'V_0', 'R']) or all(kw in question for kw in ['P0', 'V0', 'R'])
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '题目未明确限定使用 P0, V0, R 表达', 'evidence': question[:100]}

    if '摩尔数' in question or ' n ' in question or '物质的量' in question:
        return {'result': 'inconclusive', 'message': '题目中已提及摩尔数，不适用此约束检查', 'evidence': question[:100]}

    # Step 2: 检查 prediction 最终表达式是否包含未定义的自由变量 n
    # 提取预测结果中的最后公式部分（通常在 "=" 之后或最后一行）
    pred_lines = prediction.strip().split('\n')
    last_line = pred_lines[-1] if pred_lines else ''

    # 检查是否包含 n，且 n 不是作为单位或上下文的一部分
    # 匹配独立的变量 n (前后非字母数字)
    has_n = re.search(r'[^a-zA-Z]n[^a-zA-Z]', ' ' + last_line + ' ')

    # Step 3: 检查是否包含必须的符号 P0, V0, R
    has_required = all(re.search(rf'{s}', last_line) for s in ['P_?0', 'V_?0', 'R'])

    if has_n:
        # 检查是否在推理过程中消去了 n，或者设定了 n=1
        if 'n=1' in prediction or 'n = 1' in prediction or '消去' in prediction:
            return {'result': 'pass', 'message': '虽然包含n但有消去或设为1的逻辑', 'evidence': last_line}
        else:
            return {'result': 'fail', 'message': '最终表达式包含未给出的自由变量 n，且未见消去逻辑', 'evidence': last_line}

    if has_required:
        return {'result': 'pass', 'message': '表达式符合参数约束一致性', 'evidence': last_line}

    return {'result': 'inconclusive', 'message': '无法确定表达式是否完全符合约束', 'evidence': last_line}

# rule_id=norm_82edb3881635614f | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_82edb3881635614f | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_82edb3881635614f_1d7ac799e731(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及线性拟合、实验方程或系数求解
    trigger_keywords = ['拟合', '方程', '斜率', '截距', 'y=', 'k=', 'b=', 'linear fit', 'slope', 'intercept']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到线性拟合或系数映射场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 预测中是否包含物理公式推导与系数对等过程 (Matching coefficients)
    pred_lower = prediction.lower()
    # 检查是否提到了将物理公式变形为线性形式，或直接提到斜率/截距的物理意义
    logic_keywords = ['对应', '映射', '等效', '比较', '系数', 'slope is', 'intercept is', 'matching']
    has_logic = any(kw in pred_lower for kw in logic_keywords)

    # 检查是否包含 symbolic_hint 中的关键符号或结构 (如 H, a, b)
    has_symbols = all(sym in prediction for sym in ['a', 'b']) or 'H' in prediction

    if not has_logic:
        return {
            'result': 'fail',
            'message': '预测未展示从物理定律推导解析表达式并进行系数对等的过程',
            'evidence': prediction[:200]
        }

    # Step 3: 检查公式结构 (针对 H = H_0(1 + ρgh/P_0) 类型的线性化处理)
    # 查找类似 y = ax + b 或 y = kx + b 的结构，以及物理量与系数的关联
    formula_pattern = re.compile(r'([abk])\s*=\s*[^\n]+', re.IGNORECASE)
    if not formula_pattern.search(prediction):
        return {
            'result': 'fail',
            'message': '预测中缺失系数(a, b, k)的具体物理表达式定义',
            'evidence': prediction[:200]
        }

    # 如果逻辑和符号匹配都存在，则认为通过
    if has_logic and has_symbols:
        return {
            'result': 'pass',
            'message': '成功执行了物理公式到线性方程的映射与系数求解',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '证据不足以判定映射逻辑的完整性', 'evidence': ''}

# rule_id=norm_874075e387c7fff6 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_874075e387c7fff6 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_874075e387c7fff6_5428fbdbeb29(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题干是否明确要求结果需用特定参数列表表示
    # 匹配如 "用...表示", "in terms of", "expressed by" 等描述
    trigger_keywords = ['用', '表示', 'in terms of', 'expressed by', '参数', '变量']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到明确的变量约束要求', 'evidence': ''}

    # Step 2: 提取允许的符号集合 (基于 symbolic_hint 和题干)
    # 预设符号集: p0, Vr, T0, R, N, k, ell, x
    allowed_symbols = {'p0', 'Vr', 'T0', 'R', 'N', 'k', 'ell', 'x', 'p_0', 'V_r', 'T_0', 'l'}
    required_symbols = ['N', 'k']

    # Step 3: 检查 prediction 中的最终表达式是否包含非法符号
    # 寻找类似 "结果为", "=", "Ans:" 之后的表达式部分
    final_expr_match = re.search(r'(=|结果|答案|is|:)\s*([^\n。]+)', prediction)
    if not final_expr_match:
        return {'result': 'inconclusive', 'message': '未能定位最终表达式', 'evidence': ''}

    final_expr = final_expr_match.group(2)

    # 检查是否包含必须出现的符号 (N, k)
    missing_required = [s for s in required_symbols if s not in prediction]
    if missing_required:
        return {'result': 'fail', 'message': f'最终结果缺失必要参数: {missing_required}', 'evidence': final_expr}

    # 检查是否包含不应出现的中间变量 (如 A, L, M 等大写字母，且不在允许列表中)
    # 排除常见的数学常数和允许符号
    potential_illegal = re.findall(r'\b[A-Z][a-z0-9]*\b', final_expr)
    for sym in potential_illegal:
        if sym not in allowed_symbols and sym not in ['P', 'V', 'T']: # 允许基本态变量
            # 如果出现了 A 或 L 这种几何变量且未被消去
            if sym in ['A', 'L', 'S', 'H']:
                return {'result': 'fail', 'message': f'结果中包含未消去的中间变量: {sym}', 'evidence': final_expr}

    # Step 4: 验证符号覆盖情况
    if any(s in prediction for s in required_symbols):
        return {'result': 'pass', 'message': '结果符合变量约束要求', 'evidence': final_expr}

    return {'result': 'inconclusive', 'message': '无法确定变量是否完全合规', 'evidence': final_expr}

# rule_id=norm_ac014c0d6c1255b0 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_ac014c0d6c1255b0 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_ac014c0d6c1255b0_8e919ebb89b5(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及范德华方程(Van der Waals)及液相体积(V_L)求解
    trigger_keywords = ['范德华', 'Van der Waals', 'VdW', '液相', 'liquid phase', 'V_L', '体积根']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到范德华方程液相体积求解场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否选择了减号分支以使体积接近 b
    # 典型公式结构为 [a - sqrt(a^2 - 4RTab)] / 2RT 或类似形式，核心在于 sqrt 前的负号
    pred_lower = prediction.lower()

    # 检查是否提到了判别式或求根公式中的符号选择
    has_minus_sign = re.search(r'(-\s*\\sqrt|\-\s*sqrt|取减号|负号分支)', pred_lower)
    has_plus_sign = re.search(r'(\+\s*\\sqrt|\+\s*sqrt|取加号|正号分支)', pred_lower)

    # 如果明确选择了正号分支，则违反了液相根选择规则（正号通常对应气相根）
    if has_plus_sign and not has_minus_sign:
        return {'result': 'fail', 'message': '液相体积根应选择减号分支以趋向于 b，预测中错误选择了正号', 'evidence': prediction[:200]}

    # Step 3: 符号覆盖与公式结构校验
    # 检查是否包含关键物理量 a, b, R, T
    required_symbols = ['a', 'b', 'R', 'T']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    # 检查泰勒展开或极限行为的描述 (V -> b)
    has_limit_logic = re.search(r'(泰勒|Taylor|极限|limit|趋于\s*b|approaches\s*b)', pred_lower)

    if has_minus_sign and (not missing_symbols or has_limit_logic):
        return {'result': 'pass', 'message': '正确选择了减号分支并符合液相体积的物理极限逻辑', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '未能明确识别求根符号选择或极限验证逻辑', 'evidence': ''}

# rule_id=norm_b7fa9e17dde6b48e | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_b7fa9e17dde6b48e | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_b7fa9e17dde6b48e_256a98cd97a3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及非理想气体（或已知u, p）推导熵s或绝热方程
    trigger_keywords = ['内能', '压强', '熵', '绝热', 'u(T, v)', 'p(T, v)', 'entropy', 'adiabatic']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到非理想气体熵推导场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否从热力学第一定律 ds = (1/T)du + (p/T)dv 出发并展开 du
    pred = prediction.lower()
    # 检查是否包含第一定律微分形式的核心项
    has_first_law = 'ds' in pred and ('du' in pred or 'dq' in pred) and ('dv' in pred or 'pdv' in pred)
    # 检查是否对 du 进行了偏导展开 (du = (du/dT)dT + (du/dv)dv)
    has_du_expansion = re.search(r'du\s*=\s*.*dt.*dv', pred) or ('du/dt' in pred and 'du/dv' in pred)

    # 检查是否错误地直接套用了理想气体公式 (如 ds = Cv*dT/T + R*dv/v)
    # 理想气体公式通常包含 R/v 或 nR/v，而非通用的 p/T 或 (du/dv+p)/T
    has_ideal_gas_shortcut = re.search(r'r/v|nr/v', pred) and not ('du/dv' in pred or 'p/t' in pred)

    if not has_first_law:
        return {'result': 'fail', 'message': '未从热力学第一定律微分形式出发', 'evidence': prediction[:200]}

    if not has_du_expansion and 'du' in pred:
         return {'result': 'fail', 'message': '未对内能微分 du 进行全微分展开', 'evidence': prediction[:200]}

    # Step 3: 符号覆盖与结构校验
    # 检查 canonical 形式: ds = (Cv/T)dT + [(du/dv + p)/T]dv
    # 匹配特征：(du/dv + p)/T 或类似的组合项
    canonical_pattern = r'\(\s*.*du/.*dv.*\+.*p.*\)\s*/\s*t'
    if re.search(canonical_pattern, pred) or ('cv/t' in pred and 'p/t' in pred and 'du/dv' in pred):
        return {'result': 'pass', 'message': '符合非理想气体熵微分构造准则', 'evidence': prediction[:200]}

    if has_ideal_gas_shortcut:
        return {'result': 'fail', 'message': '严禁直接套用理想气体熵公式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推导过程不完整或证据不足', 'evidence': ''}

# rule_id=norm_b8b4ed0ae38a371b | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_b8b4ed0ae38a371b | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_b8b4ed0ae38a371b_8af3c027facb(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否包含玻璃管、液柱、封闭气柱、大气压等场景
    trigger_keywords = ['玻璃管', '液柱', '水银柱', '封闭气柱', '大气压', '管口', '倒置', 'h']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到变质量/体积封闭气体建模场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须联立理想气体状态方程 (PV=nRT 或 P1V1=P2V2) 与力学平衡方程 (P=P0±ρgh)
    pred = prediction.lower()
    # 检查是否包含理想气体状态方程的变形或符号组合
    has_gas_law = re.search(r'p[1v]|pv\s*=|p_0\s*\*\s*v', pred) or '理想气体' in pred
    # 检查是否包含压强平衡方程 (P0 + h 或 P0 - h 或 rho*g*h)
    has_pressure_balance = re.search(r'p_0\s*[\+\-]\s*[\rhogh]', pred) or re.search(r'p_0\s*[\+\-]\s*h', pred)

    if not has_gas_law:
        return {'result': 'fail', 'message': '未体现理想气体状态方程(PV=nRT)的应用', 'evidence': prediction[:200]}

    if not has_pressure_balance:
        return {'result': 'fail', 'message': '未建立气体压强与大气压、液柱高度的力学平衡关系(P=P0±h)', 'evidence': prediction[:200]}

    # Step 3: 符号覆盖检查 (P_0, V, h)
    required_symbols = ['p_0', 'v', 'h']
    missing_symbols = [s for s in required_symbols if s not in pred]
    if len(missing_symbols) > 1:
        return {'result': 'fail', 'message': f'缺少关键物理量符号: {missing_symbols}', 'evidence': prediction[:200]}

    # Step 4: 检查是否错误地仅使用了几何长度相加而忽略了压强变化
    if re.search(r'l_1\s*\+\s*l_2\s*=\s*l', pred) and not has_pressure_balance:
        return {'result': 'fail', 'message': '错误地使用了几何长度简单相加，未考虑压强平衡', 'evidence': prediction[:200]}

    return {'result': 'pass', 'message': '已正确联立状态方程与力学平衡方程', 'evidence': prediction[:200]}

# rule_id=norm_bee9974569a1471f | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
# rule_id=norm_bee9974569a1471f | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_norm_bee9974569a1471f_15757595507d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及等温压缩过程中的压强变化
    trigger_keywords = ['等温', 'isothermal', '压缩', 'compress', '压强', 'pressure']
    q_c_text = (question + context).lower()
    if not all(k in q_c_text for k in ['压强']) or not any(k in q_c_text for k in ['等温', 'isothermal']):
        return {'result': 'inconclusive', 'message': '未检测到等温压缩压强计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 校验是否错误地使用了线性高度差公式 ρgh
    # 如果 prediction 中出现了 Delta P = rho * g * h 且未体现 P1V1=P2V2 关系，则判定为概念错误
    pred_lower = prediction.lower()
    rho_gh_pattern = r'rho\s*g\s*h|\u03c1gh|p\s*=\s*\u03c1gh'
    isothermal_law_pattern = r'p_?1\s*v_?1\s*=\s*p_?2\s*v_?2|p_?2\s*=\s*p_?1\s*\*\s*\(v_?1\s*/\s*v_?2\)|p_?2\s*=\s*p_?1\s*\*\s*\(l_?1\s*/\s*l_?2\)'

    # 如果预测中使用了 rho*g*h 来直接计算等温压缩后的压强增量，且没有体现玻意耳定律
    if re.search(rho_gh_pattern, pred_lower) and not re.search(isothermal_law_pattern, pred_lower):
        return {
            'result': 'fail',
            'message': '错误地将等温压缩压强增量关联为线性高度差 rho*g*h，未应用玻意耳定律',
            'evidence': re.search(rho_gh_pattern, prediction).group(0) if re.search(rho_gh_pattern, prediction) else prediction[:100]
        }

    # Step 3: 符号与公式校验 — 检查是否正确使用了 P2 = P1 * (L1 / L2) 或类似形式
    if re.search(isothermal_law_pattern, pred_lower):
        return {'result': 'pass', 'message': '正确应用了等温过程压强与体积/长度的反比关系', 'evidence': '检测到符合 P1V1=P2V2 的逻辑结构'}

    return {'result': 'inconclusive', 'message': '无法确定压强计算逻辑是否正确', 'evidence': ''}

# rule_id=norm_0131c8923eef3f21 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_0131c8923eef3f21 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_0131c8923eef3f21_849ddfb0c99e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及湿空气混合及凝结/雾化场景
    trigger_keywords = ['湿空气', '混合', '凝结', '雾', 'fog', 'condensation', 'humid air', 'mixing']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到湿空气混合或凝结相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证 prediction 是否包含潜热项 (L, q, h_fg, 潜热) 的能量平衡
    pred = prediction.lower()
    latent_heat_terms = ['潜热', 'latent heat', 'h_fg', ' L ', '*L', 'q_l', 'enthalpy of vaporization']
    # 检查是否仅使用了显热公式 (cp*deltaT)
    has_latent_term = any(term in pred for term in latent_heat_terms) or re.search(r'[Lq]\s*\*?\s*m', pred)

    # Step 3: 符号与公式结构校验
    # 检查是否包含 cp, m_v (或类似质量项) 以及能量守恒的等式特征
    required_symbols = ['cp', 'm']
    has_symbols = all(sym in pred for sym in required_symbols)

    if not has_latent_term:
        # 如果只看到显热平衡而没有潜热项，判定为建模错误
        if 'cp' in pred and ('=' in pred or 'balance' in pred):
            return {
                'result': 'fail',
                'message': '在涉及凝结的混合过程中缺失潜热项 (L*Δm)，仅使用了显热平衡。',
                'evidence': prediction[:200]
            }
        return {'result': 'inconclusive', 'message': '无法确定能量方程是否完整', 'evidence': ''}

    if has_latent_term and has_symbols:
        return {
            'result': 'pass',
            'message': '能量平衡方程已包含潜热项，符合相变混合建模要求。',
            'evidence': re.search(r'.{0,50}[Lq].{0,50}', pred).group(0) if re.search(r'[Lq]', pred) else ''
        }

    return {'result': 'inconclusive', 'message': '证据不足以判定能量守恒完整性', 'evidence': ''}

# rule_id=norm_2215dcfa66da2d88 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_2215dcfa66da2d88 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_2215dcfa66da2d88_b61a4f3a0408(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及水与水蒸气热平衡、等压加热、体积增加
    trigger_keywords = ['水', '水蒸气', '热平衡', '等压', '体积增加', '膨胀']
    q_c = (question + context).lower()
    if not (('水' in q_c and '蒸气' in q_c) or '热平衡' in q_c):
        return {'result': 'inconclusive', 'message': '未检测到水气热平衡场景', 'evidence': ''}
    if not ('等压' in q_c and ('体积' in q_c or '膨胀' in q_c)):
        return {'result': 'inconclusive', 'message': '未检测到等压膨胀过程', 'evidence': ''}

    # Step 2: 检查逻辑 — 判定是否优先考虑相变（潜热）而非单纯气体膨胀
    pred = prediction.lower()
    # 检查是否提到潜热、汽化热或相变过程
    latent_heat_keywords = ['潜热', '汽化热', '相变', '汽化', '蒸发', 'L', 'm_vap']
    has_latent_logic = any(kw in pred for kw in latent_heat_keywords)

    # 检查是否错误地仅使用理想气体状态方程或单纯的热膨胀公式 (如仅有 nCpΔT 或 V/T=C)
    # 如果只谈论温度升高导致的体积增加，而忽略了等压下相变吸收热量，则判定为建模错误
    if not has_latent_logic:
        return {'result': 'fail', 'message': '在气液共存等压加热中未优先考虑相变潜热消耗', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查是否包含 Q = mL 或类似的能量守恒结构
    # 匹配 L (潜热符号) 或 m_vap (汽化质量)
    symbol_pattern = r'(L|m_\{?vap\}?|\Delta H)'
    if re.search(symbol_pattern, prediction):
        return {'result': 'pass', 'message': '已正确识别相变潜热逻辑并包含相关符号', 'evidence': re.search(symbol_pattern, prediction).group(0)}

    if 'L' in prediction or '汽化' in prediction:
        return {'result': 'pass', 'message': '逻辑中包含相变描述', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '逻辑模糊，无法确定是否正确处理相变', 'evidence': ''}

# rule_id=norm_2fdd8204d06ed5f5 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_2fdd8204d06ed5f5 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_2fdd8204d06ed5f5_14cff95d1bdf(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否存在多个容器或气团及其状态参数（如 V1, V2, T1, T2）
    # 匹配类似 V1, V_1, T1, T_2, rho1 等模式
    trigger_pattern = r'([VvTtPp]|rho)[_]?([12])'
    q_matches = re.findall(trigger_pattern, question + context)
    # 需要至少出现两个不同的下标或两个不同的物理量组合
    if len(set(q_matches)) < 2:
        return {'result': 'inconclusive', 'message': '未检测到多个状态参数的混合计算场景', 'evidence': ''}

    # Step 2: 提取题干中的初始定义映射（例如 V1 对应 T1，V2 对应 T2）
    # 寻找形如 "V1=...T1" 或 "V1...T1" 在同一句中的关联
    # 简单起见，检查 prediction 中是否存在交叉误用的迹象，如 V1 与 T2 错误配对（若题干定义是 1-1, 2-2）
    pred_text = prediction

    # Step 3: 检查逻辑 — 核对下标组合一致性
    # 寻找常见的混合公式，如 (P1*V1)/T1 = (P2*V2)/T2 或 P=(P1V1+P2V2)/(V1+V2)
    # 如果发现类似 V1*T2 或 V2*T1 且题干中 1和2 是独立实体，则可能存在交叉误用
    # 这里的逻辑是：如果在同一项中出现了不属于同一实体的下标（保守检查）

    # 检查是否存在明显的下标混淆，例如在计算总内能或混合状态时，下标 1 的体积乘了下标 2 的温度
    # 匹配模式：变量1+下标1 紧跟 变量2+下标2 (且下标不同)
    cross_usage = re.search(r'([VvTtPp]|rho)[_]?1.*([VvTtPp]|rho)[_]?2', pred_text)
    # 这种匹配较泛，需结合具体物理公式。热力学中 V1*T2 常见于某些过程，但 V1*P2/T1 可能是错的。

    # 更加严谨的检查：如果在 prediction 中完全没有出现下标区分，但在 question 中有，则视为缺失要素
    if not re.search(trigger_pattern, pred_text):
        return {'result': 'fail', 'message': '计算步骤中未按题干定义使用下标区分不同实体的状态参数', 'evidence': pred_text[:200]}

    # 检查是否存在下标在同一表达式中无理交叉（如 V1 与 T2 直接相乘且无比例关系）
    # 这是一个保守的启发式检查
    if re.search(r'V_?1.*T_?2', pred_text) and not re.search(r'V_?2.*T_?2', pred_text):
         if "mixed" in (question + pred_text).lower() or "混合" in (question + pred_text):
             # 混合计算中若只出现交叉项而无对应项，风险较高
             return {'result': 'inconclusive', 'message': '检测到可能的下标交叉使用，需人工核实映射一致性', 'evidence': re.findall(r'.{0,20}V_?1.*T_?2.{0,20}', pred_text)[:1]}

    return {'result': 'pass', 'message': '状态参数下标使用基本符合实体映射', 'evidence': ''}

# rule_id=norm_34e4e06c89e01c7b | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_34e4e06c89e01c7b | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_34e4e06c89e01c7b_12307aa576f4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及液体在容器中受热膨胀，且给出线性膨胀系数 alpha 和体膨胀系数 beta
    full_text = (question + context).lower()
    trigger_keywords = ['膨胀', 'expansion', '容器', 'container', 'vessel']
    has_alpha = re.search(r'[αα]|alpha|线性膨胀', full_text)
    has_beta = re.search(r'[ββ]|beta|体膨胀', full_text)

    if not (any(kw in full_text for kw in trigger_keywords) and has_alpha and has_beta):
        return {'result': 'inconclusive', 'message': '未检测到液体在容器中受热膨胀及相关系数场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须考虑容器横截面积的膨胀（面膨胀系数 2alpha）
    pred = prediction.lower()
    # 检查是否提到了容器面积的变化或 2*alpha 的逻辑
    area_expansion_logic = re.search(r'2\s*[αα]|2\s*alpha|面积膨胀|面膨胀', pred)

    # Step 3: 公式结构校验 — 检查是否使用了 Δh = h0 * (β - 2α) * ΔT 的逻辑结构
    # 匹配类似 (beta - 2*alpha) 或 beta - 2alpha 的模式
    formula_pattern = re.search(r'[ββ]\s*-\s*2\s*[αα]|beta\s*-\s*2\s*alpha', pred)

    if not area_expansion_logic and not formula_pattern:
        # 如果预测中直接忽略了容器膨胀，仅使用 ΔV/A0，则判定为建模错误
        if re.search(r'Δh\s*=\s*ΔV\s*/\s*A', prediction) or 'delta v / a' in pred:
            return {'result': 'fail', 'message': '未考虑容器横截面积的膨胀，应使用 Δh = h0(β - 2α)ΔT', 'evidence': prediction[:200]}
        return {'result': 'inconclusive', 'message': '预测中未明确展示高度变化的计算逻辑', 'evidence': ''}

    if formula_pattern:
        return {'result': 'pass', 'message': '正确考虑了容器面膨胀对液柱高度的影响', 'evidence': '检测到公式结构: ' + str(formula_pattern.group())}

    return {'result': 'inconclusive', 'message': '逻辑提及但公式不完整', 'evidence': prediction[:200]}

# rule_id=norm_5596801a5b735eec | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_5596801a5b735eec | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_5596801a5b735eec_c8e6632a7eef(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及冰水混合且要求讨论所有可能情况
    q_ctx = (question + context).lower()
    trigger_keywords = ['final temperature', 'all possible', 'scenario', 'case', '冰', '水', 'ice', 'water']
    if not (('ice' in q_ctx or '冰' in q_ctx) and ('water' in q_ctx or '水' in q_ctx)):
        return {'result': 'inconclusive', 'message': '未检测到冰水混合场景', 'evidence': ''}

    is_comprehensive = any(kw in q_ctx for kw in ['all possible', 'scenario', '所有可能', '讨论', '情况'])
    if not is_comprehensive:
        return {'result': 'inconclusive', 'message': '题目未明确要求全域覆盖讨论', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须检查热量临界点（升温、熔化、降温、凝固）
    pred = prediction.lower()
    # 检查冰升温/熔化相关要素
    ice_logic = ('c_ice' in pred or 'specific heat of ice' in pred or '冰的比热' in pred) and \
                ('latent heat' in pred or 'fusion' in pred or '熔化热' in pred or 'L' in pred)
    # 检查水降温/结冰相关要素
    water_logic = ('c_water' in pred or 'specific heat of water' in pred or '水的比热' in pred)

    # 检查是否对比了 Q_ice 和 Q_water 的临界值
    critical_points = ['0' in pred or '273' in pred]

    missing_elements = []
    if not ice_logic:
        missing_elements.append("冰的升温或熔化热计算")
    if not water_logic:
        missing_elements.append("水的降温放热计算")

    if missing_elements:
        return {
            'result': 'fail',
            'message': f'推理过程中缺失关键热量临界点分析: {", ".join(missing_elements)}',
            'evidence': prediction[:200]
        }

    # Step 3: 符号与公式结构校验
    # 检查是否包含 m*c*deltaT 或 m*L 结构的公式
    formula_pattern = re.search(r'(m.*c.*delta|m.*L|Q.*=.*m)', prediction, re.IGNORECASE)
    if formula_pattern:
        return {'result': 'pass', 'message': '已包含相变平衡态所需的关键热量计算与分类讨论', 'evidence': formula_pattern.group(0)}

    return {'result': 'inconclusive', 'message': '逻辑步骤尚可，但未见明确的公式化临界点对比', 'evidence': ''}

# rule_id=norm_68ab223736b4c453 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_68ab223736b4c453 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_68ab223736b4c453_9ef59b970301(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及饱和蒸汽压、含湿量或湿度计算，且未给出具体数值
    keywords = ['饱和蒸汽压', '含湿量', '饱和压力', '相对湿度', 'saturated vapor pressure', 'humidity ratio']
    is_relevant = any(kw in (question + context) for kw in keywords)
    # 检查题目是否已经给出了具体的饱和压力数值（如 P_s = ...）
    has_given_data = re.search(r'([Pp]_s|饱和压|P_sat).*?\d+', question + context)

    if not is_relevant or has_given_data:
        return {'result': 'inconclusive', 'message': '题目已提供数据或不涉及饱和参数计算', 'evidence': ''}

    # Step 2: 检查逻辑 — 预测中是否提到了查表、Antoine方程或计算饱和压力的公式
    pred = prediction.lower()
    lookup_keywords = ['查表', 'antoine', '安托万', '经验公式', '饱和压力公式', 'table', 'formula for p_s']
    has_lookup_logic = any(kw in pred for kw in lookup_keywords)

    # 检查是否随意假设了初始湿度（如直接设为100%或0.5而无依据）
    arbitrary_assumption = re.search(r'(假设|设|assume).*?(湿度|phi).*?为?\s*\d+', pred)

    # Step 3: 综合判定
    if has_lookup_logic:
        return {'result': 'pass', 'message': '正确识别需要通过查表或公式获取饱和参数', 'evidence': re.search(r'.{0,30}(查表|antoine|公式).{0,30}', pred, re.I).group() if has_lookup_logic else ''}

    if arbitrary_assumption and not has_lookup_logic:
        return {'result': 'fail', 'message': '未通过查表或公式获取饱和参数，而是随意假设了湿度数据', 'evidence': arbitrary_assumption.group()}

    return {'result': 'inconclusive', 'message': '未明确显示饱和参数的获取来源', 'evidence': ''}

# rule_id=norm_69e0b7182f288319 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_69e0b7182f288319 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_69e0b7182f288319_0dce5148b2a4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及饱和蒸气（water vapor）在恒温（沸点/等温）下的压缩过程
    trigger_keywords = ['water vapor', 'steam', '水蒸气', '饱和蒸气']
    is_vapor = any(kw in (question + context).lower() for kw in trigger_keywords)
    is_compression = any(kw in (question + context).lower() for kw in ['compress', '压缩', 'volume decrease'])
    is_isothermal = any(kw in (question + context).lower() for kw in ['isothermal', 'constant temperature', '等温', '373k', '100℃'])

    if not (is_vapor and is_compression and is_isothermal):
        return {'result': 'inconclusive', 'message': '未检测到饱和蒸气等温压缩场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 压强是否被错误地视为变量（理想气体路径）而非恒定的 P_sat
    # 如果 prediction 中使用了 nRT ln(V2/V1) 或类似的变压功公式，则违反规则
    pred_lower = prediction.lower()
    wrong_path_patterns = [r'nrt\s*ln', r'p1v1\s*ln', r'\int\s*p\s*dv', r'p\s*varies']
    for pattern in wrong_path_patterns:
        if re.search(pattern, pred_lower):
            return {'result': 'fail', 'message': '错误地使用了理想气体变压功公式，饱和蒸气等温压缩应使用恒压功公式', 'evidence': re.search(pattern, pred_lower).group()}

    # Step 3: 符号/公式校验 — 检查是否包含 P*deltaV 或 P_sat 相关的功计算结构
    # 匹配 P*deltaV, P*dV, P*(V2-V1) 等结构
    correct_logic_patterns = [
        r'p_{?sat}?.*\\cdot.*\\delta\s*v',
        r'p.*\(v_?2\s*-\s*v_?1\)',
        r'w\s*=\s*p\s*\\delta\s*v',
        r'压强保持不变',
        r'constant\s*pressure'
    ]

    found_correct = False
    for pattern in correct_logic_patterns:
        if re.search(pattern, pred_lower):
            found_correct = True
            break

    if found_correct:
        return {'result': 'pass', 'message': '正确识别了等温压缩过程中的恒压特性及功计算方法', 'evidence': '检测到符合 P*deltaV 的逻辑描述'}

    return {'result': 'inconclusive', 'message': '无法确定功的计算路径是否正确', 'evidence': prediction[:200]}

# rule_id=norm_78abb3046f473ead | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_78abb3046f473ead | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_78abb3046f473ead_d69d2114f9d9(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及范德华力模型下的汽化潜热求解
    trigger_keywords = ['范德华', 'van der Waals', 'vdW', '汽化潜热', 'latent heat', 'phase transition']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到范德华相变或汽化潜热相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 潜热是否关联到内能引力项 a/V 的积分或差值
    # 核心逻辑：L ≈ ΔU ≈ a/V_L - a/V_G，且在 V_L ≈ b 时 ΔU ≈ a/b
    pred_lower = prediction.lower()
    logic_patterns = [
        r'a/v',
        r'a/b',
        r'\\int.*a/v\^2',
        r'internal energy.*attraction',
        r'内能.*引力'
    ]

    has_logic = any(re.search(p, pred_lower) for p in logic_patterns)

    # Step 3: 符号覆盖检查 (a, b, V)
    required_symbols = ['a', 'b', 'V']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    if not has_logic:
        return {
            'result': 'fail',
            'message': '模型缺失关键物理关联：未体现潜热主要克服内能引力项 (a/V) 的逻辑',
            'evidence': prediction[:200]
        }

    # Step 4: 检查公式结构是否符合 L ≈ a/b 或积分形式
    if re.search(r'a/b', prediction) or re.search(r'a/V_L', prediction) or re.search(r'a/V\^2', prediction):
        return {
            'result': 'pass',
            'message': '正确建立了潜热与范德华引力项的能量关联',
            'evidence': re.findall(r'.{0,30}(?:a/b|a/V|a/V\^2).{0,30}', prediction)[0] if 'a' in prediction else ''
        }

    return {'result': 'inconclusive', 'message': '检测到相关讨论但公式表达不完整', 'evidence': prediction[:150]}

# rule_id=norm_95fbe239f6e2b675 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_95fbe239f6e2b675 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_95fbe239f6e2b675_7bb3ca6f73bd(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“Find the final temperature”且包含冰水混合场景
    trigger_keywords = ['final temperature', 'equilibrium temperature', '终温', '最终温度']
    phase_keywords = ['ice', 'water', 'melt', 'latent heat', '冰', '水', '熔化', '潜热']

    is_target_task = any(kw in (question + context).lower() for kw in trigger_keywords)
    is_phase_change = any(kw in (question + context).lower() for kw in phase_keywords)

    if not (is_target_task and is_phase_change):
        return {'result': 'inconclusive', 'message': '未检测到相变热平衡全场景覆盖的触发条件', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须检查三个区间：T < T_melt, T = T_melt, T > T_melt
    # 对应的物理逻辑通常表现为对 Q_lost 与 Q_gain (to melt/to heat) 的比较
    pred = prediction.lower()

    # 检查是否讨论了三种可能性或区间
    # 1. 低温相 (T < 0 or T < T_melt)
    case1 = re.search(r'(t|temp|temperature)\s*(<|below)\s*0', pred) or 'all ice' in pred or '全部为冰' in pred
    # 2. 共存相 (T = 0 or T = T_melt)
    case2 = re.search(r'(t|temp|temperature)\s*(=|is)\s*0', pred) or 'mixture' in pred or '共存' in pred
    # 3. 高温相 (T > 0 or T > T_melt)
    case3 = re.search(r'(t|temp|temperature)\s*(>|above)\s*0', pred) or 'all water' in pred or '全部为水' in pred

    # Step 3: 符号/公式校验 — 检查是否涉及 Q_lost, Q_gain 或潜热 L
    has_symbols = any(sym in prediction for sym in ['L', 'Q_gain', 'Q_lost', 'm*L', 'mL', 'latent'])

    # 综合判定
    cases_found = [case1, case2, case3]
    found_count = sum(1 for c in cases_found if c)

    if found_count >= 3:
        return {'result': 'pass', 'message': '模型完整讨论了相变平衡的三种可能区间', 'evidence': prediction[:200]}
    elif found_count > 0 and has_symbols:
        # 如果只讨论了部分但有公式，可能是在计算后排除了其他情况，保守返回 inconclusive
        return {'result': 'inconclusive', 'message': '模型讨论了部分场景，但未明确展示完整的三区间分类讨论', 'evidence': prediction[:200]}
    else:
        return {'result': 'fail', 'message': '模型未按要求对相变热平衡的所有可能场景（全冰、冰水混合、全水）进行分类讨论', 'evidence': prediction[:200]}

# rule_id=norm_b0acc1100217a1e1 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_b0acc1100217a1e1 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_b0acc1100217a1e1_f362bc46ecd6(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否要求 'specific' (比) 物理量且涉及摩尔质量 mu
    # 匹配关键词如 specific heat, specific latent heat, 比热, 比潜热 等
    trigger_keywords = ['specific', '比热', '比潜热', '单位质量']
    has_trigger = any(kw in (question + context).lower() for kw in trigger_keywords)
    # 检查是否提及摩尔质量 mu 或 M
    has_mu = re.search(r'\\mu|molar\\s+mass|摩尔质量', question + context, re.IGNORECASE)

    if not (has_trigger and has_mu):
        return {'result': 'inconclusive', 'message': '未检测到要求计算比物理量或未提供摩尔质量', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查最终表达式是否除以了摩尔质量 mu
    # 寻找类似 L/mu, Q/mu, C/mu 或 (molar_value)/mu 的结构
    # 同时也检查是否错误地保留了摩尔形式而没有除以 mu
    pred_clean = prediction.replace(' ', '')

    # 匹配除以 mu 的模式：/\mu 或 /M 或 * (1/\mu)
    division_pattern = re.compile(r'(/\\mu|/M|\\frac{[^}]+}{\\mu}|\\frac{[^}]+}{M})')

    if division_pattern.search(prediction):
        return {'result': 'pass', 'message': '表达式中包含了除以摩尔质量的转换步骤', 'evidence': re.search(r'.{0,20}/\\mu.{0,20}', prediction).group(0) if '/\\mu' in prediction else ''}

    # Step 3: 判定失败 — 如果明确给出了结果但没有除以 mu 的迹象
    # 检查是否直接使用了摩尔量符号而未进行量纲转换
    if re.search(r'L_m|C_m', prediction) and not division_pattern.search(prediction):
        return {'result': 'fail', 'message': '计算比物理量时未发现除以摩尔质量 mu 的转换逻辑', 'evidence': prediction[-150:]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确执行了摩尔到比物理量的转换', 'evidence': ''}

# rule_id=norm_c3006324d86cf585 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_c3006324d86cf585 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_c3006324d86cf585_e34ca7adeecc(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“导热隔板”或“heat conductive partition”且连接两个气室
    trigger_keywords = ['heat conductive partition', '导热隔板', '导热板']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到导热隔板相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 禁止将单侧视为绝热过程 (Adiabatic)
    pred_lower = prediction.lower()
    # 如果预测中明确提到单侧是绝热的，或者使用了绝热方程 (PV^gamma)，则判定为逻辑错误
    adiabatic_keywords = ['adiabatic', '绝热', 'pv^\\gamma', 'p v ^ \\gamma']
    if any(kw in pred_lower for kw in adiabatic_keywords):
        # 排除掉“不是绝热”这种否定表述
        if not re.search(r'(not|non|isn\'t|aren\'t|并非|不是)\s*(adiabatic|绝热)', pred_lower):
            return {'result': 'fail', 'message': '错误地将导热隔板两侧视为绝热过程', 'evidence': prediction[:200]}

    # Step 3: 检查逻辑 — 必须满足两侧温度实时相等 (T1=T2)
    # 匹配 T1=T2, T_left=T_right, T_1=T_2 等符号表达，或文字描述温度相等
    temp_eq_patterns = [
        r'T_?1\s*=\s*T_?2',
        r'T_?L\s*=\s*T_?R',
        r'T_{?left}?.*=.*T_{?right}?',
        r'温度(相等|相同|一致)',
        r'thermal equilibrium',
        r'same temperature'
    ]

    found_eq = any(re.search(p, pred_lower) for p in temp_eq_patterns)

    if found_eq:
        return {'result': 'pass', 'message': '正确识别导热隔板的热平衡约束(T1=T2)', 'evidence': prediction[:200]}

    # 如果既没有说绝热，也没有明确说温度相等，则证据不足
    return {'result': 'inconclusive', 'message': '未明确体现导热隔板的等温平衡逻辑', 'evidence': ''}

# rule_id=norm_edc7bfe126a25f87 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_edc7bfe126a25f87 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_edc7bfe126a25f87_c4b3493e3bd3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及湿空气混合及可能的凝结（fog/condensation/mixing/humidity）
    trigger_keywords = ['湿空气', '混合', '凝结', '雾', 'humid air', 'mixing', 'condensation', 'fog', 'latent heat', '潜热']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到湿空气混合或相变场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否建立了包含显热和潜热的能量守恒方程
    # 核心要素：质量/比热/温度项 (m*c*T) 以及 潜热项 (L*m 或 L*delta_w)
    pred = prediction.lower()

    # 检查是否提到了潜热 L 或 凝结量 m_condensed 相关的符号/概念
    has_latent_term = any(sym in pred for sym in ['l*', '*l', 'latent', '潜热', 'h_fg', 'm_c', 'm_w'])
    has_energy_balance = any(kw in pred for kw in ['energy balance', 'conservation', '守恒', 'heat balance', '热平衡'])

    if not has_latent_term:
        return {'result': 'fail', 'message': '在湿空气混合计算中缺失潜热项 (L*m_condensed) 的建模', 'evidence': prediction[:200]}

    # Step 3: 符号与公式结构校验
    # 匹配类似 (m1*c1*T1 + m2*c2*T2) = (m1+m2)*c*Tf + L*m 的结构
    # 简化匹配：寻找温度差与潜热项的等式关系
    pattern_energy = r'([mc].*?t.*?[\+\-].*?l|l.*?[\+\-].*?[mc].*?t)'
    if re.search(pattern_energy, pred):
        return {'result': 'pass', 'message': '已建立包含显热与潜热耦合的能量守恒方程', 'evidence': re.search(pattern_energy, pred).group(0)}

    # 检查必要符号是否存在
    required_symbols = ['L', 'T', 'c', 'm']
    missing_symbols = [s for s in required_symbols if s.lower() not in pred]
    if len(missing_symbols) > 2:
        return {'result': 'fail', 'message': f'建模公式中缺少关键物理量符号: {missing_symbols}', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '检测到相关物理量但公式结构不明确', 'evidence': prediction[:150]}

# rule_id=norm_f213bda844481b81 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
# rule_id=norm_f213bda844481b81 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_norm_f213bda844481b81_b645c312f6cd(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及热平衡方程求解末态温度 T
    # 关键词：热平衡、末态温度、混合后的温度、T =
    trigger_keywords = ['热平衡', '末态温度', '混合后', '最终温度', 'equilibrium temperature']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到热平衡温度求解场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别假设的末态相态（水或冰）
    # 寻找预测中关于末态的假设，例如 "假设全部为水" 或 "假设全部为冰"
    is_final_water = re.search(r'(假设|最终|末态).*?(全是水|为水|liquid|water)', prediction + context)
    is_final_ice = re.search(r'(假设|最终|末态).*?(全是冰|为冰|solid|ice)', prediction + context)

    # 如果没有明确假设，尝试从公式分母中的比热容数值推断
    # 水的比热容通常为 4.2e3 或 4200，冰通常为 2.1e3 或 2100
    has_c_water = re.search(r'4\.2|4200', prediction)
    has_c_ice = re.search(r'2\.1|2100', prediction)

    # Step 3: 符号/公式校验 — 检查分母中的 (m*c) 是否与假设一致
    # 匹配类似 T = (...) / (m1*c1 + m2*c2) 的结构
    formula_match = re.search(r'T\s*=\s*[^/]+/\s*\(([^\)]+)\)', prediction)
    if not formula_match:
        return {'result': 'inconclusive', 'message': '未找到明确的温度计算公式结构', 'evidence': ''}

    denominator = formula_match.group(1)

    # 逻辑检查：如果假设末态为水，分母不应出现冰的比热容（或应使用水的）
    if is_final_water and not is_final_ice:
        if '2100' in denominator or '2.1' in denominator:
            return {'result': 'fail', 'message': '分母比热容与假设的末态（水）不一致，错误使用了冰的比热容', 'evidence': formula_match.group(0)}
        if '4200' in denominator or '4.2' in denominator or 'c_w' in denominator.lower():
            return {'result': 'pass', 'message': '分母比热容与假设末态一致', 'evidence': formula_match.group(0)}

    if is_final_ice and not is_final_water:
        if '4200' in denominator or '4.2' in denominator:
            return {'result': 'fail', 'message': '分母比热容与假设的末态（冰）不一致，错误使用了水的比热容', 'evidence': formula_match.group(0)}
        if '2100' in denominator or '2.1' in denominator or 'c_i' in denominator.lower():
            return {'result': 'pass', 'message': '分母比热容与假设末态一致', 'evidence': formula_match.group(0)}

    return {'result': 'inconclusive', 'message': '无法确定假设相态或分母参数含义', 'evidence': denominator}

# rule_id=norm_2f76fe935292efc7 | domain=Thermodynamics & Statistical Physics | topic=Specific Heat and Heat Capacities
# rule_id=norm_2f76fe935292efc7 | domain=Thermodynamics & Statistical Physics | topic=Specific Heat and Heat Capacities
def check_norm_2f76fe935292efc7_bd9d0394faed(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及温度相关的热容量及总能量/内能计算
    trigger_keywords = ['热能', '内能', 'internal energy', 'total energy', 'heat capacity', '热容量', '比热']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到热能或热容量相关计算场景', 'evidence': ''}

    # 检查是否提到热容量随温度变化 (C(T) 或 C 是 T 的函数)
    if not re.search(r'[Cc]\s*\(\s*[Tt]\s*\)|[Cc]\s*∝|[Cc]\s*=\s*.*[Tt]', question + context):
        return {'result': 'inconclusive', 'message': '未检测到热容量随温度变化的函数描述', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否使用了积分式而非简单的乘积
    # 寻找积分符号或积分描述，以及避免直接使用 C*T 的错误形式
    pred = prediction.lower()
    integral_patterns = [r'\\int', r'∫', r'integral', r'积分', r'\\int_{.*}^{.*}']
    has_integral = any(re.search(p, pred) for p in integral_patterns)

    # 寻找错误的简单乘积形式，如 U = C * T 或 Q = C * T (当 C 是变量时)
    wrong_product = re.search(r'[UQ]\s*=\s*[Cc]\s*\*?\s*[Tt](?!\s*d[Tt])', pred)

    # Step 3: 综合判定
    if has_integral:
        # 进一步检查公式结构是否包含 C(T) dT
        if re.search(r'[Cc].*d[Tt]', pred):
            return {'result': 'pass', 'message': '正确使用了积分式计算总能量', 'evidence': '检测到积分结构及 C(T)dT'}
        else:
            return {'result': 'inconclusive', 'message': '检测到积分但公式细节不明确', 'evidence': prediction[:200]}

    if wrong_product:
        return {'result': 'fail', 'message': '在热容量随温度变化时错误地使用了简单乘积 Q=CT，应使用积分式', 'evidence': wrong_product.group()}

    return {'result': 'inconclusive', 'message': '未能明确判定是否使用了正确的积分计算逻辑', 'evidence': prediction[:200]}

# rule_id=norm_a22a1069523cd824 | domain=Thermodynamics & Statistical Physics | topic=Specific Heat and Heat Capacities
# rule_id=norm_a22a1069523cd824 | domain=Thermodynamics & Statistical Physics | topic=Specific Heat and Heat Capacities
def check_norm_a22a1069523cd824_7ebecf508522(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及态密度(Density of States)或物理常数计算
    trigger_keywords = ['态密度', 'density of states', 'ρ(ω)', 'g(ω)', 'D(ω)', 'specific heat', '比热']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到态密度或比热相关物理量计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证预测中是否包含态密度公式及其量纲逻辑
    # 态密度 ρ(ω) 的量纲应为 [能量]^-1 或 [频率]^-1，即 [时间]
    pred_clean = prediction.replace(' ', '')
    # 寻找类似 ρ(ω) = ... 的表达式
    dos_pattern = r'[ρgD]\(ω\)\s*[:=]'
    if not re.search(dos_pattern, prediction) and '态密度' not in prediction:
        return {'result': 'inconclusive', 'message': '预测中未明确给出态密度的推导表达式', 'evidence': ''}

    # Step 3: 符号与量纲校验 — 检查分母中速度(v)的幂次是否导致量纲错误
    # 在三维情况下，态密度通常与 V/v^3 相关；若分母速度幂次不对，量纲会失衡
    # 检查是否存在明显的量纲失衡特征，例如分母缺少速度项或速度幂次异常
    if 'V' in prediction and 'ω' in prediction:
        # 匹配典型的错误特征：如态密度公式中完全缺失速度 v 或频率 ω 的量纲关联
        if re.search(r'V/v\s*$', pred_clean) or re.search(r'V/v\^2', pred_clean):
            return {'result': 'fail', 'message': '态密度公式量纲不匹配，分母速度幂次可能错误', 'evidence': re.search(r'V/v\^?\d*', pred_clean).group(0) if re.search(r'V/v\^?\d*', pred_clean) else '量纲失衡'}

        # 检查 canonical 形式 [ρ(ω)] = [N]/[ω] 的逻辑体现
        if re.search(r'[Vv].*[ωw]', pred_clean):
            return {'result': 'pass', 'message': '态密度表达式包含必要的体积、速度与频率项，量纲逻辑基本一致', 'evidence': '检测到 V, v, ω 相关项'}

    return {'result': 'inconclusive', 'message': '无法确定量纲是否严格一致，需人工核验', 'evidence': prediction[:100]}

# rule_id=norm_b1b41faf215df2af | domain=Thermodynamics & Statistical Physics | topic=Specific Heat and Heat Capacities
# rule_id=norm_b1b41faf215df2af | domain=Thermodynamics & Statistical Physics | topic=Specific Heat and Heat Capacities
def check_norm_b1b41faf215df2af_e8097ca7d444(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否存在色散关系变量替换场景 (k, omega, v)
    trigger_keywords = ['\\omega', 'omega', 'dk', 'd\\omega', 'dispersion', '色散']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到色散关系或变量替换场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找 dk 与 domega 的转换关系及系数 (1/v)
    # 重点检查是否包含 dk = (1/v) domega 或类似的导数项系数
    pred = prediction.lower()
    # 匹配 dk = ... domega 或 dk/domega = ...
    # 允许不同的书写方式，如 1/v, v^{-1}, d\\omega/v
    pattern_dk_domega = r'dk\s*=\s*([^\n]+)d\\?omega'
    pattern_derivative = r'dk/d\\?omega'

    match_relation = re.search(pattern_dk_domega, pred) or re.search(pattern_derivative, pred)

    if not match_relation:
        # 如果完全没有提到 dk 和 domega 的转换，且题目要求积分/密度计算，则可能遗漏
        if 'density of states' in combined_text or '状态密度' in combined_text:
            return {'result': 'fail', 'message': '在进行变量替换时未显式展示 dk 与 domega 的转换关系', 'evidence': prediction[:200]}
        return {'result': 'inconclusive', 'message': '未发现明确的变量替换步骤', 'evidence': ''}

    # Step 3: 符号/公式校验 — 检查系数是否包含 1/v 或 v 的倒数项
    # 针对 omega = v*k, dk = (1/v) domega
    if '1/v' in pred or 'v^{-1}' in pred or '/v' in pred or 'v**-1' in pred:
        return {'result': 'pass', 'message': '已包含正确的变量替换系数 (1/v)', 'evidence': match_relation.group(0) if hasattr(match_relation, 'group') else ''}

    # 如果有替换动作但系数明显不对（例如直接 dk = domega）
    if re.search(r'dk\s*=\s*d\\?omega', pred):
        return {'result': 'fail', 'message': '变量替换 dk -> domega 缺少速度系数 1/v', 'evidence': match_relation.group(0)}

    return {'result': 'inconclusive', 'message': '检测到替换但系数形式不确定', 'evidence': prediction[:200]}

# rule_id=norm_09449c1649a44032 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
# rule_id=norm_09449c1649a44032 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_norm_09449c1649a44032_3ee5223f20e4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及背景辐射功率 P0 与额外扰动功率 P 导致的温度变化 ΔT
    # 关键词：辐射功率、温度变化、增量、扰动、Stefan-Boltzmann
    trigger_keywords = ['辐射', '功率', '温度', '变化', '增量', 'P0', 'ΔT', 'delta T']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到黑体辐射功率扰动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否利用微分关系 ΔP/P = 4ΔT/T 或 ΔT = (T/4) * (ΔP/P0)
    # 检查 prediction 中是否出现了线性化简化的迹象，而不是重新计算常数
    pred = prediction.lower()
    # 匹配 ΔP/P = 4ΔT/T 或其变体
    linear_patterns = [
        r'dp/p.*4.*dt/t',
        r'dt/t.*1/4.*dp/p',
        r'delta.*p/p.*4.*delta.*t/t',
        r't/4.*p/p0',
        r't/4.*delta.*p/p'
    ]

    found_linear = any(re.search(pat, pred.replace(' ', '')) for pat in linear_patterns)

    # Step 3: 检查是否避开了 Stefan-Boltzmann 常数 (sigma) 的复杂计算
    # 如果 prediction 中大量出现 sigma (σ) 的数值计算且没有体现比例关系，则可能违反了简化规则
    uses_sigma_val = re.search(r'5\.67.*10\^-8', pred)

    if found_linear:
        return {'result': 'pass', 'message': '成功利用微分线性化关系简化计算', 'evidence': '检测到线性化比例关系'}

    if uses_sigma_val and not found_linear:
        return {'result': 'fail', 'message': '未利用线性化关系，重复计算了 Stefan-Boltzmann 常数等中间变量', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否使用了线性化简化逻辑', 'evidence': ''}

# rule_id=norm_22898499de67cb74 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
# rule_id=norm_22898499de67cb74 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_norm_22898499de67cb74_d5e92970370f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及不同地表覆盖物（如冰雪与裸地）的反照率/反射率及总比例求值
    q_c_lower = (question + context).lower()
    # 匹配反照率/反射率关键字，以及多地表覆盖物场景（如 冰/雪/裸地/水/面积比例）
    trigger_keywords = ['albedo', 'reflectivity', '反照率', '反射率']
    has_trigger_kw = any(kw in q_c_lower for kw in trigger_keywords)
    has_surface_types = any(kw in q_c_lower for kw in ['ice', 'snow', 'land', 'water', 'area', 'fraction', 'proportion', '冰', '雪', '地', '水', '比例', '面积', '权重'])

    if not (has_trigger_kw and has_surface_types):
        return {
            'result': 'inconclusive',
            'message': '未检测到不同地表覆盖物反照率加权平均的场景',
            'evidence': ''
        }

    # Step 2: 检查 prediction 中是否包含总反照率的计算逻辑，尤其是线性组合形式
    # 寻找表征线性叠加的特征：如 a * x + b * (1-x) 或类似相加形式
    pred_lower = prediction.lower()

    # 如果没有提及反照率相加或按比例计算，则可能缺失计算逻辑
    calc_indicators = ['+', 'sum', 'total', 'add', 'average', '线性', '相加', '均值', '总', '合成']
    has_calc = any(ind in pred_lower for ind in calc_indicators)

    # 如果回答中完全没有体现任何加法、乘法或线性合并的表述，判定为 logic 错误
    if not has_calc:
        return {
            'result': 'fail',
            'message': '推理过程中未体现各组分反照率的加权平均或线性叠加逻辑',
            'evidence': prediction[:200]
        }

    # Step 3: 公式模式匹配验证 (α_total = x * α1 + (1 - x) * α2 结构)
    # 匹配如: x * a + (1-x) * b 或 a * x + b * y (x+y=1) 或 (a*S1 + b*S2)/S 等加权平均形式的正则
    pattern_linear_1 = r'(\w+\s*\*\s*\w+\s*\+\s*\(\s*1\s*-\s*\w+\s*\)\s*\*\s*\w+)'
    pattern_linear_2 = r'(\w+\s*\*\s*\w+\s*\+\s*\w+\s*\*\s*\w+)'
    pattern_linear_zh = r'(反照率|反射率).*\*(.*比例|.*面积|\w+)\s*\+\s*(反照率|反射率).*\*(.*比例|.*面积|\w+)'

    if (re.search(pattern_linear_1, pred_lower) or
        re.search(pattern_linear_2, pred_lower) or
        re.search(pattern_linear_zh, pred_lower)):
        return {
            'result': 'pass',
            'message': '已按面积权重线性叠加计算总反照率',
            'evidence': prediction[:200]
        }

    return {
        'result': 'inconclusive',
        'message': '无法确定是否严格采用了线性组合规则计算反照率',
        'evidence': prediction[:200]
    }

# rule_id=norm_3fe6b2dd1ec694ce | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
# rule_id=norm_3fe6b2dd1ec694ce | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_norm_3fe6b2dd1ec694ce_b3662dd214df(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及太阳常数、黑体辐射、稳态温度等关键词
    trigger_keywords = ['太阳常数', 'solar constant', '黑体辐射', 'blackbody', 'Stefan-Boltzmann', '斯特藩', '稳态温度', '平衡温度']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到黑体辐射稳态平衡相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否建立了能量平衡方程 (P_in = P_out)
    # 重点检查是否包含 Stefan-Boltzmann 定律的核心项 σT^4 或 sigma*T^4
    pred_lower = prediction.lower()
    has_stefan_law = re.search(r'σ\s*t\^4|sigma\s*t\^4|t\^4', pred_lower)
    has_balance = any(word in pred_lower for word in ['平衡', 'balance', 'equilibrium', 'in =', 'in='])

    if not has_stefan_law:
        return {'result': 'fail', 'message': '模型推理中缺失 Stefan-Boltzmann 定律 (σT^4) 的关键项', 'evidence': prediction[:200]}

    # Step 3: 符号与公式结构校验 — 检查是否考虑了吸收率 η 或 太阳常数 S
    # 检查公式结构是否符合 ηS + I = σT^4 的逻辑（允许变体）
    required_symbols = ['s', 't', 'σ|sigma']
    missing_symbols = [s for s in required_symbols if not re.search(s, pred_lower, re.IGNORECASE)]

    if len(missing_symbols) > 1: # 允许缺失一个（如σ可能被数值替代），但多个缺失则认为建模不完整
        return {'result': 'fail', 'message': f'建模公式中缺少必要物理量符号: {missing_symbols}', 'evidence': prediction[:200]}

    # 检查是否体现了能量守恒/平衡方程的等式关系
    if '=' not in pred_lower and '等于' not in pred_lower:
        return {'result': 'fail', 'message': '未明确建立能量平衡等式 (P_in = P_out)', 'evidence': prediction[:200]}

    return {'result': 'pass', 'message': '已建立黑体辐射能量平衡模型并包含核心物理量', 'evidence': prediction[:200]}

# rule_id=norm_56794270cd6c3ed6 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
# rule_id=norm_56794270cd6c3ed6 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_norm_56794270cd6c3ed6_a9b34ad0e3a9(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及物体在空气中电热丝加热达到热平衡
    # 关键词：电热丝/加热/空气/热平衡/辐射/Stefan-Boltzmann/T^4/Stefan/Boltzmann
    q_text = (question + context).lower()
    is_triggered = (
        ('thermal equilibrium' in q_text or '热平衡' in q_text) and
        ('air' in q_text or '空气' in q_text) and
        ('heat' in q_text or '加热' in q_text or 'electric' in q_text or '电' in q_text)
    )
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到涉及空气中加热热平衡的场景', 'evidence': ''}

    # Step 2: 检查 prediction 中是否同时考虑了辐射散热 (T^4) 和非辐射散热 (T - T0 或对流/传导)
    pred = prediction.lower()

    # 检查辐射散热项：通常包含 T^4 差值，或 Stefan-Boltzmann 常数 sigma (\sigma)
    has_radiation = (
        't^4' in pred or
        't_0^4' in pred or
        '\\sigma' in pred or
        'stefan' in pred or
        'boltzmann' in pred
    )

    # 检查非辐射散热项：如对流(convection)、传导(conduction)、与 (T - T0) 成正比的散热项
    has_non_radiation = (
        'convection' in pred or
        'conduction' in pred or
        '对流' in pred or
        '传导' in pred or
        't - t_0' in pred or
        't-t_0' in pred or
        't - t0' in pred or
        't-t0' in pred or
        re.search(r'h\s*\(\s*t\s*-\s*t_?0\s*\)', pred) is not None
    )

    # Step 3: 根据检查结果判断
    if not (has_radiation and has_non_radiation):
        return {
            'result': 'fail',
            'message': '热平衡方程不完整，未能同时考虑辐射散热（T^4项）与非辐射散热（如对流或传导，与 T-T0 相关项）',
            'evidence': prediction[:200]
        }

    return {'result': 'pass', 'message': '已同时考虑辐射与非辐射散热，热平衡方程完整', 'evidence': prediction[:200]}

# rule_id=norm_66b1ef17cd82f1fe | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
# rule_id=norm_66b1ef17cd82f1fe | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_norm_66b1ef17cd82f1fe_c3a21132444b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件检查 — 出现 reflective coating、cut-off frequency 且涉及热平衡温度计算
    trigger_keywords = ['reflective coating', 'cut-off frequency', '截止频率', '选择性涂层']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到选择性涂层或截止频率相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须区分吸收端(T_sun)和发射端(T_sat)在截止频率处的积分或近似处理
    pred_lower = prediction.lower()
    # 检查是否提到了两个温度端（太阳和卫星/物体）
    if not (re.search(r't_?sun|太阳', pred_lower) and re.search(r't_?sat|t_?e|卫星|平衡温度', pred_lower)):
        return {'result': 'fail', 'message': '模型未明确区分太阳辐射端与卫星发射端的温度贡献', 'evidence': prediction[:200]}

    # Step 3: 检查关键物理量 f_c (或 lambda_c) 以及能量平衡逻辑
    # 检查是否讨论了 hf/kT 或相关的积分截断逻辑
    logic_keywords = ['hf', 'kt', 'integral', '积分', 'approximation', '近似', 'stefan', 'boltzmann']
    if not any(kw in pred_lower for kw in logic_keywords):
        return {'result': 'fail', 'message': '未发现对截止频率处的辐射积分或 hf/kT 近似处理的讨论', 'evidence': prediction[:200]}

    # Step 4: 符号覆盖检查 (T_sat, T_sun, f_c)
    required_symbols = [r'T_?sun', r'T_?sat', r'f_?c|lambda_?c']
    missing_symbols = []
    for sym in required_symbols:
        if not re.search(sym, prediction, re.IGNORECASE):
            missing_symbols.append(sym)

    if missing_symbols:
        return {'result': 'fail', 'message': f'缺少必要的物理符号或参数: {missing_symbols}', 'evidence': prediction[:200]}

    # 如果包含能量平衡等式 P_abs = P_emit 的变形，则视为 pass
    if re.search(r'p_?abs.*=.*p_?emit|p_?in.*=.*p_?out', pred_lower) or 'balance' in pred_lower:
        return {'result': 'pass', 'message': '模型正确包含了选择性涂层的辐射平衡建模要素', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑要素基本具备，但无法确定计算过程是否完全符合规则要求', 'evidence': prediction[:200]}

# rule_id=norm_6c89ab62cbff11ac | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
# rule_id=norm_6c89ab62cbff11ac | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_norm_6c89ab62cbff11ac_fbaf6e0a14ee(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及量纲分析建立方程组求解幂次指数
    trigger_keywords = ['量纲分析', 'dimensional analysis', '指数', '幂次', '方程组', 'equation system']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到量纲分析建立方程组的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否包含必要的指数符号 (alpha, beta, delta, gamma)
    required_symbols = ['\\alpha', '\\beta', '\\delta', '\\gamma']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    # 如果预测中完全没有提到这些指数符号，且题目要求求解指数，则可能存在逻辑缺失
    if len(missing_symbols) == len(required_symbols):
        return {'result': 'fail', 'message': '未在推理过程中发现待求指数符号（alpha, beta等）', 'evidence': prediction[:200]}

    # Step 3: 检查方程组的完备性与解的合理性
    # 检查是否出现了全零解的错误倾向（通常是由于左侧量纲推导错误导致）
    zero_solution_pattern = r'(\\alpha|\\beta|\\gamma|\\delta)\s*=\s*0'
    zero_matches = re.findall(zero_solution_pattern, prediction)

    # 检查方程个数是否与未知数匹配（简单通过等号计数判断）
    eq_count = prediction.count('=')
    # 在量纲分析中，通常有3个基本量(M, L, T)，若未知数多于方程数且未说明，则可能逻辑不完备
    if '方程' in prediction and eq_count < 2:
         return {'result': 'fail', 'message': '方程组个数不足或未明确列出线性方程组', 'evidence': prediction[:200]}

    # 检查是否存在矛盾解或全零解的异常描述
    if len(zero_matches) >= 3 and '0' in prediction:
        return {'result': 'fail', 'message': '检测到疑似全零解，请检查等式左侧目标量量纲是否推导错误', 'evidence': str(zero_matches)}

    # 若包含方程组结构且有合理的指数赋值，则视为通过
    if re.search(r'\\begin{cases}|=', prediction) and len(zero_matches) < 3:
        return {'result': 'pass', 'message': '量纲方程组逻辑校验通过', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定方程组完备性', 'evidence': ''}

# rule_id=norm_74995a18ce9feae0 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
# rule_id=norm_74995a18ce9feae0 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_norm_74995a18ce9feae0_f59c94b8a6e5(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及遥远天体（恒星）通过望远镜/透镜成像在探测器（CCD）上的热平衡计算
    trigger_keywords = ['恒星', '天体', 'star', 'telescope', '望远镜', 'CCD', '探测器', '成像', 'imaging']
    q_c_text = (question + context).lower()
    if not any(kw in q_c_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到天体成像热平衡场景', 'evidence': ''}
    if '平衡' not in q_c_text and 'temperature' not in q_c_text:
        return {'result': 'inconclusive', 'message': '未检测到温度或平衡计算需求', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否利用像面与物面亮度关系（或立体角/焦距相关建模），而非简单通量相等
    pred = prediction.lower()
    # 检查是否提到亮度(brightness/radiance)、立体角(solid angle)、焦距(focal length/f)或孔径(aperture)
    modeling_keywords = ['radiance', 'brightness', '亮度', '立体角', 'solid angle', 'focal length', '焦距', 'f^2', 'f**2', 'omega']
    has_modeling = any(kw in pred for kw in modeling_keywords)

    # 检查是否错误地假设通量直接相等 (Flux_star = Flux_ccd) 而忽略了光学系统的几何衰减/增益
    simple_flux_assumption = re.search(r'flux_star\s*=\s*flux_ccd|通量相等', pred)

    if not has_modeling and simple_flux_assumption:
        return {'result': 'fail', 'message': '模型过于简化，未考虑光学成像的几何关系（如焦距或立体角），仅简单假设通量相等', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查关键符号 A, T_star, f 以及 Stefan-Boltzmann 相关的 4 次方关系
    required_symbols = ['T_star', 'f', 'A']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)

    # 检查是否存在类似 T^4 的 Stefan-Boltzmann 关系
    has_stefan_boltzmann = re.search(r'T(\^|\*\*)4', prediction) or 'stefan' in pred

    if symbol_count >= 2 and has_stefan_boltzmann:
        # 进一步检查公式结构是否包含焦距 f 的平方项（成像亮度的核心特征）
        if re.search(r'f(\^|\*\*)2', prediction) or 'focal' in pred:
            return {'result': 'pass', 'message': '建立了包含光学几何参数的热平衡方程', 'evidence': prediction[:200]}

    if not has_modeling:
        return {'result': 'fail', 'message': '未能识别出像面亮度与物面亮度的物理建模过程', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑存在但公式完整性不足以判定', 'evidence': ''}

# rule_id=norm_b580172bad8bcd5c | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
# rule_id=norm_b580172bad8bcd5c | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_norm_b580172bad8bcd5c_08bfce1b15d3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及斯特藩-玻尔兹曼定律及常温物体辐射计算
    trigger_keywords = ['Stefan', 'Boltzmann', '斯特藩', '玻尔兹曼', 'σT^4', 'sigma T^4']
    combined_text = (question + context).lower()
    if not any(k.lower() in combined_text for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到斯特藩-玻尔兹曼定律相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证 T 在 200K-400K 时 P 的量级，以及特定数值 P=685 的推论
    # 提取预测中的温度 T 和 辐射功率/强度 P
    t_match = re.search(r'T\s*=\s*(\d+\.?\d*)\s*K', prediction)
    p_match = re.search(r'P\s*=\s*(\d+\.?\d*)\s*W/m\^2', prediction)

    # 检查特定数值逻辑：若 P 接近 685 W/m^2，T 必须大于 273K
    if p_match:
        p_val = float(p_match.group(1))
        if abs(p_val - 685) < 10: # 允许一定误差范围
            if t_match:
                t_val = float(t_match.group(1))
                if t_val <= 273:
                    return {'result': 'fail', 'message': '当辐射功率约为 685 W/m^2 时，温度应大于 273K', 'evidence': f'P={p_val}, T={t_val}'}

    # 检查量级逻辑：T 在 200K-400K 之间时，P 应在 10^2 数量级 (约 90-1450 W/m^2)
    if t_match:
        t_val = float(t_match.group(1))
        if 200 <= t_val <= 400:
            if p_match:
                p_val = float(p_match.group(1))
                # 5.67e-8 * 200^4 = 90.7, 5.67e-8 * 400^4 = 1451.5
                if p_val < 50 or p_val > 2000:
                    return {'result': 'fail', 'message': '常温物体(200K-400K)辐射功率量级异常', 'evidence': f'T={t_val}, P={p_val}'}

    # Step 3: 符号覆盖检查
    required_symbols = ['P', 'T', 'σ']
    missing = [s for s in required_symbols if s not in prediction and s not in question]
    if len(missing) > 1: # 允许 σ 符号用文字或数值代替
        return {'result': 'inconclusive', 'message': '关键物理符号缺失', 'evidence': prediction[:100]}

    if t_match and p_match:
        return {'result': 'pass', 'message': '计算量级与物理逻辑符合常温辐射规律', 'evidence': f'T={t_match.group(1)}, P={p_match.group(1)}'}

    return {'result': 'inconclusive', 'message': '未发现明确的数值计算冲突', 'evidence': ''}

# rule_id=norm_bd0cc73fc44d1dd0 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
# rule_id=norm_bd0cc73fc44d1dd0 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_norm_bd0cc73fc44d1dd0_ff5e25e6788e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及天体表面温度、反照率或辐射平衡
    trigger_keywords = ['温度', 'temperature', '反照率', 'albedo', '辐射平衡', 'radiative equilibrium', 'energy balance']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到行星能量平衡相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证 prediction 是否包含建模必备要素 (S, alpha, sigma, T)
    pred_lower = prediction.lower()
    # 检查符号覆盖：太阳常数 S, 反照率 alpha, Stefan-Boltzmann 常数 sigma, 温度 T
    required_symbols = ['S', 'T', 'σ', 'sigma', 'α', 'albedo']
    # 检查是否包含核心物理量（至少包含 S, T 和 反照率相关的描述）
    has_s = 's' in prediction or 'solar constant' in pred_lower
    has_t = 't' in prediction or 'temperature' in pred_lower
    has_alpha = 'α' in prediction or 'alpha' in pred_lower or 'albedo' in pred_lower
    has_sigma = 'σ' in prediction or 'sigma' in pred_lower or 'stefan' in pred_lower

    if not (has_s and has_t and has_alpha):
        return {
            'result': 'fail',
            'message': '建模不完备：缺少太阳常数、反照率或温度等核心物理量',
            'evidence': prediction[:200]
        }

    # Step 3: 公式结构校验 — 检查是否体现 (1-alpha) 以及 1/4 因子或 Stefan-Boltzmann 定律形式
    # 匹配类似 (1-alpha) 或 (1-a) 的结构
    albedo_term = re.search(r'1\s*-\s*[αa]', pred_lower)
    # 匹配 Stefan-Boltzmann 定律 T^4 形式
    stefan_term = re.search(r'[T|t]\s*(\^|\*\*)\s*4', pred_lower)
    # 检查 1/4 因子（吸收面积与发射面积比）
    area_ratio = re.search(r'1/4|0\.25|/\s*4', pred_lower)

    if not (albedo_term and stefan_term):
        return {
            'result': 'fail',
            'message': '公式逻辑错误：未正确体现反照率修正或 Stefan-Boltzmann 四次方定律',
            'evidence': prediction[:200]
        }

    if not area_ratio:
        return {
            'result': 'fail',
            'message': '建模缺失：未体现球体吸收与发射面积比因子 (1/4)',
            'evidence': prediction[:200]
        }

    return {'result': 'pass', 'message': '行星能量平衡建模逻辑完备', 'evidence': prediction[:200]}

# rule_id=norm_d95ed8656e7a6e76 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
# rule_id=norm_d95ed8656e7a6e76 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_norm_d95ed8656e7a6e76_35598a82552f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及非理想黑体（如钨丝、发射率非1）及维恩位移/峰值测量
    trigger_keywords = ['非理想黑体', '钨丝', 'tungsten', '发射率', 'emissivity', 'epsilon', 'ε']
    context_blob = (question + context).lower()
    if not any(kw in context_blob for kw in trigger_keywords) or 'peak' not in context_blob and '峰值' not in context_blob:
        return {'result': 'inconclusive', 'message': '未检测到非理想黑体峰值偏移相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否错误地将发射率曲线的峰值作为辐射强度峰值
    pred = prediction.lower()
    # 错误逻辑：直接求导发射率或认为峰值由发射率决定
    error_patterns = [
        r'd\\epsilon/d\\lambda\\s*=\\s*0',
        r'dε/dλ\\s*=\\s*0',
        r'发射率.*峰值.*即为.*辐射峰值'
    ]
    for pattern in error_patterns:
        if re.search(pattern, pred):
            return {'result': 'fail', 'message': '错误地将发射率曲线峰值等同于辐射强度峰值', 'evidence': re.search(pattern, pred).group()}

    # Step 3: 符号/公式校验 — 检查是否考虑了 ε(λ) * B(λ, T) 的乘积求导
    # 正确逻辑应包含 ε(λ) 和 B(λ, T) 的乘积形式
    correct_logic_patterns = [
        r'\\epsilon.*B\\(',
        r'd\\s*\\[.*\\epsilon.*B.*\\]\\s*/\\s*d\\lambda',
        r'I\\(\\lambda\\)\\s*=\\s*\\epsilon.*B',
        r'辐射强度.*发射率.*普朗克'
    ]

    found_correct = any(re.search(p, pred) for p in correct_logic_patterns)

    if found_correct:
        return {'result': 'pass', 'message': '正确考虑了发射率与黑体辐射公式的乘积对峰值的影响', 'evidence': '检测到乘积求导或复合函数建模'}

    # 如果既没有明显的错误模式，也没有明确的正确推导过程，返回 inconclusive
    return {'result': 'inconclusive', 'message': '未能明确判定其峰值计算逻辑是否正确', 'evidence': prediction[:200]}

# rule_id=norm_ee63367bf1bce4d7 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
# rule_id=norm_ee63367bf1bce4d7 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_norm_ee63367bf1bce4d7_1570b42c41e2(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及斯特藩-玻尔兹曼常数或黑体辐射常数定义
    trigger_keywords = ['单位面积', '单位时间', '能量', 'Stefan', 'Boltzmann', '斯特藩', '玻尔兹曼']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到黑体辐射常数定义场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否包含导出公式或量纲推导过程
    # 重点检查是否包含能量、面积、时间、温度的组合关系
    pred = prediction.lower()
    # 匹配类似 E/(A*t*T^4) 的结构或其文字描述
    formula_pattern = r'([Ee]/\s*\(?[Aa].*[Tt].*[Tt]\^4\)?|[Mm]\s*[Tt]\^?-3\s*[Kk]\^?-4)'
    has_derivation = re.search(formula_pattern, pred) or ('能量' in pred and '面积' in pred and '时间' in pred and '温度' in pred)

    if not has_derivation:
        return {'result': 'fail', 'message': '未按要求从文字定义推导复合常数的公式或量纲', 'evidence': prediction[:200]}

    # Step 3: 符号与量纲校验 — 检查是否包含 sigma (\sigma) 且量纲是否正确 [M][T]^-3[K]^-4
    # 检查 canonical 量纲：M T^{-3} K^{-4}
    dimension_correct = re.search(r'M\s*T\^?-3\s*K\^?-4', prediction, re.IGNORECASE) or \
                        re.search(r'kg\s*s\^?-3\s*K\^?-4', prediction, re.IGNORECASE)

    if '\\sigma' in prediction or 'sigma' in pred:
        if dimension_correct:
            return {'result': 'pass', 'message': '成功还原复合常数定义并推导出正确量纲', 'evidence': prediction[:200]}
        else:
            return {'result': 'fail', 'message': '常数符号正确但量纲推导错误', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推导过程不完整或证据不足', 'evidence': ''}

# rule_id=norm_ab3f5c669d249bc6 | domain=Thermodynamics & Statistical Physics | topic=Clausius-Clapeyron Equation
# rule_id=norm_ab3f5c669d249bc6 | domain=Thermodynamics & Statistical Physics | topic=Clausius-Clapeyron Equation
def check_norm_ab3f5c669d249bc6_966fe3f17e9c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及压力变化下的相变（如冰融化、水汽化、Clausius-Clapeyron）
    trigger_keywords = ['相变', '融化', '汽化', '凝固', 'Clausius', 'Clapeyron', 'phase transition']
    pressure_keywords = ['压力', '压强', 'P1', 'P2', 'pressure']
    combined_text = (question + context).lower()

    is_triggered = any(kw in combined_text for kw in trigger_keywords) and any(kw in combined_text for kw in pressure_keywords)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到涉及压力变化的相变场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须考虑比容差/密度差与压力差的乘积作为功
    # 检查是否包含比容 (v) 或 密度 (rho) 的差异项，以及压力差 (delta P)
    pred_lower = prediction.lower()

    # 检查关键物理量符号：P (压力), rho (密度) 或 v (比容)
    has_rho_or_v = re.search(r'rho|密度|比容|\\rho|1/v|v2-v1|v_f - v_g', pred_lower)
    has_delta_p = re.search(r'p2\s*-\s*p1|\\delta\s*p|压力差|压强差', pred_lower)

    # Step 3: 符号与公式校验
    # 检查是否存在类似 W = deltaP * deltaV 的功计算逻辑
    work_logic_pattern = r'([Pp]2\s*-\s*[Pp]1).*(\d/rho|v2-v1|\\Delta\s*v)'

    if not (has_rho_or_v or 'volume' in pred_lower):
        return {
            'result': 'fail',
            'message': '在计算相变功时未体现比容差或密度差，可能错误地视为了不可压缩流体',
            'evidence': prediction[:200]
        }

    if re.search(work_logic_pattern, pred_lower) or 'w =' in pred_lower or 'work =' in pred_lower:
        return {
            'result': 'pass',
            'message': '模型正确考虑了相变前后的体积/密度变化对功的影响',
            'evidence': re.search(r'.{0,50}(w|work|功).{0,50}', pred_lower).group(0) if 'w' in pred_lower else ''
        }

    return {'result': 'inconclusive', 'message': '无法确定是否正确计算了相变功项', 'evidence': ''}

# rule_id=norm_2a54f77851342b05 | domain=Optics | topic=Reflection and Refraction
# rule_id=norm_2a54f77851342b05 | domain=Optics | topic=Reflection and Refraction
def check_norm_2a54f77851342b05_23efc098adb0(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及界面“不发生折射”且“与入射角无关”的场景
    trigger_keywords = ['不发生折射', '没有折射', '不改变传播方向', 'no refraction', 'without refraction']
    angle_keywords = ['任意角度', '入射角无关', 'any angle', 'regardless of the angle']

    q_c_text = (question + context).lower()
    is_triggered = any(kw in q_c_text for kw in trigger_keywords) and any(kw in q_c_text for kw in angle_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '题目未明确要求在任意入射角下不发生折射', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须满足两介质折射率相等 (n1 = n2)
    pred_text = prediction.lower()
    # 匹配 n1=n2, n_1=n_2, n_a=n_b 等折射率相等关系
    index_equality_pattern = r'n_?[12ab]\s*=\s*n_?[12ab]|折射率相等|index of refraction (is|are) (the same|equal)'

    has_equality = re.search(index_equality_pattern, pred_text) or 'n1=n2' in pred_text.replace(' ', '')

    # Step 3: 符号/公式校验 — 检查是否包含 n 或 lambda 相关的等式
    symbolic_match = re.search(r'n_?\d?\s*\(\s*\\lambda(_0)?\s*\)', pred_text)

    if not has_equality:
        return {
            'result': 'fail',
            'message': '未提及两介质折射率相等（n1 = n2）这一必要物理条件',
            'evidence': prediction[:200]
        }

    # 如果涉及色散（提到波长），检查是否考虑了特定波长的色散方程联立
    if '波长' in q_c_text or 'lambda' in q_c_text or 'dispersion' in q_c_text:
        if 'lambda' not in pred_text and '波长' not in pred_text:
            return {
                'result': 'fail',
                'message': '在色散介质场景下，未讨论特定波长下的折射率匹配',
                'evidence': prediction[:200]
            }

    return {'result': 'pass', 'message': '正确识别并应用了介质折射率相等导致无折射的判定逻辑', 'evidence': prediction[:200]}

# rule_id=norm_6a5a6c56ef2bf419 | domain=Optics | topic=Reflection and Refraction
# rule_id=norm_6a5a6c56ef2bf419 | domain=Optics | topic=Reflection and Refraction
def check_norm_6a5a6c56ef2bf419_6f87afb8347a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及封闭多边形镜面、光源反射及覆盖问题
    trigger_keywords = ['镜面', '反射', '光源', '覆盖', '多边形', '镜像', 'reflection', 'mirror', 'polygon']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到涉及镜面反射覆盖的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否包含镜像区域翻转、n次反射或张角计算的建模过程
    pred = prediction.lower()
    # 检查是否提到镜像/翻转 (image/flip/reflecting the region)
    has_image_method = any(kw in pred for kw in ['镜像', '翻转', 'image method', 'mirror image', 'unfolding'])
    # 检查是否提到张角或覆盖范围 (angle/subtended/coverage)
    has_angle_logic = any(kw in pred for kw in ['张角', '角度', 'angle', 'subtend', 'coverage', '覆盖'])

    if not has_image_method:
        return {'result': 'fail', 'message': '建模过程中缺失镜像法（区域翻转）的关键步骤', 'evidence': prediction[:200]}

    if not has_angle_logic:
        return {'result': 'fail', 'message': '未体现通过计算张角来判定覆盖边界的逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查是否包含 theta_min 或相关的最大张角逻辑
    # 匹配 theta_min 或类似的符号表示
    symbol_pattern = r'\\theta_{?min}?|theta_min|max\(.*angle.*\)'
    if not re.search(symbol_pattern, prediction, re.IGNORECASE):
        # 如果没有显式符号，检查是否有关于“最大”和“角”的描述
        if not (re.search(r'最大.*角', prediction) or re.search(r'max.*angle', pred)):
            return {'result': 'fail', 'message': '未按要求定义或计算最大张角 theta_min', 'evidence': prediction[:200]}

    return {'result': 'pass', 'message': '模型正确应用了镜像法并考虑了覆盖边界的张角判定', 'evidence': prediction[:200]}

# rule_id=norm_8c9c7d505f4b17a5 | domain=Optics | topic=Reflection and Refraction
# rule_id=norm_8c9c7d505f4b17a5 | domain=Optics | topic=Reflection and Refraction
def check_norm_8c9c7d505f4b17a5_c0dd9812cd42(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多维空间、独立维度或反射路径统计
    trigger_keywords = ['维度', 'D维', '正交空间', '独立', '路径总数', '反射次数']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多维独立路径统计场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 确认是否提及维度解耦或乘法原理
    pred_lower = prediction.lower()
    logic_keywords = ['解耦', '独立', '乘积', '相乘', '组合数', 'binom', 'C(', 'ways']
    if not any(kw in pred_lower for kw in logic_keywords):
        return {'result': 'fail', 'message': '未体现维度解耦或路径数乘法原理', 'evidence': prediction[:200]}

    # Step 3: 公式校验 — 检查是否包含组合数与各维度路径数乘积的结构
    # 匹配类似 \binom{D}{1} * Ways_N * Ways_{N-1}^{D-1} 的结构
    # 简化匹配：组合数项 * 某项 * 某项的幂次
    pattern_comb = r'(\\binom|C\(|comb)'
    pattern_prod = r'(\\times|\*|\cdot)'
    pattern_power = r'(\^|\*\*)'

    has_comb = re.search(pattern_comb, prediction)
    has_prod = re.search(pattern_prod, prediction)

    # 检查 symbolic_hint 中的关键符号 D 和 N
    if 'D' in prediction and 'N' in prediction:
        if has_comb and has_prod:
            return {'result': 'pass', 'message': '逻辑符合维度独立性乘法原理及组合分配', 'evidence': prediction[:200]}
        else:
            return {'result': 'fail', 'message': '公式结构缺失组合数或乘法项', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定公式准确性，证据不足', 'evidence': prediction[:200]}

# rule_id=norm_912909587690c1f6 | domain=Optics | topic=Reflection and Refraction
# rule_id=norm_912909587690c1f6 | domain=Optics | topic=Reflection and Refraction
def check_norm_912909587690c1f6_ca8871bded5c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及封闭空间（矩形/超矩形）内的多次反射路径
    trigger_keywords = ['反射', '镜像', '封闭', '矩形', '箱体', 'reflection', 'mirror', 'rectangular', 'enclosure']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到封闭空间多次反射场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否使用了镜像法（Method of Images）将路径转化为直线穿过格点
    pred = prediction.lower()
    logic_keywords = ['直线', '镜像点', '格点', 'straight line', 'image point', 'lattice', 'unfolding']
    has_logic = any(kw in pred for kw in logic_keywords)

    # Step 3: 符号与公式校验 — 检查坐标变换公式 x = 2mL ± x 或反射次数乘积形式
    # 匹配类似 2mL + x, 2mL - x, 2nL, 或者乘积形式 N = n1 * n2
    formula_pattern = r'(2\s*[mnk]\s*\*?\s*L|L_i|\\prod|n_i)'
    has_formula = re.search(formula_pattern, prediction) is not null

    if not has_logic and not has_formula:
        return {
            'result': 'fail',
            'message': '模型未体现镜像法建模逻辑，未将反射路径转化为穿过镜像格点的直线或未给出正确的坐标变换形式',
            'evidence': prediction[:200]
        }

    # Step 4: 验证反射次数与镜像点坐标的关系
    if '2' in pred and ('L' in prediction or 'l' in pred):
        return {
            'result': 'pass',
            'message': '模型正确应用了镜像法进行反射路径计数与坐标变换',
            'evidence': re.search(r'.{0,50}(2[mnk]L|L_i).{0,50}', prediction, re.IGNORECASE).group(0) if re.search(r'2[mnk]L|L_i', prediction, re.IGNORECASE) else prediction[:100]
        }

    return {'result': 'inconclusive', 'message': '检测到相关逻辑但证据不足以判定正误', 'evidence': prediction[:100]}

# rule_id=norm_96a30df54d3e5f0f | domain=Optics | topic=Reflection and Refraction
# rule_id=norm_96a30df54d3e5f0f | domain=Optics | topic=Reflection and Refraction
def check_norm_96a30df54d3e5f0f_6f87afb8347a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多面镜封闭空间、反射次数或全覆盖照明角度
    trigger_keywords = ['镜', 'mirror', '反射', 'reflection', '覆盖', 'coverage', '照明', 'illumination']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多面镜或反射覆盖场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否提及镜像法（翻转）或第一级镜像区域的覆盖
    pred_lower = prediction.lower()
    logic_keywords = ['镜像', 'image', '翻转', 'flip', 'fold', '区域', 'region', 'angle', '角度']
    if not any(kw in pred_lower for kw in logic_keywords):
        return {'result': 'fail', 'message': '推理过程中缺失镜像法边界判定或区域覆盖逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查是否包含 theta = 360/n 或类似的张角计算结构
    # 匹配形式如 360/n, 2*pi/n, 或具体的角度计算
    formula_pattern = r'360\s*/\s*n|2\s*\\?pi\s*/\s*n|\\theta|\\angle'
    if re.search(formula_pattern, prediction, re.IGNORECASE) or re.search(formula_pattern, answer, re.IGNORECASE):
        # 进一步检查是否提到了反射次数限制（如 1次）
        if '1' in pred_lower or 'once' in pred_lower or '一次' in pred_lower:
            return {'result': 'pass', 'message': '检测到镜像法覆盖判定逻辑及相关角度公式', 'evidence': re.search(formula_pattern, prediction, re.IGNORECASE).group() if re.search(formula_pattern, prediction, re.IGNORECASE) else ''}

    # 如果有公式但逻辑描述不全，或有逻辑但公式缺失，返回保守结果
    if re.search(r'\\theta|n', prediction):
        return {'result': 'inconclusive', 'message': '检测到相关符号但无法确认判定逻辑完整性', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '证据不足以判定镜像覆盖逻辑是否正确', 'evidence': ''}

# rule_id=norm_979888c180d55adc | domain=Optics | topic=Reflection and Refraction
# rule_id=norm_979888c180d55adc | domain=Optics | topic=Reflection and Refraction
def check_norm_979888c180d55adc_fdc88a21ed02(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及圆形区域、圆心光源及反射壁面
    trigger_keywords = ['圆', '半径', '圆心', '光源', '反射', '镜面', '壁面']
    q_c = (question + context).lower()
    if not (('圆' in q_c or 'circle' in q_c) and ('光源' in q_c or 'source' in q_c) and ('反射' in q_c or 'reflect' in q_c)):
        return {'result': 'inconclusive', 'message': '未检测到圆心光源反射场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否识别出圆心发出的光线沿法线入射并原路返回
    pred = prediction.lower()
    # 核心逻辑：光线过圆心 -> 垂直入射 -> 原路返回 -> 不增加照明面积
    logic_patterns = [
        r'沿法线', r'垂直入射', r'原路返回', r'回到圆心', r'重合',
        r'normal incidence', r'back to the center', r'overlap'
    ]

    has_logic = any(re.search(p, pred) for p in logic_patterns)

    # Step 3: 符号与公式校验 — 检查是否认为总面积等于直接照明面积 (Area_total = Area_direct)
    # 或者是 r_source = 0 (光源在圆心)
    symbolic_match = re.search(r'Area_{?total}?.*=.*Area_{?direct}?', prediction) or \
                     re.search(r'r_{?source}?\s*=\s*0', prediction) or \
                     '面积不变' in pred or '不增加' in pred

    if not has_logic and not symbolic_match:
        # 如果题目明确问及反射后的照明效果，但预测未考虑路径重合，则判定为 fail
        if '面积' in q_c or 'area' in q_c or '照明' in q_c:
            return {'result': 'fail', 'message': '未考虑圆心光源反射光线原路返回导致照明面积不增加的逻辑', 'evidence': prediction[:200]}
        return {'result': 'inconclusive', 'message': '缺乏关键物理逻辑推导', 'evidence': ''}

    if has_logic or symbolic_match:
        return {'result': 'pass', 'message': '正确识别了圆心光源反射路径重合的物理特性', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足', 'evidence': ''}

# rule_id=norm_da6e152a4d00fb74 | domain=Optics | topic=Reflection and Refraction
# rule_id=norm_da6e152a4d00fb74 | domain=Optics | topic=Reflection and Refraction
def check_norm_da6e152a4d00fb74_a17494d68651(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及折射率随高度/位置连续变化的介质（如大气折射、海市蜃楼、n(z)）
    trigger_keywords = ['n(z)', 'n(y)', 'refractive index', 'gradient', 'mirage', 'atmosphere', 'continuous', '折射率', '梯度', '海市蜃楼', '大气折射']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到分层介质或连续折射率变化场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否使用了 n*sin(theta) = const 及其变体，并注意角度定义
    pred = prediction.lower()
    # 匹配 n*sin(theta) = const 或 n1*sin1 = n2*sin2 的形式
    snell_pattern = r'n.*sin\(.*\).*=.*(const|constant|n.*sin)'
    # 匹配微分形式 n(z)*dx/ds 或 n(z)/sqrt(1+(dz/dx)^2)
    diff_pattern = r'n.*1/sqrt\(1\+\(d[zy]/dx\)\^2\)'

    has_snell = re.search(snell_pattern, pred) or re.search(diff_pattern, pred) or 'snell' in pred

    if not has_snell:
        return {'result': 'fail', 'message': '在处理连续介质折射时未体现斯涅尔定律守恒量 n(z)sinθ(z)=const', 'evidence': prediction[:200]}

    # Step 3: 检查角度定义错误（常见错误是将与垂直向夹角误用为与水平向夹角）
    # 如果提到 horizontal angle 或与水平面夹角，且未进行 90-theta 转换，则可能存在概念错误
    if 'horizontal' in pred or '水平' in pred:
        if 'cos' not in pred and '90-' not in pred and 'pi/2' not in pred:
            return {'result': 'fail', 'message': '角度定义可能错误：应使用光线与梯度方向（垂直向）的夹角，而非水平夹角', 'evidence': prediction[:200]}

    # Step 4: 符号覆盖检查
    if 'dz/dx' in prediction or 'dy/dx' in prediction or 'n(z)' in prediction:
        return {'result': 'pass', 'message': '正确使用了分层介质折射守恒量及相关符号', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到守恒思想但公式表达不完整', 'evidence': prediction[:200]}

# rule_id=norm_dc346ada5df7b6ce | domain=Optics | topic=Reflection and Refraction
# rule_id=norm_dc346ada5df7b6ce | domain=Optics | topic=Reflection and Refraction
def check_norm_dc346ada5df7b6ce_fa15c1ed4d43(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及圆心/球心光源及镜面反射
    trigger_keywords = ['圆心', '球心', 'center of the circle', 'center of the sphere']
    mirror_keywords = ['镜', 'mirror', '反射', 'reflection']
    text_to_check = (question + context).lower()

    is_triggered = any(k in text_to_check for k in trigger_keywords) and any(k in text_to_check for k in mirror_keywords)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到圆心光源与镜面反射场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否考虑光线沿法线射入/反射重合/垂直镜面
    pred = prediction.lower()
    logic_keywords = ['法线', '垂直', '重合', 'normal', 'perpendicular', 'overlap', 'along the radius']
    has_logic = any(k in pred for k in logic_keywords)

    # Step 3: 符号/公式校验 — 检查照明面积与张角的关系 (Area = theta/360 * Total)
    # 匹配类似 (theta/360), (theta/2pi), (angle/360) 的结构
    formula_pattern = r'(\\theta|angle|角度)\s*/\s*(360|2\\pi|6.28)'
    has_formula = re.search(formula_pattern, prediction, re.IGNORECASE) is not null

    if not has_logic and not has_formula:
        return {
            'result': 'fail',
            'message': '未提及光线沿法线反射或未利用张角比例计算照明面积',
            'evidence': prediction[:200]
        }

    if has_logic or has_formula:
        return {
            'result': 'pass',
            'message': '正确应用了圆心光源反射的几何恒等特性',
            'evidence': re.search(formula_pattern, prediction, re.IGNORECASE).group(0) if has_formula else '检测到法线反射逻辑'
        }

    return {'result': 'inconclusive', 'message': '证据不足', 'evidence': ''}

# rule_id=norm_e2dfdd6959c46be0 | domain=Optics | topic=Reflection and Refraction
# rule_id=norm_e2dfdd6959c46be0 | domain=Optics | topic=Reflection and Refraction
def check_norm_e2dfdd6959c46be0_2f6e09395499(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及点光源在对称图形中心产生的扇形区域占比
    trigger_keywords = ['点光源', '中心', '扇形', '占比', '比例', 'sector', 'point source']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到点光源扇形区域占比相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否使用了角度比例 theta/360 的计算逻辑
    # 匹配 theta/360, angle/360, 或具体的角度数值除以360的模式
    formula_pattern = r'(\\theta|angle|\\alpha|\\phi|\d+)\s*/\s*(360|2\\pi|6\.28)'
    pred_clean = prediction.replace(' ', '')

    # 检查是否存在非径向出射光的例外情况（如折射、反射偏转）
    exception_keywords = ['非径向', '折射', 'refraction', 'reflection gain', '反射增益']
    has_exception = any(ex in prediction for ex in exception_keywords)

    # Step 3: 符号与公式校验
    if re.search(formula_pattern, pred_clean, re.IGNORECASE):
        return {'result': 'pass', 'message': '正确使用了角度比例换算法', 'evidence': re.search(formula_pattern, pred_clean, re.IGNORECASE).group()}

    if not has_exception and ('360' not in prediction and '2\\pi' not in prediction):
        return {'result': 'fail', 'message': '在径向出射情况下未发现预期的角度比例计算逻辑', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否应用了扇区面积占比换算法', 'evidence': ''}

# rule_id=norm_07743a5498f82d0f | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_07743a5498f82d0f | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_07743a5498f82d0f_be1839fad97b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及自共轭成像（物像同位置且在屏上）
    trigger_keywords = ['image falls exactly on the screen', 'image coincides with the object', 'same position', 'back to the source']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到自共轭成像或物像同位场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否提到光路垂直射入反射镜或通过球心/光心以实现原路返回
    pred = prediction.lower()
    # 核心逻辑：垂直入射 (perpendicular/normal)、指向球心 (center of curvature)、原路返回 (retrace/back along)
    logic_keywords = ['perpendicular', 'normal to', 'center of curvature', 'retrace', 'back along the same path', 'optical center']

    found_logic = any(kw in pred for kw in logic_keywords)

    if not found_logic:
        return {
            'result': 'fail',
            'message': '未提及光路垂直射入反射镜面或通过球心以确保原路返回的物理逻辑',
            'evidence': prediction[:200]
        }

    # Step 3: 进一步验证是否明确了反射镜的作用
    if 'mirror' in pred or 'reflect' in pred:
        return {
            'result': 'pass',
            'message': '正确识别了自共轭成像中光路原路返回的判定条件',
            'evidence': re.search(r'[^.?!]*(?:perpendicular|normal|center|retrace)[^.?!]*', pred).group(0) if re.search(r'(perpendicular|normal|center|retrace)', pred) else prediction[:100]
        }

    return {'result': 'inconclusive', 'message': '逻辑描述不够完整', 'evidence': prediction[:100]}

# rule_id=norm_2abfe5ab7f2206c9 | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_2abfe5ab7f2206c9 | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_2abfe5ab7f2206c9_efc912a0a740(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 涉及椭圆镜面、焦点光源及沿长轴射出的光线
    trigger_keywords = ['椭圆', 'ellipse', 'elliptical']
    if not any(k in (question + context) for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到椭圆镜面场景', 'evidence': ''}

    if '焦点' not in (question + context) and 'focus' not in (question + context).lower():
        return {'result': 'inconclusive', 'message': '未检测到焦点光源', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否区分射向另一焦点还是远离另一焦点，以及反射路径描述
    pred = prediction.lower()
    # 检查是否讨论了反射路径的方向性（向另一焦点 vs 远离）
    direction_check = any(k in pred for k in ['另一焦点', 'other focus', 'vertex', '顶点', '远离', 'away'])
    if not direction_check:
        return {'result': 'fail', 'message': '未区分光线射向另一焦点还是远离另一焦点的反射路径', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 校验焦点距离 d=2c=2ae 或相关参数 a, c, e
    # 检查是否包含 a, c, e 等必要符号
    required_symbols = ['a', 'c', 'e']
    symbol_count = sum(1 for s in required_symbols if s in pred)

    # 检查公式结构 d = 2c 或 2ae
    formula_match = re.search(r'2\s*\*?\s*[ac]', pred) or re.search(r'2\s*\*?\s*a\s*\*?\s*e', pred)

    if symbol_count >= 2 or formula_match:
        # 如果提到了顶点反射逻辑且公式匹配
        if '顶点' in pred or 'vertex' in pred:
            return {'result': 'pass', 'message': '正确识别了远离焦点的反射路径及相关几何参数', 'evidence': prediction[:200]}
        return {'result': 'pass', 'message': '公式或符号校验通过', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑描述存在但数值/公式证据不足', 'evidence': prediction[:200]}

# rule_id=norm_3b1b5faa106755c0 | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_3b1b5faa106755c0 | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_3b1b5faa106755c0_5e749f438dac(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题干是否涉及放大率（magnification）或像高物高比例，且未明确像的性质（正立/倒立/虚实）
    trigger_keywords = ['放大率', 'magnification', '像高', '物高', '倍', 'times', 'size of image']
    if not any(k in (question + context) for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到放大率相关场景', 'evidence': ''}

    # 如果题干已经明确了是“实像”、“虚像”、“正立”或“倒立”，则不强制要求讨论两种情况
    explicit_nature = ['实像', '虚像', '正立', '倒立', 'real image', 'virtual image', 'upright', 'inverted']
    if any(k in (question + context) for k in explicit_nature):
        return {'result': 'inconclusive', 'message': '题干已明确像的性质，无需讨论两种情况', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否考虑了正负两种可能性 (m > 0 和 m < 0)
    # 查找是否提到了“两种情况”、“正立或倒立”、“正负”、“plus or minus”或列出了两个不同的计算分支
    pred_lower = prediction.lower()
    two_cases_patterns = [
        '两种情况', '两种可能', '正立', '倒立', 'plus or minus', '±',
        'inverted', 'upright', 'real or virtual', 'm =', 'm=-'
    ]

    # 检查是否同时出现了正负号相关的讨论，或者明确提到了“两种情况”
    has_positive = re.search(r'm\s*=\s*\+?\d|正立|upright|virtual', pred_lower)
    has_negative = re.search(r'm\s*=\s*-\d|倒立|inverted|real', pred_lower)
    has_dual_mention = '两种' in pred_lower or 'two cases' in pred_lower or '±' in pred_lower

    # Step 3: 判定结果
    if has_positive and has_negative:
        return {'result': 'pass', 'message': '已同时考虑正立（虚像）和倒立（实像）两种物理情景', 'evidence': prediction[:200]}

    if has_dual_mention:
        return {'result': 'pass', 'message': '提到了存在多种可能性', 'evidence': prediction[:200]}

    # 如果只计算了一种情况且没有说明理由，则判定为 fail
    if (has_positive and not has_negative) or (has_negative and not has_positive):
        return {'result': 'fail', 'message': '未同时考虑放大率的正负号（正立与倒立两种可能），除非题干已限定', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否完整讨论了放大率的正负性', 'evidence': ''}

# rule_id=norm_3ef2877cb428de02 | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_3ef2877cb428de02 | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_3ef2877cb428de02_c1c52507741b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及光阑、光屏及成像范围计算
    trigger_keywords = ['光阑', 'aperture', '光屏', 'screen', '成像范围', '成像半径', '遮挡']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到光阑限制成像范围的相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了相似三角形或光锥模型
    # 核心逻辑：R_a / |z_a - z_l| = (R_l + R_i) / v 或类似的比例关系
    pred = prediction.lower()
    logic_keywords = ['相似三角形', '比例', '光线', '边缘', 'radius', 'ratio']
    if not any(kw in pred for kw in logic_keywords):
        return {'result': 'fail', 'message': '未在推理中体现光阑限制的几何比例模型', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验
    # 检查是否包含关键物理量符号：R_a (光阑半径), R_l (透镜半径), R_i (像半径), v (像距), z (位置)
    required_symbols = ['R_a', 'R_l', 'R_i', 'v']
    # 允许下标形式如 R_a, Ra, r_a
    symbol_patterns = [r'[Rr][_]?[aliv]', r'[vz][_]?[al]']
    found_symbols = []
    for pattern in symbol_patterns:
        found_symbols.extend(re.findall(pattern, prediction))

    # 检查 canonical 公式结构：比例关系 (R/d = R/d)
    # 匹配类似 R/z = (R+R)/v 的结构
    ratio_pattern = r'([Rr].*?/.*?=.*?[Rr].*?/.*?)'
    formula_match = re.search(ratio_pattern, prediction)

    if formula_match:
        return {'result': 'pass', 'message': '检测到符合几何比例的计算模型', 'evidence': formula_match.group(1)}

    if len(set(found_symbols)) >= 2:
        return {'result': 'pass', 'message': '推理中包含必要的几何参数，逻辑基本完整', 'evidence': str(list(set(found_symbols)))}

    return {'result': 'inconclusive', 'message': '无法确定几何比例校验是否正确执行', 'evidence': prediction[:150]}

# rule_id=norm_4c22cdcb75e7d97d | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_4c22cdcb75e7d97d | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_4c22cdcb75e7d97d_de7bd5bbf1ff(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及折射率 n 与波长 lambda 的关系推导
    trigger_keywords = ['折射率', '波长', 'refractive index', 'wavelength', 'n=', '\\lambda']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到折射率与波长关系的推导场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证公式是否正确表达了 n = lambda_0 / lambda_n (真空波长与介质波长之比)
    # 重点检查是否混淆了不同介质的波长关系，或错误地将 n 与频率/颜色波长直接等同而忽略介质属性
    pred = prediction.lower()

    # 匹配 n = lambda_0 / lambda 或类似的比例关系
    # 允许常见的 LaTeX 格式如 \lambda_{0}, \lambda_{vac}, \lambda_{n}, \lambda_{m}
    pattern_correct = r'n\s*=\s*(\\lambda(_\{?0\}?)?|c)\s*/\s*(\\lambda(_\{?[nmv]\}?)?|v)'

    # 检查是否存在错误的定义，例如 n = lambda_n / lambda_0 (倒置错误)
    pattern_inverse = r'n\s*=\s*\\lambda_\{?[nmv]\}?\s*/\s*\\lambda_\{?0\}?'

    # Step 3: 符号覆盖与公式结构校验
    if re.search(pattern_inverse, pred):
        return {'result': 'fail', 'message': '折射率定义公式颠倒，混淆了真空波长与介质波长的比例关系', 'evidence': re.search(pattern_inverse, pred).group()}

    if re.search(pattern_correct, pred):
        return {'result': 'pass', 'message': '折射率与波长定义关系表述正确', 'evidence': re.search(pattern_correct, pred).group()}

    # 如果提到了波长变化但没有明确公式，检查描述性文字
    if '介质' in pred and '波长' in pred and ('变短' in pred or '减少' in pred or 'smaller' in pred):
        if 'n' in pred:
            return {'result': 'pass', 'message': '定性描述符合折射率定义', 'evidence': '介质中波长变短'}

    return {'result': 'inconclusive', 'message': '未能明确识别折射率定义的公式结构', 'evidence': prediction[:100]}

# rule_id=norm_50e8811e8c670761 | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_50e8811e8c670761 | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_50e8811e8c670761_613cf2cf9b18(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及建筑物照片、相机高度或位置估计
    trigger_keywords = ['相机高度', '摄影高度', '拍摄高度', 'camera height', 'vanishing point', '消失点', '地平线', 'horizon']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '题目未涉及透视投影高度判定场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否利用了消失点（Vanishing Point）或地平线（Horizon）的概念
    pred_lower = prediction.lower()
    logic_keywords = ['消失点', '地平线', 'vanishing', 'horizon', '汇聚', 'converge']
    if not any(kw in pred_lower for kw in logic_keywords):
        return {'result': 'fail', 'message': '未利用平行线消失点或地平线进行建模分析', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查是否包含高度比例公式 h = H * (y_h - y_b) / (y_t - y_b)
    # 匹配 y_horizon, y_base, y_top 相关的比例关系
    formula_patterns = [
        r'h.*=.*H.*\(.*y.*-.*y.*\).*/.*\(.*y.*-.*y.*\)',
        r'高度.*比例.*地平线',
        r'y_horizon|y_base|y_top',
        r'\(y_h - y_b\) / \(y_t - y_b\)'
    ]

    found_formula = False
    for pattern in formula_patterns:
        if re.search(pattern, pred_lower) or re.search(pattern, prediction):
            found_formula = True
            break

    if found_formula:
        return {'result': 'pass', 'message': '正确应用了透视投影高度判定准则及比例公式', 'evidence': prediction[:200]}

    # 如果提到了地平线但没有明确的比例计算，保守返回 inconclusive
    return {'result': 'inconclusive', 'message': '虽提及透视概念但未见明确的高度比例计算公式', 'evidence': prediction[:200]}

# rule_id=norm_7c1ecfb82e902965 | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_7c1ecfb82e902965 | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_7c1ecfb82e902965_c892148cec2d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及小孔/透光孔径及成像位置计算
    trigger_keywords = ['small light-transmitting circular aperture', '小孔', '透光孔', 'aperture']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到小孔或透光孔径相关场景', 'evidence': ''}

    if 'image' not in (question + context).lower() and '成像' not in (question + context):
        return {'result': 'inconclusive', 'message': '未检测到成像位置计算要求', 'evidence': ''}

    # Step 2: 检查逻辑 — 判定是否考虑了前级像点落在后级元件特定位置（直通判定）
    # 检查 prediction 是否直接进行了复杂的反射/折射计算而忽略了直通几何关系
    pred_lower = prediction.lower()
    pass_through_indicators = ['vertex', 'center', 'straight', 'directly', '落在', '顶点', '中心', '直通']

    # 如果预测中完全没有提到像点与后级元件位置的关系，且直接套用透镜/面镜公式，可能存在建模错误
    has_geometric_check = any(indicator in pred_lower for indicator in pass_through_indicators)

    # Step 3: 校验推理过程
    if not has_geometric_check:
        # 检查是否在没有判断位置的情况下直接使用了 1/u + 1/v = 1/f 等公式
        if re.search(r'1/f|1/u|1/v|lens formula|mirror formula', pred_lower):
            return {
                'result': 'fail',
                'message': '模型可能忽略了孔径直通成像的几何判定，直接进行了复杂的折射/反射计算',
                'evidence': prediction[:200]
            }
        return {'result': 'inconclusive', 'message': '推理过程中未体现孔径位置判定逻辑', 'evidence': ''}

    # 如果提到了位置关系且给出了合理的直通结论
    if re.search(r'(pass|through|coincide|origin|vertex)', pred_lower):
        return {
            'result': 'pass',
            'message': '模型考虑了孔径直通或特定位置成像的几何关系',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '证据不足以判定建模是否正确', 'evidence': ''}

# rule_id=norm_8b3cb9edd3fb5866 | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_8b3cb9edd3fb5866 | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_8b3cb9edd3fb5866_d5587f275465(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“线光源”在“屏幕”上形成的“最小光斑”
    trigger_keywords = ['线光源', '最小光斑', '光斑最小', '屏幕', '光屏']
    if not all(k in (question + context) for k in ['线光源', '最小']):
        return {'result': 'inconclusive', 'message': '未检测到线光源最小光斑相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否直接套用成像公式（错误建模）还是建立了几何包络/直径函数（正确建模）
    # 错误倾向：直接用 1/u + 1/v = 1/f 找像点位置作为最小光斑位置
    # 正确倾向：考虑边缘光线、相似三角形、直径函数 d(x) 或 y(x)
    pred_lower = prediction.lower()

    # 检查是否包含几何包络或直径函数的建模迹象
    modeling_keywords = ['相似三角形', '边缘光线', '包络', '直径', 'd(x)', 'y1', 'y2', '几何关系']
    has_modeling = any(k in pred_lower for k in modeling_keywords)

    # 检查是否包含关键符号 D, L, f, u
    required_symbols = ['D', 'L', 'f', 'u']
    symbol_count = sum(1 for s in required_symbols if s in prediction)

    # Step 3: 判定结果
    # 如果只用了成像公式而没有几何分析，则判定为建模错误
    if '1/u' in pred_lower and '1/v' in pred_lower and not has_modeling:
        return {
            'result': 'fail',
            'message': '禁止直接套用成像公式找像点，需建立边缘光线围成的几何包络直径函数进行分析。',
            'evidence': prediction[:200]
        }

    # 如果体现了直径函数或相似三角形分析，且符号覆盖度高，则 pass
    if has_modeling or re.search(r'[Dd]\(x\)|max\(|min\(', pred_lower):
        return {
            'result': 'pass',
            'message': '已建立几何包络或直径函数进行极值建模。',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '无法确定是否采用了正确的几何建模方法', 'evidence': ''}

# rule_id=norm_ae002630b9347759 | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_ae002630b9347759 | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_ae002630b9347759_473b0170673b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及透镜/面镜成像及高斯公式
    trigger_keywords = ['透镜', '面镜', '成像', 'lens', 'mirror', 'focal length']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到透镜或面镜成像场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别使用的公式形式 (1/u + 1/v = 1/f 或 1/v - 1/u = 1/f)
    # 匹配 1/u + 1/v = 1/f 及其变体
    plus_pattern = r'1/u\s*\+\s*1/v\s*=\s*1/f|1/v\s*\+\s*1/u\s*=\s*1/f'
    # 匹配 1/v - 1/u = 1/f 及其变体
    minus_pattern = r'1/v\s*-\s*1/u\s*=\s*1/f'

    pred_text = prediction.replace(' ', '')
    has_plus = re.search(plus_pattern, pred_text, re.IGNORECASE)
    has_minus = re.search(minus_pattern, pred_text, re.IGNORECASE)

    if not (has_plus or has_minus):
        return {'result': 'inconclusive', 'message': '未在推理中检测到标准形式的高斯公式', 'evidence': ''}

    # Step 3: 符号约定一致性检查
    # 如果使用 1/u + 1/v = 1/f，通常要求 u 为正值（实物距离）
    if has_plus:
        # 查找 u 的赋值，例如 u=10 或 u = 10
        u_val_match = re.search(r'u\s*=\s*(-?\d+\.?\d*)', prediction)
        if u_val_match:
            u_val = float(u_val_match.group(1))
            if u_val < 0:
                return {
                    'result': 'fail',
                    'message': '符号约定冲突：使用 1/u+1/v=1/f 形式时，实物距离 u 应取正值，但检测到 u 为负数',
                    'evidence': u_val_match.group(0)
                }
            else:
                return {'result': 'pass', 'message': '公式形式与物距符号约定一致', 'evidence': u_val_match.group(0)}

    # 如果使用 1/v - 1/u = 1/f，通常 u 带有坐标方向（实物在左侧时 u 为负）
    if has_minus:
        u_val_match = re.search(r'u\s*=\s*(-?\d+\.?\d*)', prediction)
        if u_val_match:
            u_val = float(u_val_match.group(1))
            # 如果 u 是正的，但在减法公式里，可能存在符号定义混淆（取决于具体坐标系，此处保守处理）
            if u_val > 0:
                return {
                    'result': 'fail',
                    'message': '符号约定潜在冲突：使用 1/v-1/u=1/f 形式时，若 u 为物距坐标，实物通常应为负值',
                    'evidence': u_val_match.group(0)
                }

    return {'result': 'inconclusive', 'message': '无法确定符号约定是否匹配', 'evidence': ''}

# rule_id=norm_b3536c94bf9118a7 | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_b3536c94bf9118a7 | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_b3536c94bf9118a7_19f81f9969bc(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否要求“距离透镜某长度”而非特定坐标点
    # 匹配关键词如“距离透镜”、“离透镜”、“距透镜”等，且不含明确的坐标轴定义
    trigger_keywords = ['距离透镜', '离透镜', '距透镜', 'distance from the lens', 'away from the lens']
    is_triggered = any(kw in question for kw in trigger_keywords)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '题目未明确要求基于距离的定位，不触发多解性检查', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否考虑了两种几何排布（实物/虚物，或透镜两侧）
    # 寻找体现“两种情况”、“两个位置”、“或”、“两种可能”的表述
    pred_lower = prediction.lower()
    multi_case_keywords = ['两种情况', '两种可能', '两个位置', '两个解', 'two cases', 'two possibilities', 'two positions', 'either', ' or ']
    has_multi_case = any(kw in pred_lower for kw in multi_case_keywords)

    # Step 3: 符号/公式校验 — 检查是否包含绝对值等价关系或距离差值公式
    # 对应 symbolic_hint: |d - v_1| = |v_{final} - d|
    has_abs_logic = re.search(r'abs\(|\|.*\|', prediction) or '绝对值' in prediction

    # 综合判定
    if has_multi_case:
        return {'result': 'pass', 'message': '模型考虑了光学系统的多解性或多种几何排布', 'evidence': prediction[:200]}

    # 如果明确只给出了一个解，且没有讨论其他可能性，则判定为 fail
    # 检查是否只存在单一的 v = ... 或 x = ... 而没有分类讨论
    if not has_multi_case and not has_abs_logic:
        return {'result': 'fail', 'message': '题目要求距离透镜某长度，但模型未讨论多解性（如透镜两侧或实虚物不同情况）', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否充分讨论了所有几何可能性', 'evidence': ''}

# rule_id=norm_cb836cbb51b39226 | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_cb836cbb51b39226 | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_cb836cbb51b39226_e76c14e2afcd(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多个光学元件（透镜、反射镜）串联成像
    trigger_keywords = ['透镜', '反射镜', 'lens', 'mirror', '组合', '串联', '系统']
    combined_text = (question + context).lower()
    # 统计元件出现次数或关键词匹配
    lens_count = len(re.findall(r'透镜|lens|镜', combined_text))
    if lens_count < 1 and not any(kw in combined_text for kw in ['光学系统', 'optical system']):
        return {'result': 'inconclusive', 'message': '未检测到多元件光学系统场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 校验各元件间的相对距离与成像位置的代数和关系
    # 重点检查是否混淆了物距 u、像距 v 与元件间距 d 的关系
    pred = prediction.lower()
    # 检查是否包含位置链相关的符号或描述
    pos_keywords = ['距离', '间距', '坐标', '位置', 'distance', 'position', 'coordinate']
    if not any(kw in pred for kw in pos_keywords):
        return {'result': 'fail', 'message': '推理过程中未明确讨论元件间距与成像位置的几何关系', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查 x_image = x_lens + v 或类似的位置链表达
    # 匹配类似 x = x0 + v 或 d = v + u 的结构
    # 同时也检查是否错误地将物距直接等同于间距（例如 d = u 而非 d = v + u）
    pattern_pos_chain = r'([xv]\s*[=+]|[dx]\s*=\s*[xv])'
    if not re.search(pattern_pos_chain, pred):
        # 如果没有明确的代数式，检查是否有描述性文字
        if '成像位置' not in pred and '像点' not in pred:
            return {'result': 'fail', 'message': '未建立成像位置与元件位置的代数关联', 'evidence': prediction[:200]}

    # 检查 canonical 要求的符号覆盖
    required_symbols = ["v", "x"] # 简化匹配 x_image, x_lens
    missing_symbols = [s for s in required_symbols if s not in pred]
    if len(missing_symbols) == len(required_symbols):
        return {'result': 'inconclusive', 'message': '缺乏必要的物理量符号进行位置链校验', 'evidence': prediction[:100]}

    # 若存在类似 x_lens + v 的逻辑结构则视为通过
    if re.search(r'[xv]\s*[\+\-]\s*[xv]', pred) or '坐标' in pred:
        return {'result': 'pass', 'message': '已执行光学系统位置链校验', 'evidence': re.search(r'.{0,50}[xv]\s*[\+\-]\s*[xv].{0,50}', pred).group(0) if re.search(r'[xv]\s*[\+\-]\s*[xv]', pred) else '包含坐标逻辑'}

    return {'result': 'inconclusive', 'message': '证据不足以判定位置链逻辑是否正确', 'evidence': ''}

# rule_id=norm_ce1a8c8d8997cfd2 | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_ce1a8c8d8997cfd2 | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_ce1a8c8d8997cfd2_ea1dd5b4d7d9(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题干是否包含具体的实验器材参数（波长、距离、条纹等）
    # 匹配如 632.8nm, 500nm, 1.2m, 0.5mm, 亮条纹, 峰值等关键词
    params_pattern = r'(\d+(\.\d+)?\s*(nm|um|mm|m|cm|Hz|THz))|(波长|条纹|间距|距离|峰值)'
    if not re.search(params_pattern, question + context):
        return {'result': 'inconclusive', 'message': '未检测到具体的实验器材参数或物理常量', 'evidence': ''}

    # Step 2: 提取题干中的关键数值常量（如波长、距离数值）
    # 简单提取数值+单位组合作为约束项
    constants = re.findall(r'(\d+(\.\d+)?)\s*(nm|um|mm|m|cm)', question + context)
    if not constants:
        return {'result': 'inconclusive', 'message': '未能提取到明确的物理常量数值', 'evidence': ''}

    # Step 3: 检查逻辑 — 核对解题步骤是否消耗了这些常量
    # 如果 prediction 中完全没有出现题干中提到的数值，则认为建模缺失约束
    missing_constants = []
    for val_tuple in constants:
        val_str = val_tuple[0]
        # 检查数值是否在预测推理中出现（允许一定格式差异）
        if val_str not in prediction:
            missing_constants.append(val_str)

    # 如果超过一半的物理常量在推理中未被提及，判定为建模缺失关键约束
    if len(missing_constants) > 0 and len(missing_constants) >= len(constants) * 0.5:
        return {
            'result': 'fail',
            'message': f'解题步骤未充分利用题干给出的物理常量: {missing_constants}，建模可能缺失关键物理约束。',
            'evidence': f'题干常量: {constants}, 预测文本片段: {prediction[:200]}'
        }

    # Step 4: 若数值有被引用，则初步判定通过
    if len(missing_constants) == 0:
        return {'result': 'pass', 'message': '解题步骤已引用题干给出的物理常量', 'evidence': f'匹配到的常量: {constants}'}

    return {'result': 'inconclusive', 'message': '部分常量未显式体现，证据不足以判定失败', 'evidence': ''}

# rule_id=norm_e6663c627da63a13 | domain=Optics | topic=Laws of Mirrors and Lenses
# rule_id=norm_e6663c627da63a13 | domain=Optics | topic=Laws of Mirrors and Lenses
def check_norm_e6663c627da63a13_7cb93ca2e905(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“物像间距”及“球面镜/透镜”
    trigger_keywords = ['物像间距', 'distance between object and image', 'distance between the object and its image']
    optics_keywords = ['镜', '透镜', 'mirror', 'lens', 'concave', 'convex']

    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and any(kw in combined_text for kw in optics_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到物像间距相关的光学建模场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否区分了实像与虚像的间距建模逻辑
    # 实像通常满足 L = |u - v| 或 u + v (当u,v同号定义时)，虚像通常为 |u| + |v| 或 |u - v| (带符号)
    pred_lower = prediction.lower()

    # 检查是否提到了像的性质（实像/虚像）
    has_image_type = any(kw in pred_lower for kw in ['实像', '虚像', 'real image', 'virtual image'])

    # 检查公式建模特征：是否包含 L, u, v 的线性组合关系
    # 匹配类似 L = u + v, L = v - u, L = |u-v| 等形式
    modeling_pattern = r'[Ll]\s*=\s*|u|\s*[\+\-]\s*|v|'
    has_modeling = re.search(r'[uv]\s*[\+\-]\s*[uv]', pred_lower) or 'distance' in pred_lower

    if not has_image_type and not re.search(r'u\s*[\+\-]\s*v', pred_lower):
        return {'result': 'fail', 'message': '在计算物像间距时，未明确区分实像与虚像的几何建模关系', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验
    # 如果是虚像，通常建模为 u+v (绝对值相加) 或 v-u (坐标差)
    # 如果是实像，通常建模为 u-v 或 v-u
    if 'virtual' in pred_lower or '虚像' in pred_lower:
        if not re.search(r'u\s*\+\s*v|v\s*\-\s*u|abs', pred_lower):
            return {'result': 'fail', 'message': '虚像情境下的物像间距建模可能存在符号错误', 'evidence': prediction[:200]}

    if re.search(r'[Ll]\s*=\s*abs\(u\s*-\s*v\)', pred_lower) or re.search(r'[Ll]\s*=\s*\|u\s*-\s*v\|', pred_lower):
        return {'result': 'pass', 'message': '正确使用了通用的物像间距几何建模公式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '已提及相关概念，但建模公式的严谨性需人工确认', 'evidence': prediction[:200]}

# rule_id=norm_aec2c6d09fcdb5f5 | domain=Optics | topic=Optical Instruments (Microscopes, Telescopes)
# rule_id=norm_aec2c6d09fcdb5f5 | domain=Optics | topic=Optical Instruments (Microscopes, Telescopes)
def check_norm_aec2c6d09fcdb5f5_ebbc6bfeac32(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否同时涉及望远镜焦距(f0, fe)与人眼分辨率(beta)
    # 匹配 f0, fe, f_0, f_e 以及 beta 或人眼分辨率/张角等关键词
    trigger_keywords = ['f_0', 'f0', 'f_e', 'fe', '焦距']
    res_keywords = ['beta', 'β', '人眼', '分辨率', '张角']

    q_c = (question + context).lower()
    has_f = any(k in q_c for k in trigger_keywords)
    has_beta = any(k in q_c for k in res_keywords)

    if not (has_f and has_beta):
        return {'result': 'inconclusive', 'message': '未检测到望远镜焦距与人眼分辨率的组合场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否计算了放大率 M = f0/fe 并应用 alpha = beta / M
    pred = prediction.lower()

    # 检查放大率公式 M = f0/fe 的变体
    magnification_pattern = r'(m\s*=\s*f_?0\s*/\s*f_?e|f_?0\s*/\s*f_?e)'
    # 检查目标张角公式 alpha = beta / M 或 alpha = beta * fe / f0
    resolution_pattern = r'(\alpha|alpha)\s*=\s*(\beta|beta)\s*/\s*m|(\alpha|alpha)\s*=\s*(\beta|beta)\s*\*\s*f_?e\s*/\s*f_?0'

    has_m = re.search(magnification_pattern, pred)
    has_alpha_calc = re.search(resolution_pattern, pred)

    # Step 3: 判定结果
    if has_m and has_alpha_calc:
        return {'result': 'pass', 'message': '正确应用了放大率对分辨率的转换公式', 'evidence': re.search(resolution_pattern, pred).group(0)}

    # 如果直接使用了 beta 而没有除以 M，则判定为建模错误
    if re.search(r'(\alpha|alpha)\s*=\s*(\beta|beta)', pred) and not has_m:
        return {'result': 'fail', 'message': '建模错误：直接使用了人眼分辨率 beta，未考虑望远镜放大率对张角的缩放', 'evidence': 'alpha = beta'}

    return {'result': 'inconclusive', 'message': '推理过程中未显式展示分辨率转换逻辑', 'evidence': ''}

# rule_id=norm_09ff58e6318938be | domain=Optics | topic=Snell's Law and Critical Angle
# rule_id=norm_09ff58e6318938be | domain=Optics | topic=Snell's Law and Critical Angle
def check_norm_09ff58e6318938be_cbfbc6172891(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及水下物体（如西瓜、球体）的密度估计或折射率 n
    trigger_keywords = ['水下', '折射率', 'n', 'underwater', 'refractive index', 'submerged']
    object_keywords = ['西瓜', '球', 'watermelon', 'sphere', 'object']
    combined_text = (question + context).lower()

    is_triggered = any(kw in combined_text for kw in trigger_keywords) and any(kw in combined_text for kw in object_keywords)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到水下物体折射修正场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否区分了垂直视深与径向/斜向位移修正，以及是否建立了 R_obs 与 R_real 的关联
    pred = prediction.lower()
    # 检查是否提到视深(apparent depth)或径向位移(radial displacement)
    has_correction_logic = any(kw in pred for kw in ['视深', 'apparent depth', '修正', 'correction', 'displacement', '位移'])
    # 检查是否建立了观测半径与真实半径的关联
    has_radius_relation = 'r_obs' in pred or 'r_real' in pred or '观测半径' in pred or '真实半径' in pred

    if not (has_correction_logic or has_radius_relation):
        return {'result': 'fail', 'message': '未体现水下物体的几何修正逻辑，需区分视深与径向位移', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 n, R_obs, h 等符号及折射定律公式结构
    required_symbols = ['n', 'r_obs', 'h']
    missing_symbols = [sym for sym in required_symbols if sym not in pred]

    # 检查折射定律基本形式 n = sin(theta_air) / sin(theta_water)
    snell_pattern = r'n\s*=\s*sin\(.*\)\s*/\s*sin\(.*\)'
    has_snell = re.search(snell_pattern, pred) is not null

    if len(missing_symbols) >= 2:
        return {'result': 'fail', 'message': f'缺少关键物理符号: {missing_symbols}', 'evidence': prediction[:200]}

    if has_snell or ('r_obs' in pred and 'n' in pred):
        return {'result': 'pass', 'message': '建立了折射关联并使用了正确的物理建模', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑要素不完整，无法判定', 'evidence': ''}

# rule_id=norm_2aaa9c41983d96df | domain=Optics | topic=Snell's Law and Critical Angle
# rule_id=norm_2aaa9c41983d96df | domain=Optics | topic=Snell's Law and Critical Angle
def check_norm_2aaa9c41983d96df_d5a6c54c54de(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及非均匀介质（折射率随坐标变化）及斜向传播
    # 匹配如 n=n0/(1-x/R), n(x), n(y), gradient index 等描述
    trigger_keywords = ['折射率', 'n=', 'n(', 'index', 'gradient', '非均匀']
    q_c_text = (question + context).lower()
    is_inhomogeneous = any(k in q_c_text for k in trigger_keywords) and re.search(r'n[\(=].*[xyzr]', q_c_text)

    if not is_inhomogeneous:
        return {'result': 'inconclusive', 'message': '未检测到非均匀介质折射场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否应用了 n*sin(theta) = Constant 的守恒律
    pred = prediction.lower()
    # 匹配 n*sin(theta) 或 n1*sin1=n2*sin2 的变体
    snell_pattern = r'n.*sin\s*\(?θ|n.*sin\s*\(?theta|n\(x\).*sin|n_0.*sin'
    has_snell_law = re.search(snell_pattern, pred)

    # 检查是否提到常数或守恒关系
    has_constant = any(k in pred for k in ['constant', '常数', '守恒', '不变', 'fixed'])

    if not (has_snell_law or has_constant):
        return {
            'result': 'fail',
            'message': '在非均匀介质计算中未体现 n(x)sinθ(x) = Constant 的守恒逻辑',
            'evidence': prediction[:200]
        }

    # Step 3: 符号校验 — 检查 canonical 形式的公式结构
    # 匹配 n*sin(theta) = n0*sin(theta0) 类似的等式结构
    canonical_pattern = r'n.*sin.*=.*n.*sin'
    if re.search(canonical_pattern, pred):
        return {
            'result': 'pass',
            'message': '正确应用了非均匀介质斯涅尔定律推广形式',
            'evidence': re.search(canonical_pattern, pred).group()
        }

    return {'result': 'inconclusive', 'message': '检测到相关物理量但公式表达不完整', 'evidence': prediction[:150]}

# rule_id=norm_46dce415ac07dcad | domain=Optics | topic=Snell's Law and Critical Angle
# rule_id=norm_46dce415ac07dcad | domain=Optics | topic=Snell's Law and Critical Angle
def check_norm_46dce415ac07dcad_6810c5e57fa5(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及负折射率材料 (epsilon < 0, mu < 0 或明确提及负折射率)
    trigger_keywords = ['负折射率', 'negative refractive index', 'negative index', 'left-handed material', '左手材料']
    is_negative_params = re.search(r'ε_?r\s*<\s*0|mu_?r\s*<\s*0|epsilon_?r\s*<\s*0', question + context)
    is_triggered = any(kw in (question + context).lower() for kw in trigger_keywords) or is_negative_params

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '题目未涉及负折射率材料场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否应用了负折射率 (n < 0) 及其导致的同侧折射效应
    pred = prediction.lower()
    # 检查是否提到 n 为负值或折射率为负
    has_negative_n = re.search(r'n\s*<\s*0|n\s*=\s*-[0-9.]+|折射率(取|为)负', pred)
    # 检查是否提到折射光线与入射光线位于法线同侧 (same side of the normal)
    has_same_side = any(kw in pred for kw in ['同侧', 'same side', 'negative angle', '负角度'])

    # Step 3: 符号与公式校验 (Snell\'s Law with n < 0)
    has_snell_logic = re.search(r'n1.*sin.*n2.*sin', pred) or 'snell' in pred

    if has_negative_n and (has_same_side or has_snell_logic):
        return {'result': 'pass', 'message': '正确识别并应用了负折射率的折射准则', 'evidence': re.search(r'.{0,50}(n\s*<\s*0|同侧|same side).{0,50}', pred).group(0) if has_negative_n else ''}

    if not has_negative_n and ('snell' in pred or '折射' in pred):
        return {'result': 'fail', 'message': '在负折射率材料计算中未明确折射率取负值或忽略了同侧折射特性', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程中关于负折射率的处理描述不详', 'evidence': ''}

# rule_id=norm_59f5fe67253f3950 | domain=Optics | topic=Snell's Law and Critical Angle
# rule_id=norm_59f5fe67253f3950 | domain=Optics | topic=Snell's Law and Critical Angle
def check_norm_59f5fe67253f3950_79427f18c77a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及声速/折射率随坐标线性变化（c = c0 + bz）及水平位移求解
    trigger_keywords = ['linear', 'gradient', 'c0', 'bz', 'z', 'depth', 'velocity', 'refractive index', '线性', '梯度', '随', '变化']
    content_to_check = (question + context).lower()
    is_triggered = any(kw in content_to_check for kw in trigger_keywords) and ('horizontal' in content_to_check or 'displacement' in content_to_check or '水平' in content_to_check)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到线性梯度介质或水平位移求解场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否识别出轨迹为圆弧 (arc/circle) 并利用 Snell 定律
    pred = prediction.lower()
    has_arc = any(kw in pred for kw in ['arc', 'circle', 'circular', '圆弧', '圆轨迹'])
    has_snell = any(kw in pred for kw in ['snell', '斯涅尔', 'law of refraction'])

    if not (has_arc or has_snell):
        return {'result': 'fail', 'message': '未利用 Snell 定律推导圆弧轨迹，可能错误使用了线性积分', 'evidence': prediction[:200]}

    # Step 3: 公式校验 — 检查关键几何关系 R = c / (b * cos(theta)) 的结构
    # 匹配 R, c, b, cos, theta 等符号的组合
    formula_pattern = r'R\s*=\s*c[0]?\s*/\s*\(\s*b\s*\*?\s*cos\s*\(\s*theta[0]?\s*\)\s*\)'
    # 简化匹配：检查是否包含 R, b, cos, theta 且存在除法关系
    simplified_pattern = r'R.*=.*c.*/.*b.*cos.*theta'

    if re.search(formula_pattern, pred, re.IGNORECASE) or re.search(simplified_pattern, pred, re.IGNORECASE):
        return {'result': 'pass', 'message': '成功识别圆弧轨迹并使用了正确的几何简化公式', 'evidence': re.search(r'R.*=.*', pred).group(0) if re.search(r'R.*=.*', pred) else prediction[:100]}

    # 如果提到了圆弧但公式不完整，保守返回 inconclusive
    if has_arc:
         return {'result': 'inconclusive', 'message': '识别出圆弧轨迹但未见明确的简化公式 R = c/(b*cos(theta))', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足以判定建模方式', 'evidence': ''}

# rule_id=norm_6b2d7cd9047fc1a4 | domain=Optics | topic=Snell's Law and Critical Angle
# rule_id=norm_6b2d7cd9047fc1a4 | domain=Optics | topic=Snell's Law and Critical Angle
def check_norm_6b2d7cd9047fc1a4_59a05d7de864(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否提供了具体的实验器材清单
    # 匹配常见的实验器材关键词，如卡尺、量筒、天平、刻度尺、半圆形玻璃砖等
    equipment_keywords = ['卡尺', '游标卡尺', '螺旋测微器', '量筒', '天平', '刻度尺', '直尺', '玻璃砖', '棱镜', '光源', '激光器']
    has_equipment = any(kw in (question + context) for kw in equipment_keywords)
    if not has_equipment:
        return {'result': 'inconclusive', 'message': '题目未提供具体的实验器材清单', 'evidence': ''}

    # Step 2: 提取题目中的核心量具/器材
    # 重点关注具有特定测量功能的器材，如卡尺（测直径/厚度）
    found_tools = []
    for tool in ['卡尺', '游标卡尺', '螺旋测微器']:
        if tool in (question + context):
            found_tools.append(tool)

    # Step 3: 检查预测步骤是否消耗/使用了这些核心器材
    # 如果题目给了卡尺但预测中完全没有提到测量直径、厚度或使用卡尺，则可能建模错误
    pred_text = prediction.lower()
    if '卡尺' in found_tools or '游标卡尺' in found_tools:
        usage_keywords = ['测量', '直径', '厚度', '宽度', '卡尺', '读数']
        has_usage = any(uk in pred_text for uk in usage_keywords)
        if not has_usage:
            return {
                'result': 'fail',
                'message': '预测步骤未利用题目提供的核心量具（如卡尺），建模可能忽略了实验约束',
                'evidence': f"题目器材: {found_tools}, 预测内容片段: {prediction[:150]}"
            }

    # Step 4: 验证预测逻辑与器材的匹配度
    # 若预测中提到了使用器材或相关的测量动作，则视为通过
    if any(tool in pred_text for tool in equipment_keywords):
        return {'result': 'pass', 'message': '预测步骤包含了对实验器材的使用或描述', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '无法明确判断器材使用逻辑是否缺失', 'evidence': ''}

# rule_id=norm_8b85803b6f06013f | domain=Optics | topic=Snell's Law and Critical Angle
# rule_id=norm_8b85803b6f06013f | domain=Optics | topic=Snell's Law and Critical Angle
def check_norm_8b85803b6f06013f_265e9c1198bb(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 折射率 n(z) 为分段函数定义时
    # 匹配类似于 n(z) 的分段折射率描述，或题目明确提到分段折射率、z=h 等边界
    q_c_text = (question + ' ' + context).lower()
    trigger_keywords = ['分段', 'piecewise', 'n(z)', '折射率', 'refractive index']
    has_trigger = any(kw in q_c_text for kw in trigger_keywords) and ('z' in q_c_text or 'y' in q_c_text)
    if not has_trigger:
        return {'result': 'inconclusive', 'message': '未检测到分段折射率相关物理场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须分区域讨论光路，并确保在边界处位置和斜率连续
    pred = prediction.lower()

    # 检查是否包含边界连续性相关的关键词（如连续、continuous、boundary、边界、斜率、slope 等）
    has_continuity = any(kw in pred for kw in ['连续', 'continuous', '边界', 'boundary', 'slope', '斜率', 'dz/dx', 'dx/dz', 'derivatives'])
    # 检查是否包含直线/曲线（或常数区、梯度区）等运动轨迹分解的讨论
    has_trajectory = any(kw in pred for kw in ['直线', 'straight', '曲线', 'curve', '抛物线', 'parabolic', '常数', '梯度', 'gradient', 'constant'])

    if not has_continuity:
        return {'result': 'fail', 'message': '未在预测中找到关于边界处位置或斜率连续性的讨论', 'evidence': prediction[:200]}
    if not has_trajectory:
        return {'result': 'fail', 'message': '未在预测中找到关于不同区域（常数区/梯度区）光路轨迹形状的分类讨论', 'evidence': prediction[:200]}

    # Step 3: 进一步利用正则匹配边界处的斜率或位置相等的表达式（如 z=h, x(h), dz/dx 连续等）
    if re.search(r'(z\s*=\s*[hH]|h\s*=\s*z|连续|continuous)', pred):
        return {'result': 'pass', 'message': '已按要求分区域讨论光路并考虑了边界处的连续性条件', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '未找到足够的证据确认边界连续性计算的正确性', 'evidence': prediction[:100]}

# rule_id=norm_b6191ba7923b1108 | domain=Optics | topic=Snell's Law and Critical Angle
# rule_id=norm_b6191ba7923b1108 | domain=Optics | topic=Snell's Law and Critical Angle
def check_norm_b6191ba7923b1108_84454692381e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否要求使用费马原理推导反射或折射定律
    trigger_keywords = ['费马原理', "Fermat's principle", 'Fermat principle']
    target_keywords = ['推导', 'derivation', 'derive', 'law of reflection', 'law of refraction', 'Snell', '折射定律', '反射定律']

    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and any(kw in combined_text for kw in target_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到费马原理推导折射/反射定律的相关要求', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了光程/时间函数并求导
    pred = prediction.lower()
    # 检查是否包含光程函数 L 或时间函数 t 的表达 (n1*L1 + n2*L2)
    path_func_pattern = r'(n1.*\+.*n2|n1.*sqrt|n2.*sqrt|l\(x\)|t\(x\))'
    # 检查是否包含求导并令其为零的操作
    derivative_pattern = r'(d/dx|d[lt]/dx|derivative|求导|等于0|=.*0)'

    if not re.search(path_func_pattern, pred) or not re.search(derivative_pattern, pred):
        return {
            'result': 'fail',
            'message': '未检测到建立光程函数或对坐标求导令其为零的建模过程',
            'evidence': prediction[:200]
        }

    # Step 3: 符号与公式结构校验 — 检查 n1, n2, theta1, theta2 以及导数项与 sin 的对应关系
    required_symbols = ['n1', 'n2', 'theta1', 'theta2']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    # 检查导数项是否对应 sin(theta) 的几何定义 (x/sqrt(a^2+x^2) -> sin)
    sin_relation_pattern = r'(sin.*theta|x/sqrt|x/l1|x/l2)'

    if len(missing_symbols) > 2: # 允许部分符号差异，但不能缺失过多
        return {
            'result': 'fail',
            'message': f'缺少关键物理符号: {missing_symbols}',
            'evidence': prediction[:200]
        }

    if not re.search(sin_relation_pattern, pred):
        return {
            'result': 'fail',
            'message': '未能在导数项中体现 sin(theta) 的几何关系',
            'evidence': prediction[:200]
        }

    # 如果包含核心公式结构，则判定为 pass
    if re.search(r'n1.*sin.*=.*n2.*sin', pred) or re.search(r'd.*dx.*=.*0', pred):
        return {'result': 'pass', 'message': '费马原理推导逻辑完整，包含函数建立、求导及几何对应', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推导过程不完整或证据不足', 'evidence': ''}

# rule_id=norm_c033a89a5f52cabf | domain=Optics | topic=Snell's Law and Critical Angle
# rule_id=norm_c033a89a5f52cabf | domain=Optics | topic=Snell's Law and Critical Angle
def check_norm_c033a89a5f52cabf_86acbdb23816(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及变分法、Beltrami恒等式或欧拉-拉格朗日方程
    trigger_keywords = ['beltrami', 'euler-lagrange', 'variational', '变分', '欧拉-拉格朗日', '恒等式']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到变分法或Beltrami恒等式相关场景', 'evidence': ''}

    # Step 2: 检查预测中是否引入了待定常数 C 或类似符号，并核对 Beltrami 结构
    # 典型结构: L - y' * dL/dy' = C
    pred = prediction.lower()
    beltrami_pattern = r"l\s*-\s*y'\s*\*?\s*\(?d[lL]/dy'\)?\s*=\s*[cCkK]"
    has_beltrami = re.search(beltrami_pattern, pred) or 'constant' in pred or '常数' in pred

    if not has_beltrami:
        return {'result': 'inconclusive', 'message': '预测中未显式展示Beltrami恒等式的常数推导过程', 'evidence': ''}

    # Step 3: 检查常数项的物理意义一致性（如折射率 n 或速度 v 的倒数）
    # 在光学最速降线问题中，常数通常与 n(y) 或 1/v(y) 相关
    consistency_keywords = ['refractive index', 'velocity', 'speed', '折射率', '速度', '倒数']
    has_consistency = any(kw in pred for kw in consistency_keywords)

    # 检查符号覆盖 (C, L, y')
    required_symbols = ['c', 'l', "y'"]
    missing_symbols = [s for s in required_symbols if s not in pred]

    if len(missing_symbols) > 1:
        return {'result': 'fail', 'message': '推导中缺失关键符号或常数定义不明确', 'evidence': f'缺失符号: {missing_symbols}'}

    if 'constant' in pred and not has_consistency:
        return {'result': 'fail', 'message': '引入常数但未核对物理意义（如折射率或速度关系）', 'evidence': prediction[-200:]}

    if has_beltrami and has_consistency:
        return {'result': 'pass', 'message': '常数定义与物理背景（折射率/速度）匹配一致', 'evidence': '检测到Beltrami结构及物理量关联'}

    return {'result': 'inconclusive', 'message': '证据不足以判定常数定义是否完全一致', 'evidence': ''}

# rule_id=norm_d1ce729aed00e574 | domain=Optics | topic=Snell's Law and Critical Angle
# rule_id=norm_d1ce729aed00e574 | domain=Optics | topic=Snell's Law and Critical Angle
def check_norm_d1ce729aed00e574_70da0dde9e3c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及圆柱/球体介质及光信号到达判定
    trigger_keywords = ['圆柱', '球体', 'cylinder', 'sphere', '介质', '光信号', '接收', '到达']
    content_to_check = (question + context).lower()
    is_triggered = any(kw in content_to_check for kw in trigger_keywords) and ('光' in content_to_check or 'light' in content_to_check)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到圆柱/球体介质的光学接收域场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否包含边界光线追踪（切线、临界角）或几何不等式建立
    pred_lower = prediction.lower()
    # 检查是否提到边界条件：切线、临界角、边缘、恰好
    boundary_terms = ['切线', '临界角', 'critical angle', 'tangent', '边缘', 'boundary', 'edge']
    has_boundary_logic = any(term in pred_lower for term in boundary_terms)

    # 检查是否建立了不等式关系 (如 x <= R, sin theta >= ...)
    has_inequality = re.search(r'[<>]=?|\\le|\\ge|range|范围', pred_lower)

    if not has_boundary_logic or not has_inequality:
        return {
            'result': 'fail',
            'message': '预测中缺失边界光线追踪逻辑或未建立几何不等式范围',
            'evidence': prediction[:200]
        }

    # Step 3: 符号校验 — 检查 R, theta, x 等关键符号的覆盖情况
    required_symbols = ['R', 'theta', 'x']
    # 转换 latex 符号为普通字符进行匹配
    clean_pred = pred_lower.replace('\\theta', 'theta').replace('\\rho', 'rho')
    missing_symbols = [sym for sym in required_symbols if sym not in clean_pred]

    if len(missing_symbols) > 1: # 允许缺失一个（如x可能被其他坐标符号代替），但不能全无
        return {
            'result': 'fail',
            'message': f'预测中缺少关键几何符号: {missing_symbols}',
            'evidence': prediction[:200]
        }

    # Step 4: 结构校验 — 检查是否存在类似 x_min <= x <= x_max 的结构
    if re.search(r'[a-zA-Z0-9_]+\s*[<≤]\s*[a-zA-Z0-9_]+\s*[<≤]\s*[a-zA-Z0-9_]+', pred_lower):
        return {'result': 'pass', 'message': '已建立几何不等式并包含边界逻辑', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑基本完整，但公式结构不典型', 'evidence': prediction[:200]}

# rule_id=norm_d781f9fa13e4f37a | domain=Optics | topic=Snell's Law and Critical Angle
# rule_id=norm_d781f9fa13e4f37a | domain=Optics | topic=Snell's Law and Critical Angle
def check_norm_d781f9fa13e4f37a_a70ba720d6c6(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及梯度折射率介质、光线方程推导或力学类比
    trigger_keywords = ['梯度折射率', 'gradient index', 'GRIN', '光线方程', 'ray equation', '力学类比', 'mechanical analogy']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到梯度折射率光线方程推导场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 校验方程左侧是否为光矢对弧长 s 的导数项 d/ds(n dr/ds)
    # 匹配模式包含 d/ds(n dr/ds) 或类似的变体，如 d/ds(n r')
    lhs_pattern = r'd/ds\s*\(\s*n\s*d[rR]/ds\s*\)|\\frac{d}{ds}\s*\\?\(?n\s*\\frac{d\\vec{r}}{ds}\\?\)?'
    rhs_pattern = r'grad\(n\)|\\nabla\s*n|\\frac{\\partial n}{\\partial [rR]}'

    pred_clean = prediction.replace(' ', '')

    # 检查是否使用了时间 t 而非弧长 s (常见错误)
    if re.search(r'd/dt|\\frac{d}{dt}', prediction) and not re.search(r'd/ds|\\frac{d}{ds}', prediction):
        return {'result': 'fail', 'message': '光线方程参数错误：应使用几何弧长 s 而非时间 t', 'evidence': re.search(r'.{0,30}d/dt.{0,30}', prediction).group(0) if re.search(r'd/dt', prediction) else ''}

    # Step 3: 符号与公式结构校验
    has_lhs = re.search(lhs_pattern, prediction, re.IGNORECASE) or 'n*dr/ds' in pred_clean
    has_rhs = re.search(rhs_pattern, prediction, re.IGNORECASE) or 'gradn' in pred_clean

    if has_lhs and has_rhs:
        return {'result': 'pass', 'message': '光线方程形式正确，包含折射率梯度与弧长导数项', 'evidence': 'LHS and RHS patterns matched'}

    if 'n' in prediction and 'r' in prediction and 's' in prediction:
        if not (has_lhs or has_rhs):
            return {'result': 'fail', 'message': '未能识别正确的光线微分方程结构 d/ds(n dr/ds) = grad(n)', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定方程推导的准确性', 'evidence': ''}

# rule_id=norm_f0550aa5be5e5f53 | domain=Optics | topic=Snell's Law and Critical Angle
# rule_id=norm_f0550aa5be5e5f53 | domain=Optics | topic=Snell's Law and Critical Angle
def check_norm_f0550aa5be5e5f53_e2b7b5b0b9eb(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及梯度介质（Mirage/海市蜃楼）或折射率随高度 z 变化
    trigger_keywords = ['mirage', '海市蜃楼', 'gradient index', 'n(z)', 'refractive index', '折射率', 'z轴', 'height']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到梯度介质或Snell定律应用场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找 Snell 定律公式 n sin theta = C 以及对应的导数定义 dx/dz 或 dz/dx
    pred = prediction.lower()
    # 检查是否提到了 Snell 定律的基本形式
    has_snell = re.search(r'n.*sin.*theta', pred) or re.search(r'n\(z\).*sin', pred)
    if not has_snell:
        return {'result': 'inconclusive', 'message': '未在预测中发现Snell定律的显式应用', 'evidence': ''}

    # Step 3: 符号与几何关系校验 — 检查 dx/dz 与 tan(theta) 的匹配关系
    # 规则：若 theta 是与垂直轴(z)夹角，则 dx/dz = tan(theta)
    # 规则：若 theta 是与水平轴(x)夹角，则 dz/dx = tan(theta)

    # 匹配 dx/dz = tan 或 dz/dx = tan 的模式
    dx_dz_tan = re.search(r'dx/dz\s*=\s*tan', pred) or re.search(r'dx\\/dz.*tan', pred)
    dz_dx_tan = re.search(r'dz/dx\s*=\s*tan', pred) or re.search(r'dz\\/dx.*tan', pred)

    # 检查 theta 的定义描述
    vertical_angle = 'vertical' in pred or '垂直' in pred or 'z-axis' in pred
    horizontal_angle = 'horizontal' in pred or '水平' in pred or 'x-axis' in pred

    # 逻辑校验：如果定义了垂直夹角但用了 dz/dx = tan，或者定义了水平夹角但用了 dx/dz = tan，则判定为概念错误
    if vertical_angle and dz_dx_tan and not dx_dz_tan:
        return {'result': 'fail', 'message': '角度定义冲突：theta为垂直夹角时应为dx/dz=tan(theta)', 'evidence': prediction[:200]}

    if horizontal_angle and dx_dz_tan and not dz_dx_tan:
        return {'result': 'fail', 'message': '角度定义冲突：theta为水平夹角时应为dz/dx=tan(theta)', 'evidence': prediction[:200]}

    # 检查 canonical 形式的符合度
    if re.search(r'dx/dz\s*=\s*tan\s*\(?theta\)?', pred) or re.search(r'dz/dx\s*=\s*tan\s*\(?theta\)?', pred):
        return {'result': 'pass', 'message': '几何导数关系与角度定义匹配', 'evidence': 'Found tan relationship in prediction'}

    return {'result': 'inconclusive', 'message': '无法确定角度定义与导数关系的匹配性', 'evidence': ''}

# rule_id=norm_1ce3895d16868e0b | domain=Optics | topic=Total Internal Reflection
# rule_id=norm_1ce3895d16868e0b | domain=Optics | topic=Total Internal Reflection
def check_norm_1ce3895d16868e0b_bdc0465004b6(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 涉及激光/光束穿过透明介质（如玻璃、棱镜）计算受力或压强
    trigger_keywords = ['激光', '光束', 'laser', 'beam', 'glass', '介质', '受力', 'force', 'pressure', '压强']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到激光穿过介质受力分析的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否通过动量矢量差 (P_in - P_out) 计算总力
    # 检查是否只关注了单次折射（如只提到了进入界面的力）而忽略了整体动量变化
    pred = prediction.lower()
    momentum_change_pattern = r'(momentum|动量|\\Delta P|P_in|P_out|k_in|k_out)'
    if not re.search(momentum_change_pattern, pred):
        return {'result': 'fail', 'message': '未通过动量矢量差计算总力，可能仅计算了单次折射受力', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 P, c, k 等关键符号及公式结构
    # 核心公式 F = P/c * |k_in - k_out| 或类似动量守恒表达
    required_symbols = ['P', 'c']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    # 检查是否包含矢量差的逻辑特征
    vector_diff_feature = re.search(r'(\\Delta|change|difference|减去|差| - )', pred)

    if not missing_symbols and vector_diff_feature:
        # 进一步寻找公式结构特征
        if re.search(r'P/c', prediction) or re.search(r'\\frac{P}{c}', prediction):
            return {'result': 'pass', 'message': '符合介质界面受力分析准则，使用了动量矢量差计算', 'evidence': prediction[:200]}

    if len(missing_symbols) > 1:
        return {'result': 'fail', 'message': '缺少关键物理量符号(P, c)，受力分析模型不完整', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到动量相关描述但公式结构不明确', 'evidence': prediction[:200]}

# rule_id=norm_4d696d28e1f35f76 | domain=Optics | topic=Total Internal Reflection
# rule_id=norm_4d696d28e1f35f76 | domain=Optics | topic=Total Internal Reflection
def check_norm_4d696d28e1f35f76_83fdf7fa927b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及增透膜 (anti-reflective coating)
    trigger_keywords = ['anti-reflective', 'anti-reflection', '增透膜', '减反射膜']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '题目未涉及增透膜场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否错误地认为增透膜可以消除全反射 (TIR)
    # 增透膜只能消除菲涅耳反射，不能消除全反射。如果 prediction 认为增透膜存在时全反射消失，则报错。
    pred_lower = prediction.lower()
    tir_keywords = ['total internal reflection', 'tir', '全反射']
    eliminate_keywords = ['eliminate', 'remove', 'cancel', 'no longer occur', '消除', '抵消', '不再发生']

    has_tir = any(kw in pred_lower for kw in tir_keywords)

    # 检查是否存在“增透膜消除全反射”的错误表述
    for tir_kw in tir_keywords:
        for elim_kw in eliminate_keywords:
            pattern = f'{tir_kw}.*?{elim_kw}|{elim_kw}.*?{tir_kw}'
            if re.search(pattern, pred_lower):
                return {
                    'result': 'fail',
                    'message': '错误地认为增透膜可以消除全反射。增透膜仅针对菲涅耳反射，不影响全反射条件。',
                    'evidence': re.search(pattern, pred_lower).group()
                }

    # Step 3: 检查力学边界 — 是否直接假设力为 P/c 而忽略了全反射可能带来的 2P/c
    # 如果题目涉及光压/力 (force/pressure)，且直接使用了 P/c (100% 透射假设) 而未讨论全反射可能性
    force_keywords = ['force', 'pressure', '光压', '压力', 'P/c']
    if any(kw in pred_lower for kw in force_keywords):
        # 如果提到全反射但直接用 P/c 计算，或者认为增透膜使得反射力消失
        if 'p/c' in pred_lower and not any(kw in pred_lower for kw in ['2p/c', '2*p/c', 'twice']):
            if has_tir:
                return {
                    'result': 'fail',
                    'message': '在存在全反射可能性的情况下，直接使用 P/c 计算光压，忽略了全反射导致的动量变化翻倍。',
                    'evidence': 'prediction contains P/c without considering 2P/c for TIR'
                }

    return {'result': 'inconclusive', 'message': '未发现明显的增透膜与全反射混淆逻辑', 'evidence': ''}

# rule_id=norm_8fe55e98cff05626 | domain=Optics | topic=Total Internal Reflection
# rule_id=norm_8fe55e98cff05626 | domain=Optics | topic=Total Internal Reflection
def check_norm_8fe55e98cff05626_517278ccbd87(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“最大力/极值力”以及“全反射”场景
    trigger_keywords = ['最大力', '最大压力', '力最大', 'maximum force', 'max force']
    optics_keywords = ['全反射', 'total internal reflection', '临界角', 'critical angle']

    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and any(kw in combined_text for kw in optics_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '题目未同时涉及力学极值与全反射场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 预测中是否考虑了全反射路径导致的动量改变（力）
    pred_lower = prediction.lower()
    # 检查是否提到全反射作为极值边界条件
    if '全反射' not in pred_lower and 'critical' not in pred_lower:
        return {'result': 'fail', 'message': '在寻找极值力时未考虑全反射这一关键物理边界', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查全反射临界角公式 sin(theta) >= 1/n
    # 匹配类似 sin(theta) = 1/n 或 n*sin(theta) = 1 的结构
    tir_formula_pattern = r'(sin[\s\(]*[\w\theta]+[\s\)]*[\s]*[>=]*[\s]*1\s*/\s*n)|(n\s*\*?\s*sin[\s\(]*[\w\theta]+[\s\)]*[\s]*[>=]*[\s]*1)'
    if not re.search(tir_formula_pattern, pred_lower):
        # 如果没有显式公式，检查是否有动量/冲量相关的描述，因为力源于动量变化
        if '动量' not in pred_lower and 'momentum' not in pred_lower and '冲量' not in pred_lower:
            return {'result': 'fail', 'message': '未建立全反射与力（动量变化）之间的物理关联', 'evidence': prediction[:200]}

    # Step 4: 综合判定
    if '1/n' in pred_lower or 'sin' in pred_lower:
        return {'result': 'pass', 'message': '已识别全反射路径并尝试进行极值判定', 'evidence': re.search(r'.{0,50}(1/n|sin).{0,50}', pred_lower).group(0) if 'sin' in pred_lower else ''}

    return {'result': 'inconclusive', 'message': '逻辑存在但公式特征不明显', 'evidence': ''}

# rule_id=norm_ff88e50566819ccd | domain=Optics | topic=Total Internal Reflection
# rule_id=norm_ff88e50566819ccd | domain=Optics | topic=Total Internal Reflection
def check_norm_ff88e50566819ccd_c4644823f29d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及激光、透明介质（折射率n）及最大力/辐射压力的求解
    trigger_keywords = ['激光', 'laser', '折射率', 'refractive index', '辐射压力', 'radiation pressure', '最大力', 'maximum force', 'max force']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and ('n' in combined_text or '折射' in combined_text)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到涉及透明介质辐射压力最大化的物理场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否考虑了全反射 (TIR) 路径以及动量差矢量
    pred_lower = prediction.lower()
    tir_keywords = ['全反射', 'total internal reflection', 'tir', 'critical angle', '临界角']
    momentum_keywords = ['动量', 'momentum', 'vector', '矢量', 'k_in', 'k_out', 'delta p']

    has_tir = any(kw in pred_lower for kw in tir_keywords)
    has_momentum_logic = any(kw in pred_lower for kw in momentum_keywords)

    if not has_tir:
        return {'result': 'fail', 'message': '在求解最大辐射压力时未考虑全反射（TIR）路径', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 P, c, n 符号及动量差公式结构
    # 匹配类似 |k_in - k_out| 或 (P/c) 相关的结构
    formula_pattern = r'(P/c|P\\/c|momentum).*(\\Delta|diff|k_in|k_out)'
    required_symbols = ['P', 'c', 'n']
    missing_symbols = [s for s in required_symbols if s not in prediction and s not in question]

    if len(missing_symbols) > 1: # 允许缺失一个（可能在上下文中隐含），多于一个则认为建模不完整
        return {'result': 'fail', 'message': f'缺少必要的物理符号: {missing_symbols}', 'evidence': prediction[:200]}

    if re.search(formula_pattern, prediction, re.IGNORECASE) or has_momentum_logic:
        return {'result': 'pass', 'message': '已考虑全反射路径及动量变化矢量分析', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑要素不完整，无法判定', 'evidence': ''}

# rule_id=norm_1169dce4668b7186 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_1169dce4668b7186 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_1169dce4668b7186_167780e37635(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及光从低折射率介质射向高折射率介质的反射场景
    # 关键词：折射率、反射、半波损失、n1 < n2、光疏到光密
    trigger_keywords = ['反射', '折射率', 'n1', 'n2', '介质', '光疏', '光密', 'reflection', 'refractive index']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到涉及介质反射或折射率变化的场景', 'evidence': ''}

    # 进一步确认是否存在“小射向大”的逻辑描述
    if not re.search(r'(n1\s*<\s*n2|n_1\s*<\s*n_2|光疏.*光密|低.*高)', question + context):
        if '半波损失' not in (question + context):
            return {'result': 'inconclusive', 'message': '未明确识别出光从低折射率射向高折射率的触发条件', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 中是否考虑了半波损失（lambda/2 或 pi）
    # 检查公式中是否包含 + lambda/2, - lambda/2, + pi, 或 0.5*lambda 等项
    pred_text = prediction.replace(' ', '')

    # 匹配光程差公式中的半波项：Δ = ... + λ/2 或 Δ = ... - λ/2
    half_wave_pattern = r'(\+|\-)(\lambda/2|0\.5\*?\lambda|\\lambda/2|\\frac{\\lambda}{2})'
    # 匹配相位移动：+ pi 或 - pi
    phase_shift_pattern = r'(\+|\-)(\pi|\\pi)'
    # 匹配文字描述
    text_desc_pattern = r'(半波损失|相位(突变|移动)|附加光程差)'

    has_half_wave = re.search(half_wave_pattern, pred_text, re.IGNORECASE)
    has_phase_shift = re.search(phase_shift_pattern, pred_text, re.IGNORECASE)
    has_text_desc = re.search(text_desc_pattern, prediction)

    if has_half_wave or has_phase_shift or has_text_desc:
        # Step 3: 符号覆盖检查 (Δ, λ)
        if 'Δ' in prediction or 'lambda' in prediction.lower() or 'λ' in prediction:
            return {'result': 'pass', 'message': '已检测到半波损失补偿项或相关概念描述', 'evidence': prediction[:200]}
        return {'result': 'pass', 'message': '检测到半波损失相关描述', 'evidence': prediction[:200]}

    # 如果明确在计算干涉条件但缺失了半波损失项，则判定为 fail
    if re.search(r'(\d+n|2nd|\Delta\s*=)', pred_text):
        return {'result': 'fail', 'message': '在涉及半波损失的反射干涉计算中，未发现λ/2或π的补偿项', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了半波损失补偿', 'evidence': ''}

# rule_id=norm_2cd473aa8cf5a15f | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_2cd473aa8cf5a15f | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_2cd473aa8cf5a15f_c9574da165f0(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及单面镜反射（Lloyd镜）、薄膜干涉或光从疏介质到密介质的反射
    trigger_keywords = ['lloyd', '劳埃德镜', '薄膜干涉', 'thin film', '反射', 'reflection', '折射率']
    content_to_check = (question + context).lower()
    is_triggered = any(kw in content_to_check for kw in trigger_keywords)

    # 进一步确认是否存在半波损失场景：如 n1 < n2 的反射
    has_refractive_index_jump = re.search(r'n1\s*<\s*n2|n[12]\s*=\s*[\d\.]+', content_to_check)

    if not (is_triggered or has_refractive_index_jump):
        return {'result': 'inconclusive', 'message': '未检测到涉及半波损失的典型光学干涉场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 中是否包含 λ/2 (或 0.5λ) 的相位修正项
    pred = prediction.lower()
    # 匹配光程差公式中包含 lambda/2 的形式
    half_wave_pattern = r'(\+|\-)\s*(\lambda/2|0\.5\s*\*?\s*\lambda|lambda/2)'
    has_half_wave_correction = re.search(half_wave_pattern, pred)

    # 检查是否提到了“半波损失”或“phase shift”或“pi”相位差
    has_term_mention = any(kw in pred for kw in ['半波损失', 'half-wave loss', 'phase change', 'phase shift', '相位突变'])

    # Step 3: 综合判定
    if has_half_wave_correction:
        return {'result': 'pass', 'message': '检测到光程差公式中包含半波损失修正项 λ/2', 'evidence': re.search(half_wave_pattern, pred).group()}

    if not has_term_mention and not has_half_wave_correction:
        # 如果题目明确是反射干涉但完全没提半波损失，判定为建模错误
        if 'lloyd' in content_to_check or '劳埃德镜' in content_to_check:
            return {'result': 'fail', 'message': '在涉及反射干涉（如劳埃德镜）的计算中缺失半波损失修正', 'evidence': prediction[:200]}
        return {'result': 'inconclusive', 'message': '未能明确识别半波损失修正项，需人工核实', 'evidence': ''}

    return {'result': 'pass', 'message': '文字描述中提及了半波损失或相位修正', 'evidence': '包含相关术语描述'}

# rule_id=norm_34cc2f48ecf7afd9 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_34cc2f48ecf7afd9 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_34cc2f48ecf7afd9_61d3667b8b35(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及薄膜干涉、牛顿环或等厚干涉场景
    trigger_keywords = ['薄膜', '干涉', '牛顿环', '等厚干涉', '折射率', '反射', '光程差']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到薄膜干涉相关物理场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否讨论了半波损失（half-wave loss）或折射率大小关系
    pred = prediction.lower()
    has_half_wave_mention = any(kw in pred for kw in ['半波损失', 'half-wave loss', 'λ/2', 'lambda/2', '0.5λ'])

    # Step 3: 公式校验 — 检查光程差公式中是否包含 (k + 1/2)λ 或类似的修正项
    # 匹配 2nd, 2nt, 2d*n 等结构，以及是否包含 lambda/2 的加减项
    formula_pattern = r'2[ndt]{2,3}.*?[\+\-].*?(0\.5|1/2|λ/2|lambda/2)'
    has_formula_correction = re.search(formula_pattern, pred, re.IGNORECASE)

    # 如果题目明确涉及不同介质界面反射，但预测中完全没有提到半波损失或公式修正，则判定为概念缺失
    if not has_half_wave_mention and not has_formula_correction:
        # 进一步确认是否真的需要半波损失（通常涉及 n1 < n2 > n3 或类似折射率跳变）
        if re.search(r'n[123]\s*[<>\=]\s*n[123]', content_to_check):
            return {'result': 'fail', 'message': '在涉及折射率变化的干涉计算中未考虑半波损失修正', 'evidence': prediction[:200]}
        return {'result': 'inconclusive', 'message': '无法确定是否必须包含半波损失修正', 'evidence': ''}

    # 如果公式结构匹配成功，则认为通过校验
    if has_formula_correction:
        return {'result': 'pass', 'message': '检测到包含半波损失修正的光程差公式', 'evidence': re.search(formula_pattern, pred, re.IGNORECASE).group()}

    return {'result': 'inconclusive', 'message': '检测到半波损失讨论但公式表达不明确', 'evidence': prediction[:150]}

# rule_id=norm_391666a6ad48d8df | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_391666a6ad48d8df | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_391666a6ad48d8df_8410baebb145(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否为双缝干涉且涉及透明介质（如玻璃片、薄膜）覆盖缝隙
    full_text = (question + context).lower()
    is_double_slit = '双缝' in full_text or 'young' in full_text
    has_medium = any(kw in full_text for kw in ['介质', '玻璃', '薄膜', '折射率', '覆盖'])
    if not (is_double_slit and has_medium):
        return {'result': 'inconclusive', 'message': '未检测到双缝干涉介质覆盖场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找关于条纹移动方向的判定逻辑
    # 核心逻辑：光程增加的一侧，条纹向该侧移动（以补偿几何路程差）
    pred = prediction.lower()
    move_keywords = ['移动', '偏移', '移向', 'shift', 'move']
    if not any(kw in pred for kw in move_keywords):
        return {'result': 'fail', 'message': '预测中未提及条纹移动方向', 'evidence': prediction[:100]}

    # Step 3: 符号与公式校验 — 检查是否包含 (n-1)h 或类似的相位补偿表达
    # 检查是否提到“光程差”或“折射率”导致的路径变化
    has_n_minus_1 = re.search(r'\(n-1\)\s*\*?\s*[hd]', pred) or 'n-1' in pred
    has_path_diff = '光程' in pred or 'path length' in pred

    # 判定移动方向的正确性（逻辑匹配）
    # 如果提到覆盖上缝(S1)，条纹应向上移；覆盖下缝(S2)，条纹应向下移
    if '上缝' in full_text or 's1' in full_text:
        if '下' in pred or '向下' in pred or 'down' in pred:
            return {'result': 'fail', 'message': '覆盖上缝时条纹应向上移动以补偿光程', 'evidence': prediction}
    elif '下缝' in full_text or 's2' in full_text:
        if '上' in pred or '向上' in pred or 'up' in pred:
            return {'result': 'fail', 'message': '覆盖下缝时条纹应向下移动以补偿光程', 'evidence': prediction}

    if has_n_minus_1 or has_path_diff:
        return {'result': 'pass', 'message': '正确识别了介质引入导致的光程变化及条纹移动方向', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '逻辑描述不够明确', 'evidence': prediction[:100]}

# rule_id=norm_48e1d9fbe98e295c | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_48e1d9fbe98e295c | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_48e1d9fbe98e295c_1f3fe7f15aee(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及薄膜干涉、折射率 n、厚度 d 及波长 lambda
    trigger_keywords = ['薄膜', '干涉', 'thin film', 'interference', '厚度', '折射率']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到薄膜干涉相关场景', 'evidence': ''}

    # 检查是否包含核心物理量符号
    if not (re.search(r'[ndλ\lambda]', combined_text)):
        return {'result': 'inconclusive', 'message': '题目未明确涉及折射率或厚度符号', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别光程差公式并检查介质一致性
    # 核心逻辑：2nd 对应 lambda_0 (真空波长)；2d 对应 lambda_n (介质波长)
    # 错误逻辑：2nd / n = m * lambda_0 (重复除以 n) 或 2nd = m * (lambda_0 / n)
    pred = prediction.replace(' ', '')

    # 匹配 2nd = m * lambda 类型的公式
    # 匹配模式：2 * n * d (或 2nd) 后面跟着波长项
    path_diff_pattern = re.compile(r'2n?d')
    if not path_diff_pattern.search(pred):
        return {'result': 'inconclusive', 'message': '预测中未发现明确的光程差计算公式', 'evidence': prediction[:100]}

    # 检查是否存在错误的重复折算：2nd / n 或 2nd = ... / n (当右侧已经是真空波长时)
    # 典型错误 1: 2nd/n = m*lambda
    error_case_1 = re.search(r'2nd/n', pred)
    # 典型错误 2: 2nd = m*(lambda/n) 其中 lambda 已经是真空波长
    error_case_2 = re.search(r'2nd=.*\\lambda(_0)?/n', pred)

    if error_case_1 or error_case_2:
        return {
            'result': 'fail',
            'message': '光程差折算错误：公式中重复除以了折射率 n，导致介质波长与真空波长混淆。',
            'evidence': (error_case_1 or error_case_2).group()
        }

    # Step 3: 验证正确的一致性表达
    # 正确形式 A: 2nd = m*lambda_0 (或 lambda)
    # 正确形式 B: 2d = m*(lambda/n)
    correct_a = re.search(r'2nd=.*\\lambda', pred)
    correct_b = re.search(r'2d=.*\\lambda/n', pred)

    if correct_a or correct_b:
        return {
            'result': 'pass',
            'message': '公式符合光程差介质一致性要求。',
            'evidence': (correct_a or correct_b).group()
        }

    return {'result': 'inconclusive', 'message': '无法确定公式折算是否正确', 'evidence': prediction[:150]}

# rule_id=norm_49806b683be01fe2 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_49806b683be01fe2 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_49806b683be01fe2_d81159254cd7(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及薄膜干涉、光谱、厚度计算场景
    trigger_keywords = ['薄膜', '厚度', '光谱', '干涉', '波长', 'thin film', 'thickness', 'interference', 'wavelength']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到薄膜干涉或厚度计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否使用了相邻峰值波长推导厚度的逻辑
    # 核心公式特征：d = (lambda1 * lambda2) / (2 * n * (lambda2 - lambda1))
    pred = prediction.lower()
    # 检查是否包含关键物理量符号
    required_symbols = ['d', 'n', 'λ', 'lambda']
    symbol_count = sum(1 for sym in required_symbols if sym in pred)

    # Step 3: 公式结构校验
    # 匹配类似 d = λ1λ2 / 2nΔλ 的结构
    # 允许不同的写法，如 (L1*L2)/(2n(L2-L1)) 或类似的变体
    formula_patterns = [
        r'd\s*=\s*.*lambda.*lambda.*/.*2.*n.*lambda',
        r'd\s*=\s*.*λ.*λ.*/.*2.*n.*λ',
        r'2nd\s*=\s*m',
        r'thickness\s*=\s*.*lambda.*lambda.*/.*2.*n'
    ]

    found_formula = any(re.search(pat, pred, re.IGNORECASE) for pat in formula_patterns)

    # 检查量纲逻辑：分子是长度平方，分母是长度，结果应为长度
    dimension_check = 'lambda' in pred and ('/' in pred or 'div' in pred)

    if found_formula:
        # 进一步检查分母是否包含 2n 或 2n(λ2-λ1)
        if re.search(r'2\s*n\s*\(\s*λ|2\s*n\s*\(\s*lambda|2n\s*delta', pred):
            return {'result': 'pass', 'message': '厚度计算公式及量纲逻辑正确', 'evidence': re.findall(r'.{0,50}d\s*=[^\n]+', pred)[0] if re.search(r'd\s*=', pred) else 'Found valid formula structure'}
        else:
            return {'result': 'inconclusive', 'message': '检测到公式但关键系数(2n)或差值项不明确', 'evidence': pred[:100]}

    # 如果明确在算厚度但公式写错（例如分子分母颠倒）
    if 'd =' in pred and ('lambda' in pred or 'λ' in pred):
        if not re.search(r'2\s*n', pred):
            return {'result': 'fail', 'message': '厚度推导公式缺失折射率n或系数2，量纲或逻辑可能错误', 'evidence': pred[:150]}

    return {'result': 'inconclusive', 'message': '未发现明确的厚度推导公式结构', 'evidence': ''}

# rule_id=norm_5b4c340bc49e62ba | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_5b4c340bc49e62ba | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_5b4c340bc49e62ba_8d128003c8c9(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两束相干光叠加或干涉强度分布计算
    trigger_keywords = ['干涉', '强度', '叠加', 'interference', 'intensity', 'double slit', 'thin film']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到干涉强度分布计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否使用了 cos²(Φ/2) 的化简形式
    # 匹配 4E0^2 cos^2(phi/2) 或类似的强度公式结构
    pred_clean = prediction.replace(' ', '')
    # 检查是否包含 cos^2 或 cos**2 以及相位差的一半
    cos_sq_pattern = r'cos\^2\(.*?/2\)|cos\*\*2\(.*?/2\)|cos\^2\(0\.5\*.*?\)'
    has_cos_sq = re.search(cos_sq_pattern, pred_clean, re.IGNORECASE)

    # 检查是否包含系数 4 (对应等振幅 E0 叠加后的 4E0^2)
    has_coeff_4 = '4' in pred_clean and ('E' in pred_clean or 'I' in pred_clean)

    # Step 3: 符号校验 — 检查 E0 和 Δφ (phi) 是否出现
    required_symbols = ['E', 'phi', 'φ', 'Δ']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)

    if has_cos_sq:
        if symbol_count >= 1:
            return {'result': 'pass', 'message': '成功验证干涉强度公式的余弦平方化简形式', 'evidence': re.search(cos_sq_pattern, pred_clean, re.IGNORECASE).group()}
        else:
            return {'result': 'inconclusive', 'message': '公式形式正确但符号不匹配', 'evidence': prediction[:100]}

    # 如果明确在计算强度但没有使用化简公式，且存在 1+cos 形式未化简，则视为未完成化简要求
    if '1+cos' in pred_clean or '1 + cos' in prediction:
        return {'result': 'fail', 'message': '未按要求将 1+cos(Φ) 化简为 2cos²(Φ/2) 形式', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了化简公式', 'evidence': ''}

# rule_id=norm_6305354853156556 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_6305354853156556 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_6305354853156556_ad512f2ec86a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及干涉极值搜索（最近、最小、第一个极值）
    trigger_keywords = ['最近', '最小', '第一个', '第1个', '最近距离', '最小位置', 'nearest', 'minimum', 'first order']
    interference_keywords = ['干涉', '双缝', '薄膜', '级数', 'interference', 'slit', 'film', 'm=']

    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and any(kw in combined_text for kw in interference_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到干涉极值搜索场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否遍历了级数 m 的多个可能解或讨论了边界条件
    # 规则要求不能只算出一个正值就停止，必须体现出对 m 的选择或范围限制 (0 < x < L)
    pred_lower = prediction.lower()

    # 检查是否提到了级数变量 m 或 k 的取值讨论
    has_m_iteration = re.search(r'[mk]\s*=\s*\d', pred_lower) or '取值' in pred_lower or '级数' in pred_lower
    # 检查是否讨论了范围限制 (如 x < L 或 0 < x)
    has_range_limit = re.search(r'[xL]\s*[<>]=?\s*\d', pred_lower) or '范围' in pred_lower or '边界' in pred_lower

    # 如果推理中直接给出一个 m 值而没有比较过程，且题目要求的是“最小/最近”，则存在逻辑风险
    if not (has_m_iteration or has_range_limit):
        return {
            'result': 'fail',
            'message': '推理过程中未体现对干涉级数 m 的穷举或边界条件 (0 < x < L) 的校验，可能导致解非全局最小',
            'evidence': prediction[-200:]
        }

    # Step 3: 符号校验 — 检查是否包含必要的物理量符号 L, x_m
    if 'L' in prediction and ('x' in prediction or 'm' in prediction):
        return {'result': 'pass', 'message': '推理包含级数讨论与边界约束', 'evidence': prediction[-150:]}

    return {'result': 'inconclusive', 'message': '逻辑讨论不充分，无法判定是否执行了穷举', 'evidence': ''}

# rule_id=norm_6665a32992c2006b | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_6665a32992c2006b | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_6665a32992c2006b_5d3cc8172f97(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及远场干涉场景（点源、反射面、远端屏幕 L >> l）
    trigger_keywords = ['点源', '反射面', '屏幕', '远端', 'L >> l', 'L>>l', 'far field', 'interference']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到远场干涉或反射面建模场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查路径差计算中是否包含大尺度距离 L
    # 规则要求：若公式中仅出现小尺度 l 和 y 而无 L，通常存在建模缺失
    pred_text = prediction.lower()
    # 检查是否包含必要的符号 L 和 y
    has_L = 'l' in pred_text and 'L' in prediction # 区分大小写，L通常代表大尺度
    has_y = 'y' in pred_text

    # Step 3: 公式结构校验 — 寻找路径差 Delta 的近似表达
    # 匹配类似 Δ ≈ ... L ... 的结构
    path_diff_pattern = r'(\Delta|path difference|路径差).*?=.*?L'
    formula_match = re.search(path_diff_pattern, prediction, re.IGNORECASE)

    if not has_L:
        # 如果预测中完全没有出现大写 L，且在讨论路径差，则判定为建模缺失
        if any(term in pred_text for term in ['delta', '路径差', 'path difference']):
            return {
                'result': 'fail',
                'message': '路径差建模缺失大尺度距离 L，可能未考虑远场近似条件',
                'evidence': prediction[:200]
            }
        return {'result': 'inconclusive', 'message': '预测中未明确给出路径差计算过程', 'evidence': ''}

    if formula_match or (has_L and has_y):
        return {
            'result': 'pass',
            'message': '路径差公式中包含了必要的几何参数 L 和 y',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '无法确定路径差建模是否完整', 'evidence': ''}

# rule_id=norm_745499daecb48b76 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_745499daecb48b76 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_745499daecb48b76_89236722e538(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及在干涉路径中插入透明介质（厚度s, 折射率n）
    trigger_keywords = ['插入', '介质', '薄膜', '玻璃片', '厚度', '折射率']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到插入介质的干涉场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别 prediction 中是否计算了额外光程差，并检查公式是否为 (n-1)s
    # 错误倾向是将光程差误认为 ns 或忽略减去原有的空气路径 s
    pred_text = prediction.replace(' ', '')

    # 匹配 (n-1)s 或 n*s-s 及其变体
    correct_pattern = r'\(n-1\)\*?s|n\*?s-s|\(n-1\)d|n\*?d-d'
    incorrect_pattern = r'[^\-1]ns|[^\-]ns|(?<!\-)ns(?!\-)' # 简单匹配 ns 但前面没有减号或1的情况

    # Step 3: 执行校验
    # 如果明确出现了 (n-1)s 结构，判定为 pass
    if re.search(correct_pattern, pred_text, re.IGNORECASE):
        return {'result': 'pass', 'message': '正确使用了 (n-1)s 计算额外光程差', 'evidence': re.search(correct_pattern, pred_text, re.IGNORECASE).group()}

    # 如果出现了 ns 且没有减去 s 的迹象，且在讨论光程差(delta L/OPD)，判定为 fail
    if 'ns' in pred_text.lower() and not re.search(correct_pattern, pred_text, re.IGNORECASE):
        if any(kw in pred_text for kw in ['光程差', 'delta', 'OPD', 'pathdifference']):
            return {'result': 'fail', 'message': '光程差计算错误：应使用 (n-1)s 而非 ns', 'evidence': prediction[:200]}

    # 如果 prediction 中完全没有提到折射率与厚度的乘积关系，视为缺失关键步骤
    if 'n' not in pred_text.lower() or 's' not in pred_text.lower() and 'd' not in pred_text.lower():
        return {'result': 'fail', 'message': '未发现介质引起的光程偏移计算步骤', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定光程差计算的具体公式', 'evidence': ''}

# rule_id=norm_7ccff077df3b2f7e | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_7ccff077df3b2f7e | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_7ccff077df3b2f7e_0b17e55491b8(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多缝/N个波源干涉以及主极大强度
    trigger_keywords = ['多缝', 'N个', '相干波源', 'multiple slit', 'N slits', 'coherent sources', 'diffraction grating']
    target_keywords = ['主极大', '最大强度', 'principal maxima', 'maximum intensity', 'I_max']

    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and any(kw in combined_text for kw in target_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到多缝干涉主极大强度的相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证合振幅是否为 N*a 或强度是否正比于 N^2
    pred = prediction.lower()
    # 匹配 N^2, N**2, (N)^2 等形式，或者明确提到 N squared
    n_squared_pattern = r'n[\^\*]{1,2}2|n\s*squared|n\s*的平方|n\s*的2次方'
    # 匹配振幅关系 N*a 或 N*A
    amplitude_pattern = r'n\s*\*?\s*[aA]|n\s*倍的振幅'

    has_n_squared = re.search(n_squared_pattern, pred) is not null
    has_amplitude_n = re.search(amplitude_pattern, pred) is not null

    # Step 3: 综合判定
    # 如果提到了强度但没有体现 N^2 的比例关系，或者提到了振幅但没有体现 N 倍关系，则判定为概念错误
    if 'intensity' in pred or '强度' in pred:
        if not has_n_squared and not has_amplitude_n:
            return {
                'result': 'fail',
                'message': '在计算多缝干涉主极大强度时，未体现强度与缝数N的平方成正比(N^2)的关系',
                'evidence': prediction[:200]
            }

    # 检查公式结构是否符合 I = N^2 * I_0
    if re.search(r'i(_?max)?\s*=\s*n[\^\*]{1,2}2', pred) or re.search(r'i\s*\propto\s*n[\^\*]{1,2}2', pred):
        return {'result': 'pass', 'message': '正确识别了主极大强度与N^2的比例关系', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定预测是否遵循了N^2强度规律', 'evidence': ''}

# rule_id=norm_a2d7b478e56bd749 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_a2d7b478e56bd749 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_a2d7b478e56bd749_a0c5b69c7c1e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两个波源对两个不同方位目标产生干涉强度（最大/最小）
    # 关键词：干涉、波源、方位角/角度、最大/最小/加强/减弱
    trigger_keywords = ['干涉', 'interference', '波源', 'source', 'slit']
    target_keywords = ['方位', '角度', 'angle', 'theta', 'θ']

    text_to_check = (question + context).lower()
    if not (any(k in text_to_check for k in trigger_keywords) and any(k in text_to_check for k in target_keywords)):
        return {'result': 'inconclusive', 'message': '未检测到干涉阵列及多方位目标场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否考虑了两个目标方位角之差（夹角 φ 或 cos θ_A - cos θ_B）
    # 如果预测中直接假设相位差为 0 或 π 而忽略了空间几何关系，则判定为建模错误
    pred = prediction.lower()
    # 检查是否包含两个不同的角度标识或余弦差值结构
    has_angle_diff = re.search(r'cos\s*[θ\(]?\s*[ab12]|theta_[ab12].*theta_[ab12]|Δθ|Δphi', pred)
    has_geometry_constraint = 'd' in pred and ('lambda' in pred or 'λ' in pred)

    if not has_angle_diff and ('d =' in pred or 'd=' in pred):
        # 如果计算了距离 d 但没有体现角度差/余弦差，可能存在建模简化错误
        return {'result': 'fail', 'message': '计算距离 d 时疑似忽略了两个目标方位角的几何约束（夹角关系）', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查 canonical 公式中的关键结构 (cos θ_A - cos θ_B)
    # 匹配类似 (cos(theta1) - cos(theta2)) 的结构
    canonical_pattern = r'cos\s*\(?\s*[θ\w]+\s*\)?\s*-\s*cos\s*\(?\s*[θ\w]+\s*\)?'
    if re.search(canonical_pattern, pred):
        return {'result': 'pass', 'message': '已考虑方位角差值的几何约束', 'evidence': re.search(canonical_pattern, pred).group()}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了方位角几何约束', 'evidence': ''}

# rule_id=norm_b4723cadb5ae7591 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_b4723cadb5ae7591 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_b4723cadb5ae7591_695f7e99e6b7(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两个曲面（圆柱、球、透镜）相切及间隙厚度计算
    trigger_keywords = ['相切', '接触', '间隙', '厚度', '空气层', '牛顿环', '曲率半径', 'R1', 'R2']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到曲面间隙建模场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 区分外切（和）与内含（差）的建模逻辑
    pred = prediction.lower()
    # 检查是否包含曲率半径符号 R1, R2
    if 'r1' not in pred or 'r2' not in pred:
        # 如果只出现一个R，可能是平凸透镜与平面，不完全符合双曲面规则，保守返回
        return {'result': 'inconclusive', 'message': '未检测到双曲面半径符号 R1 和 R2', 'evidence': ''}

    # 检查外切情况：厚度应为两部分之和 (x^2/2R1 + x^2/2R2)
    is_external = '外切' in content_to_check or '外部' in content_to_check
    is_internal = '内含' in content_to_check or '内切' in content_to_check

    # Step 3: 公式结构校验
    # 匹配类似 x^2/(2R1) + x^2/(2R2) 或 (1/R1 + 1/R2) 的结构
    plus_pattern = r'1/R1\s*\+\s*1/R2|x\^2/\(2\*?R1\)\s*\+\s*x\^2/\(2\*?R2\)'
    minus_pattern = r'1/R1\s*-\s*1/R2|x\^2/\(2\*?R1\)\s*-\s*x\^2/\(2\*?R2\)'

    if is_external:
        if re.search(plus_pattern, prediction, re.IGNORECASE):
            return {'result': 'pass', 'message': '外切场景正确使用了求和建模', 'evidence': 'detected sum pattern'}
        elif re.search(minus_pattern, prediction, re.IGNORECASE):
            return {'result': 'fail', 'message': '外切场景错误使用了求差建模', 'evidence': re.search(minus_pattern, prediction, re.IGNORECASE).group()}

    if is_internal:
        if re.search(minus_pattern, prediction, re.IGNORECASE):
            return {'result': 'pass', 'message': '内含场景正确使用了求差建模', 'evidence': 'detected difference pattern'}
        elif re.search(plus_pattern, prediction, re.IGNORECASE):
            return {'result': 'fail', 'message': '内含场景错误使用了求和建模', 'evidence': re.search(plus_pattern, prediction, re.IGNORECASE).group()}

    return {'result': 'inconclusive', 'message': '未能明确判定建模逻辑的正误', 'evidence': prediction[:100]}

# rule_id=norm_b6b2c514b036f89a | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_b6b2c514b036f89a | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_b6b2c514b036f89a_51944fc629bd(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及双缝干涉且引入了折射率为μ、厚度为w的介质板
    trigger_keywords = ['双缝', '干涉', '介质板', '折射率', '厚度']
    if not all(re.search(kw, question + context) for kw in ['双缝', '介质']):
        return {'result': 'inconclusive', 'message': '未检测到双缝干涉或介质板引入场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别公式中是否包含 (μ-1)w 或 (n-1)d 等光程差修正项
    # 匹配 (mu-1)*w, (n-1)*d, (n-1)*t 等形式
    path_diff_pattern = r'(\([\mu n]-1\)\s*\*?\s*[wt d])'
    match = re.search(path_diff_pattern, prediction)
    if not match:
        return {'result': 'fail', 'message': '未在预测中发现介质板引起的光程差修正项 (μ-1)w', 'evidence': prediction[:200]}

    # Step 3: 符号/公式结构校验 — 检查相位差公式 Δφ = (ω/c)(d sin θ - (μ-1)w) 的符号逻辑
    # 规则：若介质在光程较长一侧（θ方向），则光程差减小，符号应为减
    # 检查 canonical 形式的符号一致性
    canonical_pattern = r'd\s*sin\s*[θtheta].*?[-－].*?(\([\mu n]-1\)\s*[wt d])'
    if re.search(canonical_pattern, prediction):
        return {'result': 'pass', 'message': '相位补偿公式符号正确，符合介质板在长光程侧的减法逻辑', 'evidence': match.group(0)}

    # 如果出现了加号，且上下文暗示介质在下缝（θ>0方向），则判定为逻辑错误
    error_pattern = r'd\s*sin\s*[θtheta].*?[+＋].*?(\([\mu n]-1\)\s*[wt d])'
    if re.search(error_pattern, prediction):
        return {'result': 'fail', 'message': '介质板在光程较长一侧时，相位差公式符号错误（应为减法）', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '公式结构不完整或符号逻辑不明确', 'evidence': ''}

# rule_id=norm_b9f8e3aedcdac798 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_b9f8e3aedcdac798 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_b9f8e3aedcdac798_c9af154c798c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 涉及双声源干涉且区分声压幅值与位移幅值
    trigger_keywords = ['声源', '干涉', '声压', '位移', '驻波', 'pressure', 'displacement', 'node', '波节']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到声学干涉或声压/位移辨析场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 确认是否混淆了声压极小（压强波节）与位移极小（位移波节）
    # 声压波节对应位移波腹，反之亦然。检查 prediction 是否有区分这两者的意识
    pred_lower = prediction.lower()
    has_pressure = 'pressure' in pred_lower or '声压' in pred_lower or '压强' in pred_lower
    has_displacement = 'displacement' in pred_lower or '位移' in pred_lower

    if not (has_pressure and has_displacement):
        # 如果题目明确要求区分但预测只字未提另一方，可能存在概念缺失
        if 'pressure' in content_to_check and 'displacement' in content_to_check:
            return {'result': 'fail', 'message': '未明确区分声压幅值与位移幅值的物理差异', 'evidence': prediction[:200]}
        return {'result': 'inconclusive', 'message': '预测中未同时提及声压与位移，无法判断是否混淆', 'evidence': ''}

    # Step 3: 符号与公式校验 — 检查相位差与极小值的关系
    # 逻辑：声压极小 (p_min) 对应相位差 (2m+1)pi
    pressure_min_pattern = r'(\\Delta\\phi|phi).*?(2m\+1).*?pi.*?(p_{min}|min|极小|波节)'
    if re.search(pressure_min_pattern, prediction.replace(' ', '')):
        return {'result': 'pass', 'message': '正确识别了声压极小值的相位条件', 'evidence': re.search(pressure_min_pattern, prediction.replace(' ', '')).group()}

    # 检查是否错误地将位移波节等同于声压波节
    if re.search(r'(位移波节|displacement node).*?(等于|is|same).*?(声压波节|pressure node)', pred_lower):
        return {'result': 'fail', 'message': '错误地将位移波节与声压波节等同，两者应互补', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑辨析不清晰，无法确定正误', 'evidence': ''}

# rule_id=norm_c4608b58088d256c | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_c4608b58088d256c | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_c4608b58088d256c_8fbba139bd3d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及F-P腔透射率公式或相位宽度ε/δ的定义
    trigger_keywords = ['F-P', 'Fabry-Perot', '透射率', 'transmittance', 'FWHM', '半高全宽']
    combined_text = (question + context).lower()
    is_triggered = any(k.lower() in combined_text for k in trigger_keywords) and (re.search(r'[δδεε]', combined_text) or 'delta' in combined_text)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到F-P腔相位宽度相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否正确处理了ε与F的关系以及单位/量纲
    pred = prediction.lower()
    # 检查是否提到ε或delta的宽度定义
    if not re.search(r'[εε]|epsilon|width|delta', pred):
        return {'result': 'inconclusive', 'message': '预测中未明确讨论相位宽度', 'evidence': ''}

    # Step 3: 公式校验 — 检查 ε ≈ 4/sqrt(F) 或 sin^2(ε/4)=1/F 的结构
    # 匹配 epsilon = 4 / sqrt(F) 或类似变体
    formula_pattern = re.search(r'([εε]|epsilon).*?4.*?sqrt\(F\)', prediction, re.IGNORECASE)
    trig_pattern = re.search(r'sin(\^2)?\(([εε]|epsilon)/4\).*?1/F', prediction, re.IGNORECASE)

    if formula_pattern or trig_pattern:
        # 进一步检查单位是否为弧度(rad)
        if 'rad' in pred or '弧度' in pred or 'dimensionless' in pred or '无量纲' in pred:
            return {'result': 'pass', 'message': '相位宽度公式及量纲校验正确', 'evidence': (formula_pattern or trig_pattern).group()}
        else:
            # 如果公式对但没提单位，在物理语境下通常默认弧度，给inconclusive或pass，此处保守给inconclusive
            return {'result': 'inconclusive', 'message': '公式正确但未明确单位', 'evidence': (formula_pattern or trig_pattern).group()}

    # Step 4: 错误识别 — 如果出现了错误的比例关系（如直接正比于F）
    if re.search(r'([εε]|epsilon).*?[^\/][Ff]', prediction) and 'sqrt' not in pred:
         return {'result': 'fail', 'message': '相位宽度与精细度指数F的关系描述错误，应为反比于sqrt(F)', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定相位宽度的计算逻辑是否违反规则', 'evidence': ''}

# rule_id=norm_cdaf83d6024fb165 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_cdaf83d6024fb165 | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_cdaf83d6024fb165_24782589f214(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两个相同频率波源相向发射波（驻波场景）
    trigger_keywords = ['相向', 'opposite direction', 'standing wave', '驻波', '极值位置', '振幅极小']
    source_keywords = ['波源', 'source', 'coherent']
    text_to_check = (question + context).lower()

    is_triggered = any(kw in text_to_check for kw in trigger_keywords) and any(kw in text_to_check for kw in source_keywords)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到相向相干波源或驻波场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否错误套用了双缝干涉公式 Δr=nλ 或 d sinθ
    pred_lower = prediction.lower()
    interference_patterns = [r'\Delta r\s*=\s*n', r'd\s*sin', r'n\s*\\lambda', r'path\s+difference']
    for pattern in interference_patterns:
        if re.search(pattern, pred_lower):
            # 如果在处理驻波问题时使用了双缝干涉的路径差逻辑，判定为建模错误
            return {'result': 'fail', 'message': '错误套用了双缝干涉路径差公式，应建立驻波方程', 'evidence': re.search(pattern, pred_lower).group()}

    # Step 3: 符号与公式校验 — 检查是否包含驻波方程特征 (cos/sin 乘积形式) 及必要符号
    # 要求的符号: L, k, p_0 (或 A)
    required_symbols = ['k', 'L']
    has_symbols = all(sym in prediction for sym in required_symbols)

    # 检查驻波典型结构: 2 * A * cos/sin(kx) * cos/sin(wt)
    standing_wave_pattern = r'(2|\s+2).*?(cos|sin).*?(cos|sin)'
    has_standing_wave_form = re.search(standing_wave_pattern, pred_lower)

    if has_standing_wave_form and has_symbols:
        return {'result': 'pass', 'message': '正确使用了驻波方程进行建模分析', 'evidence': re.search(standing_wave_pattern, pred_lower).group()}

    if '驻波' in pred_lower or 'standing wave' in pred_lower:
        return {'result': 'inconclusive', 'message': '提到了驻波但公式推导细节不足', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了驻波判定逻辑', 'evidence': ''}

# rule_id=norm_f3643fae9892b48d | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
# rule_id=norm_f3643fae9892b48d | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_f3643fae9892b48d_9dcd95ceaa4e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目或上下文中是否包含对称性描述词汇
    trigger_keywords = ['vice versa', '反之亦然', '对称', 'interchange', '互换']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到对称性描述触发词', 'evidence': ''}

    # Step 2: 检查逻辑 — 预测中是否建立了对称的方程组或相位关系
    # 检查是否包含 A, B 符号以及相位 Φ (Phi) 的表达
    pred_lower = prediction.lower()
    # 匹配 Φ(A,B) 或类似的相位差表达，以及 A/B 的互换逻辑
    has_symbols = all(re.search(rf'[{s}]', prediction) for s in ['A', 'B'])
    has_phase = re.search(r'phi|Φ|\\phi|相位', pred_lower)

    if not (has_symbols and has_phase):
        return {'result': 'fail', 'message': '未在推理中建立 A, B 符号间的相位关系', 'evidence': prediction[:200]}

    # Step 3: 检查公式结构 — 是否体现了 Φ(A,B) = -Φ(B,A) 或类似的互换抵消/比例关系
    # 寻找类似 f(A)=max, f(B)=0 的逻辑描述或两式相减的操作
    logic_patterns = [
        r'max.*0|0.*max',
        r'subtract|相减|相加|sum|difference',
        r'Φ.*-Φ|phi.*-phi'
    ]

    match_count = sum(1 for p in logic_patterns if re.search(p, pred_lower))

    if match_count >= 1:
        return {'result': 'pass', 'message': '成功提取互换对称性约束并建立方程关系', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程中对称性方程推导不完整', 'evidence': prediction[:200]}

# rule_id=norm_2ac34cbbf3bf2787 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_2ac34cbbf3bf2787 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_2ac34cbbf3bf2787_e7f78c532d1a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及光栅密度 n (slit density) 或单位长度条纹数
    trigger_keywords = ['光栅', 'grating', '单位长度', '条纹数', 'density', 'lines per', 'n=']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到光栅密度相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别公式中 lambda 与 n 的关系
    # 错误模式：m*lambda = n * sin... (n 应该在分母或以 1/n 形式出现)
    # 匹配形如 m*lambda = n * sin(theta) 或 d = n 的错误逻辑
    pred = prediction.replace(' ', '')

    # 检查是否错误地将 n 直接作为光栅常数 d 使用 (d = n 是错误的，d = 1/n 才是正确的)
    wrong_patterns = [
        r'd=n',
        r'm\\lambda=n\\*?sin',
        r'm\\lambda=n\\(sin',
        r'\\lambda=n\\*?sin'
    ]

    for pattern in wrong_patterns:
        if re.search(pattern, pred, re.IGNORECASE):
            return {
                'result': 'fail',
                'message': '错误地将光栅密度 n 直接当作光栅间距 d 使用，公式应为 d = 1/n',
                'evidence': re.search(pattern, pred, re.IGNORECASE).group()
            }

    # Step 3: 符号与公式结构校验 — 寻找正确的 1/n 关系
    correct_patterns = [
        r'd=1/n',
        r'sin.*=nm\\lambda',
        r'm\\lambda=\\(1/n\\)',
        r'm\\lambda=sin.*/n'
    ]

    found_correct = False
    for pattern in correct_patterns:
        if re.search(pattern, pred, re.IGNORECASE):
            found_correct = True
            break

    if found_correct:
        return {'result': 'pass', 'message': '正确处理了光栅密度与间距的倒数关系', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '未能明确判定公式中 n 的数学位置', 'evidence': ''}

# rule_id=norm_2b3ba2ebcf96b2f3 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_2b3ba2ebcf96b2f3 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_2b3ba2ebcf96b2f3_ebec4acc8514(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及斜入射的光栅方程（Grating Equation with oblique incidence）
    trigger_keywords = ['光栅', 'grating', '衍射角', '入射角', 'diffraction angle', 'incident angle']
    content_to_check = (question + context).lower()
    is_triggered = any(kw in content_to_check for kw in trigger_keywords) and re.search(r'[ααi]|beta|[ββm]', content_to_check)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到斜入射光栅方程相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找光栅方程的表达形式 d(sin alpha +/- sin beta)
    # 重点检查是否考虑了 alpha 和 beta 的符号定义一致性
    pred = prediction.lower()
    # 匹配类似 d(sin... + sin...) 或 d(sin... - sin...)
    formula_pattern = r'd\s*\(?\s*sin\s*[ααi]?\s*[\+\-]\s*sin\s*[ββm]?\s*\)?'
    match = re.search(formula_pattern, pred)

    if not match:
        # 如果没有显式写出 d(sin+sin) 结构，检查是否有关于“同侧”、“异侧”或“法线”方向的描述
        if '法线' not in pred and 'normal' not in pred and 'side' not in pred:
            return {'result': 'fail', 'message': '在处理斜入射光栅问题时，未明确说明入射角与衍射角的定义方向或正负号逻辑', 'evidence': prediction[:200]}
        return {'result': 'inconclusive', 'message': '存在文字描述但缺乏明确的公式符号校验', 'evidence': ''}

    # Step 3: 符号一致性校验
    # 如果定义在法线同侧（same side），通常公式为 d(sin alpha - sin beta)；若顺着光路累加则为 d(sin alpha + sin beta)
    # 检查 prediction 是否对符号选取做了物理说明
    logic_keywords = ['同侧', '异侧', '方向', 'sign', 'convention', 'positive', 'negative']
    has_logic = any(lk in pred for lk in logic_keywords)

    if not has_logic:
        return {'result': 'fail', 'message': '给出了光栅方程但未对 alpha 和 beta 的正负号定义（方向约定）进行逻辑说明', 'evidence': match.group()}

    # 检查 canonical 符号覆盖
    required_symbols = ['d', 'sin', 'm']
    missing = [s for s in required_symbols if s not in pred]
    if not missing:
        return {'result': 'pass', 'message': '公式结构完整且包含了角度定义相关的逻辑描述', 'evidence': match.group()}

    return {'result': 'inconclusive', 'message': '逻辑要素不全，无法判定正误', 'evidence': ''}

# rule_id=norm_2f23860f2654abaa | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_2f23860f2654abaa | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_2f23860f2654abaa_044b74ca89a9(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多缝干涉的主极大宽度或条纹宽度
    trigger_keywords = ['主极大宽度', '条纹宽度', 'width of the principal maxima', 'fringe width']
    is_multi_slit = any(kw in (question + context) for kw in ['多缝', 'N个缝', '光栅', 'grating', 'N slits'])
    is_width_req = any(kw in (question + context) for kw in trigger_keywords)

    if not (is_multi_slit and is_width_req):
        return {'result': 'inconclusive', 'message': '未检测到多缝干涉主极大宽度计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证公式分母是否包含缝数 N (或 n)
    # 主极大宽度通常正比于 1/(Nd)，若只写 1/d 则属于典型错误
    pred_text = prediction.replace(' ', '')
    # 匹配类似 Δx = 2λL / (Nd) 或类似的结构，重点在于分母是否有 N
    # 允许 N, n 作为缝数符号
    has_n_in_denominator = re.search(r'/[\(]?[^/]*[Nn][^/]*[dD]', pred_text) or \
                           re.search(r'\\frac{[^}]*}{[^}]*[Nn][^}]*}', pred_text)

    # 如果预测中提到了宽度公式，但分母明显缺失 N
    if 'width' in prediction.lower() or 'Δ' in prediction or 'delta' in prediction.lower():
        if not has_n_in_denominator:
            # 进一步确认是否误用了双缝干涉公式 (λL/d)
            if re.search(r'[λL]/[dD]', pred_text) or re.search(r'\\frac{.*}{[dD]}', pred_text):
                return {
                    'result': 'fail',
                    'message': '主极大宽度计算错误：公式分母缺失缝数 N，未考虑总孔径对分辨率的影响。',
                    'evidence': prediction
                }

    # Step 3: 符号覆盖检查
    required_symbols = ['L', 'N', 'd', 'λ']
    # 转换 lambda 符号
    norm_pred = prediction.replace('\\lambda', 'λ')
    missing_symbols = [s for s in required_symbols if s not in norm_pred and s.lower() not in norm_pred.lower()]

    if not missing_symbols and has_n_in_denominator:
        return {'result': 'pass', 'message': '公式结构符合多缝干涉主极大宽度定义', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '无法确定公式是否正确应用了 N 因子', 'evidence': ''}

# rule_id=norm_344c526e27819bb1 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_344c526e27819bb1 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_344c526e27819bb1_4aba40ee84ac(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否同时涉及光栅(diffraction grating)和狭缝宽度(slit width d)
    q_c_text = (question + context).lower()
    if 'diffraction grating' not in q_c_text or 'slit width' not in q_c_text:
        return {'result': 'inconclusive', 'message': '未检测到光栅与狭缝宽度并存的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否错误地将狭缝宽度 d 用于计算干涉极大位置（光栅方程）
    # 光栅方程通常应使用光栅常数 a 或 d_grating (通常 a = 1/N)，而 slit width d 决定包络
    pred = prediction.lower()
    # 寻找类似 d*sin(theta) = n*lambda 的模式，且这里的 d 被明确指代为 slit width
    # 如果 prediction 中直接用题目给出的 slit width d 代入光栅主极大公式，则判定为 modeling 错误
    grating_formula_patterns = [r'd\s*sin', r'd\s*\*\s*sin', r'sin.*=.*n.*lambda.*/\s*d']

    # 检查 symbolic_hint 中的公式结构 Δλ = d / (D * f) 是否被错误引用或符号混淆
    # 提示中要求 D, f 符号，若 prediction 中出现 d 与 D, f 的错误组合也需留意
    has_grating_eq = any(re.search(p, pred) for p in grating_formula_patterns)

    # Step 3: 判定逻辑
    # 如果预测中将 slit width (d) 直接作为 grating constant 使用来求 spectral lines 位置
    if has_grating_eq and ('slit width' in pred or 'width of the slit' in pred):
        # 进一步检查是否混淆了 d (slit width) 和 a/g (grating constant)
        if re.search(r'd\s*=\s*[0-9.]+\s*mm', q_c_text) and re.search(r'd\s*sin', pred):
             return {'result': 'fail', 'message': '错误地将狭缝宽度 d 用于光栅方程计算干涉极大位置', 'evidence': prediction[:200]}

    # 检查 symbolic_hint 要求的符号覆盖
    if 'D' in prediction and 'f' in prediction and 'd' in prediction:
        if re.search(r'd\s*/\s*\(\s*D\s*\*\s*f\s*\)', prediction):
            return {'result': 'pass', 'message': '正确识别并使用了相关物理量公式', 'evidence': 'Δλ = d / (D * f) pattern found'}

    return {'result': 'inconclusive', 'message': '无法明确判定 d 是否被误用', 'evidence': ''}

# rule_id=norm_4f5e161cb1e62790 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_4f5e161cb1e62790 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_4f5e161cb1e62790_155e9bfb1fbd(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及复眼（compound eye）或小眼（ommatidia）的分辨率优化场景
    trigger_keywords = ['复眼', 'compound eye', '小眼', 'ommatidia', 'ommatidium']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到复眼或小眼相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否同时考虑了衍射极限（diffraction）与几何/采样极限（sampling/geometric）
    pred_lower = prediction.lower()
    has_diffraction = any(kw in pred_lower for kw in ['diffraction', '衍射', 'lambda/d', 'λ/d'])
    has_geometric = any(kw in pred_lower for kw in ['sampling', 'geometric', '采样', '几何', 'd/r'])

    if not (has_diffraction and has_geometric):
        return {
            'result': 'fail',
            'message': '建模不完整：未同时考虑衍射极限（Δθ≈λ/d）与几何采样极限（Δθ≈d/r）的平衡',
            'evidence': prediction[:200]
        }

    # Step 3: 符号与公式校验 — 检查最优状态 d^2/r ≈ λ 或类似的平衡关系
    # 匹配 d^2/r, d**2/r, d^2 \approx r*lambda 等结构
    patterns = [
        r'd\^2\s*/\s*r',
        r'd\*\*2\s*/\s*r',
        r'd\^2\s*\\approx\s*\\lambda\s*r',
        r'\\lambda\s*\\approx\s*d\^2\s*/\s*r',
        r'd/r\s*.*\s*\\lambda/d'
    ]

    found_formula = False
    for pattern in patterns:
        if re.search(pattern, prediction, re.IGNORECASE):
            found_formula = True
            break

    if found_formula:
        return {'result': 'pass', 'message': '成功识别复眼分辨率优化的物理建模逻辑', 'evidence': '匹配到核心公式或平衡关系'}

    return {'result': 'inconclusive', 'message': '逻辑方向正确但缺乏明确的公式推导或量级相等说明', 'evidence': prediction[:150]}

# rule_id=norm_5ac09dd623099000 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_5ac09dd623099000 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_5ac09dd623099000_260a74aa456f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及可见光衍射极限或瑞利判据
    trigger_keywords = ['rayleigh criterion', 'diffraction limit', 'resolution', '瑞利判据', '衍射极限', '分辨率']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到可见光衍射极限相关场景', 'evidence': ''}

    # Step 2: 检查公式结构 (\Delta x \approx \lambda \cdot F\#)
    # 匹配 lambda, F#, 或相关的 1.22 因子
    formula_pattern = r'(\\lambda|lambda).*([Ff]#|[Ff]数|D|A)'
    if not re.search(formula_pattern, prediction) and not re.search(r'1\.22', prediction):
        return {'result': 'inconclusive', 'message': '未发现典型的衍射极限计算公式', 'evidence': prediction[:100]}

    # Step 3: 校验结果量级是否在 0.5μm 至 10μm 之间
    # 提取数值及其单位 (um, nm, mm)
    # 匹配如 0.8 um, 800 nm, 0.001 mm 等
    matches = re.findall(r'([0-9]*\.?[0-9]+)\s*(um|μm|nm|mm)', prediction.lower())

    if not matches:
        return {'result': 'inconclusive', 'message': '未在预测中找到明确的数值单位结果', 'evidence': ''}

    for val_str, unit in matches:
        try:
            val = float(val_str)
            # 统一换算为微米 (um)
            val_in_um = val
            if unit == 'nm':
                val_in_um = val / 1000.0
            elif unit == 'mm':
                val_in_um = val * 1000.0

            # 校验逻辑：可见光分辨率通常在 0.5um 到 10um 之间
            if 0.5 <= val_in_um <= 10.0:
                return {'result': 'pass', 'message': f'计算结果 {val}{unit} 在合理量级范围内', 'evidence': f'{val_str} {unit}'}

            # 如果出现明显的量级错误（如 nm 或 mm 级别且不在 0.5-10um 范围内）
            if val_in_um < 0.1 or val_in_um > 100.0:
                return {'result': 'fail', 'message': f'计算结果 {val}{unit} 偏离可见光分辨率常识量级，请检查单位换算', 'evidence': f'{val_str} {unit}'}
        except ValueError:
            continue

    return {'result': 'inconclusive', 'message': '数值量级未触发明确违反规则的判定', 'evidence': str(matches)}

# rule_id=norm_5ceaf79ef1b14b9c | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_5ceaf79ef1b14b9c | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_5ceaf79ef1b14b9c_69deeafae5d6(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及半波带（Zone Plate）及相位延迟/调制操作
    trigger_keywords = ['半波带', '波带片', 'zone plate', 'Fresnel zone']
    modulation_keywords = ['相位延迟', '相位差', '光程差', '增加', 'lambda/2', 'λ/2', 'pi', 'π', '调制']

    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and \
                   any(kw in combined_text for kw in modulation_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到半波带相位调制相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否识别出相位改变导致干涉加强（相消变相长）
    pred = prediction.lower()
    # 检查是否提到“增强”、“相长”、“同相”或“强度增大”等逻辑
    constructive_logic = ['增强', '相长', '同相', 'in phase', 'constructive', '强度增加', '变亮']
    # 检查是否提到原本是“相消”或“抵消”的相邻带
    destructive_origin = ['相消', '抵消', 'destructive', '相反', 'out of phase']

    has_constructive = any(kw in pred for kw in constructive_logic)

    # Step 3: 符号/公式校验 — 检查是否符合 Delta phi = 2n*pi 或类似的相位补偿逻辑
    # 匹配 lambda/2 导致 pi 相位变化的描述
    phase_match = re.search(r'(\pi|180|lambda/2|λ/2)', pred)

    if not has_constructive:
        return {
            'result': 'fail',
            'message': '未识别出相位调制（如增加λ/2光程）将使相邻半波带由相消干涉转为相长干涉，从而增强强度的逻辑',
            'evidence': prediction[:200]
        }

    if phase_match and ('2n' in pred or '同相' in pred or '叠加' in pred):
        return {
            'result': 'pass',
            'message': '正确识别了半波带相位调制导致的干涉加强效应',
            'evidence': f'匹配到相位逻辑: {phase_match.group()}'
        }

    return {'result': 'inconclusive', 'message': '逻辑描述不完整，无法判定是否完全掌握相位调制原理', 'evidence': prediction[:100]}

# rule_id=norm_7d48f252f01cae73 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_7d48f252f01cae73 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_7d48f252f01cae73_0f691cc769c9(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及面阵传感器、像素数估算或分辨率限制下的总数计算
    trigger_keywords = ['像素', 'pixel', 'sensor', '传感器', '阵列', 'array', '分辨率', 'resolution']
    combined_text = (question + context).lower()
    if not any(k in combined_text for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到传感器像素建模场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找总像素数 N 与 线性比值 (L/d) 的平方关系
    # 匹配 N = (L/d)^2 或 N = L^2 / d^2 及其变体
    pred = prediction.lower()
    # 检查是否提到了总数 N 以及 长度 L 和 像素尺寸 d (或 delta x)
    # 模式匹配：寻找类似 (L/d)^2, (L/delta)^2, L**2/d**2, (L/d)的平方 等表达
    square_pattern = r'(\([^\)]+/?[^\)]+\)\s*(\^|\*\*)\s*2|L\^2|d\^2|L\*\*2|d\*\*2|平方|square)'
    ratio_pattern = r'([Ll]\s*/\s*[Dd]|[Ll]\s*/\s*\\?delta|L\s*/\s*\\Delta)'

    # 如果 prediction 中完全没有体现平方关系，且在讨论总像素数，则判定为建模错误
    if 'n' in pred and ('total' in pred or '像素' in pred):
        # 检查是否错误地使用了线性关系 N = L/d
        linear_error = re.search(r'[Nn]\s*=\s*[Ll]\s*/\s*([Dd]|\\?delta)', pred)
        if linear_error and not re.search(square_pattern, pred):
            return {'result': 'fail', 'message': '总像素数建模错误：遗漏了平方关系，误用了线性比例', 'evidence': linear_error.group()}

    # Step 3: 符号与公式结构校验
    # 检查 canonical 形式: N = (L / Δx)^2
    if re.search(r'[Nn]\s*=\s*\(?[Ll]\s*/\s*([^\)]+)\)?\s*(\^|\*\*)\s*2', pred):
        return {'result': 'pass', 'message': '正确建立了像素总数与线性分辨率的平方关系', 'evidence': '检测到符合 N = (L/d)^2 的公式结构'}

    # 如果提到了平方但格式不标准，保守返回 inconclusive
    if re.search(square_pattern, pred) and re.search(ratio_pattern, pred):
        return {'result': 'pass', 'message': '识别到像素数与分辨率比值的平方关系', 'evidence': '包含平方与比例项'}

    return {'result': 'inconclusive', 'message': '未能明确识别像素数建模公式', 'evidence': prediction[:150]}

# rule_id=norm_84e4d59cc5acc6ce | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_84e4d59cc5acc6ce | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_84e4d59cc5acc6ce_8765db0576d8(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及激光远场传输（波长λ、口径D、距离L）
    trigger_keywords = ['激光', 'laser', '波长', 'λ', 'lambda', '口径', 'aperture', 'D', '距离', 'L', '远场', 'far field']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到激光远场传输场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须包含衍射发散角 θ ≈ λ/D 的计算或考虑
    pred = prediction.lower()
    # 匹配发散角公式或描述：lambda/D, λ/D, divergence angle
    div_pattern = r'(\\lambda|lambda|λ)\s*/\s*D|divergence|发散角'
    if not re.search(div_pattern, pred):
        return {'result': 'fail', 'message': '建模过程中未考虑衍射发散角 θ ≈ λ/D', 'evidence': prediction[:200]}

    # Step 3: 检查逻辑 — 检查是否对比了光斑半径 R = Lθ 与接收器半径 r 或计算了截获能量
    # 寻找 L*theta, L*lambda/D 或 能量比例/截获相关的关键词
    energy_pattern = r'L\s*\*\s*(\\theta|theta|θ)|L\s*(\\lambda|lambda|λ)/D|intercept|receive|截获|接收'
    if not re.search(energy_pattern, pred):
        return {'result': 'fail', 'message': '未计算远场光斑大小或未评估接收器截获能量比例', 'evidence': prediction[:200]}

    # Step 4: 符号覆盖检查 (D, L, λ)
    required_symbols = ['D', 'L', 'λ']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction or sym in question)
    if symbol_count >= 2 and re.search(div_pattern, pred):
        return {'result': 'pass', 'message': '已按要求建立衍射发散模型并考虑能量截获', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程不完整，无法确定是否正确建模', 'evidence': ''}

# rule_id=norm_927e3f32562873cd | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_927e3f32562873cd | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_927e3f32562873cd_155e9bfb1fbd(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及复眼（compound eye）、小眼（ommatidia）及相关参数
    trigger_keywords = ['复眼', 'compound eye', '小眼', 'ommatidia', 'ommatidium']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到复眼或小眼相关物理场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否讨论了衍射极限与几何分辨率的平衡，或提到了最优直径 d
    pred_lower = prediction.lower()
    # 检查是否包含核心物理量符号：d (直径), r (半径), lambda (波长)
    # 允许 LaTeX 格式或普通文本格式
    has_d = 'd' in pred_lower or '\\delta' in pred_lower
    has_r = 'r' in pred_lower or 'radius' in pred_lower
    has_lambda = 'lambda' in pred_lower or '\\lambda' in pred_lower

    if not (has_d and (has_r or has_lambda)):
        return {'result': 'fail', 'message': '模型缺失关键物理量（直径d、半径r或波长λ）', 'evidence': prediction[:200]}

    # Step 3: 公式校验 — 检查是否应用了 d^2 ≈ λr 或 d ≈ sqrt(λr) 的关系
    # 匹配模式包括 d^2 ~ lambda*r, d = sqrt(lambda*r), lambda/d = d/r 等变形
    patterns = [
        r'd\^2.*[\\approx|~|=].*\\lambda.*r',
        r'd.*[\\approx|~|=].*\\sqrt{.*\\lambda.*r}',
        r'\\lambda/d.*[\\approx|~|=].*d/r',
        r'd.*[\\approx|~|=].*\\sqrt{r.*\\lambda}',
        r'd\^2/r.*\\lambda'
    ]

    found_formula = False
    for pattern in patterns:
        if re.search(pattern, prediction.replace(' ', '')):
            found_formula = True
            break

    if found_formula:
        return {'result': 'pass', 'message': '成功应用复眼最优分辨率建模公式', 'evidence': re.search(r'.{0,30}d.{0,30}', prediction).group(0) if 'd' in prediction else ''}

    # 如果提到了平衡或最优，但公式不显式，则保守返回 inconclusive
    if 'optimal' in pred_lower or 'limit' in pred_lower or '平衡' in pred_lower:
        return {'result': 'inconclusive', 'message': '提到了优化概念但未见明确的 d^2 ≈ λr 公式', 'evidence': prediction[:150]}

    return {'result': 'fail', 'message': '未体现衍射极限与几何分辨率的平衡关系（d^2 ≈ λr）', 'evidence': prediction[:200]}

# rule_id=norm_9be48e7ea1f97875 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_9be48e7ea1f97875 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_9be48e7ea1f97875_b1f6f6565652(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及单色仪、出射狭缝及光谱宽度计算
    trigger_keywords = ['monochromator', '单色仪', '狭缝', 'slit width', '光谱宽度', 'spectral width', 'Δλ']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到单色仪光谱宽度相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 严禁直接将几何长度平方与半径相除 (如 d^2/R) 作为波长量级
    # 这种错误通常出现在混淆了像差公式与色散公式时
    pred = prediction.lower()
    if re.search(r'd\^2\s*/\s*r', pred) or re.search(r'w\^2\s*/\s*r', pred):
        return {'result': 'fail', 'message': '错误地将几何长度平方与半径相除作为波长量级，未应用色散关系', 'evidence': '检测到类似 d^2/R 的错误建模'}

    # Step 3: 符号与公式校验 — 检查是否应用 Δλ = d / (R * dθ/dλ) 或类似色散关系
    # 核心要素：狭缝宽度 d_slit, 半径 R (或焦距 f), 色散率 (m/a*cosθ)
    has_slit = 'd' in pred or 'slit' in pred or 'w' in pred
    has_radius = 'r' in pred or 'f' in pred
    has_dispersion = 'cos' in pred or 'm/' in pred or 'dθ' in pred or 'dtheta' in pred

    # 匹配 canonical 形式的变体: Δλ = d / (R * (m/a * cosθ))
    formula_pattern = r'd\s*/\s*\(\s*[Rf].*cos'
    if re.search(formula_pattern, pred) or (has_slit and has_radius and has_dispersion):
        return {'result': 'pass', 'message': '正确应用了色散关系建模光谱宽度', 'evidence': '检测到符合色散关系的公式结构'}

    return {'result': 'inconclusive', 'message': '未能明确识别光谱宽度建模公式', 'evidence': ''}

# rule_id=norm_a18597ec1dffc67d | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_a18597ec1dffc67d | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_a18597ec1dffc67d_fb544fc28f8f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及相干长度 (coherence length) 且已知带宽 (bandwidth/delta lambda)
    trigger_keywords = ['coherence length', '相干长度', 'Lc', 'L_c']
    bandwidth_keywords = ['delta lambda', 'Δλ', 'bandwidth', '带宽', 'spectral width']

    combined_text = (question + context).lower()
    if not any(k in combined_text for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到相干长度计算场景', 'evidence': ''}
    if not any(k in combined_text for k in bandwidth_keywords):
        return {'result': 'inconclusive', 'message': '未检测到带宽/波长宽度相关参数', 'evidence': ''}

    # Step 2: 检查预测中是否包含核心公式 Lc = λ^2 / Δλ 的结构
    # 匹配 λ^2/Δλ 或类似的除法关系，考虑不同的符号表示
    pred = prediction.lower()
    formula_pattern = r'(\lambda\s*\^?\s*2|\w+\s*\*\*\s*2)\s*/\s*(\Delta\s*\lambda|d\s*lambda|delta)'
    has_formula = re.search(formula_pattern, pred) or 'lambda^2' in pred or 'λ^2' in pred

    # Step 3: 检查是否存在数量级偏差风险（如单位换算错误）
    # 如果提到了 pm (皮米) 或 nm (纳米) 但计算中没有体现 10^3 或 10^-3 的转换，通常会导致 Lc 偏差
    unit_mismatch = ('pm' in combined_text and 'nm' in combined_text) or ('nm' in combined_text and 'um' in combined_text)

    if not has_formula and 'Lc' not in prediction and 'L_c' not in prediction:
        return {'result': 'fail', 'message': '预测中未发现相干长度的核心计算公式或符号 Lc', 'evidence': prediction[:200]}

    # 验证公式结构的正确性
    if re.search(r'L_?c\s*[:=~]\s*\w*\^2\s*/', prediction, re.IGNORECASE) or re.search(r'\w*\^2\s*/\s*\Delta', prediction):
        return {'result': 'pass', 'message': '检测到正确的相干长度与带宽关系公式', 'evidence': re.search(r'.{0,30}(\^2|/|Lc).{0,30}', prediction).group(0) if re.search(r'.{0,30}(\^2|/|Lc).{0,30}', prediction) else ''}

    return {'result': 'inconclusive', 'message': '公式结构不完整或数值计算过程不详', 'evidence': prediction[:150]}

# rule_id=norm_b1fd40de68d5ab2a | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_b1fd40de68d5ab2a | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_b1fd40de68d5ab2a_aab418ed3101(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及三维斜入射（非垂直于狭缝方向的夹角 phi 或斜入射描述）
    trigger_keywords = ['斜入射', 'oblique', 'conical diffraction', 'phi', '夹角', '三维', '3D']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords) or '光栅' not in combined_text:
        return {'result': 'inconclusive', 'message': '未检测到三维斜入射光栅衍射场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否考虑了分量投影，而非简单的二维角度代数和
    # 错误建模通常直接使用 d(sin alpha + sin beta)，正确建模需涉及 sqrt(sin^2 - sin^2 phi) 或类似的投影项
    pred = prediction.lower()

    # 检查是否使用了错误的二维简化公式（如果明确只用了 sin alpha + sin beta 而忽略了 phi 的投影效应）
    wrong_pattern = r'd\s*\(\s*sin\s*.*\+\s*sin\s*.*\)\s*=\s*m\s*lambda'
    correct_projection_pattern = r'sin\^2|sqrt|cos\s*phi|projection|分量'

    # Step 3: 符号与公式结构校验
    # 检查 canonical 要求的符号是否存在
    required_symbols = ['phi', 'alpha', 'beta']
    symbol_count = sum(1 for sym in required_symbols if sym in pred)

    if symbol_count >= 2:
        # 寻找复杂的投影结构，如 sqrt(sin^2 alpha - sin^2 phi)
        if re.search(r'sqrt\(.*sin\^2.*sin\^2.*phi.*\)', pred) or re.search(r'cos.*phi.*sin', pred):
            return {'result': 'pass', 'message': '检测到正确的分量投影建模', 'evidence': re.search(r'.{0,50}(sqrt|sin\^2|cos\s*phi).{0,50}', pred).group(0) if re.search(r'.{0,50}(sqrt|sin\^2|cos\s*phi).{0,50}', pred) else ''}

        # 如果只用了简单的二维公式而题目是三维斜入射，则判定为建模错误
        if re.search(r'd\s*\(\s*sin[^\^]*\)', pred) and 'phi' in pred and 'sqrt' not in pred:
            return {'result': 'fail', 'message': '光程差计算未采用分量投影，可能错误地使用了二维简化公式', 'evidence': 'Formula lacks projection components for 3D incidence'}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了三维投影逻辑', 'evidence': pred[:100]}

# rule_id=norm_b43fe293b2e03db8 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_b43fe293b2e03db8 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_b43fe293b2e03db8_8908b97b747d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及漫反射与反射器（如月球、反射镜）的对比
    trigger_keywords = ['diffuse', 'reflector', 'gain', '漫反射', '反射器', '倍数', '增益']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到漫反射与反射器对比场景', 'evidence': ''}

    # Step 2: 检查逻辑要素 — 是否考虑了衍射极限 (lambda/d) 或立体角对比
    pred_lower = prediction.lower()
    logic_keywords = ['diffraction', 'limit', 'lambda', 'wavelength', 'solid angle', '衍射', '波长', '立体角']
    if not any(kw in pred_lower for kw in logic_keywords):
        return {'result': 'fail', 'message': '推理中未提及衍射极限或立体角对比逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号与公式结构校验 — 检查 G ∝ (D*d / (L*lambda))^2 相关的符号覆盖
    # 符号要求: D (接收器/发射器孔径), L (距离), λ (波长), d (反射器尺寸)
    required_symbols = ['D', 'L', 'λ', 'lambda']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction or sym in (question + context))

    # 检查公式结构特征：平方关系或比例关系
    has_formula_structure = re.search(r'\^2|squared|proportional|/\s*lambda', pred_lower)

    if symbol_count >= 2 and has_formula_structure:
        return {'result': 'pass', 'message': '包含了增益对比的核心物理量与比例逻辑', 'evidence': prediction[:200]}

    if symbol_count < 1:
        return {'result': 'fail', 'message': '缺失关键物理符号（如波长、距离或孔径）', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑要素不完整，无法判定', 'evidence': ''}

# rule_id=norm_cebf9853b9a24717 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_cebf9853b9a24717 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_cebf9853b9a24717_e646460ab278(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及 N 个等幅矢量/波的叠加、相位差或衍射合成
    trigger_keywords = ['等幅', '相位差', '矢量链', '矢量合成', 'N个', '衍射', 'diffraction', 'superposition', 'phase difference']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多波/矢量等幅叠加场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找合矢量相位 Φ_res 与首尾相位 (Φ_1, Φ_N) 的算术平均关系
    # 核心逻辑：Φ_res = (Φ_1 + Φ_N) / 2 或 Δφ = (N-1)δ/2
    pred = prediction.lower()
    # 匹配算术平均的描述或公式
    pattern_avg = r'(\phi_1\s*\+\s*\phi_n)/2|\(phi_1\s*\+\s*phi_n\)/2|算术平均|average of phases'
    # 匹配 symbolic_hint 中的 canonical 形式：(N-1)delta/2 或 (N-1)beta
    pattern_formula = r'\(n-1\)\s*\*?\s*delta\s*/\s*2|\(n-1\)\s*\*?\s*beta'

    has_avg_logic = re.search(pattern_avg, pred) or re.search(pattern_formula, pred)

    # Step 3: 判定结果
    if has_avg_logic:
        return {
            'result': 'pass',
            'message': '检测到合矢量相位为首尾相位算术平均值的正确逻辑',
            'evidence': re.search(f'({pattern_avg}|{pattern_formula})', pred).group(0) if re.search(f'({pattern_avg}|{pattern_formula})', pred) else ''
        }

    # 如果提到了相位合成但没有体现算术平均关系，则视为逻辑缺失或错误
    if 'phase' in pred or '相位' in pred:
        return {
            'result': 'fail',
            'message': '未体现合矢量相位为首尾矢量相位算术平均值的判定逻辑',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '证据不足，无法判定相位合成逻辑', 'evidence': ''}

# rule_id=norm_fba1afd812795284 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
# rule_id=norm_fba1afd812795284 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_fba1afd812795284_6e670c5df02d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否存在折射率周期性空间调制的描述
    # 匹配 n(y), n(x), n0 + delta n, sin/cos 周期项, 或 lambda_s/d_s 等空间周期描述
    trigger_pattern = r'(n\s*\(\s*[xy]\s*\)|折射率|refractive index).*?(sin|cos|周期|period|modulation)'
    if not re.search(trigger_pattern, question + context, re.IGNORECASE):
        return {'result': 'inconclusive', 'message': '未检测到介质折射率周期性调制的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否将空间周期 lambda_s 映射为光栅常数 d
    # 寻找类似 d = lambda_s 或将周期值代入光栅方程的迹象
    pred_lower = prediction.lower()
    mapping_pattern = r'(d\s*=\s*λ_?s|d\s*=\s*lambda_?s|光栅常数.*?周期)'
    has_mapping = re.search(mapping_pattern, pred_lower) or ('d' in pred_lower and ('lambda_s' in pred_lower or 'λs' in pred_lower))

    # Step 3: 检查公式应用 — 是否使用了光栅方程 d sinθ = mλ
    grating_eq_pattern = r'd\s*sin\s*θ\s*=\s*m\s*λ|d\s*sin\s*theta\s*=\s*n\s*lambda'
    has_grating_eq = re.search(grating_eq_pattern, pred_lower)

    if not has_mapping and not has_grating_eq:
        return {
            'result': 'fail',
            'message': '未发现将空间调制周期映射为光栅常数并应用光栅方程的推理过程',
            'evidence': prediction[:200]
        }

    if has_mapping and has_grating_eq:
        return {
            'result': 'pass',
            'message': '成功识别周期调制并应用光栅方程进行等效处理',
            'evidence': re.search(grating_eq_pattern, pred_lower).group(0) if has_grating_eq else ''
        }

    return {'result': 'inconclusive', 'message': '检测到部分建模要素，但推导链条不完整', 'evidence': prediction[:150]}

# rule_id=norm_5f9f935d695537bf | domain=Optics | topic=Polarization of Light
# rule_id=norm_5f9f935d695537bf | domain=Optics | topic=Polarization of Light
def check_norm_5f9f935d695537bf_5f9f28c8f77d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多个偏振器或连续偏振变换场景
    trigger_keywords = ['偏振', 'polarizer', 'polarization', '检偏', '尼科耳']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到偏振相关场景', 'evidence': ''}

    # 检查是否涉及连续/多个变换（如“依次”、“通过...后又通过”）
    if not re.search(r'(连续|依次|多个|相继|second|successive|series)', combined_text):
        return {'result': 'inconclusive', 'message': '未明确涉及连续偏振变换过程', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否应用了投影变换逻辑（马吕斯定律或矢量投影）
    pred = prediction.lower()
    # 检查是否包含余弦平方（强度）或余弦（振幅/矢量投影）的逻辑描述
    projection_logic = re.search(r'(cos|cos\^2|投影|projection|malus|马吕斯)', pred)
    if not projection_logic:
        return {'result': 'fail', 'message': '预测中未体现偏振矢量的投影变换逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 symbolic_hint 中的关键符号和结构
    # 检查是否包含角度差变换或特定的偏振矢量符号
    required_patterns = [
        r'cos\s*\(\s*\\?delta\s*\\?theta\s*\)',
        r'\\gamma',
        r'\\hat\{i\}\'',
        r'E_\{in\}',
        r'cos'
    ]

    match_count = 0
    for pattern in required_patterns:
        if re.search(pattern, prediction):
            match_count += 1

    if match_count >= 1:
        return {'result': 'pass', 'message': '符合偏振投影连续变换逻辑及公式要求', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑描述存在但关键公式符号不完整', 'evidence': prediction[:200]}

# rule_id=norm_6646928c68c2dd4d | domain=Optics | topic=Polarization of Light
# rule_id=norm_6646928c68c2dd4d | domain=Optics | topic=Polarization of Light
def check_norm_6646928c68c2dd4d_437a0ef2fd38(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及 e 光波矢 k 与射线方向 N_e 的夹角计算
    trigger_keywords = ['夹角', 'angle', 'alpha', 'α', '波矢', '射线', 'k', 'N_e', 'ray direction']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in ['e光', 'extraordinary', '双折射', 'birefringence']):
        return {'result': 'inconclusive', 'message': '未检测到双折射或e光相关场景', 'evidence': ''}
    if not any(kw in combined_text for kw in ['夹角', 'angle', 'alpha', 'α']):
        return {'result': 'inconclusive', 'message': '未检测到夹角计算需求', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否区分了相速度方向（波法线）与群速度方向（射线方向）
    pred = prediction.lower()
    distinguish_keywords = ['相速度', '群速度', '波法线', '射线方向', 'phase velocity', 'group velocity', 'wave normal', 'ray direction']
    if not any(kw in pred for kw in distinguish_keywords):
        return {'result': 'fail', 'message': '未明确区分相速度方向（波法线）与群速度方向（射线方向）', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查是否使用了折射率主值 n_o, n_e 及光轴夹角 θ 的函数关系
    # 核心公式特征：tan(alpha) 且包含 n_o, n_e, sin, cos, theta
    required_symbols = ['n_o', 'n_e', 'theta', 'θ']
    symbol_count = sum(1 for sym in required_symbols if sym in pred or sym in prediction)

    # 检查公式结构特征：(n_o^2 - n_e^2) * sin * cos / (n_o^2*sin^2 + n_e^2*cos^2)
    formula_pattern = r'tan.*[\(（].*[\)）].*n_o.*n_e.*(sin|cos)'
    has_formula = re.search(formula_pattern, pred) or 'tan' in pred

    if symbol_count >= 2 and has_formula:
        return {'result': 'pass', 'message': '已正确使用折射率主值与夹角的函数关系进行校验', 'evidence': prediction[:200]}

    if symbol_count < 2:
        return {'result': 'fail', 'message': '计算夹角时缺失必要的折射率主值(n_o, n_e)或光轴夹角(theta)参数', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程中公式表达不完整，无法判定准确性', 'evidence': prediction[:200]}

