# rule_id=norm_886a8e6d4f02e37f | domain=Optics | topic=Dispersion and Chromatic Aberration
def check_norm_886a8e6d4f02e37f_106008e1f5be(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否包含测量工具（ruler, tape）及色散/波长相关背景
    trigger_keywords = ['ruler', 'measuring tape', '直尺', '卷尺', '刻度尺', 'wavelength', '波长', 'fringe', '条纹']
    q_c_text = (question + context).lower()
    if not any(kw in q_c_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到具体的测量工具或波长相关实验背景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否建立了几何测量量（H, z, alpha, L）与物理常数（n, dn/dλ）的关联
    # 重点检查 prediction 是否包含几何建模过程，而非纯代数计算
    pred_text = prediction.lower()
    # 检查 symbolic_hint 中的关键符号
    required_symbols = ['H', 'z', 'α', 'λ']
    symbol_count = sum(1 for sym in required_symbols if sym.lower() in pred_text or sym in prediction)

    # 检查几何关联词汇
    geometry_keywords = ['geometry', 'path', 'triangle', 'angle', 'distance', '几何', '光路', '三角形', '角度', '距离']
    has_geometry = any(kw in pred_text for kw in geometry_keywords)

    if symbol_count < 2 and not has_geometry:
        return {
            'result': 'fail',
            'message': '模型未能将几何测量量与物理常数通过光路几何关联，缺乏建模过程',
            'evidence': prediction[:200]
        }

    # Step 3: 公式结构校验 — 检查是否存在类似 dn/dλ ∝ Δx / (L * Δλ) 的比例或导数关系
    # 匹配包含 n, lambda, L, x/z/H 的公式结构
    formula_pattern = r'(dn/d|d n / d|Δn/Δ|delta n).*([xHzLαα])'
    if re.search(formula_pattern, prediction, re.IGNORECASE) or 'dn/d' in pred_text:
        return {
            'result': 'pass',
            'message': '检测到几何建模与色散率的关联公式',
            'evidence': re.search(r'.{0,50}dn/d.{0,50}', prediction, re.IGNORECASE).group(0) if 'dn/d' in pred_text else ''
        }

    return {'result': 'inconclusive', 'message': '检测到部分要素但无法确定建模完整性', 'evidence': prediction[:100]}

# rule_id=norm_8327e3fc524ef7a6 | domain=Optics | topic=Optical Coherence and Interferometers
# rule_id=norm_8327e3fc524ef7a6 | domain=Optics | topic=Optical Coherence and Interferometers
def check_norm_8327e3fc524ef7a6_917107166fa8(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及宽谱光源、干涉仪及谱线数量计算
    trigger_keywords = ['谱线', 'number of lines', 'spectral lines', 'FSR', '自由光谱范围']
    if not any(k in (question + context) for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到宽谱光源干涉仪谱线计数场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否使用了 N = Δλ_source / Δλ_FSR 的逻辑
    # 检查是否包含带宽除以FSR的意图
    pred_lower = prediction.lower()
    has_ratio = re.search(r'(/|除以|ratio).*FSR', pred_lower) or re.search(r'Δλ.*/.*Δλ', pred_lower)

    if 'fsr' not in pred_lower and '自由光谱范围' not in pred_lower:
        return {'result': 'fail', 'message': '计算谱线数量时未考虑自由光谱范围 (FSR)', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 FSR 的定义公式 λ² / (2nt cosθ)
    # 检查关键符号 n, t (或 d), Δλ 是否出现
    required_symbols = ['n', 't', 'd', 'λ', 'delta']
    symbol_count = sum(1 for s in required_symbols if s in pred_lower or s in prediction)

    # 检查 FSR 公式结构 (lambda^2 / 2nt)
    fsr_formula_pattern = r'λ\^2\s*/\s*\(2.*n.*t\)'
    has_fsr_formula = re.search(fsr_formula_pattern, prediction) or '2nt' in pred_lower

    if not has_ratio:
        return {'result': 'fail', 'message': '未体现谱线数等于带宽除以FSR的计算逻辑', 'evidence': prediction[:200]}

    if symbol_count >= 2 or has_fsr_formula:
        return {'result': 'pass', 'message': '谱线计数逻辑与FSR公式校验通过', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑存在但公式细节不足以判定', 'evidence': prediction[:200]}

# rule_id=norm_89bd4f7da88e77ef | domain=Optics | topic=Optical Coherence and Interferometers
# rule_id=norm_89bd4f7da88e77ef | domain=Optics | topic=Optical Coherence and Interferometers
def check_norm_89bd4f7da88e77ef_7ef472571921(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及 Fabry-Perot 腔的透射谱线宽度或半高宽
    trigger_keywords = ['Fabry-Perot', 'F-P腔', '法布里-珀罗', '透射谱线', '谱线宽度', '半高宽', 'FWHM', 'linewidth']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到F-P腔透射谱线宽度相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否区分了腔共振峰宽度与光源带宽，并提及细度(Finesse)或FSR
    pred = prediction.lower()
    # 检查是否包含核心物理量：自由光谱范围(FSR) 和 细度(Finesse/F) 或 反射率(R)
    has_fsr = 'fsr' in pred or '自由光谱范围' in pred
    has_finesse = 'finesse' in pred or '细度' in pred or 'f=' in pred
    has_r = '反射率' in pred or ' r ' in pred or 'r=' in pred

    if not (has_fsr and (has_finesse or has_r)):
        return {
            'result': 'fail',
            'message': '未正确应用F-P腔透射峰宽度计算逻辑，需结合FSR与细度(Finesse)或反射率(R)',
            'evidence': prediction[:200]
        }

    # Step 3: 公式结构校验 — 检查是否符合 Δν = FSR / F 或包含反射率的细度公式
    # 匹配 Δν = FSR / F 或 Δν = FSR * (1-R) / (pi * sqrt(R))
    formula_patterns = [
        r'fsr\s*/\s*[fF]',
        r'fsr\s*\*\s*\(1\s*-\s*[rR]\)\s*/\s*\(\s*pi\s*\*\s*sqrt\([rR]\)\)',
        r'\(1\s*-\s*[rR]\)\s*/\s*\(\s*pi\s*\*\s*[rR]\^0\.5\)'
    ]

    found_formula = any(re.search(p, pred.replace(' ', '')) for p in formula_patterns)

    if found_formula:
        return {'result': 'pass', 'message': '正确使用了F-P腔透射峰宽度与FSR、细度的关系公式', 'evidence': prediction[:200]}

    # 如果有相关描述但公式不显式，保守返回 inconclusive
    if 'fsr' in pred and ('width' in pred or '宽度' in pred):
        return {'result': 'inconclusive', 'message': '检测到相关物理量但公式表达不完整', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足', 'evidence': ''}

# rule_id=norm_cd76f6514af55313 | domain=Optics | topic=Laser Principles and Applications
# rule_id=norm_cd76f6514af55313 | domain=Optics | topic=Laser Principles and Applications
def check_norm_cd76f6514af55313_684f14f00f0c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否存在谐振腔及增益介质（gain medium/crystal/medium）
    trigger_keywords = ['gain medium', '增益介质', 'crystal', '晶体', '介质', 'cavity', '谐振腔']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到谐振腔或增益介质场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找有效光程修正 L_eff = (L-d) + n*d 的逻辑或公式
    # 匹配 L-d+nd, L+(n-1)d, (L-d)+nd 等变体
    eff_path_patterns = [
        r'L\s*-\s*d\s*\+\s*n\s*\*?\s*d',
        r'L\s*\+\s*\(\s*n\s*-\s*1\s*\)\s*\*?\s*d',
        r'L_?eff',
        r'有效光程'
    ]

    pred_text = prediction.replace(' ', '')
    found_logic = any(re.search(p, prediction, re.IGNORECASE) or re.search(p.replace('\\s*', ''), pred_text) for p in eff_path_patterns)

    # Step 3: 符号/公式校验 — 检查 Δt 或 Δν 的计算是否包含修正后的光程
    # 目标公式: \Delta t = 2(L-d+nd)/c 或 \Delta \nu = c / [2(L-d+nd)]
    formula_patterns = [
        r'2\s*\*?\s*\(?L\s*-\s*d\s*\+\s*n\s*d\)?\s*/\s*c',
        r'c\s*/\s*\(?2\s*\*?\s*\(?L\s*-\s*d\s*\+\s*n\s*d\)?\)?'
    ]

    found_formula = any(re.search(p, prediction, re.IGNORECASE) or re.search(p.replace('\\s*', ''), pred_text) for p in formula_patterns)

    if found_formula:
        return {'result': 'pass', 'message': '正确应用了介质腔光程修正公式', 'evidence': prediction[:200]}

    if not found_logic and ('d' in question and 'n' in question):
        return {'result': 'fail', 'message': '计算往返时间或频率间隔时未见有效光程修正逻辑 (L-d+nd)', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否执行了正确的光程修正', 'evidence': ''}

