# rule_id=norm_d4b7e1858ac291de | domain=Optics | topic=Laser Principles and Applications
def check_norm_d4b7e1858ac291de_17b92159f029(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题干是否包含“From the result of”或参考答案是否为纯数值
    is_numeric_answer = bool(re.fullmatch(r'[+-]?\d*\.?\d+([eE][+-]?\d+)?\s*[a-zA-Z/\^]*', answer.strip()))
    trigger_phrase = "from the result of" in (question + context).lower()

    if not (is_numeric_answer or trigger_phrase):
        return {'result': 'inconclusive', 'message': '未检测到数值关联性触发条件', 'evidence': ''}

    # Step 2: 检查逻辑 — 若参考答案为数值，预测结果是否仅停留在符号阶段
    # 检查 prediction 中是否包含最终的数值计算结果（寻找数字）
    has_numeric_result = bool(re.search(r'\d+\.?\d*', prediction))

    # 如果参考答案是纯数值，但预测中没有明显的数值计算或结果，则判定为失败
    if is_numeric_answer and not has_numeric_result:
        return {
            'result': 'fail',
            'message': '参考答案要求数值结果，但预测仅包含符号推导或缺失数值代入过程',
            'evidence': prediction[-200:]
        }

    # Step 3: 检查是否引用了前序小题或上下文中的常量进行代入
    # 简单检查 prediction 是否包含等号后的数值赋值或计算迹象
    if re.search(r'=[^=]*\d+', prediction):
        return {'result': 'pass', 'message': '预测包含数值代入与计算过程', 'evidence': prediction[-150:]}

    return {'result': 'inconclusive', 'message': '无法确定数值代入的完整性', 'evidence': ''}

# rule_id=norm_06374cf9e920bcd7 | domain=Optics | topic=Nonlinear Optics (Harmonic Generation, Self-Focusing)
# rule_id=norm_06374cf9e920bcd7 | domain=Optics | topic=Nonlinear Optics (Harmonic Generation, Self-Focusing)
def check_norm_06374cf9e920bcd7_7173f3a0a8eb(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及自聚焦(self-focusing)或临界功率(critical power)
    trigger_keywords = ['自聚焦', '临界功率', 'self-focusing', 'critical power', '不发生衍射', 'diffraction balance']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到自聚焦临界功率相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 临界功率是否独立于光束半径 R
    # 错误建模通常会错误地让临界功率依赖于半径 R 或 w (beam waist)
    pred_lower = prediction.lower()
    # 寻找关于半径独立性的描述或公式中排除半径的逻辑
    radius_terms = ['半径', 'radius', 'beam width', 'beam waist', ' w ', ' R ']
    independence_keywords = ['无关', 'independent', 'cancel out', '抵消', '不取决于']

    # 如果预测中明确提到功率与半径有关，或者公式中 W_c 包含 R，则可能违反规则
    # 但更稳妥的是检查是否提到了抵消逻辑
    has_independence_claim = any(kw in pred_lower for kw in independence_keywords)

    # Step 3: 符号与公式校验 (W_c ∝ λ^2 / n_2)
    # 检查是否包含波长 lambda 和非线性系数 n2，且不包含半径 R
    has_required_symbols = 'lambda' in pred_lower or '\\lambda' in pred_lower or 'n_2' in pred_lower or 'n2' in pred_lower

    # 检查是否存在错误的半径依赖公式，例如 W_c ∝ R^2 (这是错误的)
    wrong_pattern = re.search(r'W_c.*[\*\/].*[Rw]', prediction)

    if has_independence_claim and has_required_symbols:
        return {'result': 'pass', 'message': '正确识别临界功率与光束半径无关，且包含核心物理量', 'evidence': prediction[:200]}

    if wrong_pattern and ('independent' not in pred_lower and '无关' not in pred_lower):
        return {'result': 'fail', 'message': '模型错误：临界功率表达式中错误地包含了光束半径，未体现抵消逻辑', 'evidence': str(wrong_pattern.group())}

    return {'result': 'inconclusive', 'message': '无法确定是否明确讨论了半径独立性', 'evidence': prediction[:150]}

# rule_id=norm_4cd65087aa01a982 | domain=Optics | topic=Rayleigh Scattering and Applications
# rule_id=norm_4cd65087aa01a982 | domain=Optics | topic=Rayleigh Scattering and Applications
def check_norm_4cd65087aa01a982_d9bd3e33cddc(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否同时涉及 μg/m³ 和 g/cm³
    q_c_text = (question + context).lower()
    has_ug_m3 = 'μg/m' in q_c_text or 'ug/m' in q_c_text or '微克/立方米' in q_c_text
    has_g_cm3 = 'g/cm' in q_c_text or '克/立方厘米' in q_c_text

    if not (has_ug_m3 and has_g_cm3):
        return {'result': 'inconclusive', 'message': '未同时检测到微克/立方米与克/立方厘米单位', 'evidence': ''}

    # Step 2: 检查预测中是否包含单位换算逻辑
    pred = prediction.lower()
    # 检查是否尝试将 g/cm3 转换为 1000 或 10^3 kg/m3
    g_to_kg_correct = re.search(r'1\s*g/cm\^?3\s*=\s*(1000|10\^3)\s*kg/m\^?3', pred) or \
                      re.search(r'g/cm\^?3.*(1000|10\^3).*kg/m\^?3', pred)

    # 检查是否尝试将 ug/m3 转换为 10^-9 kg/m3
    ug_to_kg_correct = re.search(r'(1|1.0)\s*(μg|ug)/m\^?3\s*=\s*(10\^-9|0\.000000001)\s*kg/m\^?3', pred) or \
                       re.search(r'(μg|ug)/m\^?3.*(10\^-9|10\^\{-9\}).*kg/m\^?3', pred)

    # Step 3: 判定结果
    if g_to_kg_correct and ug_to_kg_correct:
        return {'result': 'pass', 'message': '单位换算逻辑正确', 'evidence': '检测到正确的 SI 单位换算系数'}

    # 如果提到了单位但数值明显错误（例如 1g/cm3 = 1kg/m3 或 1ug/m3 = 10^-6kg/m3）
    if re.search(r'1\s*g/cm\^?3\s*=\s*1\s*kg/m\^?3', pred) or re.search(r'(μg|ug)/m\^?3.*10\^-6.*kg/m\^?3', pred):
        return {'result': 'fail', 'message': '单位换算系数错误', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '未能明确识别单位换算过程', 'evidence': ''}

# rule_id=norm_711749ad83796f1f | domain=Optics | topic=Rayleigh Scattering and Applications
# rule_id=norm_711749ad83796f1f | domain=Optics | topic=Rayleigh Scattering and Applications
def check_norm_711749ad83796f1f_d33eb52a4e47(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件检查 — 涉及山峰、大气消光、可见度百分比阈值
    trigger_keywords = ['山峰', '大气消光', '可见度', '视见度', 'extinction', 'visibility', 'threshold']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到大气视见度或消光相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否同时考虑距离平方反比 (1/d^2) 与指数衰减 (exp)
    pred = prediction.lower()
    # 检查指数衰减 (Beer-Lambert Law) 相关特征
    has_exp = 'exp' in pred or 'e^-' in pred or '指数衰减' in pred or 'beer' in pred
    # 检查距离平方反比特征
    has_inv_sq = '/d^2' in pred or '/r^2' in pred or '平方反比' in pred or 'inverse square' in pred

    if not (has_exp and has_inv_sq):
        return {
            'result': 'fail',
            'message': '模型缺失关键要素：需同时考虑距离平方反比定律与指数衰减（Beer-Lambert Law）',
            'evidence': prediction[:200]
        }

    # Step 3: 符号覆盖检查 (I, d, n, sigma)
    required_symbols = ['i', 'd', 'n', 'sigma']
    # 瑞利散射截面参数提及检查
    has_rayleigh = 'rayleigh' in pred or '瑞利' in pred or 'sigma' in pred

    missing_symbols = [s for s in required_symbols if s not in pred]
    if len(missing_symbols) > 2: # 允许少量符号差异，但核心需存在
        return {
            'result': 'fail',
            'message': f'预测中缺少必要的物理符号或参数: {missing_symbols}',
            'evidence': prediction[:200]
        }

    if has_exp and has_inv_sq and has_rayleigh:
        return {'result': 'pass', 'message': '模型完整性校验通过，包含平方反比与指数衰减要素', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足以判定模型准确性', 'evidence': ''}

# rule_id=norm_88d9be5bb0d93543 | domain=Optics | topic=Rayleigh Scattering and Applications
# rule_id=norm_88d9be5bb0d93543 | domain=Optics | topic=Rayleigh Scattering and Applications
def check_norm_88d9be5bb0d93543_cbc16bb34e92(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及衰减长度（Attenuation Length）或平均自由程（Mean Free Path）
    trigger_keywords = ['attenuation length', 'mean free path', '衰减长度', '平均自由程', 'scattering length']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到衰减长度或平均自由程相关推导场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证公式是否包含 L = 1/(n*sigma) 的结构或其变体
    # 检查符号覆盖：L_p, n, sigma (A), rho 等
    pred = prediction.lower()
    # 匹配 L = 1 / (n * sigma) 或类似倒数关系
    # 允许 n*sigma, n*A, n*s, rho*sigma 等组合
    formula_pattern = r'1\s*/\s*\(?n\s*[*\s]*[\\\w]+'
    # 检查是否提到了数密度 n 和 截面积 sigma/A
    has_n = 'n' in pred or 'number density' in pred or '数密度' in pred
    has_sigma = 'sigma' in pred or '\\sigma' in pred or 'cross section' in pred or '截面积' in pred

    # Step 3: 符号与量纲转换校验
    # 如果涉及质量密度 rho，通常需要检查体积或摩尔质量转换项
    has_rho = 'rho' in pred or '\\rho' in pred or 'density' in pred

    # 核心逻辑判断
    if re.search(formula_pattern, pred) or (has_n and has_sigma):
        # 进一步检查量纲一致性：L [L], n [L^-3], sigma [L^2] -> 1/(n*sigma) [L]
        if '1/' in pred or 'inv' in pred or '^-1' in pred:
            return {'result': 'pass', 'message': '公式结构符合 L = 1/(n*sigma) 的量纲推导', 'evidence': prediction[:200]}
        else:
            return {'result': 'fail', 'message': '公式未体现衰减长度与密度及截面积的倒数关系', 'evidence': prediction[:200]}

    # 如果提到了这些物理量但没有写出明确的倒数关系
    if has_n or has_sigma or has_rho:
        return {'result': 'fail', 'message': '推导中缺失核心公式 L = 1/(n*sigma) 或量纲转换项', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定推导逻辑是否正确', 'evidence': ''}

# rule_id=norm_08f7605830faf10d | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_08f7605830faf10d | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_08f7605830faf10d_e7c6e11ba535(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及视速度(apparent velocity)与信号延迟/接收时间
    trigger_keywords = ['apparent velocity', '视速度', 'apparent speed', 'observed velocity']
    time_keywords = ['delay', 'signal', 'receive', 'emission', '延迟', '接收', '发射', 't_e']

    q_c = (question + context).lower()
    is_triggered = any(kw in q_c for kw in trigger_keywords) and any(kw in q_c for kw in time_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '题目未明确涉及视速度计算或信号延迟场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否建立了接收时间 t 与发射时间 t_e 的导数关系 (dt/dt_e 或 dt_e/dt)
    pred = prediction.lower()
    # 检查是否提到链式法则或导数转换关系
    has_chain_rule = 'dt' in pred and 'dt_e' in pred and ('/' in pred or 'derivative' in pred)
    # 检查是否包含核心公式结构 v' = v / (dt/dt_e) 或类似的 dx/dt = (dx/dt_e)*(dt_e/dt)
    has_formula_structure = re.search(r'v\s*\/\s*\(dt\/dt_e\)', pred) or \
                            re.search(r'dx\/dt\s*=\s*\(dx\/dt_e\)\s*\*\s*\(dt_e\/dt\)', pred) or \
                            re.search(r'v\s*\*\s*\(dt_e\/dt\)', pred)

    if not (has_chain_rule or has_formula_structure):
        return {
            'result': 'fail',
            'message': '未发现视速度计算所需的链式法则逻辑，应建立接收时间t与发射时间t_e的关系',
            'evidence': prediction[:200]
        }

    # Step 3: 符号校验 — 检查是否包含必要的物理量符号
    required_symbols = ['t', 't_e', 'v']
    missing_symbols = [sym for sym in required_symbols if sym not in pred]

    if not missing_symbols:
        return {
            'result': 'pass',
            'message': '正确应用了视速度导数链式法则',
            'evidence': re.findall(r'.{0,30}(?:dt/dt_e|dt_e/dt|dx/dt).{0,30}', pred)[0] if 'dt' in pred else ''
        }

    return {'result': 'inconclusive', 'message': '逻辑存在但符号不完整', 'evidence': prediction[:100]}

# rule_id=norm_0c05e468cee23920 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_0c05e468cee23920 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_0c05e468cee23920_b5a13d22e70e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及“观测”、“看到”等视觉观测场景
    trigger_keywords = ['observing', 'according to', 'eyes', 'see', 'visual', 'observed']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '题目未明确涉及视觉观测或观测者效应场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否区分了坐标时间与光信号传播时间 (L/c)
    pred_lower = prediction.lower()
    # 检查是否提到了光速 c 参与的时间延迟计算，或者明确提到了信号传播 (signal propagation)
    has_signal_delay = any(term in pred_lower for term in ['/c', 'signal', 'propagation', 'travel time', 'light travel'])

    # Step 3: 符号/公式校验 — 检查是否包含类似 t_obs = t_coord + d/c 的逻辑结构
    # 匹配类似 t + d/c, t + x/c, L/c 等表达式
    formula_pattern = re.compile(r'([txLd]|time|distance)\s*/\s*c', re.IGNORECASE)
    has_formula = bool(formula_pattern.search(prediction))

    if not (has_signal_delay or has_formula):
        # 如果题目要求“看到”但解题过程仅使用了洛伦兹变换(gamma)而忽略了信号传播时间，则判定为错误
        if 'gamma' in pred_lower or 'sqrt(1-v' in pred_lower:
            return {
                'result': 'fail',
                'message': '模型仅进行了洛伦兹变换，未考虑光信号传播到观察者眼睛所需的额外时间 (L/c)',
                'evidence': prediction[:200]
            }
        return {'result': 'inconclusive', 'message': '未发现关于观测时间修正的明确讨论', 'evidence': ''}

    if has_formula or ('signal' in pred_lower and '/c' in pred_lower):
        return {'result': 'pass', 'message': '模型正确考虑了光信号传播时间对观测结果的影响', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足以判定是否区分了坐标时间与观测时间', 'evidence': ''}

# rule_id=norm_148a5e9412de03cc | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_148a5e9412de03cc | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_148a5e9412de03cc_bff5135b6187(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及超相对论粒子（如电子）的辐射脉冲或同步辐射场景
    trigger_keywords = ['radiation', 'pulse', 'synchrotron', 'ultra-relativistic', '脉冲', '辐射', '同步辐射', '接近光速']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到超相对论辐射脉冲相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须考虑观测时间修正 (1-v/c) 或 1/(2γ²) 或 γ⁻³ 的比例关系
    pred = prediction.lower()
    # 检查是否提到了洛伦兹因子 γ (gamma)
    has_gamma = 'gamma' in pred or 'γ' in pred
    # 检查是否提到了时间压缩因子或多普勒效应相关的修正项
    has_correction = any(term in pred for term in ['1-v/c', '1 - v/c', '1/(2g', '1/(2\\gamma', 'gamma^-3', 'γ^-3', 'γ^{-3}'])

    # 如果完全没有提到 γ 或相关的压缩因子，则判定为逻辑缺失（容易误用几何扫掠时间）
    if not (has_gamma or has_correction):
        return {'result': 'fail', 'message': '计算辐射脉冲宽度时未考虑相对论压缩效应 (1-v/c) 或洛伦兹因子修正', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查 canonical 形式 ΔT ∝ γ⁻³ 或 ΔT ≈ Δt/(2γ²)
    # 匹配 γ 的负三次方或分母上的 γ 的三次方/二次方（取决于具体推导步骤）
    if re.search(r'gamma\s*(\^|-|\*\*)\s*3', pred) or re.search(r'γ\s*(\^|-|\*\*)\s*3', pred) or \
       re.search(r'1\s*/\s*\(?2\s*gamma\s*(\^|\*\*)\s*2', pred) or re.search(r'1\s*/\s*\(?2\s*γ\s*(\^|\*\*)\s*2', pred):
        return {'result': 'pass', 'message': '正确应用了超相对论脉冲宽度压缩公式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到相关讨论但无法确定公式推导的准确性', 'evidence': prediction[:200]}

# rule_id=norm_21ab8132e7fd1c0c | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_21ab8132e7fd1c0c | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_21ab8132e7fd1c0c_9435a91c2779(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“观察到的时钟读数”及信号传输时间
    trigger_keywords = ['观察', '观测', '读数', '看到', 'observed', 'reading', 'see']
    flight_keywords = ['信号', '传播', '滞后', '飞行时间', 'signal', 'propagation', 'flight time', 'delay']

    q_c = (question + context).lower()
    is_triggered = any(k in q_c for k in trigger_keywords) and any(k in q_c for k in flight_keywords)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到光信号观测滞后相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否考虑了 t_obs = t - r/c 的修正逻辑
    # 检查 prediction 中是否包含距离除以光速的项，以及减法关系
    pred = prediction.lower()
    # 匹配类似 t - r/c, t - x/c, t - d/c, t - L/c 的结构
    correction_pattern = r't\s*-\s*[rxLd]\(t\)?\s*/\s*c|t\s*-\s*\w+/c|t_obs\s*=\s*t'
    has_correction = re.search(correction_pattern, pred) or ('/c' in pred and '-' in pred)

    if not has_correction:
        # 如果明确要求计算观测读数但未见修正公式，判定为建模错误
        return {
            'result': 'fail',
            'message': '未在推理中发现光信号传输时间修正逻辑 (t_obs = t - r/c)',
            'evidence': prediction[:200]
        }

    # Step 3: 符号覆盖检查 (required_symbols: c, t, t_obs, x(t))
    required_symbols = ['c', 't']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    if not missing_symbols:
        return {
            'result': 'pass',
            'message': '已包含光信号滞后修正逻辑及必要物理量',
            'evidence': re.search(r'.{0,50}t\s*-\s*\w+/c.{0,50}', prediction).group(0) if re.search(r't\s*-\s*\w+/c', prediction) else prediction[:100]
        }

    return {'result': 'inconclusive', 'message': '检测到部分逻辑但证据不足以判定', 'evidence': prediction[:100]}

# rule_id=norm_22023e9fd8033ffe | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_22023e9fd8033ffe | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_22023e9fd8033ffe_b00fd562c61c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及狭义相对论中的角度比例或极限情况证明
    trigger_keywords = ['angle', 'ratio', 'limit', 'approximation', '角度', '比例', '极限', '近似']
    relativity_keywords = ['relativity', 'beta', 'gamma', 'v/c', 'doppler', '相对论']
    if not (any(k in (question + context).lower() for k in trigger_keywords) and
            any(k in (question + context + prediction).lower() for k in relativity_keywords)):
        return {'result': 'inconclusive', 'message': '未检测到小角近似或相对论角度比例证明场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否执行了三角函数的一阶展开 (sin x ~ x, tan x ~ x)
    pred_lower = prediction.lower()
    expansion_patterns = [r'sin.*\\approx', r'tan.*\\approx', r'sin.*~', r'tan.*~', r'small angle', r'小角']
    has_expansion = any(re.search(p, pred_lower) for p in expansion_patterns)

    # Step 3: 符号与公式校验 — 验证比例系数是否包含 (1+beta)/(1-beta) 或其变体结构
    # 重点检查多普勒因子相关的结构 (1+v/c), (1-v/c), (1+beta), (1-beta)
    doppler_structure = re.search(r'\(1[\+\-]\\?beta\)\s*/\s*\(1[\-\+]\\?beta\)', prediction) or \
                        re.search(r'1[\+\-]v/c', prediction) or \
                        re.search(r'\\sqrt{\s*\(1[\+\-]beta\)', prediction)

    if not has_expansion:
        return {'result': 'fail', 'message': '在处理角度比例时未发现明确的小角近似展开步骤', 'evidence': prediction[:200]}

    if doppler_structure:
        return {'result': 'pass', 'message': '检测到小角近似展开且比例系数符合多普勒因子结构', 'evidence': doppler_structure.group()}

    # 如果有展开但公式结构不匹配
    if 'alpha' in pred_lower and 'beta' in pred_lower and '/' in pred_lower:
        return {'result': 'fail', 'message': '比例系数结构与预期的多普勒因子 (1±beta) 不一致', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定比例系数的正确性', 'evidence': ''}

# rule_id=norm_26cc0e34e410f30e | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_26cc0e34e410f30e | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_26cc0e34e410f30e_88cd8a5d5824(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及运动物体两端与静止物体两端同时重合的场景
    trigger_keywords = ['两端', '重合', '对齐', 'coincide', 'overlap', 'ends']
    combined_text = (question + context).lower()
    if not all(k in combined_text for k in ['两端', '重合']) and 'coincide' not in combined_text:
        return {'result': 'inconclusive', 'message': '未检测到物体两端重合的建模场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否应用了长度收缩公式 L = L0 * sqrt(1 - v^2/c^2)
    # 且逻辑上要求收缩后的长度 L 等于静止参考系中的长度 L_static
    pred_lower = prediction.lower()
    # 检查是否包含洛伦兹因子或长度收缩相关的数学表达
    has_contraction_formula = re.search(r'sqrt\(1\s*-\s*v\^2/c\^2\)|1/gamma|\\sqrt{1-v\^2/c\^2}', pred_lower)
    has_length_relation = 'l' in pred_lower and ('=' in pred_lower or '等于' in pred_lower)

    if not has_contraction_formula:
        return {'result': 'fail', 'message': '在处理两端重合问题时，未体现长度收缩公式 L = L0 * sqrt(1-v^2/c^2)', 'evidence': prediction[:200]}

    # Step 3: 符号与等价性校验 — 检查是否建立了 L_moving_contracted = L_static_proper 的等式
    # 寻找类似 L_0 * sqrt(...) = L_s 的结构
    if re.search(r'sqrt\(1-v\^2/c\^2\)\s*=\s*|\*\s*sqrt.*=|=.*sqrt', pred_lower) or 'l_0' in pred_lower:
        return {'result': 'pass', 'message': '正确建立了长度收缩后的对齐等式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到长度收缩公式但无法确认对齐逻辑的正确性', 'evidence': prediction[:200]}

# rule_id=norm_2febb3b257e868e2 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_2febb3b257e868e2 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_2febb3b257e868e2_ea3a650a565b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及恒定固有加速度（proper acceleration）的相对论运动
    trigger_keywords = ['proper acceleration', 'constant acceleration', '固有加速度', '恒定加速度', 'hyperbolic motion', '双曲运动']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到恒定固有加速度相关的相对论运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否使用了双曲函数描述速度 v 或位移 x
    # 速度公式特征: tanh(g*tau/c) 或类似的结构
    # 位移公式特征: cosh(g*tau/c) 或 (c^2/g)*(cosh-1)
    pred = prediction.lower()

    # 检查符号覆盖
    required_symbols = ['tau', 'g', 'c']
    symbol_missing = [s for s in required_symbols if s not in pred and s not in prediction]

    # 正则匹配双曲函数结构
    v_pattern = r'tanh\s*\(\s*g\s*\*?\s*\\?tau\s*/\s*c\s*\)'
    x_pattern = r'cosh\s*\(\s*g\s*\*?\s*\\?tau\s*/\s*c\s*\)'

    has_v = re.search(v_pattern, pred) or 'tanh' in pred
    has_x = re.search(x_pattern, pred) or 'cosh' in pred

    # Step 3: 判定结果
    if has_v or has_x:
        return {
            'result': 'pass',
            'message': '检测到使用双曲函数描述固有加速度运动的关联公式',
            'evidence': re.search(r'.{0,50}(tanh|cosh).{0,50}', prediction).group(0) if (has_v or has_x) else ''
        }

    # 如果明确在讨论此类运动但完全没有双曲函数迹象，则判定为概念错误
    if 'relativistic' in combined_text and ('velocity' in pred or 'position' in pred):
        return {
            'result': 'fail',
            'message': '在描述恒定固有加速度运动时，未正确使用双曲函数(tanh/cosh)关联公式',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了双曲关联公式', 'evidence': ''}

# rule_id=norm_316c2cb99835952d | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_316c2cb99835952d | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_316c2cb99835952d_0a7b32a0d0cf(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及极轻粒子（如轴子axion）或暗物质场的频率偏移估算
    trigger_keywords = ['axion', '轴子', 'dark matter field', '暗物质场', 'light particle', '极轻粒子', 'frequency shift', '频率偏移', 'Δω', 'delta omega']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到极轻粒子场频率修正的相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否误用了一阶多普勒效应 (v/c)
    # 对于弥散场，频率修正应源于动能贡献，即二阶项 (v/c)^2
    pred_lower = prediction.lower()

    # 寻找一阶多普勒的特征：v/c 或 beta 的一次方，且没有平方项
    first_order_pattern = r'[^\^\*\(](v/c|\\beta|\beta)[^\^\*\d]'
    second_order_pattern = r'(v/c)\^2|\\beta\^2|\beta\^2|v\^2/c\^2|\\frac{v^2}{c^2}'

    # 如果明确提到了频率偏移正比于 v/c 而非 (v/c)^2，则判定为建模错误
    if re.search(first_order_pattern, pred_lower) and not re.search(second_order_pattern, pred_lower):
        if 'doppler' in pred_lower or 'frequency' in pred_lower:
            return {
                'result': 'fail',
                'message': '在处理弥散暗物质场时误用了一阶多普勒效应，应基于动能贡献使用二阶关系 (v/c)^2',
                'evidence': re.search(r'.{0,50}(v/c|\\beta).{0,50}', prediction).group(0) if re.search(r'v/c|\\beta', prediction) else prediction[:100]
            }

    # Step 3: 符号与公式结构校验
    # 检查是否包含必要的物理量 c 和 v，并体现平方关系
    has_v = 'v' in pred_lower or '\\beta' in pred_lower
    has_c = 'c' in pred_lower
    has_square = re.search(second_order_pattern, pred_lower)

    if has_v and has_c and has_square:
        return {
            'result': 'pass',
            'message': '正确识别了频率修正与速度平方 (v/c)^2 的比例关系',
            'evidence': re.search(second_order_pattern, pred_lower).group(0)
        }

    return {'result': 'inconclusive', 'message': '无法确定频率修正的具体阶数逻辑', 'evidence': ''}

# rule_id=norm_378fafd4253adaba | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_378fafd4253adaba | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_378fafd4253adaba_4ffa8a0d9635(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及运动系中的垂直位移及静止系时间计算
    trigger_keywords = ['垂直', 'vertical', 'perpendicular', 'y-axis', 'y轴']
    relativity_keywords = ['相对论', 'relativity', '光速', 'gamma', '洛伦兹', '时间膨胀']

    text_to_check = (question + context).lower()
    is_triggered = any(kw in text_to_check for kw in trigger_keywords) and \
                   any(kw in text_to_check for kw in relativity_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到垂直位移的时间膨胀场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否应用了时间膨胀公式 dt' = gamma * dt
    # 垂直方向长度不收缩 (L=L0)，但时间必须膨胀
    pred = prediction.lower()

    # 检查是否错误地认为垂直长度会收缩（负向检查）
    if re.search(r'(垂直|vertical).*(收缩|contract)', pred):
        return {'result': 'fail', 'message': '错误地认为垂直于运动方向的长度会发生收缩', 'evidence': prediction[:200]}

    # 检查是否提及洛伦兹因子或时间膨胀公式
    gamma_pattern = r'(gamma|1/sqrt\(1-v\^2/c\^2\)|1/sqrt\(1-beta\^2\))'
    time_dilation_pattern = r'(dt|t).*(/|\*).*(sqrt|gamma)'

    has_gamma = re.search(gamma_pattern, pred) or '洛伦兹因子' in pred
    has_dilation = '膨胀' in pred or 'dilation' in pred or re.search(time_dilation_pattern, pred)

    if not (has_gamma or has_dilation):
        return {'result': 'fail', 'message': '未体现时间膨胀效应或洛伦兹因子的计算逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查 symbolic_hint 中的关键元素
    # 检查是否包含 beta, c, h 等符号或类似的结构
    required_symbols = ['beta', 'c', 'h']
    symbol_count = sum(1 for sym in required_symbols if sym in pred)

    # 如果公式结构 dt = h / (c * sqrt(1-v^2/c^2)) 出现，则判定为 pass
    formula_match = re.search(r'h\s*/\s*\(\s*c\s*\*\s*sqrt', pred.replace(' ', ''))
    if formula_match or (has_gamma and symbol_count >= 2):
        return {'result': 'pass', 'message': '正确应用了垂直位移下的时间膨胀计算公式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑存在但公式完整性不足以判定', 'evidence': prediction[:200]}

# rule_id=norm_37d8592f1c6ed847 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_37d8592f1c6ed847 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_37d8592f1c6ed847_7332ea828322(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及加速运动粒子观测静止参考系时钟，且涉及信号飞行时间
    trigger_keywords = ['加速', 'accelerat', '信号', '回传', '飞行时间', '光速', '观测', '时钟']
    q_c_text = (question + context).lower()
    is_triggered = ('加速' in q_c_text or 'accelerat' in q_c_text) and \
                   ('信号' in q_c_text or 'signal' in q_c_text or '飞行时间' in q_c_text or 'travel time' in q_c_text)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '题目未明确涉及加速观测者信号回传场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须建立光锥方程 x(t) = c(t - t_obs) 或类似形式，而非直接套用多普勒公式
    pred = prediction.lower()
    # 检查是否错误地直接使用了多普勒公式而没有建立光锥方程
    doppler_only = re.search(r'f\s*=\s*f0.*sqrt\((1[+-]v)/(1[+-]v)\)', pred) or \
                   re.search(r'doppler', pred)

    # 检查光锥方程的关键组成部分: x, c, t, t_obs (或 t0)
    # 匹配模式如 x = c(t - t_0), x(t) = c(t_obs - t), x = c*delta_t 等
    light_cone_pattern = re.search(r'x\s*=\s*c\s*\*?\s*\(?t\s*[-|+]\s*t', pred) or \
                         re.search(r'c\s*\*?\s*\(t_?obs\s*-\s*t\)', pred) or \
                         re.search(r'x\(t\)\s*=\s*c', pred)

    if not light_cone_pattern:
        if doppler_only:
            return {'result': 'fail', 'message': '错误地直接套用匀速多普勒公式，未建立光锥方程考虑信号飞行时间', 'evidence': prediction[:200]}
        return {'result': 'inconclusive', 'message': '未在推理中发现明确的光锥方程建模过程', 'evidence': ''}

    # Step 3: 符号覆盖检查 (c, t, t_0/t_obs, x)
    required_symbols = ['c', 't', 'x']
    missing_symbols = [s for s in required_symbols if s not in pred]

    if not missing_symbols:
        return {'result': 'pass', 'message': '已建立光锥方程并考虑了信号飞行时间', 'evidence': '检测到方程结构及必要符号'}

    return {'result': 'inconclusive', 'message': '建模过程不完整', 'evidence': f'缺失符号: {missing_symbols}'}

# rule_id=norm_3ee1162f55a05cf4 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_3ee1162f55a05cf4 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_3ee1162f55a05cf4_0215245c37bf(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及动镜反射定律推导及特定运动方向（垂直/平行）
    trigger_keywords = ['反射', 'reflection', 'mirror', '镜面', 'moving mirror']
    direction_keywords = ['垂直', '平行', 'perpendicular', 'parallel', 'normal']
    content_all = (question + context).lower()

    if not any(kw in content_all for kw in trigger_keywords) or not any(kw in content_all for kw in direction_keywords):
        return {'result': 'inconclusive', 'message': '未检测到动镜反射或特定运动方向的推导场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否定义了 phi (速度与镜面夹角) 并代入公式 (1)
    pred_lower = prediction.lower()
    # 检查是否提到 phi 或速度与镜面的夹角
    if 'phi' not in pred_lower and 'angle' not in pred_lower and '夹角' not in pred_lower:
        return {'result': 'fail', 'message': '未在推导中明确速度与镜面的夹角 phi', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 sin(phi) 的取值逻辑及核心公式结构
    # 检查核心公式 sin(alpha)-sin(beta) = (v/c)*sin(phi)*sin(alpha+beta)
    formula_pattern = r'sin\s*\(\s*alpha\s*\)\s*-\s*sin\s*\(\s*beta\s*\).*sin\s*\(\s*phi\s*\)'
    if not re.search(formula_pattern, pred_lower.replace(' ', '')):
        # 如果没找到完整公式，检查是否讨论了 sin(phi) 的特殊值
        if 'sin(phi)=0' not in pred_lower.replace(' ', '') and 'sin(phi)=1' not in pred_lower.replace(' ', ''):
            return {'result': 'fail', 'message': '未代入核心反射公式或未讨论 sin(phi) 的特殊取值', 'evidence': prediction[:200]}

    # 检查特定方向的逻辑一致性
    # 平行镜面 (parallel) -> phi=0 -> sin(phi)=0
    if ('parallel' in content_all or '平行' in content_all) and 'sin' in pred_lower:
        if 'sin(phi)=0' in pred_lower.replace(' ', '') or 'phi=0' in pred_lower.replace(' ', ''):
            return {'result': 'pass', 'message': '正确处理了平行镜面情况下的 phi 定义', 'evidence': 'sin(phi)=0 detected'}

    # 垂直镜面 (perpendicular/normal) -> phi=pi/2 -> sin(phi)=1
    if ('perpendicular' in content_all or '垂直' in content_all or '法线' in content_all) and 'sin' in pred_lower:
        if 'sin(phi)=1' in pred_lower.replace(' ', '') or 'phi=90' in pred_lower or 'phi=pi/2' in pred_lower:
            return {'result': 'pass', 'message': '正确处理了垂直镜面情况下的 phi 定义', 'evidence': 'sin(phi)=1 detected'}

    return {'result': 'inconclusive', 'message': '推导过程存在，但无法确定 phi 定义的准确性', 'evidence': prediction[:200]}

# rule_id=norm_3f87512ce14f947b | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_3f87512ce14f947b | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_3f87512ce14f947b_92f3d2fc7479(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及运动粒子吸收激光及多普勒效应
    trigger_keywords = ['运动粒子', '吸收', '激发', '激光', 'Doppler', '多普勒', 'wavelength', '波长']
    content_all = (question + context).lower()
    if not any(k in content_all for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到运动粒子激光激发场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别相对运动方向（迎面/向源）与波长补偿方向
    pred = prediction.lower()
    # 识别“迎面”、“向源”或“opposite direction”等含义
    is_towards = any(k in pred for k in ['迎面', '向源', 'towards', 'opposite direction'])
    # 识别“红移”、“调长”、“增加波长”等补偿逻辑
    is_redshift_comp = any(k in pred for k in ['红移', '调长', '增加波长', 'increase wavelength', 'redshift'])
    # 识别“蓝移”作为粒子系的感受
    is_blueshift_obs = any(k in pred for k in ['蓝移', 'blueshift'])

    if is_towards:
        if '调短' in pred or '减少波长' in pred or 'decrease wavelength' in pred:
            return {'result': 'fail', 'message': '逻辑错误：迎面运动时粒子感受蓝移，实验室光源应调长波长（红移）补偿', 'evidence': prediction[:200]}
        if is_redshift_comp:
            return {'result': 'pass', 'message': '逻辑正确：识别到迎面运动需红移补偿', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 (\lambda_{lab} = \lambda_0 (1 + v/c))
    # 检查是否包含核心符号 lambda_0, lambda_lab, v
    required_symbols = ['\\lambda_0', '\\lambda_{lab}', 'v']
    symbol_count = sum(1 for s in required_symbols if s in prediction)

    # 检查公式结构：迎面运动补偿公式通常近似为 lambda_lab = lambda_0 * (1 + v/c)
    formula_pattern = r'\\lambda_{lab}\s*=\s*\\lambda_0\s*\(\s*1\s*\+\s*v/c\s*\)'
    if re.search(formula_pattern, prediction):
        return {'result': 'pass', 'message': '公式结构与补偿逻辑匹配', 'evidence': re.search(formula_pattern, prediction).group()}

    if symbol_count >= 2 and is_towards:
         return {'result': 'inconclusive', 'message': '检测到相关符号但逻辑表述不完整', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '证据不足以判定补偿逻辑正误', 'evidence': ''}

# rule_id=norm_60999fda7622b1c8 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_60999fda7622b1c8 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_60999fda7622b1c8_e70bf564ff49(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“视在观测”或“远距离观察”场景
    trigger_keywords = ["bob's eyes", "observing from distance", "apparent time", "seen by", "travel time"]
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords) and not re.search(r'distance\s+R', combined_text, re.I):
        return {'result': 'inconclusive', 'message': '未检测到视在观测时间相关的触发词', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否考虑了光信号传播延迟 (L/c 或 R/c)
    pred_lower = prediction.lower()
    # 检查是否提到了光速延迟、传播时间或特定的修正项
    has_delay_logic = any(kw in pred_lower for kw in ['delay', 'propagation', 'travel time', 'signal time', 'light travel'])

    # Step 3: 符号与公式校验 — 检查是否包含 t_obs = t + L/c 类似的结构
    # 匹配类似 t + R/c, t + L/c, sqrt(R^2...)/c 的模式
    formula_pattern = r'(\+|\-)\s*([RLd]|sqrt\(.*?\))\s*/\s*c'
    has_formula = re.search(formula_pattern, prediction) is not null

    if not (has_delay_logic or has_formula):
        return {
            'result': 'fail',
            'message': '模型仅进行了坐标变换（如洛伦兹变换），未考虑光信号从事件点传播到观测者的延迟时间 Δt = ΔL/c。',
            'evidence': prediction[:200]
        }

    # 检查是否包含必要的物理量符号
    required_symbols = ['R', 'c']
    missing_symbols = [s for s in required_symbols if s not in prediction]
    if not missing_symbols and has_formula:
        return {'result': 'pass', 'message': '模型正确识别了视在观测时间并包含了传播延迟修正。', 'evidence': re.search(formula_pattern, prediction).group(0) if has_formula else ''}

    return {'result': 'inconclusive', 'message': '检测到相关讨论但公式表达不完整或不明确', 'evidence': prediction[:150]}

# rule_id=norm_62111da55c4e030e | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_62111da55c4e030e | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_62111da55c4e030e_ea227f459816(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及超光速运动(v > u)及视位置/视速度计算
    trigger_keywords = ['超光速', 'superluminal', 'apparent position', '视位置', '视速度', 'apparent velocity']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到超光速视位置相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须建立二次方程或体现双解建模过程
    # 核心公式: u^2(t - t_e)^2 = (v t_e)^2 + d^2 或其变体
    pred = prediction.lower()
    # 检查是否提到两个解/两个根
    has_two_solutions = any(kw in pred for kw in ['两个解', 'two solutions', 'double roots', '两个根', '双解'])
    # 检查关键物理量符号是否出现
    required_symbols = ['d', 't', 'u', 'v']
    missing_symbols = [s for s in required_symbols if s not in pred]

    # Step 3: 公式结构校验
    # 匹配类似 u^2(t-te)^2 = (v*te)^2 + d^2 的结构
    formula_pattern = r'u\^?2.*[\(（]t\s*-\s*t_?e[\)）]\^?2.*=.*v\^?2.*t_?e\^?2.*\+.*d\^?2'
    formula_match = re.search(formula_pattern, pred.replace(' ', ''))

    if not formula_match and not has_two_solutions:
        return {
            'result': 'fail',
            'message': '未建立超光速视位置的二次方程建模，或未体现双解逻辑',
            'evidence': f'缺失符号: {missing_symbols}' if missing_symbols else '未发现二次方程结构'
        }

    if formula_match or (has_two_solutions and len(missing_symbols) <= 1):
        return {
            'result': 'pass',
            'message': '已正确建立二次方程模型并考虑双解情况',
            'evidence': f'匹配到公式或双解逻辑。符号覆盖: {set(required_symbols) - set(missing_symbols)}'
        }

    return {'result': 'inconclusive', 'message': '建模过程不完整或证据不足', 'evidence': prediction[:200]}

# rule_id=norm_67cec5b4aa7fef51 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_67cec5b4aa7fef51 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_67cec5b4aa7fef51_19b8e40a6300(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及狭义相对论中的低速近似场景 (1 - sqrt(1 - x))
    # 关键词：1-sqrt, sqrt(1-v^2/c^2), beta^2, 二项式, 近似, binomial
    trigger_patterns = [r'1\s*-\s*sqrt', r'\\sqrt{1\s*-\s*[^}]*}', r'1\s*-\s*\(1\s*-\s*[^\)]*\)\\^\{1/2\}', r'v/c\s*<<\s*1']
    is_triggered = any(re.search(p, question + context, re.IGNORECASE) for p in trigger_patterns)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到 1-sqrt(1-x) 结构或低速近似场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须使用 1 - (1 - x/2) = x/2 简化，并核对 beta^2 的幂次
    # 检查是否直接使用了近似公式 1/2 * (v/c)^2 或 0.5 * beta^2
    pred_clean = prediction.replace(' ', '')
    # 匹配 1/2 * beta^2 或 0.5 * (v/c)^2 等形式
    approx_patterns = [
        r'1/2\*?v\^2/c\^2',
        r'0\.5\*?\(v/c\)\^2',
        r'1/2\*?beta\^2',
        r'0\.5\*?\\beta\^2',
        r'1-\(1-1/2\*?v\^2/c\^2\)',
        r'1-\(1-0\.5\*?beta\^2\)'
    ]

    has_approx = any(re.search(p, pred_clean, re.IGNORECASE) for p in approx_patterns)

    # Step 3: 检查是否存在幂次丢失的错误（例如直接把 sqrt(1-x) 当作 1-x 或者 1-x^2）
    # 如果出现了 1 - (1 - v^2/c^2) = v^2/c^2 而漏掉了 1/2，则判定为 fail
    fail_pattern = r'1\s*-\s*\(1\s*-\s*v\^2/c\^2\)'
    if re.search(fail_pattern, pred_clean) and not has_approx:
        return {'result': 'fail', 'message': '近似展开错误，丢失了二项式系数 1/2', 'evidence': prediction}

    if has_approx:
        # 进一步检查是否提到了科学计数法或幂次核对（针对 x 极小的情况）
        if re.search(r'10\^', prediction) or 'order' in prediction.lower() or '幂' in prediction:
            return {'result': 'pass', 'message': '正确使用了二项式近似并注意了幂次精度', 'evidence': prediction}
        return {'result': 'pass', 'message': '使用了正确的二项式近似公式', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了近似简化', 'evidence': ''}

# rule_id=norm_6da6fb4cf5e11dad | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_6da6fb4cf5e11dad | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_6da6fb4cf5e11dad_97349550ffd4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及天体喷流、视向速度或视超光速表述
    trigger_keywords = ['jet', 'apparent transverse', 'superluminal', '喷流', '视向速度', '视超光速']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '题目未涉及视超光速运动或喷流场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否考虑了信号到达时间差效应（分母项）
    # 视速度公式核心特征是分母包含 1 - (v/c)cos(theta)
    pred_lower = prediction.lower()

    # 检查是否错误地使用了简单的 v*sin(theta) 或 omega*R 而忽略了多普勒/时间延迟修正
    # 匹配公式特征：v*sin(theta) / (1 - v/c*cos(theta))
    formula_pattern = r'sin.*[\/\(].*1\s*-\s*(v/c|\beta).*cos'
    has_correct_formula = re.search(formula_pattern, pred_lower) or \
                          re.search(r'1\s*-\s*.*cos.*theta', pred_lower)

    # Step 3: 判定结果
    if has_correct_formula:
        return {'result': 'pass', 'message': '模型正确考虑了信号到达时间差效应', 'evidence': '检测到包含 1-v/c*cos(theta) 的修正项'}

    # 如果明确只用了简单的 v*sin(theta) 而没有分母修正，则判定为建模错误
    if re.search(r'v\s*\*?\s*sin', pred_lower) and not ('1-' in pred_lower or '1 -' in pred_lower):
        return {'result': 'fail', 'message': '建模错误：未考虑信号到达时间差效应，视速度公式缺失分母修正项', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了视速度修正公式', 'evidence': ''}

# rule_id=norm_6f8162283b82d02c | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_6f8162283b82d02c | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_6f8162283b82d02c_75b213ffd502(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及物体速度 v 大于介质波速 u 的场景（如切连科夫辐射、超音速、超光速信号）
    trigger_keywords = ['v > u', 'v>u', 'faster than', 'supersonic', 'Cherenkov', 'superluminal', '超音速', '切连科夫', '超光速']
    combined_text = (question + context).lower()
    is_triggered = any(kw.lower() in combined_text for kw in trigger_keywords) or re.search(r'v\s*>\s*[uc]', combined_text)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到物体速度大于波速的超光速/超音速信号场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否考虑了信号到达时间的双值性（判别式、两个实根、两个视位置）
    pred_lower = prediction.lower()
    # 检查是否提及判别式、两个根、两个位置或双值性
    dual_value_indicators = ['two roots', 'discriminant', 'two positions', 'apparent positions', 'double', '两个实根', '判别式', '两个视位置', '双值']
    has_dual_logic = any(ind in pred_lower for ind in dual_value_indicators)

    # Step 3: 符号/公式校验 — 检查 canonical 公式 t = t_e + |r(t_e)|/u 的变体或相关符号
    # 重点检查是否包含 t_e, u, v 以及平方项（判别式来源）
    formula_pattern = re.search(r't\s*=\s*t_e\s*\+\s*.*[ru]', prediction)
    has_symbols = all(sym in prediction for sym in ['t_e', 'u', 'v'])

    if not has_dual_logic:
        return {
            'result': 'fail',
            'message': '在超光速/超音速信号分析中，未体现信号到达时间的双值性或判别式分析。',
            'evidence': prediction[:200]
        }

    if has_dual_logic and (has_symbols or formula_pattern):
        return {
            'result': 'pass',
            'message': '正确识别并分析了超光速信号的双值性及相关运动方程。',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '检测到部分逻辑但证据不足以判定正确性', 'evidence': prediction[:100]}

# rule_id=norm_77179c4188b3c180 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_77179c4188b3c180 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_77179c4188b3c180_6a3bb280c29e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否要求从图像（Figure）中提取数值
    trigger_keywords = ['using figure', 'from figure', 'based on figure', 'according to figure']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '题目未明确要求从图像中提取数值', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别图像要素（坐标轴、刻度、图例、时间点）
    # 检查是否包含坐标轴(axis/scale/grid)或图例(legend/scale bar)等关键词
    pred_lower = prediction.lower()
    essential_elements = ['axis', 'scale', 'grid', 'coordinate', 'intercept', 'slope', 'reading', 'plot']
    has_element_ref = any(elem in pred_lower for elem in essential_elements)

    # Step 3: 数值校验 — 禁止仅使用占位符整数（如 1.0, 2.0）而无具体读数过程
    # 匹配 prediction 中的浮点数或带单位的数值
    readings = re.findall(r'\d+\.\d+', prediction)
    # 如果只出现了极其简单的整数（如 1, 2, 5）且没有描述读图过程，则视为建模失败
    placeholder_pattern = re.compile(r'\b(1|2|5|10|1\.0|2\.0)\b')

    if not has_element_ref and not readings:
        return {
            'result': 'fail',
            'message': '未识别到图像坐标轴刻度或具体的读数提取过程，可能使用了占位符数据',
            'evidence': prediction[:200]
        }

    # 检查是否提到了具体的时间点或观测点（针对狭义相对论背景）
    time_ref = re.search(r'(time|t\s*=|at\s*t)', pred_lower)
    if not time_ref and 'time' in combined_text:
         return {
            'result': 'fail',
            'message': '未在预测中找到具体观测时间点的提取记录',
            'evidence': prediction[:150]
        }

    if len(readings) >= 1 or has_element_ref:
        return {'result': 'pass', 'message': '检测到图像数据提取逻辑及具体读数', 'evidence': str(readings[:3])}

    return {'result': 'inconclusive', 'message': '无法确定数据提取的真实性', 'evidence': ''}

# rule_id=norm_7e7904578bdff712 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_7e7904578bdff712 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_7e7904578bdff712_9378967031e3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及加速观测者、Rindler系或Minkowski系转换
    trigger_keywords = ['rindler', 'accelerating observer', '加速观测者', '加速系', 'minkowski', '坐标转换', 'coordinate transformation']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到非惯性系或Rindler坐标转换场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否考虑了固有时间 tau 的演化，而非将坐标视为常数
    # 检查是否包含 rho, tau, cosh, sinh 等关键符号或公式结构
    pred_lower = prediction.lower()
    required_symbols = ['\\rho', '\\tau', 'cosh', 'sinh']
    missing_symbols = [s for s in required_symbols if s.replace('\\\\', '\\') not in prediction]

    # 检查是否错误地将加速系中的轨迹描述为与时间无关的常数（例如简单假设 x=const 而不含双曲函数）
    if 'cosh' not in pred_lower and 'sinh' not in pred_lower:
        if re.search(r'x\s*=\s*\\rho', prediction) or re.search(r't\s*=\s*0', prediction):
            return {'result': 'fail', 'message': '模型可能错误地将加速系轨迹简化为常数，未体现随固有时间的演化', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 验证 x = rho cosh(tau) 和 t = rho sinh(tau) 的结构
    # 使用正则匹配典型的 Rindler 转换公式
    x_pattern = r'x\s*=\s*\\?rho\s*\\?cosh\(\s*\\?tau\s*\)'
    t_pattern = r't\s*=\s*\\?rho\s*\\?sinh\(\s*\\?tau\s*\)'

    has_x_trans = re.search(x_pattern, prediction, re.IGNORECASE)
    has_t_trans = re.search(t_pattern, prediction, re.IGNORECASE)

    if has_x_trans and has_t_trans:
        return {'result': 'pass', 'message': '正确识别并应用了Rindler系与Minkowski系的坐标转换公式', 'evidence': f'Found: {has_x_trans.group()} and {has_t_trans.group()}'}

    if len(missing_symbols) > 2:
        return {'result': 'fail', 'message': '缺失关键的Rindler坐标转换符号或双曲函数定义', 'evidence': f'Missing: {missing_symbols}'}

    return {'result': 'inconclusive', 'message': '检测到相关讨论但公式完整性不足以判定', 'evidence': prediction[:150]}

# rule_id=norm_7fd3fdab2cea2799 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_7fd3fdab2cea2799 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_7fd3fdab2cea2799_77932650972b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及μ子、电子等高能粒子在重力场中的运动
    trigger_keywords = ['μ子', 'muon', '电子', 'electron', '高能粒子', 'high-energy particle']
    combined_text = (question + context).lower()
