    # 匹配形式如 (1-beta)/(1+beta), (1-v/c)/(1+v/c), (c-v)/(c+v)
    factor_pattern = r'\(1\s*-\s*(beta|v/c)\)\s*/\s*\(1\s*\+\s*(beta|v/c)\)|\(c\s*-\s*v\)\s*/\s*\(c\s*\+\s*v\)'
    has_factor = re.search(factor_pattern, pred_lower) is not null

