    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) or ' c ' in combined_text
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到相对论高速运动场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否错误使用了牛顿第二定律的经典形式 a = F/m
    pred = prediction.lower()
    # 寻找类似 a = F/m 或 F = ma 的经典表达式，且没有 gamma 修正
    classic_fma = re.search(r'a\s*=\s*f\s*/\s*m|f\s*=\s*m\s*a', pred)
    has_gamma = 'gamma' in pred or 'γ' in pred or '1/sqrt' in pred or 'sqrt(1-v^2/c^2)' in pred

    # 如果直接使用了 a=F/m 且全文没有提到 gamma 或 相对论修正因子，则判定为 concept error
    if classic_fma and not has_gamma:
        return {
            'result': 'fail',
            'message': '在相对论尺度下错误使用了经典力学公式 a=F/m，未考虑洛伦兹因子修正。',
            'evidence': pred[classic_fma.start():classic_fma.end() + 50]
        }

    # Step 3: 符号与公式校验 — 检查是否包含正确的动力学修正形式 F = m * gamma^3 * a (平行情况) 或 dp/dt
    # 匹配 gamma^3 或 (1-v^2/c^2)^1.5 等特征
    correct_pattern = re.search(r'gamma\^3|\(1-v\^2/c\^2\)\^\(3/2\)|dp/dt|d\(mv\)/dt', pred)
    if correct_pattern:
        return {
            'result': 'pass',
            'message': '正确使用了相对论动力学公式或动量变化率表达。',
            'evidence': pred[correct_pattern.start():correct_pattern.end() + 20]
        }

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了相对论力学修正', 'evidence': ''}

