    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到Sagnac效应或旋转环路相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证预测中是否包含必要的物理量符号 (L, Ω, λ)
    pred_text = prediction.lower()
    required_symbols = ['l', 'ω', 'λ']
    # 考虑到字符转义和希腊字母的不同表示，增加备选匹配
    symbol_patterns = {
        'L': r'(l|length|长度)',
        'Ω': r'(ω|omega|角速度|\\omega)',
        'λ': r'(λ|lambda|波长|\\lambda)'
    }

    missing_symbols = []
    for sym, pattern in symbol_patterns.items():
        if not re.search(pattern, pred_text):
            missing_symbols.append(sym)

    if missing_symbols:
        return {'result': 'fail', 'message': f'计算频率差时缺失关键物理量符号: {missing_symbols}', 'evidence': prediction[:200]}

    # Step 3: 公式结构校验 — 检查是否满足 Δv ∝ (L * Ω) / λ 的量纲关系
    # 典型的 Sagnac 频率差公式为 Δv = (4AΩ)/(λP) 或对于环路 Δv ≈ (LΩ)/λ 的变体
    # 检查是否存在 L*Ω/λ 或类似的乘除关系
    structure_pattern = r'(([lL].*?[ωΩ\\omega])|([ωΩ\\omega].*?[lL])).*[\/\\div].*?[λ\\lambda]'
    if re.search(structure_pattern, prediction):
        return {'result': 'pass', 'message': '公式量纲结构符合 Sagnac 效应频率差规律', 'evidence': re.search(structure_pattern, prediction).group()}

    # 如果出现了 L^2 且没有对应的面积解释，或者 c 的幂次异常，则判定为可疑
    if re.search(r'[lL](\^|\*\*)2', pred_text) and 'area' not in pred_text and '面积' not in pred_text:
        return {'result': 'fail', 'message': '频率差计算中长度量纲异常（出现L^2但未说明面积）', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定公式结构的准确性', 'evidence': ''}

