# rule_id=norm_b3caba18056ef362 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_b3caba18056ef362 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_b3caba18056ef362_924cd1c830a9(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及运动参考系发送光信号或相对论时间/长度效应
    trigger_keywords = ['光信号', '参考系', '相对论', '时间膨胀', '收缩', 'light signal', 'frame', 'relativity', 'dilation']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到涉及运动参考系信号传输的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否考虑了时间膨胀 (gamma) 以及信号传输时间 (d/c)
    pred = prediction.lower()
    # 检查是否提到了洛伦兹因子 gamma 或其展开式 sqrt(1-v^2/c^2)
    has_gamma = 'gamma' in pred or 'sqrt' in pred or '1-v' in pred or '1 - v' in pred
    # 检查是否涉及信号传输时间计算 (距离除以光速)
    has_signal_time = '/c' in pred or 'v*t' in pred or 'distance/c' in pred

    if not has_gamma:
        return {'result': 'fail', 'message': '推理过程中未体现时间膨胀公式 (gamma) 的转化', 'evidence': prediction[:200]}

    # Step 3: 符号/公式结构校验 — 匹配 t_receive = gamma * t_send * (1 + v/c) 及其变体
    # 匹配逻辑：接收时间应包含 gamma * t' 且考虑位移带来的延迟
    formula_patterns = [
        r'gamma.*t.*\(1\s*\+\s*v/c\)',
        r't.*gamma.*\(1\s*\+\s*beta\)',
        r't.*\/.*sqrt\(1.*v.*c\)',
        r't_\{receive\}.*gamma.*t.*send'
    ]

    found_formula = False
    for pattern in formula_patterns:
        if re.search(pattern, pred, re.IGNORECASE):
            found_formula = True
            break

    if found_formula:
        return {'result': 'pass', 'message': '检测到符合狭义相对论信号往返逻辑的公式结构', 'evidence': prediction[:200]}

    if not has_signal_time:
        return {'result': 'fail', 'message': '未检测到信号传输时间 (距离/c) 的计算逻辑', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到相关物理量但公式结构不完整或不明确', 'evidence': ''}

# rule_id=norm_c203e54b9543f5f4 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
# rule_id=norm_c203e54b9543f5f4 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_c203e54b9543f5f4_5a82ad017f79(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及激光推进、光帆或辐射压计算
    trigger_keywords = ['激光推进', '光帆', 'laser propulsion', 'light sail', 'radiation pressure']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到激光推进或光帆相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否考虑了多普勒修正因子 (1-beta)/(1+beta)
    # 辐射压推力修正通常涉及两个因子：频率变化和到达率变化，总修正为 ((1-beta)/(1+beta))
    pred = prediction.lower()
    # 匹配 beta, v/c 以及 (1-beta)/(1+beta) 的结构
    doppler_pattern = r'\(1\s*-\s*beta\)\s*/\s*\(1\s*\+\s*beta\)'
    alt_pattern = r'\(c\s*-\s*v\)\s*/\s*\(c\s*\+\s*v\)'

    has_doppler = re.search(doppler_pattern, pred) or re.search(alt_pattern, pred)

    # Step 3: 检查是否提到了双重修正（能量/频率 + 通量/撞击率）
    dual_factor_keywords = ['frequency', 'flux', 'rate', 'energy', 'photon count', '频率', '通量', '光子数', '能量']
    mention_count = sum(1 for kw in dual_factor_keywords if kw in pred)

    if not has_doppler:
        # 如果完全没有体现 (1-beta)/(1+beta) 因子，判定为概念错误
        return {
            'result': 'fail',
            'message': '在计算运动物体辐射压时，未正确应用相对论多普勒修正因子 (1-beta)/(1+beta)',
            'evidence': prediction[:200]
        }

    # 检查公式完整性 F = (2P/c) * ((1-beta)/(1+beta))
    canonical_pattern = r'2\s*\*?\s*P\s*/\s*c\s*\*?\s*\(\s*1\s*-\s*beta\s*\)\s*/\s*\(\s*1\s*\+\s*beta\s*\)'
    if re.search(canonical_pattern, pred.replace(' ', '')):
        return {'result': 'pass', 'message': '正确应用了相对论辐射压修正公式', 'evidence': '匹配到标准修正公式'}

    if mention_count >= 1:
        return {'result': 'pass', 'message': '推导中体现了多普勒修正逻辑', 'evidence': '检测到修正因子及相关物理量描述'}

    return {'result': 'inconclusive', 'message': '检测到修正因子但无法确认推导完整性', 'evidence': ''}

