# rule_id=norm_5c10bd4e042d6dd0 | domain=Modern Physics | topic=Relativistic Energy and Momentum
def check_norm_5c10bd4e042d6dd0_c23dabe8f185(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及粒子碰撞解离、反应的最小速度或阈能
    trigger_keywords = ['最小速度', '阈能', 'threshold', 'minimum energy', 'minimum speed', '解离', '反应']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到碰撞阈值相关的计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否考虑了末态粒子的共同运动（不变质量/质心系能量）
    # 核心逻辑是末态在阈值时应具有相同的速度（相对静止），即不变质量等于静质量之和
    pred_lower = prediction.lower()
    logic_keywords = ['共同运动', '共速', '质心系', 'invariant mass', 'center of momentum', 'relative rest']
    has_logic = any(kw in pred_lower for kw in logic_keywords)

    # Step 3: 公式校验 — 检查是否使用了 s = (E1+E2)^2 - (p1+p2)^2 的等效形式
    # 匹配类似 (E+m)^2 - p^2 = (sum m)^2 的结构
    formula_patterns = [
        r'\(E.*\+.*m.*\)\^2.*-.*p.*\^2',
        r's\s*=\s*E\^2\s*-\s*p\^2',
        r'm_\{?final\}?\^2',
        r'\(M\s*\+\s*m\)\^2'
    ]
    has_formula = any(re.search(pat, prediction) for pat in formula_patterns)

    if not has_logic and not has_formula:
        return {
            'result': 'fail',
            'message': '在计算碰撞阈值时，未体现末态粒子共速（共同运动）或不变质量守恒的物理逻辑。',
            'evidence': prediction[:200]
        }

    # Step 4: 验证符号覆盖 (E1, m2, m_final, p1)
    required_symbols = ['E', 'm', 'p']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)

    if has_formula or (has_logic and symbol_count >= 2):
        return {
            'result': 'pass',
            'message': '已考虑末态粒子共同运动动能及不变质量守恒逻辑。',
            'evidence': re.search(r'.{0,50}(共速|质心|\^2).{0,50}', prediction).group(0) if re.search(r'.{0,50}(共速|质心|\^2).{0,50}', prediction) else prediction[:100]
        }

    return {'result': 'inconclusive', 'message': '逻辑表述模糊，无法确定是否正确应用了阈值动量约束。', 'evidence': prediction[:100]}

