# rule_id=norm_64c927eb753bff0a | domain=Modern Physics | topic=Relativistic Energy and Momentum
def check_norm_64c927eb753bff0a_d5cb5621df3f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“最小速度/能量”且涉及“碰撞/产生新粒子”
    trigger_keywords = ['最小', '阈值', 'threshold', 'minimum']
    collision_keywords = ['碰撞', '产生', '解离', 'collision', 'produce', 'create', 'dissociate']
    q_c = (question + context).lower()
    if not (any(k in q_c for k in trigger_keywords) and any(k in q_c for k in collision_keywords)):
        return {'result': 'inconclusive', 'message': '未检测到碰撞阈值能量相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否仅考虑能量守恒而忽略动量守恒（即是否直接令 E_initial = E_final_rest）
    pred = prediction.lower()
    # 如果只看到能量相加而没有减去动量项或使用不变质量公式，则可能存在逻辑错误
    # 检查是否使用了不变质量公式 s = E^2 - p^2 或质心系概念
    invariant_mass_patterns = [
        r'e\^2\s*-\s*p\^2',
        r'\(e1\s*\+\s*m2\)\^2\s*-\s*p1\^2',
        r'invariant\s*mass',
        r'不变质量',
        r'质心系',
        r'center\s*of\s*momentum'
    ]

    has_invariant_logic = any(re.search(p, pred) for p in invariant_mass_patterns)

    # 检查是否错误地直接令 E_total = sum(m_final)
    error_logic_pattern = r'e_?\d*\s*=\s*\(?m_?\d*\s*\+\s*m_?\d*\)?'

    if not has_invariant_logic:
        # 如果没有体现动量约束，且直接进行了简单的能量守恒计算，判定为逻辑缺失
        if re.search(error_logic_pattern, pred):
            return {'result': 'fail', 'message': '计算阈值能时忽略了动量守恒约束，未应用不变质量公式', 'evidence': prediction[:200]}
        return {'result': 'inconclusive', 'message': '未明确观察到动量约束或不变质量公式的应用', 'evidence': ''}

    # Step 3: 符号/公式校验 — 检查 canonical 形式的近似匹配
    # (E_1 + m_2)^2 - p_1^2 = (Σm_final)^2
    if re.search(r'\(e.*\+.*m.*\)\^2.*-.*p.*\^2', pred) or re.search(r's\s*=', pred):
        return {'result': 'pass', 'message': '正确使用了能动量不变质量公式计算阈值', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑路径不清晰', 'evidence': ''}

