# rule_id=norm_6fd2c4dd26ce82ff | domain=Modern Physics | topic=Relativistic Energy and Momentum
def check_norm_6fd2c4dd26ce82ff_25cc88225476(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题干是否包含具体数值（如能量E、动量p、速度v或质量m等）
    # 匹配形如 0.5c, 10MeV, 1.2kg 等数值模式
    numeric_pattern = r'\d+\.?\d*\s*(?:[cmk]?eV|[cmk]?g|J|kg|c|m/s)'
    q_values = re.findall(numeric_pattern, question + context)

    if not q_values:
        return {'result': 'inconclusive', 'message': '题干未检测到具体物理数值，不触发参数覆盖审计', 'evidence': ''}

    # Step 2: 检查推理过程是否仅含定性描述而忽略了数值计算
    # 如果推理中没有出现任何数值或计算符号，则认为可能存在简化过度
    pred_values = re.findall(r'\d+\.?\d*', prediction)
    calculation_symbols = re.findall(r'[\+\-\*\/\=]|sqrt|gamma', prediction)

    # 如果题干有数值但推理中完全没有数值或运算符号，判定为逻辑缺失
    if len(pred_values) < 2 and not calculation_symbols:
        return {
            'result': 'fail',
            'message': '题干给出了具体数值，但推导过程仅含定性描述，未将参数纳入计算链条',
            'evidence': f"题干数值: {q_values[:3]}; 推理片段: {prediction[:150]}"
        }

    # Step 3: 检查关键参数是否在推理中被提及（模糊匹配）
    # 提取题干中可能的变量名或单位作为锚点
    missing_params = []
    for val in q_values:
        val_clean = val.strip()
        if val_clean not in prediction:
            missing_params.append(val_clean)

    # 如果超过一半的题干数值在推理中未出现，且推理长度较短，则判定为审计不通过
    if len(missing_params) > len(q_values) * 0.5 and len(prediction) < 200:
        return {
            'result': 'fail',
            'message': '推导过程未覆盖题干给出的关键量纲参数，物理模型可能简化过度',
            'evidence': f"缺失参数示例: {missing_params[:3]}"
        }

    return {'result': 'pass', 'message': '参数在推导过程中有体现或已进行定量分析', 'evidence': f"检测到参数参与: {len(q_values) - len(missing_params)}/{len(q_values)}"}

