    inversion_keywords = ['inversion', 'reverse', '反转', 'aspect ratio', '长宽比', 'shape', '形状']
    if not any(kw in pred for kw in inversion_keywords):
        return {'result': 'fail', 'message': '未提及BEC释放后的形状反转或长宽比变化逻辑', 'evidence': prediction[:200]}

