    # Step 2: 检查逻辑 — 验证是否包含能量 E 与体积 V 或半径 R 的导数关系 P = -dE/dV
    pred = prediction.lower()
    # 检查是否提到了压强与能量导数的关系
    has_thermo_def = re.search(r'p\s*=\s*-?\s*d[e|u]/d[v|r]', pred) or 'p = -de/dv' in pred
    # 检查是否提到了 E ∝ R^-2 或 E ∝ V^(-2/3) 的特征
    has_energy_scaling = re.search(r'e\s*\(?\w*\)?\s*\w*\s*r\^?-2', pred) or 'r**-2' in pred or 'v**(-2/3)' in pred

    if not (has_thermo_def or has_energy_scaling):
        return {'result': 'fail', 'message': '未体现压强与能量的热力学定义一致性 (P = -dE/dV)', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 P = (2/3)*(E/V) 或 P ∝ R^-5 的比例关系
    # 对于三维情况，V ∝ R^3, E ∝ R^-2 => P = -dE/dV = -(dE/dR)/(dV/dR) = -(-2R^-3)/(3R^2) ∝ R^-5
    has_canonical = re.search(r'p\s*=\s*\(?2/3\)?\s*\*?\s*\(?e_?k\s*/\s*v\)?', pred)
    has_r5_scaling = re.search(r'p\s*\w*\s*r\^?-5', pred) or 'r**-5' in pred

    if has_canonical or has_r5_scaling:
        return {'result': 'pass', 'message': '压强建模符合热力学一致性且比例系数正确', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '检测到相关物理量但无法确认计算系数的准确性', 'evidence': prediction[:200]}

