    trigger_keywords = ['flies past', 'captured', 'capture', '飞过', '捕获', '形成原子', '基态', 'ground state']
    q_c_text = (question + context).lower()
    if not any(kw in q_c_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到粒子捕获或进入基态的相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查预测中是否考虑了初始动能 (1/2mv^2 或 K) 与结合能 (|E1|) 的加和
    # 错误建模通常只计算能级差或忽略初始动能
    pred_text = prediction.lower()
    # 寻找能量守恒的组成部分：辐射能(h*c/lambda 或 E_photon)、动能(1/2mv^2 或 K)、结合能/电离能(E1)
    has_kinetic = re.search(r'(1/2\s*\*?\s*m\s*\*?\s*v\^2|1/2mv\^2|kinetic energy|动能|K_e|E_k)', pred_text)
    has_binding = re.search(r'(E_1|E1|ground state energy|binding energy|结合能|基态能量)', pred_text)

    if not (has_kinetic and has_binding):
        return {'result': 'fail', 'message': '模型未能明确列出初始动能与基态结合能的守恒关系', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查公式结构是否符合 h*c/λ = K + |E1|
    # 匹配类似 E = K + E1 的结构，注意绝对值或能量相加的逻辑
    conservation_pattern = r'(\+|plus|sum).* (E_1|E1|binding|结合能)'
    if re.search(conservation_pattern, pred_text) or re.search(r'h\s*\*?\s*c\s*/\s*\\?lambda', pred_text):
        # 进一步检查是否只是简单的能级差（如 E2 - E1），如果是，则可能违反本规则
        if re.search(r'E_\d\s*-\s*E_1', pred_text) and not has_kinetic:
            return {'result': 'fail', 'message': '模型仅计算了能级差，忽略了粒子的初始动能', 'evidence': prediction[:200]}
        return {'result': 'pass', 'message': '模型正确识别了辐射能量等于动能与结合能之和', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定能量守恒公式的具体形式', 'evidence': ''}

