# rule_id=norm_ec45b23df9c24be1 | domain=Modern Physics | topic=Photoelectric Effect and Compton Scattering
def check_norm_ec45b23df9c24be1_be2b0c44c55c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多级加速（倍增管、级联、多级加速器等）
    trigger_keywords = ['倍增管', '级联', '多级加速', 'dynode', 'cascade', 'multi-stage']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多级加速或级联电路场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否对每一级电荷量分别求功并求和，而非简单总数乘以单级电压
    # 错误逻辑通常表现为直接用最终粒子数 N_final * e * V_single 或忽略中间过程的电荷增量
    pred = prediction.lower()

    # 检查是否包含求和符号或分步累加的逻辑描述
    has_summation = any(x in pred for x in ['sum', 'sigma', '累加', '总功', '每一级', '各级'])
    # 检查公式特征：E = sum(Ni * e * Vi) 或类似的乘积求和形式
    formula_pattern = re.search(r'(\\sum|sum|\+.*\+)', pred)

    # Step 3: 符号校验与错误识别
    # 如果预测中直接出现类似 E = N * e * V 且 N 是最终输出数，而没有体现中间级联过程，则可能存在逻辑错误
    if 'n' in pred and 'e' in pred and 'v' in pred:
        # 寻找是否体现了分级索引 i 或 级数 n 的累加关系
        if not (re.search(r'[n_][i1]', pred) or has_summation or formula_pattern):
            return {
                'result': 'fail',
                'message': '未体现多级加速中每一级电荷位移做功的累加逻辑，可能误用了最终粒子数计算总功',
                'evidence': prediction[:200]
            }

    # 如果明确看到了分级求和的公式结构
    if formula_pattern or re.search(r'n_\d.*v_\d', pred):
        return {'result': 'pass', 'message': '检测到分级能量累加逻辑', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了级联能量累加规则', 'evidence': ''}

