def check_norm_2d0ade8f25cb51f3_dc0484a6d7ea(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及通过特征距离d估算粒子密度n
    trigger_keywords = ['密度', '距离', '间距', '估算', 'density', 'distance', 'spacing']
    q_c_text = (question + context).lower()
    if not all(k in q_c_text for k in ['n', 'd']) and not ('密度' in q_c_text and ('距离' in q_c_text or '间距' in q_c_text)):
        return {'result': 'inconclusive', 'message': '未检测到密度与特征距离的估算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否使用了 n ≈ 1/d³ 的关系
    pred_text = prediction.lower()
    # 匹配 n = 1/d^3, n ~ d^-3, n = d**-3 等形式
    relation_pattern = r'n\s*[≈~=]\s*(1/d\^3|d\^\{-3\}|1/d\*\*3)'
    has_relation = re.search(relation_pattern, pred_text) or ('1/d' in pred_text and ('3' in pred_text or '立方' in pred_text))

    if not has_relation:
        return {'result': 'fail', 'message': '未发现密度n与特征长度d的三次方反比关系(n ≈ 1/d³)', 'evidence': prediction[:200]}

    # Step 3: 数值校验 — 检查密度量级是否异常（若计算出的n远大于10^25且d极小）
    # 提取科学计数法中的指数部分
    density_match = re.search(r'10\^(\{)?(\d+)(\})?', pred_text)
    if density_match:
        exponent = int(density_match.group(2))
        # 如果密度量级远超常温常压（如 > 10^30），且未对d的极小值做说明，则可能存在建模错误
        if exponent > 30:
            return {'result': 'fail', 'message': '计算出的密度量级异常偏大，需反查特征距离d是否选取过小', 'evidence': f'检测到密度量级为10^{exponent}'}

    if has_relation:
        return {'result': 'pass', 'message': '符合密度与特征长度幂次关系建模要求', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '证据不足，无法确定建模逻辑是否完全正确', 'evidence': ''}

