    # 匹配关键词如 delta S = 0, delta phi = 0, 一阶导数为零等
    pred_clean = prediction.replace(' ', '')
    zero_variation_patterns = [
        r'\\delta S=0',
        r'\\delta\\phi=0',
        r'\\Delta\\phi=0',
        r'一阶.*(为0|等于0|抵消|平稳)',
        r'first-order.*zero',
        r'stationary.*phase'
    ]

    found_logic = False
