    # Step 3: 符号校验与结论判定
    # 如果明确提到了计算一阶差值但结果不是0，或者认为一阶项不消失，则判定为 fail
    if not found_logic:
        # 检查是否存在错误的非零表述
        if re.search(r'一阶.*(不为0|不等于0|非零)', prediction):
            return {'result': 'fail', 'message': '错误地认为经典路径的一阶变分不为零', 'evidence': prediction}
        return {'result': 'inconclusive', 'message': '未明确提及一阶变分是否为零', 'evidence': ''}

    # 检查是否包含必要的符号 delta S 或 delta phi
