def check_norm_8df5c10d108f1512_f872c0d78542(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及多普勒频移的一阶项近似 (v/c)
    trigger_keywords = ['v/c', '一阶项', 'first order', 'linear approximation', 'doppler shift', '多普勒']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多普勒频移线性近似的触发场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证共振频率关系是否表达为 ω_L(1 ± v/c) = ω_0 或类似结构
    # 匹配模式：omega_L * (1 +/- v/c) = omega_0 或 omega_0 = omega_L * (1 +/- v/c)
    # 兼容不同符号写法如 \omega, w, omega
    pattern_doppler = r'w(mega)?_?[L0].*?\(1\s*[\+\-]\s*v/c\).*?w(mega)?_?[0L]'
    found_formula = re.search(pattern_doppler, prediction, re.IGNORECASE)

    # 检查符号覆盖
    required_symbols = ['v', 'c']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    if not found_formula:
        # 如果没找到标准公式，检查是否存在错误的 v 与 h_bar 等值关系 (v = h_bar)
        if re.search(r'v\s*=\s*\\?hbar', prediction) or re.search(r'v\s*=\s*h/2pi', prediction):
            return {'result': 'fail', 'message': '推导中出现了错误的 v 与 h_bar 等值关系', 'evidence': prediction[:200]}
        return {'result': 'fail', 'message': '未发现正确的多普勒频移线性近似公式 ω_L(1 ± v/c) = ω_0', 'evidence': prediction[:200]}

    # Step 3: 验证是否保留了 v/c 的一阶项而非高阶项
    if 'v^2/c^2' in prediction or '(v/c)^2' in prediction:
        # 如果题目要求保留一阶项但出现了二阶项，可能存在逻辑冗余或错误
        if 'order' in (question + context).lower() and 'first' in (question + context).lower():
             return {'result': 'fail', 'message': '题目要求保留一阶项，但推导中出现了二阶项', 'evidence': prediction[:200]}

    return {'result': 'pass', 'message': '多普勒频移线性近似表达正确且未出现非法等值', 'evidence': found_formula.group()}

# rule_id=norm_d414d8f43c9f4c08 | domain=Modern Physics | topic=Wave-Particle Duality and de Broglie Wavelength
# rule_id=norm_d414d8f43c9f4c08 | domain=Modern Physics | topic=Wave-Particle Duality and de Broglie Wavelength
def check_norm_d414d8f43c9f4c08_92b53af2fda2(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及光子吸收/发射导致的原子动量变化
    trigger_keywords = ['photon', 'absorb', 'emit', 'momentum', 'recoil', '光子', '吸收', '发射', '动量', '反冲']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到光子动量交换场景', 'evidence': ''}

    # Step 2: 检查 prediction 中是否存在 ħω 与 mv 直接加减而无 c 缩放的量纲错误
    # 匹配类似 mv + hbar*omega 或 hbar*omega - mv 的结构，且中间没有除以 c
    # 错误模式：(mv|p) [+-] hbar*omega (没有 /c)
    pred = prediction.replace(' ', '')

    # 查找包含 hbar, omega, h, nu 等光子能量项与质量速度项 mv 的组合
    # 典型的错误公式片段：mv + hbar*omega, p - h*nu
    error_patterns = [
        r'(mv|p|P)[\+\-]([\\]?hbar|h)[\\]?(omega|nu|w|f)',
        r'([\\]?hbar|h)[\\]?(omega|nu|w|f)[\+\-](mv|p|P)'
    ]

    for pattern in error_patterns:
        match = re.search(pattern, pred, re.IGNORECASE)
        if match:
            # 进一步确认该片段周围是否确实缺失了 /c
            context_snippet = pred[max(0, match.start()-5):min(len(pred), match.end()+5)]
            if '/c' not in context_snippet and '\\frac' not in context_snippet:
                return {
                    'result': 'fail',
                    'message': '检测到光子能量项与动量项直接加减，量纲不一致（缺失光速 c）',
                    'evidence': match.group()
                }

    # Step 3: 检查是否正确使用了 p = hbar*omega/c 或 p = hbar*k
    correct_patterns = [
        r'([\\]?hbar|h)[\\]?(omega|nu|w|f)/c',
        r'\\frac{([\\]?hbar|h)[\\]?(omega|nu|w|f)}{c}',
        r'([\\]?hbar|h)q',
        r'([\\]?hbar|h)k'
    ]

    for pattern in correct_patterns:
        if re.search(pattern, pred, re.IGNORECASE):
            return {'result': 'pass', 'message': '光子动量公式量纲正确', 'evidence': '检测到符合 p=E/c 的表达'}

    return {'result': 'inconclusive', 'message': '未发现明确的量纲错误或正确公式表达', 'evidence': ''}

# rule_id=norm_f1e1785942e06778 | domain=Modern Physics | topic=Wave-Particle Duality and de Broglie Wavelength
# rule_id=norm_f1e1785942e06778 | domain=Modern Physics | topic=Wave-Particle Duality and de Broglie Wavelength
def check_norm_f1e1785942e06778_ee2508fa60c4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及 nK (纳开尔文) 量级温度与德布罗意波长计算
    # 匹配 nK, nano-Kelvin, 10^-9 K 等关键词
    trigger_pattern = r'(nk|nano-kelvin|10\^-9\s*k|100\s*nk)'
    if not re.search(trigger_pattern, (question + context).lower()):
        return {'result': 'inconclusive', 'message': '未检测到 nK 量级的极低温场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 校验 λ = h/√(2mkT) 的计算结果数量级
    # 规则指出 100nK 下波长应在 10^-8 到 10^-7 米量级，若出现 10^-11 则为典型错误
    pred_lower = prediction.lower()

    # 提取预测结果中的科学计数法数值 (如 10^-11, 1e-11)
    # 重点寻找 10^-11 或 10^-12 等皮米量级的错误特征
    error_magnitude_pattern = r'(10\^[-−]11|1[eE][-−]11|pm|picometer)'
    correct_magnitude_pattern = r'(10\^[-−][78]|1[eE][-−][78])'

    # Step 3: 符号与公式结构校验 (λ ∝ T^{-1/2})
    has_lambda = 'λ' in prediction or 'lambda' in pred_lower
    has_temp = 't' in pred_lower or 'temperature' in pred_lower

    if re.search(error_magnitude_pattern, pred_lower):
        return {
            'result': 'fail',
            'message': '检测到德布罗意波长计算数量级错误：在 nK 量级下结果不应为皮米(10^-11)量级，通常应在 10^-8 至 10^-7 米。',
            'evidence': re.search(error_magnitude_pattern, pred_lower).group(0)
        }

    if re.search(correct_magnitude_pattern, pred_lower) and (has_lambda or 'wavelength' in pred_lower):
        return {
            'result': 'pass',
            'message': '德布罗意波长数量级符合极低温量子效应预期。',
            'evidence': re.search(correct_magnitude_pattern, pred_lower).group(0)
        }

    return {'result': 'inconclusive', 'message': '未能明确识别波长计算的数量级结果', 'evidence': ''}

# rule_id=norm_5c21fc7f69745f6b | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
# rule_id=norm_5c21fc7f69745f6b | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
def check_norm_5c21fc7f69745f6b_20256aed2a6a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及衰变链、长期平衡或母核半衰期远大于子核的场景
    trigger_keywords = ['衰变链', '放射性平衡', '长期平衡', 'secular equilibrium', 'decay chain', '半衰期远大于']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) or (re.search(r'T_{?1/2}?.*>>', combined_text))

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到放射性长期平衡相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否提到了数量比与半衰期比的关系 (N1/N2 = T1/T2)
    pred = prediction.lower()
    # 匹配 N/T = N/T 或 N1/T1 = N2/T2 或 N1/N2 = T1/T2 等变体
    logic_patterns = [
        r'n_?\d?\s*/\s*t_?\d?',
        r'n_?\d?\s*:\s*n_?\d?\s*=\s*t_?\d?\s*:\s*t_?\d?',
        r'数量.*正比.*半衰期',
        r'n1/n2\s*=\s*t1/t2',
        r'\lambda_?\d?n_?\d?\s*=\s*\lambda_?\d?n_?\d?'
    ]

    found_logic = any(re.search(p, pred) for p in logic_patterns)

    # Step 3: 符号覆盖与公式结构校验
    # 检查是否包含必要的物理量符号 N 和 T(1/2) 或 lambda
    has_symbols = ('n' in pred) and ('t' in pred or 'lambda' in pred or 'λ' in pred)

    if found_logic and has_symbols:
        return {'result': 'pass', 'message': '正确应用了放射性长期平衡的数量与半衰期比例关系', 'evidence': prediction[:200]}

    if not found_logic and ('平衡' in pred or '衰变' in pred):
        # 如果讨论了平衡但没给出正确的比例关系，判定为逻辑缺失
        return {'result': 'fail', 'message': '未体现核素数量与半衰期成正比的平衡关系 (N1/T1 = N2/T2)', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '推理过程中关于数量比的逻辑不明确', 'evidence': ''}

# rule_id=norm_5e9a284304c29307 | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
# rule_id=norm_5e9a284304c29307 | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
def check_norm_5e9a284304c29307_6c5e1b0ffd8f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及长寿命母核（如U238、Th232）及衰变链功率计算场景
    trigger_keywords = ['衰变链', 'decay chain', 'U-238', 'U238', 'Th-232', '功率', 'power', 'activity', '放射性平衡']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到长寿命母核衰变链功率计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否应用放射性平衡原理 (Activity of parent = Activity of daughters)
    # 核心逻辑是 P = A * sum(Q)，其中 A = lambda * N
    pred_lower = prediction.lower()
    has_equilibrium = any(kw in pred_lower for kw in ['平衡', 'equilibrium', 'λ1n1', 'lambda1*n1', 'λn'])
    has_sum_energy = any(kw in pred_lower for kw in ['总能量', 'sum', 'total energy', 'Σ', 'sigma'])

    if not (has_equilibrium or has_sum_energy):
        return {'result': 'fail', 'message': '未体现放射性平衡原理或未考虑全链释放能量总和', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 canonical 公式中的关键元素 (ln2, tau, mu, rho, NA)
    # canonical: w = (\ln 2 / \tau_{1/2}) * (\rho N_A / \mu) * \sum E_{chain}
    required_patterns = [
        r'ln\s*2',
        r'tau|T_?1/2|半衰期',
        r'N_?A|阿伏伽德罗',
        r'mu|\mu|摩尔质量|M',
        r'rho|\rho|密度'
    ]

    match_count = 0
    for pattern in required_patterns:
        if re.search(pattern, prediction, re.IGNORECASE):
            match_count += 1

    # 如果匹配到的关键物理量过少，认为建模不完整
    if match_count < 3:
        return {'result': 'fail', 'message': '计算公式中缺失关键物理量（如半衰期、摩尔质量或密度等）', 'evidence': prediction[:200]}

    # 检查公式结构特征：功率正比于活度乘以能量总和
    if re.search(r'P\s*=|W\s*=|功率\s*=', prediction) and (re.search(r'\*|\(', prediction)):
        return {'result': 'pass', 'message': '已应用放射性平衡原理并正确建立功率计算模型', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '逻辑基本符合但公式表达不完整', 'evidence': ''}

# rule_id=norm_6b5e3a8a7c8dbcee | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
# rule_id=norm_6b5e3a8a7c8dbcee | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
def check_norm_6b5e3a8a7c8dbcee_bd467ab64fb1(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及放射性衰变且存在小量近似场景（衰变数远小于总数）
    trigger_keywords = ['衰变', 'decay', 'half-life', '半衰期', 'activity', '放射性']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到核衰变相关场景', 'evidence': ''}

    # 检查是否暗示了小量近似（如 t << tau 或 ΔN << N0）
    small_amount_hint = re.search(r'(远小于|<<|small fraction|approx|近似)', question + context)
    if not small_amount_hint:
        return {'result': 'inconclusive', 'message': '未检测到小量近似触发条件', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否正确使用了线性近似公式 ΔN = N0 * (t/tau) 或 tau = N0*t/ΔN
    # 匹配 tau 的计算表达式，允许不同的符号表示
    pred = prediction.replace(' ', '')
    # 匹配 tau = (N0 * t) / delta_N 的变体
    pattern_linear = re.compile(r'tau.*=.*(N_?0|N).*t.*/.*(Delta|Δ)N', re.IGNORECASE)
    # 匹配 delta_N = N0 * t / tau 的变体
    pattern_delta = re.compile(r'(Delta|Δ)N.*=.*(N_?0|N).*t.*/.*tau', re.IGNORECASE)

    has_linear_approx = pattern_linear.search(pred) or pattern_delta.search(pred)

    # Step 3: 符号覆盖检查
    required_symbols = ['N_0', 't', 'N'] # 简化匹配
    symbol_count = sum(1 for sym in required_symbols if sym in prediction)

    if has_linear_approx:
        return {'result': 'pass', 'message': '正确使用了指数衰变的小量线性近似公式', 'evidence': re.search(r'.{0,30}(tau|Delta|Δ).{0,30}', prediction).group() if re.search(r'(tau|Delta|Δ)', prediction) else ''}

    # 如果应该用近似但用了复杂的对数公式且计算冗余，或者完全没体现线性关系，则视为建模风险
    if 'exp' in pred or 'log' in pred or 'ln' in pred:
        # 如果在 ΔN << N0 时仍坚持使用复杂对数计算且未提及近似，标记为建模风格建议（保守返回inconclusive或特定fail）
        return {'result': 'inconclusive', 'message': '检测到对数计算，未显式使用线性近似简化', 'evidence': 'found exp/log/ln in prediction'}

    if symbol_count >= 2 and not has_linear_approx:
        return {'result': 'fail', 'message': '在小量衰变场景下未提取出正确的线性近似关系 tau = (N0 * t) / ΔN', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '证据不足以判定近似准则的使用情况', 'evidence': ''}

# rule_id=norm_77069d3aa80fcd3e | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
# rule_id=norm_77069d3aa80fcd3e | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
def check_norm_77069d3aa80fcd3e_c1a45984662c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及镜像核（Mirror Nuclei）及其质量/结合能差异
    trigger_keywords = ['镜像核', 'mirror nuclei', 'mirror nucleus', '结合能差', 'binding energy difference', '质量差', 'mass difference']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到镜像核结合能差相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否将结合能差归因于库仑能差异 (Coulomb energy)
    pred_lower = prediction.lower()
    coulomb_keywords = ['库仑能', 'coulomb energy', 'coulomb potential', 'electrostatic']
    if not any(kw in pred_lower for kw in coulomb_keywords):
        return {'result': 'fail', 'message': '未明确将结合能差归因于库仑能差异', 'evidence': prediction[:200]}

    # Step 3: 公式校验 — 检查是否使用了 ΔE = 3/5 * k * e^2 * (Z1^2 - Z2^2) / R 或类似变体
    # 匹配特征：3/5 或 0.6，常数 k 或 1/(4πε0)，电荷平方 e^2，原子序数平方差 Z^2-(Z-1)^2，半径 R
    formula_patterns = [
        r'0\.6.*k.*e\^2.*Z.*R',
        r'3/5.*k.*e\^2.*Z.*R',
        r'3/5.*e\^2.*Z.*R',
        r'Z.*\(Z-1\).*R',
        r'Z\^2.*\(Z-1\)\^2'
    ]

    found_formula = False
    for pattern in formula_patterns:
        if re.search(pattern, prediction, re.IGNORECASE):
            found_formula = True
            break

    if found_formula:
        return {'result': 'pass', 'message': '正确使用了镜像核库仑能建模公式', 'evidence': prediction[:200]}

    # 如果提到了库仑能但公式不完整或不匹配，保守返回 inconclusive
    return {'result': 'inconclusive', 'message': '检测到库仑能讨论但未识别出标准建模公式', 'evidence': prediction[:200]}

# rule_id=norm_79596b7737927aee | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
# rule_id=norm_79596b7737927aee | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
def check_norm_79596b7737927aee_ce75fc73f2a4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及衰变链、长寿命母核与短寿命子核的平衡场景
    trigger_keywords = ['衰变链', '放射性平衡', '母核', '子核', '丰度', '活度', 'decay chain', 'equilibrium']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到衰变链平衡相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 寻找长期平衡公式 N_A * λ_A = N_B * λ_B 或 N/T 形式
    # 匹配 N1*lambda1 = N2*lambda2 或 N1/T1 = N2/T2 及其变体
    pred = prediction.lower()
    # 匹配 N*lambda 或 N*λ
    lambda_pattern = r'n_?[ab12i].*?[\\lambda|λ]_?[ab12i]\s*=\s*n_?[ab12i].*?[\\lambda|λ]_?[ab12i]'
    # 匹配 N/T 或 N/T_{1/2}
    half_life_pattern = r'n_?[ab12i]\s*/\s*t_?(\{?1/2\}?)?[ab12i]?\s*=\s*n_?[ab12i]\s*/\s*t_?(\{?1/2\}?)?[ab12i]?'

    has_lambda_eq = re.search(lambda_pattern, pred)
    has_half_life_eq = re.search(half_life_pattern, pred)

    # Step 3: 符号覆盖检查 (N, T_{1/2} 或 lambda)
    required_symbols = ['n', 't']
    symbol_count = sum(1 for s in required_symbols if s in pred)

    if has_lambda_eq or has_half_life_eq:
        return {'result': 'pass', 'message': '已应用长期放射性平衡公式', 'evidence': has_lambda_eq.group(0) if has_lambda_eq else has_half_life_eq.group(0)}

    # 如果明确在计算比例但没用平衡公式，则判定为 fail
    if '比例' in combined_text or 'ratio' in combined_text:
        if 'n_a' in pred and 'n_b' in pred and '=' in pred:
             # 检查是否错误地只用了简单的比例而忽略了衰变常数
             return {'result': 'fail', 'message': '计算丰度比例时未体现长期平衡公式 (N_A/T_A = N_B/T_B)', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '未能明确识别平衡公式的应用', 'evidence': ''}

# rule_id=norm_7a9dc2a3c3630238 | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
# rule_id=norm_7a9dc2a3c3630238 | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
def check_norm_7a9dc2a3c3630238_fd0a2cffa6e1(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及粒子种类转换（如中微子、衰变产物）及探测效率差异
    trigger_keywords = ['中微子', '振荡', '转换', '效率', 'neutrino', 'oscillation', 'efficiency', 'detection']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到粒子转换或探测效率相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否考虑了不同组分的效率加权 (N_actual = Σ η_i * N_i)
    # 检查 prediction 中是否包含效率加权求和的逻辑，或比例之和为1的隐含逻辑
    pred_lower = prediction.lower()
    # 寻找效率符号 η (eta) 或 efficiency 的表达
    efficiency_pattern = r'(eta|η|效率|efficiency)'
    weight_pattern = r'(\+|sum|Σ|加权|total)'

    if not re.search(efficiency_pattern, pred_lower):
        return {'result': 'fail', 'message': '推理过程中未明确考虑探测效率(η)的影响', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查 canonical 形式 N2 = N1 * [(1 - f) + (η_x / η_e) * f]
    # 检查是否包含比例 f (或 P) 以及效率比值
    required_symbols = ['f', 'η', 'N']
    symbol_count = sum(1 for sym in required_symbols if sym in prediction or sym in pred_lower)

    # 匹配加权求和的结构特征：(1-f) 和 (ratio * f)
    structure_match = re.search(r'1\s*-\s*[fpP]|\(1\s*-\s*[fpP]\)|[ηe]/[ηx]|[ηx]/[ηe]', pred_lower)

    if symbol_count >= 2 or structure_match:
        # 进一步检查是否体现了总数方程的等价性
        if 'Σ' in prediction or '+' in prediction or 'sum' in pred_lower:
            return {'result': 'pass', 'message': '探测总数方程符合效率加权律', 'evidence': prediction[:200]}
        else:
            return {'result': 'inconclusive', 'message': '检测到效率符号但未见明确的加权求和公式', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否遵循了粒子转换探测效率加权律', 'evidence': ''}

# rule_id=norm_87eefe6e7d599eab | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
# rule_id=norm_87eefe6e7d599eab | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
def check_norm_87eefe6e7d599eab_51372898965c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题目是否涉及同位素比例且未明确初始值
    # 匹配如 238U:235U, U-238/U-235, 比例, ratio 等关键词
    isotope_pattern = r'(\d{2,3}[A-Za-z]{1,2}[:/]\d{2,3}[A-Za-z]{1,2}|比例|ratio|测年|dating)'
    if not re.search(isotope_pattern, question + context, re.IGNORECASE):
        return {'result': 'inconclusive', 'message': '未检测到同位素比例测年场景', 'evidence': ''}

    # 如果题目明确说了“初始比例为...”，则本规则不适用（属于已知初始值情况）
    if re.search(r'(初始比例|initial ratio|original ratio)', question + context):
        return {'result': 'inconclusive', 'message': '题目已提供初始比例，不适用本校验规则', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查是否将当前比例误认为初始比例 N0
    # 测年逻辑应包含从当前量 N_now (或 N_t) 推导 N_0 或直接使用衰变方程 N = N0 * e^(-λt)
    pred_lower = prediction.lower()

    # 检查是否直接将题目给出的比例代入到了 N0 的位置，或者缺乏指数衰变的回溯过程
    # 负面特征：直接令 N0 = [题目数值]
    # 正面特征：出现 e^(lambda*t) 或 ln(N0/N) 等反推结构
    has_decay_eq = re.search(r'(e\^|exp|ln|log|2\^|0\.5\^)', pred_lower)
    has_back_calculation = re.search(r'(N_0|N0).*=.*(N_now|N_t|N).*[*\/]', pred_lower) or 'e^{' in pred_lower

    if not has_decay_eq:
        return {'result': 'fail', 'message': '推理中缺失衰变方程或对数转换，可能误用了比例关系', 'evidence': prediction[:200]}

    # Step 3: 符号与公式结构校验 (N_0 = N_now * e^(λT))
    # 检查是否体现了 N0 是通过当前量乘以增长因子（或除以衰变因子）得到的
    if re.search(r'N_?0\s*=\s*N(_?now|_?t)?\s*\*\s*e', pred_lower) or re.search(r'N(_?now|_?t)?\s*=\s*N_?0\s*\*\s*e', pred_lower):
        return {'result': 'pass', 'message': '正确使用了衰变方程进行时态回溯', 'evidence': prediction[:150]}

    if 'n0' in pred_lower and 'n' in pred_lower and ('lambda' in pred_lower or 't' in pred_lower):
        return {'result': 'pass', 'message': '包含必要的物理量符号，逻辑基本完整', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '无法确定比例代入逻辑是否正确', 'evidence': ''}

# rule_id=norm_97c6d33d4dabd672 | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
# rule_id=norm_97c6d33d4dabd672 | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
def check_norm_97c6d33d4dabd672_9606a26252f4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及非放射性参考同位素（如 204Pb）
    # 常见参考同位素包括 204Pb, 86Sr, 144Nd 等，重点匹配 204Pb 或 reference isotope 概念
    trigger_keywords = ['204Pb', 'Pb-204', 'reference isotope', '非放射性成因', '参考同位素']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到非放射性参考同位素场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否执行了“总比例减去初始比例”的扣除操作
    # 核心逻辑：(Total/Ref) - (Initial/Ref) 或类似的差值计算
    pred = prediction.lower()
    # 匹配减法逻辑，尤其是涉及 initial/original/t=0 的比例扣除
    deduction_pattern = r'(-|minus|sub|减去).*?(initial|original|\(0\)|初始|t=0)'
    has_deduction = re.search(deduction_pattern, pred) or '-' in pred

    # Step 3: 符号与公式结构校验
    # 检查是否包含 required_symbols: Pb_initial, Pb_ref, Pb_total (或其变体)
    required_symbols = ['204', 'initial', 'total']
    symbol_count = sum(1 for sym in required_symbols if sym in pred)

    # 检查 canonical 公式结构: (Pb_total/Pb_ref) - (Pb_initial/Pb_ref)
    # 简化匹配：比值相减的形式
    formula_pattern = r'\/.*?204.*?\-.*?\/.*?204'
    has_formula = re.search(formula_pattern, pred)

    if not has_deduction and not has_formula:
        return {
            'result': 'fail',
            'message': '未发现非放射性参考同位素扣除逻辑，需先减去初始比例以提取纯衰变增量',
            'evidence': prediction[:200]
        }

    if has_formula or (has_deduction and symbol_count >= 2):
        return {
            'result': 'pass',
            'message': '已正确应用参考同位素扣除法进行建模',
            'evidence': re.search(r'.{0,50}(\/.*?204|减去|initial).{0,50}', pred).group(0) if has_deduction else ''
        }

    return {'result': 'inconclusive', 'message': '检测到相关术语但计算步骤不明确', 'evidence': prediction[:100]}

# rule_id=norm_9b21b10168a23ee1 | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
# rule_id=norm_9b21b10168a23ee1 | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
def check_norm_9b21b10168a23ee1_45c45000d8af(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及核衰变、核子总数计算或质量数 A
    trigger_keywords = ['核衰变', 'decay', 'nucleon', '核子', '质量数', 'mass number', 'atomic number', '原子序数']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到核衰变或核子数计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否混淆了核子数(A)与原子序数(Z)
    # 如果 prediction 中将核子数等同于质子数/原子序数，则判定为 fail
    pred_lower = prediction.lower()
    if re.search(r'(核子数|nucleon\s*number)\s*(等于|is|=)\s*(原子序数|质子数|atomic\s*number|proton\s*number)', pred_lower):
        return {'result': 'fail', 'message': '错误地将核子数等同于原子序数/质子数', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查是否使用了 N = M/m 的逻辑（若涉及总质量和单核子质量）
    # 匹配 M/m 形式的表达式，考虑 LaTeX 格式
    has_mass_total = re.search(r'M(_\{?total\}?)?|总质量', combined_text)
    has_mass_nucleon = re.search(r'm(_\{?nucleon\}?)?|单核子质量', combined_text)

    if has_mass_total and has_mass_nucleon:
        # 检查 prediction 是否包含 N = M/m 的计算逻辑
        if re.search(r'M\s*/\s*m|\\frac\{M\}\{m\}', prediction):
            return {'result': 'pass', 'message': '正确使用了总质量除以单核子质量计算核子数', 'evidence': prediction[:200]}
        elif re.search(r'm\s*/\s*M|\\frac\{m\}\{M\}', prediction):
            return {'result': 'fail', 'message': '核子数计算公式颠倒', 'evidence': prediction[:200]}

    # Step 4: 检查是否明确区分了 A = Z + N (质子+中子)
    if re.search(r'A\s*=\s*Z\s*\+\s*N|核子数\s*=\s*质子数\s*\+\s*中子数', prediction):
        return {'result': 'pass', 'message': '正确区分并定义了核子数', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '未发现明确的核子数定义或计算错误', 'evidence': ''}

