# rule_id=norm_fbe42e63b0b93eb9 | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
def check_norm_fbe42e63b0b93eb9_c6c39d3ada77(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
