    # Step 2: 检查逻辑 — 验证是否使用了 R = r0 * A^(1/3) 的幂律关系
    # 匹配 A 的 1/3 次方，或者 A 的立方根，或者 A^(1/3)
    power_law_pattern = r'A\^\(1/3\)|A\^\{1/3\}|A\s*\*\*\s*\(1/3\)|立方根|root\s*of\s*A'
    formula_pattern = r'R\s*=\s*r_?0?\s*\*?\s*A'

    pred_text = prediction.replace(' ', '')
    has_power_law = re.search(power_law_pattern, prediction, re.IGNORECASE) or re.search(r'A\^\{?1/3\}?', prediction)

    # 检查是否提到了质量数 A 和半径 R 的符号
    has_symbols = 'A' in prediction and ('R' in prediction or 'r' in prediction)

    if not (has_power_law or (has_symbols and '1/3' in prediction)):
        return {
            'result': 'fail',
            'message': '未检测到基于体积叠加原理的 R = r0 * A^(1/3) 关系或 1/3 幂律逻辑',
            'evidence': prediction[:200]
        }

    # Step 3: 符号覆盖与公式结构校验
