    if re.search(r'r_?0|r_?N|1\.[24]', prediction):
        return {
            'result': 'pass',
            'message': '成功验证核半径与质量数的 1/3 次幂关系及常数项使用',
            'evidence': re.search(r'.{0,30}(A|1/3).{0,30}', prediction).group(0) if has_power_law else ''
        }

