# rule_id=norm_fd648973f8087b3b | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
# rule_id=norm_fd648973f8087b3b | domain=Modern Physics | topic=Nuclear Physics (Binding Energy, Radioactivity)
def check_norm_fd648973f8087b3b_277be57a8c15(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查题干是否包含 log10(tau) 或类似的对数半衰期描述
    log_pattern = r'log(?:10)?\s*\(?\\?tau\)?|log(?:10)?\s*\(?\u534a\u8870\u671f\)?|\u534a\u8870\u671f\u7684\u5bf9\u6570'
    if not re.search(log_pattern, question + context, re.IGNORECASE):
        return {'result': 'inconclusive', 'message': '题干未提及对数半衰期数据', 'evidence': ''}

    # Step 2: 检查推理过程中是否执行了 10^x 的幂运算转换
    # 查找类似 tau = 10^... 或 10**... 的表达式
    power_pattern = r'10\s*\^|10\s*\*\*|exp\(.*?10\)|pow\(10'
    has_conversion = re.search(power_pattern, prediction)

    # Step 3: 检查单位匹配（如秒 s）与衰变常数 lambda 的关系
    # 衰变常数公式 lambda = ln2 / tau
    decay_const_pattern = r'\\lambda|\u8870\u53d8\u5e38\u6570'

    if not has_conversion:
        # 如果提到了对数但没有看到明显的 10^x 转换逻辑，判定为计算风险
        return {'result': 'fail', 'message': '未发现对数半衰期到线性数值的 10^x 转换步骤', 'evidence': prediction[:200]}

    # Step 4: 验证公式结构是否符合 tau = 10^{log_tau}
    if re.search(r'10\^\{?log', prediction, re.IGNORECASE) or re.search(r'tau\s*=\s*10', prediction, re.IGNORECASE):
        # 进一步检查是否提到了单位转换或衰变常数计算
        if re.search(decay_const_pattern, prediction) and ('s' in prediction.lower() or '\u79d2' in prediction):
            return {'result': 'pass', 'message': '正确执行了对数转换并考虑了单位/衰变常数', 'evidence': '检测到幂运算及衰变常数相关描述'}
        return {'result': 'pass', 'message': '检测到对数转换逻辑', 'evidence': 'found 10^x conversion'}

    return {'result': 'inconclusive', 'message': '检测到转换迹象但无法确认计算准确性', 'evidence': ''}

# rule_id=norm_3e551212bfa03861 | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
# rule_id=norm_3e551212bfa03861 | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
def check_norm_3e551212bfa03861_ac165a79a096(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及粒子转化比例 f 和探测效率 η
    # 匹配 f, eta, η, efficiency, conversion 等关键词
    trigger_pattern = r'(转化|效率|efficiency|conversion|ratio|比例|f|η|eta)'
    if not re.search(trigger_pattern, question + context, re.IGNORECASE):
        return {'result': 'inconclusive', 'message': '未检测到粒子转化或探测效率相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证预测中是否包含转化比例 f 及其对应的效率加权逻辑
    # 核心逻辑是 N_total = N_initial * [(1-f)*η1 + f*η2] 或其变体
    pred_text = prediction.replace(' ', '')

    # 检查是否提到了转化比例 f 和效率 η 的组合关系
    # 模式 1: (1-f)*eta1 + f*eta2
    # 模式 2: N1*(1-f + f*(eta_x/eta_e))
    logic_patterns = [
        r'\(1-f\)\*?η',
        r'f\*?η',
        r'1-f\+f\*\(η',
        r'η_?[1e].*\(1-f\)',
        r'η_?[2x].*f'
    ]

    found_logic = any(re.search(p, pred_text, re.IGNORECASE) for p in logic_patterns)

    # Step 3: 符号覆盖检查 (required_symbols: N_1, N_2, f, η_e, η_x)
    required_symbols = ['f', 'η', 'N']
    missing_symbols = [s for s in required_symbols if s not in prediction and s not in pred_text]

    if not found_logic:
        # 如果完全没有体现加权求和或比例分配逻辑，判定为建模错误
        if 'f' in pred_text and ('η' in pred_text or 'eta' in pred_text):
            return {'result': 'fail', 'message': '未正确建立转化前后的效率加权守恒关系', 'evidence': prediction[:200]}
        return {'result': 'inconclusive', 'message': '预测中缺乏明确的效率建模公式', 'evidence': ''}

    # Step 4: 验证公式结构是否满足守恒律（系数之和为1的逻辑）
    # 检查是否存在类似 (1-f) 和 f 的配对使用
    if re.search(r'1-f', pred_text) and re.search(r'[^1]-f', pred_text) is None: # 排除类似 2-f
        if 'f' in pred_text:
            return {'result': 'pass', 'message': '粒子转化效率建模符合守恒律', 'evidence': re.search(r'.{0,30}(1-f).{0,30}', pred_text).group()}

    return {'result': 'inconclusive', 'message': '检测到相关符号但公式结构不完整', 'evidence': prediction[:150]}

# rule_id=norm_514c631804150df0 | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
# rule_id=norm_514c631804150df0 | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
def check_norm_514c631804150df0_6e9c90b6a47f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否包含 'steady state' 且涉及泄漏率与产量表达式
    q_c = (question + context).lower()
    trigger_keywords = ['steady state', 'leakage', 'production rate']
    if not all(kw in q_c for kw in ['steady state']) or not (re.search(r'leakage|leak', q_c) and re.search(r'production|source', q_c)):
        return {'result': 'inconclusive', 'message': '未检测到稳态平衡与泄漏/产量相关的建模场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 必须建立平衡等式 (In + Production = Out + Consumption)
    # 重点检查是否尝试建立包含几何特征值（R, H）的等式来消去通量
    pred = prediction.lower()
    balance_pattern = r'(=|equals|balance|steady state equation)'
    if not re.search(balance_pattern, pred):
        return {'result': 'fail', 'message': '未在推理中建立稳态平衡等式', 'evidence': prediction[:200]}

    # Step 3: 符号与公式校验 — 检查是否包含几何特征值 R, H 以及典型的拉普拉斯算子特征值结构
    # 匹配 canonical: k_1[(2.405/R)^2+(pi/H)^2] = k_2 的结构特征
    required_symbols = ['H', 'R']
    missing_symbols = [s for s in required_symbols if s not in prediction]

    # 检查特征值公式结构 (2.405/R)^2 或 (pi/H)^2
    eigenvalue_structure = re.search(r'(\d+\.\d+/R)\^2|(\pi/H)\^2|B\^2', prediction)

    if missing_symbols:
        return {'result': 'fail', 'message': f'建模缺失关键几何参数: {missing_symbols}', 'evidence': prediction[:200]}

    if eigenvalue_structure:
        return {'result': 'pass', 'message': '已建立包含几何特征值的稳态平衡方程', 'evidence': eigenvalue_structure.group(0)}

    return {'result': 'inconclusive', 'message': '已建立等式但公式特征不明显', 'evidence': prediction[:200]}

# rule_id=norm_82477981795fe3d9 | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
# rule_id=norm_82477981795fe3d9 | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
def check_norm_82477981795fe3d9_ae973dc05f24(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及圆形区域内的正方形点阵布置（如燃料棒阵列）
    trigger_keywords = ['square array', '正方形点阵', '圆形区域', 'circular area', 'lattice', '点阵']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到正方形点阵或圆形区域布置场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否使用了 Fn = (pi * R^2) / d^2 的逻辑，而非简单的几何填充率修正
    # 寻找半径 R (或直径 D) 和间距 d 的关联
    pred_clean = prediction.replace(' ', '')
    # 匹配类似 pi*R^2/d^2 或 (pi*R^2)/(d^2) 的结构
    formula_pattern = r'(\\pi|pi|3\.14).*R\^2.*d\^2'

    # 检查是否提到了面积除以单元面积的逻辑
    logic_keywords = ['area', '面积', 'divided by', '除以', 'd^2', 'd**2']
    has_logic = any(kw in prediction.lower() for kw in logic_keywords)

    if not has_logic and not re.search(formula_pattern, pred_clean, re.IGNORECASE):
        return {'result': 'fail', 'message': '未采用有效总面积除以单个单元面积 (d^2) 的估算逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号校验 — 检查关键符号 R 和 d 是否在公式或描述中出现
    if 'R' in prediction and 'd' in prediction:
        if re.search(formula_pattern, pred_clean, re.IGNORECASE):
            return {'result': 'pass', 'message': '正确使用了点阵容量估算公式 Fn = pi*R^2/d^2', 'evidence': re.search(formula_pattern, pred_clean, re.IGNORECASE).group()}
        return {'result': 'pass', 'message': '逻辑描述符合点阵容量估算法', 'evidence': prediction[:150]}

    return {'result': 'inconclusive', 'message': '检测到相关逻辑但符号或公式表达不完整', 'evidence': prediction[:100]}

# rule_id=norm_881527da9b0e7fdf | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
# rule_id=norm_881527da9b0e7fdf | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
def check_norm_881527da9b0e7fdf_c2dde18d5191(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及最优化（最小化/最大化）及尺寸（H, R, 临界体积等）
    trigger_keywords = ['最小', '最大', '最优化', 'minimum', 'maximum', 'optimize', '尺寸', '半径', '高度']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到最优化尺寸相关场景', 'evidence': ''}

    # 检查是否涉及核反应堆或临界方程背景
    if not any(kw in (question + context) for kw in ['临界', 'critical', 'reactor', '反应堆', 'buckling']):
        return {'result': 'inconclusive', 'message': '非核反应堆临界计算场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否推导了比例关系（如 H/R 或 H=f(R)）
    # 典型比例关系如 H = 1.847R 或类似的比例常数
    ratio_pattern = re.compile(r'H\s*[:=]\s*[\d\.]+\s*R|R\s*[:=]\s*[\d\.]+\s*H|H/R|R/H', re.IGNORECASE)
    has_ratio = ratio_pattern.search(prediction)

    # Step 3: 核心检查 — 是否将比例代回约束方程求解绝对数值
    # 检查 prediction 中是否出现了将比例代入后的数值计算结果，而非仅仅停留在比例上
    # 寻找赋值语句，且包含具体的数值（非比例系数）
    value_assignment = re.compile(r'[HR]\s*=\s*\d+(\.\d+)?\s*(cm|m|cm\^|m\^)', re.IGNORECASE)
    has_absolute_value = value_assignment.search(prediction)

    if has_ratio:
        if has_absolute_value:
            return {'result': 'pass', 'message': '已完成从比例关系到绝对数值的代回求解', 'evidence': has_absolute_value.group()}
        else:
            # 如果只有比例没有绝对数值，且问题要求确定尺寸，则判定为建模不完整
            return {'result': 'fail', 'message': '仅推导了最优化比例，未代回约束方程求解绝对尺寸数值', 'evidence': has_ratio.group()}

    # Step 4: 符号覆盖检查 (H, R)
    if 'H' not in prediction or 'R' not in prediction:
        return {'result': 'inconclusive', 'message': '推理过程中缺失关键符号 H 或 R', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '无法明确判定是否完成代回求解逻辑', 'evidence': ''}

# rule_id=norm_98b582ee60cb1866 | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
# rule_id=norm_98b582ee60cb1866 | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
def check_norm_98b582ee60cb1866_03b152e2c006(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及从质子(p/H)到重核(He/Li/Be等)的聚变条件类比推导
    trigger_keywords = ['fusion', '聚变', 'barrier', '势垒', 'scaling', '缩放', '类比']
    target_nuclei = ['He', 'helium', '氦', 'alpha', 'heavy nuclei', '重核']
    q_ctx = (question + context).lower()
    if not any(kw in q_ctx for kw in trigger_keywords) or not any(tn in q_ctx for tn in target_nuclei):
        return {'result': 'inconclusive', 'message': '未检测到核聚变类比推导场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否考虑了电荷 Z 和质量 m 的复合影响，而非简单线性比例
    # 重点检查是否提到了库仑势垒 (Z1Z2) 和 德布罗意波长/隧道效应 (mu/m)
    pred = prediction.lower()
    # 检查是否提到了电荷 Z 的平方项或乘积项 (Z1*Z2)
    z_factor = re.search(r'z[\s_]*[12]?.*z[\s_]*[12]?|z\^2|电荷.*乘积', pred)
    # 检查是否提到了质量 m 或 折合质量 mu 对穿透概率的影响
    m_factor = re.search(r'\\mu|mass|质量|reduced mass|\\lambda|wavelength', pred)

    # 如果只提到了线性比例（如只看Z或只看m），则判定为逻辑缺失
    if 'linear' in pred and not (z_factor and m_factor):
        return {'result': 'fail', 'message': '错误地使用了简单线性比例，未考虑电荷与质量的复合缩放', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查 canonical 提示中的关键物理量
    # d_c ∝ Z1Z2 / (mu v^2) 或类似的势垒表达
    # lambda ∝ 1 / (mv)
    has_z = re.search(r'Z', prediction)
    has_m = re.search(r'm|\\mu', prediction)
    has_v = re.search(r'v|E|T', prediction) # 速度、能量或温度

    if has_z and has_m and (has_v or 'barrier' in pred):
        # 检查是否正确处理了 Z1Z2 这种非线性关系
        if re.search(r'Z.*Z|Z\^2|4', prediction): # 氦聚变 Z1Z2=4
            return {'result': 'pass', 'message': '正确处理了电荷与质量对聚变条件的复合影响', 'evidence': prediction[:200]}
        else:
            return {'result': 'inconclusive', 'message': '检测到物理量但缩放关系不明确', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足以判定缩放律处理是否正确', 'evidence': ''}

# rule_id=norm_a88d9914beaa216b | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
# rule_id=norm_a88d9914beaa216b | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
def check_norm_a88d9914beaa216b_554a03f4af8d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及核反应方程式书写
    trigger_keywords = ['核反应', '衰变', '裂变', '聚变', '方程式', 'reaction equation']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到核反应相关场景', 'evidence': ''}

    # Step 2: 提取预测中的核反应方程式
    # 匹配类似 ^235_92U + ^1_0n -> ^144_56Ba + ^89_36Kr + 3^1_0n 的结构
    # 简化匹配：寻找包含箭头 -> 或 = 的行，且包含上下标数字特征
    equations = re.findall(r'[^\n]+[\-\u2192=][^\n]+', prediction)
    if not equations:
        return {'result': 'inconclusive', 'message': '未在预测中找到明确的核反应方程式', 'evidence': ''}

    # Step 3: 校验质量数(A)和电荷数(Z)守恒
    for eq in equations:
        # 提取左侧和右侧
        parts = re.split(r'[\-\u2192=]', eq)
        if len(parts) != 2:
            continue

        def get_sums(text):
            # 匹配模式：(系数)?^质量数_电荷数 元素 或 (系数)?_电荷数^质量数 元素
            # 同时也考虑常见的 n, e, p 等粒子表示
            items = re.findall(r'(\d+)?(?:\^|\{)(\d+)(?:\}|\s)?(?:_|\{)(\d+)(?:\}|\s)?', text)
            total_a = 0
            total_z = 0
            for coeff, a, z in items:
                c = int(coeff) if coeff else 1
                total_a += c * int(a)
                total_z += c * int(z)
            return total_a, total_z

        left_a, left_z = get_sums(parts[0])
        right_a, right_z = get_sums(parts[1])

        # 如果提取不到有效数值，跳过当前行
        if left_a == 0 and right_a == 0:
            continue

        # 检查守恒性
        if left_a != right_a or left_z != right_z:
            return {
                'result': 'fail',
                'message': f'核反应不守恒：左侧(A={left_a}, Z={left_z}) != 右侧(A={right_a}, Z={right_z})',
                'evidence': eq.strip()
            }

    # 如果存在方程且都通过了校验（或未提取到可校验数值则保守返回）
    if any(get_sums(re.split(r'[\-\u2192=]', e)[0])[0] > 0 for e in equations if len(re.split(r'[\-\u2192=]', e)) == 2):
        return {'result': 'pass', 'message': '核反应方程式质量数与电荷数守恒', 'evidence': equations[0].strip()}

    return {'result': 'inconclusive', 'message': '未能提取到完整的核反应数值进行校验', 'evidence': ''}

# rule_id=norm_ce6db06a1aa0fce9 | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
# rule_id=norm_ce6db06a1aa0fce9 | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
def check_norm_ce6db06a1aa0fce9_e0765312c217(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及固定靶核反应的最小动能（阈能）场景
    trigger_keywords = ['minimum kinetic energy', 'incident particle', 'target nucleus at rest', 'threshold energy', '阈能', '最小动能']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到固定靶核反应阈能相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否仅计算了 Q 值（质能差）而忽略了动量守恒带来的修正项 (1 + m1/m2)
    pred = prediction.lower()
    # 检查是否提到了质量比或公式结构 K = |Q| * (1 + m1/m2)
    # 匹配模式：(1 + m/M), (m1 + m2)/m2, (M+m)/M 等
    mass_ratio_pattern = r'(\d+\s*\+\s*\d+)\/\d+|1\s*\+\s*m\w*\/m\w*|\(m\w*\s*\+\s*m\w*\)\/m\w*'
    has_mass_correction = re.search(mass_ratio_pattern, pred) or 'ratio' in pred or 'conservation of momentum' in pred

    # 如果只计算了 Q = delta_m * c^2 或直接把 Q 当作最小动能，则判定为逻辑错误
    if 'q =' in pred or 'energy release' in pred:
        if not has_mass_correction and ('threshold' in pred or 'minimum' in pred):
            return {
                'result': 'fail',
                'message': '计算阈能时未考虑动量守恒修正项 (1 + m_incident / m_target)，仅计算了Q值。',
                'evidence': prediction[-200:]
            }

    # Step 3: 符号与公式结构校验
    # 检查 canonical 公式 K_th = |Q| * (m1 + m2) / m2 的变体
    canonical_pattern = r'k(_?th)?.*=.*q.*\(.*1\s*\+\s*m.*\/m.*\)'
    if re.search(canonical_pattern, pred.replace(' ', '')):
        return {'result': 'pass', 'message': '正确使用了阈能修正公式', 'evidence': prediction[-150:]}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了阈能公式', 'evidence': ''}

# rule_id=norm_e7aba523aa760a91 | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
# rule_id=norm_e7aba523aa760a91 | domain=Modern Physics | topic=Nuclear Reactions (Fission, Fusion)
def check_norm_e7aba523aa760a91_eec4997b5c56(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及中性粒子（如中子）与不同靶核的弹性碰撞及动能传递
    trigger_keywords = ['碰撞', '动能', '靶核', '静止', '质量', '反冲']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到弹性碰撞能量传递场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 是否利用能量传递比公式 E_k = [4m1*m2/(m1+m2)^2] * E_0 或其比值形式
    # 核心逻辑是两个不同靶核的能量比值：E1/E2 = [m2*(m1+m3)^2] / [m3*(m1+m2)^2]
    pred = prediction.lower()
    # 检查是否提到了能量传递公式的结构 (4m1m2/(m1+m2)^2)
    formula_pattern = r'4.*m.*m.*/.*\(m.*\+.*m.*\)\^2'
    ratio_pattern = r'e1/e2|e_1/e_2|\\frac{e_1}{e_2}'

    has_formula = re.search(formula_pattern, pred) or '4m' in pred
    has_ratio = re.search(ratio_pattern, pred) or ('/' in pred and 'm' in pred)

    if not (has_formula or has_ratio):
        return {'result': 'fail', 'message': '未发现能量传递比公式或比例建模逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号与计算校验 — 检查是否尝试联立求解未知质量 m1
    # 寻找质量求解的痕迹，如 m=1 或 m=1.008 等常见中子质量结果，或求解方程的过程
    solve_keywords = ['解得', '求得', 'm=', 'm1=', '质量为']
    if any(kw in prediction for kw in solve_keywords):
        # 如果公式结构和求解动作都有，判定为 pass
        return {'result': 'pass', 'message': '逻辑完整：应用了能量传递比公式并进行了质量求解', 'evidence': prediction[-150:]}

    return {'result': 'inconclusive', 'message': '检测到相关公式但推导过程不完整', 'evidence': prediction[:150]}

# rule_id=norm_13b320f07e54ca6b | domain=Modern Physics | topic=Particle Physics (Quarks, Leptons, Bosons)
# rule_id=norm_13b320f07e54ca6b | domain=Modern Physics | topic=Particle Physics (Quarks, Leptons, Bosons)
def check_norm_13b320f07e54ca6b_8a8aa238104b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及切伦科夫辐射、动量展宽或环状图像宽度
    trigger_keywords = ['cherenkov', 'cherenkov angle', 'momentum spread', 'ring image', 'ring width', '切伦科夫', '动量展宽', '环状图像']
    content_to_check = (question + context).lower()
    if not any(kw in content_to_check for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到切伦科夫辐射角与动量展宽的相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别是否错误使用了小角近似 θ ≈ Δp/p
    pred_lower = prediction.lower()
    # 如果直接出现 theta 约等于 delta p / p 的简单线性关系，通常是错误的简化
    if re.search(r'theta\s*≈\s*d?p/p', pred_lower) or re.search(r'θ\s*≈\s*Δp/p', pred_lower):
        return {'result': 'fail', 'message': '错误使用了小角近似 θ ≈ Δp/p，未考虑完整的微分关联', 'evidence': prediction[:200]}

    # Step 3: 公式校验 — 检查是否基于 cos θ = 1/(nβ) 及其对 p 的导数形式
    # 核心要素：n, beta (p/E), m, p, sin theta
    required_patterns = [
        r'cos\s*theta\s*=\s*1/\(n\s*beta\)',
        r'beta\s*=\s*p/e',
        r'dtheta/dp',
        r'm\^2/e\^2'
    ]

    # 检查 canonical 形式中的关键导数结构：dθ/dp ∝ (m^2/E^2) / (p^2 ... sin θ)
    found_derivative = re.search(r'dtheta/dp|dθ/dp', pred_lower)
    found_full_logic = re.search(r'm\^2/e\^2', pred_lower) and re.search(r'sin\s*theta|sin\s*θ', pred_lower)

    if found_derivative and found_full_logic:
        return {'result': 'pass', 'message': '正确使用了基于 cos θ = 1/(nβ) 的微分关联推导', 'evidence': prediction[:200]}

    # 如果提到了微分但公式不全，或者完全没提微分过程
    if 'dtheta' in pred_lower or 'dθ' in pred_lower:
        return {'result': 'inconclusive', 'message': '检测到微分尝试但公式结构不完整', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '未发现明确的微分关联推导过程', 'evidence': ''}

# rule_id=norm_aae441670b69befd | domain=Modern Physics | topic=Particle Physics (Quarks, Leptons, Bosons)
# rule_id=norm_aae441670b69befd | domain=Modern Physics | topic=Particle Physics (Quarks, Leptons, Bosons)
def check_norm_aae441670b69befd_f5258dc2c0d8(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否同时出现不同质量粒子（如π和K）且提到动量相同
    q_c = (question + context).lower()
    particles = ['pi', 'π', 'kaon', ' k ', 'k+', 'k-', 'k0', 'muon', 'μ']
    found_particles = [p for p in particles if p in q_c]
    has_momentum = any(kw in q_c for kw in ['动量', 'momentum', ' p ', 'p='])

    if len(found_particles) < 2 or not has_momentum:
        return {'result': 'inconclusive', 'message': '未检测到多种粒子或动量一致的场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 检查 prediction 是否错误地认为速度、动能或辐射角一致
    pred = prediction.lower()
    # 错误特征：认为 v1=v2, E1=E2, 或忽略质量差异直接抵消
    error_patterns = [
        r'速度(相同|相等|一致)', r'speed (is|are) (the )?same',
        r'动能(相同|相等|一致)', r'kinetic energy (is|are) (the )?same',
        r'v_1\s*=\s*v_2', r'e_k1\s*=\s*e_k2'
    ]

    for pattern in error_patterns:
        if re.search(pattern, pred):
            return {
                'result': 'fail',
                'message': '错误地将不同质量粒子的速度或动能视为一致，未考虑质量 m 的差异',
                'evidence': re.search(pattern, pred).group()
            }

    # Step 3: 符号校验 — 检查是否代入了质量符号 m_k, m_pi 或进行了质量关联计算
    # 动量 p = mv 或 p = sqrt(2mEk)，若动量相同，则 v 或 Ek 必须与 m 相关
    mass_symbols = ['m_k', 'm_pi', 'm_1', 'm_2', '质量']
    has_mass_logic = any(sym in pred for sym in mass_symbols)

    if has_mass_logic and ('/' in pred or 'sqrt' in pred or '!=' in pred):
        return {'result': 'pass', 'message': '正确区分了不同质量粒子的物理量差异', 'evidence': '检测到质量相关计算逻辑'}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了质量差异', 'evidence': ''}

# rule_id=norm_147e8684f9af2fc9 | domain=Modern Physics | topic=Applications of Quantum Mechanics (Semiconductors, Lasers)
# rule_id=norm_147e8684f9af2fc9 | domain=Modern Physics | topic=Applications of Quantum Mechanics (Semiconductors, Lasers)
def check_norm_147e8684f9af2fc9_3463653a5fd4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及耗散力（dissipative force, viscous drag, frictional force）且力与速度成正比
    trigger_keywords = ['dissipative force', 'viscous drag', 'frictional force', 'damping', '阻尼', '耗散力', '粘滞阻力']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords)

    # 检查是否提到力与速度成正比 (F = -kv)
    proportional_hint = re.search(r'(proportional to (the )?velocity|f\s*=\s*-?k\s*v|力与速度成正比)', combined_text)

    if not (is_triggered or proportional_hint):
        return {'result': 'inconclusive', 'message': '未检测到耗散力或粘滞阻力相关场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证预测中是否包含一阶线性微分方程的指数衰减解 v(t) = v0 * exp(-kt/m)
    # 匹配指数衰减形式，重点关注 exp(-...t...) 或 e^{-...t...}
    pred_text = prediction.lower()
    # 匹配常见的指数衰减模式，如 e^(-kt/m), exp(-gamma*t/m), v0*e^(-...)
    decay_pattern = re.search(r'(exp\s*\(\s*-?[\w\\/\s]+\s*t|e\^\{\s*-?[\w\\/\s]+\s*t|e\^\(\s*-?[\w\\/\s]+\s*t)', pred_text)

    if not decay_pattern:
        return {
            'result': 'fail',
            'message': '模型演化不符合指数衰减规律，未发现 v(t) = v0 * exp(-kt/m) 形式的解',
            'evidence': prediction[:200]
        }

    # Step 3: 符号校验 — 检查是否包含必要的物理量符号 m, t, v_0
    required_symbols = ['m', 't', 'v']
    missing_symbols = [sym for sym in required_symbols if sym not in pred_text]

    if not missing_symbols:
        return {
            'result': 'pass',
            'message': '成功验证耗散力模型下的速度指数衰减公式',
            'evidence': decay_pattern.group(0)
        }

    return {'result': 'inconclusive', 'message': '检测到指数形式但物理符号不完整', 'evidence': prediction[:150]}

