# rule_id=norm_cbdbe3c10cb841c4 | domain=Modern Physics | topic=Applications of Quantum Mechanics (Semiconductors, Lasers)
def check_norm_cbdbe3c10cb841c4_a941b2f68bb1(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
