    trigger_keywords = ['conduction electron', '传导电子', '金属', 'metal', 'density of states', '态密度']
    low_energy_keywords = ['low energy', '低能', 'fermi surface', '费米面', 'excitation', '激发']

    q_c = (question + context).lower()
    if not any(k in q_c for k in trigger_keywords) or not any(k in q_c for k in low_energy_keywords):
        return {'result': 'inconclusive', 'message': '未检测到金属传导电子低能激发的物理场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 识别预测中关于幂次 n 的描述
    # 核心逻辑：在费米面附近的激发能 ε = E - Ef，态密度 ρ(ε) ∝ ε^n，其中 n 应为 0 (常数)
    pred = prediction.lower()

    # 寻找关于指数 n 的表达，如 n=0, n=1, n=1/2 等
    power_match = re.search(r'n\s*[:=]\s*([0-9\./]+)', pred)
    rho_prop_match = re.search(r'ρ\s*∝\s*ε\^?([0-9\./]+)', pred)

    # Step 3: 判定逻辑
    # 如果明确提到了非0的幂次（如 n=1/2 是 3D 自由电子绝对能量的幂次，而非费米面附近的激发幂次）
    if re.search(r'n\s*=\s*(1/2|0\.5|1)', pred) or re.search(r'ε\^\s*(1/2|0\.5|1)', pred):
        return {
            'result': 'fail',
            'message': '错误地使用了绝对能量的态密度幂次。在费米面附近的低能激发，态密度应近似为常数 (n=0)。',
            'evidence': re.search(r'.{0,30}(n\s*=\s*[0-9\./]+|ε\^\s*[0-9\./]+).{0,30}', pred).group(0) if re.search(r'(n\s*=\s*[0-9\./]+|ε\^\s*[0-9\./]+)', pred) else prediction[:100]
        }

    if 'n=0' in pred.replace(' ', '') or 'constant' in pred or '常数' in pred or 'ε^0' in pred:
        return {'result': 'pass', 'message': '正确识别费米面附近态密度为常数 (n=0)', 'evidence': prediction[:120]}

    return {'result': 'inconclusive', 'message': '未能明确提取到态密度幂次 n 的具体数值判定', 'evidence': ''}

