    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到慢滚近似参数转换场景', 'evidence': ''}

    # Step 2: 检查逻辑 — 验证是否包含势能导数形式的转换逻辑
    # 重点检查 ε ∝ (V'/V)^2 和 η ∝ V''/V 的结构
    pred = prediction.lower()

    # 检查是否提到了势能 V 及其导数 V' 或 V''
    if not re.search(r"v[''’]", pred) and 'potential' not in pred:
        return {'result': 'fail', 'message': '未发现势能导数形式的转换逻辑', 'evidence': prediction[:200]}

    # Step 3: 符号与公式结构校验
    # 检查 ε 的公式结构：通常包含 (V'/V)^2 或类似的平方项
    epsilon_pattern = r"(v[''’]/v).*\^2|\(v[''’]/v\)\*\*2|v[''’]\^2/v\^2"
    # 检查 η 的公式结构：通常包含 V''/V
    eta_pattern = r"v[''’]{2}/v"

    has_epsilon = re.search(epsilon_pattern, pred)
    has_eta = re.search(eta_pattern, pred)

    # 如果两者都缺失，判定为建模错误
    if not has_epsilon and not has_eta:
        return {'result': 'fail', 'message': '慢滚参数转换公式结构错误，未体现ε正比于(V\'/V)²或η正比于V\'\'/V', 'evidence': prediction[:300]}

    # 检查是否包含 Mpl (普朗克质量) 这一关键常数
    if 'mpl' not in pred and 'planck' not in pred:
        return {'result': 'inconclusive', 'message': '公式中缺少普朗克质量单位项，需人工确认单位制', 'evidence': prediction[:200]}

    return {'result': 'pass', 'message': '慢滚参数转换逻辑符合势能导数定义', 'evidence': prediction[:300]}

