# rule_id=norm_0d0333e8b82f2447 | domain=Mechanics | topic=Kinematics in 1D/2D/3D
def check_norm_0d0333e8b82f2447_57f14570f410(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及线绳绕圆柱/圆盘解绕且一端拉动的情景
    trigger_keywords = ['绕', '圆柱', '圆盘', '解绕', 'unwinding', 'cylinder', 'spool']
    if not any(k in (question + context) for k in trigger_keywords) or '绳' not in (question + context):
        return {'result': 'inconclusive', 'message': '未检测到线绳绕柱约束场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查逻辑错误 — 是否忽略了速度投影定理或切点转动项
    # 错误模式1：直接令质点速度等于拉绳速度，忽略了角度或转动分量
    if re.search(r'v_p\s*=\s*u(?!\s*[\+\-])', pred) or re.search(r'v\s*=\s*v_0(?!\s*[\+\-])', pred):
        if 'omega' not in pred and 'w' not in pred and 'dot' not in pred:
            return {'result': 'fail', 'message': '建模错误：直接等同了质点速度与拉绳速度，未考虑约束分解或转动项', 'evidence': prediction[:200]}

    # Step 3: 检查缺失 — 是否缺少关键物理量 L(t) 或 omega (w)
    required_symbols = ['L', 'u', 'v_p']
    missing_symbols = [s for s in required_symbols if s not in prediction]
    if len(missing_symbols) >= 2:
        return {'result': 'fail', 'message': '推理缺失：未定义或未使用必要的运动学物理量 (L, u, v_p)', 'evidence': f'缺失符号: {missing_symbols}'}

    # Step 4: 检查公式结构 — 验证是否包含速度合成的 canonical 形式 (v_p = u + omega * L)
    # 匹配类似 v = u + w*L 或 v_p = u + \omega L 的结构
    canonical_pattern = r'v_?p?\s*=\s*u\s*[\+\-]\s*(\omega|w)\s*\*?\s*L'
    if not re.search(canonical_pattern, pred):
        # 如果没有找到标准合成公式，且没有体现速度投影(cos/sin)，则判定为分析不完整
        if 'cos' not in pred and 'sin' not in pred:
            return {'result': 'fail', 'message': '建模错误：未体现速度投影定理或线绳绕柱的额外速度项公式', 'evidence': prediction[:200]}

    # Step 5: 只有在明确排除上述错误且公式匹配时才 pass
    if re.search(canonical_pattern, pred) and ('projection' in pred or '投影' in pred or '分量' in pred):
        return {'result': 'pass', 'message': '已正确应用速度投影定理并考虑了转动约束项', 'evidence': re.search(canonical_pattern, pred).group()}

    return {'result': 'inconclusive', 'message': '证据不足，无法确定是否完全符合约束逻辑', 'evidence': ''}

# rule_id=norm_1283f206e4eca456 | domain=Mechanics | topic=Projectile Motion
def check_norm_1283f206e4eca456_af7b581994c7(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')
    full_text = (question + context).lower()
    pred = prediction.lower()

    # Step 1: 触发条件 — 检查是否涉及平抛/斜抛运动落点坐标 (L, H) 及最小初速度 v_min 的求解
    trigger_keywords = ['最小初速度', '最小发射速度', 'minimum velocity', 'minimum speed', 'v_min', '最小速度']
    coord_keywords = ['落点', '坐标', '水平距离', '高度', 'l', 'h', 'distance', 'height']

    is_triggered = any(k in full_text for k in trigger_keywords) and any(k in full_text for k in coord_keywords)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到平抛/斜抛运动最小初速度求解场景', 'evidence': ''}

    # Step 2: 检查逻辑错误 — 错误地直接套用简单水平平抛公式
    # 最小速度通常对应斜抛（角度优化），若 prediction 仅考虑水平发射 v = L*sqrt(g/2H)，则属于建模错误
    # 匹配模式：v = L * sqrt(g / 2H) 或类似变体
    horizontal_pattern = r'v\s*=\s*l\s*\*?\s*sqrt\(g\s*/\s*\(2\*?h\)\)'
    if re.search(horizontal_pattern, pred) or ('水平抛出' in prediction and '最小' in prediction):
        # 如果没有提到角度优化或判别式，判定为简化错误
        if 'tan' not in pred and 'cos' not in pred and '判别式' not in prediction and 'delta' not in pred:
            return {'result': 'fail', 'message': '错误地假设为水平抛出，未考虑角度优化导致的最小速度（应使用包络线或轨迹方程判别式）', 'evidence': '检测到简化平抛公式，未见角度变量或判别式逻辑'}

    # Step 3: 检查推理缺失 — 是否缺少轨迹方程判别式法或安全包络线公式
    # 核心公式特征：v^2 = g(H + sqrt(L^2+H^2)) 或 判别式 Delta >= 0
    # 注意：H 有时指高度差，公式形式可能为 v^2/g = y + sqrt(x^2+y^2)
    has_envelope = re.search(r'g\s*\*?\s*\(?h\s*\+\s*sqrt\(l\^2\s*\+\s*h\^2\)\)?', pred) or \
                   re.search(r'v\^2\s*=\s*g', pred) and 'sqrt' in pred and ('l^2' in pred or 'h^2' in pred)
    has_discriminant = ('tan' in pred or 'theta' in pred) and ('判别式' in prediction or 'delta' in pred or 'b^2-4ac' in pred or '>= 0' in pred)

    if not (has_envelope or has_discriminant):
        return {'result': 'fail', 'message': '推理过程中缺失轨迹方程判别式分析或安全包络线公式，无法证明所求为最小速度', 'evidence': prediction[:200]}

    # Step 4: 符号校验 — 检查关键物理量是否被引用
    required_symbols = ['g', 'l', 'h']
    missing_symbols = [s.upper() for s in required_symbols if s not in pred]
    if missing_symbols:
        return {'result': 'fail', 'message': f'计算最小速度时缺少必要物理量符号: {missing_symbols}', 'evidence': prediction[:100]}

    # Step 5: 验证通过 — 必须先排除上述 fail 分支
    # 且必须包含具体的最小速度公式结构
    if (has_envelope or has_discriminant) and ('sqrt' in pred or 'v^2' in pred or 'v_min' in pred):
        return {'result': 'pass', 'message': '已正确应用轨迹方程判别式或包络线方程求解最小初速度', 'evidence': '检测到包络线逻辑或判别式推导过程'}

    return {'result': 'inconclusive', 'message': '证据不足，无法确定是否正确应用最小速度判定规则', 'evidence': ''}

# rule_id=norm_4ac5e3befd6e002d | domain=Mechanics | topic=Projectile Motion
def check_norm_4ac5e3befd6e002d_792991a7b5f4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及抛体运动且给定目标点 (L, h) 求最小初速度/能量
    trigger_keywords = ['最小初速度', '最小速度', '最小能量', 'minimum velocity', 'minimum speed', 'minimum energy']
    target_point_pattern = r'(点|坐标|位置|distance|height).*([Lh]|\d+)'

    if not any(k in (question + context).lower() for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到求解最小初速度/能量的场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查逻辑错误 — 是否错误地使用了简单的平抛公式或忽略了包络线/判别式逻辑
    # 如果直接用 v = L * sqrt(g/2h) 这种平抛公式处理带高度差的斜抛极值，通常是错误的
    if re.search(r'v\s*=\s*l\s*\*\s*sqrt\(g\s*/\s*2h\)', pred) or 'v=l*sqrt(g/2h)' in pred.replace(' ', ''):
        return {'result': 'fail', 'message': '错误地使用了平抛运动公式处理一般抛体极值问题', 'evidence': '检测到平抛简化公式的使用'}

    # Step 3: 检查核心公式缺失或建模错误
    # 检查是否提到了判别式 (discriminant/delta) 或 安全抛物线 (safety parabola/envelope)
    # 或者检查是否出现了核心公式 v^2 = g(h + sqrt(h^2 + L^2))
    has_discriminant = any(term in pred for term in ['判别式', 'discriminant', 'delta', 'd=0', 'd = 0', 'b^2-4ac'])
    has_envelope = any(term in pred for term in ['包络线', 'envelope', 'safety parabola'])

    # 匹配核心公式 v^2 = g(h + sqrt(h^2 + L^2)) 的变体
    core_formula_pattern = r'v(_?min)?\^2.*g.*\(.*h.*sqrt\(.*h\^2.*l\^2'
    has_core_formula = re.search(core_formula_pattern, pred.replace(' ', ''))

    if not (has_discriminant or has_envelope or has_core_formula):
        return {'result': 'fail', 'message': '未应用轨迹方程判别式或安全抛物线方程进行极值校验', 'evidence': prediction[:200]}

    # Step 4: 验证公式正确性并排除错误后 pass
    if has_core_formula or (has_discriminant and 'sqrt' in pred):
        # 进一步检查是否在计算中遗漏了 g 或 h
        if 'g' in pred and ('h' in pred or 'y' in pred):
            return {'result': 'pass', 'message': '正确应用了抛体运动包络线或判别式逻辑求解极值', 'evidence': '检测到符合安全抛物线逻辑的推导'}

    return {'result': 'inconclusive', 'message': '无法确定推导过程是否完全符合包络线校验要求', 'evidence': ''}

# rule_id=norm_ba4ddaa7a8693e27 | domain=Mechanics | topic=Projectile Motion
def check_norm_ba4ddaa7a8693e27_acaea628fa15(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 题目是否涉及垂直上升高度或射高
    trigger_keywords = ['垂直上升', '射高', '最大高度', '上升高度', 'height', 'vertical distance']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到垂直高度相关触发词', 'evidence': ''}

    pred = prediction.lower()

    # Step 2: 检查逻辑错误 — 混淆参考平面（错误模式：直接使用绝对高度 H 而非位移 Delta h）
    # 模式 A: 显式使用了海平面高度或总高度符号进行速度计算
    if re.search(r'v\s*=\s*sqrt\(2\s*\*?\s*g\s*\*?\s*h_(total|sea|absolute)\)', pred):
        return {'result': 'fail', 'message': '初速度计算错误：使用了绝对高度或总高度，而非相对于抛出点的垂直位移', 'evidence': prediction}

    # 模式 B: 在存在多个高度参考点的情况下，直接套用 v=sqrt(2gh) 而未定义 h 为高度差
    has_v_formula = re.search(r'v(_0)?\s*=\s*sqrt\(2\s*\*?\s*g\s*\*?\s*h\)', pred)
    has_delta_h_definition = re.search(r'h\s*=\s*(h2|h_max|h_top)\s*-\s*(h1|h_0|h_start)', pred)
    has_delta_symbol = re.search(r'delta[\s_]*h|\\delta\s*h|\u0394h', pred)

    if has_v_formula and not (has_delta_h_definition or has_delta_symbol):
        # 如果题目背景明确提到了起始高度（如从某高度抛出），但公式直接用 h 且未定义 h 为差值
        if re.search(r'从.*?高度|at\s+an\s+altitude|from\s+a\s+height', question + context):
            return {'result': 'fail', 'message': '逻辑缺失：在有初始高度背景下，未明确 h 是相对于抛出点的位移 (h_max - h_0)', 'evidence': prediction}

    # Step 3: 验证正确处理（Refute）
    # 必须同时满足公式正确且明确了高度差逻辑
    if has_v_formula and (has_delta_h_definition or has_delta_symbol):
        # 进一步检查是否误用了加法（常见错误）
        if re.search(r'h\s*=\s*(h2|h_max)\s*\+\s*(h1|h_0)', pred):
             return {'result': 'fail', 'message': '计算错误：高度差被错误计算为高度之和', 'evidence': prediction}
        return {'result': 'pass', 'message': '正确使用了相对于抛出点的垂直位移计算初速度', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '无法确定是否正确处理了高度参考点或公式不完整', 'evidence': ''}

# rule_id=norm_93d0d22e61fa28c4 | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_norm_93d0d22e61fa28c4_ea0dc5fdef3b(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 质点在曲面（如球面、圆锥面）上沿等高线/纬线运动
    trigger_keywords = ['曲面', '球面', '圆锥', '等高线', '纬线', '水平圆周', 'surface', 'sphere', 'cone']
    if not any(k in (question + context) for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到约束面圆周运动场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查逻辑错误 — 比较向心力与所需向心力时的逻辑矛盾
    # 错误模式1：合力不足却判定向内偏，或合力过剩却判定向外偏
    if ('不足' in pred or '小于' in pred or 'less than' in pred) and ('向内' in pred or 'inner' in pred or '半径减小' in pred):
        return {'result': 'fail', 'message': '向心力不足时轨迹应向外偏，预测逻辑矛盾', 'evidence': prediction}

    if ('过剩' in pred or '大于' in pred or 'greater than' in pred) and ('向外' in pred or 'outer' in pred or '半径增大' in pred):
        return {'result': 'fail', 'message': '向心力过剩时轨迹应向内偏，预测逻辑矛盾', 'evidence': prediction}

    # Step 3: 检查缺失 — 是否忽略了向心力公式的必要组成部分 (R, theta, v)
    # 检查 symbolic_hint 中的关键符号是否存在于推理过程中
    required_patterns = [r'v\^2', r'R', r'sin', r'cos', r'theta', r'\\theta']
    missing_count = 0
    for pattern in required_patterns:
        if not re.search(pattern, prediction, re.IGNORECASE):
            missing_count += 1

    if missing_count > 3: # 缺失过多关键物理量，判定为分析不完整
        return {'result': 'fail', 'message': '未建立有效的向心力平衡方程或缺少关键物理量(R, v, theta)', 'evidence': prediction}

    # Step 4: 验证正确逻辑（Refute）
    # 必须明确提到向心力比较，且结论正确
    if ('mv^2' in pred or 'v^2/r' in pred) and ('向心力' in pred or 'centripetal' in pred):
        if ('不足' in pred and '向外' in pred) or ('大于' in pred and '向内' in pred):
            return {'result': 'pass', 'message': '正确分析了向心力盈亏与轨迹偏移的关系', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '无法确定预测是否包含该逻辑错误', 'evidence': ''}

# rule_id=norm_f393a63d730cd7b6 | domain=Mechanics | topic=Friction and Contact Forces
def check_norm_f393a63d730cd7b6_e2d5939c242e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及“两质点由刚性杆连接”且受力场景
    trigger_keywords = ['刚性杆', '轻杆', 'rigid rod', 'connected by a rod', '杆连接']
    force_keywords = ['摩擦', 'friction', '外力', 'force', '推力', '拉力']

    text_to_check = (question + context).lower()
    is_triggered = any(k in text_to_check for k in trigger_keywords) and any(k in text_to_check for k in force_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到刚性杆连接及受力场景', 'evidence': ''}

    pred = prediction.lower()

    # Step 2: 检查错误模式 — 是否直接对单个质点应用牛二律而忽略了杆的内力（张力T/压力N）
    # 错误模式：只列出 F=ma 而没有 T 或 N 参与，或者没有提到加速度之间的约束关系
    # 匹配 F=ma 但缺少内力符号 T 或 N (假设杆内力常用符号)
    if re.search(r'f\s*=\s*m[12]?a', pred) and not re.search(r'[tn]\s*[+-]|tension|internal force|内力|张力|压力', pred):
        return {
            'result': 'fail',
            'message': '模型错误：直接对单个质点应用牛二律，忽略了刚性杆的内力（张力/压力）。',
            'evidence': '预测中仅见外力公式，未见内力项参与受力分析。'
        }

    # Step 3: 检查缺失 — 是否缺少约束方程 (速度/加速度在杆方向的分量相等)
    # 约束方程特征：(v1-v2).r = 0 或 a1_n = a2_n 或 长度 L 的导数为 0
    constraint_patterns = [
        r'v.*cos', r'a.*cos', r'velocity.*projection', r'acceleration.*projection',
        r'v_1.*v_2', r'a_1.*a_2', r'约束方程', r'constraint',
        r'dot\(v', r'diff.*L', r'l\^2'
    ]
    has_constraint = any(re.search(p, pred) for p in constraint_patterns)

    if not has_constraint:
        return {
            'result': 'fail',
            'message': '逻辑缺失：未建立刚性约束方程（如速度或加速度在杆方向的投影关系）。',
            'evidence': '预测中未发现描述质点间运动关联的约束表达式。'
        }

    # Step 4: 验证正确性 (Refute) — 必须同时具备内力分析和约束方程
    # 检查 symbolic_hint 中的 canonical 形式或其变体
    if has_constraint and re.search(r'[tn]\s*[+-]', pred):
        # 进一步检查是否提到了加速度 a 或 速度 v 与 长度 L 的关系
        if 'a' in pred or 'v' in pred or 'l' in pred:
            return {
                'result': 'pass',
                'message': '已正确处理刚性约束系统，包含了内力分析与运动约束方程。',
                'evidence': '预测中包含了受力平衡/动力学方程及对应的几何约束。'
            }

    return {'result': 'inconclusive', 'message': '无法确定是否完整考虑了刚性约束动力学解耦', 'evidence': ''}

# rule_id=norm_d3b8502f39b2e0e6 | domain=Mechanics | topic=Power and Energy Dissipation
def check_norm_d3b8502f39b2e0e6_784e42aba394(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及直升机悬停、螺旋桨推力与功率的几何缩放（Scale Replica）
    trigger_keywords = ['helicopter', 'hover', 'propeller', 'thrust', 'scale', 'replica', '直升机', '悬停', '螺旋桨', '推力', '缩放', '比例']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到流体推进或几何缩放场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查逻辑错误 — 检查是否错误地使用了线性缩放或其他错误的幂次律（如 P ∝ L^2 或 P ∝ L^3）
    # 动量理论要求 P ∝ L^3.5 (即 L^(7/2))
    wrong_scaling_patterns = [
        r'p\s*\/\s*p\s*=\s*\(\s*l\s*\/\s*l\s*\)\s*\^\s*2',
        r'p\s*\/\s*p\s*=\s*\(\s*l\s*\/\s*l\s*\)\s*\^\s*3',
        r'power\s*proportional\s*to\s*l\^2',
        r'power\s*proportional\s*to\s*l\^3',
        r'功率与长度的平方成正比',
        r'功率与长度的立方成正比'
    ]
    for pattern in wrong_scaling_patterns:
        if re.search(pattern, pred):
            return {'result': 'fail', 'message': '使用了错误的功率缩放幂次（应为3.5次方）', 'evidence': re.search(pattern, pred).group()}

    # Step 3: 检查缺失 — 检查是否缺少动量理论的关键推导步骤或最终的 3.5 次方关系
    # 必须包含 L^3.5, L^3.5, 7/2, 或 3.5 次方的逻辑描述
    correct_scaling_indicators = ['3.5', '7/2', '3.5次方', 'l**3.5', 'l^3.5', 'l^{3.5}']
    has_correct_scaling = any(ind in pred for ind in correct_scaling_indicators)

    # 检查推导链条：F ∝ L^3 且 P = Fv 且 v ∝ sqrt(F/A)
    has_derivation = ('f' in pred and 'v' in pred and 'a' in pred) or ('thrust' in pred and 'velocity' in pred)

    if not has_correct_scaling:
        return {'result': 'fail', 'message': '未体现功率随长度3.5次方缩放的动量理论关系', 'evidence': prediction[:200]}

    # Step 4: 验证通过 — 只有在明确排除错误且包含正确缩放律时才返回 pass
    if has_correct_scaling and ('p' in pred or 'power' in pred):
        # 进一步确认是否提到了推力 F ∝ L^3 (由于质量 m ∝ L^3)
        if '3' in pred or 'cubic' in pred:
            return {'result': 'pass', 'message': '正确应用了流体推进功率缩放律 (P ∝ L^3.5)', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '证据不足以判定缩放律的准确性', 'evidence': ''}

# rule_id=norm_0c071c022d067e1c | domain=Mechanics | topic=Linear Momentum and Collisions
def check_norm_0c071c022d067e1c_7447cd7eee87(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及重力场中的动量-时间关系 (p-t 图像或 dp/dt)
    trigger_keywords = ['动量', '时间', '图像', '重力', '质量', 'g']
    combined_text = (question + context).lower()
    if not (all(k in combined_text for k in ['动量', '时间']) or 'p-t' in combined_text):
        return {'result': 'inconclusive', 'message': '未检测到动量-时间图像或相关物理场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查逻辑错误 — 验证是否错误地计算了斜率或忽略了重力与动量变化率的关系
    # 错误模式1：动量变化率不等于 Mg (例如写成 1/2 Mg 或 Mg^2)
    if re.search(r'dp/dt\s*=\s*1/2\s*m\s*g', pred) or re.search(r'\Delta p/\Delta t\s*=\s*m\s*g/2', pred):
        return {'result': 'fail', 'message': '动量变化率公式错误，未遵循 dp/dt = Mg', 'evidence': prediction}

    # 错误模式2：在重力场自由下落或匀变速运动中，斜率计算与 Mg 矛盾
    # 寻找类似 |dp/dt| 或 Delta p / Delta t 的表达，并检查其是否与 M*g 建立等式
    has_slope_logic = re.search(r'(dp/dt|\Delta p/\Delta t|斜率|slope)', pred)
    has_mg_logic = re.search(r'(mg|m\s*\*\s*g)', pred)

    if has_slope_logic and not has_mg_logic:
        return {'result': 'fail', 'message': '分析动量图像斜率时未考虑重力(Mg)的作用', 'evidence': prediction}

    # Step 3: 检查推理缺失 — 是否未利用斜率反推质量或验证 g
    # 如果题目要求求质量 M，但预测中没有体现 M = (dp/dt) / g 的逻辑
    if '质量' in question and 'm =' not in pred and 'm=' not in pred:
        if not re.search(r'm\s*=\s*\Delta p\s*/\s*\(\s*g\s*\*\s*\Delta t\s*\)', pred):
             return {'result': 'fail', 'message': '未利用动量变化率与重力的关系反推质量', 'evidence': prediction}

    # Step 4: 验证正确性 (Refute)
    # 匹配标准公式 |dp/dt| = Mg 或 Delta p = Mg * Delta t
    correct_pattern = r'(\Delta p|dp)\s*=\s*m\s*g\s*(\Delta t|dt)'
    if re.search(correct_pattern, pred) or re.search(r'(dp/dt|\Delta p/\Delta t)\s*=\s*m\s*g', pred):
        return {'result': 'pass', 'message': '正确应用了重力场动量变化率恒定律', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了动量变化率定律', 'evidence': ''}

# rule_id=norm_2476a6043796aff9 | domain=Mechanics | topic=Linear Momentum and Collisions
def check_norm_2476a6043796aff9_284855d7180e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及两种不同质量靶核（如氢、氮）被同一粒子碰撞的最大速度
    # 典型场景：中子质量测定，已知 H 和 N 的反冲速度
    trigger_keywords = ['最大速度', '碰撞', '靶核', '反冲', '速度增量']
    if not any(k in (question + context) for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到弹性碰撞速度增量场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查逻辑错误 — 是否错误地使用了动量守恒而忽略了能量守恒（即没有使用 2m1/(m1+m2) 系数）
    # 如果只用了 m1v1 = m2v2 这种简单的动量等式，通常是错误的
    if 'm1v1' in pred and '2m1' not in pred and '2*' not in pred:
        return {'result': 'fail', 'message': '未正确应用弹性碰撞最大速度公式，可能忽略了能量守恒项', 'evidence': prediction[:200]}

    # Step 3: 检查建模缺失 — 是否建立了消去初速度 v0 的方程组
    # 核心逻辑是 v1/v2 = (m_n + m2) / (m_n + m1) 的变形
    # 必须包含两个质量（如 m_H, m_N）和两个速度（v_H, v_N）的关联
    required_patterns = [
        r'v_?[hH].*v_?[nN]',
        r'm_?[hH].*m_?[nN]',
        r'2.*m.*v.*/.*\(m.*\+.*m\)'
    ]

    # 检查是否缺失关键的比例关系或方程组建立
    if not (re.search(r'v_?[hH]', pred) and re.search(r'v_?[nN]', pred)):
         return {'result': 'fail', 'message': '未在推理中明确列出两种靶核的速度关系', 'evidence': prediction[:200]}

    # Step 4: 验证公式正确性 (symbolic_hint: v1/v2 = (m_n + m2) / (m_n + m1))
    # 检查是否出现了类似 (m+m2)/(m+m1) 的结构
    canonical_pattern = r'\(m.*\+.*m_?[2nN]\).*\/.*\(m.*\+.*m_?[1hH]\)'
    if re.search(canonical_pattern, pred.replace(' ', '')):
        return {'result': 'pass', 'message': '正确建立了消去初速度的质量比例方程', 'evidence': '检测到符合 v1/v2 = (m+m2)/(m+m1) 逻辑的推导'}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了速度增量模型', 'evidence': ''}

# rule_id=norm_4b67b1ce4fd6ae72 | domain=Mechanics | topic=Linear Momentum and Collisions
def check_norm_4b67b1ce4fd6ae72_22b0316146d4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及n个物体、几何级数质量分布或连续弹性碰撞
    trigger_keywords = ['n个', '连续碰撞', '弹性碰撞', 'elastic collision', 'geometric progression', '质量比', 'm_i']
    combined_text = (question + context).lower()
    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到多级连续弹性碰撞场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查错误模式 — 是否忽略了递推关系，直接给出结果或使用了错误的简单叠加
    # 错误模式：直接相加速度，或者未考虑质量比 f 对传递系数的影响
    if 'v_n' in pred and not any(sym in pred for sym in ['v_{n-1}', 'v_{i-1}', 'v_{i+1}', '递推', 'recurrence']):
        return {'result': 'fail', 'message': '未建立速度递推关系，可能直接跳过了建模过程', 'evidence': prediction[:200]}

    # Step 3: 检查公式结构 — 验证是否包含 v_{i+1} = A*v_i + B*v_0 形式的逻辑
    # 匹配类似 2m/(m+M) 的传递系数结构
    recursive_pattern = r'2m.*[\/\(].*m.*[\+\-].*m'
    if not re.search(recursive_pattern, pred) and 'f' not in pred:
        return {'result': 'fail', 'message': '未发现符合弹性碰撞传递系数特征的递推公式或质量比参数f', 'evidence': prediction[:200]}

    # Step 4: 检查质量比 f 对系数的影响是否被讨论
    if 'f' in pred and not any(op in pred for op in ['limit', '极限', '趋于', 'ratio']):
        return {'result': 'fail', 'message': '虽提及质量比f，但未分析其对传递效率或最终速度的影响', 'evidence': prediction[:200]}

    # Step 5: 仅在明确建立递推且公式结构合理时 pass
    if re.search(r'v_{?n}?.*=.*v_{?n-1}?', pred) and ('2m' in pred or 'm_i' in pred):
        return {'result': 'pass', 'message': '已正确建立多级碰撞递推模型并考虑了质量分布影响', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否完整建立了递推建模', 'evidence': ''}

# rule_id=norm_9f6b04ad0443bc5a | domain=Mechanics | topic=Linear Momentum and Collisions
def check_norm_9f6b04ad0443bc5a_3c9ae7630bfa(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 涉及连续两次碰撞且中间质量可变求极值
    trigger_keywords = ['碰撞', 'collision', '极值', '最大', 'maximum', 'extreme']
    if not (any(k in (question + context) for k in trigger_keywords) and ('m2' in (question + context) or '中间' in (question + context))):
        return {'result': 'inconclusive', 'message': '未检测到多级碰撞极值场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查逻辑错误 — 严禁视中间项为常数或直接跳过复合函数构建
    # 错误模式：在求导或求极值前，没有将第一级末速度代入第二级初速度，或者直接假设 m2 是常数进行处理
    if 'constant' in pred and ('m2' in pred or 'm_mid' in pred):
        return {'result': 'fail', 'message': '错误地将中间质量视为常数处理', 'evidence': prediction}

    # Step 3: 检查缺失 — 必须写出末端速度关于中间质量的完整复合函数
    # 检查是否包含类似 (4*m1*m2)/((m1+m2)*(m2+m3)) 的结构特征
    # 匹配分母中包含两个质量相加乘积的特征，这是链式代入的典型结果
    chain_pattern = r'\(m1\s*\+\s*m2\).*\(m2\s*\+\s*m3\)'
    if not re.search(chain_pattern, pred.replace(' ', '')):
        # 如果没有显式的复合函数结构，检查是否直接给出了极值结论而跳过了代入步骤
        if 'm2' in pred and ('sqrt' in pred or '根号' in pred) and 'm1*m3' in pred.replace(' ', ''):
            # 虽然有结论，但如果缺乏代入过程的描述，也视为逻辑缺失
            if '代入' not in pred and 'substitute' not in pred and 'velocity' not in pred:
                return {'result': 'fail', 'message': '未展示第一级末速度作为第二级初速度的链式代入过程', 'evidence': prediction}
        else:
            return {'result': 'fail', 'message': '未构建末端速度关于中间质量的完整复合函数', 'evidence': prediction}

    # Step 4: 验证符号完整性 (m1, m2, m3, v)
    required = ['m1', 'm2', 'm3']
    missing = [s for s in required if s not in pred]
    if missing:
        return {'result': 'fail', 'message': f'推理过程中缺失必要质量符号: {missing}', 'evidence': prediction}

    # Step 5: 排除错误后判定 pass
    # 必须同时具备代入逻辑和正确的极值条件 (m2 = sqrt(m1*m3))
    if ('m2' in pred and 'm1' in pred and 'm3' in pred) and (re.search(r'm2.*=.*(sqrt|√)\(?m1.*m3\)?', pred.replace(' ', ''))):
        return {'result': 'pass', 'message': '正确执行了多级碰撞链式代入并推导出极值条件', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '逻辑链条不完整，无法确认是否完全遵循代入律', 'evidence': ''}

# rule_id=norm_3f6ee8a611916960 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_3f6ee8a611916960_55785569a114(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 涉及多米诺骨牌或矩形块倾倒，且给定厚度t和高度h
    trigger_keywords = ['domino', '多米诺', '矩形块', 'rectangular block', 'tipping', 'topple', '倾倒']
    combined_text = (question + context).lower()
    is_triggered = any(kw in combined_text for kw in trigger_keywords) and ('h' in combined_text or 'height' in combined_text) and ('t' in combined_text or 'thickness' in combined_text or 'width' in combined_text)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到多米诺或矩形块倾倒场景及相关几何参数', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查错误模式 — 仅计算能量转换而忽略重心投影与支点的几何关系
    # 如果只讨论 mgh 或 1/2mv^2 而完全没有提到重心(center of mass/gravity)或几何角度/投影，则判定为建模错误
    energy_terms = ['energy', 'kinetic', 'potential', 'mgh', '1/2']
    geometry_terms = ['center of mass', 'center of gravity', '重心', 'projection', '投影', 'pivot', '支点', 'arctan', 'tan', 'theta']

    has_energy = any(et in pred for et in energy_terms)
    has_geometry = any(gt in pred for gt in geometry_terms)

    if has_energy and not has_geometry:
        return {'result': 'fail', 'message': '模型错误：仅考虑能量转换，未考虑重心投影越过支点的几何临界条件', 'evidence': 'Prediction mentions energy but lacks geometric stability analysis.'}

    # Step 3: 符号/公式校验 — 检查是否包含临界角公式 tan(theta) = t/h 或类似逻辑
    # 允许变体如 t/(2h) 取决于重心位置定义，但必须体现 t 与 h 的比例关系
    critical_pattern = r'(tan|arctan|atan).*([th].*[th])'
    if not re.search(critical_pattern, pred):
        return {'result': 'fail', 'message': '建模缺失：未建立临界角与厚度t、高度h之间的几何关系 (如 tan(theta) = t/h)', 'evidence': prediction[:200]}

    # Step 4: 验证正确性以判定 pass (refute)
    # 必须同时具备重心分析和正确的比例关系
    if has_geometry and re.search(r'tan.*t/h', pred.replace(' ', '')):
        return {'result': 'pass', 'message': '已正确识别刚体倾倒的几何临界条件', 'evidence': 'Found geometric analysis with tan(theta) = t/h'}

    return {'result': 'inconclusive', 'message': '证据不足以判定是否完全符合或违反临界几何规则', 'evidence': ''}

# rule_id=norm_969564f628db25f6 | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_norm_969564f628db25f6_9b48bb26631e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及水平无摩擦面且受力仅在铅垂方向
    # 关键词：水平、无摩擦/光滑、铅垂/重力/压力、动量守恒
    trigger_keywords = ['水平', 'horizontal', '无摩擦', 'frictionless', '光滑', 'smooth']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到水平无摩擦运动场景', 'evidence': ''}

    # 进一步确认是否涉及动量或质心位移
    if not any(kw in (question + context + prediction).lower() for kw in ['动量', 'momentum', '质心', 'center of mass', 'x_cm']):
        return {'result': 'inconclusive', 'message': '未检测到动量或质心相关讨论', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查错误模式 — 明确违反水平动量守恒或质心运动规律
    # 错误模式1：在无水平外力时认为水平动量不守恒，或错误计算了水平加速度
    if re.search(r'a_x\s*!=\s*0|水平方向加速度不为零|momentum is not conserved in horizontal', pred):
        return {'result': 'fail', 'message': '错误地认为水平方向动量不守恒或存在水平加速度', 'evidence': prediction}

    # Step 3: 检查缺失逻辑 — 是否未应用 P_x = const 或 M*x_cm_dot_dot = 0
    # 检查是否提到了动量守恒的公式或质心恒定的逻辑
    has_momentum_cons = re.search(r'p_x\s*=\s*const|m1v1\s*\+\s*m2v2|动量守恒|momentum conservation', pred)
    has_cm_logic = re.search(r'x_cm|质心|m\s*\*\s*x_cm|\ddot{x}_{cm}', pred)

    if not (has_momentum_cons or has_cm_logic):
        return {'result': 'fail', 'message': '未应用水平动量守恒定律或质心运动定理', 'evidence': prediction}

    # Step 4: 符号校验 (symbolic_hint)
    # 检查是否正确使用了 M 和 x_cm 描述质心加速度为0
    if 'x_cm' in pred or 'x_{cm}' in pred:
        if not re.search(r'\ddot{x}_{cm}\s*=\s*0|a_{cm,x}\s*=\s*0|质心加速度为0', pred):
            return {'result': 'fail', 'message': '虽提及质心但未明确其水平加速度为零', 'evidence': prediction}

    # Step 5: 验证通过 (Refute)
    # 如果明确写出了动量守恒公式且没有上述错误
    if has_momentum_cons and (re.search(r'p_x|m.*v', pred)):
        return {'result': 'pass', 'message': '正确应用了水平方向动量守恒', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了动量守恒', 'evidence': ''}

