    context = sample.get('context', '')

    # Step 1: 触发条件 — 题目涉及大量离散粒子（如小球、离子、液滴）在极板间往返输运电荷
    trigger_keywords = ['粒子', '小球', '离子', '液滴', '往返', '输运', '极板', '电荷', 'n_0', 'n0']
