    if not any(kw in combined_text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到离散载流子往返输运场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查建模错误 — 是否错误地直接使用了连续电流公式 I=ne 或忽略了单程时间/面积因素
    # 错误模式：直接将 n0 视为单位体积密度而非单位面积密度，或者忽略了单程时间 t 的推导过程
    if 'i =' in pred or 'i=' in pred:
        # 如果出现了电流计算，但完全没有涉及时间 t 或 根号下的运动学推导 (2md^2/qV)
        if 'sqrt' not in pred and '/t' not in pred and '2md' not in pred:
            return {'result': 'fail', 'message': '电流建模缺失运动学时间项，未考虑粒子单程输运时间', 'evidence': prediction[:200]}

    # Step 3: 检查公式结构 — 验证是否符合 I = (n0 * A * q) / t 的逻辑
    # 重点检查是否包含 n0, A, q 以及分母上的时间项（通常涉及 sqrt(2md^2/qV)）
    required_patterns = [
        r'n_?0.*A.*q',
        r'q.*V.*m',
        r'd\^2'
    ]

    missing_elements = []
    if 'n_0' not in pred and 'n0' not in pred:
        missing_elements.append('单位面积粒子数 n0')
    if 'a' not in pred and 'area' not in pred:
        missing_elements.append('面积 A')

    if missing_elements:
        return {'result': 'fail', 'message': f'电流建模缺少关键物理量: {", ".join(missing_elements)}', 'evidence': prediction[:200]}

    # Step 4: 验证公式完整性 (Refute LLM 诊断)
    # 匹配 I = (n0 * A * q) / sqrt(...) 结构的变体
    formula_match = re.search(r'i\s*=\s*.*n_?0.*a.*q.*/.*sqrt', pred)
    if formula_match:
        return {'result': 'pass', 'message': '电流建模符合离散载流子输运逻辑，包含面积、电荷及运动学时间项', 'evidence': formula_match.group()}

    return {'result': 'inconclusive', 'message': '无法确定电流建模是否完全准确', 'evidence': ''}

