    conservation_pattern = r'v_0\s*b\s*/\s*r|b\^2\s*/\s*r(_min)?\^2|l\^2\s*/\s*\(2mr\^2\)'
    energy_pattern = r'1/2\s*m\s*v(_0)?\^2'

    has_conservation = re.search(conservation_pattern, pred, re.IGNORECASE)
    has_energy = re.search(energy_pattern, pred, re.IGNORECASE)

    if not (has_conservation and has_energy):
        return {'result': 'fail', 'message': '未明确联立能量守恒与角动量守恒，或缺少必要的物理量(b, r_min)', 'evidence': prediction[:200]}

