# rule_id=norm_8e4a30866fd31b16 | domain=Thermodynamics & Statistical Physics | topic=First Law of Thermodynamics
def check_norm_8e4a30866fd31b16_c3ae3a0db891(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及绝热容器、理想气体、内能变化及末态压强求解
    trigger_keywords = ['绝热', 'adiabatic', '内能', 'internal energy', 'ΔU', 'delta U']
    if not any(k in (question + context).lower() for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到绝热内能变化场景', 'evidence': ''}
    if '压强' not in (question + context) and 'pressure' not in (question + context).lower():
        return {'result': 'inconclusive', 'message': '未检测到压强求解需求', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查错误模式 — 是否错误地使用了绝热过程路径方程 pV^gamma = C (适用于准静态过程，而非所有平衡态关联)
    # 如果题目给出的是内能变化量 Delta U，通常意味着是非准静态过程或直接利用状态函数定义更优
    if re.search(r'p.*v\^\\?gamma', pred) or re.search(r'p.*v\^\{?\\?gamma\}?', pred):
        if 'delta u' in pred or '\\delta u' in pred or 'u_f' in pred:
            return {
                'result': 'fail',
                'message': '在已知内能变化的情况下，错误地使用了绝热过程路径方程 pV^γ=C，应优先使用内能与压强体积的状态函数关系。',
                'evidence': re.findall(r'p.*v\^[^\s]+', pred)[0] if re.search(r'p.*v\^[^\s]+', pred) else 'detected pV^gamma'
            }

    # Step 3: 检查缺失逻辑 — 是否缺少 U = f(p, V) 的核心关联式
    # 典型形式如 U = pV / (gamma - 1) 或 p = (gamma-1)U/V
    has_state_relation = re.search(r'u\s*=\s*p\s*v', pred) or \
                         re.search(r'p\s*v\s*/\s*\(\s*\\?gamma\s*-\s*1\s*\)', pred) or \
                         re.search(r'p_f\s*=\s*\(\s*\\?gamma\s*-\s*1\s*\)', pred)

    if not has_state_relation:
        return {
            'result': 'fail',
            'message': '未发现内能与压强体积的状态函数关联式 (如 U = pV/(γ-1))，建模路径不完整。',
            'evidence': prediction[:200]
        }

    # Step 4: 验证 canonical 形式的正确性 (p_f = (gamma-1)(U_i + Delta U)/V_f)
    # 检查是否正确结合了初态内能和内能增量
    if re.search(r'u_i\s*\+\s*\\?delta\s*u', pred) and has_state_relation:
        return {
            'result': 'pass',
            'message': '正确使用了内能状态函数关系式并结合内能变化量求解末态压强。',
            'evidence': prediction[:200]
        }

    return {'result': 'inconclusive', 'message': '无法确定是否遵循了最优建模路径', 'evidence': ''}

# rule_id=norm_e6b7f0ff9c50adbd | domain=Thermodynamics & Statistical Physics | topic=First Law of Thermodynamics
def check_norm_e6b7f0ff9c50adbd_e12ed6d7d5af(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及绝热上升、成云/凝结临界压力点
    trigger_keywords = ['成云', '凝结', 'cloud', 'condensation', 'critical pressure', '临界压力']
    if not any(k in (question + context) for k in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到相变分段建模场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查错误模式 — 是否直接用单一过程（如全干绝热或全湿绝热）处理全过程
    # 如果预测中没有体现出分段（即没有区分临界点前后的逻辑），则判定为建模错误
    if '分段' not in pred and 'stage' not in pred and 'step' not in pred:
        # 检查是否只用了一个绝热指数或单一公式到底
        if re.search(r'p_\{?start\}?.*p_\{?final\}?', pred) and not re.search(r'p_\{?cloud\}?|p_\{?c\}?', pred):
            return {'result': 'fail', 'message': '未按临界压力点分段处理，直接计算了始末状态', 'evidence': prediction[:200]}

    # Step 3: 检查缺失逻辑 — 临界点后的湿绝热过程是否考虑了潜热(Lv)或水分变化
    # 必须包含潜热释放相关的符号或描述
    required_elements = ['l_v', '潜热', 'latent heat', 'dq', 'moist']
    if not any(e in pred for e in required_elements):
        return {'result': 'fail', 'message': '临界点后的建模缺失潜热释放(Lv)或湿绝热修正', 'evidence': prediction[:200]}

    # Step 4: 检查公式结构 — 验证是否包含干绝热等熵公式及后续修正项
    # 预期包含类似 T*(P2/P1)^(R/Cp) 的结构以及后续的温度变化
    dry_adiabatic_pattern = r'p.*\^.*r/c|t.*p.*r/c'
    if not re.search(dry_adiabatic_pattern, pred):
        return {'result': 'fail', 'message': '未见干绝热过程（等熵）的标准公式表达', 'evidence': prediction[:200]}

    # Step 5: 只有当明确区分了两个阶段且公式逻辑正确时才 pass
    if ('p_c' in pred or 'p_cloud' in pred) and any(e in pred for e in ['l_v', 'dq']):
        return {'result': 'pass', 'message': '已正确执行分段建模：区分了干绝热阶段与考虑潜热的湿绝热阶段', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定是否完整执行了分段建模逻辑', 'evidence': ''}

