def check_norm_a8f89175f65efb53_e1f1663bb9c5(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 题目要求射线经过多次反射、震荡或周期性路径到达特定水平距离 X
    trigger_keywords = ['反射', '震荡', '周期', '水平距离', '多次', 'reflection', 'oscillation', 'periodic', 'horizontal distance']
    if not any(kw in (question + context) for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到周期性路径或多次反射场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查逻辑错误 — 验证是否忽略了周期性跨度 n 的计算或奇偶性对终点深度的影响
    # 错误模式1：直接给出总距离 X 而没有体现单次跨度 delta_x 或周期性倍数 n
    if 'n' not in pred and '周期' not in pred and 'times' not in pred:
        return {'result': 'fail', 'message': '未体现周期性路径的倍数关系 n', 'evidence': prediction[:200]}

    # 错误模式2：忽略了 n 的奇偶性（parity）对最终位置（如深度、方向）的影响
    if 'odd' not in pred and 'even' not in pred and '奇' not in pred and '偶' not in pred:
        # 如果题目涉及深度或最终状态，必须考虑奇偶性
        if '深度' in (question + context) or 'depth' in (question + context).lower():
            return {'result': 'fail', 'message': '未讨论周期数 n 的奇偶性对终点深度的影响', 'evidence': prediction[:200]}

    # Step 3: 符号/公式校验 — 检查是否满足 X = n * delta_x 的逻辑结构
    # 匹配类似 X = n * (...) * tan(theta) 的结构
    pattern_x = r'x\s*=\s*n\s*\*.*tan\(theta'
    # 匹配 symbolic_hint 中的核心结构
    if not re.search(pattern_x, pred) and 'tan' not in pred:
         return {'result': 'fail', 'message': '未发现正确的水平跨度计算公式 X = n * delta_x(theta)', 'evidence': prediction[:200]}

    # Step 4: 仅在明确排除上述错误且逻辑完整时 pass
    if ('n' in pred or '周期' in pred) and ('tan' in pred) and (re.search(r'[Xx]\s*=', pred)):
        return {'result': 'pass', 'message': '已正确建立周期性路径水平跨度与总距离的关系', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定周期性路径校验是否完整', 'evidence': ''}

# rule_id=norm_f3e25781274322bd | domain=Optics | topic=Interference (Young's Double Slit, Thin Films)
def check_norm_f3e25781274322bd_b259cb72e38e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 涉及 F-P 腔/干涉仪分辨率 λ/Δλ 且已知相位分辨率条件 Δδ=ε
    trigger_keywords = ['分辨本领', '分辨率', 'resolving power', 'F-P', '法布里', '干涉仪']
    phase_keywords = ['相位', 'Δδ', 'delta', 'epsilon', 'ε']
    combined_text = (question + context).lower()
    if not (any(k in combined_text for k in trigger_keywords) and any(k in combined_text for k in phase_keywords)):
        return {'result': 'inconclusive', 'message': '未检测到色分辨本领与相位分辨率转换的适用场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查逻辑错误 — 检查是否错误地建立了 Δδ 与 Δλ 的关系，或公式推导逻辑断裂
    # 错误模式 1: 直接将 λ/Δλ 等于 ε (应该是反比关系或包含 δ)
    if re.search(r'λ/Δλ\s*=\s*ε', pred) or re.search(r'lambda/delta\s*lambda\s*=\s*epsilon', pred):
        return {'result': 'fail', 'message': '错误地将色分辨本领直接等同于相位分辨率 ε', 'evidence': prediction}

    # Step 3: 检查缺失 — 必须包含从相位公式 δ=4πntcosθ/λ 到微分形式 |Δδ| = (δ/λ)Δλ 的推导或等效表达
    # 核心逻辑是 Δδ = |dδ/dλ| * Δλ = (4πnt cosθ / λ^2) * Δλ = (δ/λ) * Δλ
    required_logic = ['δ/λ', 'delta/lambda', '4πnt', '4pi', 'cos']
    logic_found = any(logic in pred for logic in required_logic)

    # 检查是否缺失了关键的转换公式 λ/Δλ = δ/ε
    formula_pattern = r'λ/Δλ|lambda/delta\s*lambda'
    if not re.search(formula_pattern, pred):
        return {'result': 'fail', 'message': '预测中缺失色分辨本领 λ/Δλ 的定义或计算步骤', 'evidence': prediction}

    if 'δ/ε' not in pred and 'delta/epsilon' not in pred and 'δ' not in pred:
         return {'result': 'fail', 'message': '未利用相位分辨率 ε 推导色分辨本领，缺少 Δδ=ε 的代换逻辑', 'evidence': prediction}

    # Step 4: 验证正确性 (Refute) — 只有当公式 λ/Δλ = δ/ε 或其展开形式正确出现时
    # 展开形式: λ/Δλ = (4πnt cosθ) / (λ * ε)
    canonical_pattern = r'(λ/Δλ|lambda/delta\s*lambda)\s*=\s*(δ/ε|delta/epsilon|\(4πnt.*?\)\s*/\s*\(λ.*?ε\))'
    if re.search(canonical_pattern, pred):
        return {'result': 'pass', 'message': '正确执行了从相位分辨率到色分辨本领的转换推导', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '推导过程不完整或证据不足以判定正误', 'evidence': ''}

# rule_id=norm_712539d0ac9878e0 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_norm_712539d0ac9878e0_0afba7db469f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及相干长度（coherence length）且已知中心波长与带宽
    trigger_keywords = ['coherence length', '相干长度', 'spectral width', 'bandwidth', '光谱宽度', '带宽']
    if not any(kw in (question + context).lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到相干长度与光谱宽度的计算场景', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查逻辑错误 — 验证公式是否满足 Lc ≈ λ²/Δλ
    # 错误模式1：公式结构错误，如 Lc = λ * Δλ 或 Lc = Δλ / λ^2
    wrong_patterns = [
        r'l_c\s*=\s*λ_0\s*\*\s*Δλ',
        r'l_c\s*=\s*Δλ\s*/\s*λ_0',
        r'l_c\s*=\s*Δλ\s*/\s*λ_0\^2'
    ]
    for pattern in wrong_patterns:
        if re.search(pattern, pred, re.IGNORECASE):
            return {'result': 'fail', 'message': '相干长度公式结构错误，未遵循 Lc ≈ λ²/Δλ', 'evidence': re.search(pattern, pred, re.IGNORECASE).group()}

    # Step 3: 检查缺失 — 必须包含核心物理量 λ_0^2 / Δλ 的计算逻辑
    # 匹配 λ^2/Δλ 或 λ*λ/Δλ 的形式
    correct_logic_pattern = r'(λ|lambda|l_0|λ_0)\^2\s*/\s*(Δλ|delta\s*lambda|d_lambda)'
    correct_logic_pattern_alt = r'((λ|lambda|l_0|λ_0)\s*\*\s*(λ|lambda|l_0|λ_0))\s*/\s*(Δλ|delta\s*lambda|d_lambda)'

    has_correct_formula = re.search(correct_logic_pattern, pred, re.IGNORECASE) or re.search(correct_logic_pattern_alt, pred, re.IGNORECASE)

    if not has_correct_formula:
        return {'result': 'fail', 'message': '预测中缺失相干长度的核心计算公式 Lc ≈ λ²/Δλ', 'evidence': prediction[:200]}

    # Step 4: 检查物理一致性 — 若 Δλ 极小，Lc 应显著大于波长
    # 如果提到带宽极窄或单色性好，但计算出的 Lc 却很小，则判定为逻辑错误
    if ('narrow' in (question + context).lower() or '极小' in (question + context)) and 'lc' in pred:
        # 简单启发式：如果带宽小但公式中没有体现平方关系，通常会导致量级错误
        if 'λ' in pred and 'Δλ' in pred and not has_correct_formula:
            return {'result': 'fail', 'message': '在窄带宽条件下未正确应用平方反比关系计算相干长度', 'evidence': prediction[:150]}

    # Step 5: 只有在明确包含正确公式且未发现上述错误时，才返回 pass
    if has_correct_formula:
        return {'result': 'pass', 'message': '正确应用了相干长度与光谱宽度的倒数平方关系', 'evidence': 'Detected formula: ' + (re.search(correct_logic_pattern, pred, re.IGNORECASE).group() if re.search(correct_logic_pattern, pred, re.IGNORECASE) else 'λ*λ/Δλ')}

    return {'result': 'inconclusive', 'message': '证据不足，无法确定公式应用是否完全正确', 'evidence': ''}

