# rule_id=norm_94c9efe55d8fbe00 | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_norm_94c9efe55d8fbe00_d16aa3a406d5(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 题目给出周长 L 但涉及 Sagnac 效应、面积 A 或半径 R
    q_text = (question + context).lower()
    if not (re.search(r'[Ll]\s*=', q_text) or '周长' in q_text or 'perimeter' in q_text):
        return {'result': 'inconclusive', 'message': '未检测到周长 L 的输入条件', 'evidence': ''}
    if not ('sagnac' in q_text or '面积' in q_text or 'area' in q_text or 'delta' in q_text):
        return {'result': 'inconclusive', 'message': '未检测到 Sagnac 效应或面积转换需求', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查逻辑 — 优先使用面积 A 表达 Sagnac 效应，检查 A 与 L 的转换比例
    # 针对正三角形 (L=3a, A=sqrt(3)/4 * a^2 = sqrt(3)/36 * L^2) 或正多边形转换错误
    # 错误模式 1: 直接混淆 L 和 A，或者在公式中缺失面积项
    if 'sagnac' in pred and 'a' not in pred and 'area' not in pred:
        return {'result': 'fail', 'message': 'Sagnac 效应计算中未体现面积 A，可能错误使用了周长 L', 'evidence': prediction[:200]}

    # 错误模式 2: 比例系数错误。例如正三角形 A = L^2 / (12 * sqrt(3)) 约等于 0.048 L^2
    # 如果 prediction 中出现了错误的比例系数（如 A = L^2 / 16 等）
    if re.search(r'a\s*=\s*l\^2\s*/\s*16', pred) or re.search(r'a\s*=\s*l\^2\s*/\s*4', pred):
        return {'result': 'fail', 'message': '面积 A 与周长 L 的几何比例系数计算错误', 'evidence': prediction[:200]}

    # Step 3: 检查 symbolic_hint 要求的关键公式 A = L^2 / (12 * sqrt(3))
    # 检查是否缺失了必要的几何转换逻辑
    has_correct_ratio = re.search(r'l\^2\s*/\s*\(\s*12\s*\*?\s*sqrt\(3\)\s*\)', pred) or \
                        re.search(r'l\^2\s*/\s*20\.78', pred) or \
                        re.search(r'0\.048\s*l\^2', pred)

    if 'triangle' in q_text or '三角形' in q_text:
        if not has_correct_ratio and ('a =' in pred or 'area =' in pred):
             return {'result': 'fail', 'message': '未找到正确的正三角形面积与周长转换公式 A = L^2 / (12*sqrt(3))', 'evidence': prediction[:200]}

    # Step 4: 验证 pass 条件 — 必须同时具备面积表达和正确的转换比例
    if 'sagnac' in pred and has_correct_ratio:
        return {'result': 'pass', 'message': '正确使用了面积 A 表达 Sagnac 效应并完成了几何参数转换', 'evidence': prediction[:200]}

    return {'result': 'inconclusive', 'message': '无法确定几何转换的准确性', 'evidence': ''}

# rule_id=norm_cc20162a477cb748 | domain=Modern Physics | topic=Relativistic Energy and Momentum
def check_norm_cc20162a477cb748_bed84925c8f4(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # Step 1: 触发条件 — 检查是否涉及相对论动力学中的双曲函数或指数函数
    # 触发词：sinh, cosh, tanh, exp, e^, 加速度 g, 时间 tau/t
    trigger_patterns = [r'sinh', r'cosh', r'tanh', r'exp', r'e\^']
    combined_text = (question + context).lower()
    if not any(re.search(p, combined_text) for p in trigger_patterns):
        if not any(re.search(p, prediction.lower()) for p in trigger_patterns):
            return {'result': 'inconclusive', 'message': '未检测到双曲函数或指数函数，规则不适用', 'evidence': ''}

    pred = prediction.lower()
    # Step 2: 检查逻辑 — 查找量纲不匹配的错误模式 (g*tau 或 g*t 缺少除以 c)
    # 错误模式：sinh(g*tau), cosh(gt), exp(g*t/k) 其中没有 c 参与抵消速度量纲
    # 匹配 g 乘以时间变量但未除以 c 的情况
    error_patterns = [
        r'(sinh|cosh|tanh|exp)\s*\(\s*g\s*[*\s]*[τt]\s*\)',  # 直接 g*t
        r'e\^\{\s*g\s*[*\s]*[τt]\s*\}',                      # 指数形式 g*t
        r'g\s*[*\s]*[τt](?!\s*/\s*c)'                         # 任意位置出现 g*t 且后面没跟 /c
    ]

    for pattern in error_patterns:
        match = re.search(pattern, pred)
        if match:
            return {
                'result': 'fail',
                'message': '超越函数参数量纲不一致：检测到 g*τ 或 g*t 组合，但未除以光速 c 以达到无量纲化。',
                'evidence': match.group(0)
            }

    # Step 3: 检查缺失 — 验证是否正确使用了 g*tau/c 或 g*t/c
    correct_pattern = r'g\s*[*\s]*[τt]\s*/\s*c'
    if not re.search(correct_pattern, pred):
        # 如果既没有明显的错误模式，也没有正确的量纲组合，则无法确定
        return {'result': 'inconclusive', 'message': '未发现明确的量纲错误，但也未检测到正确的 g*τ/c 组合', 'evidence': ''}

    # Step 4: 排除 fail 后，若存在正确组合且逻辑自洽，则 pass
    if re.search(r'(sinh|cosh|tanh|exp)\s*\(\s*g\s*[*\s]*[τt]\s*/\s*c\s*\)', pred):
        return {
            'result': 'pass',
            'message': '超越函数参数量纲正确，已包含 g*τ/c 形式。',
            'evidence': '检测到符合量纲要求的表达式'
        }

    return {'result': 'inconclusive', 'message': '证据不足，无法判定量纲完整性', 'evidence': ''}

