    pred = prediction.lower()
    # Step 2: 检查逻辑错误 — 检查是否错误地使用了 hbar/2 导致系数与特征长度不匹配
    # 在量级估算中，若使用 Delta p * Delta x ~ hbar/2 往往会导致结果与标准特征长度 (如 sqrt(hbar/mw)) 差一个 sqrt(2) 系数
    # 错误模式：明确写出 hbar/2 且后续推导出的特征尺寸系数不符合 sqrt(hbar/m...)
    if re.search(r'\\hbar\s*/\s*2', pred) or '0.5\\hbar' in pred or '0.5 * \\hbar' in pred:
        # 如果使用了 hbar/2 且没有进行修正，通常在量级估算中被视为不一致（针对此规则定义的场景）
        if 'order of magnitude' in pred or 'estimate' in pred or '估算' in pred:
            return {'result': 'fail', 'message': '在量级估算中使用了严格的 hbar/2 而非更一致的 hbar，可能导致特征尺寸系数不匹配', 'evidence': '检测到 hbar/2 的使用'}

    # Step 3: 检查缺失或不一致 — 检查是否缺少必要的物理量符号 (m, hbar, omega)
    required_symbols = ['\\hbar', 'm']
    missing_symbols = [s for s in required_symbols if s not in prediction]
    if missing_symbols:
        return {'result': 'fail', 'message': f'缺少必要的物理量符号: {missing_symbols}', 'evidence': prediction[:100]}

    # Step 4: 检查公式一致性 (symbolic_hint)
    # 检查是否出现了符合特征长度形式的公式 z_0 = sqrt(hbar / (m * omega))
    # 如果 prediction 中使用了 hbar/2 且推导出的结果不是 sqrt(hbar/m...) 形式，则 fail
    ho_pattern = r'\\sqrt{\s*\\hbar\s*/\s*\(\s*m\s*\\?[Oo]mega\s*\)\s*}'
    has_correct_form = re.search(ho_pattern, prediction) is not null

    if not has_correct_form and ('omega' in pred or '\\omega' in pred or '\\Omega' in pred):
        return {'result': 'fail', 'message': '未能推导出与谐振子特征长度一致的系数形式', 'evidence': prediction[:200]}

    # Step 5: 只有在明确使用了 hbar 且形式正确时才 pass
    if has_correct_form and re.search(r'\\Delta\s*p\s*\\cdot\s*\\Delta\s*x\s*\\sim\s*\\hbar', prediction):
        return {'result': 'pass', 'message': '估算系数与特征长度一致，正确使用了 Delta p * Delta x ~ hbar', 'evidence': '符合 z_0 = sqrt(hbar/mO) 且使用 hbar 估算'}

    return {'result': 'inconclusive', 'message': '证据不足以判定系数一致性', 'evidence': ''}

